            private sealed class AutoJoinCategoryItem : INotifyPropertyChanged
            {
                private bool _isEnabled;

                public Autodesk.Revit.DB.BuiltInCategory Category { get; }
                public string DisplayName { get; }
                public bool DefaultEnabled { get; }

                public bool IsEnabled
                {
                    get => _isEnabled;
                    set
                    {
                        if (_isEnabled == value)
                        {
                            return;
                        }

                        _isEnabled = value;
                        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(IsEnabled)));
                    }
                }

                public AutoJoinCategoryItem(
                    Autodesk.Revit.DB.BuiltInCategory category,
                    string displayName,
                    bool defaultEnabled)
                {
                    Category = category;
                    DisplayName = displayName ?? "";
                    DefaultEnabled = defaultEnabled;
                    _isEnabled = defaultEnabled;
                }

                public event PropertyChangedEventHandler PropertyChanged;
            }

