            {
                get => _isChecked;
                set
                {
                    if (_isChecked == value) return;
                    _isChecked = value;
                    OnPropertyChanged(nameof(IsChecked));
                }
            }

            public event PropertyChangedEventHandler PropertyChanged;

            private void OnPropertyChanged(string propertyName)
            {
                PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
            }
        }

        private sealed class LinksheetParameterSelectionItem : INotifyPropertyChanged
        {
            private bool _isChecked;

            public string Key { get; set; } = "";
            public string Name { get; set; } = "";
            public LinksheetParameterKind Kind { get; set; } = LinksheetParameterKind.ReadOnly;

            public string KindLabel
            {
                get
                {
                    switch (Kind)
                    {
                        case LinksheetParameterKind.Instance:
                            return "Instance";
                        case LinksheetParameterKind.Type:
                            return "Type";
                        default:
                            return "Read-only";
                    }
                }
            }

            public Brush RowBackground
            {
                get
                {
                    switch (Kind)
                    {
                        case LinksheetParameterKind.Instance:
                            return new SolidColorBrush(System.Windows.Media.Color.FromRgb(234, 247, 234));
                        case LinksheetParameterKind.Type:
                            return new SolidColorBrush(System.Windows.Media.Color.FromRgb(247, 241, 221));
                        default:
                            return new SolidColorBrush(System.Windows.Media.Color.FromRgb(248, 223, 223));
                    }
                }
            }

            public bool IsChecked
            {
                get => _isChecked;
                set
                {
                    if (_isChecked == value) return;
                    _isChecked = value;
                    OnPropertyChanged(nameof(IsChecked));
                }
            }

            public event PropertyChangedEventHandler PropertyChanged;

            private void OnPropertyChanged(string propertyName)
            {
                PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
            }
        }

