        public CamboBIMWindow()
        {
            InitializeComponent();
            _revitMainWindowHandle = IntPtr.Zero;
            ApplyInitialStatusText();
            ApplyIdentifyToolSvgIcons();
            Loaded += OnIdentifySvgWindowLoaded;
            ShowStatus("Visual Studio designer preview. Revit runtime actions are disabled.");
        }

        public CamboBIMWindow(IntPtr revitMainWindowHandle)
        {
            InitializeComponent();
            _revitMainWindowHandle = revitMainWindowHandle;
            ApplyInitialStatusText();
            ApplyIdentifyToolSvgIcons();
            Loaded += OnIdentifySvgWindowLoaded;

            if (DesignerProperties.GetIsInDesignMode(this))
            {
                return;
            }

            ConfigureRevitOwnedWindow();

            Activated += OnWindowActivated;

            _handler = new CadToModelExternalEventHandler();
            _handler.SetWindow(this);
            _externalEvent = ExternalEvent.Create(_handler);

            if (ColumnSectionGrid != null)
            {
                ColumnSectionGrid.ItemsSource = _columnSectionSpecs;
            }
            if (WallSectionGrid != null)
            {
                WallSectionGrid.ItemsSource = _wallSectionSpecs;
            }
            if (BeamSectionGrid != null)
            {
                BeamSectionGrid.ItemsSource = _beamSectionSpecs;
            }
            if (SlabSectionGrid != null)
            {
                SlabSectionGrid.ItemsSource = _slabSectionSpecs;
            }
            if (BoqTableGrid != null)
            {
                BoqTableGrid.ItemsSource = _boqRows;
            }
            if (BoqReportGrid != null)
            {
                BoqReportGrid.ItemsSource = _boqReportRows;
            }
            if (BoqReportCategoryTree != null)
            {
                BoqReportCategoryTree.ItemsSource = _boqReportCategoryNodes;
            }
            if (PrepareBoqGrid != null)
            {
                PrepareBoqGrid.ItemsSource = _prepareBoqRows;
                ApplyPrepareBoqColumnHeaders(_prepareBoqHeaderMap);
            }
            if (SiteProgressCombinedGrid != null)
            {
                SiteProgressCombinedGrid.ItemsSource = _siteProgressCombinedRows;
            }
            if (FindName("PmDetailProgressDataGrid") is DataGrid pmDetailProgressDataGrid)
            {
                pmDetailProgressDataGrid.ItemsSource = _siteProgressCombinedRows;
            }
            if (SiteProgressByBuildingGrid != null)
            {
                SiteProgressByBuildingGrid.ItemsSource = _siteProgressByBuildingRows;
            }
            if (SiteProgressDashboardStructureGrid != null)
            {
                SiteProgressDashboardStructureGrid.ItemsSource = _siteProgressDashboardStructureRows;
            }
            if (FindName("SiteProgressElementChartItemsControl") is ItemsControl siteProgressElementChartItemsControl)
            {
                siteProgressElementChartItemsControl.ItemsSource = _siteProgressDashboardChartItems;
            }
            if (LinksheetScheduleListBox != null)
            {
                LinksheetScheduleListBox.ItemsSource = _linksheetScheduleItems;
            }
            if (LinksheetParameterListBox != null)
            {
                LinksheetParameterListBox.ItemsSource = _linksheetParameterItems;
            }
            if (LinksheetParameterTypeCombo != null)
            {
                LinksheetParameterTypeCombo.SelectedIndex = 0;
            }
            if (LinksheetPreviewSheetCombo != null)
            {
                LinksheetPreviewSheetCombo.ItemsSource = new List<string>();
            }
            if (AutoJoinCategoriesListBox != null)
            {
                AutoJoinCategoriesListBox.ItemsSource = _autoJoinCategoryItems;
