            InitializeAutoJoinDefaults();
            InitializeFoundationRebarDesignUi();
            InitializeWallRebarDesignUi();
            InitializeBeamRebarDesignUi();
            UpdateWallRebarSelectionUiState();
            UpdateBeamRebarSelectionUiState();

            if (LayerCombo != null) LayerCombo.IsEnabled = LayerModeRadio?.IsChecked == true;
            System.Windows.Controls.ComboBox columnLabelCombo = GetColumnLabelLayerCombo();
            if (columnLabelCombo != null) columnLabelCombo.IsEnabled = true;
            if (LayerCombo_Grid != null) LayerCombo_Grid.IsEnabled = LayerModeRadio_Grid?.IsChecked == true;
            if (LabelLayerCombo_Grid != null) LabelLayerCombo_Grid.IsEnabled = true;
            if (BoredLayerCombo_Bored != null) BoredLayerCombo_Bored.IsEnabled = LayerModeRadio_Bored?.IsChecked == true;
            if (HeadOffsetTextBox_Bored != null && string.IsNullOrWhiteSpace(HeadOffsetTextBox_Bored.Text))
            {
                HeadOffsetTextBox_Bored.Text = "0";
            }
            if (SlabLayerCombo_Foundation != null) SlabLayerCombo_Foundation.IsEnabled = LayerModeRadio_Foundation?.IsChecked == true;
            if (IsolatedLayerCombo_Foundation != null) IsolatedLayerCombo_Foundation.IsEnabled = LayerModeRadio_Foundation?.IsChecked == true;
            System.Windows.Controls.TextBox leanSourceSummaryTextBox = GetLeanSourceSummaryTextBox();
            if (leanSourceSummaryTextBox != null && string.IsNullOrWhiteSpace(leanSourceSummaryTextBox.Text))
            {
                leanSourceSummaryTextBox.Text = "(not selected)";
