            System.Windows.Controls.TextBox soilSourceSummaryTextBox = GetSoilExcavationSourceSummaryTextBox();
            if (soilSourceSummaryTextBox != null && string.IsNullOrWhiteSpace(soilSourceSummaryTextBox.Text))
            {
                soilSourceSummaryTextBox.Text = "(not selected)";
            }
            if (LayerCombo_Wall != null) LayerCombo_Wall.IsEnabled = LayerModeRadio_Wall?.IsChecked == true;
            if (LayerCombo_Beam != null) LayerCombo_Beam.IsEnabled = LayerModeRadio_Beam?.IsChecked == true;
            if (FoundationOffsetTextBox_Foundation != null && string.IsNullOrWhiteSpace(FoundationOffsetTextBox_Foundation.Text))
            {
                FoundationOffsetTextBox_Foundation.Text = "0";
            }
            System.Windows.Controls.TextBox leanSideOffsetTextBox = GetLeanConcreteSideOffsetTextBox();
            if (leanSideOffsetTextBox != null && string.IsNullOrWhiteSpace(leanSideOffsetTextBox.Text))
            {
                leanSideOffsetTextBox.Text = "100";
            }
            System.Windows.Controls.TextBox soilBaseOffsetTextBox = GetSoilExcavationBaseOffsetTextBox();
            if (soilBaseOffsetTextBox != null && string.IsNullOrWhiteSpace(soilBaseOffsetTextBox.Text))
            {
                soilBaseOffsetTextBox.Text = "300";
            }
            System.Windows.Controls.TextBox soilTopOffsetTextBox = GetSoilExcavationTopOffsetTextBox();
            if (soilTopOffsetTextBox != null && string.IsNullOrWhiteSpace(soilTopOffsetTextBox.Text))
            {
                soilTopOffsetTextBox.Text = "0";
            }
            System.Windows.Controls.TextBox soilAngleTextBox = GetSoilExcavationAngleTextBox();
            if (soilAngleTextBox != null && string.IsNullOrWhiteSpace(soilAngleTextBox.Text))
            {
                soilAngleTextBox.Text = "135";
            }
            System.Windows.Controls.TextBox soilVolumeTextBox = GetSoilExcavationVolumeTextBox();
            if (soilVolumeTextBox != null && string.IsNullOrWhiteSpace(soilVolumeTextBox.Text))
            {
                soilVolumeTextBox.Text = "(not calculated)";
            }
            var drawingLayerCombo = GetDrawingLayerCombo();
            var drawingLayerModeRadio = GetDrawingLayerModeRadio();
            if (drawingLayerCombo != null) drawingLayerCombo.IsEnabled = drawingLayerModeRadio?.IsChecked == true;
            InitializeColumnRebarPreviewViewport();

            InitializeQsDefaults();
            InitializeSiteProgressDefaults();
            InitializeLinksheetDefaults();
            InitializeBoreyDefaults();
            InitializeBoreyUiEvents();
            InitializePowerBiDefaults();
            InitializePmDashboardDefaults();
            UpdateLinksheetScopeBadge();

            RequestInitialize();
        }

        private void ApplyInitialStatusText()
        {
            if (StatusText != null)
            {
                StatusText.Text = _pendingStatusText ?? "";
            }
        }

        private void ConfigureRevitOwnedWindow()
        {
            if (_revitMainWindowHandle == IntPtr.Zero)
            {
                ShowInTaskbar = true;
                return;
            }

            // Make CamboBIM behave like a Revit-owned palette window:
            // it stays above Revit and follows Revit minimize/restore.
            new WindowInteropHelper(this).Owner = _revitMainWindowHandle;
            ShowInTaskbar = false;
        }

        internal void SelectTab(string mainTabHeader, string qsSubTabHeader)
        {
            if (string.IsNullOrWhiteSpace(mainTabHeader))
            {
                return;
            }

            void select()
            {
                bool mainMatched = SelectTabItemByHeader(MainTabControl, mainTabHeader);
                if (!mainMatched)
                {
                    return;
                }

                if (string.Equals(mainTabHeader.Trim(), "QS TOOLS", StringComparison.OrdinalIgnoreCase) &&
                    !string.IsNullOrWhiteSpace(qsSubTabHeader))
                {
                    SelectTabItemByHeader(QsSubTabControl, qsSubTabHeader);
                }
            }

            if (Dispatcher.CheckAccess())
            {
                select();
            }
            else
            {
                Dispatcher.Invoke(select);
            }
        }

        internal void SetMainTabMode(string mainTabHeader, bool focusedMainTabOnly)
        {
            void applyMode()
            {
                if (MainTabControl == null)
                {
                    return;
                }

                TabItem focusedTab = null;
                if (!string.IsNullOrWhiteSpace(mainTabHeader))
                {
                    focusedTab = FindTabItemByHeader(MainTabControl, mainTabHeader);
                }

                foreach (object item in MainTabControl.Items)
                {
                    if (!(item is TabItem tab))
                    {
                        continue;
                    }

                    bool isFocused = focusedTab != null && ReferenceEquals(tab, focusedTab);
                    tab.Visibility = focusedMainTabOnly
                        ? (isFocused ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed)
                        : System.Windows.Visibility.Visible;
                }

                // If focused mode is requested but tab name did not match, keep all tabs visible.
                if (focusedMainTabOnly && focusedTab == null)
                {
                    foreach (object item in MainTabControl.Items)
                    {
                        if (item is TabItem tab)
                        {
                            tab.Visibility = System.Windows.Visibility.Visible;
                        }
                    }
                }
            }

            if (Dispatcher.CheckAccess())
            {
                applyMode();
            }
            else
            {
                Dispatcher.Invoke(applyMode);
            }
        }

        private static bool SelectTabItemByHeader(TabControl tabControl, string header)
        {
            if (tabControl == null || string.IsNullOrWhiteSpace(header))
            {
                return false;
            }

            string target = header.Trim();
            foreach (object item in tabControl.Items)
            {
                if (!(item is TabItem tab)) continue;
                if (!string.Equals((tab.Header?.ToString() ?? "").Trim(), target, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                tabControl.SelectedItem = tab;
                return true;
            }

            return false;
        }

        private static TabItem FindTabItemByHeader(TabControl tabControl, string header)
        {
            if (tabControl == null || string.IsNullOrWhiteSpace(header))
            {
                return null;
            }

            string target = header.Trim();
            foreach (object item in tabControl.Items)
            {
                if (!(item is TabItem tab))
                {
                    continue;
                }

                if (string.Equals((tab.Header?.ToString() ?? "").Trim(), target, StringComparison.OrdinalIgnoreCase))
                {
                    return tab;
                }
            }

            return null;
        }

