        private ColumnSidelineSelectionMode? ShowColumnEntitySelectionModeDialog(
            string title,
            string detail,
            string freeSelectDetail,
            string byLayerDetail,
            string byColorDetail)
        {
            ColumnSidelineSelectionMode? selectedMode = null;

            var dialog = new Window
            {
                Title = "Entity Selection Mode",
                Width = 380,
                SizeToContent = SizeToContent.Height,
                MinHeight = 260,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Owner = this,
                Background = Brushes.White
            };

            var root = new DockPanel
            {
                LastChildFill = true,
                Margin = new Thickness(18)
            };
            dialog.Content = root;

            var buttons = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Right,
                Margin = new Thickness(0, 18, 0, 0)
            };
            DockPanel.SetDock(buttons, Dock.Bottom);
            root.Children.Add(buttons);

            var content = new StackPanel();
            root.Children.Add(content);

            content.Children.Add(new TextBlock
            {
                Text = title,
                FontSize = 16,
                FontWeight = System.Windows.FontWeights.SemiBold,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(31, 41, 55)),
                Margin = new Thickness(0, 0, 0, 8)
            });

            content.Children.Add(new TextBlock
            {
                Text = detail,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(75, 85, 99)),
                Margin = new Thickness(0, 0, 0, 14)
            });

            RadioButton freeSelect = MakeColumnSidelineModeRadio("Free Select", freeSelectDetail, true);
            RadioButton byLayer = MakeColumnSidelineModeRadio("Select by layer", byLayerDetail, false);
            RadioButton byColor = MakeColumnSidelineModeRadio("Select by color", byColorDetail, false);
            content.Children.Add(freeSelect);
            content.Children.Add(byLayer);
            content.Children.Add(byColor);

            var ok = new Button
            {
                Content = "OK",
                Width = 88,
                Height = 30,
                Margin = new Thickness(0, 0, 8, 0),
                IsDefault = true
            };
            ok.Click += (_, __) =>
            {
                if (byLayer.IsChecked == true)
                {
                    selectedMode = ColumnSidelineSelectionMode.SelectByLayer;
                }
                else if (byColor.IsChecked == true)
                {
                    selectedMode = ColumnSidelineSelectionMode.SelectByColor;
                }
                else
                {
                    selectedMode = ColumnSidelineSelectionMode.FreeSelect;
                }

                dialog.DialogResult = true;
                dialog.Close();
            };
            buttons.Children.Add(ok);

            var cancel = new Button
            {
                Content = "Cancel",
                Width = 88,
                Height = 30,
                IsCancel = true
            };
            cancel.Click += (_, __) =>
            {
                selectedMode = null;
                dialog.DialogResult = false;
                dialog.Close();
            };
            buttons.Children.Add(cancel);

            bool? result = dialog.ShowDialog();
            return result == true ? selectedMode : null;
        }

        private static RadioButton MakeColumnSidelineModeRadio(string title, string detail, bool isChecked)
        {
            var radio = new RadioButton
            {
                IsChecked = isChecked,
                Margin = new Thickness(0, 0, 0, 10)
            };

            var text = new StackPanel();
            text.Children.Add(new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.SemiBold,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(31, 41, 55))
            });
            text.Children.Add(new TextBlock
            {
                Text = detail,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(94, 104, 120)),
                FontSize = 12,
                Margin = new Thickness(0, 2, 0, 0)
            });
            radio.Content = text;
            return radio;
        }

        private void ApplyColumnSidelineSelectionMode(ColumnSidelineSelectionMode mode)
        {
            if (SelectModeRadio != null)
            {
                SelectModeRadio.IsChecked = mode == ColumnSidelineSelectionMode.FreeSelect;
            }

            if (LayerModeRadio != null)
            {
                LayerModeRadio.IsChecked = mode == ColumnSidelineSelectionMode.SelectByLayer;
            }

            if (ColorModeRadio != null)
            {
                ColorModeRadio.IsChecked = mode == ColumnSidelineSelectionMode.SelectByColor;
            }

            if (LayerCombo != null)
            {
                LayerCombo.IsEnabled = mode == ColumnSidelineSelectionMode.SelectByLayer;
            }
        }

