        private void StartColumnScheduleCadScan()
        {
            StartElementScheduleCadScan("Column");
        }

        private void StartElementScheduleCadScan(string elementGroup)
        {
            ApplyTasReferenceSettingsToRequest();

            string group = elementGroup ?? "Column";
            if (group.Equals("Wall", StringComparison.OrdinalIgnoreCase))
            {
                HideForColumnScheduleCadScan();
                _handler.Request.RequestType = CadToModelRequestType.PickWallSchedule;
                _externalEvent.Raise();
                return;
            }

            if (group.Equals("Beam", StringComparison.OrdinalIgnoreCase))
            {
                HideForColumnScheduleCadScan();
                _handler.Request.RequestType = CadToModelRequestType.PickBeamSchedule;
                _externalEvent.Raise();
                return;
            }

            if (!group.Equals("Column", StringComparison.OrdinalIgnoreCase))
            {
                ShowStatus(group + " CAD schedule selection is not connected yet. Use Paste or Excel import in Identify Element Schedule.");
                return;
            }

            HideForColumnScheduleCadScan();
            _handler.Request.RequestType = CadToModelRequestType.PickColumnSchedule;
            _externalEvent.Raise();
        }

        private void HideForColumnScheduleCadScan()
        {
            if (!Dispatcher.CheckAccess())
            {
                Dispatcher.Invoke(HideForColumnScheduleCadScan);
                return;
            }

            if (_hiddenForColumnSchedulePick)
            {
                return;
            }

            _columnSchedulePickWasVisible = IsVisible;
            _columnSchedulePickPreviousWindowState = WindowState;
            if (!_columnSchedulePickWasVisible)
            {
                return;
            }

            _hiddenForColumnSchedulePick = true;
            Hide();
            Dispatcher.Invoke(System.Windows.Threading.DispatcherPriority.Background, new Action(() => { }));
        }

        internal void RestoreAfterColumnScheduleCadScan()
        {
            if (!Dispatcher.CheckAccess())
            {
                Dispatcher.Invoke(RestoreAfterColumnScheduleCadScan);
                return;
            }

            if (!_hiddenForColumnSchedulePick)
            {
                return;
            }

            _hiddenForColumnSchedulePick = false;
            if (!_columnSchedulePickWasVisible)
            {
                return;
            }

            Show();
            WindowState = _columnSchedulePickPreviousWindowState;
            Activate();
        }

        private void OpenIdentifyElementScheduleWindow(bool autoImportOnOpen, string initialElementGroup = "Column")
        {
            var dialog = new IdentifyElementScheduleWindow(_columnSectionSpecs.ToList(), autoImportOnOpen, initialElementGroup)
            {
                Owner = this
            };

            bool? result = dialog.ShowDialog();
            if (dialog.RequestedCadDataSelection)
            {
                StartElementScheduleCadScan(dialog.RequestedCadDataElementGroup);
                return;
            }

            if (result == true)
            {
                ApplyIdentifyElementScheduleResult(dialog);
            }
        }

