                scheduleRows,
                string.IsNullOrWhiteSpace(sourceLabel) ? "CAD Data" : sourceLabel,
                string.IsNullOrWhiteSpace(sourceLabel)
                    ? "Loaded selected schedule data."
                    : "Loaded selected schedule data from " + sourceLabel + ".",
                elementGroup)
            {
