            };

            bool? result = dialog.ShowDialog();
            if (dialog.RequestedCadDataSelection)
            {
                StartElementScheduleCadScan(dialog.RequestedCadDataElementGroup);
                return;
            }

            if (result == true)
            {
                ApplyIdentifyElementScheduleResult(dialog);
            }
        }

