        private void OnPasteColumnSectionsClick(object sender, RoutedEventArgs e)
        {
            string text = Clipboard.GetText();
            if (string.IsNullOrWhiteSpace(text))
            {
                ShowStatus("Clipboard is empty.");
                return;
            }

            List<ColumnSectionSpec> items = ParseColumnSectionSpecs(text);
            if (items.Count == 0)
            {
                ShowStatus("No valid rows found. Expect: Name, Width[mm], Length[mm].");
                return;
            }

            _columnSectionSpecs.Clear();
            foreach (ColumnSectionSpec spec in items)
            {
                _columnSectionSpecs.Add(spec);
            }

            ShowStatus($"Loaded {items.Count} column section row(s).");
            UpdateCad2ModelTasWorkflowRail();
        }

