        private void ImportColumnSectionsFromExcelFile()
        {
            var dialog = new OpenFileDialog
            {
                Title = "Import Column Schedule Excel/CSV",
                Filter = "Excel files (*.xlsx;*.xlsm;*.xls)|*.xlsx;*.xlsm;*.xls|CSV/Text (*.csv;*.txt)|*.csv;*.txt|All files (*.*)|*.*",
                Multiselect = false,
                CheckFileExists = true
            };

            bool? ok = dialog.ShowDialog(this);
            if (ok != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            LoadColumnSectionsFromFile(dialog.FileName);
        }

        private void LoadColumnSectionsFromFile(string path)
        {
            try
            {
                string extension = Path.GetExtension(path) ?? "";
                string sourceLabel;
                List<ColumnSectionSpec> items;
                if (string.Equals(extension, ".csv", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(extension, ".txt", StringComparison.OrdinalIgnoreCase))
                {
                    sourceLabel = Path.GetFileName(path);
                    items = ParseColumnSectionSpecs(File.ReadAllText(path, Encoding.UTF8));
                }
                else
                {
                    items = ReadColumnSectionSpecsFromExcel(path, out sourceLabel);
                }

                if (items.Count == 0)
                {
                    ShowStatus("No valid rows found. Expect: Name, Width[mm], Length[mm].");
                    return;
                }

                _columnSectionSpecs.Clear();
                foreach (ColumnSectionSpec spec in items)
                {
                    _columnSectionSpecs.Add(spec);
                }

                ShowStatus($"Loaded {items.Count} column section row(s) from {sourceLabel}.");
                UpdateCad2ModelTasWorkflowRail();
            }
            catch (Exception ex)
            {
                ShowStatus("Failed to import column schedule: " + ex.Message);
            }
        }

        private void OnPasteWallSectionsClick(object sender, RoutedEventArgs e)
        {
            string text = Clipboard.GetText();
            if (string.IsNullOrWhiteSpace(text))
            {
                ShowStatus("Clipboard is empty.");
                return;
            }

            List<WallSectionSpec> items = ParseWallSectionSpecs(text);
            if (items.Count == 0)
            {
                ShowStatus("No valid rows found. Expect: Name, Width[mm].");
                return;
            }

            _wallSectionSpecs.Clear();
            foreach (WallSectionSpec spec in items)
            {
                _wallSectionSpecs.Add(spec);
            }

            ShowStatus($"Loaded {items.Count} wall section row(s).");
            UpdateCad2ModelTasWorkflowRail();
        }

