        private void ApplyIdentifyElementScheduleResult(IdentifyElementScheduleWindow dialog)
        {
            if (dialog == null)
            {
                return;
            }

            string group = dialog.ResultElementGroup ?? "Column";
            if (group.Equals("Wall", StringComparison.OrdinalIgnoreCase))
            {
                UpdateWallSectionSpecs(dialog.ResultWallSpecs.ToList(), "Identify Element Schedule");
                return;
            }

            if (group.Equals("Beam", StringComparison.OrdinalIgnoreCase))
            {
                UpdateBeamSectionSpecs(dialog.ResultBeamSpecs.ToList(), "Identify Element Schedule");
                return;
            }

            if (group.Equals("Slab", StringComparison.OrdinalIgnoreCase))
            {
                UpdateSlabSectionSpecs(dialog.ResultSlabSpecs.ToList(), "Identify Element Schedule");
                return;
            }

            UpdateColumnSectionSpecs(dialog.ResultSpecs.ToList(), "Identify Element Schedule");
        }

        private string GetColumnSectionExcelPath()
        {
            return Path.Combine(GetDatabaseFolder(), ColumnSectionExcelFileName);
        }

        private void OnOpenColumnExcelClick(object sender, RoutedEventArgs e)
        {
            string folder = GetDatabaseFolder();
            string path = GetColumnSectionExcelPath();

            try
            {
                if (!File.Exists(path))
                {
                    string template = Path.Combine(folder, "Beam Section.xlsx");
                    if (File.Exists(template))
                    {
                        File.Copy(template, path, false);
                    }
                }

                if (File.Exists(path))
                {
                    Process.Start(new ProcessStartInfo
                    {
                        FileName = path,
                        UseShellExecute = true
                    });
                    ShowStatus($"Opened: {path}");
                }
                else
                {
                    if (!Directory.Exists(folder))
                    {
                        Directory.CreateDirectory(folder);
                    }
                    Process.Start(new ProcessStartInfo
                    {
                        FileName = folder,
                        UseShellExecute = true
                    });
                    ShowStatus($"Excel file not found. Please create: {path}");
                }
            }
            catch (Exception ex)
            {
                ShowStatus($"Failed to open Excel: {ex.Message}");
            }
        }

