        private void RequestEditTypeProperties(System.Windows.Controls.ComboBox combo, string displayName, params BuiltInCategory[] candidateCategories)
        {
            if (!(combo?.SelectedItem is ComboItem selected))
            {
                ShowStatus("Select " + (string.IsNullOrWhiteSpace(displayName) ? "type" : displayName) + ".");
                return;
            }

            _handler.Request.EditSelectedTypeId = selected.Id;
            _handler.Request.EditSelectedTypeDisplayName = displayName ?? "type";
            _handler.Request.EditSelectedTypeCandidateCategories = (candidateCategories ?? Array.Empty<BuiltInCategory>()).ToList();
            _handler.Request.RequestType = CadToModelRequestType.EditSelectedTypeProperties;
            _refreshTypeListsOnActivate = true;
            _externalEvent.Raise();
        }

