        private void OnLinksheetImportClick(object sender, RoutedEventArgs e)
        {
            var dialog = new OpenFileDialog
            {
                Title = "Import LinkSheet Excel",
                Filter = "Excel files (*.xlsx;*.xlsm;*.xls)|*.xlsx;*.xlsm;*.xls",
                Multiselect = false,
                CheckFileExists = true
            };

            if (dialog.ShowDialog(this) != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            try
            {
                List<LinksheetSchedulePreview> imported = ReadLinksheetPreviewsFromExcel(
                    dialog.FileName,
                    out int importedSheets,
                    out int importedRows,
                    out int skippedRows);

                if (imported.Count == 0)
                {
                    ShowStatus("LINKSHEET import: no valid row found. Expected columns include GUID and/or Element ID.");
                    return;
                }

                if (LinksheetSubTabControl != null)
                {
                    SelectTabItemByHeader(LinksheetSubTabControl, "Preview/Edit");
                }

                string fileName = Path.GetFileName(dialog.FileName);
                UpdateLinksheetPreview(
                    imported,
                    "LINKSHEET imported: " + fileName +
                    " (sheets: " + importedSheets.ToString(CultureInfo.InvariantCulture) +
                    ", rows: " + importedRows.ToString(CultureInfo.InvariantCulture) +
                    ", skipped: " + skippedRows.ToString(CultureInfo.InvariantCulture) + ").");
            }
            catch (Exception ex)
            {
                ShowStatus("LINKSHEET import failed: " + ex.Message);
            }
        }

        private static List<LinksheetSchedulePreview> ReadLinksheetPreviewsFromExcel(
            string path,
            out int importedSheets,
            out int importedRows,
            out int skippedRows)
        {
            importedSheets = 0;
            importedRows = 0;
            skippedRows = 0;
            var result = new List<LinksheetSchedulePreview>();

            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                return result;
            }

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Open(path, Type.Missing, true);
                dynamic workbook = workbookObj;

                object worksheetsObj = null;
                try
                {
                    worksheetsObj = workbook.Worksheets;
                    dynamic worksheets = worksheetsObj;
                    int sheetCount = Convert.ToInt32(worksheets.Count, CultureInfo.InvariantCulture);

                    for (int wsIndex = 1; wsIndex <= sheetCount; wsIndex++)
                    {
                        object worksheetObj = null;
                        object usedRangeObj = null;
                        try
                        {
                            worksheetObj = worksheets[wsIndex];
                            dynamic worksheet = worksheetObj;
                            string sheetName = Convert.ToString(worksheet.Name, CultureInfo.InvariantCulture) ??
                                               ("Sheet" + wsIndex.ToString(CultureInfo.InvariantCulture));

                            usedRangeObj = worksheet.UsedRange;
                            dynamic usedRange = usedRangeObj;
                            object valuesObj = usedRange.Value2;
                            object[,] values = NormalizeExcelRangeToMatrix(valuesObj);
                            if (values == null)
                            {
                                continue;
                            }

                            LinksheetSchedulePreview preview = BuildLinksheetImportedPreviewFromExcelMatrix(
                                values,
                                sheetName,
                                ref importedRows,
                                ref skippedRows);
                            if (preview == null || preview.Rows.Count == 0)
                            {
                                continue;
                            }

                            result.Add(preview);
                            importedSheets++;
                        }
                        finally
                        {
                            SafeReleaseCom(usedRangeObj);
                            SafeReleaseCom(worksheetObj);
                        }
                    }
                }
                finally
                {
                    SafeReleaseCom(worksheetsObj);
                }

                workbook.Close(false);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }

            return result;
        }

        private static LinksheetSchedulePreview BuildLinksheetImportedPreviewFromExcelMatrix(
            object[,] values,
            string sheetName,
            ref int importedRows,
            ref int skippedRows)
        {
            if (values == null)
            {
                return null;
            }

            int rMin = values.GetLowerBound(0);
            int rMax = values.GetUpperBound(0);
            int cMin = values.GetLowerBound(1);
            int cMax = values.GetUpperBound(1);
            if (rMax < rMin || cMax < cMin)
            {
                return null;
            }

            int headerRow = FindLinksheetHeaderRow(values, rMin, rMax, cMin, cMax);
            if (headerRow < rMin)
            {
                return null;
            }

            var columns = new List<(int Index, string Header, string Key, bool IsGuid, bool IsElementId)>();
            var usedKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int c = cMin; c <= cMax; c++)
            {
                string header = NormalizeImportedHeaderCell((ToCellString(values[headerRow, c]) ?? "").Trim());
                if (string.IsNullOrWhiteSpace(header))
                {
                    continue;
                }

                bool isGuid = IsLinksheetGuidHeader(header);
                bool isElementId = IsLinksheetElementIdHeader(header);
                string key;
                if (isGuid)
                {
                    key = LinksheetFieldKeys.Guid;
                }
                else if (isElementId)
                {
                    key = LinksheetFieldKeys.ElementId;
                }
                else
                {
                    key = NormalizeLinksheetKey(header);
                }

                if (string.IsNullOrWhiteSpace(key))
                {
                    key = "col_" + c.ToString(CultureInfo.InvariantCulture);
                }

                if (!usedKeys.Add(key))
                {
                    key = key + "_" + c.ToString(CultureInfo.InvariantCulture);
                    usedKeys.Add(key);
                }

                columns.Add((c, header, key, isGuid, isElementId));
            }

            if (columns.Count == 0)
            {
                return null;
            }

            var preview = new LinksheetSchedulePreview
            {
                ScheduleName = string.IsNullOrWhiteSpace(sheetName) ? "Imported" : sheetName.Trim()
            };

            foreach (var column in columns)
            {
                preview.ColumnKeys.Add(column.Key);
                preview.ColumnHeaders[column.Key] = column.Header;
            }

            bool hasGuidColumn = columns.Any(c => c.IsGuid);
            bool hasElementIdColumn = columns.Any(c => c.IsElementId);
            for (int r = headerRow + 1; r <= rMax; r++)
            {
                var cellValues = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                bool hasNonEmptyCell = false;
                foreach (var column in columns)
                {
                    string value = (ToCellString(values[r, column.Index]) ?? "").Trim();
                    if (!string.IsNullOrWhiteSpace(value))
                    {
                        hasNonEmptyCell = true;
                    }

                    cellValues[column.Key] = value;
                }

                if (!hasNonEmptyCell)
                {
                    continue;
                }
                if (IsLikelyLinksheetHeaderRepeatRow(cellValues, columns))
                {
                    skippedRows++;
                    continue;
                }

                string guid = hasGuidColumn && cellValues.TryGetValue(LinksheetFieldKeys.Guid, out string guidRaw)
                    ? (guidRaw ?? "").Trim()
                    : "";
                long elementId = 0;
                if (hasElementIdColumn && cellValues.TryGetValue(LinksheetFieldKeys.ElementId, out string idRaw))
                {
                    TryParseLinksheetElementId(idRaw, out elementId);
                }

                if (string.IsNullOrWhiteSpace(guid) && elementId <= 0)
                {
                    skippedRows++;
                    continue;
                }

                var row = new LinksheetPreviewRow
                {
                    UniqueId = guid,
                    ElementId = elementId
                };

                foreach (var column in columns.Where(c => !c.IsGuid && !c.IsElementId))
                {
                    if (!cellValues.TryGetValue(column.Key, out string value) || string.IsNullOrWhiteSpace(value))
                    {
                        continue;
                    }

                    row.Values[column.Key] = value;
                }

                preview.Rows.Add(row);
                importedRows++;
            }

            return preview;
        }

        private static bool IsLikelyLinksheetHeaderRepeatRow(
            Dictionary<string, string> cellValues,
            List<(int Index, string Header, string Key, bool IsGuid, bool IsElementId)> columns)
        {
            if (cellValues == null || columns == null || columns.Count == 0)
            {
                return false;
            }

            int comparable = 0;
            int matches = 0;
            foreach (var column in columns)
            {
                if (string.IsNullOrWhiteSpace(column.Header))
                {
                    continue;
                }

                comparable++;
                if (!cellValues.TryGetValue(column.Key, out string value))
                {
                    continue;
                }

                string normalized = NormalizeImportedHeaderCell((value ?? "").Trim());
                if (string.Equals(normalized, column.Header, StringComparison.OrdinalIgnoreCase))
                {
                    matches++;
                }
            }

            if (comparable == 0)
            {
                return false;
            }

            return matches >= Math.Max(2, comparable - 1);
        }

        private static int FindLinksheetHeaderRow(object[,] values, int rMin, int rMax, int cMin, int cMax)
        {
            int bestRow = -1;
            int bestScore = int.MinValue;
            int scanMax = Math.Min(rMax, rMin + 80);

            for (int r = rMin; r <= scanMax; r++)
            {
                int nonEmpty = 0;
                int guidHits = 0;
                int elementIdHits = 0;
                int nameLikeHits = 0;

                for (int c = cMin; c <= cMax; c++)
                {
                    string cell = NormalizeImportedHeaderCell((ToCellString(values[r, c]) ?? "").Trim());
                    if (string.IsNullOrWhiteSpace(cell))
                    {
                        continue;
                    }

                    nonEmpty++;
                    if (IsLinksheetGuidHeader(cell))
                    {
                        guidHits++;
                    }
                    else if (IsLinksheetElementIdHeader(cell))
                    {
                        elementIdHits++;
                    }
                    else if (LooksLikeLinksheetHeaderCell(cell))
                    {
                        nameLikeHits++;
                    }
                }

                if (nonEmpty == 0)
                {
                    continue;
                }

                int score = (guidHits * 120) + (elementIdHits * 100) + (nameLikeHits * 5) + Math.Min(nonEmpty, 20);
                if (guidHits > 0 || elementIdHits > 0)
                {
                    score += 40;
                }

                if (score > bestScore)
                {
                    bestScore = score;
                    bestRow = r;
                }
            }

            if (bestRow >= 0)
            {
                return bestRow;
            }

            for (int r = rMin; r <= scanMax; r++)
            {
                int nonEmpty = 0;
                for (int c = cMin; c <= cMax; c++)
                {
                    if (!string.IsNullOrWhiteSpace(ToCellString(values[r, c])))
                    {
                        nonEmpty++;
                    }
                }

                if (nonEmpty > 1)
                {
                    return r;
                }
            }

            return -1;
        }

        private static bool LooksLikeLinksheetHeaderCell(string value)
        {
            string text = (value ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            if (text.StartsWith("{", StringComparison.Ordinal) ||
                text.StartsWith("[", StringComparison.Ordinal))
            {
                return false;
            }

            if (text.Length > 120)
            {
                return false;
            }

            return text.Any(char.IsLetter);
        }

        private static bool IsLinksheetGuidHeader(string value)
        {
            string text = (value ?? "").Trim();
            return string.Equals(text, "GUID", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(text, "__GUID__", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(text, "UniqueId", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(text, "Unique Id", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsLinksheetElementIdHeader(string value)
        {
            string text = (value ?? "").Trim();
            return string.Equals(text, "Element ID", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(text, "ElementId", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(text, "__ELEMENT_ID__", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(text, "Id", StringComparison.OrdinalIgnoreCase);
        }

        private static bool TryParseLinksheetElementId(string value, out long elementId)
        {
            elementId = 0;
            string text = (value ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out long id))
            {
                elementId = id;
                return true;
            }

            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out double asDouble) ||
                double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out asDouble))
            {
                long rounded = Convert.ToInt64(Math.Round(asDouble), CultureInfo.InvariantCulture);
                if (rounded > 0)
                {
                    elementId = rounded;
                    return true;
                }
            }

            return false;
        }

        private void OnLinksheetExportClick(object sender, RoutedEventArgs e)
        {
            SyncActiveLinksheetTableToPreviewModel();

            if (_linksheetPreviewBySchedule.Count == 0)
            {
                ShowStatus("LINKSHEET: no preview data. Click Preview/Edit first.");
                return;
            }

            string defaultFileName = BuildLinksheetDefaultExportFileName();
            var dialog = new SaveFileDialog
            {
                Title = "Export LinkSheet Excel",
                Filter = "Excel Workbook (*.xlsx)|*.xlsx",
                FileName = defaultFileName,
                AddExtension = true,
                DefaultExt = ".xlsx"
            };

            if (dialog.ShowDialog(this) != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            bool keepFormatting = LinksheetKeepFormattingCheck?.IsChecked == true;
            bool openAfterExport = (LinksheetPreviewOpenAfterExportCheck?.IsChecked == true) ||
                                   (LinksheetOpenAfterExportCheck?.IsChecked == true);

            try
            {
                ExportLinksheetPreviewToExcel(
                    _linksheetPreviewBySchedule.Values
                        .OrderBy(p => p.ScheduleName, StringComparer.OrdinalIgnoreCase)
                        .ToList(),
                    dialog.FileName,
                    keepFormatting,
                    openAfterExport);

                int rows = _linksheetPreviewBySchedule.Values.Sum(p => p.Rows.Count);
                ShowStatus("LINKSHEET exported: " + dialog.FileName + " (" +
                           rows.ToString(CultureInfo.InvariantCulture) + " row(s)).");
            }
            catch (Exception ex)
            {
                ShowStatus("LINKSHEET export failed: " + ex.Message);
            }
        }

        private void OnLinksheetResetValuesClick(object sender, RoutedEventArgs e)
        {
            _linksheetUiUpdateInProgress = true;
            try
            {
                foreach (LinksheetScheduleSelectionItem schedule in _linksheetAllScheduleItems)
                {
                    schedule.IsChecked = false;
                }

                foreach (LinksheetParameterSelectionItem parameter in _linksheetAllParameterItems)
                {
                    parameter.IsChecked = false;
                }

                if (LinksheetHideUncheckedSchedulesCheck != null)
                {
                    LinksheetHideUncheckedSchedulesCheck.IsChecked = false;
                }
                if (LinksheetParameterTypeCombo != null)
                {
                    LinksheetParameterTypeCombo.SelectedIndex = 0;
                }
                if (LinksheetScheduleSearchTextBox != null)
                {
                    LinksheetScheduleSearchTextBox.Text = "";
                }
                if (LinksheetParameterSearchTextBox != null)
                {
                    LinksheetParameterSearchTextBox.Text = "";
                }
            }
            finally
            {
                _linksheetUiUpdateInProgress = false;
            }

            RebuildLinksheetScheduleView();
            RebuildLinksheetParameterView();
            UpdateLinksheetSelectionSummaryTexts();
            ClearLinksheetPreviewData("Collecting data: 0 schedule(s), 0 row(s).");
            ShowStatus("LINKSHEET reset complete.");
        }

        private void OnLinksheetUpdateModelClick(object sender, RoutedEventArgs e)
        {
            SyncActiveLinksheetTableToPreviewModel();

            List<LinksheetCellEdit> edits = BuildLinksheetCellEditsFromPreviewDiff();
            if (edits.Count == 0)
            {
                ShowStatus("LINKSHEET: no edited values to update.");
                return;
            }

            _handler.Request.LinksheetScope = GetLinksheetScope();
            _handler.Request.LinksheetSelectedScheduleNames = _linksheetPreviewBySchedule.Keys
                .OrderBy(n => n, StringComparer.OrdinalIgnoreCase)
                .ToList();
            _handler.Request.LinksheetSelectedParameterKeys = GetLinksheetSelectedParameterKeys();
            if (_handler.Request.LinksheetSelectedParameterKeys.Count == 0)
            {
                _handler.Request.LinksheetSelectedParameterKeys = edits
                    .Select(edit => edit.ParameterKey)
                    .Where(k => !string.IsNullOrWhiteSpace(k))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(k => k, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }

            _handler.Request.LinksheetEditedCells = edits;
            _handler.Request.RequestType = CadToModelRequestType.ApplyLinksheetPreviewEdits;
            _externalEvent.Raise();
            ShowStatus("LINKSHEET: applying " + edits.Count.ToString(CultureInfo.InvariantCulture) + " edited value(s) to model...");
        }

        private void UpdateLinksheetScopeBadge()
        {
            if (LinksheetScopeBadgeText == null)
            {
                return;
            }

            string scope = "Whole Model";
            if (LinksheetActiveViewRadio?.IsChecked == true)
            {
                scope = "Active View";
            }
            else if (LinksheetCurrentSelectionRadio?.IsChecked == true)
            {
                scope = "Current Selection";
            }

            LinksheetScopeBadgeText.Text = "Scope: " + scope;
        }

        internal void UpdateLinksheetSchedules(List<LinksheetScheduleInfo> schedules)
        {
            void apply()
            {
                _linksheetUiUpdateInProgress = true;
                try
                {
                    var selected = new HashSet<string>(
                        _linksheetAllScheduleItems.Where(i => i.IsChecked).Select(i => i.Name),
                        StringComparer.OrdinalIgnoreCase);

                    _linksheetAllScheduleItems.Clear();
                    foreach (LinksheetScheduleInfo schedule in schedules ?? new List<LinksheetScheduleInfo>())
                    {
                        _linksheetAllScheduleItems.Add(new LinksheetScheduleSelectionItem
                        {
                            Name = schedule?.Name ?? "",
                            ElementCount = schedule?.ElementCount ?? 0,
                            IsChecked = selected.Contains(schedule?.Name ?? "")
                        });
                    }
                }
                finally
                {
                    _linksheetUiUpdateInProgress = false;
                }

                RebuildLinksheetScheduleView();
                UpdateLinksheetSelectionSummaryTexts();

                if (_linksheetAllScheduleItems.Count == 0 ||
                    !_linksheetAllScheduleItems.Any(i => i.IsChecked))
                {
                    UpdateLinksheetParameters(new List<LinksheetParameterInfo>());
                }

                _linksheetSchedulesLoadedOnce = true;
            }

            if (Dispatcher.CheckAccess())
            {
                apply();
            }
            else
            {
                Dispatcher.Invoke(apply);
            }
        }

        internal void UpdateLinksheetParameters(List<LinksheetParameterInfo> parameters)
        {
            void apply()
            {
                _linksheetUiUpdateInProgress = true;
                try
                {
                    var selected = new HashSet<string>(
                        _linksheetAllParameterItems.Where(i => i.IsChecked).Select(i => i.Key),
                        StringComparer.OrdinalIgnoreCase);
                    bool keepPreviousSelection = selected.Count > 0;

                    _linksheetAllParameterItems.Clear();
                    foreach (LinksheetParameterInfo parameter in parameters ?? new List<LinksheetParameterInfo>())
                    {
                        string key = NormalizeLinksheetKey(parameter?.Key);
                        if (string.IsNullOrWhiteSpace(key))
                        {
                            continue;
                        }

                        _linksheetAllParameterItems.Add(new LinksheetParameterSelectionItem
                        {
                            Key = key,
                            Name = parameter?.Name ?? "",
                            Kind = parameter?.Kind ?? LinksheetParameterKind.ReadOnly,
                            IsChecked = !keepPreviousSelection || selected.Contains(key)
                        });
                    }
                }
                finally
                {
                    _linksheetUiUpdateInProgress = false;
                }

                RebuildLinksheetParameterView();
                UpdateLinksheetSelectionSummaryTexts();
            }

            if (Dispatcher.CheckAccess())
            {
                apply();
            }
            else
            {
                Dispatcher.Invoke(apply);
            }
        }

        internal void UpdateLinksheetPreview(List<LinksheetSchedulePreview> previews, string message)
        {
            void apply()
            {
                _linksheetPreviewBySchedule.Clear();
                _linksheetOriginalPreviewBySchedule.Clear();
                foreach (LinksheetSchedulePreview preview in previews ?? new List<LinksheetSchedulePreview>())
                {
                    if (preview == null || string.IsNullOrWhiteSpace(preview.ScheduleName))
                    {
                        continue;
                    }

                    LinksheetSchedulePreview current = CloneLinksheetSchedulePreview(preview);
                    _linksheetPreviewBySchedule[current.ScheduleName] = current;
                    _linksheetOriginalPreviewBySchedule[current.ScheduleName] = CloneLinksheetSchedulePreview(current);
                }

                _linksheetUiUpdateInProgress = true;
                try
                {
                    if (LinksheetPreviewSheetCombo != null)
                    {
                        List<string> names = _linksheetPreviewBySchedule.Keys
                            .OrderBy(n => n, StringComparer.OrdinalIgnoreCase)
                            .ToList();
                        LinksheetPreviewSheetCombo.ItemsSource = names;
                        LinksheetPreviewSheetCombo.SelectedIndex = names.Count > 0 ? 0 : -1;
                    }
                }
                finally
                {
                    _linksheetUiUpdateInProgress = false;
                }

                if (_linksheetPreviewBySchedule.Count == 0)
                {
                    ClearLinksheetPreviewData("Collecting data: 0 schedule(s), 0 row(s).");
                }
                else
                {
                    string firstSchedule = _linksheetPreviewBySchedule.Keys
                        .OrderBy(n => n, StringComparer.OrdinalIgnoreCase)
                        .First();
                    RenderLinksheetPreviewSheet(firstSchedule);

                    int scheduleCount = _linksheetPreviewBySchedule.Count;
                    int rowCount = _linksheetPreviewBySchedule.Values.Sum(p => p.Rows.Count);
                    if (LinksheetPreviewProgressText != null)
                    {
                        LinksheetPreviewProgressText.Text = "Collecting data: " +
                            scheduleCount.ToString(CultureInfo.InvariantCulture) + " schedule(s), " +
                            rowCount.ToString(CultureInfo.InvariantCulture) + " row(s).";
                    }
                    if (LinksheetPreviewPercentText != null)
                    {
                        LinksheetPreviewPercentText.Text = "100%";
                    }
                }

                if (!string.IsNullOrWhiteSpace(message))
                {
                    ShowStatus(message);
                }
            }

            if (Dispatcher.CheckAccess())
            {
                apply();
            }
            else
            {
                Dispatcher.Invoke(apply);
            }
        }

        private void RebuildLinksheetScheduleView()
        {
            _linksheetScheduleItems.Clear();

            string search = (LinksheetScheduleSearchTextBox?.Text ?? "").Trim();
            bool hideUnchecked = LinksheetHideUncheckedSchedulesCheck?.IsChecked == true;

            IEnumerable<LinksheetScheduleSelectionItem> query = _linksheetAllScheduleItems;
            if (!string.IsNullOrWhiteSpace(search))
            {
                query = query.Where(i =>
                    !string.IsNullOrWhiteSpace(i.Name) &&
                    i.Name.IndexOf(search, StringComparison.OrdinalIgnoreCase) >= 0);
            }
            if (hideUnchecked)
            {
                query = query.Where(i => i.IsChecked);
            }

            foreach (LinksheetScheduleSelectionItem item in query.OrderBy(i => i.Name, StringComparer.OrdinalIgnoreCase))
            {
                _linksheetScheduleItems.Add(item);
            }
        }

        private void RebuildLinksheetParameterView()
        {
            _linksheetParameterItems.Clear();

            string search = (LinksheetParameterSearchTextBox?.Text ?? "").Trim();
            LinksheetParameterKind? kindFilter = GetLinksheetParameterKindFilter();

            IEnumerable<LinksheetParameterSelectionItem> query = _linksheetAllParameterItems;
            if (kindFilter.HasValue)
            {
                query = query.Where(i => i.Kind == kindFilter.Value);
            }
            if (!string.IsNullOrWhiteSpace(search))
            {
                query = query.Where(i =>
                    !string.IsNullOrWhiteSpace(i.Name) &&
                    i.Name.IndexOf(search, StringComparison.OrdinalIgnoreCase) >= 0);
            }

            foreach (LinksheetParameterSelectionItem item in query.OrderBy(i => i.Name, StringComparer.OrdinalIgnoreCase))
            {
                _linksheetParameterItems.Add(item);
            }
        }

        private LinksheetParameterKind? GetLinksheetParameterKindFilter()
        {
            if (LinksheetParameterTypeCombo == null)
            {
                return null;
            }

            switch (LinksheetParameterTypeCombo.SelectedIndex)
            {
                case 1:
                    return LinksheetParameterKind.Instance;
                case 2:
                    return LinksheetParameterKind.Type;
                case 3:
                    return LinksheetParameterKind.ReadOnly;
                default:
                    return null;
            }
        }

        private void UpdateLinksheetSelectionSummaryTexts()
        {
            int selectedSchedules = _linksheetAllScheduleItems.Count(i => i.IsChecked);
            int totalSchedules = _linksheetAllScheduleItems.Count;
            int selectedParameters = _linksheetAllParameterItems.Count(i => i.IsChecked);
            int totalParameters = _linksheetAllParameterItems.Count;

            if (LinksheetScheduleCountText != null)
            {
                LinksheetScheduleCountText.Text =
                    selectedSchedules.ToString(CultureInfo.InvariantCulture) + "/" +
                    totalSchedules.ToString(CultureInfo.InvariantCulture) + " schedules selected";
            }

            if (LinksheetSelectedParameterCountText != null)
            {
                LinksheetSelectedParameterCountText.Text =
                    selectedParameters.ToString(CultureInfo.InvariantCulture) + "/" +
                    totalParameters.ToString(CultureInfo.InvariantCulture) + " parameter(s) selected";
            }

            if (LinksheetSchedulesHintText != null)
            {
                if (totalSchedules == 0)
                {
                    LinksheetSchedulesHintText.Text = "No schedules found. Click Reload to refresh model data.";
                }
                else
                {
                    LinksheetSchedulesHintText.Text = "Select schedule(s), select parameter(s), then click Preview/Edit.";
                }
            }
        }

        private List<string> GetLinksheetSelectedScheduleNames()
        {
            return _linksheetAllScheduleItems
                .Where(i => i.IsChecked && !string.IsNullOrWhiteSpace(i.Name))
                .Select(i => i.Name.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(n => n, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private List<string> GetLinksheetSelectedParameterKeys()
        {
            return _linksheetAllParameterItems
                .Where(i => i.IsChecked && !string.IsNullOrWhiteSpace(i.Key))
                .Select(i => i.Key)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(k => k, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private void RequestLinksheetParametersRefresh()
        {
            List<string> selectedSchedules = GetLinksheetSelectedScheduleNames();
            if (selectedSchedules.Count == 0)
            {
                UpdateLinksheetParameters(new List<LinksheetParameterInfo>());
                return;
            }

            _handler.Request.LinksheetScope = GetLinksheetScope();
            _handler.Request.LinksheetSelectedScheduleNames = selectedSchedules;
            _handler.Request.RequestType = CadToModelRequestType.RefreshLinksheetParameters;
            _externalEvent.Raise();
        }

        private void RequestLinksheetSchedulesRefresh(bool focusSchedulesTab)
        {
            if (focusSchedulesTab && LinksheetSubTabControl != null)
            {
                SelectTabItemByHeader(LinksheetSubTabControl, "Schedules");
            }

            _handler.Request.LinksheetScope = GetLinksheetScope();
            _handler.Request.RequestType = CadToModelRequestType.RefreshLinksheetSchedules;
            _externalEvent.Raise();
            ShowStatus("LINKSHEET: refreshing schedules...");
        }

        private bool RequestLinksheetPreviewBuild()
        {
            List<string> selectedSchedules = GetLinksheetSelectedScheduleNames();
            if (selectedSchedules.Count == 0)
            {
                return false;
            }

            _handler.Request.LinksheetScope = GetLinksheetScope();
            _handler.Request.LinksheetSelectedScheduleNames = selectedSchedules;
            _handler.Request.LinksheetSelectedParameterKeys = GetLinksheetSelectedParameterKeys();
            _handler.Request.RequestType = CadToModelRequestType.BuildLinksheetPreview;
            _externalEvent.Raise();
            return true;
        }

        private QsScope GetLinksheetScope()
        {
            if (LinksheetCurrentSelectionRadio?.IsChecked == true)
            {
                return QsScope.CurrentSelection;
            }
            if (LinksheetActiveViewRadio?.IsChecked == true)
            {
                return QsScope.CurrentView;
            }

            return QsScope.EntireModel;
        }

        private void ClearLinksheetPreviewData(string progressText)
        {
            _linksheetActivePreviewTable = null;
            _linksheetActivePreviewScheduleName = "";
            _linksheetActiveHeaderToKey = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            if (LinksheetPreviewDataGrid != null)
            {
                LinksheetPreviewDataGrid.ItemsSource = null;
            }

            if (LinksheetPreviewSheetCombo != null)
            {
                _linksheetUiUpdateInProgress = true;
                try
                {
                    LinksheetPreviewSheetCombo.ItemsSource = new List<string>();
                    LinksheetPreviewSheetCombo.SelectedIndex = -1;
                }
                finally
                {
                    _linksheetUiUpdateInProgress = false;
                }
            }

            if (LinksheetPreviewProgressText != null)
            {
                LinksheetPreviewProgressText.Text = progressText ?? "Collecting data: 0 schedule(s), 0 row(s).";
            }
            if (LinksheetPreviewPercentText != null)
            {
                LinksheetPreviewPercentText.Text = "0%";
            }
        }

        private void RenderLinksheetPreviewSheet(string scheduleName)
        {
            if (string.IsNullOrWhiteSpace(scheduleName) ||
                !_linksheetPreviewBySchedule.TryGetValue(scheduleName, out LinksheetSchedulePreview preview) ||
                preview == null)
            {
                _linksheetActivePreviewTable = null;
                _linksheetActivePreviewScheduleName = "";
                _linksheetActiveHeaderToKey = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                if (LinksheetPreviewDataGrid != null)
                {
                    LinksheetPreviewDataGrid.ItemsSource = null;
                }
                return;
            }

            _linksheetActivePreviewScheduleName = preview.ScheduleName ?? scheduleName ?? "";
            _linksheetActivePreviewTable = BuildLinksheetPreviewDataTable(preview, out Dictionary<string, string> headerToKey);
            _linksheetActiveHeaderToKey = headerToKey ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (LinksheetPreviewDataGrid != null)
            {
                LinksheetPreviewDataGrid.ItemsSource = _linksheetActivePreviewTable.DefaultView;
            }

            if (LinksheetPreviewHintText != null)
            {
                LinksheetPreviewHintText.Text = "Columns: GUID + Element ID + selected parameters. Rows: " +
                                                preview.Rows.Count.ToString(CultureInfo.InvariantCulture) + ".";
            }
        }

        private void OnLinksheetPreviewDataGridAutoGeneratingColumn(object sender, DataGridAutoGeneratingColumnEventArgs e)
        {
            if (e?.Column == null)
            {
                return;
            }

            string header = Convert.ToString(e.Column.Header, CultureInfo.InvariantCulture) ?? "";
            string key = "";
            if (!string.IsNullOrWhiteSpace(header) &&
                _linksheetActiveHeaderToKey.TryGetValue(header, out string mappedKey))
            {
                key = mappedKey ?? "";
            }
            if (string.IsNullOrWhiteSpace(key))
            {
                key = NormalizeLinksheetKey(header);
            }

            bool isIdentityColumn = string.Equals(key, LinksheetFieldKeys.Guid, StringComparison.OrdinalIgnoreCase) ||
                                    string.Equals(key, LinksheetFieldKeys.ElementId, StringComparison.OrdinalIgnoreCase);
            LinksheetParameterKind kind = GetLinksheetParameterKindByKey(key);
            bool isReadOnly = isIdentityColumn || kind == LinksheetParameterKind.ReadOnly;
            e.Column.IsReadOnly = isReadOnly;
        }

        private void OnLinksheetPreviewDataGridPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            if (!(sender is DataGrid grid) ||
                e == null ||
                (Keyboard.Modifiers & ModifierKeys.Control) != ModifierKeys.Control)
            {
                return;
            }

            DataGridColumnHeader header = FindVisualParent<DataGridColumnHeader>(e.OriginalSource as DependencyObject);
            if (header?.Column == null)
            {
                return;
            }

            SelectLinksheetPreviewColumn(grid, header.Column);
            e.Handled = true;
        }

        private static T FindVisualParent<T>(DependencyObject source) where T : DependencyObject
        {
            while (source != null)
            {
                if (source is T typed)
                {
                    return typed;
                }

                source = VisualTreeHelper.GetParent(source);
            }

            return null;
        }

        private static void SelectLinksheetPreviewColumn(DataGrid grid, DataGridColumn column)
        {
            if (grid == null || column == null)
            {
                return;
            }

            try
            {
                grid.CommitEdit(DataGridEditingUnit.Cell, true);
                grid.CommitEdit(DataGridEditingUnit.Row, true);
            }
            catch
            {
                // Ignore commit failures and continue selecting visible cells.
            }

            grid.SelectedCells.Clear();
            foreach (object item in grid.Items)
            {
                if (item == null || item == System.Windows.Data.CollectionView.NewItemPlaceholder)
                {
                    continue;
                }

                grid.SelectedCells.Add(new DataGridCellInfo(item, column));
            }

            object firstItem = grid.Items
                .Cast<object>()
                .FirstOrDefault(item => item != null && item != System.Windows.Data.CollectionView.NewItemPlaceholder);
            if (firstItem != null)
            {
                grid.CurrentCell = new DataGridCellInfo(firstItem, column);
            }
        }

        private static LinksheetSchedulePreview CloneLinksheetSchedulePreview(LinksheetSchedulePreview source)
        {
            if (source == null)
            {
                return new LinksheetSchedulePreview();
            }

            var clone = new LinksheetSchedulePreview
            {
                ScheduleName = source.ScheduleName ?? ""
            };

            foreach (string key in source.ColumnKeys ?? new List<string>())
            {
                if (string.IsNullOrWhiteSpace(key))
                {
                    continue;
                }

                clone.ColumnKeys.Add(key);
            }

            if (source.ColumnHeaders != null)
            {
                foreach (KeyValuePair<string, string> pair in source.ColumnHeaders)
                {
                    if (string.IsNullOrWhiteSpace(pair.Key))
                    {
                        continue;
                    }

                    clone.ColumnHeaders[pair.Key] = pair.Value ?? "";
                }
            }

            foreach (LinksheetPreviewRow row in source.Rows ?? new List<LinksheetPreviewRow>())
            {
                if (row == null)
                {
                    continue;
                }

                var rowClone = new LinksheetPreviewRow
                {
                    ElementId = row.ElementId,
                    UniqueId = row.UniqueId ?? ""
                };

                if (row.Values != null)
                {
                    foreach (KeyValuePair<string, string> valuePair in row.Values)
                    {
                        if (string.IsNullOrWhiteSpace(valuePair.Key))
                        {
                            continue;
                        }

                        rowClone.Values[valuePair.Key] = valuePair.Value ?? "";
                    }
                }

                clone.Rows.Add(rowClone);
            }

            return clone;
        }

        private void SyncActiveLinksheetTableToPreviewModel()
        {
            if (_linksheetActivePreviewTable == null ||
                string.IsNullOrWhiteSpace(_linksheetActivePreviewScheduleName) ||
                !_linksheetPreviewBySchedule.TryGetValue(_linksheetActivePreviewScheduleName, out LinksheetSchedulePreview preview) ||
                preview == null)
            {
                return;
            }

            try
            {
                if (LinksheetPreviewDataGrid != null)
                {
                    LinksheetPreviewDataGrid.CommitEdit(DataGridEditingUnit.Cell, true);
                    LinksheetPreviewDataGrid.CommitEdit(DataGridEditingUnit.Row, true);
                }
            }
            catch
            {
                // Ignore commit failures; DataTable still carries committed values for most edit paths.
            }

            Dictionary<string, string> keyToHeader = _linksheetActiveHeaderToKey
                .Where(pair => !string.IsNullOrWhiteSpace(pair.Key) && !string.IsNullOrWhiteSpace(pair.Value))
                .GroupBy(pair => pair.Value, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(group => group.Key, group => group.First().Key, StringComparer.OrdinalIgnoreCase);
            if (keyToHeader.Count == 0)
            {
                return;
            }

            var previewRowsByIdentity = new Dictionary<string, Queue<LinksheetPreviewRow>>(StringComparer.OrdinalIgnoreCase);
            foreach (LinksheetPreviewRow row in preview.Rows ?? new List<LinksheetPreviewRow>())
            {
                if (row == null)
                {
                    continue;
                }

                string identity = BuildLinksheetRowIdentity(row.UniqueId, row.ElementId);
                if (string.IsNullOrWhiteSpace(identity))
                {
                    continue;
                }

                if (!previewRowsByIdentity.TryGetValue(identity, out Queue<LinksheetPreviewRow> queue))
                {
                    queue = new Queue<LinksheetPreviewRow>();
                    previewRowsByIdentity[identity] = queue;
                }

                queue.Enqueue(row);
            }

            foreach (DataRow dataRow in _linksheetActivePreviewTable.Rows)
            {
                if (dataRow == null)
                {
                    continue;
                }

                string guid = TryGetLinksheetPreviewCellValue(dataRow, keyToHeader, LinksheetFieldKeys.Guid);
                string elementIdText = TryGetLinksheetPreviewCellValue(dataRow, keyToHeader, LinksheetFieldKeys.ElementId);
                TryParseLinksheetElementId(elementIdText, out long elementId);
                string identity = BuildLinksheetRowIdentity(guid, elementId);

                LinksheetPreviewRow targetRow = null;
                if (!string.IsNullOrWhiteSpace(identity) &&
                    previewRowsByIdentity.TryGetValue(identity, out Queue<LinksheetPreviewRow> queue) &&
                    queue.Count > 0)
                {
                    targetRow = queue.Dequeue();
                }

                if (targetRow == null)
                {
                    continue;
                }

                foreach (string key in preview.ColumnKeys ?? new List<string>())
                {
                    if (string.IsNullOrWhiteSpace(key) ||
                        !keyToHeader.TryGetValue(key, out string header) ||
                        string.IsNullOrWhiteSpace(header) ||
                        !_linksheetActivePreviewTable.Columns.Contains(header))
                    {
                        continue;
                    }

                    string value = Convert.ToString(dataRow[header], CultureInfo.CurrentCulture) ?? "";
                    if (string.Equals(key, LinksheetFieldKeys.Guid, StringComparison.OrdinalIgnoreCase))
                    {
                        targetRow.UniqueId = value.Trim();
                    }
                    else if (string.Equals(key, LinksheetFieldKeys.ElementId, StringComparison.OrdinalIgnoreCase))
                    {
                        if (TryParseLinksheetElementId(value, out long parsedId))
                        {
                            targetRow.ElementId = parsedId;
                        }
                    }
                    else
                    {
                        targetRow.Values[key] = value;
                    }
                }
            }
        }

        private List<LinksheetCellEdit> BuildLinksheetCellEditsFromPreviewDiff()
        {
            var edits = new List<LinksheetCellEdit>();
            Dictionary<string, LinksheetParameterKind> kindByKey = BuildLinksheetParameterKindMap();

            foreach (KeyValuePair<string, LinksheetSchedulePreview> pair in _linksheetPreviewBySchedule
                .OrderBy(p => p.Key, StringComparer.OrdinalIgnoreCase))
            {
                string scheduleName = pair.Key ?? "";
                LinksheetSchedulePreview current = pair.Value;
                if (current == null || string.IsNullOrWhiteSpace(scheduleName))
                {
                    continue;
                }

                if (!_linksheetOriginalPreviewBySchedule.TryGetValue(scheduleName, out LinksheetSchedulePreview original) ||
                    original == null)
                {
                    continue;
                }

                var originalRowsByIdentity = new Dictionary<string, Queue<LinksheetPreviewRow>>(StringComparer.OrdinalIgnoreCase);
                foreach (LinksheetPreviewRow row in original.Rows ?? new List<LinksheetPreviewRow>())
                {
                    if (row == null)
                    {
                        continue;
                    }

                    string identity = BuildLinksheetRowIdentity(row.UniqueId, row.ElementId);
                    if (string.IsNullOrWhiteSpace(identity))
                    {
                        continue;
                    }

                    if (!originalRowsByIdentity.TryGetValue(identity, out Queue<LinksheetPreviewRow> queue))
                    {
                        queue = new Queue<LinksheetPreviewRow>();
                        originalRowsByIdentity[identity] = queue;
                    }

                    queue.Enqueue(row);
                }

                foreach (LinksheetPreviewRow currentRow in current.Rows ?? new List<LinksheetPreviewRow>())
                {
                    if (currentRow == null)
                    {
                        continue;
                    }

                    string identity = BuildLinksheetRowIdentity(currentRow.UniqueId, currentRow.ElementId);
                    if (string.IsNullOrWhiteSpace(identity) ||
                        !originalRowsByIdentity.TryGetValue(identity, out Queue<LinksheetPreviewRow> queue) ||
                        queue.Count == 0)
                    {
                        continue;
                    }

                    LinksheetPreviewRow originalRow = queue.Dequeue();
                    foreach (string key in current.ColumnKeys ?? new List<string>())
                    {
                        if (string.IsNullOrWhiteSpace(key) ||
                            string.Equals(key, LinksheetFieldKeys.Guid, StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(key, LinksheetFieldKeys.ElementId, StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        LinksheetParameterKind kind = GetLinksheetParameterKindByKey(key, kindByKey);
                        if (kind == LinksheetParameterKind.ReadOnly)
                        {
                            continue;
                        }

                        string originalValue = "";
                        if (originalRow.Values != null &&
                            originalRow.Values.TryGetValue(key, out string oldValue) &&
                            oldValue != null)
                        {
                            originalValue = oldValue;
                        }

                        string currentValue = "";
                        if (currentRow.Values != null &&
                            currentRow.Values.TryGetValue(key, out string newValue) &&
                            newValue != null)
                        {
                            currentValue = newValue;
                        }

                        if (string.Equals(originalValue, currentValue, StringComparison.Ordinal))
                        {
                            continue;
                        }

                        edits.Add(new LinksheetCellEdit
                        {
                            ScheduleName = scheduleName,
                            ElementId = currentRow.ElementId,
                            UniqueId = currentRow.UniqueId ?? "",
                            ParameterKey = key,
                            Kind = kind,
                            Value = currentValue
                        });
                    }
                }
            }

            if (edits.Count <= 1)
            {
                return edits;
            }

            var deduped = new Dictionary<string, LinksheetCellEdit>(StringComparer.OrdinalIgnoreCase);
            foreach (LinksheetCellEdit edit in edits)
            {
                string identity = BuildLinksheetRowIdentity(edit.UniqueId, edit.ElementId);
                string dedupeKey = (edit.ScheduleName ?? "") + "|" + identity + "|" + NormalizeLinksheetKey(edit.ParameterKey);
                deduped[dedupeKey] = edit;
            }

            return deduped.Values
                .OrderBy(edit => edit.ScheduleName, StringComparer.OrdinalIgnoreCase)
                .ThenBy(edit => edit.UniqueId, StringComparer.OrdinalIgnoreCase)
                .ThenBy(edit => edit.ElementId)
                .ThenBy(edit => edit.ParameterKey, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private Dictionary<string, LinksheetParameterKind> BuildLinksheetParameterKindMap()
        {
            var map = new Dictionary<string, LinksheetParameterKind>(StringComparer.OrdinalIgnoreCase);
            foreach (LinksheetParameterSelectionItem item in _linksheetAllParameterItems)
            {
                string key = NormalizeLinksheetKey(item?.Key);
                if (string.IsNullOrWhiteSpace(key))
                {
                    continue;
                }

                map[key] = item?.Kind ?? LinksheetParameterKind.ReadOnly;
            }

            return map;
        }

        private LinksheetParameterKind GetLinksheetParameterKindByKey(
            string key,
            Dictionary<string, LinksheetParameterKind> kindByKey = null)
        {
            string normalized = NormalizeLinksheetKey(key);
            if (string.IsNullOrWhiteSpace(normalized))
            {
                return LinksheetParameterKind.ReadOnly;
            }

            if (kindByKey != null && kindByKey.TryGetValue(normalized, out LinksheetParameterKind mappedKind))
            {
                return mappedKind;
            }

            LinksheetParameterSelectionItem item = _linksheetAllParameterItems.FirstOrDefault(
                p => string.Equals(NormalizeLinksheetKey(p?.Key), normalized, StringComparison.OrdinalIgnoreCase));
            return item?.Kind ?? LinksheetParameterKind.ReadOnly;
        }

        private static string BuildLinksheetRowIdentity(string uniqueId, long elementId)
        {
            string guid = (uniqueId ?? "").Trim();
            string idPart = elementId > 0
                ? elementId.ToString(CultureInfo.InvariantCulture)
                : "";

            if (!string.IsNullOrWhiteSpace(guid) && !string.IsNullOrWhiteSpace(idPart))
            {
                return "g:" + guid.ToLowerInvariant() + "|e:" + idPart;
            }
            if (!string.IsNullOrWhiteSpace(guid))
            {
                return "g:" + guid.ToLowerInvariant();
            }
            if (!string.IsNullOrWhiteSpace(idPart))
            {
                return "e:" + idPart;
            }

            return "";
        }

        private static string TryGetLinksheetPreviewCellValue(
            DataRow dataRow,
            Dictionary<string, string> keyToHeader,
            string key)
        {
            if (dataRow == null ||
                keyToHeader == null ||
                string.IsNullOrWhiteSpace(key) ||
                !keyToHeader.TryGetValue(key, out string header) ||
                string.IsNullOrWhiteSpace(header) ||
                dataRow.Table == null ||
                !dataRow.Table.Columns.Contains(header))
            {
                return "";
            }

            object raw = dataRow[header];
            if (raw == null || raw == DBNull.Value)
            {
                return "";
            }

            return Convert.ToString(raw, CultureInfo.CurrentCulture) ?? "";
        }

        private static DataTable BuildLinksheetPreviewDataTable(LinksheetSchedulePreview preview)
        {
            return BuildLinksheetPreviewDataTable(preview, out _);
        }

        private static DataTable BuildLinksheetPreviewDataTable(
            LinksheetSchedulePreview preview,
            out Dictionary<string, string> headerToKey)
        {
            var table = new DataTable(preview?.ScheduleName ?? "Preview");
            headerToKey = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (preview == null)
            {
                return table;
            }

            var columnMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (string key in preview.ColumnKeys ?? new List<string>())
            {
                string header = key;
                if (preview.ColumnHeaders != null && preview.ColumnHeaders.TryGetValue(key, out string mappedHeader))
                {
                    header = mappedHeader;
                }

                if (string.IsNullOrWhiteSpace(header))
                {
                    header = key;
                }

                string uniqueHeader = header;
                int index = 2;
                while (table.Columns.Contains(uniqueHeader))
                {
                    uniqueHeader = header + " (" + index.ToString(CultureInfo.InvariantCulture) + ")";
                    index++;
                }

                table.Columns.Add(uniqueHeader, typeof(string));
                columnMap[key] = uniqueHeader;
                headerToKey[uniqueHeader] = key;
            }

            if (table.Columns.Count == 0)
            {
                table.Columns.Add("Value", typeof(string));
            }

            foreach (LinksheetPreviewRow previewRow in preview.Rows ?? new List<LinksheetPreviewRow>())
            {
                DataRow row = table.NewRow();
                foreach (string key in preview.ColumnKeys ?? new List<string>())
                {
                    if (!columnMap.TryGetValue(key, out string header))
                    {
                        continue;
                    }

                    string value = "";
                    if (string.Equals(key, LinksheetFieldKeys.Guid, StringComparison.OrdinalIgnoreCase))
                    {
                        value = previewRow.UniqueId ?? "";
                    }
                    else if (string.Equals(key, LinksheetFieldKeys.ElementId, StringComparison.OrdinalIgnoreCase))
                    {
                        value = previewRow.ElementId.ToString(CultureInfo.InvariantCulture);
                    }
                    else if (previewRow.Values != null && previewRow.Values.TryGetValue(key, out string fieldValue))
                    {
                        value = fieldValue ?? "";
                    }

                    row[header] = value;
                }

                table.Rows.Add(row);
            }

            return table;
        }

        private string BuildLinksheetDefaultExportFileName()
        {
            List<string> selectedSchedules = GetLinksheetSelectedScheduleNames();
            if (selectedSchedules.Count == 1)
            {
                string sheetName = selectedSchedules[0] ?? "LinkSheet";
                foreach (char c in Path.GetInvalidFileNameChars())
                {
                    sheetName = sheetName.Replace(c, '_');
                }

                return sheetName + ".xlsx";
            }

            return "LinkSheet_" + DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture) + ".xlsx";
        }

        private void ExportLinksheetPreviewToExcel(
            List<LinksheetSchedulePreview> previews,
            string filePath,
            bool keepFormatting,
            bool openAfterExport)
        {
            previews = (previews ?? new List<LinksheetSchedulePreview>())
                .Where(p => p != null && !string.IsNullOrWhiteSpace(p.ScheduleName))
                .ToList();

            if (previews.Count == 0)
            {
                throw new InvalidOperationException("No LinkSheet preview data to export.");
            }

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Add();
                dynamic workbook = workbookObj;

                while (workbook.Worksheets.Count < previews.Count)
                {
                    workbook.Worksheets.Add(After: workbook.Worksheets[workbook.Worksheets.Count]);
                }

                var usedSheetNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                for (int i = 0; i < previews.Count; i++)
                {
                    LinksheetSchedulePreview preview = previews[i];
                    DataTable table = BuildLinksheetPreviewDataTable(preview);

                    object worksheetObj = null;
                    object rangeObj = null;
                    object topLeftObj = null;
                    object bottomRightObj = null;
                    object headerRangeObj = null;

                    try
                    {
                        worksheetObj = workbook.Worksheets[i + 1];
                        dynamic worksheet = worksheetObj;
                        worksheet.Name = BuildLinksheetSafeSheetName(preview.ScheduleName, usedSheetNames);

                        int rowCount = Math.Max(1, table.Rows.Count + 1);
                        int colCount = Math.Max(1, table.Columns.Count);
                        var matrix = new object[rowCount, colCount];

                        for (int c = 0; c < colCount; c++)
                        {
                            matrix[0, c] = table.Columns[c].ColumnName;
                        }

                        for (int r = 0; r < table.Rows.Count; r++)
                        {
                            for (int c = 0; c < colCount; c++)
                            {
                                matrix[r + 1, c] = table.Rows[r][c] ?? "";
                            }
                        }

                        topLeftObj = worksheet.Cells[1, 1];
                        bottomRightObj = worksheet.Cells[rowCount, colCount];
                        rangeObj = worksheet.Range[topLeftObj, bottomRightObj];
                        dynamic range = rangeObj;
                        range.Value2 = matrix;

                        headerRangeObj = worksheet.Range[worksheet.Cells[1, 1], worksheet.Cells[1, colCount]];
                        dynamic headerRange = headerRangeObj;
                        headerRange.Font.Bold = true;
                        headerRange.Interior.Color = 0x87B8EA;

                        if (!keepFormatting)
                        {
                            try
                            {
                                worksheet.Columns.AutoFit();
                            }
                            catch
                            {
                                // ignore Excel auto-fit issues
                            }
                        }
                    }
                    finally
                    {
                        SafeReleaseCom(headerRangeObj);
                        SafeReleaseCom(bottomRightObj);
                        SafeReleaseCom(topLeftObj);
                        SafeReleaseCom(rangeObj);
                        SafeReleaseCom(worksheetObj);
                    }
                }

                workbook.SaveAs(filePath, 51);
                workbook.Close(true);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }

            if (openAfterExport)
            {
                Process.Start(new ProcessStartInfo
                {
                    FileName = filePath,
                    UseShellExecute = true
                });
            }
        }

        private static string BuildLinksheetSafeSheetName(string rawName, HashSet<string> usedNames)
        {
            string name = (rawName ?? "").Trim();
            if (string.IsNullOrWhiteSpace(name))
            {
                name = "Sheet";
            }

            foreach (char invalid in new[] { ':', '\\', '/', '?', '*', '[', ']' })
            {
                name = name.Replace(invalid, '_');
            }

            if (name.Length > 31)
            {
                name = name.Substring(0, 31);
            }

            string candidate = name;
            int index = 2;
            while (usedNames.Contains(candidate))
            {
                string suffix = "_" + index.ToString(CultureInfo.InvariantCulture);
                int maxBaseLength = Math.Max(1, 31 - suffix.Length);
                string baseName = name.Length > maxBaseLength ? name.Substring(0, maxBaseLength) : name;
                candidate = baseName + suffix;
                index++;
            }

            usedNames.Add(candidate);
            return candidate;
        }

        private static string NormalizeLinksheetKey(string value)
        {
            return (value ?? "").Trim().ToLowerInvariant();
        }

