        private string ResolvePowerBiProjectPath(out string expectedPath)
        {
            string databaseFolder = GetDatabaseFolder();
            string primary = Path.Combine(databaseFolder, DefaultPowerBiProjectRelativePath);
            expectedPath = primary;

            var candidates = new List<string>
            {
                primary,
                Path.Combine(databaseFolder, DefaultPowerBiProjectFileName)
            };

            if (!string.IsNullOrWhiteSpace(_powerBiLastExportFolder))
            {
                candidates.Add(Path.Combine(_powerBiLastExportFolder, DefaultPowerBiProjectFileName));
            }

            if (!string.IsNullOrWhiteSpace(DefaultPowerBiProjectAbsolutePath))
            {
                candidates.Add(DefaultPowerBiProjectAbsolutePath);
            }

            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string candidate in candidates)
            {
                if (string.IsNullOrWhiteSpace(candidate))
                {
                    continue;
                }

                string fullPath;
                try
                {
                    fullPath = Path.GetFullPath(candidate);
                }
                catch
                {
                    fullPath = candidate;
                }

                if (!seen.Add(fullPath))
                {
                    continue;
                }

                if (File.Exists(fullPath))
                {
                    return fullPath;
                }
            }

            return "";
        }

