        private void StartPowerBiRefreshPipeline(bool openPowerBiAfterRefresh)
        {
            if (_powerBiRefreshPipelinePending)
            {
                ShowStatus("Power BI: refresh pipeline is already running.");
                return;
            }

            _powerBiOpenProjectAfterRefreshPending = openPowerBiAfterRefresh;
            _powerBiRefreshPipelinePending = true;
            SetPowerBiExportSummary(
                openPowerBiAfterRefresh
                    ? "Refreshing Site Progress from Revit... Power BI project will open automatically."
                    : "Refreshing Site Progress from Revit...");
            ShowStatus(
                openPowerBiAfterRefresh
                    ? "Power BI: refreshing Site Progress from Revit. PBIP will open after export completes."
                    : "Power BI: refreshing Site Progress from Revit. Export to Excel/CSV will run automatically.");
            RequestSiteProgressRefresh(focusFilteredView: false);
        }

