        private void ExecutePowerBiRefreshPipelineFromCurrentRows()
        {
            string exportFolder = ResolvePowerBiPipelineExportFolder();
            string databaseFolder = GetDatabaseFolder();
            string excelPath = Path.Combine(databaseFolder, DefaultSiteProgressExcelFileName);
            string excelSummary;

            try
            {
                List<SiteProgressSummaryRow> combined = _siteProgressCombinedRows.ToList();
                List<SiteProgressSummaryRow> byBuilding = _siteProgressByBuildingRows.ToList();
                List<SiteProgressElementDetailRow> elementRows = _siteProgressElementRows.ToList();
                if (combined.Count == 0 && byBuilding.Count == 0 && elementRows.Count == 0)
                {
                    excelSummary = "Excel skipped: Site Progress rows are empty.";
                }
                else
                {
                    string excelDir = Path.GetDirectoryName(excelPath);
                    if (!string.IsNullOrWhiteSpace(excelDir))
                    {
                        Directory.CreateDirectory(excelDir);
                    }

                    ExportSiteProgressRowsToExcel(combined, byBuilding, elementRows, excelPath);
                    int totalExcelRows = combined.Count + byBuilding.Count + elementRows.Count;
                    excelSummary = "Excel updated: " + excelPath + " (" +
                                   totalExcelRows.ToString(CultureInfo.InvariantCulture) + " row(s)).";
                }
            }
            catch (Exception ex)
            {
                excelSummary = "Excel export failed: " + ex.Message;
            }

            SetPowerBiExportSummary("Exporting Power BI Site Progress + QS BOQ CSV files...");
            bool csvOk = TryExportPowerBiDataModelToFolder(exportFolder, out string csvSummary);
            bool mspOk = TryExportMsProjectSyncPackage(ResolveMsProjectSyncFolder(), out string mspSummary);

            string final = (csvOk && mspOk
                    ? "Power BI/MS Project refresh pipeline completed. "
                    : "Power BI/MS Project refresh pipeline completed with warnings. ") +
                excelSummary + " " + csvSummary +
                " " + mspSummary +
                " In Power BI Desktop, click Refresh.";

            if (_powerBiOpenProjectAfterRefreshPending)
            {
                _powerBiOpenProjectAfterRefreshPending = false;
                if (TryOpenPowerBiProjectFile(out string openMessage))
                {
                    final += " " + openMessage;
                }
                else
                {
                    final += " " + openMessage;
                }
            }

            SetPowerBiExportSummary(final);
            ShowStatus(final);
        }

        private bool TryOpenPowerBiProjectFile(out string message)
        {
            string projectPath = ResolvePowerBiProjectPath(out string expectedPath);
            if (string.IsNullOrWhiteSpace(projectPath))
            {
                message = "Power BI: project file not found. Expected: " + expectedPath;
                UpdatePowerBiRuntimeInfo();
                return false;
            }

            var normalizationMessages = new List<string>();

            if (!TryNormalizePowerBiSemanticModelEncoding(projectPath, out string normalizeEncodingMessage))
            {
                message = normalizeEncodingMessage;
                _powerBiLastSummaryMessage = message;
                _powerBiLastActionLocal = DateTime.Now;
                UpdatePowerBiRuntimeInfo();
                return false;
            }

            if (!string.IsNullOrWhiteSpace(normalizeEncodingMessage))
            {
                normalizationMessages.Add(normalizeEncodingMessage);
            }

            if (!TryNormalizePowerBiRelationshipReferences(projectPath, out string normalizeRelationshipMessage))
            {
                message = normalizeRelationshipMessage;
                _powerBiLastSummaryMessage = message;
                _powerBiLastActionLocal = DateTime.Now;
                UpdatePowerBiRuntimeInfo();
                return false;
            }

            if (!string.IsNullOrWhiteSpace(normalizeRelationshipMessage))
            {
                normalizationMessages.Add(normalizeRelationshipMessage);
            }

            string normalizeMessage = string.Join(" ", normalizationMessages.Where(x => !string.IsNullOrWhiteSpace(x)));

            try
            {
                Process.Start(new ProcessStartInfo
                {
                    FileName = projectPath,
                    UseShellExecute = true
                });
                message = string.IsNullOrWhiteSpace(normalizeMessage)
                    ? "Power BI project opened: " + projectPath
                    : normalizeMessage + " Power BI project opened: " + projectPath;
                _powerBiLastSummaryMessage = message;
                _powerBiLastActionLocal = DateTime.Now;
                UpdatePowerBiRuntimeInfo();
                return true;
            }
            catch (Exception ex)
            {
                message = "Power BI: failed to open project file. " + ex.Message;
                UpdatePowerBiRuntimeInfo();
                return false;
            }
        }

        private static bool TryNormalizePowerBiSemanticModelEncoding(string projectPath, out string message)
        {
            message = "";
            string semanticModelFolder = ResolvePowerBiSemanticModelFolder(projectPath);
            if (string.IsNullOrWhiteSpace(semanticModelFolder))
            {
                return true;
            }

            string[] tmdlFiles;
            try
            {
                tmdlFiles = Directory.GetFiles(semanticModelFolder, "*.tmdl", SearchOption.AllDirectories);
            }
            catch (Exception ex)
            {
                message = "Power BI: failed to scan SemanticModel files. " + ex.Message;
                return false;
            }

            if (tmdlFiles.Length == 0)
            {
                return true;
            }

            int normalizedCount = 0;
            var failedFiles = new List<string>();

            foreach (string file in tmdlFiles)
            {
                try
                {
                    byte[] bytes = File.ReadAllBytes(file);
                    if (!StartsWithUtf8Bom(bytes))
                    {
                        continue;
                    }

                    byte[] bytesWithoutBom = new byte[bytes.Length - Utf8BomBytes.Length];
                    Buffer.BlockCopy(bytes, Utf8BomBytes.Length, bytesWithoutBom, 0, bytesWithoutBom.Length);
                    File.WriteAllBytes(file, bytesWithoutBom);
                    normalizedCount++;
                }
                catch
                {
                    failedFiles.Add(file);
                }
            }

            if (failedFiles.Count > 0)
            {
                string sample = string.Join(
                    ", ",
                    failedFiles.Take(2).Select(Path.GetFileName).Where(name => !string.IsNullOrWhiteSpace(name)));
                string suffix = failedFiles.Count > 2 ? " (and more)." : ".";
                message = "Power BI: UTF-8 BOM was detected in SemanticModel files but could not be fixed. " +
                          (string.IsNullOrWhiteSpace(sample)
                              ? failedFiles.Count.ToString(CultureInfo.InvariantCulture) + " file(s) failed" + suffix
                              : "Failed file(s): " + sample + suffix);
                return false;
            }

            if (normalizedCount > 0)
            {
                message = "Power BI: removed UTF-8 BOM from " +
                          normalizedCount.ToString(CultureInfo.InvariantCulture) + " SemanticModel file(s).";
            }

            return true;
        }

        private static bool TryNormalizePowerBiRelationshipReferences(string projectPath, out string message)
        {
            message = "";
            string semanticModelFolder = ResolvePowerBiSemanticModelFolder(projectPath);
            if (string.IsNullOrWhiteSpace(semanticModelFolder))
            {
                return true;
            }

            string definitionFolder = Path.Combine(semanticModelFolder, "definition");
            string tablesFolder = Path.Combine(definitionFolder, "tables");
            string relationshipsPath = Path.Combine(definitionFolder, "relationships.tmdl");

            if (!Directory.Exists(tablesFolder) || !File.Exists(relationshipsPath))
            {
                return true;
            }

            HashSet<string> knownColumns;
            try
            {
                knownColumns = BuildPowerBiTableColumnReferenceSet(tablesFolder);
            }
            catch (Exception ex)
            {
                message = "Power BI: failed to read table columns for relationship validation. " + ex.Message;
                return false;
            }

            string[] lines;
            try
            {
                lines = File.ReadAllLines(relationshipsPath);
            }
            catch (Exception ex)
            {
                message = "Power BI: failed to read relationships definition. " + ex.Message;
                return false;
            }

            var blocks = new List<List<string>>();
            List<string> currentBlock = null;
            foreach (string line in lines)
            {
                if (line.TrimStart().StartsWith("relationship ", StringComparison.OrdinalIgnoreCase))
                {
                    if (currentBlock != null && currentBlock.Count > 0)
                    {
                        blocks.Add(currentBlock);
                    }

                    currentBlock = new List<string> { line };
                    continue;
                }

                currentBlock?.Add(line);
            }

            if (currentBlock != null && currentBlock.Count > 0)
            {
                blocks.Add(currentBlock);
            }

            if (blocks.Count == 0)
            {
                return true;
            }

            var keptBlocks = new List<string>();
            var removedRelationships = new List<string>();

            foreach (List<string> block in blocks)
            {
                string header = (block.Count > 0 ? block[0] : "").Trim();
                string relationshipName = header.StartsWith("relationship ", StringComparison.OrdinalIgnoreCase)
                    ? header.Substring("relationship ".Length).Trim()
                    : "";

                string fromColumn = ExtractRelationshipColumnReference(block, "fromColumn:");
                string toColumn = ExtractRelationshipColumnReference(block, "toColumn:");

                if (string.IsNullOrWhiteSpace(fromColumn) || string.IsNullOrWhiteSpace(toColumn))
                {
                    keptBlocks.Add(string.Join(Environment.NewLine, block).TrimEnd());
                    continue;
                }

                string normalizedFrom = NormalizeRelationshipColumnReference(fromColumn);
                string normalizedTo = NormalizeRelationshipColumnReference(toColumn);

                if (knownColumns.Contains(normalizedFrom) && knownColumns.Contains(normalizedTo))
                {
                    keptBlocks.Add(string.Join(Environment.NewLine, block).TrimEnd());
                }
                else
                {
                    removedRelationships.Add(
                        string.IsNullOrWhiteSpace(relationshipName) ? "(unnamed relationship)" : relationshipName);
                }
            }

            if (removedRelationships.Count == 0)
            {
                return true;
            }

            string normalizedContent = string.Join(
                Environment.NewLine + Environment.NewLine,
                keptBlocks.Where(x => !string.IsNullOrWhiteSpace(x)));

            if (!string.IsNullOrWhiteSpace(normalizedContent))
            {
                normalizedContent += Environment.NewLine;
            }

            try
            {
                File.WriteAllText(relationshipsPath, normalizedContent, new UTF8Encoding(false));
            }
            catch (Exception ex)
            {
                message = "Power BI: failed to update invalid relationships. " + ex.Message;
                return false;
            }

            string sample = string.Join(", ", removedRelationships.Take(3));
            message = "Power BI: removed " +
                      removedRelationships.Count.ToString(CultureInfo.InvariantCulture) +
                      " invalid relationship(s)" +
                      (string.IsNullOrWhiteSpace(sample)
                          ? "."
                          : ": " + sample + (removedRelationships.Count > 3 ? ", ..." : "."));
            return true;
        }

        private static string ResolvePowerBiSemanticModelFolder(string projectPath)
        {
            if (string.IsNullOrWhiteSpace(projectPath))
            {
                return "";
            }

            string projectFolder = Path.GetDirectoryName(projectPath);
            if (string.IsNullOrWhiteSpace(projectFolder) || !Directory.Exists(projectFolder))
            {
                return "";
            }

            string semanticModelFolder = Path.Combine(
                projectFolder,
                (Path.GetFileNameWithoutExtension(projectPath) ?? "Power BI Project") + ".SemanticModel");

            return Directory.Exists(semanticModelFolder) ? semanticModelFolder : "";
        }

        private static HashSet<string> BuildPowerBiTableColumnReferenceSet(string tablesFolder)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string[] tableFiles = Directory.GetFiles(tablesFolder, "*.tmdl", SearchOption.TopDirectoryOnly);
            foreach (string tableFile in tableFiles)
            {
                string[] lines = File.ReadAllLines(tableFile);
                string tableName = "";

                foreach (string line in lines)
                {
                    tableName = ExtractTmdlIdentifierAfterKeyword(line, "table ");
                    if (!string.IsNullOrWhiteSpace(tableName))
                    {
                        break;
                    }
                }

                if (string.IsNullOrWhiteSpace(tableName))
                {
                    continue;
                }

                foreach (string line in lines)
                {
                    string columnName = ExtractTmdlIdentifierAfterKeyword(line, "column ");
                    if (string.IsNullOrWhiteSpace(columnName))
                    {
                        continue;
                    }

                    result.Add(tableName + "." + columnName);
                }
            }

            return result;
        }

        private static string ExtractTmdlIdentifierAfterKeyword(string line, string keyword)
        {
            string trimmed = (line ?? "").Trim();
            if (string.IsNullOrWhiteSpace(trimmed) || string.IsNullOrWhiteSpace(keyword))
            {
                return "";
            }

            if (!trimmed.StartsWith(keyword, StringComparison.OrdinalIgnoreCase))
            {
                return "";
            }

            string rest = trimmed.Substring(keyword.Length).Trim();
            if (string.IsNullOrWhiteSpace(rest))
            {
                return "";
            }

            if (rest.StartsWith("'", StringComparison.Ordinal))
            {
                int endQuote = rest.IndexOf('\'', 1);
                if (endQuote > 1)
                {
                    return rest.Substring(1, endQuote - 1).Trim();
                }
            }

            int stopIndex = rest.IndexOfAny(new[] { ' ', '\t', '=' });
            if (stopIndex > 0)
            {
                rest = rest.Substring(0, stopIndex);
            }

            return rest.Trim().Trim('\'');
        }

        private static string ExtractRelationshipColumnReference(IEnumerable<string> blockLines, string key)
        {
            foreach (string line in blockLines ?? Enumerable.Empty<string>())
            {
                string trimmed = (line ?? "").Trim();
                if (trimmed.StartsWith(key, StringComparison.OrdinalIgnoreCase))
                {
                    return trimmed.Substring(key.Length).Trim();
                }
            }

            return "";
        }

        private static string NormalizeRelationshipColumnReference(string raw)
        {
            string value = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(value))
            {
                return "";
            }

            int dotIndex = value.LastIndexOf('.');
            if (dotIndex <= 0 || dotIndex >= value.Length - 1)
            {
                return value.Trim().Trim('\'', '[', ']');
            }

            string tableName = value.Substring(0, dotIndex).Trim().Trim('\'', '[', ']');
            string columnName = value.Substring(dotIndex + 1).Trim().Trim('\'', '[', ']');
            return tableName + "." + columnName;
        }

        private static bool StartsWithUtf8Bom(byte[] bytes)
        {
            return bytes != null &&
                   bytes.Length >= Utf8BomBytes.Length &&
                   bytes[0] == Utf8BomBytes[0] &&
                   bytes[1] == Utf8BomBytes[1] &&
                   bytes[2] == Utf8BomBytes[2];
        }

        private string ResolvePowerBiPipelineExportFolder()
        {
            string projectPath = ResolvePowerBiProjectPath(out _);
            if (!string.IsNullOrWhiteSpace(projectPath))
            {
                string projectFolder = Path.GetDirectoryName(projectPath);
                if (!string.IsNullOrWhiteSpace(projectFolder))
                {
                    return projectFolder;
                }
            }

            if (!string.IsNullOrWhiteSpace(_powerBiLastExportFolder))
            {
                return _powerBiLastExportFolder;
            }

            string databaseFolder = GetDatabaseFolder();
            if (string.IsNullOrWhiteSpace(databaseFolder))
            {
                return "";
            }

            return Path.Combine(databaseFolder, "Power BI");
        }

        private string BuildPowerBiAllElementsSummaryText()
        {
            List<SiteProgressElementDetailRow> items = (_siteProgressElementRows ?? new List<SiteProgressElementDetailRow>())
                .Where(r => r != null)
                .ToList();

            int elementCount;
            int buildingCount;
            int structureCount;
            int notStarted;
            int inProgress;
            int completed;
            double totalRebar;
            double completedRebar;
            double totalFormwork;
            double completedFormwork;
            double totalVolume;
            double completedVolume;
            string sourceText;

            if (items.Count > 0)
            {
                elementCount = items
                    .Select(r => r.ElementId)
                    .Where(id => id > 0)
                    .Distinct()
                    .Count();
                if (elementCount <= 0)
                {
                    elementCount = items.Count;
                }

                buildingCount = items
                    .Select(r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel.Trim())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count();
                structureCount = items
                    .Select(r => string.IsNullOrWhiteSpace(r.StructureElement) ? "Unassigned" : r.StructureElement.Trim())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count();

                notStarted = 0;
                inProgress = 0;
                completed = 0;
                foreach (SiteProgressElementDetailRow row in items)
                {
                    string status = (row.Status ?? "").Trim();
                    if (string.IsNullOrWhiteSpace(status))
                    {
                        double p = Math.Max(0.0, Math.Min(100.0, row.ProgressPercent));
                        status = p >= 99.999 ? "Completed" : (p <= 0.001 ? "Not Started" : "In Progress");
                    }

                    if (string.Equals(status, "Completed", StringComparison.OrdinalIgnoreCase))
                    {
                        completed++;
                    }
                    else if (string.Equals(status, "Not Started", StringComparison.OrdinalIgnoreCase))
                    {
                        notStarted++;
                    }
                    else
                    {
                        inProgress++;
                    }
                }

                totalRebar = items.Sum(r => Math.Max(0.0, r.ReinforcementKg));
                completedRebar = items.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.ReinforcementKg), r.ReinforcementCompletedKg)));
                totalFormwork = items.Sum(r => Math.Max(0.0, r.FormworkM2));
                completedFormwork = items.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.FormworkM2), r.FormworkCompletedM2)));
                totalVolume = items.Sum(r => Math.Max(0.0, r.VolumeM3));
                completedVolume = items.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.VolumeM3), r.VolumeCompletedM3)));
                sourceText = "Source: element detail rows";
            }
            else
            {
                List<SiteProgressSummaryRow> sourceRows = (_siteProgressCombinedSourceRows ?? new List<SiteProgressSummaryRow>())
                    .Where(r => r != null)
                    .ToList();
                if (sourceRows.Count == 0)
                {
                    return "All Elements Summary: no rows available. Click Refresh in Site Progress first.";
                }

                elementCount = sourceRows.Sum(r => Math.Max(0, r.ElementCount));
                buildingCount = sourceRows
                    .Select(r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel.Trim())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count();
                structureCount = sourceRows
                    .Select(r => string.IsNullOrWhiteSpace(r.StructureElement) ? "Unassigned" : r.StructureElement.Trim())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count();

                notStarted = 0;
                inProgress = 0;
                completed = 0;
                foreach (SiteProgressSummaryRow row in sourceRows)
                {
                    int qty = Math.Max(1, row.ElementCount);
                    string status = (row.Status ?? "").Trim();
                    if (string.IsNullOrWhiteSpace(status))
                    {
                        double p = Math.Max(0.0, Math.Min(100.0, row.ProgressPercent));
                        status = p >= 99.999 ? "Completed" : (p <= 0.001 ? "Not Started" : "In Progress");
                    }

                    if (string.Equals(status, "Completed", StringComparison.OrdinalIgnoreCase))
                    {
                        completed += qty;
                    }
                    else if (string.Equals(status, "Not Started", StringComparison.OrdinalIgnoreCase))
                    {
                        notStarted += qty;
                    }
                    else
                    {
                        inProgress += qty;
                    }
                }

                totalRebar = sourceRows.Sum(r => Math.Max(0.0, r.ReinforcementKg));
                completedRebar = sourceRows.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.ReinforcementKg), r.ReinforcementCompletedKg)));
                totalFormwork = sourceRows.Sum(r => Math.Max(0.0, r.FormworkM2));
                completedFormwork = sourceRows.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.FormworkM2), r.FormworkCompletedM2)));
                totalVolume = sourceRows.Sum(r => Math.Max(0.0, r.VolumeM3));
                completedVolume = sourceRows.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.VolumeM3), r.VolumeCompletedM3)));
                sourceText = "Source: summary rows (fallback)";
            }

            double remainingRebar = Math.Max(0.0, totalRebar - completedRebar);
            double remainingFormwork = Math.Max(0.0, totalFormwork - completedFormwork);
            double remainingVolume = Math.Max(0.0, totalVolume - completedVolume);

            double progressRebar = totalRebar > 1e-9 ? (completedRebar * 100.0 / totalRebar) : 0.0;
            double progressFormwork = totalFormwork > 1e-9 ? (completedFormwork * 100.0 / totalFormwork) : 0.0;
            double progressVolume = totalVolume > 1e-9 ? (completedVolume * 100.0 / totalVolume) : 0.0;

            progressRebar = Math.Max(0.0, Math.Min(100.0, progressRebar));
            progressFormwork = Math.Max(0.0, Math.Min(100.0, progressFormwork));
            progressVolume = Math.Max(0.0, Math.Min(100.0, progressVolume));

            string nl = Environment.NewLine;
            return "All Elements Summary (" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture) + ")" + nl +
                   sourceText + nl +
                   "Elements: " + elementCount.ToString(CultureInfo.InvariantCulture) +
                   " | Buildings: " + buildingCount.ToString(CultureInfo.InvariantCulture) +
                   " | Structures: " + structureCount.ToString(CultureInfo.InvariantCulture) + nl +
                   "Status: Not Started=" + notStarted.ToString(CultureInfo.InvariantCulture) +
                   " | In Progress=" + inProgress.ToString(CultureInfo.InvariantCulture) +
                   " | Completed=" + completed.ToString(CultureInfo.InvariantCulture) + nl +
                   "Rebar (kg): Total=" + totalRebar.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Completed=" + completedRebar.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Remaining=" + remainingRebar.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Progress=" + progressRebar.ToString("0.##", CultureInfo.InvariantCulture) + "%" + nl +
                   "Formwork (m2): Total=" + totalFormwork.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Completed=" + completedFormwork.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Remaining=" + remainingFormwork.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Progress=" + progressFormwork.ToString("0.##", CultureInfo.InvariantCulture) + "%" + nl +
                   "Volume (m3): Total=" + totalVolume.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Completed=" + completedVolume.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Remaining=" + remainingVolume.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Progress=" + progressVolume.ToString("0.##", CultureInfo.InvariantCulture) + "%";
        }

        private void OnPowerBiExportDataClick(object sender, RoutedEventArgs e)
        {
            string initialFolder = !string.IsNullOrWhiteSpace(_powerBiLastExportFolder) &&
                                   Directory.Exists(_powerBiLastExportFolder)
                ? _powerBiLastExportFolder
                : GetDatabaseFolder();

            string selectedFolder = "";
            using (var dialog = new System.Windows.Forms.FolderBrowserDialog())
            {
                dialog.Description = "Select a folder for Power BI CSV export";
                dialog.ShowNewFolderButton = true;
                dialog.SelectedPath = initialFolder;
                if (dialog.ShowDialog() != System.Windows.Forms.DialogResult.OK ||
                    string.IsNullOrWhiteSpace(dialog.SelectedPath))
                {
                    return;
                }

                selectedFolder = dialog.SelectedPath;
            }

            try
            {
                ShowStatus("Power BI: preparing data model export...");
                SetPowerBiExportSummary("Exporting Power BI Site Progress + QS BOQ CSV files...");
                TryExportPowerBiDataModelToFolder(selectedFolder, out string summary);
                ShowStatus(summary);
            }
            catch (Exception ex)
            {
                string msg = "Power BI export failed: " + ex.Message;
                SetPowerBiExportSummary(msg);
                ShowStatus(msg);
            }
        }

        private void OnExportMsProjectPackageClick(object sender, RoutedEventArgs e)
        {
            string folder = ResolveMsProjectSyncFolder();
            bool ok = TryExportMsProjectSyncPackage(folder, out string summary);
            SetPowerBiExportSummary(summary);
            ShowStatus(summary);
            if (!ok)
            {
                return;
            }

            UpdatePowerBiRuntimeInfo();
            RefreshPmDashboardProjectOptions();
            RefreshPmDashboardSummaryAndChart();
        }

        private void OnImportMsProjectProgressClick(object sender, RoutedEventArgs e)
        {
            string initialFolder = ResolveMsProjectSyncFolder();
            var dialog = new OpenFileDialog
            {
                Title = "Import MS Project Progress CSV",
                Filter = "CSV files (*.csv)|*.csv|All files (*.*)|*.*",
                Multiselect = false,
                CheckFileExists = true
            };

            if (Directory.Exists(initialFolder))
            {
                dialog.InitialDirectory = initialFolder;
            }

            bool? result = dialog.ShowDialog(this);
            if (result != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            try
            {
                List<SiteProgressImportRowPayload> rows = ReadMsProjectProgressRowsFromCsv(
                    dialog.FileName,
                    out int parsedRows,
                    out int skippedRows);

                if (rows.Count == 0)
                {
                    ShowStatus("MS Project import: no valid progress rows found.");
                    return;
                }

                _handler.Request.SiteProgressImportRows = rows;
                _handler.Request.SiteProgressScope = QsScope.EntireModel;
                _handler.Request.SiteProgressStructureFilter = SiteProgressFilterAll;
                _handler.Request.SiteProgressBuildingLevelFilter = SiteProgressFilterAll;
                _handler.Request.RequestType = CadToModelRequestType.ApplySiteProgressFromImport;
                _externalEvent.Raise();

                string message = "MS Project progress import queued: " +
                                 rows.Count.ToString(CultureInfo.InvariantCulture) +
                                 " row(s), parsed=" +
                                 parsedRows.ToString(CultureInfo.InvariantCulture) +
                                 ", skipped=" +
                                 skippedRows.ToString(CultureInfo.InvariantCulture) + ".";
                SetPowerBiExportSummary(message);
                ShowStatus(message);
            }
            catch (Exception ex)
            {
                string message = "MS Project import failed: " + ex.Message;
                SetPowerBiExportSummary(message);
                ShowStatus(message);
            }
        }

        private void OnOpenMsProjectDashboardClick(object sender, RoutedEventArgs e)
        {
            string dashboardPath = ResolveMsProjectDashboardPath(out string expectedPath);
            if (string.IsNullOrWhiteSpace(dashboardPath))
            {
                ShowStatus("MS Project dashboard not found. Expected: " + expectedPath);
                return;
            }

            string workingDir = Path.GetDirectoryName(dashboardPath) ?? "";
            string syncFolder = ResolveMsProjectSyncFolder();

            try
            {
                var info = new ProcessStartInfo
                {
                    FileName = dashboardPath,
                    UseShellExecute = true
                };

                if (!string.IsNullOrWhiteSpace(workingDir) && Directory.Exists(workingDir))
                {
                    info.WorkingDirectory = workingDir;
                }

                if (Directory.Exists(syncFolder))
                {
                    info.Arguments = "\"" + syncFolder + "\"";
                }

                Process.Start(info);
                ShowStatus("Opened CamboBIM Dashboard.");
            }
            catch (Exception ex)
            {
                ShowStatus("Failed to open CamboBIM Dashboard: " + ex.Message);
            }
        }

        private string ResolveMsProjectSyncFolder()
        {
            string databaseFolder = GetDatabaseFolder();
            if (string.IsNullOrWhiteSpace(databaseFolder))
            {
                return "";
            }

            return Path.Combine(databaseFolder, DefaultMsProjectSyncFolderName);
        }

        private string ResolveMsProjectDashboardPath(out string expectedPath)
        {
            string baseDir = AppDomain.CurrentDomain.BaseDirectory ?? "";
            var candidates = new List<string>();

            if (!string.IsNullOrWhiteSpace(DefaultMsProjectDashboardAbsolutePath))
            {
                candidates.Add(DefaultMsProjectDashboardAbsolutePath);
            }

            if (!string.IsNullOrWhiteSpace(baseDir))
            {
                candidates.Add(Path.Combine(baseDir, "PmDashboard", "CamboBIM_Dashboard.exe"));
                candidates.Add(Path.Combine(baseDir, "PmDashboard", "win-x64", "CamboBIM_Dashboard.exe"));
                candidates.Add(Path.Combine(baseDir, DefaultMsProjectDashboardRelativePath));
                candidates.Add(Path.GetFullPath(Path.Combine(baseDir, "..", "..", "..", "..", DefaultMsProjectDashboardRelativePath)));
                candidates.Add(Path.GetFullPath(Path.Combine(baseDir, "..", "..", "..", "MSP_Extension", "CamboBIM_Dashboard", "bin", "x64", "Release", "CamboBIM_Dashboard.exe")));
            }

            expectedPath = DefaultMsProjectDashboardAbsolutePath;
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string candidate in candidates)
            {
                if (string.IsNullOrWhiteSpace(candidate))
                {
                    continue;
                }

                string fullPath;
                try
                {
                    fullPath = Path.GetFullPath(candidate);
                }
                catch
                {
                    fullPath = candidate;
                }

                if (!seen.Add(fullPath))
                {
                    continue;
                }

                if (File.Exists(fullPath))
                {
                    return fullPath;
                }
            }

            return "";
        }

        private bool TryExportMsProjectSyncPackage(string folderPath, out string summary)
        {
            summary = "";
            try
            {
                if (string.IsNullOrWhiteSpace(folderPath))
                {
                    summary = "MS Project export failed: sync folder is not available.";
                    return false;
                }

                Directory.CreateDirectory(folderPath);

                DateTime snapshotUtc = DateTime.UtcNow;
                TryGetActiveMsProjectContext(out MsProjectActiveContext activeMsProjectContext);
                List<BoqTableRow> boqRows = (_boqAllRows ?? new List<BoqTableRow>())
                    .Where(r => r != null)
                    .Select(CloneBoqTableRowShallow)
                    .ToList();
                if (boqRows.Count == 0)
                {
                    boqRows = (_boqRows ?? new ObservableCollection<BoqTableRow>())
                        .Where(r => r != null)
                        .Select(CloneBoqTableRowShallow)
                        .ToList();
                }

                List<SiteProgressSummaryRow> summaryRows = (_siteProgressCombinedSourceRows ?? new List<SiteProgressSummaryRow>())
                    .Where(r => r != null)
                    .Select(CloneSiteProgressRowShallow)
                    .ToList();
                List<SiteProgressElementDetailRow> elementRows = (_siteProgressElementRows ?? new List<SiteProgressElementDetailRow>())
                    .Where(r => r != null)
                    .Select(CloneSiteProgressElementRowShallow)
                    .ToList();

                DataTable boqTable = BuildPowerBiQsBoqTable(boqRows, summaryRows, elementRows);
                DataTable summaryTable = BuildPowerBiSiteProgressSummaryFact(snapshotUtc, summaryRows);
                DataTable elementTable = BuildPowerBiSiteProgressElementFact(snapshotUtc, elementRows);
                DataTable importTemplate = BuildMsProjectProgressTemplateTable(boqTable);
                DataTable manifest = BuildMsProjectSyncManifestTable(
                    snapshotUtc,
                    boqTable.Rows.Count,
                    summaryTable.Rows.Count,
                    elementTable.Rows.Count,
                    importTemplate.Rows.Count,
                    activeMsProjectContext?.ProjectName ?? "",
                    activeMsProjectContext?.ProjectPath ?? "",
                    activeMsProjectContext?.DataDateLocal,
                    activeMsProjectContext?.DataDateSource ?? "");

                var files = new Dictionary<string, DataTable>(StringComparer.OrdinalIgnoreCase)
                {
                    ["msp_revit_boq.csv"] = boqTable,
                    ["msp_revit_site_progress_summary.csv"] = summaryTable,
                    ["msp_revit_site_progress_element.csv"] = elementTable,
                    ["msp_progress_import_template.csv"] = importTemplate,
                    [MsProjectManifestFileName] = manifest
                };

                int totalRows = 0;
                foreach (KeyValuePair<string, DataTable> file in files.OrderBy(f => f.Key, StringComparer.OrdinalIgnoreCase))
                {
                    string path = Path.Combine(folderPath, file.Key);
                    WriteDataTableToCsv(file.Value, path);
                    totalRows += file.Value?.Rows?.Count ?? 0;
                }

                summary = "MS Project sync package exported: " +
                          files.Count.ToString(CultureInfo.InvariantCulture) +
                          " file(s), " +
                          totalRows.ToString(CultureInfo.InvariantCulture) +
                          " row(s). Folder: " +
                          folderPath;

                if (activeMsProjectContext != null)
                {
                    if (!string.IsNullOrWhiteSpace(activeMsProjectContext.ProjectName))
                    {
                        summary += " Active MS Project: " + activeMsProjectContext.ProjectName + ".";
                    }

                    if (activeMsProjectContext.DataDateLocal.HasValue)
                    {
                        summary += " Data Date: " +
                                   activeMsProjectContext.DataDateLocal.Value.ToString("dd MMM yyyy", CultureInfo.InvariantCulture) +
                                   ".";
                    }
                }

                return true;
            }
            catch (Exception ex)
            {
                summary = "MS Project export failed: " + ex.Message;
                return false;
            }
        }

        private static DataTable BuildMsProjectProgressTemplateTable(DataTable boqTable)
        {
            var table = new DataTable("msp_progress_import_template");
            table.Columns.Add("task_key", typeof(string));
            table.Columns.Add("structure_element", typeof(string));
            table.Columns.Add("building_level", typeof(string));
            table.Columns.Add("type", typeof(string));
            table.Columns.Add("progress_reinforcement_pct", typeof(double));
            table.Columns.Add("progress_formwork_pct", typeof(double));
            table.Columns.Add("progress_volume_pct", typeof(double));
            table.Columns.Add("status", typeof(string));
            table.Columns.Add("notes", typeof(string));

            if (boqTable == null || boqTable.Rows.Count == 0)
            {
                return table;
            }

            foreach (DataRow row in boqTable.Rows)
            {
                if (row == null || row.RowState == DataRowState.Deleted)
                {
                    continue;
                }

                string structure = Convert.ToString(row["structure_element"], CultureInfo.InvariantCulture)?.Trim() ?? "";
                string level = Convert.ToString(row["building_level"], CultureInfo.InvariantCulture)?.Trim() ?? "";
                string type = Convert.ToString(row["type"], CultureInfo.InvariantCulture)?.Trim() ?? "";

                double rebarRatio = ConvertToDoubleSafe(row["progress_reinforcement_ratio"]);
                double formworkRatio = ConvertToDoubleSafe(row["progress_formwork_ratio"]);
                double volumeRatio = ConvertToDoubleSafe(row["progress_volume_ratio"]);

                DataRow output = table.NewRow();
                output["task_key"] = BuildBoqKey(structure, level, type);
                output["structure_element"] = structure;
                output["building_level"] = level;
                output["type"] = type;
                output["progress_reinforcement_pct"] = rebarRatio * 100.0;
                output["progress_formwork_pct"] = formworkRatio * 100.0;
                output["progress_volume_pct"] = volumeRatio * 100.0;
                output["status"] = Convert.ToString(row["status"], CultureInfo.InvariantCulture) ?? "";
                output["notes"] = "";
                table.Rows.Add(output);
            }

            return table;
        }

        private static DataTable BuildMsProjectSyncManifestTable(
            DateTime snapshotUtc,
            int boqRows,
            int summaryRows,
            int elementRows,
            int importTemplateRows,
            string projectName,
            string projectPath,
            DateTime? dataDateLocal,
            string dataDateSource)
        {
            var table = new DataTable("msp_sync_manifest");
            table.Columns.Add("key", typeof(string));
            table.Columns.Add("value", typeof(string));

            void Add(string key, string value)
            {
                DataRow row = table.NewRow();
                row["key"] = key ?? "";
                row["value"] = value ?? "";
                table.Rows.Add(row);
            }

            Add(MsProjectManifestSnapshotUtcKey, snapshotUtc.ToString("o", CultureInfo.InvariantCulture));
            Add(MsProjectManifestProjectNameKey, projectName ?? "");
            Add(MsProjectManifestProjectPathKey, projectPath ?? "");
            Add(MsProjectManifestDataDateKey,
                dataDateLocal.HasValue
                    ? dataDateLocal.Value.ToString("o", CultureInfo.InvariantCulture)
                    : "");
            Add(MsProjectManifestDataDateSourceKey, dataDateSource ?? "");
            Add("boq_rows", boqRows.ToString(CultureInfo.InvariantCulture));
            Add("site_progress_summary_rows", summaryRows.ToString(CultureInfo.InvariantCulture));
            Add("site_progress_element_rows", elementRows.ToString(CultureInfo.InvariantCulture));
            Add("import_template_rows", importTemplateRows.ToString(CultureInfo.InvariantCulture));

            return table;
        }

        private bool TryGetActiveMsProjectContext(out MsProjectActiveContext context)
        {
            context = null;
            object appObj = null;
            object projectObj = null;
            object summaryTaskObj = null;

            try
            {
                appObj = ComActiveObject.GetActiveObject(MsProjectApplicationProgId);
                if (appObj == null)
                {
                    return false;
                }

                dynamic app = appObj;
                projectObj = app.ActiveProject;
                if (projectObj == null)
                {
                    return false;
                }

                dynamic project = projectObj;
                string projectName = Convert.ToString(project.Name, CultureInfo.InvariantCulture) ?? "";
                string projectPath = Convert.ToString(project.FullName, CultureInfo.InvariantCulture) ?? "";
                string summaryTaskName = "";

                try
                {
                    summaryTaskObj = project.ProjectSummaryTask;
                    if (summaryTaskObj != null)
                    {
                        dynamic summaryTask = summaryTaskObj;
                        summaryTaskName = Convert.ToString(summaryTask.Name, CultureInfo.InvariantCulture) ?? "";
                    }
                }
                catch
                {
                    summaryTaskName = "";
                }

                var result = new MsProjectActiveContext
                {
                    ProjectPath = (projectPath ?? "").Trim(),
                    ProjectName = ResolveMsProjectDisplayName(summaryTaskName, projectName, projectPath)
                };

                object statusDateObj = null;
                try
                {
                    statusDateObj = project.StatusDate;
                    if (TryConvertComDateToLocal(statusDateObj, out DateTime statusDate))
                    {
                        result.DataDateLocal = statusDate;
                        result.DataDateSource = "status_date";
                    }
                }
                catch
                {
                    // Ignore and continue with fallback date sources.
                }
                finally
                {
                    SafeReleaseCom(statusDateObj);
                }

                if (!result.DataDateLocal.HasValue)
                {
                    object appDateObj = null;
                    try
                    {
                        appDateObj = app.Date;
                        if (TryConvertComDateToLocal(appDateObj, out DateTime appDate))
                        {
                            result.DataDateLocal = appDate;
                            result.DataDateSource = "application_date";
                        }
                    }
                    catch
                    {
                        // Keep null if no date can be captured from active MS Project.
                    }
                    finally
                    {
                        SafeReleaseCom(appDateObj);
                    }
                }

                context = result;
                return !string.IsNullOrWhiteSpace(result.ProjectName) || result.DataDateLocal.HasValue;
            }
            catch
            {
                return false;
            }
            finally
            {
                SafeReleaseCom(summaryTaskObj);
                SafeReleaseCom(projectObj);
                SafeReleaseCom(appObj);
            }
        }

        private static string ResolveMsProjectDisplayName(string summaryTaskName, string projectName, string projectPath)
        {
            string summary = (summaryTaskName ?? "").Trim();
            if (!string.IsNullOrWhiteSpace(summary))
            {
                return summary;
            }

            string name = (projectName ?? "").Trim();
            if (!string.IsNullOrWhiteSpace(name))
            {
                string fromName = Path.GetFileNameWithoutExtension(name);
                return string.IsNullOrWhiteSpace(fromName) ? name : fromName.Trim();
            }

            string path = (projectPath ?? "").Trim();
            if (!string.IsNullOrWhiteSpace(path))
            {
                string fromPath = Path.GetFileNameWithoutExtension(path);
                if (!string.IsNullOrWhiteSpace(fromPath))
                {
                    return fromPath.Trim();
                }
            }

            return "";
        }

        private static bool TryConvertComDateToLocal(object value, out DateTime dateLocal)
        {
            dateLocal = DateTime.MinValue;
            if (value == null || value == DBNull.Value)
            {
                return false;
            }

            try
            {
                if (value is DateTime dt)
                {
                    dateLocal = dt.Kind == DateTimeKind.Utc ? dt.ToLocalTime() : dt;
                    return true;
                }

                if (value is double oaDate && oaDate > 0.0)
                {
                    dateLocal = DateTime.FromOADate(oaDate);
                    return true;
                }

                if (value is float oaFloat && oaFloat > 0.0f)
                {
                    dateLocal = DateTime.FromOADate(oaFloat);
                    return true;
                }

                if (value is int oaInt && oaInt > 0)
                {
                    dateLocal = DateTime.FromOADate(oaInt);
                    return true;
                }

                if (value is decimal oaDecimal && oaDecimal > 0m)
                {
                    dateLocal = DateTime.FromOADate((double)oaDecimal);
                    return true;
                }

                string text = (Convert.ToString(value, CultureInfo.InvariantCulture) ?? "").Trim();
                if (string.IsNullOrWhiteSpace(text) ||
                    string.Equals(text, "NA", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(text, "N/A", StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }

                if (DateTimeOffset.TryParse(
                    text,
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.AssumeLocal,
                    out DateTimeOffset dto))
                {
                    dateLocal = dto.LocalDateTime;
                    return true;
                }

                if (DateTime.TryParse(
                    text,
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.AssumeLocal,
                    out dt))
                {
                    dateLocal = dt.Kind == DateTimeKind.Utc ? dt.ToLocalTime() : dt;
                    return true;
                }

                if (DateTime.TryParse(
                    text,
                    CultureInfo.CurrentCulture,
                    DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.AssumeLocal,
                    out dt))
                {
                    dateLocal = dt.Kind == DateTimeKind.Utc ? dt.ToLocalTime() : dt;
                    return true;
                }
            }
            catch
            {
                return false;
            }

            return false;
        }

        private static double ConvertToDoubleSafe(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return 0.0;
            }

            if (value is double d)
            {
                return d;
            }

            if (value is float f)
            {
                return f;
            }

            if (value is decimal m)
            {
                return (double)m;
            }

            if (value is int i)
            {
                return i;
            }

            if (value is long l)
            {
                return l;
            }

            string text = Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out d))
            {
                return d;
            }

            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out d))
            {
                return d;
            }

            return 0.0;
        }

        private static int ConvertToIntSafe(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return 0;
            }

            if (value is int i)
            {
                return i;
            }

            if (value is short s)
            {
                return s;
            }

            if (value is long l)
            {
                if (l > int.MaxValue) return int.MaxValue;
                if (l < int.MinValue) return int.MinValue;
                return (int)l;
            }

            if (value is double d)
            {
                if (double.IsNaN(d) || double.IsInfinity(d))
                {
                    return 0;
                }

                if (d > int.MaxValue) return int.MaxValue;
                if (d < int.MinValue) return int.MinValue;
                return Convert.ToInt32(Math.Round(d, MidpointRounding.AwayFromZero));
            }

            string text = Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
            if (int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out i))
            {
                return i;
            }

            if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out d))
            {
                if (d > int.MaxValue) return int.MaxValue;
                if (d < int.MinValue) return int.MinValue;
                return Convert.ToInt32(Math.Round(d, MidpointRounding.AwayFromZero));
            }

            return 0;
        }

        private static List<SiteProgressImportRowPayload> ReadMsProjectProgressRowsFromCsv(
            string path,
            out int parsedRows,
            out int skippedRows)
        {
            parsedRows = 0;
            skippedRows = 0;

            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                throw new FileNotFoundException("Progress CSV file not found.", path ?? "");
            }

            string[] lines = File.ReadAllLines(path);
            if (lines.Length == 0)
            {
                return new List<SiteProgressImportRowPayload>();
            }

            int headerIndex = Array.FindIndex(lines, line => !string.IsNullOrWhiteSpace(line));
            if (headerIndex < 0)
            {
                return new List<SiteProgressImportRowPayload>();
            }

            List<string> headers = ParseCsvLine(lines[headerIndex]);
            int idxStructure = IndexOfHeader(headers, "structure_element", "Structure Element", "structure", "element");
            int idxBuilding = IndexOfHeader(headers, "building_level", "Building Level", "level");
            int idxType = IndexOfHeader(headers, "type", "Type", "type_name");
            int idxRebar = IndexOfHeader(headers,
                "progress_reinforcement_pct",
                "rebar_progress_pct",
                "Rebar Progress %",
                "Site Progress Rebar %",
                "progress_reinforcement_ratio");
            int idxFormwork = IndexOfHeader(headers,
                "progress_formwork_pct",
                "formwork_progress_pct",
                "Formwork Progress %",
                "Site Progress Formwork %",
                "progress_formwork_ratio");
            int idxVolume = IndexOfHeader(headers,
                "progress_volume_pct",
                "volume_progress_pct",
                "Volume Progress %",
                "Site Progress Volume %",
                "progress_pct",
                "progress_volume_ratio");

            if (idxStructure < 0 || (idxRebar < 0 && idxFormwork < 0 && idxVolume < 0))
            {
                throw new InvalidOperationException(
                    "CSV must contain 'structure_element' and at least one progress column (rebar/formwork/volume).");
            }

            var rows = new List<SiteProgressImportRowPayload>();
            for (int i = headerIndex + 1; i < lines.Length; i++)
            {
                if (string.IsNullOrWhiteSpace(lines[i]))
                {
                    continue;
                }

                parsedRows++;
                List<string> cells = ParseCsvLine(lines[i]);
                string structure = ValueAt(cells, idxStructure);
                if (string.IsNullOrWhiteSpace(structure))
                {
                    skippedRows++;
                    continue;
                }

                bool hasRebar = TryReadImportedPercent(cells, idxRebar, out double? rebarPercent);
                bool hasFormwork = TryReadImportedPercent(cells, idxFormwork, out double? formworkPercent);
                bool hasVolume = TryReadImportedPercent(cells, idxVolume, out double? volumePercent);
                if (!hasRebar && !hasFormwork && !hasVolume)
                {
                    skippedRows++;
                    continue;
                }

                var row = new SiteProgressImportRowPayload
                {
                    StructureElement = structure,
                    BuildingLevel = ValueAt(cells, idxBuilding),
                    TypeName = ValueAt(cells, idxType),
                    ReinforcementPercent = rebarPercent,
                    FormworkPercent = formworkPercent,
                    VolumePercent = volumePercent
                };
                rows.Add(row);
            }

            return rows;
        }

        private static bool TryReadImportedPercent(IReadOnlyList<string> cells, int index, out double? percent)
        {
            percent = null;
            if (index < 0)
            {
                return false;
            }

            string raw = ValueAt(cells, index);
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            if (!TryParseImportedPercent(raw, out double parsed))
            {
                return false;
            }

            percent = Math.Max(0.0, Math.Min(100.0, parsed));
            return true;
        }

        private static bool TryParseImportedPercent(string raw, out double percent)
        {
            percent = 0.0;
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            bool hasPercentSymbol = text.IndexOf('%') >= 0;
            text = text.Replace("%", "").Trim();

            if (!double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out double value) &&
                !double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out value))
            {
                return false;
            }

            if (!hasPercentSymbol && value >= 0.0 && value <= 1.0)
            {
                value *= 100.0;
            }

            percent = value;
            return true;
        }

        private bool TryExportPowerBiDataModelToFolder(string selectedFolder, out string summary)
        {
            summary = "";
            try
            {
                if (string.IsNullOrWhiteSpace(selectedFolder))
                {
                    summary = "Power BI: export folder is not available.";
                    SetPowerBiExportSummary(summary);
                    return false;
                }

                Dictionary<string, DataTable> tables = BuildPowerBiExportTables(out string warning);
                if (tables.Count == 0)
                {
                    summary = "Power BI: no data available for export.";
                    SetPowerBiExportSummary(summary);
                    return false;
                }

                Directory.CreateDirectory(selectedFolder);
                RemovePowerBiLegacyCsvFiles(selectedFolder);
                int totalRows = 0;
                foreach (KeyValuePair<string, DataTable> kv in tables.OrderBy(k => k.Key, StringComparer.OrdinalIgnoreCase))
                {
                    string path = Path.Combine(selectedFolder, kv.Key);
                    WriteDataTableToCsv(kv.Value, path);
                    totalRows += kv.Value?.Rows?.Count ?? 0;
                }

                _powerBiLastExportFolder = selectedFolder;
                summary = "Power BI export completed: " +
                          tables.Count.ToString(CultureInfo.InvariantCulture) +
                          " file(s), " +
                          totalRows.ToString(CultureInfo.InvariantCulture) +
                          " row(s).";
                if (!string.IsNullOrWhiteSpace(warning))
                {
                    summary += " Warning: " + warning;
                }

                SetPowerBiExportSummary(summary + " Folder: " + selectedFolder);
                return true;
            }
            catch (Exception ex)
            {
                summary = "Power BI export failed: " + ex.Message;
                SetPowerBiExportSummary(summary);
                return false;
            }
        }

        private Dictionary<string, DataTable> BuildPowerBiExportTables(out string warning)
        {
            warning = "";
            DateTime snapshotUtc = DateTime.UtcNow;
            var warnings = new List<string>();
            var exportTables = new Dictionary<string, DataTable>(StringComparer.OrdinalIgnoreCase);

            List<SiteProgressElementDetailRow> elementRows = (_siteProgressElementRows ?? new List<SiteProgressElementDetailRow>())
                .Select(CloneSiteProgressElementRowShallow)
                .ToList();
            List<SiteProgressSummaryRow> summaryRows = (_siteProgressCombinedSourceRows ?? new List<SiteProgressSummaryRow>())
                .Select(CloneSiteProgressRowShallow)
                .ToList();
            List<BoqTableRow> boqRows = (_boqAllRows ?? new List<BoqTableRow>())
                .Select(CloneBoqTableRowShallow)
                .ToList();
            if (summaryRows.Count == 0 && elementRows.Count == 0)
            {
                warnings.Add("Site Progress rows are empty. Open Site Progress tab and run Refresh Summary before export.");
            }
            else if (elementRows.Count == 0)
            {
                warnings.Add("Element detail rows are empty. 3D bridge export will be empty; refresh Site Progress Entire Model.");
            }
            if (boqRows.Count == 0)
            {
                warnings.Add("QS BOQ rows are empty. Open QS TOOLS -> BOQ Table and click Refresh before export.");
            }

            exportTables["fact_site_progress_element.csv"] = BuildPowerBiSiteProgressElementFact(snapshotUtc, elementRows);
            exportTables["fact_site_progress_summary.csv"] = BuildPowerBiSiteProgressSummaryFact(snapshotUtc, summaryRows);
            exportTables["fact_site_progress_3d_bridge.csv"] = BuildPowerBiSiteProgress3DBridgeFact(snapshotUtc, elementRows);
            exportTables["site_progress_flat.csv"] = BuildPowerBiSiteProgressFlatTable(summaryRows, elementRows);
            exportTables["fact_qs_boq.csv"] = BuildPowerBiQsBoqTable(boqRows, summaryRows, elementRows);

            warning = string.Join(" | ", warnings.Where(w => !string.IsNullOrWhiteSpace(w)));
            return exportTables;
        }

        private static void RemovePowerBiLegacyCsvFiles(string folderPath)
        {
            if (string.IsNullOrWhiteSpace(folderPath) || !Directory.Exists(folderPath))
            {
                return;
            }

            foreach (string name in RemovedPowerBiLegacyCsvFiles)
            {
                if (string.IsNullOrWhiteSpace(name))
                {
                    continue;
                }

                string path = Path.Combine(folderPath, name);
                try
                {
                    if (File.Exists(path))
                    {
                        File.Delete(path);
                    }
                }
                catch
                {
                    // Ignore cleanup failures; active export files are still written.
                }
            }
        }

        private DataTable LoadPowerBiBoreySourceTable(string logicalTableName, out string warning)
        {
            warning = "";
            string logical = string.IsNullOrWhiteSpace(logicalTableName) ? "Project_Info" : logicalTableName.Trim();

            if (_boreyRevitTableCache.TryGetValue(logical, out DataTable cached) && cached != null)
            {
                try
                {
                    return SanitizePowerBiBoreySourceTable(cached.Copy());
                }
                catch
                {
                    // Fall back to DB query below.
                }
            }

            string dbPath = ResolveBoreyDbPathForTableCached(logical, out string physicalTableName);
            if (string.IsNullOrWhiteSpace(dbPath) || string.IsNullOrWhiteSpace(physicalTableName))
            {
                warning = logical + ": source DB table not found.";
                return CreateEmptyPowerBiBoreyTable(logical);
            }

            try
            {
                DataTable queried = QueryBoreyProjectedTable(
                    dbPath,
                    physicalTableName,
                    logical,
                    new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase));
                return SanitizePowerBiBoreySourceTable(queried);
            }
            catch (Exception ex)
            {
                warning = logical + ": failed to load source table (" + ex.Message + ").";
                return CreateEmptyPowerBiBoreyTable(logical);
            }
        }

        private static DataTable CreateEmptyPowerBiBoreyTable(string logicalTableName)
        {
            string logical = string.IsNullOrWhiteSpace(logicalTableName) ? "Project_Info" : logicalTableName.Trim();
            var table = new DataTable(logical);
            foreach (string column in GetBoreyLogicalColumns(logical))
            {
                if (!table.Columns.Contains(column))
                {
                    table.Columns.Add(column, typeof(string));
                }
            }

            return table;
        }

        private static DataTable BuildPowerBiBoreyFactTable(string logicalTableName, DataTable source, DateTime snapshotUtc)
        {
            var fact = new DataTable("fact_borey_" + NormalizePowerBiName(logicalTableName));
            fact.Columns.Add("snapshot_utc", typeof(string));
            fact.Columns.Add("source_table", typeof(string));
            fact.Columns.Add("house_key", typeof(string));

            var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "snapshot_utc",
                "source_table",
                "house_key"
            };
            var mapped = new List<KeyValuePair<DataColumn, string>>();
            if (source != null)
            {
                foreach (DataColumn col in source.Columns)
                {
                    string normalized = EnsureUniquePowerBiName(used, NormalizePowerBiName(col.ColumnName));
                    fact.Columns.Add(normalized, typeof(string));
                    mapped.Add(new KeyValuePair<DataColumn, string>(col, normalized));
                }

                foreach (DataRow row in source.Rows)
                {
                    if (row == null || row.RowState == DataRowState.Deleted)
                    {
                        continue;
                    }

                    if (IsPowerBiBoreyHeaderLikeRow(row, mapped.Select(m => m.Key)))
                    {
                        continue;
                    }

                    DataRow output = fact.NewRow();
                    output["snapshot_utc"] = snapshotUtc.ToString("o", CultureInfo.InvariantCulture);
                    output["source_table"] = logicalTableName ?? "";
                    output["house_key"] = ResolvePowerBiHouseKey(row);
                    foreach (KeyValuePair<DataColumn, string> map in mapped)
                    {
                        object value = row[map.Key];
                        string rawText = value == null || value == DBNull.Value
                            ? ""
                            : Convert.ToString(value, CultureInfo.InvariantCulture)?.Trim() ?? "";
                        output[map.Value] = NormalizePowerBiBoreyFactCell(map.Value, rawText);
                    }

                    fact.Rows.Add(output);
                }
            }

            return fact;
        }

        private static DataTable SanitizePowerBiBoreySourceTable(DataTable source)
        {
            if (source == null)
            {
                return null;
            }

            DataTable cleaned = source.Clone();
            List<DataColumn> columns = source.Columns.Cast<DataColumn>().ToList();
            foreach (DataRow row in source.Rows)
            {
                if (row == null || row.RowState == DataRowState.Deleted)
                {
                    continue;
                }

                if (IsPowerBiBoreyHeaderLikeRow(row, columns))
                {
                    continue;
                }

                DataRow newRow = cleaned.NewRow();
                foreach (DataColumn col in columns)
                {
                    object value = row[col];
                    if (value == null || value == DBNull.Value)
                    {
                        newRow[col.ColumnName] = DBNull.Value;
                    }
                    else if (value is string text)
                    {
                        newRow[col.ColumnName] = text.Trim();
                    }
                    else
                    {
                        newRow[col.ColumnName] = value;
                    }
                }

                cleaned.Rows.Add(newRow);
            }

            return cleaned;
        }

        private static bool IsPowerBiBoreyHeaderLikeRow(DataRow row, IEnumerable<DataColumn> columns)
        {
            if (row == null)
            {
                return true;
            }

            List<DataColumn> sourceColumns = (columns ?? Enumerable.Empty<DataColumn>()).ToList();
            if (sourceColumns.Count == 0)
            {
                return true;
            }

            int nonEmpty = 0;
            int headerMatches = 0;
            foreach (DataColumn col in sourceColumns)
            {
                if (col == null)
                {
                    continue;
                }

                object value = row[col];
                string text = value == null || value == DBNull.Value
                    ? ""
                    : Convert.ToString(value, CultureInfo.InvariantCulture)?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(text))
                {
                    continue;
                }

                nonEmpty++;
                string normalizedValue = NormalizePowerBiName(text);
                string normalizedColumn = NormalizePowerBiName(col.ColumnName);
                if (!string.IsNullOrWhiteSpace(normalizedValue) &&
                    !string.IsNullOrWhiteSpace(normalizedColumn) &&
                    string.Equals(normalizedValue, normalizedColumn, StringComparison.OrdinalIgnoreCase))
                {
                    headerMatches++;
                }
            }

            if (nonEmpty == 0)
            {
                return true;
            }

            int minMatchThreshold = Math.Max(3, (int)Math.Ceiling(sourceColumns.Count * 0.4));
            return headerMatches >= minMatchThreshold;
        }

        private static string NormalizePowerBiBoreyFactCell(string normalizedColumnName, string rawText)
        {
            string column = NormalizePowerBiName(normalizedColumnName ?? "");
            string value = (rawText ?? "").Trim();
            if (string.IsNullOrWhiteSpace(value))
            {
                return "";
            }

            if (!string.IsNullOrWhiteSpace(column))
            {
                string normalizedValue = NormalizePowerBiName(value);
                if (!string.IsNullOrWhiteSpace(normalizedValue) &&
                    string.Equals(normalizedValue, column, StringComparison.OrdinalIgnoreCase))
                {
                    return "";
                }
            }

            if (PowerBiBoreyDateColumns.Contains(column))
            {
                if (TryParsePowerBiDate(value, out DateTime parsedDate) ||
                    DateTime.TryParse(value, CultureInfo.InvariantCulture, DateTimeStyles.AssumeLocal, out parsedDate) ||
                    DateTime.TryParse(value, out parsedDate))
                {
                    return parsedDate.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
                }

                return "";
            }

            if (PowerBiBoreyIntegerColumns.Contains(column))
            {
                if (TryParsePowerBiNumeric(value, out double parsedInt))
                {
                    long rounded = (long)Math.Round(parsedInt, MidpointRounding.AwayFromZero);
                    return rounded.ToString(CultureInfo.InvariantCulture);
                }

                return "";
            }

            if (PowerBiBoreyNumberColumns.Contains(column))
            {
                if (TryParsePowerBiNumeric(value, out double parsedNumber))
                {
                    return parsedNumber.ToString("0.############################", CultureInfo.InvariantCulture);
                }

                return "";
            }

            return value;
        }

        private static bool TryParsePowerBiNumeric(string raw, out double value)
        {
            value = 0.0;
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out value))
            {
                return true;
            }

            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out value))
            {
                return true;
            }

            string withoutGrouping = text.Replace(",", "").Trim();
            if (double.TryParse(withoutGrouping, NumberStyles.Float, CultureInfo.InvariantCulture, out value))
            {
                return true;
            }

            if (text.Contains(",") && !text.Contains("."))
            {
                string commaAsDecimal = text.Replace(",", ".");
                if (double.TryParse(commaAsDecimal, NumberStyles.Float, CultureInfo.InvariantCulture, out value))
                {
                    return true;
                }
            }

            return false;
        }

        private static DataTable BuildPowerBiHouseDimension(IDictionary<string, DataTable> sourceByLogical)
        {
            var dim = new DataTable("dim_house");
            dim.Columns.Add("house_key", typeof(string));
            dim.Columns.Add("code_item", typeof(string));
            dim.Columns.Add("house_id", typeof(string));
            dim.Columns.Add("house_code", typeof(string));
            dim.Columns.Add("code", typeof(string));
            dim.Columns.Add("zone", typeof(string));
            dim.Columns.Add("block", typeof(string));
            dim.Columns.Add("sub_block", typeof(string));
            dim.Columns.Add("house_type", typeof(string));
            dim.Columns.Add("plan_description", typeof(string));
            dim.Columns.Add("handovered_status", typeof(string));
            dim.Columns.Add("source_tables", typeof(string));

            var rowsByHouseKey = new Dictionary<string, DataRow>(StringComparer.OrdinalIgnoreCase);
            if (sourceByLogical == null || sourceByLogical.Count == 0)
            {
                return dim;
            }

            foreach (KeyValuePair<string, DataTable> kv in sourceByLogical)
            {
                string sourceName = kv.Key ?? "";
                DataTable table = kv.Value;
                if (table == null)
                {
                    continue;
                }

                foreach (DataRow src in table.Rows)
                {
                    if (src == null || src.RowState == DataRowState.Deleted)
                    {
                        continue;
                    }

                    string houseKey = ResolvePowerBiHouseKey(src);
                    if (string.IsNullOrWhiteSpace(houseKey))
                    {
                        continue;
                    }

                    if (!rowsByHouseKey.TryGetValue(houseKey, out DataRow target))
                    {
                        target = dim.NewRow();
                        target["house_key"] = houseKey;
                        target["source_tables"] = sourceName;
                        dim.Rows.Add(target);
                        rowsByHouseKey[houseKey] = target;
                    }
                    else
                    {
                        string existingSource = Convert.ToString(target["source_tables"], CultureInfo.InvariantCulture) ?? "";
                        bool hasSource = existingSource
                            .Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries)
                            .Any(s => string.Equals(s.Trim(), sourceName, StringComparison.OrdinalIgnoreCase));
                        if (!hasSource)
                        {
                            target["source_tables"] = string.IsNullOrWhiteSpace(existingSource)
                                ? sourceName
                                : existingSource + ";" + sourceName;
                        }
                    }

                    MergePowerBiDimensionValue(target, "code_item", GetPowerBiSourceValue(src, "Code_Item"));
                    MergePowerBiDimensionValue(target, "house_id", GetPowerBiSourceValue(src, "HOUSE ID"));
                    MergePowerBiDimensionValue(target, "house_code", GetPowerBiSourceValue(src, "House Code"));
                    MergePowerBiDimensionValue(target, "code", GetPowerBiSourceValue(src, "Code"));
                    MergePowerBiDimensionValue(target, "zone", GetPowerBiSourceValue(src, "ZONE"));
                    MergePowerBiDimensionValue(target, "block", GetPowerBiSourceValue(src, "BLOCK"));
                    MergePowerBiDimensionValue(target, "sub_block", GetPowerBiSourceValue(src, "SUB-BLOCK"));
                    MergePowerBiDimensionValue(target, "house_type", GetPowerBiSourceValue(src, "HOUSE-TYPE"));
                    MergePowerBiDimensionValue(target, "plan_description", GetPowerBiSourceValue(src, "Plan Description"));
                    MergePowerBiDimensionValue(target, "handovered_status", GetPowerBiSourceValue(src, "HANDOVERED STATUS"));
                }
            }

            return dim;
        }

        private static DataTable BuildPowerBiDateDimension(DateTime snapshotUtc, IDictionary<string, DataTable> sourceByLogical)
        {
            var dim = new DataTable("dim_date");
            dim.Columns.Add("date_key", typeof(string));
            dim.Columns.Add("date", typeof(string));
            dim.Columns.Add("year", typeof(int));
            dim.Columns.Add("quarter", typeof(string));
            dim.Columns.Add("month_no", typeof(int));
            dim.Columns.Add("month_name", typeof(string));
            dim.Columns.Add("year_month", typeof(string));
            dim.Columns.Add("week_no", typeof(int));
            dim.Columns.Add("day_of_week", typeof(string));

            var dates = new SortedSet<DateTime>
            {
                snapshotUtc.Date
            };
            if (sourceByLogical != null)
            {
                foreach (DataTable table in sourceByLogical.Values)
                {
                    CollectPowerBiDatesFromTable(table, dates);
                }
            }

            foreach (DateTime date in dates.OrderBy(d => d))
            {
                DataRow row = dim.NewRow();
                row["date_key"] = date.ToString("yyyyMMdd", CultureInfo.InvariantCulture);
                row["date"] = date.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
                row["year"] = date.Year;
                row["quarter"] = "Q" + (((date.Month - 1) / 3) + 1).ToString(CultureInfo.InvariantCulture);
                row["month_no"] = date.Month;
                row["month_name"] = date.ToString("MMM", CultureInfo.InvariantCulture);
                row["year_month"] = date.ToString("yyyy-MM", CultureInfo.InvariantCulture);
                row["week_no"] = CultureInfo.InvariantCulture.Calendar.GetWeekOfYear(
                    date,
                    CalendarWeekRule.FirstFourDayWeek,
                    DayOfWeek.Monday);
                row["day_of_week"] = date.ToString("ddd", CultureInfo.InvariantCulture);
                dim.Rows.Add(row);
            }

            return dim;
        }

        private static DataTable BuildPowerBiSiteProgressElementFact(DateTime snapshotUtc, IEnumerable<SiteProgressElementDetailRow> rows)
        {
            var fact = new DataTable("fact_site_progress_element");
            fact.Columns.Add("snapshot_utc", typeof(string));
            fact.Columns.Add("element_id", typeof(int));
            fact.Columns.Add("unique_id", typeof(string));
            fact.Columns.Add("structural_plan", typeof(string));
            fact.Columns.Add("building_level", typeof(string));
            fact.Columns.Add("structure_element", typeof(string));
            fact.Columns.Add("category", typeof(string));
            fact.Columns.Add("family_name", typeof(string));
            fact.Columns.Add("type_name", typeof(string));
            fact.Columns.Add("reinforcement_kg", typeof(double));
            fact.Columns.Add("formwork_m2", typeof(double));
            fact.Columns.Add("volume_m3", typeof(double));
            fact.Columns.Add("reinforcement_percent", typeof(double));
            fact.Columns.Add("formwork_percent", typeof(double));
            fact.Columns.Add("volume_percent", typeof(double));
            fact.Columns.Add("reinforcement_completed_kg", typeof(double));
            fact.Columns.Add("formwork_completed_m2", typeof(double));
            fact.Columns.Add("volume_completed_m3", typeof(double));
            fact.Columns.Add("progress_percent", typeof(double));
            fact.Columns.Add("status", typeof(string));

            foreach (SiteProgressElementDetailRow item in rows ?? Enumerable.Empty<SiteProgressElementDetailRow>())
            {
                if (item == null)
                {
                    continue;
                }

                DataRow row = fact.NewRow();
                row["snapshot_utc"] = snapshotUtc.ToString("o", CultureInfo.InvariantCulture);
                row["element_id"] = item.ElementId;
