        private static DataTable BuildPowerBiSiteProgress3DBridgeFact(DateTime snapshotUtc, IEnumerable<SiteProgressElementDetailRow> rows)
        {
            var fact = new DataTable("fact_site_progress_3d_bridge");
            fact.Columns.Add("snapshot_utc", typeof(string));
            fact.Columns.Add("element_id", typeof(int));
            fact.Columns.Add("element_id_text", typeof(string));
            fact.Columns.Add("unique_id", typeof(string));
            fact.Columns.Add("application_id", typeof(string));
            fact.Columns.Add("object_id", typeof(string));
            fact.Columns.Add("building_level", typeof(string));
            fact.Columns.Add("structure_element", typeof(string));
            fact.Columns.Add("category", typeof(string));
            fact.Columns.Add("family_name", typeof(string));
            fact.Columns.Add("type_name", typeof(string));
            fact.Columns.Add("status", typeof(string));
            fact.Columns.Add("progress_ratio", typeof(double));
            fact.Columns.Add("progress_percent", typeof(double));
            fact.Columns.Add("progress_color_hex", typeof(string));
            fact.Columns.Add("reinforcement_kg", typeof(double));
            fact.Columns.Add("formwork_m2", typeof(double));
            fact.Columns.Add("volume_m3", typeof(double));
            fact.Columns.Add("reinforcement_completed_kg", typeof(double));
            fact.Columns.Add("formwork_completed_m2", typeof(double));
            fact.Columns.Add("volume_completed_m3", typeof(double));
            fact.Columns.Add("reinforcement_remaining_kg", typeof(double));
            fact.Columns.Add("formwork_remaining_m2", typeof(double));
            fact.Columns.Add("volume_remaining_m3", typeof(double));
            fact.Columns.Add("rebar_progress_ratio", typeof(double));
            fact.Columns.Add("formwork_progress_ratio", typeof(double));
            fact.Columns.Add("volume_progress_ratio", typeof(double));

            foreach (SiteProgressElementDetailRow item in rows ?? Enumerable.Empty<SiteProgressElementDetailRow>())
            {
                if (item == null)
                {
                    continue;
                }

                double totalRebar = Math.Max(0.0, item.ReinforcementKg);
                double totalFormwork = Math.Max(0.0, item.FormworkM2);
                double totalVolume = Math.Max(0.0, item.VolumeM3);

                double completedRebar = Math.Max(0.0, Math.Min(totalRebar, item.ReinforcementCompletedKg));
                double completedFormwork = Math.Max(0.0, Math.Min(totalFormwork, item.FormworkCompletedM2));
                double completedVolume = Math.Max(0.0, Math.Min(totalVolume, item.VolumeCompletedM3));

                double rebarRatio = ResolvePowerBiProgressRatio(completedRebar, totalRebar, item.SiteProgressReinforcementPercent);
                double formworkRatio = ResolvePowerBiProgressRatio(completedFormwork, totalFormwork, item.SiteProgressFormworkPercent);
                double volumeRatio = ResolvePowerBiProgressRatio(completedVolume, totalVolume, item.SiteProgressVolumePercent);
                double progressRatio = NormalizePowerBiProgressRatio((rebarRatio + formworkRatio + volumeRatio) / 3.0);

                string status = string.IsNullOrWhiteSpace(item.Status)
                    ? BuildPowerBiSiteProgressStatus(rebarRatio, formworkRatio, volumeRatio)
                    : item.Status.Trim();

                string progressColorHex = GetPowerBiProgressColorHex(progressRatio, status);
                int elementId = Math.Max(0, item.ElementId);
                string elementIdText = elementId > 0
                    ? elementId.ToString(CultureInfo.InvariantCulture)
                    : "";
                string uniqueId = (item.UniqueId ?? "").Trim();

                DataRow row = fact.NewRow();
                row["snapshot_utc"] = snapshotUtc.ToString("o", CultureInfo.InvariantCulture);
                row["element_id"] = elementId;
                row["element_id_text"] = elementIdText;
                row["unique_id"] = uniqueId;
                row["application_id"] = uniqueId;
                row["object_id"] = "";
                row["building_level"] = item.BuildingLevel ?? "";
                row["structure_element"] = item.StructureElement ?? "";
                row["category"] = item.Category ?? "";
                row["family_name"] = item.FamilyName ?? "";
                row["type_name"] = item.TypeName ?? "";
                row["status"] = status;
                row["progress_ratio"] = progressRatio;
                row["progress_percent"] = progressRatio * 100.0;
                row["progress_color_hex"] = progressColorHex;
                row["reinforcement_kg"] = totalRebar;
                row["formwork_m2"] = totalFormwork;
                row["volume_m3"] = totalVolume;
                row["reinforcement_completed_kg"] = completedRebar;
                row["formwork_completed_m2"] = completedFormwork;
                row["volume_completed_m3"] = completedVolume;
                row["reinforcement_remaining_kg"] = Math.Max(0.0, totalRebar - completedRebar);
                row["formwork_remaining_m2"] = Math.Max(0.0, totalFormwork - completedFormwork);
                row["volume_remaining_m3"] = Math.Max(0.0, totalVolume - completedVolume);
                row["rebar_progress_ratio"] = rebarRatio;
                row["formwork_progress_ratio"] = formworkRatio;
                row["volume_progress_ratio"] = volumeRatio;
                fact.Rows.Add(row);
            }

            return fact;
        }

        private static string GetPowerBiProgressColorHex(double progressRatio, string status)
        {
            string normalizedStatus = (status ?? "").Trim();
            if (string.Equals(normalizedStatus, "Completed", StringComparison.OrdinalIgnoreCase) || progressRatio >= 0.9999)
            {
                return "#2E7D32";
            }

            if (string.Equals(normalizedStatus, "Not Started", StringComparison.OrdinalIgnoreCase) || progressRatio <= 1e-9)
            {
                return "#5D6D7E";
            }

            if (progressRatio < 0.5)
            {
                return "#C62828";
            }

            if (progressRatio < 0.8)
            {
                return "#F28C28";
            }

            return "#2E7D32";
        }

        private static DataTable BuildPowerBiSiteProgressFlatTable(
            IEnumerable<SiteProgressSummaryRow> summaryRows,
            IEnumerable<SiteProgressElementDetailRow> elementRows)
        {
            var flat = new DataTable("site_progress_flat");
            flat.Columns.Add("building_level", typeof(string));
            flat.Columns.Add("structure_element", typeof(string));
            flat.Columns.Add("type", typeof(string));
            flat.Columns.Add("element_qty", typeof(int));
            flat.Columns.Add("boq_reinforcement_kg", typeof(double));
            flat.Columns.Add("boq_formwork_m2", typeof(double));
            flat.Columns.Add("boq_volume_m3", typeof(double));
            flat.Columns.Add("site_progress_reinforcement_pct", typeof(double));
            flat.Columns.Add("site_progress_formwork_pct", typeof(double));
            flat.Columns.Add("site_progress_volume_pct", typeof(double));
            flat.Columns.Add("boq_completed_reinforcement_kg", typeof(double));
            flat.Columns.Add("boq_completed_formwork_m2", typeof(double));
            flat.Columns.Add("boq_completed_volume_m3", typeof(double));
            flat.Columns.Add("status", typeof(string));

            List<SiteProgressSummaryRow> summaries = (summaryRows ?? Enumerable.Empty<SiteProgressSummaryRow>())
                .Where(r => r != null)
                .ToList();

            if (summaries.Count > 0)
            {
                foreach (SiteProgressSummaryRow item in summaries)
                {
                    DataRow row = flat.NewRow();
                    row["building_level"] = item.BuildingLevel ?? "";
                    row["structure_element"] = item.StructureElement ?? "";
                    row["type"] = item.TypeName ?? "";
                    row["element_qty"] = Math.Max(0, item.ElementCount);
                    row["boq_reinforcement_kg"] = Math.Max(0.0, item.ReinforcementKg);
                    row["boq_formwork_m2"] = Math.Max(0.0, item.FormworkM2);
                    row["boq_volume_m3"] = Math.Max(0.0, item.VolumeM3);
                    double pReinf = ResolvePowerBiProgressRatio(item.ReinforcementCompletedKg, item.ReinforcementKg, item.SiteProgressReinforcementPercent);
                    double pForm = ResolvePowerBiProgressRatio(item.FormworkCompletedM2, item.FormworkM2, item.SiteProgressFormworkPercent);
                    double pVol = ResolvePowerBiProgressRatio(item.VolumeCompletedM3, item.VolumeM3, item.SiteProgressVolumePercent);
                    row["site_progress_reinforcement_pct"] = pReinf;
                    row["site_progress_formwork_pct"] = pForm;
                    row["site_progress_volume_pct"] = pVol;
                    row["boq_completed_reinforcement_kg"] = Math.Max(0.0, item.ReinforcementCompletedKg);
                    row["boq_completed_formwork_m2"] = Math.Max(0.0, item.FormworkCompletedM2);
                    row["boq_completed_volume_m3"] = Math.Max(0.0, item.VolumeCompletedM3);
                    row["status"] = string.IsNullOrWhiteSpace(item.Status)
                        ? BuildPowerBiSiteProgressStatus(pReinf, pForm, pVol)
                        : item.Status.Trim();
                    flat.Rows.Add(row);
                }

                return flat;
            }

            var grouped = (elementRows ?? Enumerable.Empty<SiteProgressElementDetailRow>())
                .Where(r => r != null)
                .GroupBy(
                    r => new
                    {
                        BuildingLevel = r.BuildingLevel ?? "",
                        StructureElement = r.StructureElement ?? "",
                        TypeName = r.TypeName ?? ""
                    })
                .OrderBy(g => g.Key.StructureElement, StringComparer.OrdinalIgnoreCase)
                .ThenBy(g => g.Key.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                .ThenBy(g => g.Key.TypeName, StringComparer.OrdinalIgnoreCase);

            foreach (var group in grouped)
            {
                List<SiteProgressElementDetailRow> items = group.ToList();
                if (items.Count == 0)
                {
                    continue;
                }

                double boqReinf = items.Sum(x => Math.Max(0.0, x.ReinforcementKg));
                double boqForm = items.Sum(x => Math.Max(0.0, x.FormworkM2));
                double boqVol = items.Sum(x => Math.Max(0.0, x.VolumeM3));
                double completedReinf = items.Sum(x => Math.Max(0.0, x.ReinforcementCompletedKg));
                double completedForm = items.Sum(x => Math.Max(0.0, x.FormworkCompletedM2));
                double completedVol = items.Sum(x => Math.Max(0.0, x.VolumeCompletedM3));

                double pReinf = ResolvePowerBiProgressRatio(completedReinf, boqReinf, items.Average(x => x.SiteProgressReinforcementPercent));
                double pForm = ResolvePowerBiProgressRatio(completedForm, boqForm, items.Average(x => x.SiteProgressFormworkPercent));
                double pVol = ResolvePowerBiProgressRatio(completedVol, boqVol, items.Average(x => x.SiteProgressVolumePercent));

                SiteProgressElementDetailRow first = items[0];
                DataRow row = flat.NewRow();
                row["building_level"] = first.BuildingLevel ?? "";
                row["structure_element"] = first.StructureElement ?? "";
                row["type"] = first.TypeName ?? "";
                row["element_qty"] = items.Count;
                row["boq_reinforcement_kg"] = boqReinf;
                row["boq_formwork_m2"] = boqForm;
                row["boq_volume_m3"] = boqVol;
                row["site_progress_reinforcement_pct"] = pReinf;
                row["site_progress_formwork_pct"] = pForm;
                row["site_progress_volume_pct"] = pVol;
                row["boq_completed_reinforcement_kg"] = completedReinf;
                row["boq_completed_formwork_m2"] = completedForm;
                row["boq_completed_volume_m3"] = completedVol;
                row["status"] = BuildPowerBiSiteProgressStatus(pReinf, pForm, pVol);
                flat.Rows.Add(row);
            }

            return flat;
        }

        private static DataTable BuildPowerBiQsBoqTable(
            IEnumerable<BoqTableRow> boqRows,
            IEnumerable<SiteProgressSummaryRow> summaryRows,
            IEnumerable<SiteProgressElementDetailRow> elementRows)
        {
            var table = new DataTable("fact_qs_boq");
            table.Columns.Add("building_level", typeof(string));
            table.Columns.Add("room", typeof(string));
            table.Columns.Add("structure_element", typeof(string));
            table.Columns.Add("type", typeof(string));
            table.Columns.Add("qs_rule_code", typeof(string));
            table.Columns.Add("qs_formula", typeof(string));
            table.Columns.Add("qs_breakdown", typeof(string));
            table.Columns.Add("qty", typeof(int));
            table.Columns.Add("boq_reinforcement_kg", typeof(double));
            table.Columns.Add("boq_formwork_m2", typeof(double));
            table.Columns.Add("boq_volume_m3", typeof(double));
            table.Columns.Add("progress_reinforcement_ratio", typeof(double));
            table.Columns.Add("progress_formwork_ratio", typeof(double));
            table.Columns.Add("progress_volume_ratio", typeof(double));
            table.Columns.Add("completed_qty", typeof(double));
            table.Columns.Add("completed_reinforcement_kg", typeof(double));
            table.Columns.Add("completed_formwork_m2", typeof(double));
            table.Columns.Add("completed_volume_m3", typeof(double));
            table.Columns.Add("status", typeof(string));

            List<BoqTableRow> boqSource = (boqRows ?? Enumerable.Empty<BoqTableRow>())
                .Where(r => r != null)
                .ToList();

            if (boqSource.Count == 0)
            {
                boqSource = (summaryRows ?? Enumerable.Empty<SiteProgressSummaryRow>())
                    .Where(r => r != null)
                    .GroupBy(r => BuildPowerBiBoqKey(r.StructureElement, r.BuildingLevel, r.TypeName), StringComparer.OrdinalIgnoreCase)
                    .Select(g =>
                    {
                        SiteProgressSummaryRow first = g.First();
                        return new BoqTableRow
                        {
                            StructureElement = first.StructureElement ?? "",
                            BuildingLevel = first.BuildingLevel ?? "",
                            TypeName = first.TypeName ?? "",
                            Quantity = g.Sum(x => Math.Max(0, x.ElementCount)),
                            TotalVolumeM3 = g.Sum(x => Math.Max(0.0, x.VolumeM3)),
                            TotalFormworkAreaM2 = g.Sum(x => Math.Max(0.0, x.FormworkM2)),
                            StructureOrder = GetSiteProgressStructureOrder(first.StructureElement)
                        };
                    })
                    .OrderBy(r => r.StructureOrder)
                    .ThenBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(r => r.TypeName, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }

            var progressByType = new Dictionary<string, PowerBiBoqProgressAggregate>(StringComparer.OrdinalIgnoreCase);
            var progressByLevel = new Dictionary<string, PowerBiBoqProgressAggregate>(StringComparer.OrdinalIgnoreCase);
            var progressByStructure = new Dictionary<string, PowerBiBoqProgressAggregate>(StringComparer.OrdinalIgnoreCase);

            foreach (SiteProgressSummaryRow row in summaryRows ?? Enumerable.Empty<SiteProgressSummaryRow>())
            {
                if (row == null)
                {
                    continue;
                }

                double boqRebar = Math.Max(0.0, row.ReinforcementKg);
                double boqForm = Math.Max(0.0, row.FormworkM2);
                double boqVol = Math.Max(0.0, row.VolumeM3);
                double doneRebar = Math.Max(0.0, row.ReinforcementCompletedKg);
                double doneForm = Math.Max(0.0, row.FormworkCompletedM2);
                double doneVol = Math.Max(0.0, row.VolumeCompletedM3);

                AddPowerBiBoqProgress(
                    progressByType,
                    BuildPowerBiBoqKey(row.StructureElement, row.BuildingLevel, row.TypeName),
                    boqRebar,
                    doneRebar,
                    boqForm,
                    doneForm,
                    boqVol,
                    doneVol);
                AddPowerBiBoqProgress(
                    progressByLevel,
                    BuildPowerBiBoqLevelKey(row.StructureElement, row.BuildingLevel),
                    boqRebar,
                    doneRebar,
                    boqForm,
                    doneForm,
                    boqVol,
                    doneVol);
                AddPowerBiBoqProgress(
                    progressByStructure,
                    BuildPowerBiBoqStructureKey(row.StructureElement),
                    boqRebar,
                    doneRebar,
                    boqForm,
                    doneForm,
                    boqVol,
                    doneVol);
            }

            if (progressByType.Count == 0)
            {
                foreach (SiteProgressElementDetailRow row in elementRows ?? Enumerable.Empty<SiteProgressElementDetailRow>())
                {
                    if (row == null)
                    {
                        continue;
                    }

                    double boqRebar = Math.Max(0.0, row.ReinforcementKg);
                    double boqForm = Math.Max(0.0, row.FormworkM2);
                    double boqVol = Math.Max(0.0, row.VolumeM3);
                    double doneRebar = Math.Max(0.0, row.ReinforcementCompletedKg);
                    double doneForm = Math.Max(0.0, row.FormworkCompletedM2);
                    double doneVol = Math.Max(0.0, row.VolumeCompletedM3);

                    AddPowerBiBoqProgress(
                        progressByType,
                        BuildPowerBiBoqKey(row.StructureElement, row.BuildingLevel, row.TypeName),
                        boqRebar,
                        doneRebar,
                        boqForm,
                        doneForm,
                        boqVol,
                        doneVol);
                    AddPowerBiBoqProgress(
                        progressByLevel,
                        BuildPowerBiBoqLevelKey(row.StructureElement, row.BuildingLevel),
                        boqRebar,
                        doneRebar,
                        boqForm,
                        doneForm,
                        boqVol,
                        doneVol);
                    AddPowerBiBoqProgress(
                        progressByStructure,
                        BuildPowerBiBoqStructureKey(row.StructureElement),
                        boqRebar,
                        doneRebar,
                        boqForm,
                        doneForm,
                        boqVol,
                        doneVol);
                }
            }

            foreach (BoqTableRow row in boqSource)
            {
                if (row == null)
                {
                    continue;
                }

                string structure = (row.StructureElement ?? "").Trim();
                string level = (row.BuildingLevel ?? "").Trim();
                string room = (row.Room ?? "").Trim();
                string type = (row.TypeName ?? "").Trim();
                int qty = Math.Max(0, row.Quantity);
                double boqRebar = 0.0;
                double boqForm = Math.Max(0.0, row.TotalFormworkAreaM2);
                double boqVol = Math.Max(0.0, row.TotalVolumeM3);

                progressByType.TryGetValue(BuildPowerBiBoqKey(structure, level, type), out PowerBiBoqProgressAggregate progress);
                if (progress == null)
                {
                    progressByLevel.TryGetValue(BuildPowerBiBoqLevelKey(structure, level), out progress);
                }
                if (progress == null)
                {
                    progressByStructure.TryGetValue(BuildPowerBiBoqStructureKey(structure), out progress);
                }

                double pRebar = 0.0;
                double pForm = 0.0;
                double pVol = 0.0;
                if (progress != null)
                {
                    pRebar = ResolvePowerBiProgressRatio(progress.CompletedRebarKg, progress.BoqRebarKg, 0.0);
                    pForm = ResolvePowerBiProgressRatio(progress.CompletedFormworkM2, progress.BoqFormworkM2, 0.0);
                    pVol = ResolvePowerBiProgressRatio(progress.CompletedVolumeM3, progress.BoqVolumeM3, 0.0);
                }

                double completedRebar = boqRebar * pRebar;
                double completedForm = boqForm * pForm;
                double completedVolume = boqVol * pVol;

                var qtyRatios = new List<double>(3);
                if (boqRebar > 1e-9) qtyRatios.Add(pRebar);
                if (boqForm > 1e-9) qtyRatios.Add(pForm);
                if (boqVol > 1e-9) qtyRatios.Add(pVol);
                if (qtyRatios.Count == 0 && progress != null)
                {
                    qtyRatios.Add(pRebar);
                    qtyRatios.Add(pForm);
                    qtyRatios.Add(pVol);
                }

                double qtyRatio = qtyRatios.Count > 0
                    ? NormalizePowerBiProgressRatio(qtyRatios.Average())
                    : 0.0;
                double completedQty = qty * qtyRatio;

                DataRow output = table.NewRow();
                output["building_level"] = level;
                output["room"] = room;
                output["structure_element"] = structure;
                output["type"] = type;
                output["qs_rule_code"] = row.QsRuleCode ?? "";
                output["qs_formula"] = row.QsFormula ?? "";
                output["qs_breakdown"] = row.QsBreakdown ?? "";
                output["qty"] = qty;
                output["boq_reinforcement_kg"] = boqRebar;
                output["boq_formwork_m2"] = boqForm;
                output["boq_volume_m3"] = boqVol;
                output["progress_reinforcement_ratio"] = pRebar;
                output["progress_formwork_ratio"] = pForm;
                output["progress_volume_ratio"] = pVol;
                output["completed_qty"] = completedQty;
                output["completed_reinforcement_kg"] = completedRebar;
                output["completed_formwork_m2"] = completedForm;
                output["completed_volume_m3"] = completedVolume;
                output["status"] = BuildPowerBiSiteProgressStatus(pRebar, pForm, pVol);
                table.Rows.Add(output);
            }

            return table;
        }

        private sealed class PowerBiBoqProgressAggregate
        {
            public double BoqRebarKg { get; set; }
            public double CompletedRebarKg { get; set; }
            public double BoqFormworkM2 { get; set; }
            public double CompletedFormworkM2 { get; set; }
            public double BoqVolumeM3 { get; set; }
            public double CompletedVolumeM3 { get; set; }
        }

        private static void AddPowerBiBoqProgress(
            IDictionary<string, PowerBiBoqProgressAggregate> map,
            string key,
            double boqRebar,
            double completedRebar,
            double boqForm,
            double completedForm,
            double boqVolume,
            double completedVolume)
        {
            if (map == null || string.IsNullOrWhiteSpace(key))
            {
                return;
            }

            if (!map.TryGetValue(key, out PowerBiBoqProgressAggregate item))
            {
                item = new PowerBiBoqProgressAggregate();
                map[key] = item;
            }

            item.BoqRebarKg += Math.Max(0.0, boqRebar);
            item.CompletedRebarKg += Math.Max(0.0, completedRebar);
            item.BoqFormworkM2 += Math.Max(0.0, boqForm);
            item.CompletedFormworkM2 += Math.Max(0.0, completedForm);
            item.BoqVolumeM3 += Math.Max(0.0, boqVolume);
            item.CompletedVolumeM3 += Math.Max(0.0, completedVolume);
        }

        private static string BuildPowerBiBoqKey(string structureElement, string buildingLevel, string typeName)
        {
            return NormalizePowerBiBoqKeyPart(structureElement) + "|" +
                   NormalizePowerBiBoqKeyPart(buildingLevel) + "|" +
                   NormalizePowerBiBoqKeyPart(typeName);
        }

        private static string BuildPowerBiBoqLevelKey(string structureElement, string buildingLevel)
        {
            return NormalizePowerBiBoqKeyPart(structureElement) + "|" +
                   NormalizePowerBiBoqKeyPart(buildingLevel);
        }

        private static string BuildPowerBiBoqStructureKey(string structureElement)
        {
            return NormalizePowerBiBoqKeyPart(structureElement);
        }

        private static string NormalizePowerBiBoqKeyPart(string raw)
        {
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            var sb = new StringBuilder(text.Length);
            foreach (char ch in text)
            {
                if (char.IsLetterOrDigit(ch))
                {
                    sb.Append(char.ToLowerInvariant(ch));
                }
            }

            return sb.ToString();
        }

        private static double ResolvePowerBiProgressRatio(double completed, double total, double percent)
        {
            if (total > 1e-9)
            {
                return NormalizePowerBiProgressRatio(completed / total);
            }

            if (completed > 1e-9)
            {
                return 1.0;
            }

            return NormalizePowerBiProgressRatio(percent / 100.0);
        }

        private static double NormalizePowerBiProgressRatio(double value)
        {
            if (double.IsNaN(value) || double.IsInfinity(value))
            {
                return 0.0;
            }

            if (value < 0.0)
            {
                return 0.0;
            }

            if (value > 1.0)
            {
                return 1.0;
            }

            return value;
        }

        private static string BuildPowerBiSiteProgressStatus(double reinforcementRatio, double formworkRatio, double volumeRatio)
        {
            double max = Math.Max(reinforcementRatio, Math.Max(formworkRatio, volumeRatio));
            double min = Math.Min(reinforcementRatio, Math.Min(formworkRatio, volumeRatio));
            if (max <= 1e-9)
            {
                return "Not Started";
            }

            if (min >= 0.9999 && max >= 0.9999)
            {
                return "Completed";
            }

            return "In Progress";
        }

        private static DataTable BuildPowerBiManifestTable(DateTime snapshotUtc, IDictionary<string, DataTable> tables)
        {
            var manifest = new DataTable("export_manifest");
            manifest.Columns.Add("exported_utc", typeof(string));
            manifest.Columns.Add("file_name", typeof(string));
            manifest.Columns.Add("row_count", typeof(int));

            foreach (KeyValuePair<string, DataTable> kv in (tables ?? new Dictionary<string, DataTable>()).OrderBy(k => k.Key, StringComparer.OrdinalIgnoreCase))
            {
                DataRow row = manifest.NewRow();
                row["exported_utc"] = snapshotUtc.ToString("o", CultureInfo.InvariantCulture);
                row["file_name"] = kv.Key ?? "";
                row["row_count"] = kv.Value?.Rows?.Count ?? 0;
                manifest.Rows.Add(row);
            }

            return manifest;
        }

        private static void CollectPowerBiDatesFromTable(DataTable source, ISet<DateTime> dates)
        {
            if (source == null || dates == null || source.Columns.Count == 0)
            {
                return;
            }

            List<DataColumn> candidates = source.Columns
                .Cast<DataColumn>()
                .Where(c =>
                {
                    string name = c?.ColumnName ?? "";
                    return name.IndexOf("date", StringComparison.OrdinalIgnoreCase) >= 0 ||
                           name.IndexOf("toc", StringComparison.OrdinalIgnoreCase) >= 0 ||
                           name.IndexOf("handover", StringComparison.OrdinalIgnoreCase) >= 0 ||
                           name.IndexOf("spa", StringComparison.OrdinalIgnoreCase) >= 0 ||
                           name.IndexOf("month", StringComparison.OrdinalIgnoreCase) >= 0;
                })
                .ToList();
            if (candidates.Count == 0)
            {
                return;
            }

            foreach (DataRow row in source.Rows)
            {
                if (row == null || row.RowState == DataRowState.Deleted)
                {
                    continue;
                }

                foreach (DataColumn column in candidates)
                {
                    string raw = Convert.ToString(row[column], CultureInfo.InvariantCulture)?.Trim();
                    if (TryParsePowerBiDate(raw, out DateTime parsed))
                    {
                        dates.Add(parsed.Date);
                    }
                }
            }
        }

        private static bool TryParsePowerBiDate(string raw, out DateTime parsed)
        {
            parsed = DateTime.MinValue;
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out double oaInvariant) ||
                double.TryParse(text, NumberStyles.Float, CultureInfo.CurrentCulture, out oaInvariant))
            {
                if (oaInvariant > 1.0 && oaInvariant < 300000.0)
                {
                    try
                    {
                        parsed = DateTime.FromOADate(oaInvariant);
                        return true;
                    }
                    catch
                    {
                    }
                }
            }

            string[] formats =
            {
                "d/M/yyyy", "dd/MM/yyyy", "M/d/yyyy", "MM/dd/yyyy",
                "d-MMM-yy", "dd-MMM-yy", "d-MMM-yyyy", "dd-MMM-yyyy",
                "MMM-yy", "MMM-yyyy", "MMM yy", "MMM yyyy",
                "yyyy-MM-dd", "yyyy/M/d", "yyyyMMdd", "MM/yyyy", "M/yyyy"
            };

            if (DateTime.TryParseExact(
                text,
                formats,
                CultureInfo.InvariantCulture,
                DateTimeStyles.AllowWhiteSpaces,
                out parsed))
            {
                return true;
            }

            if (DateTime.TryParse(text, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out parsed))
            {
                return true;
            }

            return DateTime.TryParse(text, CultureInfo.CurrentCulture, DateTimeStyles.AllowWhiteSpaces, out parsed);
        }

        private static string ResolvePowerBiHouseKey(DataRow row)
        {
            string[] keyCandidates = { "Code_Item", "HOUSE ID", "House No(Sell)", "House Code", "Code", "Mark", "Id" };
            foreach (string key in keyCandidates)
            {
                string value = GetPowerBiSourceValue(row, key);
                if (!string.IsNullOrWhiteSpace(value))
                {
                    return value;
                }
            }

            return "";
        }

        private static string GetPowerBiSourceValue(DataRow row, string logicalName)
        {
            if (row?.Table == null || string.IsNullOrWhiteSpace(logicalName))
            {
                return "";
            }

            string columnName = ResolveFilterColumn(row.Table, logicalName);
            if (string.IsNullOrWhiteSpace(columnName))
            {
                DataColumn direct = row.Table.Columns
                    .Cast<DataColumn>()
                    .FirstOrDefault(c => string.Equals(c.ColumnName, logicalName, StringComparison.OrdinalIgnoreCase));
                if (direct != null)
                {
                    columnName = direct.ColumnName;
                }
            }

            if (string.IsNullOrWhiteSpace(columnName) || !row.Table.Columns.Contains(columnName))
            {
                return "";
            }

            object value = row[columnName];
            return value == null || value == DBNull.Value
                ? ""
                : Convert.ToString(value, CultureInfo.InvariantCulture)?.Trim() ?? "";
        }

        private static void MergePowerBiDimensionValue(DataRow target, string columnName, string value)
        {
            if (target == null || string.IsNullOrWhiteSpace(columnName) || string.IsNullOrWhiteSpace(value))
            {
                return;
            }

            string existing = Convert.ToString(target[columnName], CultureInfo.InvariantCulture) ?? "";
            if (string.IsNullOrWhiteSpace(existing))
            {
                target[columnName] = value.Trim();
            }
        }

        private static string NormalizePowerBiName(string raw)
        {
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return "col";
            }

            var sb = new StringBuilder(text.Length + 8);
            bool lastUnderscore = false;
            foreach (char ch in text)
            {
                if (char.IsLetterOrDigit(ch))
                {
                    sb.Append(char.ToLowerInvariant(ch));
                    lastUnderscore = false;
                }
                else if (!lastUnderscore)
                {
                    sb.Append('_');
                    lastUnderscore = true;
                }
            }

            string normalized = sb.ToString().Trim('_');
            if (string.IsNullOrWhiteSpace(normalized))
            {
                normalized = "col";
            }

            if (char.IsDigit(normalized[0]))
            {
                normalized = "c_" + normalized;
            }

            return normalized;
        }

        private static string EnsureUniquePowerBiName(HashSet<string> used, string baseName)
        {
            string candidate = string.IsNullOrWhiteSpace(baseName) ? "col" : baseName.Trim();
            if (used == null)
            {
                return candidate;
            }

            if (used.Add(candidate))
            {
                return candidate;
            }

            int index = 2;
            while (true)
            {
                string next = candidate + "_" + index.ToString(CultureInfo.InvariantCulture);
                if (used.Add(next))
                {
                    return next;
                }

                index++;
            }
        }

        private static string NormalizePowerBiUrl(string raw)
        {
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            if (!text.Contains("://"))
            {
                text = "https://" + text;
            }

            if (Uri.TryCreate(text, UriKind.Absolute, out Uri uri) &&
                (string.Equals(uri.Scheme, Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(uri.Scheme, Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase)))
            {
                return uri.AbsoluteUri;
            }

            return "";
        }

        private void SetPowerBiExportSummary(string message)
        {
            string safeMessage = message ?? "";
            if (PowerBiExportSummaryText != null)
            {
                PowerBiExportSummaryText.Text = safeMessage;
            }

            _powerBiLastSummaryMessage = safeMessage;
            if (!string.IsNullOrWhiteSpace(safeMessage) &&
                !safeMessage.StartsWith("Ready.", StringComparison.OrdinalIgnoreCase))
            {
                _powerBiLastActionLocal = DateTime.Now;
            }

            UpdatePowerBiRuntimeInfo();
        }

        private void UpdatePowerBiRuntimeInfo()
        {
            string projectPath = ResolvePowerBiProjectPath(out string expectedPath);
            if (PowerBiProjectPathText != null)
            {
                PowerBiProjectPathText.Text = !string.IsNullOrWhiteSpace(projectPath)
                    ? projectPath
                    : "Not found. Expected: " + expectedPath;
            }

            string exportFolder = _powerBiLastExportFolder;
            if (string.IsNullOrWhiteSpace(exportFolder))
            {
                exportFolder = ResolvePowerBiPipelineExportFolder();
            }

            if (PowerBiExportFolderText != null)
            {
                if (string.IsNullOrWhiteSpace(exportFolder))
                {
                    PowerBiExportFolderText.Text = "Not resolved.";
                }
                else if (Directory.Exists(exportFolder))
                {
                    PowerBiExportFolderText.Text = exportFolder;
                }
                else
                {
                    PowerBiExportFolderText.Text = exportFolder + " (folder missing)";
                }
            }

            if (PowerBiSiteProgressRefreshText != null)
            {
                PowerBiSiteProgressRefreshText.Text = _siteProgressLastRefreshLocal == DateTime.MinValue
                    ? "Never"
                    : _siteProgressLastRefreshLocal.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
            }

            if (PowerBiDataHealthText != null)
            {
                int summaryRows = _siteProgressCombinedSourceRows?.Count ?? 0;
                int byBuildingRows = _siteProgressByBuildingRows?.Count ?? 0;
                int detailRows = _siteProgressElementRows?.Count ?? 0;

                if (summaryRows <= 0 && byBuildingRows <= 0 && detailRows <= 0)
                {
                    PowerBiDataHealthText.Text = "No Site Progress cache loaded yet. Run Refresh Summary first.";
                }
                else
                {
                    PowerBiDataHealthText.Text = "Summary rows=" +
                                                 summaryRows.ToString(CultureInfo.InvariantCulture) +
                                                 " | By-building rows=" +
                                                 byBuildingRows.ToString(CultureInfo.InvariantCulture) +
                                                 " | Element rows=" +
                                                 detailRows.ToString(CultureInfo.InvariantCulture);
                }
            }

            if (PowerBiLastActionText != null)
            {
                if (_powerBiLastActionLocal == DateTime.MinValue)
                {
                    PowerBiLastActionText.Text = "No pipeline action yet.";
                }
                else
                {
                    string when = _powerBiLastActionLocal.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
                    string detail = TruncatePowerBiInfoText(_powerBiLastSummaryMessage, 150);
                    PowerBiLastActionText.Text = string.IsNullOrWhiteSpace(detail)
                        ? when
                        : when + " | " + detail;
                }
            }
        }

        private static string TruncatePowerBiInfoText(string raw, int maxLength)
        {
            int safeMax = Math.Max(8, maxLength);
            string text = (raw ?? "").Replace(Environment.NewLine, " ").Trim();
            if (text.Length <= safeMax)
            {
                return text;
            }

            return text.Substring(0, safeMax - 3) + "...";
        }

        private static void WriteDataTableToCsv(DataTable table, string filePath)
        {
            if (table == null)
            {
                throw new ArgumentNullException(nameof(table));
            }

            string folder = Path.GetDirectoryName(filePath) ?? "";
            if (!string.IsNullOrWhiteSpace(folder))
            {
                Directory.CreateDirectory(folder);
            }

            var sb = new StringBuilder(8192);
            List<DataColumn> columns = table.Columns.Cast<DataColumn>().ToList();
            sb.AppendLine(string.Join(",", columns.Select(c => EscapeCsv(c.ColumnName))));

            foreach (DataRow row in table.Rows)
            {
                if (row == null || row.RowState == DataRowState.Deleted)
                {
                    continue;
                }

                for (int i = 0; i < columns.Count; i++)
                {
                    if (i > 0)
                    {
                        sb.Append(',');
                    }

                    object value = row[columns[i]];
                    sb.Append(EscapeCsv(ToCsvCellString(value)));
                }

                sb.AppendLine();
            }

            File.WriteAllText(filePath, sb.ToString(), new UTF8Encoding(false));
        }

        private static string ToCsvCellString(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return "";
            }

            if (value is DateTime dt)
            {
                return dt.ToString("o", CultureInfo.InvariantCulture);
            }

            if (value is IFormattable formattable)
            {
                return formattable.ToString(null, CultureInfo.InvariantCulture);
            }

            return Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
        }

        private bool TryGetSiteProgressPercents(out double reinforcementPercent, out double formworkPercent, out double volumePercent)
        {
            formworkPercent = 0.0;
            volumePercent = 0.0;

            if (!TryParseSiteProgressPercent(SiteProgressReinforcementPercentTextBox?.Text, out reinforcementPercent))
            {
                ShowStatus("Site Progress: Reinforcement(%) must be a number between 0 and 100.");
                return false;
            }
            if (!TryParseSiteProgressPercent(SiteProgressFormworkPercentTextBox?.Text, out formworkPercent))
            {
                ShowStatus("Site Progress: Formwork(%) must be a number between 0 and 100.");
                return false;
            }
            if (!TryParseSiteProgressPercent(SiteProgressVolumePercentTextBox?.Text, out volumePercent))
            {
                ShowStatus("Site Progress: Volume(%) must be a number between 0 and 100.");
                return false;
            }

            return true;
        }

        private static bool TryParseSiteProgressPercent(string raw, out double percent)
        {
            string normalized = (raw ?? "").Trim().TrimEnd('%').Trim();
            if (string.IsNullOrWhiteSpace(normalized)) normalized = "0";

            if (!double.TryParse(normalized, NumberStyles.Float, CultureInfo.InvariantCulture, out percent) &&
                !double.TryParse(normalized, NumberStyles.Float, CultureInfo.CurrentCulture, out percent))
            {
                return false;
            }

            if (percent < 0.0 || percent > 100.0)
            {
                return false;
            }

            return true;
        }

