        private static PmStageMappingRules CreateDefaultPmStageMappingRules()
        {
            var rules = new PmStageMappingRules();
            rules.ReinforcementKeywords.AddRange(new[] { "reinforcement", "rebar", "re-bar", "steel" });
            rules.FormworkKeywords.AddRange(new[] { "formwork", "form work", "shutter", "shuttering" });
            rules.VolumeKeywords.AddRange(new[] { "concrete", "volume", "cast", "casting", "pour", "grout" });
            return rules;
        }

        private static PmAutoMapMatchOptions CreateDefaultPmAutoMapMatchOptions()
        {
            return new PmAutoMapMatchOptions
            {
                MatchBuildingLevel = true,
                MatchStructureElement = true,
                MatchStructureType = true
            };
        }

        private static PmAutoMapMatchOptions NormalizePmAutoMapMatchOptions(PmAutoMapMatchOptions options)
        {
            PmAutoMapMatchOptions normalized = (options ?? CreateDefaultPmAutoMapMatchOptions()).Clone();
            if (normalized.ActiveCount <= 0)
            {
                return CreateDefaultPmAutoMapMatchOptions();
            }

            return normalized;
        }

        private void LoadPmAutoMapMatchOptions()
        {
            try
            {
                string path = ResolvePmAutoMapRulesPath();
                if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
                {
                    _pmAutoMapMatchOptions = CreateDefaultPmAutoMapMatchOptions();
                    return;
                }

                Dictionary<string, string> kv = ReadPmStageMappingRulesFile(path);
                var loaded = CreateDefaultPmAutoMapMatchOptions();
                if (kv.TryGetValue(PmAutoMapRulesMatchBuildingLevelKey, out string matchBuildingRaw))
                {
                    loaded.MatchBuildingLevel = ParsePmAutoMapBoolean(matchBuildingRaw, loaded.MatchBuildingLevel);
                }
                if (kv.TryGetValue(PmAutoMapRulesMatchStructureElementKey, out string matchStructureRaw))
                {
                    loaded.MatchStructureElement = ParsePmAutoMapBoolean(matchStructureRaw, loaded.MatchStructureElement);
                }
                if (kv.TryGetValue(PmAutoMapRulesMatchStructureTypeKey, out string matchTypeRaw))
                {
                    loaded.MatchStructureType = ParsePmAutoMapBoolean(matchTypeRaw, loaded.MatchStructureType);
                }

                _pmAutoMapMatchOptions = NormalizePmAutoMapMatchOptions(loaded);
            }
            catch
            {
                _pmAutoMapMatchOptions = CreateDefaultPmAutoMapMatchOptions();
            }
        }

        private static bool ParsePmAutoMapBoolean(string raw, bool fallback)
        {
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return fallback;
            }

            if (string.Equals(text, "1", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "true", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "yes", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "on", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (string.Equals(text, "0", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "false", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "no", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(text, "off", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            return fallback;
        }

        private void SavePmAutoMapMatchOptions(PmAutoMapMatchOptions options)
        {
            PmAutoMapMatchOptions normalized = NormalizePmAutoMapMatchOptions(options);
            string path = ResolvePmAutoMapRulesPath();
            if (string.IsNullOrWhiteSpace(path))
            {
                return;
            }

            string folder = Path.GetDirectoryName(path);
            if (!string.IsNullOrWhiteSpace(folder))
            {
                Directory.CreateDirectory(folder);
            }

            var sb = new StringBuilder();
            sb.AppendLine("# CamboBIM PM Auto-Map Rules");
            sb.AppendLine("# Edit via Update Progress > Auto-Map Rule");
            sb.AppendLine(PmAutoMapRulesMatchBuildingLevelKey + "=" + normalized.MatchBuildingLevel.ToString().ToLowerInvariant());
            sb.AppendLine(PmAutoMapRulesMatchStructureElementKey + "=" + normalized.MatchStructureElement.ToString().ToLowerInvariant());
            sb.AppendLine(PmAutoMapRulesMatchStructureTypeKey + "=" + normalized.MatchStructureType.ToString().ToLowerInvariant());

            File.WriteAllText(path, sb.ToString(), new UTF8Encoding(false));
        }

        private string ResolvePmAutoMapRulesPath()
        {
            try
            {
                string databaseFolder = GetDatabaseFolder();
                if (string.IsNullOrWhiteSpace(databaseFolder))
                {
                    return Path.Combine(AppDomain.CurrentDomain.BaseDirectory ?? "", PmAutoMapRulesFileName);
                }

                string targetFolder = Path.Combine(databaseFolder, "PM Dashboard");
                return Path.Combine(targetFolder, PmAutoMapRulesFileName);
            }
            catch
            {
                return Path.Combine(AppDomain.CurrentDomain.BaseDirectory ?? "", PmAutoMapRulesFileName);
            }
        }

        private void LoadPmStageMappingRules()
        {
            try
            {
                string path = ResolvePmStageMappingRulesPath();
                if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
                {
                    _pmStageMappingRules = CreateDefaultPmStageMappingRules();
                    return;
                }

                Dictionary<string, string> kv = ReadPmStageMappingRulesFile(path);
                var loaded = CreateDefaultPmStageMappingRules();

                if (kv.TryGetValue(PmStageMappingRulesReinforcementKey, out string reinforcementRaw))
                {
                    List<string> parsed = ParsePmStageMappingKeywords(reinforcementRaw);
                    if (parsed.Count > 0)
                    {
                        loaded.ReinforcementKeywords.Clear();
                        loaded.ReinforcementKeywords.AddRange(parsed);
                    }
                }

                if (kv.TryGetValue(PmStageMappingRulesFormworkKey, out string formworkRaw))
                {
                    List<string> parsed = ParsePmStageMappingKeywords(formworkRaw);
                    if (parsed.Count > 0)
                    {
                        loaded.FormworkKeywords.Clear();
                        loaded.FormworkKeywords.AddRange(parsed);
                    }
                }

                if (kv.TryGetValue(PmStageMappingRulesVolumeKey, out string volumeRaw))
                {
                    List<string> parsed = ParsePmStageMappingKeywords(volumeRaw);
                    if (parsed.Count > 0)
                    {
                        loaded.VolumeKeywords.Clear();
                        loaded.VolumeKeywords.AddRange(parsed);
                    }
                }

                _pmStageMappingRules = loaded;
            }
            catch
            {
                _pmStageMappingRules = CreateDefaultPmStageMappingRules();
            }
        }

        private static Dictionary<string, string> ReadPmStageMappingRulesFile(string path)
        {
            var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                return result;
            }

            foreach (string rawLine in File.ReadAllLines(path))
            {
                string line = (rawLine ?? "").Trim();
                if (string.IsNullOrWhiteSpace(line) || line.StartsWith("#", StringComparison.Ordinal))
                {
                    continue;
                }

                int split = line.IndexOf('=');
                if (split <= 0)
                {
                    continue;
                }

                string key = line.Substring(0, split).Trim();
                string value = split + 1 < line.Length ? line.Substring(split + 1).Trim() : "";
                if (string.IsNullOrWhiteSpace(key))
                {
                    continue;
                }

                result[key] = value;
            }

            return result;
        }

        private void SavePmStageMappingRules(PmStageMappingRules rules)
        {
            if (rules == null)
            {
                return;
            }

            string path = ResolvePmStageMappingRulesPath();
            if (string.IsNullOrWhiteSpace(path))
            {
                return;
            }

            string folder = Path.GetDirectoryName(path);
            if (!string.IsNullOrWhiteSpace(folder))
            {
                Directory.CreateDirectory(folder);
            }

            string reinforcement = string.Join(",", NormalizePmStageMappingKeywords(rules.ReinforcementKeywords));
            string formwork = string.Join(",", NormalizePmStageMappingKeywords(rules.FormworkKeywords));
            string volume = string.Join(",", NormalizePmStageMappingKeywords(rules.VolumeKeywords));

            var sb = new StringBuilder();
            sb.AppendLine("# CamboBIM PM Stage Mapping Rules");
            sb.AppendLine("# Edit via Update Progress > Stage Rules");
            sb.AppendLine(PmStageMappingRulesReinforcementKey + "=" + reinforcement);
            sb.AppendLine(PmStageMappingRulesFormworkKey + "=" + formwork);
            sb.AppendLine(PmStageMappingRulesVolumeKey + "=" + volume);

            File.WriteAllText(path, sb.ToString(), new UTF8Encoding(false));
        }

        private static string BuildPmStageMappingKeywordsText(IEnumerable<string> keywords)
        {
            List<string> list = NormalizePmStageMappingKeywords(keywords);
            return string.Join(Environment.NewLine, list);
        }

        private static List<string> ParsePmStageMappingKeywords(string raw)
        {
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return new List<string>();
            }

            string[] tokens = text
                .Replace("\r\n", "\n")
                .Replace('\r', '\n')
                .Split(new[] { '\n', ',', ';', '|' }, StringSplitOptions.RemoveEmptyEntries);

            return NormalizePmStageMappingKeywords(tokens);
        }

        private static List<string> NormalizePmStageMappingKeywords(IEnumerable<string> keywords)
        {
            return (keywords ?? Enumerable.Empty<string>())
                .Select(v => (v ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(v => v, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private string ResolvePmStageMappingRulesPath()
        {
            try
            {
                string databaseFolder = GetDatabaseFolder();
                if (string.IsNullOrWhiteSpace(databaseFolder))
                {
                    return Path.Combine(AppDomain.CurrentDomain.BaseDirectory ?? "", PmStageMappingRulesFileName);
                }

                string targetFolder = Path.Combine(databaseFolder, "PM Dashboard");
                return Path.Combine(targetFolder, PmStageMappingRulesFileName);
            }
            catch
            {
                return Path.Combine(AppDomain.CurrentDomain.BaseDirectory ?? "", PmStageMappingRulesFileName);
            }
        }

