        private static string BuildPmAutoMapRuleSummary(PmAutoMapMatchOptions options)
        {
            PmAutoMapMatchOptions normalized = NormalizePmAutoMapMatchOptions(options);
            var parts = new List<string>();
            if (normalized.MatchBuildingLevel)
            {
                parts.Add("Building Level");
            }
            if (normalized.MatchStructureElement)
            {
                parts.Add("Structure Element");
            }
            if (normalized.MatchStructureType)
            {
                parts.Add("Structure Type");
            }

            return parts.Count > 0 ? string.Join(" + ", parts) : "Building Level + Structure Element + Structure Type";
        }

