        private static bool IsPmUpdateProgressDefaultVisibleColumnKey(string key)
        {
            string normalized = NormalizePmUpdateProgressColumnKey(key);
            if (string.IsNullOrWhiteSpace(normalized))
            {
                return false;
            }

            return PmUpdateProgressDefaultVisibleColumnKeys
                .Any(v => string.Equals(v, normalized, StringComparison.OrdinalIgnoreCase));
        }

        private void EnsurePmUpdateProgressDefaultVisibleColumns(DataGrid grid)
        {
            if (grid == null || grid.Columns == null || grid.Columns.Count == 0)
            {
                return;
            }

            foreach (DataGridColumn column in grid.Columns)
            {
                string key = GetPmUpdateProgressColumnKey(grid, column);
                if (string.IsNullOrWhiteSpace(key))
                {
                    continue;
                }

                bool shouldInitialize = !_pmUpdateProgressColumnVisibilityInitialized ||
                                        _pmUpdateProgressKnownColumnKeys.Add(key);
                if (PmUpdateProgressInternalColumnKeys.Contains(key))
                {
                    _pmUpdateProgressHiddenColumnKeys.Add(key);
                    continue;
                }

                if (!shouldInitialize)
                {
                    continue;
                }

                if (IsPmUpdateProgressDefaultVisibleColumnKey(key))
                {
                    _pmUpdateProgressHiddenColumnKeys.Remove(key);
                }
                else
                {
                    _pmUpdateProgressHiddenColumnKeys.Add(key);
                }
            }

            _pmUpdateProgressColumnVisibilityInitialized = true;
        }

