        private void RefreshPmDetailProgressFilterOptions()
        {
            var buildingCombo = GetPmDashboardNamedControl<System.Windows.Controls.ComboBox>("PmDetailProgressBuildingLevelFilterCombo");
            var structureCombo = GetPmDashboardNamedControl<System.Windows.Controls.ComboBox>("PmDetailProgressStructureElementFilterCombo");
            var typeCombo = GetPmDashboardNamedControl<System.Windows.Controls.ComboBox>("PmDetailProgressStructureTypeFilterCombo");
            if (buildingCombo == null || structureCombo == null || typeCombo == null)
            {
                return;
            }

            List<SiteProgressSummaryRow> rows = _siteProgressCombinedRows
                .Where(r => r != null)
                .ToList();
            SetPmUpdateProgressFilterComboOptions(
                buildingCombo,
                rows.Select(r => r.BuildingLevel),
                sortByBuildingLevel: true);
            SetPmUpdateProgressFilterComboOptions(
                structureCombo,
                rows.Select(r => r.StructureElement),
                sortByBuildingLevel: false);
            SetPmUpdateProgressFilterComboOptions(
                typeCombo,
                rows.Select(r => r.TypeName),
                sortByBuildingLevel: false);
        }

        private void RefreshPmMsProjectFilterOptions()
        {
            var buildingCombo = GetPmDashboardNamedControl<System.Windows.Controls.ComboBox>("PmMsProjectBuildingLevelFilterCombo");
            var structureCombo = GetPmDashboardNamedControl<System.Windows.Controls.ComboBox>("PmMsProjectStructureElementFilterCombo");
            var typeCombo = GetPmDashboardNamedControl<System.Windows.Controls.ComboBox>("PmMsProjectStructureTypeFilterCombo");
            var revitActiveCombo = GetPmDashboardNamedControl<System.Windows.Controls.ComboBox>("PmMsProjectRevitActiveFilterCombo");
            var grid = GetPmDashboardNamedControl<DataGrid>("PmUpdateProgressDataGrid");
            if (buildingCombo == null ||
                structureCombo == null ||
                typeCombo == null ||
                revitActiveCombo == null ||
                !(grid?.ItemsSource is DataView view))
            {
                return;
            }

            EnsurePmMsProjectFilterColumns(view);
            List<DataRow> rows = view.Table.Rows
                .Cast<DataRow>()
                .Where(r => r != null && r.RowState != DataRowState.Deleted)
                .ToList();
            SetPmUpdateProgressFilterComboOptions(
                buildingCombo,
                rows.Select(r => ReadPmUpdateProgressRowString(r, "pm_filter_building_level")),
                sortByBuildingLevel: true);
            SetPmUpdateProgressFilterComboOptions(
                structureCombo,
                rows.Select(r => ReadPmUpdateProgressRowString(r, "pm_filter_structure_element")),
                sortByBuildingLevel: false);
            SetPmUpdateProgressFilterComboOptions(
                typeCombo,
                rows.Select(r => ReadPmUpdateProgressRowString(r, "pm_filter_structure_type")),
                sortByBuildingLevel: false);
            SetPmUpdateProgressRevitLinkFilterComboOptions(revitActiveCombo);
        }

        private void SetPmUpdateProgressFilterComboOptions(
            System.Windows.Controls.ComboBox combo,
            IEnumerable<string> values,
            bool sortByBuildingLevel)
        {
            if (combo == null)
            {
                return;
            }

            List<string> items = (values ?? Enumerable.Empty<string>())
                .Select(v => (v ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Where(v => !string.Equals(v, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            items = sortByBuildingLevel
                ? items
                    .OrderBy(v => GetPmDashboardBuildingLevelOrder(v))
                    .ThenBy(v => v, StringComparer.OrdinalIgnoreCase)
                    .ToList()
                : items
                    .OrderBy(v => v, StringComparer.OrdinalIgnoreCase)
                    .ToList();

            HashSet<string> selectedValues = GetPmUpdateProgressFilterSelectedValues(combo);
            selectedValues.IntersectWith(items);

            var options = new List<PmUpdateProgressFilterOption>
            {
                new PmUpdateProgressFilterOption
                {
                    Value = SiteProgressFilterAll,
                    IsSelected = selectedValues.Count == 0
                }
            };
            options.AddRange(items.Select(v => new PmUpdateProgressFilterOption
            {
                Value = v,
                IsSelected = selectedValues.Contains(v)
            }));

            NormalizePmUpdateProgressFilterOptionsState(options);
            SavePmUpdateProgressFilterSelectedValues(combo, options);

            _pmUpdateProgressFilterUiUpdateInProgress = true;
            try
            {
                combo.ItemsSource = options;
                combo.SelectedIndex = -1;
                combo.Text = BuildPmUpdateProgressFilterComboText(options, sortByBuildingLevel);
            }
            finally
            {
                _pmUpdateProgressFilterUiUpdateInProgress = false;
            }
        }

        private void SetPmUpdateProgressRevitLinkFilterComboOptions(System.Windows.Controls.ComboBox combo)
        {
            if (combo == null)
            {
                return;
            }

            var items = new List<string>
            {
                PmUpdateProgressRevitLinkActive,
                PmUpdateProgressRevitLinkNotActive
            };

            SetPmUpdateProgressFilterComboOptions(combo, items, sortByBuildingLevel: false);
        }

        private static string GetPmUpdateProgressFilterComboKey(System.Windows.Controls.ComboBox combo)
        {
            return (combo?.Name ?? "").Trim();
        }

        private HashSet<string> GetPmUpdateProgressFilterSelectedValues(System.Windows.Controls.ComboBox combo)
        {
            string key = GetPmUpdateProgressFilterComboKey(combo);
            if (string.IsNullOrWhiteSpace(key))
            {
                return new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            }

            if (_pmUpdateProgressFilterSelectedValuesByCombo.TryGetValue(key, out HashSet<string> selected))
            {
                return new HashSet<string>(selected, StringComparer.OrdinalIgnoreCase);
            }

            return new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        }

        private void SavePmUpdateProgressFilterSelectedValues(
            System.Windows.Controls.ComboBox combo,
            IEnumerable<PmUpdateProgressFilterOption> options)
        {
            string key = GetPmUpdateProgressFilterComboKey(combo);
            if (string.IsNullOrWhiteSpace(key))
            {
                return;
            }

            var selected = (options ?? Enumerable.Empty<PmUpdateProgressFilterOption>())
                .Where(o => o != null &&
                            o.IsSelected &&
                            !string.Equals(o.Value, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase))
                .Select(o => (o.Value ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);

            _pmUpdateProgressFilterSelectedValuesByCombo[key] = selected;
        }

        private static void NormalizePmUpdateProgressFilterOptionsState(List<PmUpdateProgressFilterOption> options)
        {
            if (options == null || options.Count == 0)
            {
                return;
            }

            PmUpdateProgressFilterOption allOption = options
                .FirstOrDefault(o => o != null && string.Equals(o.Value, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase));
            List<PmUpdateProgressFilterOption> valueOptions = options
                .Where(o => o != null && !string.Equals(o.Value, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase))
                .ToList();

            if (allOption == null)
            {
                return;
            }

            if (allOption.IsSelected)
            {
                foreach (PmUpdateProgressFilterOption valueOption in valueOptions)
                {
                    valueOption.IsSelected = false;
                }

                return;
            }

            if (valueOptions.Any(o => o.IsSelected))
            {
                allOption.IsSelected = false;
                return;
            }

            allOption.IsSelected = true;
        }

        private static string BuildPmUpdateProgressFilterComboText(
            IEnumerable<PmUpdateProgressFilterOption> options,
            bool sortByBuildingLevel)
        {
            List<string> selected = (options ?? Enumerable.Empty<PmUpdateProgressFilterOption>())
                .Where(o => o != null &&
                            o.IsSelected &&
                            !string.Equals(o.Value, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase))
                .Select(o => (o.Value ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (selected.Count == 0)
            {
                return SiteProgressFilterAll;
            }

            selected = sortByBuildingLevel
                ? selected
                    .OrderBy(v => GetPmDashboardBuildingLevelOrder(v))
                    .ThenBy(v => v, StringComparer.OrdinalIgnoreCase)
                    .ToList()
                : selected
                    .OrderBy(v => v, StringComparer.OrdinalIgnoreCase)
                    .ToList();

            return string.Join(", ", selected);
        }

        private void TogglePmUpdateProgressFilterOption(
            System.Windows.Controls.ComboBox combo,
            PmUpdateProgressFilterOption clickedOption)
        {
            if (combo == null || clickedOption == null)
            {
                return;
            }

            List<PmUpdateProgressFilterOption> options = (combo.ItemsSource as IEnumerable<PmUpdateProgressFilterOption>)?
                .Where(o => o != null)
                .ToList() ?? new List<PmUpdateProgressFilterOption>();
            if (options.Count == 0)
            {
                return;
            }

            bool clickedIsAll = string.Equals(clickedOption.Value, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase);
            clickedOption.IsSelected = !clickedOption.IsSelected;

            if (clickedIsAll && clickedOption.IsSelected)
            {
                foreach (PmUpdateProgressFilterOption option in options)
                {
                    if (!ReferenceEquals(option, clickedOption))
                    {
                        option.IsSelected = false;
                    }
                }
            }
            else if (!clickedIsAll && clickedOption.IsSelected)
            {
                PmUpdateProgressFilterOption allOption = options
                    .FirstOrDefault(o => string.Equals(o.Value, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase));
                if (allOption != null)
                {
                    allOption.IsSelected = false;
                }
            }

            NormalizePmUpdateProgressFilterOptionsState(options);
            SavePmUpdateProgressFilterSelectedValues(combo, options);

            _pmUpdateProgressFilterUiUpdateInProgress = true;
            try
            {
                combo.SelectedIndex = -1;
                bool sortByBuildingLevel = (combo.Name ?? "").IndexOf("BuildingLevel", StringComparison.OrdinalIgnoreCase) >= 0;
                combo.Text = BuildPmUpdateProgressFilterComboText(options, sortByBuildingLevel);
                combo.Items.Refresh();
            }
            finally
            {
                _pmUpdateProgressFilterUiUpdateInProgress = false;
            }

            if ((combo.Name ?? "").StartsWith("PmDetailProgress", StringComparison.OrdinalIgnoreCase))
            {
                ApplyPmDetailProgressFilters();
            }
            else
            {
                ApplyPmMsProjectTableFilters();
            }
        }

        private HashSet<string> GetPmUpdateProgressFilterValueSet(System.Windows.Controls.ComboBox combo)
        {
            string key = GetPmUpdateProgressFilterComboKey(combo);
            if (!string.IsNullOrWhiteSpace(key) &&
                _pmUpdateProgressFilterSelectedValuesByCombo.TryGetValue(key, out HashSet<string> selectedValues))
            {
                return new HashSet<string>(selectedValues, StringComparer.OrdinalIgnoreCase);
            }

            var options = (combo?.ItemsSource as IEnumerable<PmUpdateProgressFilterOption>)?
                .Where(o => o != null &&
                            o.IsSelected &&
                            !string.Equals(o.Value, SiteProgressFilterAll, StringComparison.OrdinalIgnoreCase))
                .Select(o => (o.Value ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .ToHashSet(StringComparer.OrdinalIgnoreCase);

            return options ?? new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        }

        private static bool IsPmUpdateProgressAllFilter(HashSet<string> values)
        {
            return values == null || values.Count == 0;
        }

        private static bool MatchesPmUpdateProgressFilterValue(HashSet<string> values, string candidate)
        {
            if (IsPmUpdateProgressAllFilter(values))
            {
                return true;
            }

            string normalized = (candidate ?? "").Trim();
            return values.Contains(normalized);
        }

