        private void RefreshReportsFromLiveSnapshot(PmDashboardLiveSnapshot liveSnapshot)
        {
            _reportsLatestSnapshot = liveSnapshot;
            if (liveSnapshot == null || liveSnapshot.Tasks.Count == 0)
            {
                _reportsLookaheadProjectStart = null;
                _reportsLookaheadProjectFinish = null;
                _reportsActivityTasks = new List<PmReportsActivityTaskRow>();
                _reportsFilteredActivityTasks = new List<PmReportsActivityTaskRow>();
                if (lookaheadPreviewGrid != null)
                {
                    lookaheadPreviewGrid.ItemsSource = null;
                }
                if (activityTaskGrid != null)
                {
                    activityTaskGrid.ItemsSource = null;
                }
                _reportsSCurvePoints = new List<PmDashboardCurvePoint>();
                _reportsDurationCurvePoints = new List<PmDashboardCurvePoint>();
                _reportsResourceCurvePoints = new List<PmDashboardCurvePoint>();
                RefreshReportsCurveVisuals();
                _reportsProgressCostContent = null;
                _reportsProgressDurationContent = null;
                UpdateProgressReportView();
                RefreshReportsDashboardAndQuality(null);
                return;
            }

            DateTime statusDate = liveSnapshot.StatusDate.Date;
            DateTime projectStart = liveSnapshot.ProjectStart.Date;
            DateTime projectFinish = liveSnapshot.ProjectFinish.Date;
            if (!IsValidPmDashboardProjectDate(projectStart) || !IsValidPmDashboardProjectDate(projectFinish) || projectFinish < projectStart)
            {
                projectStart = statusDate;
                projectFinish = statusDate;
            }

            _reportsLookaheadProjectStart = projectStart;
            _reportsLookaheadProjectFinish = projectFinish;
            EnsureReportsLookaheadDateRange(statusDate);

            RefreshReportsCurveVisuals();
            RefreshReportsLookaheadPreview(GetSelectedLookaheadDays());
            RefreshReportsActivityTaskData(liveSnapshot);
            UpdateReportsProgressReport(liveSnapshot);
            RefreshReportsDashboardAndQuality(liveSnapshot);
        }

