        private void EnsureReportsLookaheadDateRange(DateTime statusDate)
        {
            if (lookaheadStartPicker == null || lookaheadFinishPicker == null)
            {
                return;
            }

            DateTime projectStart = _reportsLookaheadProjectStart ?? statusDate.Date;
            DateTime projectFinish = _reportsLookaheadProjectFinish ?? statusDate.Date;
            if (!IsValidPmDashboardProjectDate(projectStart) || !IsValidPmDashboardProjectDate(projectFinish) || projectFinish < projectStart)
            {
                projectStart = statusDate.Date;
                projectFinish = statusDate.Date;
            }

            int lookaheadDays = Math.Max(1, GetSelectedLookaheadDays());
            DateTime start = statusDate.Date;
            if (start < projectStart)
            {
                start = projectStart;
            }

            DateTime finish = start.AddDays(lookaheadDays);
            if (finish > projectFinish)
            {
                finish = projectFinish;
            }
            if (finish < start)
            {
                finish = start;
            }

            _reportsLookaheadSuppressUpdate = true;
            try
            {
                if (!lookaheadStartPicker.SelectedDate.HasValue)
                {
                    lookaheadStartPicker.SelectedDate = start;
                }
                if (!lookaheadFinishPicker.SelectedDate.HasValue)
                {
                    lookaheadFinishPicker.SelectedDate = finish;
                }
            }
            finally
            {
                _reportsLookaheadSuppressUpdate = false;
            }

            SyncLookaheadSlidersFromDates();
        }

        private int GetSelectedLookaheadDays()
        {
            string text = GetPmDashboardComboValue(lookaheadPeriodCombo, "2 Weeks");
            if (string.IsNullOrWhiteSpace(text))
            {
                return 14;
            }

            Match numberMatch = Regex.Match(text, @"\d+");
            int value = numberMatch.Success &&
                        int.TryParse(numberMatch.Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsed)
                ? Math.Max(1, parsed)
                : 2;

            if (text.IndexOf("month", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return value * 30;
            }
            if (text.IndexOf("week", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return value * 7;
            }

            return value;
        }

        private void ApplyLookaheadPeriodToDates(int lookaheadDays)
        {
            if (lookaheadStartPicker == null || lookaheadFinishPicker == null)
            {
                return;
            }

            int days = Math.Max(1, lookaheadDays);
            DateTime baseDate = _reportsLatestSnapshot?.StatusDate.Date ?? DateTime.Today;
            DateTime start = lookaheadStartPicker.SelectedDate ?? baseDate;
            DateTime finish = start.AddDays(days);

            if (_reportsLookaheadProjectStart.HasValue && start < _reportsLookaheadProjectStart.Value.Date)
            {
                start = _reportsLookaheadProjectStart.Value.Date;
            }
            if (_reportsLookaheadProjectFinish.HasValue && finish > _reportsLookaheadProjectFinish.Value.Date)
            {
                finish = _reportsLookaheadProjectFinish.Value.Date;
            }
            if (finish < start)
            {
                finish = start;
            }

            _reportsLookaheadSuppressUpdate = true;
            try
            {
                lookaheadStartPicker.SelectedDate = start;
                lookaheadFinishPicker.SelectedDate = finish;
            }
            finally
            {
                _reportsLookaheadSuppressUpdate = false;
            }

            SyncLookaheadSlidersFromDates();
        }

        private void SyncLookaheadSlidersFromDates()
        {
            if (lookaheadStartSlider == null || lookaheadFinishSlider == null ||
                lookaheadStartPicker == null || lookaheadFinishPicker == null)
            {
                return;
            }

            DateTime projectStart = _reportsLookaheadProjectStart ?? (_reportsLatestSnapshot?.ProjectStart.Date ?? DateTime.Today);
            DateTime projectFinish = _reportsLookaheadProjectFinish ?? (_reportsLatestSnapshot?.ProjectFinish.Date ?? projectStart);
            if (!IsValidPmDashboardProjectDate(projectStart) || !IsValidPmDashboardProjectDate(projectFinish) || projectFinish < projectStart)
            {
                projectStart = DateTime.Today;
                projectFinish = projectStart.AddDays(1);
            }

            DateTime start = (lookaheadStartPicker.SelectedDate ?? projectStart).Date;
            DateTime finish = (lookaheadFinishPicker.SelectedDate ?? projectFinish).Date;
            if (finish < start)
            {
                (start, finish) = (finish, start);
            }

            double totalDays = Math.Max(1.0, (projectFinish - projectStart).TotalDays);
            double startPercent = ((start - projectStart).TotalDays / totalDays) * 100.0;
            double finishPercent = ((finish - projectStart).TotalDays / totalDays) * 100.0;
            startPercent = Math.Max(0.0, Math.Min(100.0, startPercent));
            finishPercent = Math.Max(0.0, Math.Min(100.0, finishPercent));

            _reportsLookaheadSuppressUpdate = true;
            try
            {
                lookaheadStartSlider.Value = startPercent;
                lookaheadFinishSlider.Value = finishPercent;
            }
            finally
            {
                _reportsLookaheadSuppressUpdate = false;
            }
        }

        private void SyncLookaheadDatesFromSliders()
        {
            if (lookaheadStartSlider == null || lookaheadFinishSlider == null ||
                lookaheadStartPicker == null || lookaheadFinishPicker == null)
            {
                return;
            }

            DateTime projectStart = _reportsLookaheadProjectStart ?? (_reportsLatestSnapshot?.ProjectStart.Date ?? DateTime.Today);
            DateTime projectFinish = _reportsLookaheadProjectFinish ?? (_reportsLatestSnapshot?.ProjectFinish.Date ?? projectStart);
            if (!IsValidPmDashboardProjectDate(projectStart) || !IsValidPmDashboardProjectDate(projectFinish) || projectFinish < projectStart)
            {
                projectStart = DateTime.Today;
                projectFinish = projectStart.AddDays(1);
            }

            double totalDays = Math.Max(1.0, (projectFinish - projectStart).TotalDays);
            double startPercent = Math.Max(0.0, Math.Min(100.0, lookaheadStartSlider.Value));
            double finishPercent = Math.Max(0.0, Math.Min(100.0, lookaheadFinishSlider.Value));
            if (finishPercent < startPercent)
            {
                (startPercent, finishPercent) = (finishPercent, startPercent);
            }

            DateTime start = projectStart.AddDays(Math.Round((startPercent / 100.0) * totalDays)).Date;
            DateTime finish = projectStart.AddDays(Math.Round((finishPercent / 100.0) * totalDays)).Date;
            if (finish < start)
            {
                finish = start;
            }

            _reportsLookaheadSuppressUpdate = true;
            try
            {
                lookaheadStartPicker.SelectedDate = start;
                lookaheadFinishPicker.SelectedDate = finish;
            }
            finally
            {
                _reportsLookaheadSuppressUpdate = false;
            }
        }

        private PmReportsLookaheadViewMode GetSelectedLookaheadViewMode()
        {
            string text = GetPmDashboardComboValue(lookaheadViewCombo, "Timeline");
            return string.Equals(text, "WBS", StringComparison.OrdinalIgnoreCase)
                ? PmReportsLookaheadViewMode.Wbs
                : PmReportsLookaheadViewMode.Timeline;
        }

        private void UpdateLookaheadViewColumns()
        {
            if (lookaheadWbsColumn == null)
            {
                return;
            }

            lookaheadWbsColumn.Visibility = GetSelectedLookaheadViewMode() == PmReportsLookaheadViewMode.Wbs
                ? System.Windows.Visibility.Visible
                : System.Windows.Visibility.Collapsed;
        }

        private static int CompareReportsWbs(string left, string right)
        {
            string a = (left ?? "").Trim();
            string b = (right ?? "").Trim();
            bool aEmpty = string.IsNullOrWhiteSpace(a);
            bool bEmpty = string.IsNullOrWhiteSpace(b);
            if (aEmpty && bEmpty) return 0;
            if (aEmpty) return 1;
            if (bEmpty) return -1;

            string[] aParts = a.Split('.');
            string[] bParts = b.Split('.');
            int len = Math.Max(aParts.Length, bParts.Length);
            for (int i = 0; i < len; i++)
            {
                if (i >= aParts.Length) return -1;
                if (i >= bParts.Length) return 1;

                string aPart = aParts[i];
                string bPart = bParts[i];
                bool aNum = int.TryParse(aPart, NumberStyles.Integer, CultureInfo.InvariantCulture, out int aVal);
                bool bNum = int.TryParse(bPart, NumberStyles.Integer, CultureInfo.InvariantCulture, out int bVal);
                if (aNum && bNum)
                {
                    int cmp = aVal.CompareTo(bVal);
                    if (cmp != 0) return cmp;
                }
                else
                {
                    int cmp = string.Compare(aPart, bPart, StringComparison.OrdinalIgnoreCase);
                    if (cmp != 0) return cmp;
                }
            }

            return string.Compare(a, b, StringComparison.OrdinalIgnoreCase);
        }

        private void RefreshReportsLookaheadPreview(int lookaheadDays)
        {
            if (lookaheadPreviewGrid == null)
            {
                return;
            }

            PmDashboardLiveSnapshot snapshot = _reportsLatestSnapshot;
            if (snapshot == null || snapshot.Tasks.Count == 0)
            {
                lookaheadPreviewGrid.ItemsSource = null;
                return;
            }

            DateTime statusDate = snapshot.StatusDate.Date;
            DateTime windowStart = lookaheadStartPicker?.SelectedDate ?? statusDate;
            DateTime windowFinish = lookaheadFinishPicker?.SelectedDate ?? statusDate.AddDays(Math.Max(1, lookaheadDays));
            if (windowFinish < windowStart)
            {
                (windowStart, windowFinish) = (windowFinish, windowStart);
            }

            PmReportsLookaheadViewMode viewMode = GetSelectedLookaheadViewMode();

            var rows = new List<PmReportsLookaheadRow>();
            double totalRemainingDays = 0.0;
            double totalBaselineCost = 0.0;
            double totalActualCost = 0.0;
            double totalRemainingCost = 0.0;

            foreach (PmDashboardTaskSnapshot task in snapshot.Tasks)
            {
                if (task == null)
                {
                    continue;
                }

                if (task.PercentComplete >= 100.0)
                {
                    continue;
                }

                DateTime start = task.TaskStart.Date;
                DateTime finish = task.TaskFinish.Date;
                if (!IsValidPmDashboardProjectDate(start) || !IsValidPmDashboardProjectDate(finish) || finish < start)
                {
                    continue;
                }

                bool overlaps = start <= windowFinish && finish >= windowStart;
                if (!overlaps)
                {
                    continue;
                }

                DateTime actualStart = task.ActualStart.Date;
                DateTime actualFinish = task.ActualFinish.Date;
                string actualText = IsValidPmDashboardProjectDate(actualFinish)
                    ? actualFinish.ToString("dd MMM yy", CultureInfo.InvariantCulture)
                    : (IsValidPmDashboardProjectDate(actualStart)
                        ? actualStart.ToString("dd MMM yy", CultureInfo.InvariantCulture)
                        : "-");

                double remainingDays = Math.Max(0.0, task.RemainingDurationDays);
                if (remainingDays <= 1e-9 && finish >= statusDate)
                {
                    remainingDays = (finish - statusDate).TotalDays + 1.0;
                }
                if (remainingDays < 0.0)
                {
                    remainingDays = 0.0;
                }

                totalRemainingDays += remainingDays;
                totalBaselineCost += Math.Max(0.0, task.BaselineCost);
                totalActualCost += Math.Max(0.0, task.ActualCostToDate);
                totalRemainingCost += Math.Max(0.0, task.RemainingCost);

                string taskLabel = string.IsNullOrWhiteSpace(task.TaskName)
                    ? "Task " + task.TaskId.ToString(CultureInfo.InvariantCulture)
                    : task.TaskName;
                string wbs = task.TaskLinkKey ?? "";
                string activityDisplay = viewMode == PmReportsLookaheadViewMode.Wbs && !string.IsNullOrWhiteSpace(wbs)
                    ? wbs + " - " + taskLabel
                    : taskLabel;

                rows.Add(new PmReportsLookaheadRow
                {
                    Id = task.TaskId > 0 ? task.TaskId.ToString(CultureInfo.InvariantCulture) : "",
                    Activity = taskLabel,
                    ActivityDisplay = activityDisplay,
                    Start = start.ToString("dd MMM yy", CultureInfo.InvariantCulture),
                    Finish = finish.ToString("dd MMM yy", CultureInfo.InvariantCulture),
                    Actual = actualText,
                    Remaining = Math.Round(remainingDays, 0).ToString("N0", CultureInfo.InvariantCulture),
                    StartDate = start,
                    Wbs = wbs,
                    BaselineCost = Math.Max(0.0, task.BaselineCost).ToString("N0", CultureInfo.InvariantCulture),
                    ActualCost = Math.Max(0.0, task.ActualCostToDate).ToString("N0", CultureInfo.InvariantCulture),
                    RemainingCost = Math.Max(0.0, task.RemainingCost).ToString("N0", CultureInfo.InvariantCulture),
                    IsTotal = false
                });
            }

            if (viewMode == PmReportsLookaheadViewMode.Wbs)
            {
                rows = rows
                    .OrderBy(r => r.Wbs ?? "", Comparer<string>.Create(CompareReportsWbs))
                    .ThenBy(r => r.StartDate)
                    .ToList();
            }
            else
            {
                rows = rows
                    .OrderBy(r => r.StartDate)
                    .ThenBy(r => r.Activity, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }

            if (rows.Count > 0)
            {
                rows.Add(new PmReportsLookaheadRow
                {
                    Id = "",
                    Activity = "TOTAL",
                    ActivityDisplay = "TOTAL",
                    Start = "",
                    Finish = "",
                    Actual = "",
                    Remaining = Math.Round(totalRemainingDays, 0).ToString("N0", CultureInfo.InvariantCulture),
                    StartDate = DateTime.MaxValue,
                    Wbs = "",
                    BaselineCost = totalBaselineCost.ToString("N0", CultureInfo.InvariantCulture),
                    ActualCost = totalActualCost.ToString("N0", CultureInfo.InvariantCulture),
                    RemainingCost = totalRemainingCost.ToString("N0", CultureInfo.InvariantCulture),
                    IsTotal = true
                });
            }

            lookaheadPreviewGrid.ItemsSource = rows;
            UpdateLookaheadViewColumns();
        }

        private void RefreshReportsCurveVisuals()
        {
            _reportsCashflowSyncInProgress = true;
            try
            {
                PmDashboardLiveSnapshot snapshot = _reportsLatestSnapshot;
                bool hasData = snapshot != null && snapshot.Tasks.Count > 0;

                PmDashboardTimeGranularity costGranularity = GetSelectedReportGranularity(sCurveGranularityCombo);
                bool costPercentMode = IsPercentModeSelected(sCurveValueModeCombo);
                _reportsSCurvePoints = hasData
                    ? BuildPmDashboardCurvePointsFromSnapshot(snapshot, "Cost", costGranularity, costPercentMode)
                    : new List<PmDashboardCurvePoint>();
                RenderReportsCurvePlot(sCurvePlotView, sCurveChartPlaceholder, _reportsSCurvePoints, costPercentMode, "S-Curve (Cost)");
                if (sCurveDataGrid != null)
                {
                    sCurveDataGrid.ItemsSource = BuildReportsCurveGridRows(_reportsSCurvePoints, costPercentMode);
                }

                PmDashboardTimeGranularity durationGranularity = GetSelectedReportGranularity(durationGranularityCombo);
                bool durationPercentMode = IsPercentModeSelected(durationValueModeCombo);
                _reportsDurationCurvePoints = hasData
                    ? BuildPmDashboardCurvePointsFromSnapshot(snapshot, "Duration", durationGranularity, durationPercentMode)
                    : new List<PmDashboardCurvePoint>();
                RenderReportsCurvePlot(durationPlotView, durationChartPlaceholder, _reportsDurationCurvePoints, durationPercentMode, "S-Curve (Duration)");
                if (durationDataGrid != null)
                {
                    durationDataGrid.ItemsSource = BuildReportsCurveGridRows(_reportsDurationCurvePoints, durationPercentMode);
                }

                PmDashboardTimeGranularity resourceGranularity = GetSelectedReportGranularity(resourceGranularityCombo);
                bool resourcePercentMode = IsPercentModeSelected(resourceValueModeCombo);
                _reportsResourceCurvePoints = hasData
                    ? BuildPmDashboardCurvePointsFromSnapshot(snapshot, "Resource", resourceGranularity, resourcePercentMode)
                    : new List<PmDashboardCurvePoint>();
                RenderReportsCurvePlot(resourcePlotView, resourceChartPlaceholder, _reportsResourceCurvePoints, resourcePercentMode, "S-Curve (Resource)");
                if (resourceDataGrid != null)
                {
                    resourceDataGrid.ItemsSource = BuildReportsCurveGridRows(_reportsResourceCurvePoints, resourcePercentMode);
                }
            }
            finally
            {
                _reportsCashflowSyncInProgress = false;
            }
        }

        private static PmDashboardTimeGranularity GetSelectedReportGranularity(System.Windows.Controls.ComboBox combo)
        {
            string text = GetPmDashboardComboValue(combo, "Monthly");
            if (text.IndexOf("week", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return PmDashboardTimeGranularity.Weekly;
            }
            if (text.IndexOf("day", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return PmDashboardTimeGranularity.Daily;
            }

            return PmDashboardTimeGranularity.Monthly;
        }

        private static bool IsPercentModeSelected(System.Windows.Controls.ComboBox combo)
        {
            string text = GetPmDashboardComboValue(combo, "Amount");
            return string.Equals(text, "Percent", StringComparison.OrdinalIgnoreCase);
        }

        private static List<PmReportsCurveGridRow> BuildReportsCurveGridRows(IEnumerable<PmDashboardCurvePoint> points, bool percentMode)
        {
            var rows = new List<PmReportsCurveGridRow>();
            foreach (PmDashboardCurvePoint point in points ?? Enumerable.Empty<PmDashboardCurvePoint>())
            {
                if (point == null)
                {
                    continue;
                }

                rows.Add(new PmReportsCurveGridRow
                {
                    Period = point.Label ?? "",
                    PVDisplay = FormatReportsCurveValue(point.PeriodPlanned, percentMode),
                    ACDisplay = FormatReportsCurveValue(point.PeriodActualCost, percentMode),
                    EVDisplay = FormatReportsCurveValue(point.PeriodActual, percentMode),
                    ForecastDisplay = FormatReportsCurveValue(point.ForecastCumulative, percentMode),
                    PVTotalDisplay = FormatReportsCurveValue(point.PlannedCumulative, percentMode),
                    ACTotalDisplay = FormatReportsCurveValue(point.ActualCostCumulative, percentMode),
                    EVTotalDisplay = FormatReportsCurveValue(point.ActualCumulative, percentMode),
                    ForecastTotalDisplay = FormatReportsCurveValue(point.ForecastCumulative, percentMode)
                });
            }

            return rows;
        }

        private static string FormatReportsCurveValue(double value, bool percentMode)
        {
            double safe = Math.Max(0.0, value);
            if (percentMode)
            {
                return safe.ToString("0.##", CultureInfo.InvariantCulture) + "%";
            }

            return safe.ToString("N2", CultureInfo.InvariantCulture);
        }

        private void RenderReportsCurvePlot(
            OxyPlot.Wpf.PlotView plotView,
            TextBlock placeholder,
            List<PmDashboardCurvePoint> points,
            bool percentMode,
            string title)
        {
            if (plotView == null)
            {
                return;
            }

            var model = new PlotModel
            {
                Title = title,
                PlotAreaBorderColor = OxyColor.Parse("#D8E0EA"),
                PlotAreaBorderThickness = new OxyThickness(1),
                Background = OxyColor.Parse("#F8FAFD"),
                TextColor = OxyColor.Parse("#3C4B61"),
                IsLegendVisible = true
            };

            if (points == null || points.Count == 0)
            {
                plotView.Model = model;
                if (placeholder != null)
                {
                    placeholder.Visibility = System.Windows.Visibility.Visible;
                }
                return;
            }

            if (placeholder != null)
            {
                placeholder.Visibility = System.Windows.Visibility.Collapsed;
            }

            var xAxis = new CategoryAxis
            {
                Position = AxisPosition.Bottom,
                GapWidth = 0.25,
                Angle = points.Count > 10 ? -30 : 0
            };
            foreach (PmDashboardCurvePoint point in points)
            {
                xAxis.Labels.Add(point?.Label ?? "");
            }

            var yAxis = new LinearAxis
            {
                Position = AxisPosition.Left,
                Minimum = 0,
                LabelFormatter = v => percentMode
                    ? v.ToString("0.##", CultureInfo.InvariantCulture) + "%"
                    : v.ToString("N0", CultureInfo.InvariantCulture)
            };

            var pvSeries = new LineSeries { Title = "PV", Color = OxyColor.Parse("#4E79A7"), StrokeThickness = 2 };
            var acSeries = new LineSeries { Title = "AC", Color = OxyColor.Parse("#E15759"), StrokeThickness = 2 };
            var evSeries = new LineSeries { Title = "EV", Color = OxyColor.Parse("#59A14F"), StrokeThickness = 2 };
            var forecastSeries = new LineSeries
            {
                Title = "Forecast",
                Color = OxyColor.Parse("#F28E2B"),
                StrokeThickness = 2,
                LineStyle = LineStyle.Dash
            };

            for (int i = 0; i < points.Count; i++)
            {
                PmDashboardCurvePoint point = points[i];
                pvSeries.Points.Add(new DataPoint(i, Math.Max(0.0, point.PlannedCumulative)));
                acSeries.Points.Add(new DataPoint(i, Math.Max(0.0, point.ActualCostCumulative)));
                evSeries.Points.Add(new DataPoint(i, Math.Max(0.0, point.ActualCumulative)));
                forecastSeries.Points.Add(new DataPoint(i, Math.Max(0.0, point.ForecastCumulative)));
            }

            model.Axes.Add(xAxis);
            model.Axes.Add(yAxis);
            model.Series.Add(pvSeries);
            model.Series.Add(acSeries);
            model.Series.Add(evSeries);
            model.Series.Add(forecastSeries);
            plotView.Model = model;
        }

        private void RefreshReportsActivityTaskData(PmDashboardLiveSnapshot snapshot)
        {
            if (snapshot == null || snapshot.Tasks.Count == 0)
            {
                _reportsActivityTasks = new List<PmReportsActivityTaskRow>();
                ApplyReportsActivityTaskFilter();
                return;
            }

            DateTime statusDate = snapshot.StatusDate.Date;
            var rows = new List<PmReportsActivityTaskRow>(snapshot.Tasks.Count);

            foreach (PmDashboardTaskSnapshot task in snapshot.Tasks)
            {
                if (task == null)
                {
                    continue;
                }

                string activity = string.IsNullOrWhiteSpace(task.TaskName)
                    ? "Task " + task.TaskId.ToString(CultureInfo.InvariantCulture)
                    : task.TaskName;

                DateTime start = task.TaskStart.Date;
                DateTime finish = task.TaskFinish.Date;
                DateTime baselineStart = task.PlanStart.Date;
                DateTime baselineFinish = task.PlanFinish.Date;
                DateTime actualStart = task.ActualStart.Date;
                DateTime actualFinish = task.ActualFinish.Date;

                double durationDays = Math.Max(0.0, (finish - start).TotalDays + 1.0);
                double baselineDurationDays = Math.Max(0.0, task.BaselineDurationDays);
                if (baselineDurationDays <= 1e-9 && baselineFinish >= baselineStart)
                {
                    baselineDurationDays = (baselineFinish - baselineStart).TotalDays + 1.0;
                }

                double actualDurationDays = Math.Max(0.0, task.ActualDurationDays);
                if (actualDurationDays <= 1e-9)
                {
                    actualDurationDays = baselineDurationDays * Math.Max(0.0, Math.Min(100.0, task.PercentComplete)) / 100.0;
                }

                double totalFloatDays = 0.0;
                double plannedPercent = 0.0;
                if (baselineFinish >= baselineStart)
                {
                    double totalBaselineCalendarDays = (baselineFinish - baselineStart).TotalDays + 1.0;
                    if (totalBaselineCalendarDays > 0.0)
                    {
                        double elapsed;
                        if (statusDate < baselineStart)
                        {
                            elapsed = 0.0;
                        }
                        else if (statusDate > baselineFinish)
                        {
                            elapsed = totalBaselineCalendarDays;
                        }
                        else
                        {
                            elapsed = (statusDate - baselineStart).TotalDays + 1.0;
                        }

                        plannedPercent = (elapsed / totalBaselineCalendarDays) * 100.0;
                    }
                }

                double slipDays = (IsValidPmDashboardProjectDate(finish) && IsValidPmDashboardProjectDate(baselineFinish))
                    ? (finish - baselineFinish).TotalDays
                    : 0.0;

                rows.Add(new PmReportsActivityTaskRow
                {
                    Id = task.TaskId > 0 ? task.TaskId.ToString(CultureInfo.InvariantCulture) : "",
                    Activity = activity,
                    PercentComplete = FormatReportsPercent(task.PercentComplete),
                    PlannedPercent = FormatReportsPercent(plannedPercent),
                    Start = FormatReportsShortDate(start),
                    Finish = FormatReportsShortDate(finish),
                    Duration = FormatReportsDurationToken(durationDays),
                    TotalFloat = FormatReportsDurationToken(totalFloatDays),
                    BaselineStart = FormatReportsShortDate(baselineStart),
                    BaselineFinish = FormatReportsShortDate(baselineFinish),
                    BaselineDuration = FormatReportsDurationToken(baselineDurationDays),
                    Slip = FormatReportsDurationToken(slipDays),
                    PercentCompleteValue = task.PercentComplete,
                    PlannedPercentValue = plannedPercent,
                    StartDate = start,
                    FinishDate = finish,
                    BaselineStartDate = baselineStart,
                    BaselineFinishDate = baselineFinish,
                    ActualStartDate = actualStart,
                    ActualFinishDate = actualFinish,
                    DurationDays = durationDays,
                    BaselineDurationDays = baselineDurationDays,
                    ActualDurationDays = actualDurationDays,
                    TotalFloatDays = totalFloatDays,
                    SlipDays = slipDays
                });
            }

            _reportsActivityTasks = rows;
            ApplyReportsActivityTaskFilter();
        }

        private void ApplyReportsActivityTaskFilter()
        {
            PmReportsActivityTaskFilterMode filter = GetSelectedActivityTaskFilterMode();
            DateTime statusDate = _reportsLatestSnapshot?.StatusDate.Date ?? DateTime.Today;
            DateTime weekStart = GetReportsWeekStart(statusDate);
            DateTime weekEnd = weekStart.AddDays(6);

            IEnumerable<PmReportsActivityTaskRow> filtered = _reportsActivityTasks ?? Enumerable.Empty<PmReportsActivityTaskRow>();
            filtered = filtered.Where(row =>
            {
                if (row == null)
                {
                    return false;
                }

                double pc = row.PercentCompleteValue;
                bool completed = pc >= 99.99;
                bool started = pc > 0.0;

                switch (filter)
                {
                    case PmReportsActivityTaskFilterMode.Completed:
                        return completed;
                    case PmReportsActivityTaskFilterMode.InProgress:
                        return started && !completed;
                    case PmReportsActivityTaskFilterMode.NotStarted:
                        return pc <= 0.0;
                    case PmReportsActivityTaskFilterMode.StartLate:
                        return row.StartDate > row.BaselineStartDate;
                    case PmReportsActivityTaskFilterMode.TookLonger:
                        return completed && row.ActualDurationDays > row.BaselineDurationDays + 0.01;
                    case PmReportsActivityTaskFilterMode.FinishedLater:
                        return completed && row.ActualFinishDate > row.BaselineFinishDate;
                    case PmReportsActivityTaskFilterMode.FinishedEarlier:
                        return completed && row.ActualFinishDate < row.BaselineFinishDate;
                    case PmReportsActivityTaskFilterMode.FinishedOnTime:
                        return completed && row.ActualFinishDate == row.BaselineFinishDate;
                    case PmReportsActivityTaskFilterMode.TookLess:
                        return completed && row.ActualDurationDays > 0.0 && row.ActualDurationDays < row.BaselineDurationDays - 0.01;
                    case PmReportsActivityTaskFilterMode.StartingThisWeek:
                        return row.StartDate >= weekStart && row.StartDate <= weekEnd;
                    case PmReportsActivityTaskFilterMode.FinishingThisWeek:
                        return row.FinishDate >= weekStart && row.FinishDate <= weekEnd;
                    case PmReportsActivityTaskFilterMode.InProgressThisWeek:
                        return started && !completed && row.StartDate <= weekEnd && row.FinishDate >= weekStart;
                    default:
                        return true;
                }
            });

            _reportsFilteredActivityTasks = filtered.ToList();
            if (activityTaskGrid != null)
            {
                activityTaskGrid.ItemsSource = _reportsFilteredActivityTasks;
            }
        }

        private PmReportsActivityTaskFilterMode GetSelectedActivityTaskFilterMode()
        {
            if (activityTaskFilterCombo?.SelectedItem is ComboBoxItem item)
            {
                string tag = (item.Tag ?? "").ToString();
                if (!string.IsNullOrWhiteSpace(tag) &&
                    Enum.TryParse(tag, true, out PmReportsActivityTaskFilterMode parsed))
                {
                    return parsed;
                }
            }

            return PmReportsActivityTaskFilterMode.AllTasks;
        }

        private static DateTime GetReportsWeekStart(DateTime date)
        {
            int diff = (7 + (date.DayOfWeek - DayOfWeek.Monday)) % 7;
            return date.Date.AddDays(-diff);
        }

        private List<PmReportsActivityTaskRow> GetFilteredActivityTasks()
        {
            return (_reportsFilteredActivityTasks ?? new List<PmReportsActivityTaskRow>())
                .Where(row => row != null)
                .ToList();
        }

        private static string FormatReportsPercent(double value)
        {
            return Math.Max(0.0, Math.Min(100.0, value)).ToString("0.##", CultureInfo.InvariantCulture) + "%";
        }

        private static string FormatReportsDurationToken(double days)
        {
            double rounded = Math.Round(days, 1);
            if (Math.Abs(rounded - Math.Round(rounded)) < 0.05)
            {
                return Math.Round(rounded).ToString("N0", CultureInfo.InvariantCulture) + "d";
            }

            return rounded.ToString("0.0", CultureInfo.InvariantCulture) + "d";
        }

        private static string FormatReportsShortDate(DateTime date)
        {
            if (!IsValidPmDashboardProjectDate(date))
            {
                return "-";
            }

            return date.ToString("dd-MMM-yy", CultureInfo.InvariantCulture);
        }

        private static string FormatReportsSignedDays(int days)
        {
            return days.ToString("N0", CultureInfo.InvariantCulture) + " Days";
        }

        private static string FormatReportsValue(double value, PmReportsProgressMode mode)
        {
            if (mode == PmReportsProgressMode.Cost)
            {
                return "$" + value.ToString("N2", CultureInfo.InvariantCulture);
            }

            double rounded = Math.Round(value, 1);
            if (Math.Abs(rounded - Math.Round(rounded)) < 0.05)
            {
                return Math.Round(rounded).ToString("N0", CultureInfo.InvariantCulture) + " Days";
            }

            return rounded.ToString("0.0", CultureInfo.InvariantCulture) + " Days";
        }

        private void UpdateReportsProgressReport(PmDashboardLiveSnapshot snapshot)
        {
            if (snapshot == null || snapshot.Tasks.Count == 0)
            {
                _reportsProgressCostContent = null;
                _reportsProgressDurationContent = null;
                UpdateProgressReportView();
                return;
            }

            PmReportsProgressMetrics costMetrics = BuildReportsProgressMetrics(snapshot, PmReportsProgressMode.Cost);
            PmReportsProgressMetrics durationMetrics = BuildReportsProgressMetrics(snapshot, PmReportsProgressMode.Duration);
            _reportsProgressCostContent = BuildReportsProgressReportContent(snapshot, PmReportsProgressMode.Cost, costMetrics, durationMetrics);
            _reportsProgressDurationContent = BuildReportsProgressReportContent(snapshot, PmReportsProgressMode.Duration, durationMetrics, durationMetrics);
            UpdateProgressReportView();
        }

        private PmReportsProgressMetrics BuildReportsProgressMetrics(PmDashboardLiveSnapshot snapshot, PmReportsProgressMode mode)
        {
            var metrics = new PmReportsProgressMetrics();
            if (snapshot == null)
            {
                return metrics;
            }

            if (mode == PmReportsProgressMode.Cost)
            {
                double plannedTotal = Math.Max(0.0, snapshot.Bac);
                double forecastTotal = Math.Max(0.0, snapshot.AcToDate + snapshot.RemainingCost);
                if (forecastTotal <= 1e-9)
                {
                    forecastTotal = Math.Max(plannedTotal, snapshot.EvToDate);
                }
                if (plannedTotal <= 1e-9)
                {
                    plannedTotal = Math.Max(forecastTotal, snapshot.PvToDate);
                }

                metrics.ActualToDate = Math.Max(0.0, snapshot.AcToDate);
                metrics.BaselineToDate = Math.Max(0.0, snapshot.PvToDate);
                metrics.ForecastTotal = Math.Max(0.0, forecastTotal);
                metrics.PlannedTotal = Math.Max(0.0, plannedTotal);
            }
            else
            {
                double plannedTotal = Math.Max(0.0, snapshot.BaselineDurationTotalDays);
                if (plannedTotal <= 1e-9)
                {
                    plannedTotal = Math.Max(1.0, (snapshot.ProjectFinish.Date - snapshot.ProjectStart.Date).TotalDays + 1.0);
                }

                metrics.ActualToDate = Math.Max(0.0, snapshot.EarnedDurationToDateDays);
                metrics.BaselineToDate = Math.Max(0.0, snapshot.PlannedDurationToDateDays);
                metrics.ForecastTotal = Math.Max(plannedTotal, metrics.ActualToDate);
                metrics.PlannedTotal = plannedTotal;
            }

            metrics.ActualPercent = metrics.ForecastTotal > 1e-9
                ? (metrics.ActualToDate / metrics.ForecastTotal) * 100.0
                : 0.0;
            metrics.PlannedPercent = metrics.PlannedTotal > 1e-9
                ? (metrics.BaselineToDate / metrics.PlannedTotal) * 100.0
                : 0.0;
            metrics.PercentVariance = metrics.ActualPercent - metrics.PlannedPercent;
            metrics.Ptq = metrics.PlannedPercent > 1e-9
                ? (metrics.ActualPercent / metrics.PlannedPercent) * 100.0
                : 0.0;
            metrics.SlipDays = (int)Math.Round(metrics.BaselineToDate - metrics.ActualToDate);
            metrics.BaselineDateForActual = EstimateReportsBaselineDateForValue(snapshot, metrics.ActualToDate, mode);
            return metrics;
        }

        private static DateTime? EstimateReportsBaselineDateForValue(
            PmDashboardLiveSnapshot snapshot,
            double actualValue,
            PmReportsProgressMode mode)
        {
            if (snapshot == null)
            {
                return null;
            }

            DateTime start = snapshot.ProjectStart.Date;
            DateTime finish = snapshot.ProjectFinish.Date;
            if (!IsValidPmDashboardProjectDate(start) || !IsValidPmDashboardProjectDate(finish) || finish < start)
            {
                return null;
            }

            double total;
            if (mode == PmReportsProgressMode.Cost)
            {
                total = Math.Max(0.0, snapshot.Bac);
                if (total <= 1e-9)
                {
                    total = Math.Max(0.0, snapshot.PvToDate);
                }
            }
            else
            {
                total = Math.Max(0.0, snapshot.BaselineDurationTotalDays);
            }

            if (total <= 1e-9)
            {
                return null;
            }

            double ratio = Math.Max(0.0, Math.Min(1.0, actualValue / total));
            double totalDays = Math.Max(0.0, (finish - start).TotalDays);
            return start.AddDays(Math.Round(totalDays * ratio)).Date;
        }

        private PmReportsProgressReportContent BuildReportsProgressReportContent(
            PmDashboardLiveSnapshot snapshot,
            PmReportsProgressMode mode,
            PmReportsProgressMetrics metrics,
            PmReportsProgressMetrics durationMetrics)
        {
            string projectName = string.IsNullOrWhiteSpace(snapshot?.ProjectName)
                ? "CamboBIM"
                : snapshot.ProjectName.Trim();
            DateTime statusDate = snapshot?.StatusDate.Date ?? DateTime.Today;
            DateTime forecastFinish = snapshot?.ProjectFinish.Date ?? statusDate;
            DateTime plannedFinish = snapshot?.ProjectFinish.Date ?? statusDate;

            var content = new PmReportsProgressReportContent
            {
                Title = "Project Progress Report (" + (mode == PmReportsProgressMode.Duration ? "Duration" : "Cost") + ") " + projectName,
                ReportDate = "Project Progress Report " + statusDate.ToString("dddd, MMMM dd, yyyy", CultureInfo.InvariantCulture),
                SummaryActual = FormatReportsValue(metrics.ActualToDate, mode),
                SummaryBaseline = FormatReportsValue(metrics.BaselineToDate, mode),
                SummaryVariance = FormatReportsValue(metrics.ActualToDate - metrics.BaselineToDate, mode),
                SummaryPercentComplete = FormatReportsPercent(metrics.ActualPercent),
                SummaryPlannedPercent = FormatReportsPercent(metrics.PlannedPercent),
                SummaryPercentVariance = FormatReportsPercent(metrics.PercentVariance),
                SummaryPtq = FormatReportsPercent(metrics.Ptq),
                SummarySlip = FormatReportsSignedDays(metrics.SlipDays),
                ForecastFinishDate = FormatReportsShortDate(forecastFinish),
                PlannedFinishDate = FormatReportsShortDate(plannedFinish),
                ProjectSlip = FormatReportsSignedDays((int)Math.Round((forecastFinish - plannedFinish).TotalDays)),
                ForecastTotal = FormatReportsValue(metrics.ForecastTotal, mode),
                PlannedTotal = FormatReportsValue(metrics.PlannedTotal, mode),
                ProjectGrowth = FormatReportsValue(metrics.ForecastTotal - metrics.PlannedTotal, mode)
            };

            double growth = metrics.ForecastTotal - metrics.PlannedTotal;
            double growthPct = metrics.PlannedTotal > 1e-9
                ? ((metrics.ForecastTotal / metrics.PlannedTotal) - 1.0) * 100.0
                : 0.0;

            content.SCurveLine1 = growth > 0.01
                ? "- The project has grown in scope. (Forecast is above Baseline)"
                : "- The project has not grown in scope. (Forecast is aligned with Baseline)";
            content.SCurveLine2 = metrics.SlipDays > 0
                ? "- The project is behind schedule at data date."
                : (metrics.SlipDays < 0 ? "- The project is ahead of schedule at data date." : "- The project is on schedule at data date.");
            content.SCurveLine3 = metrics.PercentVariance >= 0
                ? "- Actual progress line is above baseline at data date."
                : "- Actual progress line is below baseline at data date.";

            content.GrowthLine1 = "The project has grown in scope by " + FormatReportsValue(growth, mode) +
                                  ", or " + FormatReportsPercent(growthPct) + ".";
            content.GrowthLine2 = "Growth = Forecast - Baseline = " +
                                  FormatReportsValue(metrics.ForecastTotal, mode) + " - " +
                                  FormatReportsValue(metrics.PlannedTotal, mode) + ".";
            content.GrowthLine3 = "Growth % = (Forecast / Baseline - 1) x 100%.";

            content.SlipLine1 = metrics.SlipDays == 0
                ? "There has been no change in project duration."
                : "There is a schedule shift of " + Math.Abs(metrics.SlipDays).ToString("N0", CultureInfo.InvariantCulture) + " days.";
            content.SlipLine2 = "Slippage = Forecast Duration - Baseline Duration.";
            content.SlipLine3 = "Slippage % is reflected by planned vs actual pace.";

            content.ToDateLine1 = "Actual complete at data date: " + FormatReportsPercent(metrics.ActualPercent) +
                                  ". Planned complete: " + FormatReportsPercent(metrics.PlannedPercent) + ".";
            content.ToDateLine2 = "Actual total to date: " + FormatReportsValue(metrics.ActualToDate, mode) + ".";
            content.ToDateLine3 = "Baseline total to date: " + FormatReportsValue(metrics.BaselineToDate, mode) + ".";
            if (metrics.BaselineDateForActual.HasValue)
            {
                content.ToDateLine4 = "The actual total should have been achieved by " +
                                      FormatReportsShortDate(metrics.BaselineDateForActual.Value) + ".";
                content.ToDateLine5 = "Data date (" + FormatReportsShortDate(statusDate) +
                                      ") - baseline date (" + FormatReportsShortDate(metrics.BaselineDateForActual.Value) +
                                      ") = " + Math.Abs(metrics.SlipDays).ToString("N0", CultureInfo.InvariantCulture) + " Days.";
            }
            else
            {
                content.ToDateLine4 = "No baseline reference date is available.";
                content.ToDateLine5 = "";
            }

            double variance = Math.Abs(metrics.PercentVariance);
            content.ForecastLine1 = "At the data date the project had " +
                                    (metrics.PercentVariance >= 0 ? "accelerated" : "delayed") +
                                    " by " + FormatReportsPercent(variance) + ".";
            content.ForecastLine2 = "As a result the project is forecasted to complete on " +
                                    FormatReportsShortDate(forecastFinish) + ".";

            if (mode == PmReportsProgressMode.Cost && durationMetrics != null)
            {
                content.SummarySlip = FormatReportsSignedDays(durationMetrics.SlipDays);
            }

            return content;
        }

        private PmReportsProgressMode GetSelectedProgressReportMode()
        {
            string text = GetPmDashboardComboValue(progressReportModeCombo, "Cost");
            return string.Equals(text, "Duration", StringComparison.OrdinalIgnoreCase)
                ? PmReportsProgressMode.Duration
                : PmReportsProgressMode.Cost;
        }

