        private string BuildActivityTaskText(IReadOnlyList<PmReportsActivityTaskRow> rows)
        {
            var sb = new StringBuilder();
            sb.AppendLine("Activity ID\tName\tPercent Complete\tPlanned %\tStart\tFinish\tDuration\tTotal Float\tBaseline Start\tBaseline Finish\tBaseline Duration\tSlip");
            foreach (PmReportsActivityTaskRow row in rows ?? Array.Empty<PmReportsActivityTaskRow>())
            {
                if (row == null) continue;
                sb.Append(row.Id).Append('\t')
                  .Append(row.Activity).Append('\t')
                  .Append(row.PercentComplete).Append('\t')
                  .Append(row.PlannedPercent).Append('\t')
                  .Append(row.Start).Append('\t')
                  .Append(row.Finish).Append('\t')
                  .Append(row.Duration).Append('\t')
                  .Append(row.TotalFloat).Append('\t')
                  .Append(row.BaselineStart).Append('\t')
                  .Append(row.BaselineFinish).Append('\t')
                  .Append(row.BaselineDuration).Append('\t')
                  .Append(row.Slip)
                  .AppendLine();
            }

            return sb.ToString();
        }

