        private string BuildProgressReportCsv(PmReportsProgressReportContent content)
        {
            var sb = new StringBuilder();
            sb.AppendLine("section,item,value");
            void append(string section, string item, string value)
            {
                sb.Append(EscapeCsv(section)).Append(',')
                  .Append(EscapeCsv(item)).Append(',')
                  .Append(EscapeCsv(value ?? ""))
                  .AppendLine();
            }

            append("Header", "Title", content.Title);
            append("Header", "Date", content.ReportDate);
            append("Summary", "Actual", content.SummaryActual);
            append("Summary", "Baseline", content.SummaryBaseline);
            append("Summary", "Variance", content.SummaryVariance);
            append("Summary", "Percent Complete", content.SummaryPercentComplete);
            append("Summary", "Planned Percent Complete", content.SummaryPlannedPercent);
            append("Summary", "Percent Variance", content.SummaryPercentVariance);
            append("Summary", "PTQ", content.SummaryPtq);
            append("Summary", "Slip", content.SummarySlip);
            append("Forecast", "Forecast Finish Date", content.ForecastFinishDate);
            append("Forecast", "Planned Finish Date", content.PlannedFinishDate);
            append("Forecast", "Project Slip", content.ProjectSlip);
            append("Forecast", "Forecast Total", content.ForecastTotal);
            append("Forecast", "Planned Total", content.PlannedTotal);
            append("Forecast", "Project Growth", content.ProjectGrowth);
            append("Analysis", "SCurve 1", content.SCurveLine1);
            append("Analysis", "SCurve 2", content.SCurveLine2);
            append("Analysis", "SCurve 3", content.SCurveLine3);
            append("Analysis", "Growth 1", content.GrowthLine1);
            append("Analysis", "Growth 2", content.GrowthLine2);
            append("Analysis", "Growth 3", content.GrowthLine3);
            append("Analysis", "Slip 1", content.SlipLine1);
            append("Analysis", "Slip 2", content.SlipLine2);
            append("Analysis", "Slip 3", content.SlipLine3);
            append("Analysis", "ToDate 1", content.ToDateLine1);
            append("Analysis", "ToDate 2", content.ToDateLine2);
            append("Analysis", "ToDate 3", content.ToDateLine3);
            append("Analysis", "ToDate 4", content.ToDateLine4);
            append("Analysis", "ToDate 5", content.ToDateLine5);
            append("Analysis", "Forecast 1", content.ForecastLine1);
            append("Analysis", "Forecast 2", content.ForecastLine2);
            return sb.ToString();
        }

        private void ExportProgressReportToCsv(PmReportsProgressReportContent content)
        {
            if (content == null)
            {
                ShowStatus("Progress Report: no data to export.");
                return;
            }

            var dialog = new SaveFileDialog
            {
                Title = "Export Progress Report",
                Filter = "CSV files (*.csv)|*.csv|All files (*.*)|*.*",
                FileName = "progress_report_" + DateTime.Now.ToString("yyyyMMdd_HHmm", CultureInfo.InvariantCulture) + ".csv",
                OverwritePrompt = true
            };
            bool? accepted = dialog.ShowDialog(this);
            if (accepted != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            File.WriteAllText(dialog.FileName, BuildProgressReportCsv(content), new UTF8Encoding(false));
            ShowStatus("Progress Report exported: " + dialog.FileName);
        }

        private void ExportTasksToCsv()
        {
            if (_reportsActivityTasks == null || _reportsActivityTasks.Count == 0)
            {
                ShowStatus("Export Tasks: no task rows available.");
                return;
            }

            var table = new DataTable("tasks");
            table.Columns.Add("task_id", typeof(string));
            table.Columns.Add("task_name", typeof(string));
            table.Columns.Add("percent_complete", typeof(string));
            table.Columns.Add("planned_percent", typeof(string));
            table.Columns.Add("start", typeof(string));
            table.Columns.Add("finish", typeof(string));
            table.Columns.Add("duration", typeof(string));
            table.Columns.Add("baseline_start", typeof(string));
            table.Columns.Add("baseline_finish", typeof(string));
            table.Columns.Add("baseline_duration", typeof(string));
            table.Columns.Add("slip", typeof(string));

            foreach (PmReportsActivityTaskRow row in _reportsActivityTasks)
            {
                if (row == null) continue;
                DataRow dr = table.NewRow();
                dr["task_id"] = row.Id ?? "";
                dr["task_name"] = row.Activity ?? "";
                dr["percent_complete"] = row.PercentComplete ?? "";
                dr["planned_percent"] = row.PlannedPercent ?? "";
                dr["start"] = row.Start ?? "";
                dr["finish"] = row.Finish ?? "";
                dr["duration"] = row.Duration ?? "";
                dr["baseline_start"] = row.BaselineStart ?? "";
                dr["baseline_finish"] = row.BaselineFinish ?? "";
                dr["baseline_duration"] = row.BaselineDuration ?? "";
                dr["slip"] = row.Slip ?? "";
                table.Rows.Add(dr);
            }

            ExportDataTableToCsv(table, "tasks_export", "Export Tasks");
        }

        private void ExportCalendarSummaryToCsv()
        {
            PmDashboardLiveSnapshot snapshot = _reportsLatestSnapshot;
            if (snapshot == null || snapshot.Tasks.Count == 0)
            {
                ShowStatus("Export Calendar: no live PM data.");
                return;
            }

            DateTime start = snapshot.ProjectStart.Date;
            DateTime finish = snapshot.ProjectFinish.Date;
            if (!IsValidPmDashboardProjectDate(start) || !IsValidPmDashboardProjectDate(finish) || finish < start)
            {
                start = snapshot.StatusDate.Date;
                finish = snapshot.StatusDate.Date;
            }

            var table = new DataTable("calendar");
            table.Columns.Add("date", typeof(string));
            table.Columns.Add("day_of_week", typeof(string));
            table.Columns.Add("is_weekend", typeof(string));

            for (DateTime day = start; day <= finish; day = day.AddDays(1))
            {
                DataRow row = table.NewRow();
                row["date"] = day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
                row["day_of_week"] = day.DayOfWeek.ToString();
                row["is_weekend"] = (day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday) ? "Yes" : "No";
                table.Rows.Add(row);
            }

            ExportDataTableToCsv(table, "calendar_export", "Export Calendar");
        }

        private void ExportDataGridToCsv(DataGrid grid, string filePrefix, string title)
        {
            if (grid == null)
            {
                ShowStatus(title + ": view is not ready.");
                return;
            }

            DataTable table = BuildDataTableFromDataGrid(grid, filePrefix);
            if (table == null || table.Rows.Count == 0)
            {
                ShowStatus(title + ": no rows to export.");
                return;
            }

            ExportDataTableToCsv(table, filePrefix, title);
        }

        private void ExportDataTableToCsv(DataTable table, string filePrefix, string title)
        {
            if (table == null || table.Rows.Count == 0)
            {
                ShowStatus(title + ": no data to export.");
                return;
            }

            string safePrefix = string.IsNullOrWhiteSpace(filePrefix) ? "export" : filePrefix.Trim();
            var dialog = new SaveFileDialog
            {
                Title = title,
                Filter = "CSV files (*.csv)|*.csv|All files (*.*)|*.*",
                FileName = safePrefix + "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture) + ".csv",
                OverwritePrompt = true
            };

            bool? accepted = dialog.ShowDialog(this);
            if (accepted != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            WriteDataTableToCsv(table, dialog.FileName);
            ShowStatus(title + ": exported " + table.Rows.Count.ToString(CultureInfo.InvariantCulture) + " row(s) to " + dialog.FileName);
        }

        private static DataTable BuildDataTableFromDataGrid(DataGrid grid, string tableName)
        {
            if (grid == null || grid.ItemsSource == null)
            {
                return null;
            }

            var columns = new List<(string Header, string Path)>();
            foreach (DataGridColumn column in grid.Columns)
            {
                if (column == null || column.Visibility != System.Windows.Visibility.Visible)
                {
                    continue;
                }

                if (!(column is DataGridBoundColumn boundColumn) || !(boundColumn.Binding is System.Windows.Data.Binding binding))
                {
                    continue;
                }

                string header = Convert.ToString(column.Header, CultureInfo.InvariantCulture) ?? "";
                string path = binding.Path?.Path ?? "";
                if (string.IsNullOrWhiteSpace(path))
                {
                    continue;
                }

                columns.Add((string.IsNullOrWhiteSpace(header) ? path : header.Trim(), path.Trim()));
            }

            if (columns.Count == 0)
            {
                return null;
            }

            var table = new DataTable(string.IsNullOrWhiteSpace(tableName) ? "export" : tableName.Trim());
            foreach ((string Header, string Path) column in columns)
            {
                string header = column.Header;
                string baseHeader = header;
                int duplicate = 2;
                while (table.Columns.Contains(header))
                {
                    header = baseHeader + "_" + duplicate.ToString(CultureInfo.InvariantCulture);
                    duplicate++;
                }

                table.Columns.Add(header, typeof(string));
            }

            foreach (object item in grid.ItemsSource)
            {
                if (item == null)
                {
                    continue;
                }

                DataRow row = table.NewRow();
                for (int i = 0; i < columns.Count; i++)
                {
                    object value = ReadObjectPathValue(item, columns[i].Path);
                    row[i] = ConvertToCsvCellText(value);
                }

                table.Rows.Add(row);
            }

            return table;
        }

        private static object ReadObjectPathValue(object item, string path)
        {
            if (item == null || string.IsNullOrWhiteSpace(path))
            {
                return null;
            }

            if (item is DataRowView rowView)
            {
                return rowView.Row.Table.Columns.Contains(path) ? rowView[path] : null;
            }

            object current = item;
            foreach (string part in path.Split('.'))
            {
                if (current == null)
                {
                    return null;
                }

                string name = (part ?? "").Trim();
                if (string.IsNullOrWhiteSpace(name))
                {
                    return null;
                }

                PropertyInfo prop = current.GetType().GetProperty(name, BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase);
                if (prop == null)
                {
                    return null;
                }

                current = prop.GetValue(current, null);
            }

            return current;
        }

        private static string ConvertToCsvCellText(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return "";
            }

            if (value is DateTime dt)
            {
                return dt.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
            }

            return Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
        }

        private void PrintVisualControl(System.Windows.Media.Visual visual, string title)
        {
            if (visual == null)
            {
                ShowStatus(title + ": no visual available.");
                return;
            }

            try
            {
                var dialog = new PrintDialog();
                bool? accepted = dialog.ShowDialog();
                if (accepted != true)
                {
                    return;
                }

                if (visual is FrameworkElement element)
                {
                    element.UpdateLayout();
                }

                dialog.PrintVisual(visual, title);
                ShowStatus(title + ": sent to printer/PDF.");
            }
            catch (Exception ex)
            {
                ShowStatus(title + ": print failed - " + ex.Message);
            }
        }

        private void RefreshReportsDashboardAndQuality(PmDashboardLiveSnapshot snapshot)
        {
            UpdateReportsDashboardVisuals(snapshot);
            UpdateReportsQualityVisuals(snapshot);
        }

        private void UpdateReportsDashboardVisuals(PmDashboardLiveSnapshot snapshot)
        {
            int total = snapshot?.Tasks?.Count ?? 0;
            if (dashboardTitleText != null)
            {
                string projectName = string.IsNullOrWhiteSpace(snapshot?.ProjectName) ? "Dashboard Report" : "Dashboard Report - " + snapshot.ProjectName;
                dashboardTitleText.Text = projectName;
            }

            PmReportsPieStatus startStatus = BuildStartStatus(snapshot);
            PmReportsPieStatus finishStatus = BuildFinishStatus(snapshot);
            PmReportsPieStatus durationStatus = BuildDurationStatus(snapshot);
            PmReportsPieStatus progressStatus = BuildProgressStatus(snapshot);
            PmReportsPieStatus workStatus = BuildWorkStatus(snapshot);
            PmReportsPieStatus costStatus = BuildCostStatus(snapshot);

            RenderReportsPiePlot(dashboardStartPlot, "Start", startStatus, "#009900", "#FFCC00", "#CC0000");
            RenderReportsPiePlot(dashboardFinishPlot, "Finish", finishStatus, "#009900", "#FFCC00", "#CC0000");
            RenderReportsPiePlot(dashboardDurationPlot, "Duration", durationStatus, "#009900", "#FFCC00", "#CC0000");
            RenderReportsPiePlot(dashboardProgressPlot, "Progress", progressStatus, "#009900", "#FFCC00", "#0066CC");
            RenderReportsPiePlot(dashboardWorkPlot, "Work", workStatus, "#009900", "#FFCC00", "#CC0000");
            RenderReportsPiePlot(dashboardCostPlot, "Cost", costStatus, "#009900", "#FFCC00", "#CC0000");

            SetLegendText(dashboardStartLegend1, "Start On Time", startStatus.FirstCount, total);
            SetLegendText(dashboardStartLegend2, "Start Early", startStatus.SecondCount, total);
            SetLegendText(dashboardStartLegend3, "Start Late", startStatus.ThirdCount, total);

            SetLegendText(dashboardFinishLegend1, "Finish On Time", finishStatus.FirstCount, total);
            SetLegendText(dashboardFinishLegend2, "Finish Early", finishStatus.SecondCount, total);
            SetLegendText(dashboardFinishLegend3, "Finish Late", finishStatus.ThirdCount, total);

            SetLegendText(dashboardDurationLegend1, "As Planned", durationStatus.FirstCount, total);
            SetLegendText(dashboardDurationLegend2, "Shorter", durationStatus.SecondCount, total);
            SetLegendText(dashboardDurationLegend3, "Longer", durationStatus.ThirdCount, total);

            SetLegendText(dashboardProgressLegend1, "Complete", progressStatus.FirstCount, total);
            SetLegendText(dashboardProgressLegend2, "In Progress", progressStatus.SecondCount, total);
            SetLegendText(dashboardProgressLegend3, "Not Started", progressStatus.ThirdCount, total);

            SetLegendText(dashboardWorkLegend1, "On Budget", workStatus.FirstCount, total);
            SetLegendText(dashboardWorkLegend2, "Under Budget", workStatus.SecondCount, total);
            SetLegendText(dashboardWorkLegend3, "Over Budget", workStatus.ThirdCount, total);

            SetLegendText(dashboardCostLegend1, "On Budget", costStatus.FirstCount, total);
            SetLegendText(dashboardCostLegend2, "Under Budget", costStatus.SecondCount, total);
            SetLegendText(dashboardCostLegend3, "Over Budget", costStatus.ThirdCount, total);
        }

        private void UpdateReportsQualityVisuals(PmDashboardLiveSnapshot snapshot)
        {
            int total = snapshot?.Tasks?.Count ?? 0;
            if (projectQualityTitleText != null)
            {
                string projectName = string.IsNullOrWhiteSpace(snapshot?.ProjectName) ? "Project Quality Report" : "Project Quality Report - " + snapshot.ProjectName;
                projectQualityTitleText.Text = projectName;
            }

            int missingBaselines = 0;
            int invalidDates = 0;
            int highDuration = 0;
            int noResources = 0;
            int onDataDate = 0;
            if (snapshot != null)
            {
                DateTime status = snapshot.StatusDate.Date;
                foreach (PmDashboardTaskSnapshot task in snapshot.Tasks)
                {
                    if (task == null)
                    {
                        continue;
                    }

                    bool missingBaseline = !IsValidPmDashboardProjectDate(task.PlanStart) ||
                                           !IsValidPmDashboardProjectDate(task.PlanFinish) ||
                                           task.PlanFinish < task.PlanStart ||
                                           task.BaselineDurationDays <= 1e-9;
                    if (missingBaseline)
                    {
                        missingBaselines++;
                    }

                    if (!IsValidPmDashboardProjectDate(task.TaskStart) ||
                        !IsValidPmDashboardProjectDate(task.TaskFinish) ||
                        task.TaskFinish < task.TaskStart)
                    {
                        invalidDates++;
                    }

                    if (task.BaselineDurationDays > 30.0)
                    {
                        highDuration++;
                    }

                    if (task.BaselineWorkDays <= 1e-9 && task.ActualWorkDays <= 1e-9)
                    {
                        noResources++;
                    }

                    if (IsValidPmDashboardProjectDate(task.TaskStart) &&
                        IsValidPmDashboardProjectDate(task.TaskFinish) &&
                        task.TaskStart.Date <= status &&
                        task.TaskFinish.Date >= status)
                    {
                        onDataDate++;
                    }
                }
            }

            SetQualityText(qualityMissingBaselines, missingBaselines, total);
            SetQualityText(qualityMissingPredecessors, 0, total);
            SetQualityText(qualityMissingSuccessors, 0, total);
            SetQualityText(qualityMissingLogic, 0, total);
            SetQualityText(qualityLeadLogic, 0, total);
            SetQualityText(qualityLagLogic, 0, total);
            SetQualityText(qualityNonFinishStart, 0, total);
            SetQualityText(qualityHighFloat, 0, total);
            SetQualityText(qualityNegativeFloat, 0, total);
            SetQualityText(qualityHighDuration, highDuration, total);
            SetQualityText(qualityInvalidDates, invalidDates, total);
            SetQualityText(qualityOnDataDate, onDataDate, total);
            SetQualityText(qualityNoResources, noResources, total);
            SetQualityText(qualityConstraints, 0, total);
        }

        private static void SetLegendText(TextBlock textBlock, string label, int count, int total)
        {
            if (textBlock == null)
            {
                return;
            }

            double pct = total > 0 ? (count * 100.0 / total) : 0.0;
            textBlock.Text = label + " - " + pct.ToString("0.#", CultureInfo.InvariantCulture) + "%";
        }

        private static void SetQualityText(TextBlock textBlock, int count, int total)
        {
            if (textBlock == null)
            {
                return;
            }

            double pct = total > 0 ? (count * 100.0 / total) : 0.0;
            textBlock.Text = count.ToString(CultureInfo.InvariantCulture) + " - " + pct.ToString("0.#", CultureInfo.InvariantCulture) + "%";
        }

        private static PmReportsPieStatus BuildStartStatus(PmDashboardLiveSnapshot snapshot)
        {
            var status = new PmReportsPieStatus();
            foreach (PmDashboardTaskSnapshot task in snapshot?.Tasks ?? Enumerable.Empty<PmDashboardTaskSnapshot>())
            {
                if (task == null)
                {
                    continue;
                }

                if (task.TaskStart.Date == task.PlanStart.Date) status.FirstCount++;
                else if (task.TaskStart.Date < task.PlanStart.Date) status.SecondCount++;
                else status.ThirdCount++;
            }

            return status;
        }

        private static PmReportsPieStatus BuildFinishStatus(PmDashboardLiveSnapshot snapshot)
        {
            var status = new PmReportsPieStatus();
            foreach (PmDashboardTaskSnapshot task in snapshot?.Tasks ?? Enumerable.Empty<PmDashboardTaskSnapshot>())
            {
                if (task == null || task.PercentComplete < 99.99)
                {
                    continue;
                }

                DateTime finish = IsValidPmDashboardProjectDate(task.ActualFinish) ? task.ActualFinish.Date : task.TaskFinish.Date;
                DateTime baseline = task.PlanFinish.Date;
                if (finish == baseline) status.FirstCount++;
                else if (finish < baseline) status.SecondCount++;
                else status.ThirdCount++;
            }

            return status;
        }

        private static PmReportsPieStatus BuildDurationStatus(PmDashboardLiveSnapshot snapshot)
        {
            var status = new PmReportsPieStatus();
            foreach (PmDashboardTaskSnapshot task in snapshot?.Tasks ?? Enumerable.Empty<PmDashboardTaskSnapshot>())
            {
                if (task == null)
                {
                    continue;
                }

                double baseline = Math.Max(0.0, task.BaselineDurationDays);
                double actual = Math.Max(0.0, task.ActualDurationDays);
                if (Math.Abs(actual - baseline) <= 0.01) status.FirstCount++;
                else if (actual < baseline) status.SecondCount++;
                else status.ThirdCount++;
            }

            return status;
        }

        private static PmReportsPieStatus BuildProgressStatus(PmDashboardLiveSnapshot snapshot)
        {
            var status = new PmReportsPieStatus();
            foreach (PmDashboardTaskSnapshot task in snapshot?.Tasks ?? Enumerable.Empty<PmDashboardTaskSnapshot>())
            {
                if (task == null)
                {
                    continue;
                }

                if (task.PercentComplete >= 99.99) status.FirstCount++;
                else if (task.PercentComplete > 0.0) status.SecondCount++;
                else status.ThirdCount++;
            }

            return status;
        }

        private static PmReportsPieStatus BuildWorkStatus(PmDashboardLiveSnapshot snapshot)
        {
            var status = new PmReportsPieStatus();
            foreach (PmDashboardTaskSnapshot task in snapshot?.Tasks ?? Enumerable.Empty<PmDashboardTaskSnapshot>())
            {
                if (task == null)
                {
                    continue;
                }

                double planned = Math.Max(0.0, task.BaselineWorkDays);
                double actual = Math.Max(0.0, task.ActualWorkDays);
                if (Math.Abs(actual - planned) <= 0.01) status.FirstCount++;
                else if (actual < planned) status.SecondCount++;
                else status.ThirdCount++;
            }

            return status;
        }

        private static PmReportsPieStatus BuildCostStatus(PmDashboardLiveSnapshot snapshot)
        {
            var status = new PmReportsPieStatus();
            foreach (PmDashboardTaskSnapshot task in snapshot?.Tasks ?? Enumerable.Empty<PmDashboardTaskSnapshot>())
            {
                if (task == null)
                {
                    continue;
                }

                double planned = Math.Max(0.0, task.BcwpToDate);
                double actual = Math.Max(0.0, task.AcwpToDate);
                if (Math.Abs(actual - planned) <= 0.01) status.FirstCount++;
                else if (actual < planned) status.SecondCount++;
                else status.ThirdCount++;
            }

            return status;
        }

        private static void RenderReportsPiePlot(
            OxyPlot.Wpf.PlotView plotView,
            string title,
            PmReportsPieStatus status,
            string firstColor,
            string secondColor,
            string thirdColor)
        {
            if (plotView == null)
            {
                return;
            }

            int first = Math.Max(0, status?.FirstCount ?? 0);
            int second = Math.Max(0, status?.SecondCount ?? 0);
            int third = Math.Max(0, status?.ThirdCount ?? 0);
            int total = first + second + third;

            var model = new PlotModel
            {
                PlotMargins = new OxyThickness(0),
                IsLegendVisible = false,
                Title = total > 0 ? "" : title
            };

            var series = new PieSeries
            {
                StrokeThickness = 1,
                InsideLabelPosition = 0.72,
                AngleSpan = 360,
                StartAngle = 0
            };

            if (total <= 0)
            {
                series.Slices.Add(new PieSlice("", 1) { Fill = OxyColor.Parse("#D9DFEA") });
            }
            else
            {
                if (first > 0) series.Slices.Add(new PieSlice("", first) { Fill = OxyColor.Parse(firstColor) });
                if (second > 0) series.Slices.Add(new PieSlice("", second) { Fill = OxyColor.Parse(secondColor) });
                if (third > 0) series.Slices.Add(new PieSlice("", third) { Fill = OxyColor.Parse(thirdColor) });
            }

            model.Series.Add(series);
            plotView.Model = model;
        }

