        private void ConfigureBoreyMultiSelectFilterCombo(System.Windows.Controls.ComboBox combo)
        {
            if (combo == null)
            {
                return;
            }

            combo.IsEditable = true;
            combo.IsReadOnly = true;
            combo.IsTextSearchEnabled = false;
            combo.StaysOpenOnEdit = true;

            if (combo.ItemTemplate == null &&
                TryFindResource("PmUpdateProgressMultiSelectFilterItemTemplate") is DataTemplate itemTemplate)
            {
                combo.ItemTemplate = itemTemplate;
            }

            if (combo.ItemContainerStyle == null)
            {
                combo.ItemContainerStyle = GetOrCreateBoreyMultiSelectComboItemStyle();
            }
        }

        private Style GetOrCreateBoreyMultiSelectComboItemStyle()
        {
            if (_boreyMultiSelectComboItemStyle != null)
            {
                return _boreyMultiSelectComboItemStyle;
            }

            var style = new Style(typeof(ComboBoxItem));
            style.Setters.Add(new EventSetter(
                ComboBoxItem.PreviewMouseLeftButtonDownEvent,
                new MouseButtonEventHandler(OnBoreyFilterComboItemPreviewMouseLeftButtonDown)));

            _boreyMultiSelectComboItemStyle = style;
            return _boreyMultiSelectComboItemStyle;
        }

        private void OnBoreyFilterComboItemPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            if (_boreyFilterMultiSelectUiUpdateInProgress || _boreyUiSyncInProgress)
            {
                return;
            }

            if (!(sender is ComboBoxItem comboItem) ||
                !(comboItem.DataContext is BoreyMultiSelectFilterOption option))
            {
                return;
            }

            if (!(ItemsControl.ItemsControlFromItemContainer(comboItem) is System.Windows.Controls.ComboBox combo))
            {
                return;
            }

            ToggleBoreyFilterOption(combo, option);
            e.Handled = true;
        }

        private static string GetBoreyFilterComboKey(System.Windows.Controls.ComboBox combo)
        {
            return (combo?.Name ?? "").Trim();
        }

        private HashSet<string> GetBoreyFilterSelectedValues(System.Windows.Controls.ComboBox combo)
        {
            string key = GetBoreyFilterComboKey(combo);
            if (!string.IsNullOrWhiteSpace(key) &&
                _boreyFilterSelectedValuesByCombo.TryGetValue(key, out HashSet<string> selectedValues))
            {
                return new HashSet<string>(selectedValues, StringComparer.OrdinalIgnoreCase);
            }

            var optionValues = (combo?.ItemsSource as IEnumerable<BoreyMultiSelectFilterOption>)?
                .Where(o => o != null &&
                            o.IsSelected &&
                            !string.Equals(o.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase))
                .Select(o => (o.Value ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            if (optionValues != null)
            {
                return optionValues;
            }

            string selected = combo?.SelectedItem as string;
            if (!string.IsNullOrWhiteSpace(selected) &&
                !string.Equals(selected.Trim(), BoreyFilterAll, StringComparison.OrdinalIgnoreCase))
            {
                return new HashSet<string>(new[] { selected.Trim() }, StringComparer.OrdinalIgnoreCase);
            }

            return new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        }

        private void SaveBoreyFilterSelectedValues(
            System.Windows.Controls.ComboBox combo,
            IEnumerable<BoreyMultiSelectFilterOption> options)
        {
            string key = GetBoreyFilterComboKey(combo);
            if (string.IsNullOrWhiteSpace(key))
            {
                return;
            }

            HashSet<string> selected = (options ?? Enumerable.Empty<BoreyMultiSelectFilterOption>())
                .Where(o => o != null &&
                            o.IsSelected &&
                            !string.Equals(o.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase))
                .Select(o => (o.Value ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);

            _boreyFilterSelectedValuesByCombo[key] = selected;
        }

        private static void NormalizeBoreyFilterOptionsState(List<BoreyMultiSelectFilterOption> options)
        {
            if (options == null || options.Count == 0)
            {
                return;
            }

            BoreyMultiSelectFilterOption allOption = options
                .FirstOrDefault(o => o != null && string.Equals(o.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase));
            if (allOption == null)
            {
                return;
            }

            List<BoreyMultiSelectFilterOption> valueOptions = options
                .Where(o => o != null && !string.Equals(o.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase))
                .ToList();

            if (allOption.IsSelected)
            {
                foreach (BoreyMultiSelectFilterOption option in valueOptions)
                {
                    option.IsSelected = false;
                }

                return;
            }

            if (valueOptions.Any(o => o.IsSelected))
            {
                allOption.IsSelected = false;
                return;
            }

            allOption.IsSelected = true;
        }

        private static string BuildBoreyFilterComboText(IEnumerable<BoreyMultiSelectFilterOption> options)
        {
            List<string> selected = (options ?? Enumerable.Empty<BoreyMultiSelectFilterOption>())
                .Where(o => o != null &&
                            o.IsSelected &&
                            !string.Equals(o.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase))
                .Select(o => (o.Value ?? "").Trim())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            return selected.Count == 0 ? BoreyFilterAll : string.Join(", ", selected);
        }

        private List<BoreyMultiSelectFilterOption> GetBoreyFilterOptions(System.Windows.Controls.ComboBox combo)
        {
            return (combo?.ItemsSource as IEnumerable<BoreyMultiSelectFilterOption>)?
                .Where(o => o != null)
                .ToList() ?? new List<BoreyMultiSelectFilterOption>();
        }

        private void ToggleBoreyFilterOption(
            System.Windows.Controls.ComboBox combo,
            BoreyMultiSelectFilterOption clickedOption)
        {
            if (combo == null || clickedOption == null)
            {
                return;
            }

            List<BoreyMultiSelectFilterOption> options = GetBoreyFilterOptions(combo);
            if (options.Count == 0)
            {
                return;
            }

            bool clickedIsAll = string.Equals(clickedOption.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase);
            clickedOption.IsSelected = !clickedOption.IsSelected;

            if (clickedIsAll && clickedOption.IsSelected)
            {
                foreach (BoreyMultiSelectFilterOption option in options)
                {
                    if (!ReferenceEquals(option, clickedOption))
                    {
                        option.IsSelected = false;
                    }
                }
            }
            else if (!clickedIsAll && clickedOption.IsSelected)
            {
                BoreyMultiSelectFilterOption allOption = options
                    .FirstOrDefault(o => string.Equals(o.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase));
                if (allOption != null)
                {
                    allOption.IsSelected = false;
                }
            }

            NormalizeBoreyFilterOptionsState(options);
            SaveBoreyFilterSelectedValues(combo, options);

            _boreyFilterMultiSelectUiUpdateInProgress = true;
            try
            {
                combo.SelectedIndex = -1;
                combo.Text = BuildBoreyFilterComboText(options);
                combo.Items.Refresh();
            }
            finally
            {
                _boreyFilterMultiSelectUiUpdateInProgress = false;
            }

            if (!_boreyUiSyncInProgress && IsBoreyTab())
            {
                ApplyCurrentBoreyRevitView(refreshFilterOptions: true);
            }
        }

        private void GenerateBoreyData()
        {
            if (!(BoreySubTabControl?.SelectedItem is TabItem tab))
            {
                ShowStatus("BOREY: select a sub-tab first.");
                return;
            }

            string header = tab.Header?.ToString() ?? "";
            if (!TryGetBoreySubTabContext(
                header,
                out string logicalTable,
                out _,
                out _,
                out _,
                out _,
                out _,
                out DataGrid grid))
            {
                ShowStatus("BOREY: unknown sub-tab.");
                return;
            }

            List<BoreyGridRowPayload> changedRows = BuildChangedBoreyGridRows(grid);
            string baseDir = Path.GetDirectoryName(System.Reflection.Assembly.GetExecutingAssembly().Location) ?? "";
            _handler.Request.BoreySharedParameterFilePath = SharedParameterPathResolver.ResolveDefaultSharedParameterPath(baseDir);
            _handler.Request.BoreySharedParameterGroupName = "CBIM-BOREY";
            _handler.Request.BoreyEnsureSharedParameters = true;
            _handler.Request.BoreyLogicalTableName = logicalTable;
            _handler.Request.BoreyRows = changedRows;
            _handler.Request.BoreyApplyGridChanges = changedRows.Count > 0;
            _handler.Request.RequestType = CadToModelRequestType.SyncBoreyFloorData;

            if (changedRows.Count > 0)
            {
                ShowStatus($"BOREY: applying {changedRows.Count} edited row(s) to Floors and refreshing...");
            }
            else
            {
                ShowStatus("BOREY: syncing floor data and verifying shared parameters...");
            }

            _boreyInitialLoadRequested = true;
            _externalEvent.Raise();
        }

