        private static DataRow GetPlanVsActualTotalRow(DataTable table)
        {
            if (table == null || !table.Columns.Contains("HOUSE-TYPE"))
            {
                return null;
            }

            return table.Rows
                .Cast<DataRow>()
                .FirstOrDefault(r => string.Equals(
                    Convert.ToString(r["HOUSE-TYPE"], CultureInfo.InvariantCulture)?.Trim(),
                    "Total",
                    StringComparison.OrdinalIgnoreCase));
        }

        private static IEnumerable<string> GetPlanVsActualMonthColumns(DataTable table)
        {
            if (table == null)
            {
                return Enumerable.Empty<string>();
            }

            return table.Columns
                .Cast<DataColumn>()
                .Select(c => c.ColumnName)
                .Where(name =>
                    !string.Equals(name, "HOUSE-TYPE", StringComparison.OrdinalIgnoreCase) &&
                    !string.Equals(name, "Total", StringComparison.OrdinalIgnoreCase));
        }

        private static double GetPlanVsActualTableValue(DataTable table, DataRow totalRow, string columnName)
        {
            if (table == null || string.IsNullOrWhiteSpace(columnName) || !table.Columns.Contains(columnName))
            {
                return 0.0;
            }

            if (totalRow != null)
            {
                return ParseBoreyNumericValue(totalRow[columnName]);
            }

            if (!table.Columns.Contains("HOUSE-TYPE"))
            {
                return table.Rows.Cast<DataRow>().Sum(r => ParseBoreyNumericValue(r[columnName]));
            }

            return table.Rows
                .Cast<DataRow>()
                .Where(r => !string.Equals(
                    Convert.ToString(r["HOUSE-TYPE"], CultureInfo.InvariantCulture)?.Trim(),
                    "Total",
                    StringComparison.OrdinalIgnoreCase))
                .Sum(r => ParseBoreyNumericValue(r[columnName]));
        }

