            TextBlock gapUnitsText = GetBoreyNamedTextBlock("BoreyProjectOverallGapUnitsText");
            if (gapUnitsText != null)
            {
                gapUnitsText.Text = "0";
            }

            TextBlock scopeText = GetBoreyNamedTextBlock("BoreyProjectOverallScopeText");
            if (scopeText != null)
            {
                scopeText.Text = "Rows: 0 | Months: 0";
            }

            OxyPlot.Wpf.PlotView plotView = GetBoreyNamedPlotView("BoreyProjectOverallPlotView");
            if (plotView != null)
            {
                plotView.Model = new PlotModel();
            }
        }

        private static double ParseBoreyNumericValue(object raw)
        {
            string text = Convert.ToString(raw, CultureInfo.InvariantCulture)?.Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return 0.0;
            }

            if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out double value) ||
                double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.CurrentCulture, out value))
            {
                return value;
            }

            return 0.0;
        }

        private sealed class ProjectInfoSummaryMetrics
        {
            public double LandLots { get; set; }
            public double SoldOnlyLand { get; set; }
            public double HouseUnits { get; set; }

            public void Add(double landLots, double soldOnlyLand, double houseUnits)
            {
                LandLots += landLots;
                SoldOnlyLand += soldOnlyLand;
                HouseUnits += houseUnits;
            }
        }

        private static bool IsInfraStructureZone(string zone)
        {
            string value = (zone ?? "").Trim();
            if (string.IsNullOrWhiteSpace(value))
            {
                return false;
            }

            return string.Equals(value, "Infra Structure", StringComparison.OrdinalIgnoreCase);
        }

        private static List<string> FilterOutInfraStructureZoneValues(IEnumerable<string> zones)
        {
            if (zones == null)
            {
                return new List<string>();
            }

            return zones
                .Select(z => (z ?? "").Trim())
                .Where(z => !string.IsNullOrWhiteSpace(z) && !IsInfraStructureZone(z))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(z => z, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static DataTable BuildProjectInfoSummaryTable(DataView filteredView)
        {
            var summary = new DataTable("Project_Info_Summary");
            summary.Columns.Add("HOUSE-TYPE", typeof(string));
            if (filteredView?.Table == null)
            {
                return summary;
            }

            DataTable source = filteredView.Table;
            List<DataRow> rows = filteredView
                .Cast<DataRowView>()
                .Select(rv => rv?.Row)
                .Where(r => r != null && r.RowState != DataRowState.Deleted)
                .ToList();
            if (rows.Count == 0)
            {
                return summary;
            }

            string zoneColumn = ResolveFilterColumn(source, "ZONE");
            string houseTypeColumn = ResolveFilterColumn(source, "HOUSE-TYPE");
            string landLotsColumn = ResolveFilterColumn(source, "LAND LOTS");
            string soldOnlyLandColumn = ResolveFilterColumn(source, "Sold Only Land");
            string dataSoldOutColumn = ResolveFilterColumn(source, "Data_Sold_Out");
            string soldUnsoldColumn = ResolveFilterColumn(source, "Sold/Unsold");
            string handoverStatusColumn = ResolveFilterColumn(source, "HANDOVERED STATUS");
            string houseUnitsColumn = ResolveFilterColumn(source, "House-Units");

            bool hasUnspecifiedZoneRows = rows.Any(row => string.IsNullOrWhiteSpace(GetProjectInfoCellText(row, zoneColumn)));
            List<string> zones = SortProjectInfoCodes(
                rows
                    .Select(row => GetProjectInfoCellText(row, zoneColumn))
                    .Where(v => !string.IsNullOrWhiteSpace(v) && !IsInfraStructureZone(v))
                    .Distinct(StringComparer.OrdinalIgnoreCase));
            if (zones.Count == 0 && hasUnspecifiedZoneRows)
            {
                zones.Add("Unspecified");
            }

            foreach (string zone in zones)
            {
                summary.Columns.Add(BuildProjectInfoMetricColumnName(zone, "LAND LOTS"), typeof(string));
                summary.Columns.Add(BuildProjectInfoMetricColumnName(zone, "Sold Only Land"), typeof(string));
                summary.Columns.Add(BuildProjectInfoMetricColumnName(zone, "House-Units"), typeof(string));
            }

            summary.Columns.Add(BuildProjectInfoMetricColumnName("Total", "LAND LOTS"), typeof(string));
            summary.Columns.Add(BuildProjectInfoMetricColumnName("Total", "Sold Only Land"), typeof(string));
            summary.Columns.Add(BuildProjectInfoMetricColumnName("Total", "House-Units"), typeof(string));

            var metricsByHouseType = new Dictionary<string, Dictionary<string, ProjectInfoSummaryMetrics>>(StringComparer.OrdinalIgnoreCase);
            var totalsByZone = new Dictionary<string, ProjectInfoSummaryMetrics>(StringComparer.OrdinalIgnoreCase);
            var grandTotal = new ProjectInfoSummaryMetrics();

            foreach (DataRow row in rows)
            {
                string zone = GetProjectInfoCellText(row, zoneColumn);
                if (string.IsNullOrWhiteSpace(zone))
                {
                    zone = "Unspecified";
                }

                string houseType = GetProjectInfoCellText(row, houseTypeColumn);
                if (string.IsNullOrWhiteSpace(houseType))
                {
                    houseType = "(Blank)";
                }

                double landLots = GetProjectInfoLandLotsValue(row, landLotsColumn);
                double soldOnlyLand = GetProjectInfoSoldOnlyLandValue(row, soldOnlyLandColumn, dataSoldOutColumn, soldUnsoldColumn, handoverStatusColumn);
                double houseUnits = GetProjectInfoHouseUnitsValue(row, houseUnitsColumn, landLots);

                if (!metricsByHouseType.TryGetValue(houseType, out Dictionary<string, ProjectInfoSummaryMetrics> zoneMap))
                {
                    zoneMap = new Dictionary<string, ProjectInfoSummaryMetrics>(StringComparer.OrdinalIgnoreCase);
                    metricsByHouseType[houseType] = zoneMap;
                }

                if (!zoneMap.TryGetValue(zone, out ProjectInfoSummaryMetrics zoneMetrics))
                {
                    zoneMetrics = new ProjectInfoSummaryMetrics();
                    zoneMap[zone] = zoneMetrics;
                }

                zoneMetrics.Add(landLots, soldOnlyLand, houseUnits);

                if (!totalsByZone.TryGetValue(zone, out ProjectInfoSummaryMetrics zoneTotalMetrics))
                {
                    zoneTotalMetrics = new ProjectInfoSummaryMetrics();
                    totalsByZone[zone] = zoneTotalMetrics;
                }

                zoneTotalMetrics.Add(landLots, soldOnlyLand, houseUnits);
                grandTotal.Add(landLots, soldOnlyLand, houseUnits);
            }

            List<string> houseTypes = metricsByHouseType.Keys
                .OrderBy(v => v, StringComparer.OrdinalIgnoreCase)
                .ToList();

            foreach (string houseType in houseTypes)
            {
                DataRow outputRow = summary.NewRow();
                outputRow["HOUSE-TYPE"] = houseType;
                Dictionary<string, ProjectInfoSummaryMetrics> zoneMap = metricsByHouseType[houseType];

                var rowTotal = new ProjectInfoSummaryMetrics();
                foreach (ProjectInfoSummaryMetrics metrics in zoneMap.Values)
                {
                    if (metrics == null)
                    {
                        continue;
                    }

                    rowTotal.Add(metrics.LandLots, metrics.SoldOnlyLand, metrics.HouseUnits);
                }

                foreach (string zone in zones)
                {
                    if (zoneMap.TryGetValue(zone, out ProjectInfoSummaryMetrics metrics))
                    {
                        outputRow[BuildProjectInfoMetricColumnName(zone, "LAND LOTS")] =
                            FormatProjectInfoMetric("LAND LOTS", metrics.LandLots);
                        outputRow[BuildProjectInfoMetricColumnName(zone, "Sold Only Land")] =
                            FormatProjectInfoMetric("Sold Only Land", metrics.SoldOnlyLand);
                        outputRow[BuildProjectInfoMetricColumnName(zone, "House-Units")] =
                            FormatProjectInfoMetric("House-Units", metrics.HouseUnits);
                    }
                }

                outputRow[BuildProjectInfoMetricColumnName("Total", "LAND LOTS")] =
                    FormatProjectInfoMetric("LAND LOTS", rowTotal.LandLots);
                outputRow[BuildProjectInfoMetricColumnName("Total", "Sold Only Land")] =
                    FormatProjectInfoMetric("Sold Only Land", rowTotal.SoldOnlyLand);
                outputRow[BuildProjectInfoMetricColumnName("Total", "House-Units")] =
                    FormatProjectInfoMetric("House-Units", rowTotal.HouseUnits);

                summary.Rows.Add(outputRow);
            }

            DataRow totalRow = summary.NewRow();
            totalRow["HOUSE-TYPE"] = "Total";
            foreach (string zone in zones)
            {
                if (totalsByZone.TryGetValue(zone, out ProjectInfoSummaryMetrics metrics))
                {
                    totalRow[BuildProjectInfoMetricColumnName(zone, "LAND LOTS")] =
                        FormatProjectInfoMetric("LAND LOTS", metrics.LandLots);
                    totalRow[BuildProjectInfoMetricColumnName(zone, "Sold Only Land")] =
                        FormatProjectInfoMetric("Sold Only Land", metrics.SoldOnlyLand);
                    totalRow[BuildProjectInfoMetricColumnName(zone, "House-Units")] =
                        FormatProjectInfoMetric("House-Units", metrics.HouseUnits);
                }
            }

            totalRow[BuildProjectInfoMetricColumnName("Total", "LAND LOTS")] =
                FormatProjectInfoMetric("LAND LOTS", grandTotal.LandLots);
            totalRow[BuildProjectInfoMetricColumnName("Total", "Sold Only Land")] =
                FormatProjectInfoMetric("Sold Only Land", grandTotal.SoldOnlyLand);
            totalRow[BuildProjectInfoMetricColumnName("Total", "House-Units")] =
                FormatProjectInfoMetric("House-Units", grandTotal.HouseUnits);
            summary.Rows.Add(totalRow);

            return summary;
        }

        private static string BuildProjectInfoMetricColumnName(string groupName, string metricName)
        {
            string group = (groupName ?? "").Trim();
            string metric = (metricName ?? "").Trim();
            if (string.IsNullOrWhiteSpace(group))
            {
                return metric;
            }

            if (string.Equals(group, "Total", StringComparison.OrdinalIgnoreCase))
            {
                return "Total" + Environment.NewLine + metric;
            }

            return group + Environment.NewLine + metric;
        }

        private static string GetProjectInfoCellText(DataRow row, string columnName)
        {
            if (row == null || string.IsNullOrWhiteSpace(columnName))
            {
                return "";
            }

            return Convert.ToString(row[columnName], CultureInfo.InvariantCulture)?.Trim() ?? "";
        }

        private static double GetProjectInfoLandLotsValue(DataRow row, string landLotsColumn)
        {
            return ParseBoreyNumericValue(string.IsNullOrWhiteSpace(landLotsColumn) ? null : row[landLotsColumn]);
        }

        private static double GetProjectInfoHouseUnitsValue(DataRow row, string houseUnitsColumn, double landLots)
        {
            double value = ParseBoreyNumericValue(string.IsNullOrWhiteSpace(houseUnitsColumn) ? null : row[houseUnitsColumn]);
            if (value > 0.0)
            {
                return value;
            }

            if (landLots > 0.0)
            {
                return landLots;
            }

            return 1.0;
        }

        private static double GetProjectInfoSoldOnlyLandValue(
            DataRow row,
            string soldOnlyLandColumn,
            string dataSoldOutColumn,
            string soldUnsoldColumn,
            string handoverStatusColumn)
        {
            double numeric = ParseBoreyNumericValue(string.IsNullOrWhiteSpace(soldOnlyLandColumn) ? null : row[soldOnlyLandColumn]);
            if (numeric > 0.0)
            {
                return numeric;
            }

            numeric = ParseBoreyNumericValue(string.IsNullOrWhiteSpace(dataSoldOutColumn) ? null : row[dataSoldOutColumn]);
            if (numeric > 0.0)
            {
                return numeric;
            }

            string soldUnsold = GetProjectInfoCellText(row, soldUnsoldColumn);
            if (string.Equals(soldUnsold, "Sold Only Land", StringComparison.OrdinalIgnoreCase))
            {
                return 1.0;
            }

            string status = GetProjectInfoCellText(row, handoverStatusColumn);
            if (string.Equals(status, "Sold Only Land", StringComparison.OrdinalIgnoreCase))
            {
                return 1.0;
            }

            return 0.0;
        }

        private static string FormatProjectInfoMetric(string metricName, double value)
        {
            if (string.Equals(metricName, "House-Units", StringComparison.OrdinalIgnoreCase))
            {
                return value.ToString("0.###", CultureInfo.InvariantCulture);
            }

            return value.ToString("0.00", CultureInfo.InvariantCulture);
        }

        private static readonly string[] ProjectStatusBuckets =
        {
            "Hand over team",
            "Head Office (HO)",
            "Mockup",
            "Progressive",
            "Sold Only Land",
            "Stop Build",
            "To Client",
            "Unsold"
        };

        private static OxyColor GetProjectStatusBucketColor(string bucket)
        {
            string key = (bucket ?? "").Trim();
            if (string.Equals(key, "Hand over team", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#2D8CBE");
            if (string.Equals(key, "Head Office (HO)", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#6F63B8");
            if (string.Equals(key, "Mockup", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#7A9E45");
            if (string.Equals(key, "Progressive", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#4E79A7");
            if (string.Equals(key, "Sold Only Land", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#F28E2B");
            if (string.Equals(key, "Stop Build", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#E15759");
            if (string.Equals(key, "To Client", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#59A14F");
            if (string.Equals(key, "Unsold", StringComparison.OrdinalIgnoreCase)) return OxyColor.Parse("#9C755F");
            return OxyColor.Parse("#B5BDC9");
        }

        private static Dictionary<string, double> BuildProjectStatusBucketTotals(DataView filteredView)
        {
            var totals = ProjectStatusBuckets.ToDictionary(k => k, _ => 0.0, StringComparer.OrdinalIgnoreCase);
            if (filteredView?.Table == null)
            {
                return totals;
            }

            DataTable source = filteredView.Table;
            string statusColumn = ResolveFilterColumn(source, "HANDOVERED STATUS");
            string houseUnitsColumn = ResolveFilterColumn(source, "House-Units");
            string landLotsColumn = ResolveFilterColumn(source, "LAND LOTS");

            foreach (DataRowView rowView in filteredView.Cast<DataRowView>())
            {
                if (rowView?.Row == null || rowView.Row.RowState == DataRowState.Deleted)
                {
                    continue;
                }

                DataRow row = rowView.Row;
                string bucket = NormalizeProjectStatusBucket(GetProjectInfoCellText(row, statusColumn));
                double units = GetProjectInfoHouseUnitsValue(row, houseUnitsColumn, GetProjectInfoLandLotsValue(row, landLotsColumn));
                if (units <= 0.0)
                {
                    continue;
                }

                if (!totals.ContainsKey(bucket))
                {
                    totals[bucket] = 0.0;
                }
                totals[bucket] += units;
            }

            return totals;
        }

        private void UpdateBoreyProjectStatusDonutChart(DataView filteredView)
        {
            OxyPlot.Wpf.PlotView plotView = GetBoreyNamedPlotView("ProjectStatusDonutPlotView");
            TextBlock summaryText = GetBoreyNamedTextBlock("ProjectStatusDonutSummaryText");
            WrapPanel legendPanel = FindName("ProjectStatusDonutLegendPanel") as WrapPanel;
            if (plotView == null && summaryText == null && legendPanel == null)
            {
                return;
            }

            Dictionary<string, double> totals = BuildProjectStatusBucketTotals(filteredView);
            double totalUnits = totals.Values.Sum();
            int categoryCount = totals.Count(x => x.Value > 1e-9);

            if (summaryText != null)
            {
                summaryText.Text = "Total Units: " + totalUnits.ToString("0.###", CultureInfo.InvariantCulture) +
                                   " | Categories: " + categoryCount.ToString(CultureInfo.InvariantCulture);
            }

            UpdateBoreyProjectStatusDonutLegend(legendPanel, totals, totalUnits);

            if (plotView == null)
            {
                return;
            }

            var model = new PlotModel
            {
                Background = OxyColor.Parse("#F8FAFD"),
                PlotAreaBorderColor = OxyColors.Undefined,
                PlotAreaBorderThickness = new OxyThickness(0),
                // Reserve breathing room so outside labels are not clipped by the plot bounds.
                Padding = new OxyThickness(16, 10, 16, 10),
                PlotMargins = new OxyThickness(20, 12, 20, 12),
                TextColor = OxyColor.Parse("#3C4B61"),
                IsLegendVisible = false
            };

            var donutSeries = new PieSeries
            {
                StartAngle = 270,
                AngleSpan = 360,
                Diameter = 0.86,
                InnerDiameter = 0.62,
                Stroke = OxyColor.Parse("#FFFFFF"),
                StrokeThickness = 1.0,
                OutsideLabelFormat = "{1}: {2:0.##}",
                InsideLabelFormat = "",
                TickDistance = 2,
                TickHorizontalLength = 4,
                TickRadialLength = 4,
                TickLabelDistance = 2
            };

            foreach (string bucket in ProjectStatusBuckets)
            {
                if (!totals.TryGetValue(bucket, out double value) || value <= 1e-9)
                {
                    continue;
                }

                donutSeries.Slices.Add(new PieSlice(bucket, value)
                {
                    Fill = GetProjectStatusBucketColor(bucket)
                });
            }

            if (donutSeries.Slices.Count == 0)
            {
                donutSeries.Slices.Add(new PieSlice("No data", 1.0)
                {
                    Fill = OxyColor.Parse("#D9DFEA")
                });
            }

            model.Series.Add(donutSeries);
            plotView.Model = model;
        }

        private void UpdateBoreyProjectStatusDonutLegend(
            WrapPanel legendPanel,
            IDictionary<string, double> totals,
            double totalUnits)
        {
            if (legendPanel == null)
            {
                return;
            }

            legendPanel.Children.Clear();

            if (totals == null || totals.Count == 0)
            {
                return;
            }

            foreach (string bucket in ProjectStatusBuckets)
            {
                if (!totals.TryGetValue(bucket, out double value) || value <= 1e-9)
                {
                    continue;
                }

                legendPanel.Children.Add(CreateBoreyProjectStatusLegendItem(
                    bucket,
                    GetProjectStatusBucketColor(bucket),
                    value,
                    totalUnits));
            }

            if (legendPanel.Children.Count == 0)
            {
                legendPanel.Children.Add(CreateBoreyProjectStatusLegendItem(
                    "No data",
                    OxyColor.Parse("#D9DFEA"),
                    0.0,
                    0.0));
            }
        }

        private static FrameworkElement CreateBoreyProjectStatusLegendItem(
            string bucket,
            OxyColor color,
            double value,
            double totalUnits)
        {
            var itemPanel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 0, 14, 6),
                VerticalAlignment = global::System.Windows.VerticalAlignment.Center
            };

            var swatch = new Border
            {
                Width = 12,
                Height = 12,
                CornerRadius = new CornerRadius(2),
                Background = ToMediaBrush(color),
                BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(140, 153, 171)),
                BorderThickness = new Thickness(0.8)
            };

            string text = bucket ?? "";
            if (value > 1e-9)
            {
                text += ": " + value.ToString("0.##", CultureInfo.InvariantCulture);
                if (totalUnits > 1e-9)
                {
                    text += " (" + (value * 100.0 / totalUnits).ToString("0.##", CultureInfo.InvariantCulture) + "%)";
                }
            }

            var label = new TextBlock
            {
                Text = text,
                Margin = new Thickness(6, 0, 0, 0),
                Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(60, 75, 97)),
                VerticalAlignment = global::System.Windows.VerticalAlignment.Center
            };

            itemPanel.Children.Add(swatch);
            itemPanel.Children.Add(label);
            return itemPanel;
        }

        private static DataTable BuildProjectStatusSummaryTable(DataView filteredView)
        {
            var summary = new DataTable("Project_Status_Summary");
            summary.Columns.Add("ZONE", typeof(string));
            foreach (string bucket in ProjectStatusBuckets)
            {
                summary.Columns.Add(bucket, typeof(string));
            }

            summary.Columns.Add("Total", typeof(string));

            if (filteredView?.Table == null)
            {
                return summary;
            }

            DataTable source = filteredView.Table;
            List<DataRow> rows = filteredView
                .Cast<DataRowView>()
                .Select(rv => rv?.Row)
                .Where(r => r != null && r.RowState != DataRowState.Deleted)
                .ToList();
            if (rows.Count == 0)
            {
                return summary;
            }

            string zoneColumn = ResolveFilterColumn(source, "ZONE");
            string houseTypeColumn = ResolveFilterColumn(source, "HOUSE-TYPE");
            string statusColumn = ResolveFilterColumn(source, "HANDOVERED STATUS");
            string houseUnitsColumn = ResolveFilterColumn(source, "House-Units");
            string landLotsColumn = ResolveFilterColumn(source, "LAND LOTS");

            var zoneTypeBucket = new Dictionary<string, Dictionary<string, Dictionary<string, double>>>(StringComparer.OrdinalIgnoreCase);
            var zoneBucketTotals = new Dictionary<string, Dictionary<string, double>>(StringComparer.OrdinalIgnoreCase);
            var grandBucketTotals = ProjectStatusBuckets.ToDictionary(k => k, _ => 0.0, StringComparer.OrdinalIgnoreCase);

            foreach (DataRow row in rows)
            {
                string zone = GetProjectInfoCellText(row, zoneColumn);
                if (string.IsNullOrWhiteSpace(zone))
                {
                    zone = "Unspecified";
                }

                string houseType = GetProjectInfoCellText(row, houseTypeColumn);
                if (string.IsNullOrWhiteSpace(houseType))
                {
                    houseType = "(Blank)";
                }

                string rawStatus = GetProjectInfoCellText(row, statusColumn);
                string bucket = NormalizeProjectStatusBucket(rawStatus);
                double units = GetProjectInfoHouseUnitsValue(row, houseUnitsColumn, GetProjectInfoLandLotsValue(row, landLotsColumn));
                if (units <= 0.0)
                {
                    continue;
                }

                if (!zoneTypeBucket.TryGetValue(zone, out Dictionary<string, Dictionary<string, double>> typeMap))
                {
                    typeMap = new Dictionary<string, Dictionary<string, double>>(StringComparer.OrdinalIgnoreCase);
                    zoneTypeBucket[zone] = typeMap;
                }

                if (!typeMap.TryGetValue(houseType, out Dictionary<string, double> typeBucket))
                {
                    typeBucket = ProjectStatusBuckets.ToDictionary(k => k, _ => 0.0, StringComparer.OrdinalIgnoreCase);
                    typeMap[houseType] = typeBucket;
                }

                typeBucket[bucket] += units;

                if (!zoneBucketTotals.TryGetValue(zone, out Dictionary<string, double> zoneTotals))
                {
                    zoneTotals = ProjectStatusBuckets.ToDictionary(k => k, _ => 0.0, StringComparer.OrdinalIgnoreCase);
                    zoneBucketTotals[zone] = zoneTotals;
                }

                zoneTotals[bucket] += units;
                grandBucketTotals[bucket] += units;
            }

            List<string> zones = SortProjectInfoCodes(zoneTypeBucket.Keys);
            foreach (string zone in zones)
            {
                Dictionary<string, double> zoneTotals = zoneBucketTotals.TryGetValue(zone, out Dictionary<string, double> z)
                    ? z
                    : ProjectStatusBuckets.ToDictionary(k => k, _ => 0.0, StringComparer.OrdinalIgnoreCase);
                summary.Rows.Add(BuildProjectStatusRow(summary, zone, zoneTotals));

                List<string> houseTypes = zoneTypeBucket[zone].Keys
                    .OrderBy(v => v, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                foreach (string houseType in houseTypes)
                {
                    summary.Rows.Add(BuildProjectStatusRow(summary, houseType, zoneTypeBucket[zone][houseType]));
                }
            }

            summary.Rows.Add(BuildProjectStatusRow(summary, "Total", grandBucketTotals));
            return summary;
        }

        private static DataRow BuildProjectStatusRow(DataTable table, string label, IDictionary<string, double> bucketValues)
        {
            DataRow row = table.NewRow();
            row["ZONE"] = label ?? "";

            double total = 0.0;
            foreach (string bucket in ProjectStatusBuckets)
            {
                double value = 0.0;
                if (bucketValues != null && bucketValues.TryGetValue(bucket, out double found))
                {
                    value = found;
                }

                total += value;
                row[bucket] = FormatProjectStatusMetric(value);
            }

            row["Total"] = FormatProjectStatusMetric(total);
            return row;
        }

        private static string NormalizeProjectStatusBucket(string status)
        {
            string value = (status ?? "").Trim();
            if (string.IsNullOrWhiteSpace(value))
            {
                return "Unsold";
            }

            string lowered = value.ToLowerInvariant();
            if (lowered.Contains("to client"))
            {
                return "To Client";
            }

            if (lowered.Contains("sold only land"))
            {
                return "Sold Only Land";
            }

            if (lowered.Contains("stop"))
            {
                return "Stop Build";
            }

            if (lowered.Contains("head office") || string.Equals(lowered, "ho", StringComparison.OrdinalIgnoreCase))
            {
                return "Head Office (HO)";
            }

            if (lowered.Contains("mock"))
            {
                return "Mockup";
            }

            if (lowered.Contains("hand over team") || lowered.Contains("handover team") || lowered == "hand over")
            {
                return "Hand over team";
            }

            if (lowered.Contains("progress") || lowered.Contains("under construction"))
            {
                return "Progressive";
            }

            if (lowered.Contains("unsold") || lowered.Contains("stock in") || lowered.Contains("unplan"))
            {
                return "Unsold";
            }

            return "Unsold";
        }

        private static string FormatProjectStatusMetric(double value)
        {
            if (Math.Abs(value) < 1e-9)
            {
                return "";
            }

            return value.ToString("0.00", CultureInfo.InvariantCulture);
        }

        private static void BuildPlanVsActualTables(
            DataView filteredView,
            out DataTable monthlyPlanTable,
            out DataTable actualCompletedTable,
            out DataTable remainingTable)
        {
            monthlyPlanTable = new DataTable("PlanVsActual_MonthlyPlan");
            actualCompletedTable = new DataTable("PlanVsActual_Actual");
            remainingTable = new DataTable("PlanVsActual_Remaining");

            DataTable source = filteredView?.Table;
            if (source == null)
            {
                InitializePlanVsActualMatrixSchema(monthlyPlanTable, new List<DateTime>());
                InitializePlanVsActualMatrixSchema(actualCompletedTable, new List<DateTime>());
                InitializePlanVsActualMatrixSchema(remainingTable, new List<DateTime>());
                return;
            }

            string houseTypeColumn = ResolveFilterColumn(source, "HOUSE-TYPE");
            string planUnitsColumn = ResolveFilterColumn(source, "House-Units");
            string actualUnitsColumn = ResolveFilterColumn(source, "Handovered-Units");
            string handoverFlagColumn = ResolveFilterColumn(source, "HANDOVERED");
            string planDateColumn = ResolveTocColumnName(source);
            string actualDateColumn = ResolveFilterColumn(source, "Plan Handover");
            if (string.IsNullOrWhiteSpace(actualDateColumn))
            {
                actualDateColumn = ResolveFilterColumn(source, "SPA (HO Date)");
            }

            var monthSet = new SortedSet<DateTime>();
            var planByType = new Dictionary<string, Dictionary<DateTime, double>>(StringComparer.OrdinalIgnoreCase);
            var actualByType = new Dictionary<string, Dictionary<DateTime, double>>(StringComparer.OrdinalIgnoreCase);

            foreach (DataRowView rowView in filteredView.Cast<DataRowView>())
            {
                if (rowView?.Row == null || rowView.Row.RowState == DataRowState.Deleted)
                {
                    continue;
                }

                DataRow row = rowView.Row;
                string houseType = GetProjectInfoCellText(row, houseTypeColumn);
                if (string.IsNullOrWhiteSpace(houseType))
                {
                    houseType = "(Blank)";
                }

                double planUnits = ParseBoreyNumericValue(string.IsNullOrWhiteSpace(planUnitsColumn) ? null : row[planUnitsColumn]);
                if (planUnits <= 0.0)
                {
                    planUnits = 1.0;
                }

                bool hasPlanMonth = TryGetPlanVsActualMonth(row, planDateColumn, out DateTime planMonth);
                if (hasPlanMonth)
                {
                    AddPlanVsActualValue(planByType, houseType, planMonth, planUnits);
                    monthSet.Add(planMonth);
                }

                double actualUnits = ParseBoreyNumericValue(string.IsNullOrWhiteSpace(actualUnitsColumn) ? null : row[actualUnitsColumn]);
                bool isHandovered = ParseBoreyNumericValue(string.IsNullOrWhiteSpace(handoverFlagColumn) ? null : row[handoverFlagColumn]) > 0.0;
                if (actualUnits <= 0.0 && isHandovered)
                {
                    actualUnits = planUnits;
                }

                if (actualUnits <= 0.0)
                {
                    continue;
                }

                if (!TryGetPlanVsActualMonth(row, actualDateColumn, out DateTime actualMonth))
                {
                    if (!hasPlanMonth)
                    {
                        continue;
                    }

                    actualMonth = planMonth;
                }

                AddPlanVsActualValue(actualByType, houseType, actualMonth, actualUnits);
                monthSet.Add(actualMonth);
            }

            var months = monthSet.ToList();
            InitializePlanVsActualMatrixSchema(monthlyPlanTable, months);
            InitializePlanVsActualMatrixSchema(actualCompletedTable, months);
            InitializePlanVsActualMatrixSchema(remainingTable, months);

            var houseTypes = planByType.Keys
                .Concat(actualByType.Keys)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(v => v, StringComparer.OrdinalIgnoreCase)
                .ToList();

            foreach (string houseType in houseTypes)
            {
                DataRow planRow = monthlyPlanTable.NewRow();
                DataRow actualRow = actualCompletedTable.NewRow();
                DataRow remainingRow = remainingTable.NewRow();

                planRow["HOUSE-TYPE"] = houseType;
                actualRow["HOUSE-TYPE"] = houseType;
                remainingRow["HOUSE-TYPE"] = houseType;

                double planTotal = 0.0;
                double actualTotal = 0.0;
                double remainingTotal = 0.0;

                foreach (DateTime month in months)
                {
                    string columnName = month.ToString("MMM-yy", CultureInfo.InvariantCulture);
                    double plan = GetPlanVsActualValue(planByType, houseType, month);
                    double actual = GetPlanVsActualValue(actualByType, houseType, month);
                    double remaining = Math.Max(0.0, plan - actual);

                    planTotal += plan;
                    actualTotal += actual;
                    remainingTotal += remaining;

                    planRow[columnName] = FormatPlanVsActualValue(plan, showZero: false);
                    actualRow[columnName] = FormatPlanVsActualValue(actual, showZero: false);
                    remainingRow[columnName] = FormatPlanVsActualValue(remaining, showZero: false);
                }

                planRow["Total"] = FormatPlanVsActualValue(planTotal, showZero: true);
                actualRow["Total"] = FormatPlanVsActualValue(actualTotal, showZero: true);
                remainingRow["Total"] = FormatPlanVsActualValue(remainingTotal, showZero: true);

                monthlyPlanTable.Rows.Add(planRow);
                actualCompletedTable.Rows.Add(actualRow);
                remainingTable.Rows.Add(remainingRow);
            }

            DataRow monthlyTotalRow = monthlyPlanTable.NewRow();
            DataRow actualTotalRow = actualCompletedTable.NewRow();
            DataRow remainingTotalRow = remainingTable.NewRow();
            monthlyTotalRow["HOUSE-TYPE"] = "Total";
            actualTotalRow["HOUSE-TYPE"] = "Total";
            remainingTotalRow["HOUSE-TYPE"] = "Total";

            double monthlyGrandTotal = 0.0;
            double actualGrandTotal = 0.0;
            double remainingGrandTotal = 0.0;

            foreach (DateTime month in months)
            {
                string columnName = month.ToString("MMM-yy", CultureInfo.InvariantCulture);
                double monthPlan = monthlyPlanTable.Rows.Cast<DataRow>()
                    .Where(r => !string.Equals(Convert.ToString(r["HOUSE-TYPE"], CultureInfo.InvariantCulture), "Total", StringComparison.OrdinalIgnoreCase))
                    .Sum(r => ParseBoreyNumericValue(r[columnName]));
                double monthActual = actualCompletedTable.Rows.Cast<DataRow>()
                    .Where(r => !string.Equals(Convert.ToString(r["HOUSE-TYPE"], CultureInfo.InvariantCulture), "Total", StringComparison.OrdinalIgnoreCase))
                    .Sum(r => ParseBoreyNumericValue(r[columnName]));
                double monthRemain = remainingTable.Rows.Cast<DataRow>()
                    .Where(r => !string.Equals(Convert.ToString(r["HOUSE-TYPE"], CultureInfo.InvariantCulture), "Total", StringComparison.OrdinalIgnoreCase))
                    .Sum(r => ParseBoreyNumericValue(r[columnName]));

                monthlyGrandTotal += monthPlan;
                actualGrandTotal += monthActual;
                remainingGrandTotal += monthRemain;

                monthlyTotalRow[columnName] = FormatPlanVsActualValue(monthPlan, showZero: true);
                actualTotalRow[columnName] = FormatPlanVsActualValue(monthActual, showZero: true);
                remainingTotalRow[columnName] = FormatPlanVsActualValue(monthRemain, showZero: true);
            }

            monthlyTotalRow["Total"] = FormatPlanVsActualValue(monthlyGrandTotal, showZero: true);
            actualTotalRow["Total"] = FormatPlanVsActualValue(actualGrandTotal, showZero: true);
            remainingTotalRow["Total"] = FormatPlanVsActualValue(remainingGrandTotal, showZero: true);

            monthlyPlanTable.Rows.Add(monthlyTotalRow);
            actualCompletedTable.Rows.Add(actualTotalRow);
            remainingTable.Rows.Add(remainingTotalRow);
        }

        private static void InitializePlanVsActualMatrixSchema(DataTable table, IList<DateTime> months)
        {
            if (table == null)
            {
                return;
            }

            table.Columns.Clear();
            table.Columns.Add("HOUSE-TYPE", typeof(string));
            if (months != null)
            {
                foreach (DateTime month in months)
                {
                    string columnName = month.ToString("MMM-yy", CultureInfo.InvariantCulture);
                    if (!table.Columns.Contains(columnName))
                    {
                        table.Columns.Add(columnName, typeof(string));
                    }
                }
            }

            table.Columns.Add("Total", typeof(string));
        }

        private static bool TryGetPlanVsActualMonth(DataRow row, string columnName, out DateTime monthEnd)
        {
            monthEnd = DateTime.MinValue;
            if (row == null || string.IsNullOrWhiteSpace(columnName))
            {
                return false;
            }

            string raw = Convert.ToString(row[columnName], CultureInfo.InvariantCulture)?.Trim();
            return TryGetTocMonthEnd(raw, out monthEnd);
        }

        private static void AddPlanVsActualValue(
            IDictionary<string, Dictionary<DateTime, double>> valuesByType,
            string houseType,
            DateTime month,
            double value)
        {
            if (valuesByType == null || string.IsNullOrWhiteSpace(houseType) || value <= 0.0)
            {
                return;
            }

            if (!valuesByType.TryGetValue(houseType, out Dictionary<DateTime, double> byMonth))
            {
                byMonth = new Dictionary<DateTime, double>();
                valuesByType[houseType] = byMonth;
            }

            if (!byMonth.TryGetValue(month.Date, out double existing))
            {
                existing = 0.0;
            }

            byMonth[month.Date] = existing + value;
        }

        private static double GetPlanVsActualValue(
            IDictionary<string, Dictionary<DateTime, double>> valuesByType,
            string houseType,
            DateTime month)
        {
            if (valuesByType == null || string.IsNullOrWhiteSpace(houseType))
            {
                return 0.0;
            }

            if (!valuesByType.TryGetValue(houseType, out Dictionary<DateTime, double> byMonth) || byMonth == null)
            {
                return 0.0;
            }

            if (!byMonth.TryGetValue(month.Date, out double value))
            {
                return 0.0;
            }

            return value;
        }

        private static string FormatPlanVsActualValue(double value, bool showZero)
        {
            if (Math.Abs(value) < 1e-9)
            {
                return showZero ? "0" : "";
            }

            if (Math.Abs(value - Math.Round(value)) < 1e-9)
            {
                return Math.Round(value).ToString("0", CultureInfo.InvariantCulture);
            }

            return value.ToString("0.##", CultureInfo.InvariantCulture);
        }

        private static List<string> SortProjectInfoCodes(IEnumerable<string> values)
        {
            return (values ?? Enumerable.Empty<string>())
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Select(v => v.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Select(v =>
                {
                    SplitProjectInfoCodeForSort(v, out string prefix, out int number, out string suffix);
                    return new
                    {
                        Value = v,
                        Prefix = prefix,
                        Number = number,
                        Suffix = suffix
                    };
                })
                .OrderBy(x => x.Prefix, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Number)
                .ThenBy(x => x.Suffix, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Value, StringComparer.OrdinalIgnoreCase)
                .Select(x => x.Value)
                .ToList();
        }

        private static void SplitProjectInfoCodeForSort(string value, out string prefix, out int number, out string suffix)
        {
            prefix = "";
            number = int.MaxValue;
            suffix = "";

            string text = (value ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return;
            }

            int firstDigit = -1;
            for (int i = 0; i < text.Length; i++)
            {
                if (char.IsDigit(text[i]))
                {
                    firstDigit = i;
                    break;
                }
            }

            if (firstDigit < 0)
            {
                prefix = text;
                return;
            }

            prefix = text.Substring(0, firstDigit);
            int j = firstDigit;
            while (j < text.Length && char.IsDigit(text[j]))
            {
                j++;
            }

            string numberToken = text.Substring(firstDigit, j - firstDigit);
            if (!int.TryParse(numberToken, NumberStyles.Integer, CultureInfo.InvariantCulture, out number))
            {
                number = int.MaxValue;
            }

            suffix = j < text.Length ? text.Substring(j) : "";
        }

        private void RequestBoreySyncFromRevit(string logicalTableName = "")
        {
