        private void ApplyTasReferenceSettingsToRequest()
        {
            if (_handler?.Request == null)
            {
                return;
            }

            TasReferenceSettings tas = EnsureTasReferenceSettings();
            TasIdentificationOptionsProfile identification = EnsureTasIdentificationOptions();
            _handler.Request.TasAiConfigLoaded = tas.AiConfigLoaded;
            _handler.Request.TasReferenceSummary = tas.IsInstalled
                ? $"TAS {tas.DisplayVersion}, AIConfig {(tas.AiConfigLoaded ? "loaded" : "not loaded")}"
                : "TAS reference not found";
            _handler.Request.TasRdpEpsilonMm = tas.RdpEpsilonMm;
            _handler.Request.TasApproxPolylineEpsilon = tas.ApproxPolylineEpsilon;
            _handler.Request.TasRepairPolyline = tas.RepairPolyline;
            _handler.Request.TasCadLineParallelAngleEpsilonDeg = tas.CadLineParallelAngleEpsilonDeg;
            _handler.Request.TasCadLineSearchMaxDistanceMm = tas.CadLineSearchMaxDistanceMm;
            _handler.Request.TasShortLineMinLengthMm = Math.Max(
                tas.ShortLineMinLengthMm,
                identification.GetDouble("LineMergeSettings", tas.ShortLineMinLengthMm));
            _handler.Request.TasIdentificationOptionsSummary = identification.BuildWorkflowSummary();
            _handler.Request.TasColumnCodes = JoinTasCodes(
                identification.GetValue("CADKZCode", "KZ,C"),
                identification.GetValue("CADAZCode", "AZ"),
                identification.GetValue("CADDZCode", "DZ"),
                identification.GetValue("CADKZZCode", "KZZ"),
                identification.GetValue("CADGZCode", "GZ"));
            _handler.Request.TasWallCodes = identification.GetValue("CADWallCode", "WS,W");
            _handler.Request.TasBeamCodes = JoinTasCodes(
                identification.GetValue("CADKLCode", "KL,B,G,CG,CB,FB,P,E,D"),
                identification.GetValue("CADKZLCode", "KZL"),
                identification.GetValue("CADLCode", "L,J"),
                identification.GetValue("CADJZLCode", "JZL"),
                identification.GetValue("CADFZLCode", "FG"),
                identification.GetValue("CADFCLCode", "JCL"),
                identification.GetValue("CADLLCode", "LL"));
            _handler.Request.TasBeamSizeIdentifyMode = identification.GetValue("CADBeamSizeIdentifyMode", "Width * Height");
            _handler.Request.TasMaxColumnSidelineLengthMm = identification.GetDouble("MaxColumnSidelineLen", 1800.0);
            _handler.Request.TasColumnLongShortRatioMax = identification.GetDouble("ShortToLongEdgeRatio", 4.0);
            _handler.Request.TasBeamDefaultHeightMm = identification.GetDouble("CADBeamDefaultHeight", 500.0);
            _handler.Request.TasDefaultSlabThicknessMm = identification.GetDouble("CADDefSlabThickness", 120.0);
            _handler.Request.TasLineMergeMaxDistanceMm = identification.GetDouble("LineMergeSettings", 400.0);
        }

        private static string JoinTasCodes(params string[] values)
        {
            return string.Join(",", (values ?? new string[0])
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Select(value => value.Trim()));
        }

        private void ShowTasIdentificationOptionsDialog()
        {
            TasReferenceSettings tas = EnsureTasReferenceSettings();
            TasIdentificationOptionsProfile profile = EnsureTasIdentificationOptions();
            var dialog = new TasIdentificationOptionsWindow(profile, tas)
            {
                Owner = this
            };

            bool? result = dialog.ShowDialog();
            if (result == true && dialog.SelectedProfile != null)
            {
                _tasIdentificationOptions = dialog.SelectedProfile.Clone();
                _tasIdentificationOptions.Save();
                ApplyTasReferenceSettingsToRequest();
                RefreshCad2ModelTasAttributeRows(
                    _cad2ModelTasActiveCategory,
                    _cad2ModelTasActiveElement,
                    _cad2ModelTasActiveToolName,
                    _cad2ModelTasActiveConnected,
                    null);
                UpdateCad2ModelTasWorkflowRail();
                ShowStatus("IDENTIFY: Identification Options saved. " + _tasIdentificationOptions.BuildWorkflowSummary() + ".");
            }
        }

