        private void ApplyCad2ModelSubTabSvgIcons()
        {
            if (Cad2ModelSubTabControl == null)
            {
                return;
            }

            foreach (object rawItem in Cad2ModelSubTabControl.Items)
            {
                if (!(rawItem is TabItem tabItem) || !(tabItem.Header is StackPanel headerPanel))
                {
                    continue;
                }

                string toolName = tabItem.ToolTip?.ToString() ?? "";
                if (string.IsNullOrWhiteSpace(toolName))
                {
                    continue;
                }

                Border iconBorder = headerPanel.Children.OfType<Border>().FirstOrDefault();
                if (iconBorder == null)
                {
                    continue;
                }

                iconBorder.Child = IdentifySvgIconFactory.CreateIconForTool(toolName, toolName, toolName, "", 48);
            }
        }

        private void ApplyCad2ModelButtonSvgIcons()
        {
            if (Cad2ModelSubTabControl == null)
            {
                return;
            }

            foreach (System.Windows.Controls.Button button in EnumerateLogicalDescendants<System.Windows.Controls.Button>(Cad2ModelSubTabControl))
            {
                if (!(button.Content is string text) || !IsIdentifyIconButtonText(text))
                {
                    continue;
                }

                button.Content = IdentifySvgIconFactory.CreateIconText(text, IdentifySvgIconFactory.ResolveButtonIconFile(text), 16);
                button.HorizontalContentAlignment = System.Windows.HorizontalAlignment.Center;
                button.VerticalContentAlignment = System.Windows.VerticalAlignment.Center;

                double targetWidth = Math.Min(170, Math.Max(82, 34 + (text.Length * 7)));
                if (!double.IsNaN(button.Width) && button.Width > 0 && button.Width < targetWidth)
                {
                    button.Width = targetWidth;
                }
                else if ((double.IsNaN(button.Width) || button.Width <= 0) && button.MinWidth < targetWidth)
                {
                    button.MinWidth = targetWidth;
                }
            }
        }

