        private static IEnumerable<T> EnumerateLogicalDescendants<T>(DependencyObject root)
            where T : DependencyObject
        {
            if (root == null)
            {
                yield break;
            }

            foreach (object rawChild in LogicalTreeHelper.GetChildren(root))
            {
                if (!(rawChild is DependencyObject child))
                {
                    continue;
                }

                if (child is T typedChild)
                {
                    yield return typedChild;
                }

                foreach (T descendant in EnumerateLogicalDescendants<T>(child))
                {
                    yield return descendant;
                }
            }
        }

        private static FrameworkElement CreateCad2ModelTasHeader(
            string label,
            string key,
            string toolName,
            string category,
            bool muted)
        {
            var panel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            };

            panel.Children.Add(IdentifySvgIconFactory.CreateIconForTool(label, key, toolName, category, 24, muted));
            panel.Children.Add(new TextBlock
            {
                Text = label ?? "",
                ToolTip = label ?? "",
                FontSize = 14,
                Margin = new Thickness(8, 0, 0, 0),
                VerticalAlignment = System.Windows.VerticalAlignment.Center
            });

            return panel;
        }

        private static string GetTasHeaderText(object header)
        {
            if (header == null)
            {
                return "";
            }

            if (header is string text)
            {
                return text;
            }

            if (header is TextBlock textBlock)
            {
                return textBlock.Text ?? "";
            }

            if (header is System.Windows.Controls.Panel panel)
            {
                foreach (UIElement child in panel.Children)
                {
                    string childText = GetTasHeaderText(child);
                    if (!string.IsNullOrWhiteSpace(childText))
                    {
                        return childText;
                    }
                }
            }

            return header.ToString() ?? "";
        }

        private void InitializeCad2ModelTasTree()
        {
            if (Cad2ModelTasTree == null || _cad2ModelTasTreeBuilt)
            {
                return;
            }

            Cad2ModelToolRegistry registry = EnsureCad2ModelToolRegistry();

            _cad2ModelTasNavigatorSyncing = true;
            try
            {
                Cad2ModelTasTree.Items.Clear();

                foreach (Cad2ModelToolCategory category in registry.Categories ?? new List<Cad2ModelToolCategory>())
                {
                    TreeViewItem categoryItem = CreateCad2ModelTasCategoryTreeItem(category);
                    Cad2ModelTasTree.Items.Add(categoryItem);
                }

                _cad2ModelTasTreeBuilt = true;
            }
            finally
            {
                _cad2ModelTasNavigatorSyncing = false;
            }
        }

        private TreeViewItem CreateCad2ModelTasCategoryTreeItem(Cad2ModelToolCategory category)
        {
            string categoryName = category?.Name ?? "";
            var categoryItem = new TreeViewItem
            {
                Header = CreateCad2ModelTasHeader(categoryName, categoryName, "", categoryName, false),
                Tag = $"Category|{categoryName}||{categoryName}",
                IsExpanded = category?.IsExpanded == true,
                Style = TryFindResource("TasTreeCategoryItem") as Style
            };

            foreach (Cad2ModelToolItem toolItem in category?.Items ?? new List<Cad2ModelToolItem>())
            {
                categoryItem.Items.Add(CreateCad2ModelTasToolTreeItem(categoryName, toolItem));
            }

            return categoryItem;
        }

        private TreeViewItem CreateCad2ModelTasToolTreeItem(string categoryName, Cad2ModelToolItem toolItem)
        {
            string toolName = toolItem?.ToolName ?? "";
            string label = toolItem?.Label ?? "";
            string key = !string.IsNullOrWhiteSpace(toolItem?.Key) ? toolItem.Key : label;
            string tagType = string.IsNullOrWhiteSpace(toolName) ? "Future" : "Tool";
            string tagValue = string.Equals(tagType, "Tool", StringComparison.OrdinalIgnoreCase)
                ? toolName
                : key;

            return new TreeViewItem
            {
                Header = CreateCad2ModelTasHeader(label, key, toolName, categoryName, string.Equals(tagType, "Future", StringComparison.OrdinalIgnoreCase)),
                Tag = $"{tagType}|{tagValue}|{categoryName}|{label}",
                Style = TryFindResource("TasTreeElementItem") as Style
            };
        }

