        private sealed class Cad2ModelTasAttributeEditorProfile
        {
            private const string SettingsFileName = "attribute-editor.json";

            public string Version { get; set; } = "1.0";
            public List<Cad2ModelTasAttributeEditorItem> Items { get; set; } =
                new List<Cad2ModelTasAttributeEditorItem>();

            public static Cad2ModelTasAttributeEditorProfile Load()
            {
                string path = GetSettingsPath();
                try
                {
                    if (!File.Exists(path))
                    {
                        return new Cad2ModelTasAttributeEditorProfile();
                    }

                    Cad2ModelTasAttributeEditorProfile profile =
                        CamboBimJson.Deserialize<Cad2ModelTasAttributeEditorProfile>(File.ReadAllText(path, Encoding.UTF8));
                    return profile ?? new Cad2ModelTasAttributeEditorProfile();
                }
                catch
                {
                    return new Cad2ModelTasAttributeEditorProfile();
                }
            }

            public void Save()
            {
                string path = GetSettingsPath();
                string directory = Path.GetDirectoryName(path);
                if (!string.IsNullOrWhiteSpace(directory))
                {
                    Directory.CreateDirectory(directory);
                }

                File.WriteAllText(path, CamboBimJson.Serialize(this), new UTF8Encoding(false));
            }

            public Cad2ModelTasAttributeEditorItem Find(string key)
            {
                return (Items ?? new List<Cad2ModelTasAttributeEditorItem>())
                    .FirstOrDefault(item => string.Equals(item?.Key, key, StringComparison.OrdinalIgnoreCase));
            }

            public void Upsert(Cad2ModelTasAttributeEditorItem item)
            {
                if (item == null || string.IsNullOrWhiteSpace(item.Key))
                {
                    return;
                }

                if (Items == null)
                {
                    Items = new List<Cad2ModelTasAttributeEditorItem>();
                }

                Cad2ModelTasAttributeEditorItem existing = Find(item.Key);
                if (existing == null)
                {
                    Items.Add(item);
                    return;
                }

                existing.Category = item.Category ?? "";
                existing.ElementLabel = item.ElementLabel ?? "";
                existing.ScopeLabel = item.ScopeLabel ?? "";
                existing.ToolName = item.ToolName ?? "";
                existing.GroupKey = item.GroupKey ?? "";
                existing.Attribute = item.Attribute ?? "";
                existing.FieldKey = item.FieldKey ?? "";
                existing.Value = item.Value ?? "";
                existing.Add = item.Add;
            }

            private static string GetSettingsPath()
            {
                string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                return Path.Combine(appData, "MHNK", "RevitExtension", "CAD2MODEL", SettingsFileName);
            }
        }

        private sealed class Cad2ModelTasAttributeEditorItem
        {
            public string Key { get; set; } = "";
            public string Category { get; set; } = "";
            public string ElementLabel { get; set; } = "";
            public string ScopeLabel { get; set; } = "";
            public string ToolName { get; set; } = "";
            public string GroupKey { get; set; } = "";
            public string Attribute { get; set; } = "";
            public string FieldKey { get; set; } = "";
            public string Value { get; set; } = "";
            public bool Add { get; set; }
        }

        private sealed class Cad2ModelTasAttributeRow : INotifyPropertyChanged
        {
            private string _value = "";
            private bool _add;

            public bool IsGroup { get; set; }
            public string GroupKey { get; set; } = "";
            public bool IsExpanded { get; set; }
            public string Attribute { get; set; } = "";
            public string FieldKey { get; set; } = "";
            public string Category { get; set; } = "";
            public string ElementLabel { get; set; } = "";
            public string ScopeLabel { get; set; } = "";
            public string ToolName { get; set; } = "";
            public string StorageKey { get; set; } = "";
            public bool IsValueEditable { get; set; } = true;
            public bool IsAddEnabled { get; set; } = true;
            public bool AllowCustomValue { get; set; } = true;
            public bool IsUserEdited { get; set; }
            public ObservableCollection<string> ValueOptions { get; } = new ObservableCollection<string>();

            public string Value
            {
                get => _value;
                set
                {
                    string normalized = value ?? "";
                    if (string.Equals(_value, normalized, StringComparison.Ordinal))
                    {
                        return;
                    }

                    _value = normalized;
                    IsUserEdited = true;
                    OnPropertyChanged(nameof(Value));
                    OnPropertyChanged(nameof(ValueForeground));
                }
            }

            public bool Add
            {
                get => _add;
                set
                {
                    if (_add == value)
                    {
                        return;
                    }

                    _add = value;
                    IsUserEdited = true;
                    OnPropertyChanged(nameof(Add));
                }
            }

            public bool IsValueReadOnly => !IsValueEditable;

            public System.Windows.Visibility ComboVisibility =>
                IsValueEditable && ValueOptions.Count > 0
                    ? System.Windows.Visibility.Visible
                    : System.Windows.Visibility.Collapsed;

            public System.Windows.Visibility TextVisibility =>
                IsValueEditable && ValueOptions.Count > 0
                    ? System.Windows.Visibility.Collapsed
                    : System.Windows.Visibility.Visible;

            public Brush ValueForeground =>
                IsGroup
                    ? Brushes.Transparent
                    : (IsValueEditable ? Brushes.Black : Brushes.Gray);

            public event PropertyChangedEventHandler PropertyChanged;

            private void OnPropertyChanged(string propertyName)
            {
                PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
            }
        }

        private void OnCad2ModelTasAttributeGridBeginningEdit(object sender, DataGridBeginningEditEventArgs e)
        {
            if (!(e.Row?.Item is Cad2ModelTasAttributeRow row) || row.IsGroup || !row.IsValueEditable)
            {
                e.Cancel = true;
            }
        }

        private void TrackCad2ModelTasAttributeRow(Cad2ModelTasAttributeRow row)
        {
            if (row == null)
            {
                return;
            }

            row.PropertyChanged -= OnCad2ModelTasAttributeRowPropertyChanged;
            row.PropertyChanged += OnCad2ModelTasAttributeRowPropertyChanged;
        }

        private void OnCad2ModelTasAttributeRowPropertyChanged(object sender, PropertyChangedEventArgs e)
        {
            if (_cad2ModelTasAttributeEditorRefreshing ||
                !(sender is Cad2ModelTasAttributeRow row) ||
                row.IsGroup ||
                (e.PropertyName != nameof(Cad2ModelTasAttributeRow.Value) &&
                 e.PropertyName != nameof(Cad2ModelTasAttributeRow.Add)))
            {
                return;
            }

            SaveCad2ModelTasAttributeRow(row);
            SyncCad2ModelTasAttributeRowsToSectionSpecs();
            ApplyCad2ModelTasAttributeEditorToRequest();
        }

        private void SaveCad2ModelTasAttributeRow(Cad2ModelTasAttributeRow row)
        {
            if (row == null || row.IsGroup || string.IsNullOrWhiteSpace(row.StorageKey))
            {
                return;
            }

            Cad2ModelTasAttributeEditorProfile profile = EnsureCad2ModelTasAttributeEditorProfile();
            profile.Upsert(new Cad2ModelTasAttributeEditorItem
            {
                Key = row.StorageKey,
                Category = row.Category ?? "",
                ElementLabel = row.ElementLabel ?? "",
                ScopeLabel = row.ScopeLabel ?? "",
                ToolName = row.ToolName ?? "",
                GroupKey = row.GroupKey ?? "",
                Attribute = row.Attribute ?? "",
                FieldKey = row.FieldKey ?? "",
                Value = row.Value ?? "",
                Add = row.Add
            });

            try
            {
                profile.Save();
            }
            catch
            {
                // Attribute edits are still live in this session even if the profile cannot be written.
            }
        }

        private void ApplyStoredTasAttributeValues(Cad2ModelTasAttributeRow row)
        {
            if (row == null || row.IsGroup || string.IsNullOrWhiteSpace(row.StorageKey))
            {
                return;
            }

            Cad2ModelTasAttributeEditorItem stored = EnsureCad2ModelTasAttributeEditorProfile().Find(row.StorageKey);
            if (stored == null)
            {
                row.IsUserEdited = false;
                return;
            }

            row.Value = stored.Value ?? row.Value;
            row.Add = stored.Add;
            row.IsUserEdited = true;
        }

        private static string BuildTasAttributeStorageKey(
            string category,
            string elementLabel,
            string toolName,
            string groupKey,
            string attribute)
        {
            return string.Join("|", new[]
            {
                NormalizeTasAttributeKeyPart(category),
                NormalizeTasAttributeKeyPart(elementLabel),
                NormalizeTasAttributeKeyPart(toolName),
                NormalizeTasAttributeKeyPart(groupKey),
                NormalizeTasAttributeKeyPart(attribute)
            });
        }

        private static string NormalizeTasAttributeKeyPart(string value)
        {
            return Regex.Replace(value ?? "", @"\s+", " ").Trim().ToUpperInvariant();
        }

        private void OnCad2ModelTasTreeSelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (_cad2ModelTasNavigatorSyncing)
            {
                return;
            }

            if (!(e.NewValue is TreeViewItem item))
            {
                return;
            }

            string category = GetTasTreeCategoryName(item);
            string label = GetTasTreeLabel(item);
            string toolName = GetTasTreeToolName(item);

            PopulateCad2ModelTasElementList(category, toolName, false);

            if (IsTasTreeCategory(item))
            {
                UpdateCad2ModelTasAttributePanel(category, category, "", false);
                ShowStatus($"IDENTIFY / {category.ToUpperInvariant()}: Select a TAS sub element from the expanded tree.");
                return;
            }

            SelectCad2ModelTasTool(category, label, toolName);
        }

