            ShowStatus("IDENTIFY: TAS category navigator is active.");
        }

        private void OnCad2ModelTasElementListNavigatorClick(object sender, RoutedEventArgs e)
        {
            SetCad2ModelTasNavigatorMode(showCategoryTree: true, showAttributeEditor: false);
            ShowStatus("IDENTIFY: TAS element list is active.");
        }

        private void OnCad2ModelTasAttributeNavigatorClick(object sender, RoutedEventArgs e)
        {
            SetCad2ModelTasNavigatorMode(showCategoryTree: true, showAttributeEditor: true);
            ShowStatus("IDENTIFY: TAS attribute editor is active.");
        }

        private void SetCad2ModelTasNavigatorMode(bool showCategoryTree, bool showAttributeEditor)
        {
            if (Cad2ModelTasCategoryColumn != null)
            {
                Cad2ModelTasCategoryColumn.Width = showCategoryTree ? new GridLength(260) : new GridLength(0);
                Cad2ModelTasCategoryColumn.MinWidth = showCategoryTree ? 230 : 0;
            }

            if (Cad2ModelTasTree != null)
            {
                Cad2ModelTasTree.Visibility = showCategoryTree ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;
            }

            if (Cad2ModelTasExpandAllButton != null)
            {
                Cad2ModelTasExpandAllButton.Visibility = showCategoryTree ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;
            }

            if (Cad2ModelTasCollapseAllButton != null)
            {
                Cad2ModelTasCollapseAllButton.Visibility = showCategoryTree ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;
            }

            if (Cad2ModelTasAttributePanel != null)
            {
                Cad2ModelTasAttributePanel.Visibility = showAttributeEditor ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;
            }

            if (Cad2ModelTasAttributeSplitter != null)
            {
                Cad2ModelTasAttributeSplitter.Visibility = showAttributeEditor ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;
            }

            if (Cad2ModelTasElementPaneRow != null)
            {
                Cad2ModelTasElementPaneRow.Height = new GridLength(1, GridUnitType.Star);
            }

            if (Cad2ModelTasAttributeSplitterRow != null)
            {
                Cad2ModelTasAttributeSplitterRow.Height = showAttributeEditor ? new GridLength(6) : new GridLength(0);
            }

            if (Cad2ModelTasAttributePaneRow != null)
            {
                Cad2ModelTasAttributePaneRow.Height = showAttributeEditor ? new GridLength(250) : new GridLength(0);
                Cad2ModelTasAttributePaneRow.MinHeight = showAttributeEditor ? 135 : 0;
            }
        }

        private void OnCad2ModelTasElementSelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            if (_cad2ModelTasNavigatorSyncing)
            {
                return;
            }

            SelectCad2ModelTasElementTool(Cad2ModelTasElementList?.SelectedItem as ListBoxItem);
        }

        private void SyncCad2ModelTasNavigatorToActiveTool()
        {
            if (Cad2ModelTasTree == null || Cad2ModelTasElementList == null)
            {
                return;
            }

            InitializeCad2ModelTasTree();

            string toolName = GetActiveCad2ModelToolName();
            if (string.IsNullOrWhiteSpace(toolName))
            {
                return;
            }

            string category = GetTasCategoryForTool(toolName);
            TreeViewItem toolItem = FindTasTreeToolItem(toolName);

            _cad2ModelTasNavigatorSyncing = true;
            try
            {
                if (toolItem != null)
                {
                    toolItem.IsSelected = true;
                    toolItem.BringIntoView();
                }
            }
            finally
            {
                _cad2ModelTasNavigatorSyncing = false;
            }

            PopulateCad2ModelTasElementList(category, toolName, false);
            UpdateCad2ModelTasAttributePanel(category, GetTasElementLabelForTool(toolName), toolName, true);
        }

        private void PopulateCad2ModelTasElementList(string category, string preferredToolName, bool selectSelectedTool)
        {
            if (Cad2ModelTasElementList == null)
            {
                return;
            }

            _cad2ModelTasNavigatorSyncing = true;
            try
            {
                Cad2ModelTasElementList.Items.Clear();

                List<KeyValuePair<string, string>> items = GetTasElementDefinitions(category);
                foreach (KeyValuePair<string, string> item in items)
                {
                    AddCad2ModelTasElementItem(item.Key, item.Value, category);
                }

                ListBoxItem preferredItem = null;
                foreach (object rawItem in Cad2ModelTasElementList.Items)
                {
                    if (rawItem is ListBoxItem listBoxItem &&
                        listBoxItem.Tag is Cad2ModelTasElementTag tag &&
                        !string.IsNullOrWhiteSpace(tag.ToolName) &&
                        string.Equals(tag.ToolName, preferredToolName, StringComparison.OrdinalIgnoreCase))
                    {
                        preferredItem = listBoxItem;
                        break;
                    }
                }

                if (preferredItem == null && Cad2ModelTasElementList.Items.Count > 0)
                {
                    preferredItem = Cad2ModelTasElementList.Items[0] as ListBoxItem;
                }

                Cad2ModelTasElementList.SelectedItem = preferredItem;
            }
            finally
            {
                _cad2ModelTasNavigatorSyncing = false;
            }

            if (selectSelectedTool)
            {
                SelectCad2ModelTasElementTool(Cad2ModelTasElementList.SelectedItem as ListBoxItem);
            }
        }

        private ListBoxItem AddCad2ModelTasElementItem(string label, string toolName, string category)
        {
            ListBoxItem item = new ListBoxItem
            {
                Content = CreateCad2ModelTasHeader(label, label, toolName, category, string.IsNullOrWhiteSpace(toolName)),
                Tag = new Cad2ModelTasElementTag
                {
                    Label = label ?? "",
                    ToolName = toolName ?? "",
                    Category = category ?? ""
                },
                Style = TryFindResource("TasElementItem") as Style
            };

            Cad2ModelTasElementList.Items.Add(item);
            return item;
        }

        private void SelectCad2ModelTasElementTool(ListBoxItem item)
        {
            if (item == null)
            {
                return;
            }

            Cad2ModelTasElementTag tag = item.Tag as Cad2ModelTasElementTag;
            string category = tag?.Category ?? GetSelectedTasTreeCategoryName();
            string label = !string.IsNullOrWhiteSpace(tag?.Label) ? tag.Label : GetTasHeaderText(item.Content);
            string toolName = tag?.ToolName ?? "";

            SelectCad2ModelTasTool(category, label, toolName);
        }

        private void SelectCad2ModelTasTool(string category, string label, string toolName)
        {
            if (string.IsNullOrWhiteSpace(toolName))
            {
                UpdateCad2ModelTasAttributePanel(category, label, "", false);
                ShowStatus($"IDENTIFY / {category.ToUpperInvariant()}: TAS category is prepared for the next identify tool stage.");
                return;
            }

            bool connected = SelectCad2ModelSubTabByToolName(toolName);
            UpdateCad2ModelTasAttributePanel(category, label, toolName, connected);

            if (connected)
            {
                ShowCad2ModelSubTabHint();
            }
            else
            {
                ShowStatus($"IDENTIFY / {label.ToUpperInvariant()}: Tool page is not connected yet.");
            }
        }

        private bool SelectCad2ModelSubTabByToolName(string toolName)
        {
            if (Cad2ModelSubTabControl == null || string.IsNullOrWhiteSpace(toolName))
            {
                return false;
            }

            foreach (object rawItem in Cad2ModelSubTabControl.Items)
            {
                if (rawItem is TabItem tabItem &&
                    string.Equals(tabItem.ToolTip?.ToString(), toolName, StringComparison.OrdinalIgnoreCase))
                {
                    if (!ReferenceEquals(Cad2ModelSubTabControl.SelectedItem, tabItem))
                    {
                        Cad2ModelSubTabControl.SelectedItem = tabItem;
                    }

                    return true;
                }
            }

            return false;
        }

        private TreeViewItem FindTasTreeToolItem(string toolName)
        {
            if (Cad2ModelTasTree == null || string.IsNullOrWhiteSpace(toolName))
            {
                return null;
            }

            foreach (TreeViewItem item in EnumerateTasTreeItems(Cad2ModelTasTree))
            {
                if (string.Equals(GetTasTreeToolName(item), toolName, StringComparison.OrdinalIgnoreCase))
                {
                    return item;
                }
            }

            return null;
        }

        private string GetSelectedTasTreeCategoryName()
        {
            if (Cad2ModelTasTree?.SelectedItem is TreeViewItem item)
            {
                return GetTasTreeCategoryName(item);
            }

            return "";
        }

        private IEnumerable<TreeViewItem> EnumerateTasTreeItems(ItemsControl parent)
        {
            if (parent == null)
            {
                yield break;
            }

            foreach (object rawItem in parent.Items)
            {
                if (!(rawItem is TreeViewItem item))
                {
                    continue;
                }

                yield return item;

                foreach (TreeViewItem child in EnumerateTasTreeItems(item))
                {
                    yield return child;
                }
            }
        }

        private void SetCad2ModelTasTreeExpansion(bool isExpanded)
        {
            if (Cad2ModelTasTree == null)
            {
                return;
            }

            InitializeCad2ModelTasTree();

            foreach (TreeViewItem item in EnumerateTasTreeItems(Cad2ModelTasTree))
            {
                if (item.HasItems)
                {
                    item.IsExpanded = isExpanded;
                }
            }
        }

        private bool IsTasTreeCategory(TreeViewItem item)
        {
            return string.Equals(GetTasTreeTagPart(item, 0), "Category", StringComparison.OrdinalIgnoreCase);
        }

        private string GetTasTreeToolName(TreeViewItem item)
        {
            return string.Equals(GetTasTreeTagPart(item, 0), "Tool", StringComparison.OrdinalIgnoreCase)
                ? GetTasTreeTagPart(item, 1)
                : "";
        }

        private string GetTasTreeCategoryName(TreeViewItem item)
        {
            string tagType = GetTasTreeTagPart(item, 0);
            if (string.Equals(tagType, "Category", StringComparison.OrdinalIgnoreCase))
            {
                return GetTasTreeTagPart(item, 1);
            }

            if (string.Equals(tagType, "Tool", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(tagType, "Future", StringComparison.OrdinalIgnoreCase))
            {
                return GetTasTreeTagPart(item, 2);
            }

            return item?.Header?.ToString() ?? "";
        }

        private string GetTasTreeLabel(TreeViewItem item)
        {
            string taggedLabel = GetTasTreeTagPart(item, 3);
            return !string.IsNullOrWhiteSpace(taggedLabel)
                ? taggedLabel
                : (GetTasHeaderText(item?.Header) ?? GetTasTreeCategoryName(item));
        }

        private string GetTasTreeTagPart(TreeViewItem item, int index)
        {
            string raw = item?.Tag?.ToString() ?? "";
            string[] parts = raw.Split('|');
            return index >= 0 && index < parts.Length ? parts[index] : "";
        }

        private List<KeyValuePair<string, string>> GetTasElementDefinitions(string category)
        {
            var items = new List<KeyValuePair<string, string>>();

            Cad2ModelToolCategory categoryDefinition = EnsureCad2ModelToolRegistry().FindCategory(category);
            foreach (Cad2ModelToolItem item in categoryDefinition?.Items ?? new List<Cad2ModelToolItem>())
            {
                items.Add(new KeyValuePair<string, string>(item.Label ?? "", item.ToolName ?? ""));
            }

            if (items.Count == 0)
            {
                items.Add(new KeyValuePair<string, string>(string.IsNullOrWhiteSpace(category) ? "Not Connected" : category, ""));
            }

            return items;
        }

        private string GetTasCategoryForTool(string toolName)
        {
            return EnsureCad2ModelToolRegistry().GetCategoryForTool(toolName);
        }

        private string GetTasElementLabelForTool(string toolName)
        {
            return EnsureCad2ModelToolRegistry().GetLabelForTool(toolName);
        }

        private string GetTasModeForTool(string toolName)
        {
            switch (toolName)
            {
                case "Lean Concrete":
                case "Soil Excavation":
                    return "Model Source";
                case "":
                    return "Not Connected";
                default:
                    return "Identify / Auto Generate";
            }
        }

        private void UpdateCad2ModelTasAttributePanel(string category, string label, string toolName, bool connected)
        {
            if (Cad2ModelTasPlanText != null)
            {
                Cad2ModelTasPlanText.Text = $"01. {(string.IsNullOrWhiteSpace(category) ? "IDENTIFY" : category.ToUpperInvariant())}";
            }

            RefreshCad2ModelTasCommandRibbon(category, label, toolName, connected);
            RefreshCad2ModelTasAttributeRows(category, label, toolName, connected, null);
        }

        private void RefreshCad2ModelTasCommandRibbon(string category, string label, string toolName, bool connected)
        {
            _cad2ModelTasActiveCategory = category ?? "";
            _cad2ModelTasActiveElement = label ?? "";
            _cad2ModelTasActiveToolName = toolName ?? "";
            _cad2ModelTasActiveConnected = connected && !string.IsNullOrWhiteSpace(toolName);

            string displayCategory = string.IsNullOrWhiteSpace(_cad2ModelTasActiveCategory)
                ? "IDENTIFY"
                : _cad2ModelTasActiveCategory.ToUpperInvariant();
            string displayElement = string.IsNullOrWhiteSpace(_cad2ModelTasActiveElement)
                ? "Select from left navigation"
                : _cad2ModelTasActiveElement;

            if (Cad2ModelTasRibbonCategoryText != null)
            {
                Cad2ModelTasRibbonCategoryText.Text = displayCategory;
            }

            if (Cad2ModelTasRibbonElementText != null)
            {
                Cad2ModelTasRibbonElementText.Text = displayElement;
            }

            if (Cad2ModelTasRibbonTitleText != null)
            {
                Cad2ModelTasRibbonTitleText.Text = _cad2ModelTasActiveConnected
                    ? displayElement.ToUpperInvariant() + " TOOLS"
                    : displayCategory + " TOOLS";
            }

            if (Cad2ModelTasRibbonStatusText != null)
            {
                Cad2ModelTasRibbonStatusText.Text = _cad2ModelTasActiveConnected
                    ? "Context tools follow the selected left navigation element. Source, identify, drawing, then Generate Revit."
                    : "Prepared for TAS-style tools. Select a connected element from the left navigation.";
            }

            bool isColumn = IsActiveTasTool("Column");
            bool isWall = IsActiveTasTool("Wall");
            bool isBeam = IsActiveTasTool("Beam");
            bool hasScheduleTool = isColumn || isWall || isBeam;
            bool canPickLink = _cad2ModelTasActiveConnected && !IsActiveTasTool("Lean Concrete") && !IsActiveTasTool("Soil Excavation");
            bool canPickObjects = _cad2ModelTasActiveConnected;
            bool canAutoIdentify = isColumn || isWall || isBeam;

            SetRibbonButtonState(Cad2ModelTasRibbonPickLinkButton, canPickLink);
            SetRibbonButtonState(Cad2ModelTasRibbonImportAdaptButton, true);
            SetRibbonButtonState(Cad2ModelTasRibbonPickObjectsButton, canPickObjects);
            SetRibbonButtonState(Cad2ModelTasRibbonElementScheduleButton, hasScheduleTool);
            SetRibbonButtonState(Cad2ModelTasRibbonCheckSourceButton, _cad2ModelTasActiveConnected);
            SetRibbonButtonState(Cad2ModelTasRibbonPickSidelineButton, isColumn);
            SetRibbonButtonState(Cad2ModelTasRibbonPickLabelButton, isColumn);
            SetRibbonButtonState(Cad2ModelTasRibbonAutoIdentifyButton, canAutoIdentify);
            SetRibbonButtonState(Cad2ModelTasRibbonClickIdentifyButton, isColumn);
            SetRibbonButtonState(Cad2ModelTasRibbonDragIdentifyButton, isColumn);
            SetRibbonButtonState(Cad2ModelTasRibbonGenerateButton, _cad2ModelTasActiveConnected);

            SetRibbonButtonState(Cad2ModelTasRibbonDrawingManagerButton, true);
            SetRibbonButtonState(Cad2ModelTasRibbonLayerManagerButton, canPickLink);
            SetRibbonButtonState(Cad2ModelTasRibbonApplyAttributeButton, _cad2ModelTasActiveConnected);

            UpdateCad2ModelTasWorkflowRail();
        }

        private static void SetRibbonButtonState(System.Windows.Controls.Button button, bool isEnabled)
        {
            if (button == null)
            {
                return;
            }

            button.IsEnabled = isEnabled;
            button.Opacity = isEnabled ? 1.0 : 0.48;
        }

        private bool IsActiveTasTool(string toolName)
        {
            return string.Equals(_cad2ModelTasActiveToolName, toolName, StringComparison.OrdinalIgnoreCase);
        }

        private bool EnsureCad2ModelTasRibbonToolSelected()
        {
            if (string.IsNullOrWhiteSpace(_cad2ModelTasActiveToolName))
            {
                ShowStatus("IDENTIFY: Select a connected TAS element from the left navigation first.");
                return false;
            }

            bool connected = SelectCad2ModelSubTabByToolName(_cad2ModelTasActiveToolName);
            if (!connected)
            {
                ShowStatus($"IDENTIFY / {GetCad2ModelTasActiveElementForStatus()}: Tool page is not connected yet.");
                return false;
            }

            return true;
        }

        private string GetCad2ModelTasActiveElementForStatus()
        {
            if (!string.IsNullOrWhiteSpace(_cad2ModelTasActiveElement))
            {
                return _cad2ModelTasActiveElement;
            }

            if (!string.IsNullOrWhiteSpace(_cad2ModelTasActiveToolName))
            {
                return _cad2ModelTasActiveToolName;
            }

            return string.IsNullOrWhiteSpace(_cad2ModelTasActiveCategory) ? "IDENTIFY" : _cad2ModelTasActiveCategory;
        }

        private void OnCad2ModelTasRibbonPickLinkClick(object sender, RoutedEventArgs e)
        {
            if (!EnsureCad2ModelTasRibbonToolSelected())
            {
                return;
            }

            OnPickLinkClick(sender, e);
        }

        private void OnCad2ModelTasRibbonPickObjectsClick(object sender, RoutedEventArgs e)
        {
            if (!EnsureCad2ModelTasRibbonToolSelected())
            {
                return;
            }

            OnPickObjectsClick(sender, e);
        }

        private void OnCad2ModelTasRibbonElementScheduleClick(object sender, RoutedEventArgs e)
        {
            if (!EnsureCad2ModelTasRibbonToolSelected())
            {
                return;
            }

            if (IsActiveTasTool("Column"))
            {
                OpenIdentifyElementScheduleWindow(false, "Column");
                return;
            }

            if (IsActiveTasTool("Wall"))
            {
                OpenIdentifyElementScheduleWindow(false, "Wall");
                return;
            }

            if (IsActiveTasTool("Beam"))
            {
                OpenIdentifyElementScheduleWindow(false, "Beam");
                return;
            }

            ShowStatus($"IDENTIFY / {GetCad2ModelTasActiveElementForStatus()}: Element Schedule is not connected for this element yet.");
        }

        private void OnCad2ModelTasRibbonIdentificationOptionsClick(object sender, RoutedEventArgs e)
        {
            ShowTasIdentificationOptionsDialog();
        }

        private void OnCad2ModelTasRibbonCheckSourceClick(object sender, RoutedEventArgs e)
