        private void OnCad2ModelTasRibbonGenerateClick(object sender, RoutedEventArgs e)
        {
            if (!EnsureCad2ModelTasRibbonToolSelected())
            {
                return;
            }

            Cad2ModelTasWorkflowState state = EvaluateCad2ModelTasWorkflowState();
            if (!state.GenerateReady)
            {
                ShowStatus(BuildCad2ModelTasBlockedGenerateMessage(state));
                UpdateCad2ModelTasWorkflowRail();
                return;
            }

            OnGenerateClick(sender, e);
        }

        private void OnCad2ModelTasRibbonApplyAttributeClick(object sender, RoutedEventArgs e)
        {
            if (!EnsureCad2ModelTasRibbonToolSelected())
            {
                return;
            }

            if (!TryUpdateRequestFromUi())
            {
                return;
            }

            int checkedAttributeCount = _handler.Request.TasAttributes?
                .Count(attribute => attribute != null &&
                                    attribute.Add &&
                                    !string.IsNullOrWhiteSpace(attribute.Attribute) &&
                                    !string.IsNullOrWhiteSpace(attribute.Value)) ?? 0;
            if (checkedAttributeCount == 0)
            {
                ShowStatus("Attribute Editor: tick Add for at least one attribute before applying to Revit elements.");
                return;
            }

            _handler.Request.RequestType = CadToModelRequestType.ApplyTasAttributesToSelection;
            _externalEvent.Raise();
        }

        private void OnCad2ModelTasRibbonDrawingToolClick(object sender, RoutedEventArgs e)
        {
            ShowTasDrawingManagerDialog();
        }

        private void ShowTasDrawingManagerDialog()
        {
            Cad2ModelTasWorkflowState state = EvaluateCad2ModelTasWorkflowState();
            TasReferenceSettings tas = EnsureTasReferenceSettings();
            string elementLabel = state.Element;
            string pendingAction = "";

            var root = new System.Windows.Controls.Grid
            {
                Margin = new Thickness(16)
            };
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1.0, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var header = new StackPanel
            {
                Margin = new Thickness(0, 0, 0, 12)
            };
            header.Children.Add(new TextBlock
            {
                Text = "TAS Drawing Manager",
                FontSize = 18,
                FontWeight = System.Windows.FontWeights.Bold,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(31, 42, 61))
            });
            header.Children.Add(new TextBlock
            {
                Text = $"{elementLabel} - {state.NextStepText}",
                FontSize = 12,
                TextWrapping = TextWrapping.Wrap,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(82, 97, 115)),
                Margin = new Thickness(0, 4, 0, 0)
            });
            System.Windows.Controls.Grid.SetRow(header, 0);
            root.Children.Add(header);

            var summaryPanel = new UniformGrid
            {
                Columns = 4,
                Margin = new Thickness(0, 0, 0, 12)
            };
            summaryPanel.Children.Add(BuildTasDrawingManagerSummaryCard("Source", state.SourceText, state.SourceReady));
            summaryPanel.Children.Add(BuildTasDrawingManagerSummaryCard("Schedule", state.ScheduleText, state.ScheduleReady));
            summaryPanel.Children.Add(BuildTasDrawingManagerSummaryCard("Identify", state.IdentifyText, state.IdentifyReady));
            summaryPanel.Children.Add(BuildTasDrawingManagerSummaryCard("Generate", state.GenerateText, state.GenerateReady));
            System.Windows.Controls.Grid.SetRow(summaryPanel, 1);
            root.Children.Add(summaryPanel);

            var managerGrid = new DataGrid
            {
                AutoGenerateColumns = false,
                CanUserAddRows = false,
                IsReadOnly = true,
                HeadersVisibility = DataGridHeadersVisibility.Column,
                GridLinesVisibility = DataGridGridLinesVisibility.Horizontal,
                SelectionMode = DataGridSelectionMode.Single,
                ItemsSource = BuildTasDrawingManagerRows(state, tas),
                Margin = new Thickness(0, 0, 0, 12)
            };
            managerGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Area",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasDrawingManagerRow.Area)),
                Width = new DataGridLength(130)
            });
            managerGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Status",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasDrawingManagerRow.Status)),
                Width = new DataGridLength(115)
            });
            managerGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Current Value",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasDrawingManagerRow.CurrentValue)),
                Width = new DataGridLength(220)
            });
            managerGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "TAS Workflow Note",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasDrawingManagerRow.Note)),
                Width = new DataGridLength(1.0, DataGridLengthUnitType.Star)
            });
            System.Windows.Controls.Grid.SetRow(managerGrid, 2);
            root.Children.Add(managerGrid);

            var buttonPanel = new StackPanel
            {
                Orientation = System.Windows.Controls.Orientation.Horizontal,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Right
            };
            var sourceButton = BuildTasDialogActionButton(
                IsActiveTasTool("Lean Concrete") || IsActiveTasTool("Soil Excavation") ? "Pick Objects" : "Pick Link",
                state.IsConnected,
                () => pendingAction = "Source");
            var layerButton = BuildTasDialogActionButton("Layer Recognition", state.IsConnected && GetActiveCad2ModelLayerCombo() != null, () => pendingAction = "Layer");
            var scheduleButton = BuildTasDialogActionButton("Element Schedule", state.IsConnected && state.ScheduleApplies, () => pendingAction = "Schedule");
            var checkButton = BuildTasDialogActionButton("Check Source", state.IsConnected, () => pendingAction = "Check");
            var generateButton = BuildTasDialogActionButton("Generate Revit", state.IsConnected, () => pendingAction = "Generate");
            var closeButton = new Button
            {
                Content = "Close",
                MinWidth = 86,
                Height = 32,
                IsCancel = true
            };

            buttonPanel.Children.Add(sourceButton);
            buttonPanel.Children.Add(layerButton);
            buttonPanel.Children.Add(scheduleButton);
            buttonPanel.Children.Add(checkButton);
            buttonPanel.Children.Add(generateButton);
            buttonPanel.Children.Add(closeButton);
            System.Windows.Controls.Grid.SetRow(buttonPanel, 3);
            root.Children.Add(buttonPanel);

            var dialog = new Window
            {
                Title = $"TAS Drawing Manager - {elementLabel}",
                Owner = this,
                Width = 860,
                Height = 560,
                MinWidth = 760,
                MinHeight = 440,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ResizeMode = ResizeMode.CanResize,
                ShowInTaskbar = false,
                Content = root
            };

            foreach (Button button in buttonPanel.Children.OfType<Button>().Where(b => !ReferenceEquals(b, closeButton)))
            {
                button.Click += (s, e) => dialog.DialogResult = true;
            }

            bool? accepted = dialog.ShowDialog();
            if (accepted != true || string.IsNullOrWhiteSpace(pendingAction))
            {
                ShowStatus($"Drawing Manager: {elementLabel} source review closed.");
                return;
            }

            RunTasDrawingManagerAction(pendingAction);
        }

        private static Border BuildTasDrawingManagerSummaryCard(string title, string value, bool ready)
        {
            WpfColor background = ready
                ? WpfColor.FromRgb(236, 253, 245)
                : WpfColor.FromRgb(255, 247, 237);
            WpfColor border = ready
                ? WpfColor.FromRgb(110, 231, 183)
                : WpfColor.FromRgb(253, 186, 116);

            var panel = new StackPanel();
            panel.Children.Add(new TextBlock
            {
                Text = title ?? "",
                FontSize = 11,
                FontWeight = System.Windows.FontWeights.Bold,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(82, 97, 115))
            });
            panel.Children.Add(new TextBlock
            {
                Text = value ?? "",
                FontSize = 14,
                FontWeight = System.Windows.FontWeights.Bold,
                TextWrapping = TextWrapping.Wrap,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(31, 42, 61)),
                Margin = new Thickness(0, 4, 0, 0)
            });

            return new Border
            {
                Child = panel,
                Background = new SolidColorBrush(background),
                BorderBrush = new SolidColorBrush(border),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6),
                Padding = new Thickness(10),
                Margin = new Thickness(0, 0, 8, 0)
            };
        }

        private static Button BuildTasDialogActionButton(string text, bool isEnabled, Action setAction)
        {
            var button = new Button
            {
                Content = text ?? "",
                MinWidth = 104,
                Height = 32,
                Margin = new Thickness(0, 0, 8, 0),
                IsEnabled = isEnabled,
                Opacity = isEnabled ? 1.0 : 0.48
            };
            button.Click += (s, e) => setAction?.Invoke();
            return button;
        }

        private List<Cad2ModelTasDrawingManagerRow> BuildTasDrawingManagerRows(
            Cad2ModelTasWorkflowState state,
            TasReferenceSettings tas)
        {
            string linkName = GetActiveCad2ModelLinkName();
            int layerCount = GetComboLayerNames(GetActiveCad2ModelLayerCombo()).Count;
            string selectedLayer = GetSelectedLayerName();
            string selectedLabelLayer = GetSelectedLabelLayerName();
            string missingText = state.Missing.Count == 0 ? "None" : string.Join(", ", state.Missing);

            return new List<Cad2ModelTasDrawingManagerRow>
            {
                new Cad2ModelTasDrawingManagerRow(
                    "CAD Source",
                    state.SourceReady ? "Ready" : "Waiting",
                    linkName,
                    state.SourceReady ? "Source is bound to the active IDENTIFY tool." : "Pick Link or Pick Objects before generating."),
                new Cad2ModelTasDrawingManagerRow(
                    "Layer",
                    string.IsNullOrWhiteSpace(selectedLayer) ? "Waiting" : "Ready",
                    string.IsNullOrWhiteSpace(selectedLayer) ? $"Available layers: {layerCount}" : selectedLayer,
                    BuildTasSmartLayerAdvisorText(_cad2ModelTasActiveToolName)),
                new Cad2ModelTasDrawingManagerRow(
                    "Label Layer",
                    string.IsNullOrWhiteSpace(selectedLabelLayer) ? "Optional" : "Ready",
                    string.IsNullOrWhiteSpace(selectedLabelLayer) ? "Not selected" : selectedLabelLayer,
                    "Used by TAS-style schedule and label recognition where the element supports text labels."),
                new Cad2ModelTasDrawingManagerRow(
                    "Element Schedule",
                    state.ScheduleReady ? "Ready" : "Waiting",
                    state.ScheduleText,
                    state.ScheduleApplies ? "Scan, paste, or import the section table before generation." : "This element does not require a schedule table."),
                new Cad2ModelTasDrawingManagerRow(
                    "Identify",
                    state.IdentifyReady ? "Ready" : "Waiting",
                    state.IdentifyText,
                    "Use Pick Sideline, Layer Recognition, or Auto-Identify depending on the active element."),
                new Cad2ModelTasDrawingManagerRow(
                    "TAS Reference",
                    tas.IsInstalled ? "Loaded" : "Missing",
                    tas.IsInstalled ? $"{tas.DisplayVersion}, AIConfig {(tas.AiConfigLoaded ? "loaded" : "not loaded")}" : "TAS reference not found",
                    tas.IsInstalled
                        ? $"CAD search {tas.CadLineSearchMaxDistanceMm.ToString("0.#", CultureInfo.InvariantCulture)} mm, parallel angle {tas.CadLineParallelAngleEpsilonDeg.ToString("0.#", CultureInfo.InvariantCulture)} deg."
                        : "Install Cubicost TAS or keep the default recognition tolerances."),
                new Cad2ModelTasDrawingManagerRow(
                    "Generate",
                    state.GenerateReady ? "Ready" : "Blocked",
                    missingText,
                    state.GenerateReady ? "Ready to generate Revit elements." : state.NextStepText)
            };
        }

        private string GetActiveCad2ModelLinkName()
        {
            string text = GetActiveCad2ModelLinkNameTextBox()?.Text ?? "";
            return string.IsNullOrWhiteSpace(text) ? "(not selected)" : text;
        }

        private System.Windows.Controls.TextBox GetActiveCad2ModelLinkNameTextBox()
        {
            if (IsGridlineTab()) return LinkNameTextBox_Grid;
            if (IsBoredPileTab()) return LinkNameTextBox_Bored;
            if (IsFoundationTab()) return LinkNameTextBox_Foundation;
            if (IsSlabTab()) return LinkNameTextBox_Slab;
            if (IsWallTab()) return LinkNameTextBox_Wall;
            if (IsBeamTab()) return LinkNameTextBox_Beam;
            if (IsColumnTabActive()) return LinkNameTextBox;
            if (IsDrawingTab()) return GetDrawingLinkNameTextBox();
            return LinkNameTextBox;
        }

        private void RunTasDrawingManagerAction(string action)
        {
            if (string.Equals(action, "Source", StringComparison.OrdinalIgnoreCase))
            {
                if (IsActiveTasTool("Lean Concrete") || IsActiveTasTool("Soil Excavation"))
                {
                    OnCad2ModelTasRibbonPickObjectsClick(this, new RoutedEventArgs());
                    return;
                }

                OnCad2ModelTasRibbonPickLinkClick(this, new RoutedEventArgs());
                return;
            }

            if (string.Equals(action, "Layer", StringComparison.OrdinalIgnoreCase))
            {
                ShowTasLayerRecognitionDialog();
                return;
            }

            if (string.Equals(action, "Schedule", StringComparison.OrdinalIgnoreCase))
            {
                OnCad2ModelTasRibbonElementScheduleClick(this, new RoutedEventArgs());
                return;
            }

            if (string.Equals(action, "Check", StringComparison.OrdinalIgnoreCase))
            {
                OnCad2ModelTasRibbonCheckSourceClick(this, new RoutedEventArgs());
                return;
            }

            if (string.Equals(action, "Generate", StringComparison.OrdinalIgnoreCase))
            {
                OnCad2ModelTasRibbonGenerateClick(this, new RoutedEventArgs());
            }
        }

        private void OnCad2ModelTasRibbonLayerManagerClick(object sender, RoutedEventArgs e)
        {
            if (!EnsureCad2ModelTasRibbonToolSelected())
            {
                return;
            }

            ShowTasLayerRecognitionDialog();
        }

        private void ShowTasLayerRecognitionDialog()
        {
            System.Windows.Controls.ComboBox layerCombo = GetActiveCad2ModelLayerCombo();
            string elementLabel = GetCad2ModelTasActiveElementForStatus();
            if (layerCombo == null)
            {
                ShowStatus($"IDENTIFY / {elementLabel}: Layer Manager is not required for this tool.");
                return;
            }

            string toolName = GetActiveCad2ModelToolName();
            List<string> layerNames = GetComboLayerNames(layerCombo);
            if (layerNames.Count == 0)
            {
                ShowStatus($"IDENTIFY / {elementLabel}: Pick Link first so Layer Manager can read DWG layers.");
                return;
            }

            List<Cad2ModelTasLayerCandidate> mainCandidates = BuildTasLayerCandidates(toolName, layerNames, includeLabelLayers: false);
            Cad2ModelTasLayerCandidate recommendedMain = mainCandidates.FirstOrDefault(c => c.Score > 0) ?? mainCandidates.FirstOrDefault();
            string currentMainName = layerCombo.SelectedItem?.ToString() ?? recommendedMain?.Name ?? "";

            System.Windows.Controls.ComboBox labelCombo = GetActiveCad2ModelLabelLayerCombo();
            List<Cad2ModelTasLayerCandidate> labelCandidates = new List<Cad2ModelTasLayerCandidate>();
            if (labelCombo != null)
            {
                List<string> labelLayerNames = GetComboLayerNames(labelCombo);
                labelCandidates = BuildTasLayerCandidates(toolName, labelLayerNames, includeLabelLayers: true);
            }

            Cad2ModelTasLayerCandidate recommendedLabel = labelCandidates.FirstOrDefault(c => c.Score > 0);
            string currentLabelName = labelCombo?.SelectedItem?.ToString() ?? recommendedLabel?.Name ?? "";

            var mainSelector = new System.Windows.Controls.ComboBox
            {
                ItemsSource = mainCandidates,
                DisplayMemberPath = nameof(Cad2ModelTasLayerCandidate.DisplayText),
                MinWidth = 270,
                Height = 30,
                Margin = new Thickness(0, 5, 0, 0)
            };
            mainSelector.SelectedItem = mainCandidates.FirstOrDefault(c => string.Equals(c.Name, currentMainName, StringComparison.OrdinalIgnoreCase))
                ?? recommendedMain;

            var labelSelector = new System.Windows.Controls.ComboBox
            {
                ItemsSource = labelCandidates,
                DisplayMemberPath = nameof(Cad2ModelTasLayerCandidate.DisplayText),
                MinWidth = 270,
                Height = 30,
                Margin = new Thickness(0, 5, 0, 0),
                IsEnabled = labelCandidates.Count > 0
            };
            labelSelector.SelectedItem = labelCandidates.FirstOrDefault(c => string.Equals(c.Name, currentLabelName, StringComparison.OrdinalIgnoreCase))
                ?? recommendedLabel;

            List<Cad2ModelTasLayerDialogRow> rows = BuildTasLayerDialogRows(
                mainCandidates,
                labelCandidates,
                (mainSelector.SelectedItem as Cad2ModelTasLayerCandidate)?.Name,
                (labelSelector.SelectedItem as Cad2ModelTasLayerCandidate)?.Name);

            var grid = new System.Windows.Controls.Grid();
            grid.Margin = new Thickness(16);
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            grid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1.0, GridUnitType.Star) });
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var title = new TextBlock
            {
                Text = $"TAS Layer Recognition - {elementLabel}",
                FontSize = 18,
                FontWeight = System.Windows.FontWeights.Bold,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(31, 42, 61))
            };
            System.Windows.Controls.Grid.SetRow(title, 0);
            grid.Children.Add(title);

            var selectorPanel = new StackPanel
            {
                Orientation = System.Windows.Controls.Orientation.Horizontal,
                Margin = new Thickness(0, 14, 0, 12)
            };
            selectorPanel.Children.Add(BuildTasLayerSelectorPanel(
                "Main CAD Layer",
                mainSelector,
                recommendedMain == null ? "No confident layer was found." : $"Recommended: {recommendedMain.Name}"));
            selectorPanel.Children.Add(BuildTasLayerSelectorPanel(
                "Label / Text Layer",
                labelSelector,
                labelCandidates.Count == 0 ? "No label layer is required for this tool." : $"Recommended: {(recommendedLabel == null ? "manual check" : recommendedLabel.Name)}"));
            System.Windows.Controls.Grid.SetRow(selectorPanel, 1);
            grid.Children.Add(selectorPanel);

            var candidateGrid = new DataGrid
            {
                AutoGenerateColumns = false,
                CanUserAddRows = false,
                IsReadOnly = true,
                HeadersVisibility = DataGridHeadersVisibility.Column,
                GridLinesVisibility = DataGridGridLinesVisibility.Horizontal,
                SelectionMode = DataGridSelectionMode.Single,
                ItemsSource = rows,
                Margin = new Thickness(0, 0, 0, 12)
            };
            candidateGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Use",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasLayerDialogRow.Usage)),
                Width = new DataGridLength(90)
            });
            candidateGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Rank",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasLayerDialogRow.Rank)),
                Width = new DataGridLength(60)
            });
            candidateGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Layer",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasLayerDialogRow.Layer)),
                Width = new DataGridLength(1.0, DataGridLengthUnitType.Star)
            });
            candidateGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Score",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasLayerDialogRow.Score)),
                Width = new DataGridLength(70)
            });
            candidateGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Status",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasLayerDialogRow.Status)),
                Width = new DataGridLength(110)
            });
            candidateGrid.Columns.Add(new DataGridTextColumn
            {
                Header = "Reason",
                Binding = new System.Windows.Data.Binding(nameof(Cad2ModelTasLayerDialogRow.Reason)),
                Width = new DataGridLength(220)
            });
            Action refreshCandidateRows = () =>
            {
                candidateGrid.ItemsSource = BuildTasLayerDialogRows(
                    mainCandidates,
                    labelCandidates,
                    (mainSelector.SelectedItem as Cad2ModelTasLayerCandidate)?.Name,
                    (labelSelector.SelectedItem as Cad2ModelTasLayerCandidate)?.Name);
            };
            mainSelector.SelectionChanged += (s, e) => refreshCandidateRows();
            labelSelector.SelectionChanged += (s, e) => refreshCandidateRows();
            System.Windows.Controls.Grid.SetRow(candidateGrid, 2);
            grid.Children.Add(candidateGrid);

            var buttons = new StackPanel
            {
                Orientation = System.Windows.Controls.Orientation.Horizontal,
                HorizontalAlignment = System.Windows.HorizontalAlignment.Right
            };
            var autoButton = new Button
            {
                Content = "Auto Select",
                MinWidth = 104,
                Height = 32,
                Margin = new Thickness(0, 0, 8, 0)
            };
            var applyButton = new Button
            {
                Content = "Apply",
                MinWidth = 92,
                Height = 32,
                Margin = new Thickness(0, 0, 8, 0),
                IsDefault = true
            };
            var cancelButton = new Button
            {
                Content = "Cancel",
                MinWidth = 92,
                Height = 32,
                IsCancel = true
            };
            buttons.Children.Add(autoButton);
            buttons.Children.Add(applyButton);
            buttons.Children.Add(cancelButton);
            System.Windows.Controls.Grid.SetRow(buttons, 3);
            grid.Children.Add(buttons);

            var dialog = new Window
            {
                Title = $"TAS Layer Recognition - {elementLabel}",
                Owner = this,
                Width = 780,
                Height = 560,
                MinWidth = 680,
                MinHeight = 430,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ResizeMode = ResizeMode.CanResize,
                ShowInTaskbar = false,
                Content = grid
            };

            autoButton.Click += (s, e) =>
            {
                if (recommendedMain != null)
                {
                    mainSelector.SelectedItem = recommendedMain;
                }

                if (recommendedLabel != null)
                {
                    labelSelector.SelectedItem = recommendedLabel;
                }
            };
            applyButton.Click += (s, e) => dialog.DialogResult = true;

            bool? accepted = dialog.ShowDialog();
            if (accepted != true)
            {
                ShowStatus($"Layer Recognition: cancelled for {elementLabel}.");
                return;
            }

            Cad2ModelTasLayerCandidate selectedMain = mainSelector.SelectedItem as Cad2ModelTasLayerCandidate;
            if (selectedMain == null || string.IsNullOrWhiteSpace(selectedMain.Name))
            {
                ShowStatus($"Layer Recognition: select a main CAD layer for {elementLabel}.");
                return;
            }

            SelectComboItemByName(layerCombo, selectedMain.Name);
            EnsureActiveLayerModeForTool();

            string labelMessage = "";
            Cad2ModelTasLayerCandidate selectedLabel = labelSelector.SelectedItem as Cad2ModelTasLayerCandidate;
            if (labelCombo != null && selectedLabel != null && !string.IsNullOrWhiteSpace(selectedLabel.Name))
            {
                SelectComboItemByName(labelCombo, selectedLabel.Name);
                labelMessage = $", label '{selectedLabel.Name}'";
            }

            RefreshCad2ModelTasAttributeRows(
                _cad2ModelTasActiveCategory,
                _cad2ModelTasActiveElement,
                _cad2ModelTasActiveToolName,
                _cad2ModelTasActiveConnected,
                null);
            RefreshCad2ModelTasLayerManagerTooltip();
            UpdateCad2ModelTasWorkflowRail();
            ShowStatus($"Layer Recognition: applied {elementLabel} layer '{selectedMain.Name}'{labelMessage}. {FormatLayerCandidateSummary(mainCandidates)}");
        }

        private static Border BuildTasLayerSelectorPanel(
            string title,
            System.Windows.Controls.ComboBox selector,
            string note)
        {
            var panel = new StackPanel();
            panel.Children.Add(new TextBlock
            {
                Text = title,
                FontWeight = System.Windows.FontWeights.Bold,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(31, 42, 61))
            });
            panel.Children.Add(selector);
            panel.Children.Add(new TextBlock
            {
                Text = note ?? "",
                FontSize = 11,
                TextWrapping = TextWrapping.Wrap,
                Foreground = new SolidColorBrush(WpfColor.FromRgb(82, 97, 115)),
                Margin = new Thickness(0, 6, 0, 0)
            });

            return new Border
            {
                Child = panel,
                Background = new SolidColorBrush(WpfColor.FromRgb(245, 248, 252)),
                BorderBrush = new SolidColorBrush(WpfColor.FromRgb(214, 224, 236)),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(6),
                Padding = new Thickness(12),
                Margin = new Thickness(0, 0, 12, 0),
                Width = 350
            };
        }

        private void OnCad2ModelTasWorkflowCardClick(object sender, MouseButtonEventArgs e)
        {
            if (!(sender is Border card))
            {
                return;
            }

            string step = card.Tag as string ?? "";
            if (string.Equals(step, "Generate", StringComparison.OrdinalIgnoreCase))
            {
                OnCad2ModelTasRibbonGenerateClick(sender, e);
                return;
            }

            if (!EnsureCad2ModelTasRibbonToolSelected())
            {
                return;
            }

            if (string.Equals(step, "Source", StringComparison.OrdinalIgnoreCase))
            {
                if (IsActiveTasTool("Lean Concrete") || IsActiveTasTool("Soil Excavation"))
                {
                    OnPickObjectsClick(sender, e);
                }
                else
                {
                    OnPickLinkClick(sender, e);
                }
                return;
            }

            if (string.Equals(step, "Schedule", StringComparison.OrdinalIgnoreCase))
            {
                Cad2ModelTasWorkflowState state = EvaluateCad2ModelTasWorkflowState();
                if (state.ScheduleApplies)
                {
                    OnCad2ModelTasRibbonElementScheduleClick(sender, e);
                }
                else
                {
                    ShowStatus($"IDENTIFY / {state.Element}: Element Schedule is not required for this tool.");
                }
                return;
            }

            if (string.Equals(step, "Identify", StringComparison.OrdinalIgnoreCase))
            {
                if (IsActiveTasTool("Column"))
                {
                    OnCad2ModelTasRibbonPickSidelineClick(sender, e);
                    return;
                }

                if (IsActiveTasTool("Wall") || IsActiveTasTool("Beam"))
                {
                    OnCad2ModelTasRibbonAutoIdentifyClick(sender, e);
                    return;
                }

                ShowStatus(BuildCad2ModelTasSourceCheckMessage());
            }
        }

        private sealed class Cad2ModelTasWorkflowState
        {
            public bool IsConnected { get; set; }
            public bool SourceReady { get; set; }
            public bool ScheduleReady { get; set; }
            public bool IdentifyReady { get; set; }
            public bool GenerateReady { get; set; }
            public bool ScheduleApplies { get; set; }
            public string Element { get; set; } = "";
            public string SourceText { get; set; } = "";
            public string ScheduleText { get; set; } = "";
            public string IdentifyText { get; set; } = "";
            public string GenerateText { get; set; } = "";
            public string LayerText { get; set; } = "";
            public string LabelText { get; set; } = "";
            public string TasText { get; set; } = "";
            public string NextStepText { get; set; } = "";
            public List<string> Missing { get; } = new List<string>();
        }

        private Cad2ModelTasWorkflowState EvaluateCad2ModelTasWorkflowState()
        {
            TasReferenceSettings tas = EnsureTasReferenceSettings();
            CadToModelRequest request = _handler?.Request;
            string toolName = _cad2ModelTasActiveToolName ?? "";
            string element = GetCad2ModelTasActiveElementForStatus();
            string layerName = GetSelectedLayerName();
            string labelLayerName = GetSelectedLabelLayerName();
            TasIdentificationOptionsProfile options = EnsureTasIdentificationOptions();

            var state = new Cad2ModelTasWorkflowState
            {
                IsConnected = _cad2ModelTasActiveConnected,
                Element = element,
                LayerText = string.IsNullOrWhiteSpace(layerName) ? "Layer: -" : "Layer: " + layerName,
                LabelText = string.IsNullOrWhiteSpace(labelLayerName) ? "" : ", Label: " + labelLayerName,
                TasText = tas.IsInstalled
                    ? $"TAS {tas.DisplayVersion}, {options.BuildSummaryForTool(toolName)}"
                    : "TAS reference not found, " + options.BuildSummaryForTool(toolName)
            };

            if (string.IsNullOrWhiteSpace(toolName) || !_cad2ModelTasActiveConnected)
            {
                state.Missing.Add("Select connected element");
                state.SourceText = "Select element";
                state.ScheduleText = "Waiting";
                state.IdentifyText = "Waiting";
                state.GenerateText = "Waiting";
                state.NextStepText = BuildCad2ModelTasNextStepText(state);
                return state;
            }

            bool needsCadLink = !IsActiveTasTool("Lean Concrete") && !IsActiveTasTool("Soil Excavation");
            bool hasCadLink = request != null && request.SelectedLinkId != ElementId.InvalidElementId;

            if (needsCadLink)
            {
                state.SourceReady = hasCadLink;
                state.SourceText = hasCadLink ? "CAD linked" : "Need Pick Link";
                if (!hasCadLink)
                {
                    state.Missing.Add("Pick Link");
                }
            }
            else if (IsActiveTasTool("Lean Concrete"))
            {
                int count = request?.SelectedLeanSourceElementIds?.Count ?? 0;
                state.SourceReady = count > 0;
                state.SourceText = count > 0 ? $"Model source {count}" : "Need source elements";
                if (count == 0)
                {
                    state.Missing.Add("Pick modeled source elements");
                }
            }
            else if (IsActiveTasTool("Soil Excavation"))
            {
                int count = request?.SelectedSoilExcavationSourceElementIds?.Count ?? 0;
                state.SourceReady = count > 0;
                state.SourceText = count > 0 ? $"Lean source {count}" : "Need lean source";
                if (count == 0)
                {
                    state.Missing.Add("Pick lean concrete source");
                }
            }
            else
            {
                state.SourceReady = true;
                state.SourceText = "Ready";
            }

            state.ScheduleApplies = IsActiveTasTool("Column") || IsActiveTasTool("Wall") || IsActiveTasTool("Beam");
            if (IsActiveTasTool("Column"))
            {
                int count = _columnSectionSpecs.Count;
                state.ScheduleReady = count > 0;
                state.ScheduleText = count > 0 ? $"{count} type row(s)" : "Need schedule";
                if (count == 0)
                {
                    state.Missing.Add("Element Schedule");
                }
            }
            else if (IsActiveTasTool("Wall"))
            {
                int count = _wallSectionSpecs.Count;
                state.ScheduleReady = true;
                state.ScheduleText = count > 0 ? $"{count} type row(s)" : "Type fallback";
            }
            else if (IsActiveTasTool("Beam"))
            {
                int count = _beamSectionSpecs.Count;
                state.ScheduleReady = true;
                state.ScheduleText = count > 0 ? $"{count} type row(s)" : "Type fallback";
            }
            else
            {
                state.ScheduleReady = true;
                state.ScheduleText = "Not required";
            }

            state.IdentifyReady = ResolveCad2ModelTasIdentifyReady(request, layerName, state.Missing, out string identifyText);
            state.IdentifyText = identifyText;
            state.GenerateReady = state.IsConnected && state.SourceReady && state.ScheduleReady && state.IdentifyReady;
            state.GenerateText = state.GenerateReady ? "Ready" : "Waiting";
            state.NextStepText = BuildCad2ModelTasNextStepText(state);
            return state;
        }

        private bool ResolveCad2ModelTasIdentifyReady(
            CadToModelRequest request,
            string layerName,
            List<string> missing,
            out string identifyText)
        {
            identifyText = "Ready";

            if (IsActiveTasTool("Column"))
            {
                bool hasSidelineSelection =
                    request != null &&
                    ((request.SelectedColumnSidelineReferences != null && request.SelectedColumnSidelineReferences.Count > 0) ||
                     request.HasSelectedColumnSidelineBox ||
                     !string.IsNullOrWhiteSpace(request.SelectedColumnSidelineColorKey));
                bool hasLayer = !string.IsNullOrWhiteSpace(layerName);

                if (hasSidelineSelection)
                {
                    identifyText = "Sideline picked";
                    return true;
                }

                if (hasLayer)
                {
                    identifyText = "Layer ready";
                    return true;
                }

                missing.Add("Pick Sideline or select Column layer");
                identifyText = "Need sideline";
                return false;
            }

            if (IsActiveTasTool("Wall"))
            {
                if (!string.IsNullOrWhiteSpace(layerName))
                {
                    identifyText = "Wall layer ready";
                    return true;
                }

                missing.Add("Wall layer");
                identifyText = "Need wall layer";
                return false;
            }

            if (IsActiveTasTool("Beam"))
            {
                if (!string.IsNullOrWhiteSpace(layerName))
                {
                    identifyText = "Beam layer ready";
                    return true;
                }

                missing.Add("Beam layer");
                identifyText = "Need beam layer";
                return false;
            }

            if (IsActiveTasTool("Gridline") || IsActiveTasTool("Bored Pile") ||
                IsActiveTasTool("Foundation") || IsActiveTasTool("Slab"))
            {
                if (!string.IsNullOrWhiteSpace(layerName))
                {
                    identifyText = "CAD layer ready";
                    return true;
                }

                missing.Add("CAD layer");
                identifyText = "Need CAD layer";
                return false;
            }

            identifyText = IsActiveTasTool("Lean Concrete") || IsActiveTasTool("Soil Excavation")
                ? "Model source"
                : "Ready";
            return true;
        }

        private string BuildCad2ModelTasNextStepText(Cad2ModelTasWorkflowState state)
        {
            if (state == null || !state.IsConnected)
            {
                return "Select a connected IDENTIFY element from the left navigation.";
            }

            if (state.Missing.Count == 0)
            {
                return $"Ready to Generate Revit for {state.Element}. Confirm level/type settings, then click Generate Revit.";
            }

            string first = state.Missing[0] ?? "";
            if (first.IndexOf("Pick Link", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: Pick Link to bind the DWG source, then select the correct CAD layer.";
            }

            if (first.IndexOf("Element Schedule", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: open Element Schedule and scan, paste, or import the TAS-style type table.";
            }

            if (first.IndexOf("Sideline", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: use Pick Sideline or choose the Column layer before Auto-Identify.";
            }

            if (first.IndexOf("Wall layer", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: choose the wall centerline layer, then Auto-Identify or Generate.";
            }

            if (first.IndexOf("Beam layer", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: choose the beam centerline layer, then Auto-Identify or Generate.";
            }

            if (first.IndexOf("CAD layer", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: choose the CAD layer for this element, then Generate Revit.";
            }

            if (first.IndexOf("modeled source", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: Pick Objects from the Revit model source elements.";
            }

            if (first.IndexOf("lean concrete", StringComparison.OrdinalIgnoreCase) >= 0 ||
                first.IndexOf("lean source", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Next: Pick Objects from generated lean concrete before soil excavation.";
            }

            return "Next: complete " + first + ".";
        }

        private string BuildCad2ModelTasBlockedGenerateMessage(Cad2ModelTasWorkflowState state)
        {
            if (state == null)
            {
                return "IDENTIFY: Generate is not ready. Complete Source, Schedule, and Identify first.";
            }

            string missingText = state.Missing.Count == 0
                ? "required inputs"
                : string.Join(", ", state.Missing);
            string next = string.IsNullOrWhiteSpace(state.NextStepText)
                ? BuildCad2ModelTasNextStepText(state)
                : state.NextStepText;
            return $"IDENTIFY / {state.Element}: Generate stopped. Need {missingText}. {next}";
        }

        private void UpdateCad2ModelTasWorkflowRail()
        {
            Cad2ModelTasWorkflowState state = EvaluateCad2ModelTasWorkflowState();
            if (Cad2ModelTasRibbonStatusText != null)
            {
                Cad2ModelTasRibbonStatusText.Text = state.NextStepText;
            }

            RefreshCad2ModelTasLayerManagerTooltip();

            ApplyCad2ModelTasWorkflowCard(
                Cad2ModelTasWorkflowSourceCard,
                Cad2ModelTasWorkflowSourceText,
                state.SourceText,
                state.IsConnected,
                state.SourceReady);
            ApplyCad2ModelTasWorkflowCard(
                Cad2ModelTasWorkflowScheduleCard,
                Cad2ModelTasWorkflowScheduleText,
                state.ScheduleText,
                state.IsConnected,
                state.ScheduleReady);
            ApplyCad2ModelTasWorkflowCard(
                Cad2ModelTasWorkflowIdentifyCard,
                Cad2ModelTasWorkflowIdentifyText,
                state.IdentifyText,
                state.IsConnected,
                state.IdentifyReady);
            ApplyCad2ModelTasWorkflowCard(
                Cad2ModelTasWorkflowGenerateCard,
                Cad2ModelTasWorkflowGenerateText,
                state.GenerateText,
                state.IsConnected,
                state.GenerateReady);
        }

        private static void ApplyCad2ModelTasWorkflowCard(Border card, TextBlock textBlock, string text, bool connected, bool ready)
        {
            if (textBlock != null)
            {
                textBlock.Text = text ?? "";
            }

            if (card == null)
            {
                return;
            }

            if (!connected)
            {
                card.ToolTip = "Waiting: " + (text ?? "");
                card.Background = new SolidColorBrush(WpfColor.FromRgb(248, 250, 252));
                card.BorderBrush = new SolidColorBrush(WpfColor.FromRgb(203, 213, 225));
                card.Opacity = 0.72;
                return;
            }

            card.ToolTip = (ready ? "Ready: " : "Waiting: ") + (text ?? "");

            if (ready)
            {
                card.Background = new SolidColorBrush(WpfColor.FromRgb(236, 253, 245));
                card.BorderBrush = new SolidColorBrush(WpfColor.FromRgb(110, 231, 183));
                card.Opacity = 1.0;
                return;
            }

            card.Background = new SolidColorBrush(WpfColor.FromRgb(255, 247, 237));
            card.BorderBrush = new SolidColorBrush(WpfColor.FromRgb(253, 186, 116));
            card.Opacity = 1.0;
        }

        private string BuildCad2ModelTasSourceCheckMessage()
        {
            Cad2ModelTasWorkflowState state = EvaluateCad2ModelTasWorkflowState();
            string options = EnsureTasIdentificationOptions().BuildWorkflowSummary();

            if (state.Missing.Count == 0)
            {
                return $"IDENTIFY / {state.Element}: Identification Check OK. {state.TasText}. {options}. {state.LayerText}{state.LabelText}.";
            }

            return $"IDENTIFY / {state.Element}: Identification Check needs {string.Join(", ", state.Missing)}. {state.NextStepText} {state.TasText}. {options}. {state.LayerText}{state.LabelText}.";
        }

        private static string GetCad2ModelTasRibbonButtonText(object sender)
        {
            if (sender is System.Windows.Controls.Button button)
            {
                string tagText = button.Tag as string;
                if (!string.IsNullOrWhiteSpace(tagText))
                {
                    return tagText;
                }

                if (button.Content is string contentText)
                {
                    return contentText;
                }
            }

            return "Tool";
        }

        private void OnCad2ModelTasAttributeGridMouseDoubleClick(object sender, MouseButtonEventArgs e)
        {
            if (!(Cad2ModelTasAttributeGrid?.SelectedItem is Cad2ModelTasAttributeRow row) || !row.IsGroup)
            {
                return;
            }

            string activeToolName = GetActiveCad2ModelToolName();
            string category = GetTasCategoryForTool(activeToolName);
            string label = GetTasElementLabelForTool(activeToolName);

            if (string.IsNullOrWhiteSpace(activeToolName) &&
                Cad2ModelTasElementList?.SelectedItem is ListBoxItem listBoxItem &&
                listBoxItem.Tag is Cad2ModelTasElementTag tag)
            {
                category = tag.Category ?? category;
                label = tag.Label ?? label;
                activeToolName = tag.ToolName ?? activeToolName;
            }

            RefreshCad2ModelTasAttributeRows(category, label, activeToolName, !string.IsNullOrWhiteSpace(activeToolName), row.GroupKey);
        }

        private void RefreshCad2ModelTasAttributeRows(
            string category,
            string label,
            string toolName,
            bool connected,
            string toggleGroupKey)
        {
            if (Cad2ModelTasAttributeGrid != null && Cad2ModelTasAttributeGrid.ItemsSource == null)
            {
                Cad2ModelTasAttributeGrid.ItemsSource = _cad2ModelTasAttributeRows;
            }

            var expandedGroups = new HashSet<string>(
                _cad2ModelTasAttributeRows
                    .Where(row => row.IsGroup && row.IsExpanded)
                    .Select(row => row.GroupKey ?? ""),
                StringComparer.OrdinalIgnoreCase);

            if (expandedGroups.Count == 0)
            {
                expandedGroups.Add("Common");
                expandedGroups.Add("IdentificationOptions");
                expandedGroups.Add("TasReference");
            }

            if (!string.IsNullOrWhiteSpace(toggleGroupKey))
            {
                if (expandedGroups.Contains(toggleGroupKey))
                {
                    expandedGroups.Remove(toggleGroupKey);
                }
                else
                {
                    expandedGroups.Add(toggleGroupKey);
                }
            }

            _cad2ModelTasAttributeEditorRefreshing = true;
            try
            {
                _cad2ModelTasAttributeRows.Clear();

                string displayLabel = BuildTasAttributeElementName(category, label, toolName);
                string displayTool = string.IsNullOrWhiteSpace(toolName) ? "Not Connected" : toolName;
                string mode = GetTasModeForTool(toolName ?? "");
                string status = connected ? "Connected" : "Prepared for next stage";
                TasReferenceSettings tas = EnsureTasReferenceSettings();
                TasIdentificationOptionsProfile identification = EnsureTasIdentificationOptions();

                AddTasAttributeGroup("Common", "Common Attribute", expandedGroups, new[]
                {
                    TasAttribute("Name", displayLabel, "Name"),
                    TasAttribute("Material", ResolveTasDefaultMaterial(toolName), "Material", GetTasMaterialOptions(), true, false),
                    TasAttribute("Section Width (mm)", ResolveTasDefaultSectionWidth(toolName), "SectionWidthMm"),
                    TasAttribute("Section Height (mm)", ResolveTasDefaultSectionHeight(toolName), "SectionHeightMm"),
                    TasAttribute("Top Elevation (m)", ResolveTasDefaultTopElevation(toolName), "TopElevation", GetTasElevationOptions(), true, false),
                    TasAttribute("Bottom Elevation (m)", ResolveTasDefaultBottomElevation(toolName), "BottomElevation", GetTasElevationOptions(), true, false),
                    TasAttribute("Concrete Grade", "C30", "ConcreteGrade", GetTasConcreteGradeOptions(), true, false),
                    TasAttribute("Formwork Type", "Common Formwork", "FormworkType", GetTasFormworkTypeOptions(), true, false),
                    TasAttribute("Entity Type", ResolveTasDefaultEntityType(toolName), "EntityType", GetTasEntityTypeOptions(), true, false),
                    TasAttribute("Category 1", ResolveTasDefaultCategory1(category, toolName), "Category1", GetTasCategory1Options(toolName), true, false),
                    TasAttribute("Category 2", ResolveTasDefaultCategory2(toolName), "Category2", GetTasCategory2Options(toolName), true, false),
                    TasAttribute("Concrete Type", "Common Concrete", "ConcreteType", GetTasConcreteTypeOptions(), true, false),
                    TasAttribute("Steel Ratio (kg/m3)", "150.000", "SteelRatioKgM3"),
                    TasAttribute("Entity Object Type", string.IsNullOrWhiteSpace(toolName) ? "" : "Normal Object", "EntityObjectType", GetTasEntityObjectTypeOptions(), true, false),
                    TasAttribute("Associated Component", "", "AssociatedComponent"),
                    TasAttribute("Associated PPVC", "", "AssociatedPpvc"),
                    TasAttribute("Associated Unit Type (...)", "", "AssociatedUnitType"),
                    TasAttribute("Revision", "", "Revision"),
                    TasAttribute("Summary Info", "", "SummaryInfo"),
                    TasAttribute("Remarks", "", "Remarks")
                }, category, displayLabel, toolName);

                AddTasAttributeGroup("Calculation", "Calculation Attribute", expandedGroups, new[]
                {
                    TasAttribute("Strutting High Top Elevation", "Default", "StruttingHighTopElevation", GetTasElevationOptions(), true, true),
                    TasAttribute("Strutting High Bottom Elevation", "Default", "StruttingHighBottomElevation", GetTasElevationOptions(), true, true),
                    TasAttribute("Strutting Height (m)", "Default", "StruttingHeightM"),
                    TasReadOnlyAttribute("Measurement Settings", "Default"),
                    TasReadOnlyAttribute("Measurement Rules", "Default"),
                    TasReadOnlyAttribute("Mode", mode),
                    TasReadOnlyAttribute("Status", status),
                    TasReadOnlyAttribute("Selected CAD Layer", GetSelectedLayerName()),
                    TasReadOnlyAttribute("Selected Label Layer", GetSelectedLabelLayerName()),
                    TasReadOnlyAttribute("Layer Advisor", BuildTasSmartLayerAdvisorText(toolName))
                }, category, displayLabel, toolName);

                AddTasAttributeGroup("IdentificationOptions", "Identification Options", expandedGroups, BuildTasIdentificationOptionAttributes(toolName, identification), category, displayLabel, toolName);

                AddTasAttributeGroup("TasReference", "TAS Reference", expandedGroups, new[]
                {
                    TasReadOnlyAttribute("TAS Status", tas.DisplayStatus),
                    TasReadOnlyAttribute("TAS Version", tas.DisplayVersion),
                    TasReadOnlyAttribute("TAS.exe", tas.TasExePath),
                    TasReadOnlyAttribute("AIConfig.ini", tas.AiConfigLoaded ? tas.AiConfigPath : "Not loaded"),
                    TasReadOnlyAttribute("CAD Filter Types", tas.CadFilterTypes),
                    TasReadOnlyAttribute("Repair Polyline", tas.RepairPolyline ? "True" : "False"),
                    TasReadOnlyAttribute("CAD Line Parallel Angle (deg)", tas.CadLineParallelAngleEpsilonDeg.ToString("0.###", CultureInfo.InvariantCulture)),
                    TasReadOnlyAttribute("CAD Line Search Distance (mm)", tas.CadLineSearchMaxDistanceMm.ToString("0.###", CultureInfo.InvariantCulture)),
                    TasReadOnlyAttribute("RDP Epsilon (mm)", tas.RdpEpsilonMm.ToString("0.###", CultureInfo.InvariantCulture)),
                    TasReadOnlyAttribute("Short Line Min Length (mm)", tas.ShortLineMinLengthMm.ToString("0.###", CultureInfo.InvariantCulture))
                }, category, displayLabel, toolName);

                AddTasAttributeGroup("Construction", "Construction Attribute", expandedGroups, new[]
                {
                    TasAttribute("Construction Phase", "", "ConstructionPhase"),
                    TasAttribute("Flow Zone", "", "FlowZone"),
                    TasAttribute("Subcontractor", "", "Subcontractor"),
                    TasAttribute("Construction Team", "", "ConstructionTeam"),
                    TasAttribute("Scheduled Start Date", "", "ScheduledStartDate"),
                    TasAttribute("Scheduled End Date", "", "ScheduledEndDate"),
                    TasAttribute("Actual Start Date", "", "ActualStartDate"),
                    TasAttribute("Actual End Date", "", "ActualEndDate"),
                    TasAttribute("Claim", "", "Claim"),
                    TasAttribute("Payment", "", "Payment")
                }, category, displayLabel, toolName);

                AddTasAttributeGroup("Display", "Display Style", expandedGroups, new[]
                {
                    TasAttribute("Fill Color", "Auto", "FillColor"),
                    TasAttribute("Opacity", "100", "Opacity")
                }, category, displayLabel, toolName);

                AddTasAttributeGroup("BimDimensions", "BIM-Dimensions", expandedGroups, new[]
                {
                    TasReadOnlyAttribute("Area", ""),
                    TasReadOnlyAttribute("BIM-Length", ""),
                    TasReadOnlyAttribute("BIM-Volume", ""),
                    TasReadOnlyAttribute("QS-Area", ""),
                    TasReadOnlyAttribute("QS-Length", ""),
                    TasReadOnlyAttribute("QS-Perimeter", ""),
                    TasReadOnlyAttribute("QS-Width", ""),
                    TasReadOnlyAttribute("b", ""),
                    TasReadOnlyAttribute("h", "")
                }, category, displayLabel, toolName);

                AddTasAttributeGroup("BimMaterial", "BIM-Entity Material/Thickness/Color", expandedGroups, new[]
                {
                    TasAttribute("Entity Color", "", "EntityColor"),
                    TasAttribute("Entity Material", "", "EntityMaterial", GetTasMaterialOptions(), true, true),
                    TasAttribute("Thickness", "", "ThicknessMm")
                }, category, displayLabel, toolName);

                AddTasAttributeGroup("BimIdentification", "BIM-Identification", expandedGroups, new[]
                {
                    TasReadOnlyAttribute("BIM-Category", category ?? ""),
                    TasReadOnlyAttribute("BIM-Name", displayLabel),
                    TasReadOnlyAttribute("Family Name", ""),
                    TasReadOnlyAttribute("GUID", ""),
                    TasReadOnlyAttribute("Type Name", displayTool)
                }, category, displayLabel, toolName);
            }
            finally
            {
                _cad2ModelTasAttributeEditorRefreshing = false;
            }

            SyncCad2ModelTasAttributeRowsToSectionSpecs();
            ApplyCad2ModelTasAttributeEditorToRequest();
        }

        private void AddTasAttributeGroup(
            string key,
            string header,
            ISet<string> expandedGroups,
            IEnumerable<Cad2ModelTasAttributeRow> children,
            string category,
            string displayLabel,
            string toolName)
        {
            bool expanded = expandedGroups.Contains(key);
            _cad2ModelTasAttributeRows.Add(new Cad2ModelTasAttributeRow
            {
                IsGroup = true,
                GroupKey = key,
                IsExpanded = expanded,
                Attribute = (expanded ? "[-] " : "[+] ") + header,
                Value = "",
                Add = false,
                IsValueEditable = false,
                IsAddEnabled = false
            });

            if (!expanded)
            {
                return;
            }

            foreach (Cad2ModelTasAttributeRow child in children)
            {
                string scopeLabel = string.IsNullOrWhiteSpace(_cad2ModelTasActiveElement)
                    ? (displayLabel ?? "")
                    : _cad2ModelTasActiveElement;
                child.GroupKey = key;
                child.Category = category ?? "";
                child.ElementLabel = displayLabel ?? "";
                child.ScopeLabel = scopeLabel;
                child.ToolName = toolName ?? "";
                child.StorageKey = BuildTasAttributeStorageKey(category, scopeLabel, toolName, key, child.Attribute);
                ApplyStoredTasAttributeValues(child);
                TrackCad2ModelTasAttributeRow(child);
                _cad2ModelTasAttributeRows.Add(child);
            }
        }

        private static Cad2ModelTasAttributeRow TasAttribute(
            string attribute,
            string value,
            string fieldKey = "",
            IEnumerable<string> options = null,
            bool editable = true,
            bool allowCustomValue = true,
            bool addEnabled = true)
        {
            var row = new Cad2ModelTasAttributeRow
            {
                IsGroup = false,
                Attribute = attribute ?? "",
                FieldKey = string.IsNullOrWhiteSpace(fieldKey) ? (attribute ?? "") : fieldKey,
                Value = value ?? "",
                Add = false,
                IsValueEditable = editable,
                IsAddEnabled = addEnabled,
                AllowCustomValue = allowCustomValue
            };

            foreach (string option in options ?? Enumerable.Empty<string>())
            {
                if (!string.IsNullOrWhiteSpace(option) &&
                    !row.ValueOptions.Any(existing => string.Equals(existing, option.Trim(), StringComparison.OrdinalIgnoreCase)))
                {
                    row.ValueOptions.Add(option.Trim());
                }
            }

            row.IsUserEdited = false;
            return row;
        }

        private static Cad2ModelTasAttributeRow TasReadOnlyAttribute(string attribute, string value)
        {
            return TasAttribute(attribute, value, "", null, false, true, false);
        }

        private static IEnumerable<Cad2ModelTasAttributeRow> BuildTasIdentificationOptionAttributes(
            string toolName,
            TasIdentificationOptionsProfile options)
        {
            if (options == null)
            {
                options = TasIdentificationOptionsProfile.CreateDefault(null);
            }

            var rows = new List<Cad2ModelTasAttributeRow>
            {
                TasReadOnlyAttribute("Workflow Summary", options.BuildWorkflowSummary())
            };

            if (string.Equals(toolName, "Column", StringComparison.OrdinalIgnoreCase))
            {
                rows.Add(TasReadOnlyAttribute("Frame Column Code", options.GetValue("CADKZCode", "KZ,C")));
                rows.Add(TasReadOnlyAttribute("Wall Column Code", options.GetValue("CADAZCode", "AZ")));
                rows.Add(TasReadOnlyAttribute("End Column Code", options.GetValue("CADDZCode", "DZ")));
                rows.Add(TasReadOnlyAttribute("Transfer Column Code", options.GetValue("CADKZZCode", "KZZ")));
                rows.Add(TasReadOnlyAttribute("Stiffener Code", options.GetValue("CADGZCode", "GZ")));
                rows.Add(TasReadOnlyAttribute("Maximum Column Sideline (mm)", options.GetValue("MaxColumnSidelineLen", "1800")));
                rows.Add(TasReadOnlyAttribute("Long Edge / Short Edge Ratio", options.GetValue("ShortToLongEdgeRatio", "4")));
                return rows;
            }

            if (string.Equals(toolName, "Wall", StringComparison.OrdinalIgnoreCase))
            {
                rows.Add(TasReadOnlyAttribute("Wall Code", options.GetValue("CADWallCode", "WS,W")));
                rows.Add(TasReadOnlyAttribute("Wall Thickness Tolerance (mm)", options.GetValue("CADWallWidthTol", "5")));
                rows.Add(TasReadOnlyAttribute("Wall End Auto Extension (mm)", options.GetValue("CADWallIntExtTol", "100")));
                rows.Add(TasReadOnlyAttribute("Maximum Opening Width (mm)", options.GetValue("MaxOpeningWidth", "500")));
                rows.Add(TasReadOnlyAttribute("Maximum Identifiable Thickness (mm)", options.GetValue("CADMaxThickness", "600")));
                return rows;
            }

            if (string.Equals(toolName, "Beam", StringComparison.OrdinalIgnoreCase))
            {
                rows.Add(TasReadOnlyAttribute("Frame Beam Code", options.GetValue("CADKLCode", "KL,B,G,CG,CB,FB,P,E,D")));
                rows.Add(TasReadOnlyAttribute("Transfer Beam Code", options.GetValue("CADKZLCode", "KZL")));
                rows.Add(TasReadOnlyAttribute("Non-frame Beam Code", options.GetValue("CADLCode", "L,J")));
                rows.Add(TasReadOnlyAttribute("Beam Size Format", options.GetValue("CADBeamSizeIdentifyMode", "Width * Height")));
                rows.Add(TasReadOnlyAttribute("Default Beam Height (mm)", options.GetValue("CADBeamDefaultHeight", "500")));
                rows.Add(TasReadOnlyAttribute("Beam End Auto Extension (mm)", options.GetValue("CADBeamSupportExtend", "200")));
                return rows;
            }

            if (string.Equals(toolName, "Slab", StringComparison.OrdinalIgnoreCase))
            {
                rows.Add(TasReadOnlyAttribute("Slab Code", options.GetValue("CADSlabCode", "S")));
                rows.Add(TasReadOnlyAttribute("Default Slab Thickness (mm)", options.GetValue("CADDefSlabThickness", "120")));
                return rows;
            }

            if (string.Equals(toolName, "Foundation", StringComparison.OrdinalIgnoreCase))
            {
                rows.Add(TasReadOnlyAttribute("Pad Foundation Height (mm)", options.GetValue("CADIsolatedFDHeight", "500")));
                rows.Add(TasReadOnlyAttribute("Pad Foundation Code", options.GetValue("CADIsolatedFDCode", "J,I,F,P")));
                rows.Add(TasReadOnlyAttribute("Pile Cap Height (mm)", options.GetValue("CADPileCapHeight", "500")));
                rows.Add(TasReadOnlyAttribute("Pile Cap Code", options.GetValue("CADPileCapCode", "CT,PC,F,P")));
                rows.Add(TasReadOnlyAttribute("Pile Depth (mm)", options.GetValue("CADPileHeight", "3000")));
                rows.Add(TasReadOnlyAttribute("Pile Code", options.GetValue("CADPileCode", "ZJ,WKZ,P")));
                return rows;
            }

            rows.Add(TasReadOnlyAttribute("Minimum Length Unit", options.GetValue("CADMinUnit", "mm")));
            rows.Add(TasReadOnlyAttribute("Line Merge Distance (mm)", options.GetValue("LineMergeSettings", "400")));
            return rows;
        }

        private string BuildTasAttributeElementName(string category, string label, string toolName)
        {
            if (string.Equals(toolName, "Column", StringComparison.OrdinalIgnoreCase))
            {
                ColumnSectionSpec spec = _columnSectionSpecs.FirstOrDefault(s => s != null && !string.IsNullOrWhiteSpace(s.Name));
                string name = string.IsNullOrWhiteSpace(spec?.Name) ? "C1" : spec.Name.Trim();
                double width = spec != null && spec.WidthMm > 0 ? spec.WidthMm : 250.0;
                double height = spec != null && spec.LengthMm > 0 ? spec.LengthMm : 450.0;
                return $"Concrete-Rectangular-Column:{name}-({FormatTasMmAsMeters(width)}X{FormatTasMmAsMeters(height)})";
            }

            if (string.Equals(toolName, "Beam", StringComparison.OrdinalIgnoreCase))
            {
                BeamSectionSpec spec = _beamSectionSpecs.FirstOrDefault(s => s != null && !string.IsNullOrWhiteSpace(s.Name));
                string name = string.IsNullOrWhiteSpace(spec?.Name) ? "B1" : spec.Name.Trim();
                double width = spec != null && spec.WidthMm > 0 ? spec.WidthMm : 250.0;
                double depth = spec != null && spec.DepthMm > 0 ? spec.DepthMm : EnsureTasIdentificationOptions().GetDouble("CADBeamDefaultHeight", 500.0);
                return $"Concrete-Rectangular-Beam:{name}-({FormatTasMmAsMeters(width)}X{FormatTasMmAsMeters(depth)})";
            }

            if (string.Equals(toolName, "Wall", StringComparison.OrdinalIgnoreCase))
            {
                WallSectionSpec spec = _wallSectionSpecs.FirstOrDefault(s => s != null && !string.IsNullOrWhiteSpace(s.Name));
                string name = string.IsNullOrWhiteSpace(spec?.Name) ? "W1" : spec.Name.Trim();
                double width = spec != null && spec.WidthMm > 0 ? spec.WidthMm : 200.0;
                return $"Concrete Wall:{name}-({FormatTasMmAsMeters(width)})";
            }

            if (string.Equals(toolName, "Slab", StringComparison.OrdinalIgnoreCase))
            {
                SlabSectionSpec spec = _slabSectionSpecs.FirstOrDefault(s => s != null && !string.IsNullOrWhiteSpace(s.Name));
                string name = string.IsNullOrWhiteSpace(spec?.Name) ? "S1" : spec.Name.Trim();
                double thickness = spec != null && spec.ThicknessMm > 0 ? spec.ThicknessMm : EnsureTasIdentificationOptions().GetDouble("CADDefSlabThickness", 120.0);
                return $"In-situ Slab:{name}-({FormatTasMmAsMeters(thickness)})";
            }

            return string.IsNullOrWhiteSpace(label)
                ? (category ?? "")
                : label;
        }

        private static string FormatTasMmAsMeters(double valueMm)
        {
            return (Math.Max(0.0, valueMm) / 1000.0).ToString("0.##", CultureInfo.InvariantCulture);
        }

        private static string ResolveTasDefaultMaterial(string toolName)
        {
            return string.IsNullOrWhiteSpace(toolName) ? "" : "In-situ Concrete";
        }

        private string ResolveTasDefaultSectionWidth(string toolName)
        {
            if (string.Equals(toolName, "Column", StringComparison.OrdinalIgnoreCase))
            {
                ColumnSectionSpec spec = _columnSectionSpecs.FirstOrDefault(s => s != null && s.WidthMm > 0);
                return FormatTasMm(spec?.WidthMm ?? 250.0);
            }

            if (string.Equals(toolName, "Wall", StringComparison.OrdinalIgnoreCase))
            {
                WallSectionSpec spec = _wallSectionSpecs.FirstOrDefault(s => s != null && s.WidthMm > 0);
                return FormatTasMm(spec?.WidthMm ?? 200.0);
            }

            if (string.Equals(toolName, "Beam", StringComparison.OrdinalIgnoreCase))
            {
                BeamSectionSpec spec = _beamSectionSpecs.FirstOrDefault(s => s != null && s.WidthMm > 0);
                return FormatTasMm(spec?.WidthMm ?? 250.0);
            }

            return "";
        }

        private string ResolveTasDefaultSectionHeight(string toolName)
        {
            if (string.Equals(toolName, "Column", StringComparison.OrdinalIgnoreCase))
            {
                ColumnSectionSpec spec = _columnSectionSpecs.FirstOrDefault(s => s != null && s.LengthMm > 0);
                return FormatTasMm(spec?.LengthMm ?? 450.0);
            }

            if (string.Equals(toolName, "Beam", StringComparison.OrdinalIgnoreCase))
            {
                BeamSectionSpec spec = _beamSectionSpecs.FirstOrDefault(s => s != null && s.DepthMm > 0);
                return FormatTasMm(spec?.DepthMm ?? EnsureTasIdentificationOptions().GetDouble("CADBeamDefaultHeight", 500.0));
            }

            if (string.Equals(toolName, "Slab", StringComparison.OrdinalIgnoreCase))
            {
                SlabSectionSpec spec = _slabSectionSpecs.FirstOrDefault(s => s != null && s.ThicknessMm > 0);
                return FormatTasMm(spec?.ThicknessMm ?? EnsureTasIdentificationOptions().GetDouble("CADDefSlabThickness", 120.0));
            }

            return "";
        }

        private static string FormatTasMm(double value)
        {
            return Math.Max(0.0, value).ToString("0.###", CultureInfo.InvariantCulture);
        }

