        private List<string> GetTasMaterialOptions()
        {
            if (_cad2ModelTasMaterialOptions != null)
            {
                return _cad2ModelTasMaterialOptions;
            }

            var options = new List<string>();
            try
            {
                string path = Path.Combine(EnsureTasReferenceSettings().BinPath ?? "", "ExportTRB", "MaterialTRBEn.xml");
                if (File.Exists(path))
                {
                    XDocument document = XDocument.Load(path);
                    foreach (XElement node in document.Descendants("MaterialNode"))
                    {
                        AddTasOption(options, (string)node.Attribute("TRBValue"));
                    }
                }
            }
            catch
            {
                options.Clear();
            }

            AddTasOption(options, "In-situ Concrete");
            AddTasOption(options, "Precast Concrete");
            AddTasOption(options, "Brick");
            AddTasOption(options, "Stone");
            AddTasOption(options, "Others");
            _cad2ModelTasMaterialOptions = options;
            return _cad2ModelTasMaterialOptions;
        }

        private List<string> GetTasElevationOptions()
        {
            if (_cad2ModelTasElevationOptions != null)
            {
                return _cad2ModelTasElevationOptions;
            }

            var options = new List<string>();
            try
            {
                string path = Path.Combine(EnsureTasReferenceSettings().BinPath ?? "", "ImportTRB", "TranslateForTRB.xml");
                if (File.Exists(path))
                {
                    XDocument document = XDocument.Load(path);
                    foreach (XElement group in document.Descendants("Group")
                        .Where(g => string.Equals((string)g.Attribute("FieldName"), "Elev", StringComparison.OrdinalIgnoreCase)))
                    {
                        foreach (XElement item in group.Elements("Item"))
                        {
                            AddTasOption(options, (string)item.Attribute("Key"));
                        }
                    }
                }
            }
            catch
            {
                options.Clear();
            }

            AddTasOption(options, "Floor_Bottom_Elevation");
            AddTasOption(options, "Floor_Top_Elevation");
            AddTasOption(options, "Bottom_Slab_Top_Elevation");
            AddTasOption(options, "Top_Slab_Top_Elevation");
            AddTasOption(options, "Top_Slab_Bottom_Elevation");
            AddTasOption(options, "Bottom_Beam_Top_Elevation");
            AddTasOption(options, "Top_Beam_Top_Elevation");
            AddTasOption(options, "Foundation_Bottom_Elevation");
            AddTasOption(options, "Foundation_Top_Elevation");
            AddTasOption(options, "Wall_Top_Elevation");
            AddTasOption(options, "Wall_Bottom_Elevation");
            AddTasOption(options, "Slab_Top_Elevation");
            _cad2ModelTasElevationOptions = options;
            return _cad2ModelTasElevationOptions;
        }

