                    SetBoreyFilterComboToAll(combo);
                }
            }
            finally
            {
                _boreyUiSyncInProgress = false;
            }

            ApplyCurrentBoreyRevitView(refreshFilterOptions: true);
            ShowStatus("BOREY: all filters reset to All.");
        }

        private static void AddBoreyFilterCombo(
            List<System.Windows.Controls.ComboBox> combos,
            System.Windows.Controls.ComboBox combo)
        {
            if (combos == null || combo == null)
            {
                return;
            }

            if (combos.Contains(combo))
            {
                return;
            }

            combos.Add(combo);
        }

        private void SetBoreyFilterComboToAll(System.Windows.Controls.ComboBox combo)
        {
            if (combo == null)
            {
                return;
            }

            List<BoreyMultiSelectFilterOption> options = GetBoreyFilterOptions(combo);
            if (options.Count > 0)
            {
                BoreyMultiSelectFilterOption allOption = options
                    .FirstOrDefault(o => string.Equals(o.Value, BoreyFilterAll, StringComparison.OrdinalIgnoreCase));

                foreach (BoreyMultiSelectFilterOption option in options)
                {
                    option.IsSelected = allOption != null && ReferenceEquals(option, allOption);
                }

                NormalizeBoreyFilterOptionsState(options);
                SaveBoreyFilterSelectedValues(combo, options);

                _boreyFilterMultiSelectUiUpdateInProgress = true;
                try
                {
                    combo.SelectedIndex = -1;
                    combo.Text = BuildBoreyFilterComboText(options);
                    combo.Items.Refresh();
                }
                finally
                {
                    _boreyFilterMultiSelectUiUpdateInProgress = false;
                }

                return;
            }

            if (combo.Items != null && combo.Items.Count > 0)
            {
                for (int i = 0; i < combo.Items.Count; i++)
                {
                    object item = combo.Items[i];
                    string text = (item as string) ?? Convert.ToString(item, CultureInfo.InvariantCulture) ?? "";
                    if (string.Equals(text.Trim(), BoreyFilterAll, StringComparison.OrdinalIgnoreCase))
                    {
                        combo.SelectedIndex = i;
                        return;
                    }
                }

                combo.SelectedIndex = 0;
                return;
            }

            combo.Text = BoreyFilterAll;
        }

        private void OnImportExcelClick(object sender, RoutedEventArgs e)
        {
            if (IsColumnTabActive())
            {
                OpenIdentifyElementScheduleWindow(true);
                return;
            }

            if (!IsBoreyTab())
            {
                ShowStatus("Import Excel is available in COLUMN and BOREY tabs.");
                return;
            }

            if (!(BoreySubTabControl?.SelectedItem is TabItem selectedTab))
            {
                ShowStatus("BOREY: select a sub-tab first.");
                return;
            }

            if (!TryGetBoreySubTabContext(
                selectedTab.Header?.ToString() ?? "",
                out string logicalTable,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out DataGrid _))
            {
                ShowStatus("BOREY: unknown sub-tab.");
                return;
            }

            var dialog = new OpenFileDialog
            {
                Title = "Import Borey Excel/CSV",
                Filter = "Excel files (*.xlsx;*.xlsm;*.xls)|*.xlsx;*.xlsm;*.xls|CSV (*.csv)|*.csv|All files (*.*)|*.*",
                Multiselect = false,
                CheckFileExists = true
            };

            bool? ok = dialog.ShowDialog(this);
            if (ok != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            try
            {
                List<BoreyGridRowPayload> rows = ReadBoreyRowsFromFile(
                    dialog.FileName,
                    out int importedSheets,
                    out int scannedRows,
                    out int skippedNoKeyRows);

                if (rows.Count == 0)
                {
                    ShowStatus("BOREY import: no valid row with key column (Id / HOUSE ID / House Code / Code / Code_Item / Mark).");
                    return;
                }

                string baseDir = Path.GetDirectoryName(System.Reflection.Assembly.GetExecutingAssembly().Location) ?? "";
                _handler.Request.BoreySharedParameterFilePath = SharedParameterPathResolver.ResolveDefaultSharedParameterPath(baseDir);
                _handler.Request.BoreySharedParameterGroupName = "CBIM-BOREY";
                _handler.Request.BoreyEnsureSharedParameters = true;
                _handler.Request.BoreyLogicalTableName = logicalTable;
                _handler.Request.BoreyRows = rows;
                _handler.Request.BoreyApplyGridChanges = true;
                _handler.Request.RequestType = CadToModelRequestType.SyncBoreyFloorData;

                _boreyInitialLoadRequested = true;
                _externalEvent.Raise();

                string fileName = Path.GetFileName(dialog.FileName);
                ShowStatus(
                    "BOREY: importing " + rows.Count.ToString(CultureInfo.InvariantCulture) +
                    " row(s) from " + fileName +
                    " (sheets: " + importedSheets.ToString(CultureInfo.InvariantCulture) +
                    ", scanned: " + scannedRows.ToString(CultureInfo.InvariantCulture) +
                    ", no-key skipped: " + skippedNoKeyRows.ToString(CultureInfo.InvariantCulture) + ").");
            }
            catch (Exception ex)
            {
                ShowStatus("BOREY import failed: " + ex.Message);
            }
        }

        private static List<BoreyGridRowPayload> ReadBoreyRowsFromFile(
            string path,
            out int importedSheets,
            out int scannedRows,
            out int skippedNoKeyRows)
        {
            importedSheets = 0;
            scannedRows = 0;
            skippedNoKeyRows = 0;
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                return new List<BoreyGridRowPayload>();
            }

            string ext = Path.GetExtension(path) ?? "";
            if (string.Equals(ext, ".csv", StringComparison.OrdinalIgnoreCase))
            {
                importedSheets = 1;
                return ReadBoreyRowsFromCsv(path, ref scannedRows, ref skippedNoKeyRows);
            }

            return ReadBoreyRowsFromExcel(path, out importedSheets, ref scannedRows, ref skippedNoKeyRows);
        }

        private static List<BoreyGridRowPayload> ReadBoreyRowsFromCsv(
            string path,
            ref int scannedRows,
            ref int skippedNoKeyRows)
        {
            var result = new List<BoreyGridRowPayload>();
            string[] lines = File.ReadAllLines(path);
            if (lines.Length == 0)
            {
                return result;
            }

            int headerLineIndex = FindBoreyHeaderLineIndex(lines);

            if (headerLineIndex < 0)
            {
                return result;
            }

            List<string> headers = ParseCsvLine(lines[headerLineIndex])
                .Select(h => NormalizeImportedHeaderCell((h ?? "").Trim()))
                .ToList();
            if (headers.Count == 0 || headers.All(string.IsNullOrWhiteSpace))
            {
                return result;
            }

            for (int i = headerLineIndex + 1; i < lines.Length; i++)
            {
                if (string.IsNullOrWhiteSpace(lines[i]))
                {
                    continue;
                }

                string[] cells = ParseCsvLine(lines[i]).ToArray();
                if (IsLikelyBoreyDescriptorRow(cells))
                {
                    skippedNoKeyRows++;
                    continue;
                }

                BoreyGridRowPayload payload = BuildBoreyPayloadFromCells(headers, cells);
                if (payload == null)
                {
                    continue;
                }

                scannedRows++;
                if (!HasBoreyPayloadMatchKey(payload.Values))
                {
                    skippedNoKeyRows++;
                    continue;
                }

                result.Add(payload);
            }

            return result;
        }

        private static int FindBoreyHeaderLineIndex(IReadOnlyList<string> lines)
        {
            if (lines == null || lines.Count == 0)
            {
                return -1;
            }

            int scanMax = Math.Min(lines.Count - 1, 80);
            int bestLine = -1;
            int bestScore = int.MinValue;

            for (int i = 0; i <= scanMax; i++)
            {
                string line = lines[i];
                if (string.IsNullOrWhiteSpace(line))
                {
                    continue;
                }

                List<string> headers = ParseCsvLine(line)
                    .Select(h => NormalizeImportedHeaderCell((h ?? "").Trim()))
                    .ToList();

                int nonEmpty = headers.Count(h => !string.IsNullOrWhiteSpace(h));
                if (nonEmpty == 0)
                {
                    continue;
                }

                int knownHeaders = headers.Count(IsKnownBoreyHeader);
                int keyHeaders = headers.Count(h => BoreyImportMatchKeyColumns.Any(k => string.Equals(k, h, StringComparison.OrdinalIgnoreCase)));
                int score = (keyHeaders * 120) + (knownHeaders * 25) + Math.Min(nonEmpty, 20);

                if (score > bestScore)
                {
                    bestScore = score;
                    bestLine = i;
                }
            }

            if (bestLine >= 0)
            {
                return bestLine;
            }

            for (int i = 0; i < lines.Count; i++)
            {
                if (!string.IsNullOrWhiteSpace(lines[i]))
                {
                    return i;
                }
            }

            return -1;
        }

        private static List<BoreyGridRowPayload> ReadBoreyRowsFromExcel(
            string path,
            out int importedSheets,
            ref int scannedRows,
            ref int skippedNoKeyRows)
        {
            importedSheets = 0;
            var result = new List<BoreyGridRowPayload>();

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Open(path, Type.Missing, true);
                dynamic workbook = workbookObj;
                object worksheetsObj = null;
                try
                {
                    worksheetsObj = workbook.Worksheets;
                    dynamic worksheets = worksheetsObj;
                    int sheetCount = Convert.ToInt32(worksheets.Count, CultureInfo.InvariantCulture);

                    for (int wsIndex = 1; wsIndex <= sheetCount; wsIndex++)
                    {
                        object worksheetObj = null;
                        object usedRangeObj = null;
                        try
                        {
                            worksheetObj = worksheets[wsIndex];
                            dynamic worksheet = worksheetObj;
                            usedRangeObj = worksheet.UsedRange;
                            dynamic usedRange = usedRangeObj;
                            object valuesObj = usedRange.Value2;
                            object[,] values = NormalizeExcelRangeToMatrix(valuesObj);
                            if (values == null)
                            {
                                continue;
                            }

                            int before = result.Count;
                            AppendBoreyRowsFromExcelMatrix(values, result, ref scannedRows, ref skippedNoKeyRows);
                            if (result.Count > before)
                            {
                                importedSheets++;
                            }
                        }
                        finally
                        {
                            SafeReleaseCom(usedRangeObj);
                            SafeReleaseCom(worksheetObj);
                        }
                    }
                }
                finally
                {
                    SafeReleaseCom(worksheetsObj);
                }

                workbook.Close(false);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }

            return result;
        }

        private static void AppendBoreyRowsFromExcelMatrix(
            object[,] values,
            IList<BoreyGridRowPayload> target,
            ref int scannedRows,
            ref int skippedNoKeyRows)
        {
            if (values == null || target == null)
            {
                return;
            }

            int rMin = values.GetLowerBound(0);
            int rMax = values.GetUpperBound(0);
            int cMin = values.GetLowerBound(1);
            int cMax = values.GetUpperBound(1);
            if (rMax < rMin || cMax < cMin)
            {
                return;
            }

            int headerRow = FindBoreyHeaderRow(values, rMin, rMax, cMin, cMax);

            if (headerRow < rMin)
            {
                return;
            }

            var headers = new List<string>();
            for (int c = cMin; c <= cMax; c++)
            {
                string normalized = NormalizeImportedHeaderCell((ToCellString(values[headerRow, c]) ?? "").Trim());
                headers.Add(normalized);
            }

            if (headers.Count == 0 || headers.All(string.IsNullOrWhiteSpace))
            {
                return;
            }

            for (int r = headerRow + 1; r <= rMax; r++)
            {
                var cells = new string[headers.Count];
                for (int c = cMin; c <= cMax; c++)
                {
                    cells[c - cMin] = ToCellString(values[r, c]);
                }

                if (IsLikelyBoreyDescriptorRow(cells))
                {
                    skippedNoKeyRows++;
                    continue;
                }

                BoreyGridRowPayload payload = BuildBoreyPayloadFromCells(headers, cells);
                if (payload == null)
                {
                    continue;
                }

                scannedRows++;
                if (!HasBoreyPayloadMatchKey(payload.Values))
                {
                    skippedNoKeyRows++;
                    continue;
                }

                target.Add(payload);
            }
        }

        private static int FindBoreyHeaderRow(object[,] values, int rMin, int rMax, int cMin, int cMax)
        {
            int scanMax = Math.Min(rMax, rMin + 80);
            int bestRow = -1;
            int bestScore = int.MinValue;

            for (int r = rMin; r <= scanMax; r++)
            {
                int nonEmpty = 0;
                int knownHeaders = 0;
                int keyHeaders = 0;

                for (int c = cMin; c <= cMax; c++)
                {
                    string header = NormalizeImportedHeaderCell((ToCellString(values[r, c]) ?? "").Trim());
                    if (string.IsNullOrWhiteSpace(header))
                    {
                        continue;
                    }

                    nonEmpty++;
                    if (IsKnownBoreyHeader(header))
                    {
                        knownHeaders++;
                    }
                    if (BoreyImportMatchKeyColumns.Any(k => string.Equals(k, header, StringComparison.OrdinalIgnoreCase)))
                    {
                        keyHeaders++;
                    }
                }

                if (nonEmpty == 0)
                {
                    continue;
                }

                int score = (keyHeaders * 120) + (knownHeaders * 25) + Math.Min(nonEmpty, 20);
                if (score > bestScore)
                {
                    bestScore = score;
                    bestRow = r;
                }
            }

            if (bestRow >= 0)
            {
                return bestRow;
            }

            for (int r = rMin; r <= scanMax; r++)
            {
                int nonEmpty = 0;
                for (int c = cMin; c <= cMax; c++)
                {
                    if (!string.IsNullOrWhiteSpace(ToCellString(values[r, c])))
                    {
                        nonEmpty++;
                    }
                }

                if (nonEmpty > 1)
                {
                    return r;
                }
            }

            return -1;
        }

        private static bool IsKnownBoreyHeader(string header)
        {
            string text = (header ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            if (BoreyFilterColumnAliases.ContainsKey(text))
            {
                return true;
            }

            foreach (string[] aliases in BoreyFilterColumnAliases.Values)
            {
                if (aliases == null)
                {
                    continue;
                }

                foreach (string alias in aliases)
                {
                    if (string.Equals(alias, text, StringComparison.OrdinalIgnoreCase))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private static bool IsLikelyBoreyDescriptorRow(IReadOnlyList<string> cells)
        {
            if (cells == null || cells.Count == 0)
            {
                return false;
            }

            int nonEmpty = 0;
            int descriptorHits = 0;
            for (int i = 0; i < cells.Count; i++)
            {
                string value = (cells[i] ?? "").Trim();
                if (string.IsNullOrWhiteSpace(value))
                {
                    continue;
                }

                nonEmpty++;
                if (IsBoreyDescriptorToken(value))
                {
                    descriptorHits++;
                }
            }

            if (nonEmpty < 3)
            {
                return false;
            }

            return descriptorHits >= Math.Max(2, nonEmpty / 2);
        }

        private static bool IsBoreyDescriptorToken(string value)
        {
            string token = (value ?? "").Trim();
            if (string.IsNullOrWhiteSpace(token))
            {
                return false;
            }

            if (token.StartsWith("{", StringComparison.Ordinal) && token.EndsWith("}", StringComparison.Ordinal))
            {
                return true;
            }

            switch (token.ToLowerInvariant())
            {
                case "string":
                case "double":
                case "integer":
                case "instance":
                case "type":
                case "read-only":
                case "readonly":
                case "custom parameter":
                case "text":
                case "data":
                case "construction":
                case "constraints":
                    return true;
                default:
                    return false;
            }
        }

        private static BoreyGridRowPayload BuildBoreyPayloadFromCells(IReadOnlyList<string> headers, IReadOnlyList<string> cells)
        {
            if (headers == null || headers.Count == 0 || cells == null || cells.Count == 0)
            {
                return null;
            }

            var payload = new BoreyGridRowPayload();
            bool hasData = false;
            int count = Math.Min(headers.Count, cells.Count);
            for (int i = 0; i < count; i++)
            {
                string header = (headers[i] ?? "").Trim();
                if (string.IsNullOrWhiteSpace(header))
                {
                    continue;
                }

                string value = (cells[i] ?? "").Trim();
                if (string.IsNullOrWhiteSpace(value))
                {
                    continue;
                }

                payload.Values[header] = value;
                hasData = true;
            }

            return hasData ? payload : null;
        }

        private static bool HasBoreyPayloadMatchKey(IDictionary<string, string> values)
        {
            if (values == null || values.Count == 0)
            {
                return false;
            }

            foreach (string key in BoreyImportMatchKeyColumns)
            {
                if (TryGetBoreyPayloadValue(values, key, out string value) && !string.IsNullOrWhiteSpace(value))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool TryGetBoreyPayloadValue(IDictionary<string, string> values, string logicalName, out string value)
        {
            value = "";
            if (values == null || string.IsNullOrWhiteSpace(logicalName))
            {
                return false;
            }

            if (values.TryGetValue(logicalName, out string direct))
            {
                value = (direct ?? "").Trim();
                return true;
            }

            if (BoreyFilterColumnAliases.TryGetValue(logicalName, out string[] aliases))
            {
                foreach (string alias in aliases)
                {
                    if (values.TryGetValue(alias, out string aliasValue))
                    {
                        value = (aliasValue ?? "").Trim();
                        return true;
                    }
                }
            }

            if (string.Equals(logicalName, "Id", StringComparison.OrdinalIgnoreCase) &&
                (values.TryGetValue("ID", out string idValue) ||
                 values.TryGetValue("Element ID", out idValue) ||
                 values.TryGetValue("__ELEMENT_ID__", out idValue)))
            {
                value = (idValue ?? "").Trim();
                return true;
            }

            return false;
        }

        private void OnExportExcelClick(object sender, RoutedEventArgs e)
        {
            if (!IsBoreyTab())
            {
                ShowStatus("Export to Excel is currently available in BOREY tab.");
                return;
            }

            if (!(BoreySubTabControl?.SelectedItem is TabItem selectedTab))
            {
                ShowStatus("BOREY: select a sub-tab first.");
                return;
            }

            if (!TryGetBoreySubTabContext(
                selectedTab.Header?.ToString() ?? "",
                out string logicalTable,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out System.Windows.Controls.ComboBox _,
                out DataGrid grid))
            {
                ShowStatus("BOREY: unknown sub-tab.");
                return;
            }

            string tabName = (selectedTab.Header?.ToString() ?? "Borey").Trim();
            bool isPlanVsActualToRemainingTab = IsBoreyPlanVsActualToRemainingSubTabHeader(tabName);

            DataView view = grid?.ItemsSource as DataView;
            if (isPlanVsActualToRemainingTab)
            {
                bool hasAnyPlanVsActualGrid =
                    (GetBoreyNamedGrid("PlanVsActualPlanDataGrid")?.ItemsSource as DataView)?.Table != null ||
                    (GetBoreyNamedGrid("PlanVsActualActualDataGrid")?.ItemsSource as DataView)?.Table != null ||
                    (GetBoreyNamedGrid("PlanVsActualRemainingDataGrid")?.ItemsSource as DataView)?.Table != null;

                if (!hasAnyPlanVsActualGrid)
                {
                    ShowStatus("BOREY: no data to export.");
                    return;
                }
            }
            else if (grid == null || view == null || view.Table == null || view.Count == 0)
            {
                ShowStatus("BOREY: no data to export.");
                return;
            }

            var dialog = new SaveFileDialog
            {
                Title = "Export Borey Excel",
                Filter = "Excel Workbook (*.xlsx)|*.xlsx",
                FileName = "CamboBIM_" + tabName.Replace(" ", "") + "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture) + ".xlsx",
                AddExtension = true,
                DefaultExt = ".xlsx",
                OverwritePrompt = true
            };

            bool? ok = dialog.ShowDialog(this);
            if (ok != true)
            {
                return;
            }

            try
            {
                if (isPlanVsActualToRemainingTab)
                {
                    ExportBoreyPlanVsActualToRemainingToExcel(dialog.FileName);
                }
                else
                {
                    ExportBoreyViewToExcel(grid, view, logicalTable, dialog.FileName);
                }
                ShowStatus("BOREY: exported to Excel: " + dialog.FileName);
            }
            catch (Exception ex)
            {
                ShowStatus("BOREY export failed: " + ex.Message);
            }
        }

        private void ExportBoreyViewToExcel(DataGrid grid, DataView view, string logicalTable, string filePath)
        {
            if (view == null || view.Table == null)
            {
                throw new InvalidOperationException("No Borey table data to export.");
            }

            DataTable table = view.Table;
            List<(string ColumnName, string Header)> columns = GetBoreyExportColumns(grid, table);
            if (columns.Count == 0)
            {
                throw new InvalidOperationException("No exportable columns in Borey grid.");
            }

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;
            object worksheetObj = null;
            object rangeObj = null;
            object topLeftObj = null;
            object bottomRightObj = null;
            object headerRangeObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Add();
                dynamic workbook = workbookObj;

                worksheetObj = workbook.Worksheets[1];
                dynamic worksheet = worksheetObj;
                worksheet.Name = ToExcelSheetName(string.IsNullOrWhiteSpace(logicalTable) ? "Borey" : logicalTable);

                int dataCount = view.Count;
                int rowCount = Math.Max(1, dataCount) + 1;
                int colCount = columns.Count;
                var matrix = new object[rowCount, colCount];

                for (int c = 0; c < columns.Count; c++)
                {
                    matrix[0, c] = columns[c].Header;
                }

                for (int r = 0; r < dataCount; r++)
                {
                    DataRow row = view[r].Row;
                    for (int c = 0; c < columns.Count; c++)
                    {
                        string columnName = columns[c].ColumnName;
                        matrix[r + 1, c] = Convert.ToString(row[columnName], CultureInfo.InvariantCulture) ?? "";
                    }
                }

                topLeftObj = worksheet.Cells[1, 1];
                bottomRightObj = worksheet.Cells[rowCount, colCount];
                rangeObj = worksheet.Range[topLeftObj, bottomRightObj];
                dynamic range = rangeObj;
                range.Value2 = matrix;

                headerRangeObj = worksheet.Range[worksheet.Cells[1, 1], worksheet.Cells[1, colCount]];
                dynamic headerRange = headerRangeObj;
                headerRange.Font.Bold = true;

                try
                {
                    worksheet.Columns.AutoFit();
                }
                catch
                {
                    // ignore formatting issues
                }

                workbook.SaveAs(filePath, 51);
                workbook.Close(true);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(headerRangeObj);
                SafeReleaseCom(bottomRightObj);
                SafeReleaseCom(topLeftObj);
                SafeReleaseCom(rangeObj);
                SafeReleaseCom(worksheetObj);
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }
        }

        private static bool IsBoreyPlanVsActualToRemainingSubTabHeader(string header)
        {
            string value = (header ?? "").Trim();
            return string.Equals(value, "PLAN VS ACTUAL TO REMAINING", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(value, "PLAN VS ACTUAL TO REMAINNING", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(value, "Plan Vs Actual To Remainning", StringComparison.OrdinalIgnoreCase);
        }

        private void ExportBoreyPlanVsActualToRemainingToExcel(string filePath)
        {
            var sections = new List<(string Title, DataGrid Grid)>
            {
                ("MONTHLY PLAN TO COMPLETE", GetBoreyNamedGrid("PlanVsActualPlanDataGrid")),
                ("ACTUAL COMPLETED", GetBoreyNamedGrid("PlanVsActualActualDataGrid")),
                ("REMAINING TO COMPLETE", GetBoreyNamedGrid("PlanVsActualRemainingDataGrid"))
            };

            bool hasAnyTableData = sections.Any(s => (s.Grid?.ItemsSource as DataView)?.Table != null);
            if (!hasAnyTableData)
            {
                throw new InvalidOperationException("No PLAN VS ACTUAL TO REMAINING tables to export.");
            }

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;
            object worksheetObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Add();
                dynamic workbook = workbookObj;

                worksheetObj = workbook.Worksheets[1];
                dynamic worksheet = worksheetObj;
                worksheet.Name = ToExcelSheetName("PlanVsActualRemain");

                DataTable planChartTable = (sections[0].Grid?.ItemsSource as DataView)?.Table;
                DataTable actualChartTable = (sections[1].Grid?.ItemsSource as DataView)?.Table;
                DataTable remainingChartTable = (sections[2].Grid?.ItemsSource as DataView)?.Table;

                int blueHeaderColor = ToExcelOleColor(156, 194, 229);
                int blueHeaderDarkTextColor = ToExcelOleColor(0, 0, 0);
                int bodyFillColor = ToExcelOleColor(234, 241, 250);
                int totalFillColor = ToExcelOleColor(223, 234, 247);
                int panelBorderColor = ToExcelOleColor(209, 218, 230);
                int whiteColor = ToExcelOleColor(255, 255, 255);

                int currentRow = 1;
                int maxExportColCount = 1;

                foreach (var section in sections)
                {
                    DataView sectionView = section.Grid?.ItemsSource as DataView;
                    DataTable table = sectionView?.Table;

                    if (table == null)
                    {
                        continue;
                    }

                    List<(string ColumnName, string Header)> columns = GetBoreyExportColumns(section.Grid, table);
                    if (columns.Count == 0)
                    {
                        continue;
                    }

                    maxExportColCount = Math.Max(maxExportColCount, columns.Count);

                    for (int c = 0; c < columns.Count; c++)
                    {
                        try
                        {
                            worksheet.Columns[c + 1].ColumnWidth = GetBoreyPlanVsActualExportColumnWidth(columns[c].Header);
                        }
                        catch
                        {
                            // ignore Excel column width issues
                        }
                    }

                    int dataCount = sectionView?.Count ?? 0;
                    int tableRowCount = Math.Max(1, dataCount) + 1; // header + data (or header only)
                    int colCount = columns.Count;
                    var matrix = new object[tableRowCount, colCount];

                    for (int c = 0; c < columns.Count; c++)
                    {
                        matrix[0, c] = columns[c].Header;
                    }

                    for (int r = 0; r < dataCount; r++)
                    {
                        DataRow row = sectionView[r].Row;
                        for (int c = 0; c < columns.Count; c++)
                        {
                            string columnName = columns[c].ColumnName;
                            matrix[r + 1, c] = Convert.ToString(row[columnName], CultureInfo.InvariantCulture) ?? "";
                        }
                    }

                    int titleRow = currentRow;
                    int headerRow = currentRow + 1;
                    int firstDataRow = currentRow + 2;
                    int lastTableRow = currentRow + tableRowCount;

                    object titleRangeObj = null;
                    object topLeftObj = null;
                    object bottomRightObj = null;
                    object bodyRangeObj = null;
                    object headerRangeObj = null;
                    object fullTableRangeObj = null;
                    object firstColumnRangeObj = null;
                    object totalRowRangeObj = null;

                    try
                    {
                        worksheet.Cells[titleRow, 1] = section.Title;
                        titleRangeObj = worksheet.Range[worksheet.Cells[titleRow, 1], worksheet.Cells[titleRow, colCount]];
                        dynamic titleRange = titleRangeObj;
                        titleRange.Merge();
                        titleRange.Font.Bold = true;
                        titleRange.Font.Name = "Calibri";
                        titleRange.Font.Size = 10;
                        titleRange.Font.Color = blueHeaderDarkTextColor;
                        titleRange.HorizontalAlignment = -4108; // xlCenter
                        titleRange.VerticalAlignment = -4108;
                        titleRange.Interior.Color = blueHeaderColor;
                        titleRange.Borders.LineStyle = 1;
                        titleRange.Borders.Color = panelBorderColor;

                        try { worksheet.Rows[titleRow].RowHeight = 20; } catch { }

                        topLeftObj = worksheet.Cells[headerRow, 1];
                        bottomRightObj = worksheet.Cells[lastTableRow, colCount];
                        bodyRangeObj = worksheet.Range[topLeftObj, bottomRightObj];
                        dynamic bodyRange = bodyRangeObj;
                        bodyRange.Value2 = matrix;
                        bodyRange.Font.Name = "Calibri";
                        bodyRange.Font.Size = 9;
                        bodyRange.HorizontalAlignment = -4108; // center
                        bodyRange.VerticalAlignment = -4108;
                        bodyRange.Interior.Color = bodyFillColor;

                        headerRangeObj = worksheet.Range[worksheet.Cells[headerRow, 1], worksheet.Cells[headerRow, colCount]];
                        dynamic headerRange = headerRangeObj;
                        headerRange.Font.Bold = true;
                        headerRange.Font.Name = "Calibri";
                        headerRange.Font.Size = 9;
                        headerRange.Font.Color = blueHeaderDarkTextColor;
                        headerRange.Interior.Color = blueHeaderColor;
                        headerRange.HorizontalAlignment = -4108;
                        headerRange.VerticalAlignment = -4108;

                        try { worksheet.Rows[headerRow].RowHeight = 18; } catch { }

                        fullTableRangeObj = worksheet.Range[worksheet.Cells[titleRow, 1], worksheet.Cells[lastTableRow, colCount]];
                        dynamic fullTableRange = fullTableRangeObj;
                        fullTableRange.Borders.LineStyle = 1;
                        fullTableRange.Borders.Color = 0; // black grid

                        if (lastTableRow >= firstDataRow)
                        {
                            firstColumnRangeObj = worksheet.Range[worksheet.Cells[headerRow, 1], worksheet.Cells[lastTableRow, 1]];
                            dynamic firstColumnRange = firstColumnRangeObj;
                            firstColumnRange.HorizontalAlignment = -4131; // xlLeft
                            firstColumnRange.VerticalAlignment = -4108;

                            totalRowRangeObj = worksheet.Range[worksheet.Cells[lastTableRow, 1], worksheet.Cells[lastTableRow, colCount]];
                            dynamic totalRowRange = totalRowRangeObj;
                            totalRowRange.Font.Bold = true;
                            totalRowRange.Interior.Color = totalFillColor;
                        }

                        for (int rowIndex = firstDataRow; rowIndex <= lastTableRow; rowIndex++)
                        {
                            try
                            {
                                worksheet.Rows[rowIndex].RowHeight = 16;
                            }
                            catch
                            {
                            }
                        }
                    }
                    finally
                    {
                        SafeReleaseCom(totalRowRangeObj);
                        SafeReleaseCom(firstColumnRangeObj);
                        SafeReleaseCom(fullTableRangeObj);
                        SafeReleaseCom(headerRangeObj);
                        SafeReleaseCom(bodyRangeObj);
                        SafeReleaseCom(bottomRightObj);
                        SafeReleaseCom(topLeftObj);
                        SafeReleaseCom(titleRangeObj);
                    }

                    currentRow = lastTableRow + 2;
                }

                List<string> monthColumns = GetPlanVsActualMonthColumns(planChartTable ?? actualChartTable ?? remainingChartTable).ToList();
                DataRow planTotalRow = GetPlanVsActualTotalRow(planChartTable);
                DataRow actualTotalRow = GetPlanVsActualTotalRow(actualChartTable);
                DataRow remainingTotalRow = GetPlanVsActualTotalRow(remainingChartTable);

                var chartPoints = new List<(string Label, double Plan, double Actual, double Remaining)>();
                foreach (string monthColumn in monthColumns)
                {
                    chartPoints.Add((
                        monthColumn,
                        GetPlanVsActualTableValue(planChartTable, planTotalRow, monthColumn),
                        GetPlanVsActualTableValue(actualChartTable, actualTotalRow, monthColumn),
                        GetPlanVsActualTableValue(remainingChartTable, remainingTotalRow, monthColumn)));
                }

                if (chartPoints.Count == 0)
                {
                    double planTotal = GetPlanVsActualTableValue(planChartTable, planTotalRow, "Total");
                    double actualTotal = GetPlanVsActualTableValue(actualChartTable, actualTotalRow, "Total");
                    double remainingTotal = GetPlanVsActualTableValue(remainingChartTable, remainingTotalRow, "Total");
                    if (planTotal > 0.0 || actualTotal > 0.0 || remainingTotal > 0.0)
                    {
                        chartPoints.Add(("Total", planTotal, actualTotal, remainingTotal));
                    }
                }

                if (chartPoints.Count > 0)
                {
                    const int xlColumnClustered = 51;
                    const int xlColumns = 2;
                    const int xlCategory = 1;
                    const int xlValue = 2;
                    const int xlLeft = -4131;
                    const int xlCenter = -4108;

                    int chartPanelStartCol = Math.Max(8, maxExportColCount + 3);
                    int chartPanelWidthCols = 13;
                    int chartPanelEndCol = chartPanelStartCol + chartPanelWidthCols - 1;
                    int chartTitleRow = 1;
                    int chartScopeRow = 2;
                    int chartBodyTopRow = 3;
                    int chartBodyBottomRow = 24;

                    int chartDataStartCol = chartPanelEndCol + 4;
                    int chartDataStartRow = 2;

                    double planGrandTotal = chartPoints.Sum(p => p.Plan);
                    double actualGrandTotal = chartPoints.Sum(p => p.Actual);
                    double remainingGrandTotal = chartPoints.Sum(p => p.Remaining);

                    object chartDataTopLeftObj = null;
                    object chartDataBottomRightObj = null;
                    object chartDataRangeObj = null;
                    object chartHiddenRangeObj = null;
                    object chartPanelTitleRangeObj = null;
                    object chartPanelScopeRangeObj = null;
                    object chartPanelBorderRangeObj = null;
                    object chartObjectsObj = null;
                    object chartObjectObj = null;
                    object chartObj = null;
                    object seriesCollectionObj = null;
                    object series1Obj = null;
                    object series2Obj = null;
                    object series3Obj = null;
                    object axisXObj = null;
                    object axisYObj = null;
                    object chartPanelTopLeftCellObj = null;
                    object chartPanelBottomRightCellObj = null;
                    object chartPlotTopLeftCellObj = null;

                    try
                    {
                        try
                        {
                            worksheet.Columns[maxExportColCount + 1].ColumnWidth = 1.6;
                            worksheet.Columns[maxExportColCount + 2].ColumnWidth = 1.6;
                            for (int c = chartPanelStartCol; c <= chartPanelEndCol; c++)
