                        chartPanelTitleRange.Font.Bold = true;
                        chartPanelTitleRange.Font.Name = "Calibri";
                        chartPanelTitleRange.Font.Size = 10;
                        chartPanelTitleRange.HorizontalAlignment = xlLeft;
                        chartPanelTitleRange.VerticalAlignment = xlCenter;
                        chartPanelTitleRange.Interior.Color = whiteColor;

                        chartPanelScopeRangeObj = worksheet.Range[worksheet.Cells[chartScopeRow, chartPanelStartCol], worksheet.Cells[chartScopeRow, chartPanelEndCol]];
                        dynamic chartPanelScopeRange = chartPanelScopeRangeObj;
                        chartPanelScopeRange.Merge();
                        chartPanelScopeRange.Value2 =
                            "Months: " + monthColumns.Count.ToString(CultureInfo.InvariantCulture) +
                            " | Plan: " + planGrandTotal.ToString("0.###", CultureInfo.InvariantCulture) +
                            " | Actual: " + actualGrandTotal.ToString("0.###", CultureInfo.InvariantCulture) +
                            " | Remaining: " + remainingGrandTotal.ToString("0.###", CultureInfo.InvariantCulture);
                        chartPanelScopeRange.Font.Name = "Calibri";
                        chartPanelScopeRange.Font.Size = 9;
                        chartPanelScopeRange.Font.Color = ToExcelOleColor(75, 90, 115);
                        chartPanelScopeRange.HorizontalAlignment = xlLeft;
                        chartPanelScopeRange.VerticalAlignment = xlCenter;
                        chartPanelScopeRange.Interior.Color = whiteColor;

                        try
                        {
