                        chartPanelBorderRangeObj = worksheet.Range[worksheet.Cells[chartTitleRow, chartPanelStartCol], worksheet.Cells[chartBodyBottomRow, chartPanelEndCol]];
                        dynamic chartPanelBorderRange = chartPanelBorderRangeObj;
                        chartPanelBorderRange.Borders.LineStyle = 1;
                        chartPanelBorderRange.Borders.Color = panelBorderColor;
                        chartPanelBorderRange.Interior.Color = whiteColor;

                        worksheet.Cells[chartDataStartRow, chartDataStartCol] = "Month";
                        worksheet.Cells[chartDataStartRow, chartDataStartCol + 1] = "Plan";
                        worksheet.Cells[chartDataStartRow, chartDataStartCol + 2] = "Actual";
                        worksheet.Cells[chartDataStartRow, chartDataStartCol + 3] = "Remaining";

                        for (int i = 0; i < chartPoints.Count; i++)
                        {
                            int row = chartDataStartRow + 1 + i;
                            worksheet.Cells[row, chartDataStartCol] = chartPoints[i].Label;
                            worksheet.Cells[row, chartDataStartCol + 1] = chartPoints[i].Plan;
                            worksheet.Cells[row, chartDataStartCol + 2] = chartPoints[i].Actual;
                            worksheet.Cells[row, chartDataStartCol + 3] = chartPoints[i].Remaining;
                        }

                        chartDataTopLeftObj = worksheet.Cells[chartDataStartRow, chartDataStartCol];
                        chartDataBottomRightObj = worksheet.Cells[chartDataStartRow + chartPoints.Count, chartDataStartCol + 3];
                        chartDataRangeObj = worksheet.Range[chartDataTopLeftObj, chartDataBottomRightObj];

                        chartPlotTopLeftCellObj = worksheet.Cells[chartBodyTopRow, chartPanelStartCol];
                        chartPanelTopLeftCellObj = worksheet.Cells[chartBodyTopRow, chartPanelStartCol];
                        chartPanelBottomRightCellObj = worksheet.Cells[chartBodyBottomRow, chartPanelEndCol];
                        dynamic chartPlotTopLeftCell = chartPlotTopLeftCellObj;
                        dynamic chartPanelTopLeftCell = chartPanelTopLeftCellObj;
                        dynamic chartPanelBottomRightCell = chartPanelBottomRightCellObj;
                        double chartLeft = Convert.ToDouble(chartPlotTopLeftCell.Left, CultureInfo.InvariantCulture) + 6.0;
                        double chartTop = Convert.ToDouble(chartPlotTopLeftCell.Top, CultureInfo.InvariantCulture) + 6.0;
                        double chartRight = Convert.ToDouble(chartPanelBottomRightCell.Left, CultureInfo.InvariantCulture) +
                                            Convert.ToDouble(chartPanelBottomRightCell.Width, CultureInfo.InvariantCulture) - 6.0;
                        double chartBottom = Convert.ToDouble(chartPanelBottomRightCell.Top, CultureInfo.InvariantCulture) +
                                             Convert.ToDouble(chartPanelBottomRightCell.Height, CultureInfo.InvariantCulture) - 6.0;
                        double chartWidth = Math.Max(220.0, chartRight - chartLeft);
                        double chartHeight = Math.Max(180.0, chartBottom - chartTop);

                        chartObjectsObj = worksheet.ChartObjects();
                        dynamic chartObjects = chartObjectsObj;
                        chartObjectObj = chartObjects.Add(chartLeft, chartTop, chartWidth, chartHeight);
                        dynamic chartObject = chartObjectObj;
                        chartObj = chartObject.Chart;
                        dynamic chart = chartObj;

                        chart.ChartType = xlColumnClustered;
                        chart.SetSourceData(chartDataRangeObj);
                        chart.PlotBy = xlColumns;
                        chart.HasTitle = false;
                        chart.HasLegend = false;

                        try
                        {
                            axisXObj = chart.Axes(xlCategory);
                            dynamic axisX = axisXObj;
                            axisX.TickLabelSpacing = 1;
                            axisX.TickLabels.Orientation = 45;
                            axisX.HasTitle = false;
                        }
                        catch
                        {
                        }

                        try
                        {
                            axisYObj = chart.Axes(xlValue);
                            dynamic axisY = axisYObj;
                            axisY.HasTitle = true;
                            axisY.AxisTitle.Text = "Units";
                            axisY.MinimumScale = 0;
                            try { axisY.TickLabels.Font.Size = 8; } catch { }
                        }
                        catch
                        {
                        }

                        try
                        {
                            chart.ChartArea.Format.Fill.ForeColor.RGB = whiteColor;
                            chart.ChartArea.Format.Line.ForeColor.RGB = panelBorderColor;
                            chart.PlotArea.Format.Fill.ForeColor.RGB = whiteColor;
                            chart.PlotArea.Format.Line.ForeColor.RGB = panelBorderColor;
                        }
                        catch
                        {
                        }

                        try
                        {
                            seriesCollectionObj = chart.SeriesCollection();
                            dynamic seriesCollection = seriesCollectionObj;
                            series1Obj = seriesCollection.Item(1);
                            series2Obj = seriesCollection.Item(2);
                            series3Obj = seriesCollection.Item(3);

                            dynamic series1 = series1Obj;
                            dynamic series2 = series2Obj;
                            dynamic series3 = series3Obj;

                            series1.Name = "Plan";
                            series2.Name = "Actual";
                            series3.Name = "Remaining";

                            try { series1.Format.Fill.ForeColor.RGB = ToExcelOleColor(78, 121, 167); } catch { }
                            try { series1.Format.Line.ForeColor.RGB = ToExcelOleColor(58, 94, 136); } catch { }
                            try { series2.Format.Fill.ForeColor.RGB = ToExcelOleColor(89, 161, 79); } catch { }
                            try { series2.Format.Line.ForeColor.RGB = ToExcelOleColor(75, 138, 66); } catch { }
                            try { series3.Format.Fill.ForeColor.RGB = ToExcelOleColor(242, 142, 43); } catch { }
                            try { series3.Format.Line.ForeColor.RGB = ToExcelOleColor(204, 116, 31); } catch { }

                            try { series1.ApplyDataLabels(); } catch { }
                            try { series2.ApplyDataLabels(); } catch { }
                            try { series3.ApplyDataLabels(); } catch { }
                            try { series1.DataLabels.Font.Size = 8; } catch { }
                            try { series2.DataLabels.Font.Size = 8; } catch { }
                            try { series3.DataLabels.Font.Size = 8; } catch { }
                        }
                        catch
                        {
                        }

                        try
                        {
                            chartHiddenRangeObj = worksheet.Range[worksheet.Cells[chartDataStartRow, chartDataStartCol], worksheet.Cells[chartDataStartRow + chartPoints.Count, chartDataStartCol + 3]];
                            dynamic hiddenRange = chartHiddenRangeObj;
                            hiddenRange.EntireColumn.Hidden = true;
                        }
                        catch
                        {
                        }
                    }
                    finally
                    {
                        SafeReleaseCom(chartPlotTopLeftCellObj);
                        SafeReleaseCom(chartPanelBottomRightCellObj);
                        SafeReleaseCom(chartPanelTopLeftCellObj);
                        SafeReleaseCom(axisYObj);
                        SafeReleaseCom(axisXObj);
                        SafeReleaseCom(series3Obj);
                        SafeReleaseCom(series2Obj);
                        SafeReleaseCom(series1Obj);
                        SafeReleaseCom(seriesCollectionObj);
                        SafeReleaseCom(chartObj);
                        SafeReleaseCom(chartObjectObj);
                        SafeReleaseCom(chartObjectsObj);
                        SafeReleaseCom(chartPanelBorderRangeObj);
                        SafeReleaseCom(chartPanelScopeRangeObj);
                        SafeReleaseCom(chartPanelTitleRangeObj);
                        SafeReleaseCom(chartHiddenRangeObj);
                        SafeReleaseCom(chartDataRangeObj);
                        SafeReleaseCom(chartDataBottomRightObj);
                        SafeReleaseCom(chartDataTopLeftObj);
                    }
                }

                workbook.SaveAs(filePath, 51);
                workbook.Close(true);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(worksheetObj);
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }
        }

        private static List<(string ColumnName, string Header)> GetBoreyExportColumns(DataGrid grid, DataTable table)
        {
            var result = new List<(string ColumnName, string Header)>();
            if (table == null)
            {
                return result;
            }

            if (grid?.Columns != null && grid.Columns.Count > 0)
            {
                foreach (DataGridColumn gridColumn in grid.Columns
                             .Where(c => c != null && c.Visibility == System.Windows.Visibility.Visible)
                             .OrderBy(c => c.DisplayIndex))
                {
                    string columnName = ResolveBoreyGridColumnName(table, gridColumn);
                    if (string.IsNullOrWhiteSpace(columnName) ||
                        result.Any(x => string.Equals(x.ColumnName, columnName, StringComparison.OrdinalIgnoreCase)))
                    {
                        continue;
                    }

                    string header = Convert.ToString(gridColumn.Header, CultureInfo.InvariantCulture)?.Trim() ?? columnName;
                    result.Add((columnName, header));
                }
            }

            if (result.Count > 0)
            {
                return result;
            }

            foreach (DataColumn col in table.Columns)
            {
                if (col == null)
                {
                    continue;
                }

                result.Add((col.ColumnName, col.ColumnName));
            }

            return result;
        }

        private static string ToExcelSheetName(string value)
        {
            string name = (value ?? "Sheet1").Trim();
            if (string.IsNullOrWhiteSpace(name))
            {
                name = "Sheet1";
            }

            char[] invalid = { ':', '\\', '/', '?', '*', '[', ']' };
            foreach (char c in invalid)
            {
                name = name.Replace(c, '_');
            }

            if (name.Length > 31)
            {
                name = name.Substring(0, 31);
            }

            return string.IsNullOrWhiteSpace(name) ? "Sheet1" : name;
        }

        private static int ToExcelOleColor(int r, int g, int b)
        {
            int rr = Math.Max(0, Math.Min(255, r));
            int gg = Math.Max(0, Math.Min(255, g));
            int bb = Math.Max(0, Math.Min(255, b));
            return (bb << 16) | (gg << 8) | rr;
        }

        private static double GetBoreyPlanVsActualExportColumnWidth(string header)
        {
            string h = (header ?? "").Trim();
            if (string.Equals(h, "HOUSE-TYPE", StringComparison.OrdinalIgnoreCase))
            {
                return 12.0;
            }

            if (string.Equals(h, "Total", StringComparison.OrdinalIgnoreCase))
            {
                return 6.5;
            }

            return 6.0;
        }

        private void OnGenerateClick(object sender, RoutedEventArgs e)
        {
            if (IsQsTab())
            {
                OnQsCalculateClick(sender, e);
                return;
            }

            if (IsSiteProgressTab())
            {
                OnSiteProgressApplyClick(sender, e);
                return;
            }

            if (IsLinksheetTab())
            {
                OnLinksheetOpenPreviewClick(sender, e);
                return;
            }

            if (IsBoreyTab())
            {
                GenerateBoreyData();
                return;
            }

            if (!IsCad2ModelTab() && !IsDrawingTab())
            {
                ShowStatus("Switch to IDENTIFY, QS TOOLS, LINKSHEET, REINFORCEMENT, SITE PROGRESS, or BOREY tab.");
                return;
            }

            if (IsDrawingTab() && IsDrawingColumnRebarSubTab())
            {
                TryRaiseColumnRebarGenerateRequest();
                return;
            }

            if (IsDrawingTab() && IsDrawingShopDrawingSubTab())
            {
                TryRaiseShopDrawingRequest(CadToModelRequestType.GenerateConstructionShopSheets, null, null, null);
                return;
            }

            if (!TryUpdateRequestFromUi())
            {
                return;
            }

            if (IsDrawingTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateDetailLines;
            }
            else if (IsGridlineTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateGridlines;
            }
            else if (IsBoredPileTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GeneratePiles;
            }
            else if (IsFoundationTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateFoundations;
            }
            else if (IsLeanConcreteTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateLeanConcrete;
            }
            else if (IsSoilExcavationTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateSoilExcavation;
            }
            else if (IsSlabTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateSlabs;
            }
            else if (IsWallTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateWalls;
            }
            else if (IsBeamTab())
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateBeams;
            }
            else
            {
                _handler.Request.RequestType = CadToModelRequestType.GenerateColumns;
            }
            _externalEvent.Raise();
        }

