        private bool TryUpdateShopDrawingRequestFromUi(
            bool? includeFormworkOverride,
            bool? includeRebarOverride,
            bool? createSheetsOverride)
        {
            bool includeFormwork = includeFormworkOverride ?? (ShopDrawingFormworkCheck?.IsChecked == true);
            bool includeRebar = includeRebarOverride ?? (ShopDrawingRebarCheck?.IsChecked == true);
            bool createSheets = createSheetsOverride ?? (ShopDrawingSheetsCheck?.IsChecked == true);
            bool replaceExisting = ShopDrawingReplaceExistingCheck?.IsChecked == true;

            if (!includeFormwork && !includeRebar)
            {
                ShowStatus("Shop Drawing: enable Formwork Layout or Rebar Drawing.");
                if (ShopDrawingStatusText != null)
                {
                    ShopDrawingStatusText.Text = "Select at least one output.";
                }
                return false;
            }

            int scale = 50;
            string scaleText = ShopDrawingScaleTextBox?.Text ?? "50";
            if (!int.TryParse(scaleText, NumberStyles.Integer, CultureInfo.InvariantCulture, out scale) ||
                scale < 1 ||
                scale > 5000)
            {
                ShowStatus("Shop Drawing: scale must be a whole number from 1 to 5000.");
                if (ShopDrawingStatusText != null)
                {
                    ShopDrawingStatusText.Text = "Scale must be between 1 and 5000.";
                }
                return false;
            }

            int maxMarks = 32;
            string maxMarksText = ShopDrawingMaxMarksTextBox?.Text ?? "32";
            if (!int.TryParse(maxMarksText, NumberStyles.Integer, CultureInfo.InvariantCulture, out maxMarks) ||
                maxMarks < 1 ||
                maxMarks > 200)
            {
                ShowStatus("Shop Drawing: rows must be a whole number from 1 to 200.");
                if (ShopDrawingStatusText != null)
                {
                    ShopDrawingStatusText.Text = "Schedule rows must be between 1 and 200.";
                }
                return false;
            }

            string issueText = NormalizeShopDrawingUiText(
                GetShopDrawingComboText(ShopDrawingIssueCombo, "FOR CONSTRUCTION REVIEW"),
                "FOR CONSTRUCTION REVIEW",
                64);
            string formworkPrefix = NormalizeShopDrawingUiPrefix(ShopDrawingFormworkPrefixTextBox?.Text, "MHNK-FWK");
            string rebarPrefix = NormalizeShopDrawingUiPrefix(ShopDrawingRebarPrefixTextBox?.Text, "MHNK-RBR");
            string indexPrefix = NormalizeShopDrawingUiPrefix(ShopDrawingIndexPrefixTextBox?.Text, "MHNK-SD-INDEX");
            string detailPrefix = NormalizeShopDrawingUiPrefix(ShopDrawingDetailPrefixTextBox?.Text, "MHNK-DET");
            ShopDrawingGroupMode groupMode = GetShopDrawingGroupMode();
            string packageName = NormalizeShopDrawingUiText(ShopDrawingPackageTextBox?.Text, "SHOP DRAWING PACKAGE", 80);
            string discipline = NormalizeShopDrawingUiText(ShopDrawingDisciplineTextBox?.Text, "STRUCTURAL", 40);
            string revision = NormalizeShopDrawingUiText(ShopDrawingRevisionTextBox?.Text, "R0", 16);
            string preparedBy = NormalizeShopDrawingUiText(ShopDrawingPreparedByTextBox?.Text, "", 40);
            string checkedBy = NormalizeShopDrawingUiText(ShopDrawingCheckedByTextBox?.Text, "", 40);
            string approvedBy = NormalizeShopDrawingUiText(ShopDrawingApprovedByTextBox?.Text, "", 40);

            _handler.Request.ShopDrawingsScope = GetShopDrawingScope();
            _handler.Request.ShopDrawingsIncludeFormwork = includeFormwork;
            _handler.Request.ShopDrawingsIncludeRebar = includeRebar;
            _handler.Request.ShopDrawingsCreateSheets = createSheets;
            _handler.Request.ShopDrawingsReplaceExisting = replaceExisting;
            _handler.Request.ShopDrawingsViewScale = scale;
            _handler.Request.ShopDrawingsTitleBlockTypeId =
                GetShopDrawingTitleBlockCombo()?.SelectedItem is ComboItem titleBlock
                    ? titleBlock.Id
                    : ElementId.InvalidElementId;
            _handler.Request.ShopDrawingsIssueText = issueText;
            _handler.Request.ShopDrawingsFormworkSheetPrefix = formworkPrefix;
            _handler.Request.ShopDrawingsRebarSheetPrefix = rebarPrefix;
            _handler.Request.ShopDrawingsIndexSheetPrefix = indexPrefix;
            _handler.Request.ShopDrawingsDetailSheetPrefix = detailPrefix;
            _handler.Request.ShopDrawingsMaxMarksPerSheet = maxMarks;
            _handler.Request.ShopDrawingsGroupMode = groupMode;
            _handler.Request.ShopDrawingsPackageName = packageName;
            _handler.Request.ShopDrawingsDiscipline = discipline;
            _handler.Request.ShopDrawingsRevision = revision;
            _handler.Request.ShopDrawingsPreparedBy = preparedBy;
            _handler.Request.ShopDrawingsCheckedBy = checkedBy;
            _handler.Request.ShopDrawingsApprovedBy = approvedBy;

            string scopeText = _handler.Request.ShopDrawingsScope == QsScope.CurrentSelection
                ? "selection"
                : _handler.Request.ShopDrawingsScope == QsScope.CurrentView
                    ? "current view"
                    : "entire model";
            string outputText = includeFormwork && includeRebar
                ? "formwork + rebar"
                : includeFormwork
                    ? "formwork"
                    : "rebar";
            string sheetText = createSheets ? "with sheets" : "views only";
            string groupText = FormatShopDrawingGroupMode(groupMode);
            string replaceText = replaceExisting ? "replace existing" : "keep existing";

            if (ShopDrawingStatusText != null)
            {
                ShopDrawingStatusText.Text = $"Queued {outputText}, {scopeText}, 1:{scale}, {sheetText}, {groupText}, {replaceText}, {issueText}, {revision}.";
            }
            ShowStatus($"Shop Drawing: queued {outputText}, {scopeText}, 1:{scale}, {sheetText}, {groupText}, {replaceText}, {revision}.");
            return true;
        }

