        private void OnAutoJoinResetOrderClick(object sender, RoutedEventArgs e)
        {
            Autodesk.Revit.DB.BuiltInCategory? selectedCategory = (AutoJoinCategoriesListBox?.SelectedItem as AutoJoinCategoryItem)?.Category;
            Dictionary<Autodesk.Revit.DB.BuiltInCategory, bool> enabledByCategory =
                _autoJoinCategoryItems.ToDictionary(i => i.Category, i => i.IsEnabled);

            _autoJoinCategoryItems.Clear();
            foreach (AutoJoinCategoryItem item in CreateDefaultAutoJoinCategoryItems())
            {
                if (enabledByCategory.TryGetValue(item.Category, out bool enabled))
                {
                    item.IsEnabled = enabled;
                }

                _autoJoinCategoryItems.Add(item);
            }

            if (selectedCategory.HasValue && AutoJoinCategoriesListBox != null)
            {
                AutoJoinCategoryItem selectedItem = _autoJoinCategoryItems.FirstOrDefault(i => i.Category == selectedCategory.Value);
                if (selectedItem != null)
                {
                    AutoJoinCategoriesListBox.SelectedItem = selectedItem;
                }
            }

            UpdateAutoJoinCategoryButtons();
        }

