        private void OnSelectionModeChanged(object sender, RoutedEventArgs e)
        {
            if (sender == LayerModeRadio_Grid || sender == SelectModeRadio_Grid)
            {
                bool layerMode = LayerModeRadio_Grid != null && LayerModeRadio_Grid.IsChecked == true;
                if (LayerCombo_Grid != null)
                {
                    LayerCombo_Grid.IsEnabled = layerMode;
                }
            }
            else if (sender == LayerModeRadio_Bored || sender == SelectModeRadio_Bored)
            {
                bool layerMode = LayerModeRadio_Bored != null && LayerModeRadio_Bored.IsChecked == true;
                if (BoredLayerCombo_Bored != null) BoredLayerCombo_Bored.IsEnabled = layerMode;
            }
            else if (sender == LayerModeRadio_Foundation || sender == SelectModeRadio_Foundation)
            {
                bool layerMode = LayerModeRadio_Foundation != null && LayerModeRadio_Foundation.IsChecked == true;
                if (SlabLayerCombo_Foundation != null) SlabLayerCombo_Foundation.IsEnabled = layerMode;
                if (IsolatedLayerCombo_Foundation != null) IsolatedLayerCombo_Foundation.IsEnabled = layerMode;
            }
            else if (sender == LayerModeRadio_Wall || sender == SelectModeRadio_Wall)
            {
                bool layerMode = LayerModeRadio_Wall != null && LayerModeRadio_Wall.IsChecked == true;
                if (LayerCombo_Wall != null)
                {
                    LayerCombo_Wall.IsEnabled = layerMode;
                }
            }
            else if (sender == LayerModeRadio_Slab || sender == SelectModeRadio_Slab)
            {
                bool layerMode = LayerModeRadio_Slab != null && LayerModeRadio_Slab.IsChecked == true;
                if (LayerCombo_Slab != null)
                {
                    LayerCombo_Slab.IsEnabled = layerMode;
                }
            }
            else if (sender == LayerModeRadio_Beam || sender == SelectModeRadio_Beam)
            {
                bool layerMode = LayerModeRadio_Beam != null && LayerModeRadio_Beam.IsChecked == true;
                if (LayerCombo_Beam != null)
                {
                    LayerCombo_Beam.IsEnabled = layerMode;
                }
            }
            else
            {
                var drawingLayerModeRadio = GetDrawingLayerModeRadio();
                var drawingSelectModeRadio = GetDrawingSelectModeRadio();
                if (sender == drawingLayerModeRadio || sender == drawingSelectModeRadio)
                {
                    bool layerMode = drawingLayerModeRadio != null && drawingLayerModeRadio.IsChecked == true;
                    var drawingLayerCombo = GetDrawingLayerCombo();
                    if (drawingLayerCombo != null)
                    {
                        drawingLayerCombo.IsEnabled = layerMode;
                    }
                }
                else
                {
                    bool layerMode = LayerModeRadio != null && LayerModeRadio.IsChecked == true;
                    if (LayerCombo != null)
                    {
                        LayerCombo.IsEnabled = layerMode;
                    }
                }
            }

            UpdateCad2ModelTasWorkflowRail();
        }

