        private bool IsLayerMode()
        {
            if (IsGridlineTab())
            {
                return LayerModeRadio_Grid != null && LayerModeRadio_Grid.IsChecked == true;
            }

            if (IsDrawingTab())
            {
                var drawingLayerModeRadio = GetDrawingLayerModeRadio();
                return drawingLayerModeRadio != null && drawingLayerModeRadio.IsChecked == true;
            }

            if (IsBoredPileTab())
            {
                return LayerModeRadio_Bored != null && LayerModeRadio_Bored.IsChecked == true;
            }

            if (IsFoundationTab())
            {
                return LayerModeRadio_Foundation != null && LayerModeRadio_Foundation.IsChecked == true;
            }
            if (IsLeanConcreteTab())
            {
                return false;
            }
            if (IsSoilExcavationTab())
            {
                return false;
            }
            if (IsWallTab())
            {
                return LayerModeRadio_Wall != null && LayerModeRadio_Wall.IsChecked == true;
            }
            if (IsSlabTab())
            {
                return LayerModeRadio_Slab != null && LayerModeRadio_Slab.IsChecked == true;
            }
            if (IsBeamTab())
            {
                return LayerModeRadio_Beam != null && LayerModeRadio_Beam.IsChecked == true;
            }

            return LayerModeRadio != null && LayerModeRadio.IsChecked == true;
        }

        private bool IsColumnColorMode()
        {
            return IsColumnTabActive() && ColorModeRadio != null && ColorModeRadio.IsChecked == true;
        }

        private bool TryUpdateRequestFromUi()
        {
            ApplyTasReferenceSettingsToRequest();
            if (IsCad2ModelTab())
            {
                SyncCad2ModelTasAttributeRowsToSectionSpecs();
                ApplyCad2ModelTasAttributeEditorToRequest();
            }

            if (IsDrawingTab())
            {
                if (IsDrawingColumnRebarSubTab())
                {
                    return TryUpdateColumnRebarRequestFromUi();
                }

                var drawingLineStyleCombo = GetDrawingLineStyleCombo();
                if (drawingLineStyleCombo?.SelectedItem is ComboItem lineStyle)
                {
                    _handler.Request.DrawingLineStyleId = lineStyle.Id;
                }
                else
                {
                    _handler.Request.DrawingLineStyleId = Autodesk.Revit.DB.ElementId.InvalidElementId;
                }
            }
            else if (IsBoredPileTab())
            {
                if (BaseLevelCombo_Bored?.SelectedItem is ComboItem baseLevel)
                {
                    _handler.Request.BaseLevelId = baseLevel.Id;
                }
                else
                {
                    ShowStatus("Select base level.");
                    return false;
                }

                if (TopLevelCombo_Bored?.SelectedItem is ComboItem topLevel)
                {
                    _handler.Request.TopLevelId = topLevel.Id;
                }
                else
                {
                    ShowStatus("Select top level.");
                    return false;
                }

                _handler.Request.BoredPileTypeId = (BoredPileCombo_Bored?.SelectedItem as ComboItem)?.Id ?? Autodesk.Revit.DB.ElementId.InvalidElementId;
                _handler.Request.SpunPileTypeId = Autodesk.Revit.DB.ElementId.InvalidElementId;
                _handler.Request.SheetPileTypeId = Autodesk.Revit.DB.ElementId.InvalidElementId;

                if (_handler.Request.BoredPileTypeId == Autodesk.Revit.DB.ElementId.InvalidElementId)
                {
                    ShowStatus("Select bored pile family type.");
                    return false;
                }

                double headOffsetMm = 0.0;
                if (HeadOffsetTextBox_Bored != null && !string.IsNullOrWhiteSpace(HeadOffsetTextBox_Bored.Text))
                {
                    string raw = HeadOffsetTextBox_Bored.Text.Trim();
                    if (!double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out headOffsetMm) &&
                        !double.TryParse(raw, NumberStyles.Float, CultureInfo.CurrentCulture, out headOffsetMm))
                    {
                        ShowStatus("Head Offset must be a number (mm).");
                        return false;
                    }
                }

                _handler.Request.BoredPileTopOffsetFt = headOffsetMm / 304.8;
            }
            else if (IsFoundationTab())
            {
                if (FoundationLevelCombo_Foundation?.SelectedItem is ComboItem level)
                {
                    _handler.Request.FoundationLevelId = level.Id;
                }
                else
                {
                    ShowStatus("Select foundation level.");
                    return false;
                }

                _handler.Request.FoundationSlabTypeId = (FoundationSlabTypeCombo_Foundation?.SelectedItem as ComboItem)?.Id ?? Autodesk.Revit.DB.ElementId.InvalidElementId;
                _handler.Request.FoundationIsolatedTypeId = (FoundationIsolatedTypeCombo_Foundation?.SelectedItem as ComboItem)?.Id ?? Autodesk.Revit.DB.ElementId.InvalidElementId;

                if (_handler.Request.FoundationSlabTypeId == Autodesk.Revit.DB.ElementId.InvalidElementId &&
                    _handler.Request.FoundationIsolatedTypeId == Autodesk.Revit.DB.ElementId.InvalidElementId)
                {
                    ShowStatus("Select slab or isolated foundation type.");
                    return false;
                }

                double offsetMm = 0.0;
                if (FoundationOffsetTextBox_Foundation != null && !string.IsNullOrWhiteSpace(FoundationOffsetTextBox_Foundation.Text))
                {
                    string raw = FoundationOffsetTextBox_Foundation.Text.Trim();
                    if (!double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out offsetMm) &&
                        !double.TryParse(raw, NumberStyles.Float, CultureInfo.CurrentCulture, out offsetMm))
                    {
                        ShowStatus("Foundation Offset must be a number (mm).");
                        return false;
                    }
                }

                _handler.Request.FoundationOffsetFt = offsetMm / 304.8;
            }
            else if (IsLeanConcreteTab())
            {
                System.Windows.Controls.ComboBox leanLevelCombo = GetLeanConcreteLevelCombo();
                if (leanLevelCombo?.SelectedItem is ComboItem level)
                {
                    _handler.Request.LeanConcreteLevelId = level.Id;
                }
                else
                {
                    ShowStatus("Select Lean Concrete level.");
                    return false;
                }

                System.Windows.Controls.ComboBox leanTypeCombo = GetLeanConcreteTypeCombo();
                if (leanTypeCombo?.SelectedItem is ComboItem type)
                {
                    _handler.Request.LeanConcreteTypeId = type.Id;
                }
                else
                {
                    ShowStatus("Select Lean Concrete type.");
                    return false;
                }

                double sideOffsetMm = 0.0;
                System.Windows.Controls.TextBox leanSideOffsetTextBox = GetLeanConcreteSideOffsetTextBox();
                if (leanSideOffsetTextBox != null && !string.IsNullOrWhiteSpace(leanSideOffsetTextBox.Text))
                {
                    string raw = leanSideOffsetTextBox.Text.Trim();
                    if (!double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out sideOffsetMm) &&
                        !double.TryParse(raw, NumberStyles.Float, CultureInfo.CurrentCulture, out sideOffsetMm))
                    {
                        ShowStatus("Lean Concrete side offset must be a number (mm).");
                        return false;
                    }
                }

                if (sideOffsetMm < 0)
                {
                    ShowStatus("Lean Concrete side offset must be zero or greater.");
                    return false;
                }

                _handler.Request.LeanConcreteSideOffsetFt = sideOffsetMm / 304.8;
                int selectedSourceCount = _handler.Request.SelectedLeanSourceElementIds?.Count ?? 0;
                if (selectedSourceCount == 0)
                {
                    ShowStatus("Pick modeled structural source elements first (Foundation, Column, Wall, Beam, Floor, Stair).");
                    return false;
                }
            }
            else if (IsSoilExcavationTab())
            {
                double topOffsetMm = 0.0;
                System.Windows.Controls.TextBox soilTopOffsetTextBox = GetSoilExcavationTopOffsetTextBox();
                if (soilTopOffsetTextBox != null && !string.IsNullOrWhiteSpace(soilTopOffsetTextBox.Text))
                {
                    string raw = soilTopOffsetTextBox.Text.Trim();
                    if (!double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out topOffsetMm) &&
                        !double.TryParse(raw, NumberStyles.Float, CultureInfo.CurrentCulture, out topOffsetMm))
                    {
                        ShowStatus("Soil Excavation top foundation offset must be a number (mm).");
                        return false;
                    }
                }

                if (topOffsetMm < 0)
                {
                    ShowStatus("Soil Excavation top foundation offset must be zero or greater.");
                    return false;
                }

                double bottomOffsetMm = 0.0;
                System.Windows.Controls.TextBox soilBaseOffsetTextBox = GetSoilExcavationBaseOffsetTextBox();
                if (soilBaseOffsetTextBox != null && !string.IsNullOrWhiteSpace(soilBaseOffsetTextBox.Text))
                {
                    string raw = soilBaseOffsetTextBox.Text.Trim();
                    if (!double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out bottomOffsetMm) &&
                        !double.TryParse(raw, NumberStyles.Float, CultureInfo.CurrentCulture, out bottomOffsetMm))
                    {
                        ShowStatus("Soil Excavation bottom lean offset must be a number (mm).");
                        return false;
                    }
                }

                if (bottomOffsetMm < 0)
                {
                    ShowStatus("Soil Excavation bottom lean offset must be zero or greater.");
                    return false;
                }

                System.Windows.Controls.TextBox soilAngleTextBox = GetSoilExcavationAngleTextBox();
                if (soilAngleTextBox == null || string.IsNullOrWhiteSpace(soilAngleTextBox.Text))
                {
                    ShowStatus("Soil Excavation angle must be a number (degrees).");
                    return false;
                }

                string angleRaw = soilAngleTextBox.Text.Trim();
                if (!double.TryParse(angleRaw, NumberStyles.Float, CultureInfo.InvariantCulture, out double angleDeg) &&
                    !double.TryParse(angleRaw, NumberStyles.Float, CultureInfo.CurrentCulture, out angleDeg))
                {
                    ShowStatus("Soil Excavation angle must be a number (degrees).");
                    return false;
                }

                if (angleDeg <= 0 || angleDeg >= 180)
                {
                    ShowStatus("Soil Excavation angle must be between 0 and 180 degrees.");
                    return false;
                }

                double acuteAngleDeg = angleDeg > 90 ? 180 - angleDeg : angleDeg;
                if (acuteAngleDeg <= 0 || acuteAngleDeg >= 89.999)
                {
                    ShowStatus("Soil Excavation angle cannot be 90 degrees. Use values like 45 or 135.");
                    return false;
                }

                _handler.Request.SoilExcavationTopOffsetFt = topOffsetMm / 304.8;
                _handler.Request.SoilExcavationBaseOffsetFt = bottomOffsetMm / 304.8;
                _handler.Request.SoilExcavationAngleDeg = angleDeg;

                int selectedSourceCount = _handler.Request.SelectedSoilExcavationSourceElementIds?.Count ?? 0;
                if (selectedSourceCount == 0)
                {
                    ShowStatus("Pick modeled lean concrete elements first.");
                    return false;
                }
            }
            else if (IsWallTab())
            {
                if (WallBaseLevelCombo?.SelectedItem is ComboItem wallBaseLevel)
                {
                    _handler.Request.BaseLevelId = wallBaseLevel.Id;
                }
                else
                {
                    ShowStatus("Select wall base level.");
                    return false;
                }

                if (WallTopLevelCombo?.SelectedItem is ComboItem wallTopLevel)
                {
                    _handler.Request.TopLevelId = wallTopLevel.Id;
                }
                else
                {
                    ShowStatus("Select wall top level.");
                    return false;
                }

                if (WallTypeCombo?.SelectedItem is ComboItem wallType)
                {
                    _handler.Request.WallTypeId = wallType.Id;
                }
                else
                {
                    ShowStatus("Select wall type.");
                    return false;
                }

                _handler.Request.CreateWallTypesFromExcel = CreateWallTypesCheck?.IsChecked == true;
                _handler.Request.WallSectionSpecs = _wallSectionSpecs
                    .Where(s => s != null && !string.IsNullOrWhiteSpace(s.Name))
                    .Select(s => new WallSectionSpec
                    {
                        Name = s.Name.Trim(),
                        WidthMm = s.WidthMm
                    })
                    .ToList();
            }
            else if (IsSlabTab())
            {
                if (SlabLevelCombo?.SelectedItem is ComboItem slabLevel)
                {
                    _handler.Request.SlabLevelId = slabLevel.Id;
                }
                else
                {
                    ShowStatus("Select slab level.");
                    return false;
                }

                if (SlabTypeCombo?.SelectedItem is ComboItem slabType)
                {
                    _handler.Request.SlabTypeId = slabType.Id;
                }
                else
                {
                    ShowStatus("Select slab type.");
                    return false;
                }

                _handler.Request.UseSlabSectionSpecs = UseSlabSectionsCheck?.IsChecked == true;
                _handler.Request.SlabSectionSpecs = _slabSectionSpecs
                    .Where(s => s != null && !string.IsNullOrWhiteSpace(s.Name))
                    .Select(s => new SlabSectionSpec
                    {
                        Name = s.Name.Trim(),
                        ThicknessMm = s.ThicknessMm
                    })
                    .ToList();
            }
            else if (IsBeamTab())
            {
                if (BeamBaseLevelCombo?.SelectedItem is ComboItem beamBaseLevel)
                {
                    _handler.Request.BaseLevelId = beamBaseLevel.Id;
                }
                else
                {
                    ShowStatus("Select beam base level.");
                    return false;
                }

                if (BeamTopLevelCombo?.SelectedItem is ComboItem beamTopLevel)
                {
                    _handler.Request.TopLevelId = beamTopLevel.Id;
                }
                else
                {
                    ShowStatus("Select beam top level.");
                    return false;
                }

                if (BeamTypeCombo?.SelectedItem is ComboItem beamType)
                {
                    _handler.Request.BeamTypeId = beamType.Id;
                }
                else
                {
                    ShowStatus("Select beam type.");
                    return false;
                }

                _handler.Request.CreateBeamTypesFromExcel = CreateBeamTypesCheck?.IsChecked == true;
                _handler.Request.BeamSectionSpecs = _beamSectionSpecs
                    .Where(s => s != null && !string.IsNullOrWhiteSpace(s.Name))
                    .Select(s => new BeamSectionSpec
                    {
                        Name = s.Name.Trim(),
                        WidthMm = s.WidthMm,
                        DepthMm = s.DepthMm
                    })
                    .ToList();
            }
            else if (!IsGridlineTab())
            {
                if (TryGetSelectedLevels(out ComboItem baseLevel, out ComboItem topLevel))
                {
                    _handler.Request.BaseLevelId = baseLevel.Id;
                    _handler.Request.TopLevelId = topLevel.Id;
                }
                else
                {
                    ShowStatus("Select base level and top level.");
                    return false;
                }

                if (ColumnTypeCombo.SelectedItem is ComboItem columnType)
                {
                    _handler.Request.ColumnTypeId = columnType.Id;
                }
                else
                {
                    ShowStatus("Select column type.");
                    return false;
                }

                _handler.Request.CreateColumnTypesFromExcel = CreateColumnTypesCheck?.IsChecked == true;
                if (_handler.Request.CreateColumnTypesFromExcel && _columnSectionSpecs.Count == 0)
                {
                    try
                    {
                        List<ColumnSectionSpec> fromExcel = ReadColumnSectionSpecsFromExcel(
                            GetColumnSectionExcelPath(),
                            out string sourceLabel);
                        if (fromExcel.Count > 0)
                        {
                            _columnSectionSpecs.Clear();
                            foreach (ColumnSectionSpec spec in fromExcel)
                            {
                                _columnSectionSpecs.Add(spec);
                            }

                            ShowStatus($"Loaded {fromExcel.Count} column section row(s) from {sourceLabel}.");
                        }
                    }
                    catch
                    {
                        // Keep generation flow working even if Excel import fails.
                    }
                }

                _handler.Request.ColumnSectionSpecs = _columnSectionSpecs
                    .Where(s => s != null && !string.IsNullOrWhiteSpace(s.Name))
                    .Select(s => new ColumnSectionSpec
                    {
                        Name = s.Name.Trim(),
                        WidthMm = s.WidthMm,
                        LengthMm = s.LengthMm
                    })
                    .ToList();
            }

            _handler.Request.UseLayerFilter = IsLayerMode();
            _handler.Request.UseColorFilter = IsColumnColorMode();
            _handler.Request.SelectedLayerName = GetSelectedLayerName();
            _handler.Request.SelectedLabelLayerName = GetSelectedLabelLayerName();
            _handler.Request.SelectedBoredLayerName = GetSelectedBoredLayerName();
            _handler.Request.SelectedSpunLayerName = "";
            _handler.Request.SelectedSheetLayerName = "";
            _handler.Request.SelectedFoundationSlabLayerName = GetSelectedFoundationSlabLayerName();
            _handler.Request.SelectedFoundationIsolatedLayerName = GetSelectedFoundationIsolatedLayerName();
            _handler.Request.SelectedSlabLayerName = GetSelectedSlabLayerName();
            _handler.Request.SelectedBeamLabelLayerName = GetSelectedBeamLabelLayerName();

            _handler.Request.UseCircles = CirclesCheck.IsChecked == true;
            _handler.Request.UseBlocks = BlocksCheck.IsChecked == true;
            _handler.Request.UseLineIntersections = LinesCheck.IsChecked == true;
            _handler.Request.ExplicitColumnPoints.Clear();

            return true;
        }

        private bool TryUpdateAutoJoinRequest()
        {
            List<Autodesk.Revit.DB.BuiltInCategory> categories = _autoJoinCategoryItems
                .Where(i => i != null && i.IsEnabled)
                .Select(i => i.Category)
                .ToList();

            if (categories.Count == 0)
            {
                ShowStatus("Select at least one category for AutoJoin.");
                return false;
            }

            _handler.Request.AutoJoinCategories = categories;
            _handler.Request.AutoJoinUseActiveView = AutoJoinActiveViewRadio?.IsChecked == true;

            return true;
        }

        private void InitializeAutoJoinDefaults()
        {
            if (_autoJoinCategoryItems.Count == 0)
            {
                foreach (AutoJoinCategoryItem item in CreateDefaultAutoJoinCategoryItems())
                {
                    _autoJoinCategoryItems.Add(item);
                }
            }

            if (AutoJoinCategoriesListBox != null && AutoJoinCategoriesListBox.SelectedIndex < 0 && _autoJoinCategoryItems.Count > 0)
            {
                AutoJoinCategoriesListBox.SelectedIndex = 0;
            }

            UpdateAutoJoinCategoryButtons();
        }

        private static IEnumerable<AutoJoinCategoryItem> CreateDefaultAutoJoinCategoryItems()
        {
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_Ceilings, "Ceilings", false);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_Columns, "Columns", false);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_Floors, "Floors", true);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_GenericModel, "Generic Models", false);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_Mass, "Mass", false);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_StructuralColumns, "Structural Columns", true);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_StructuralFoundation, "Structural Foundations", true);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_StructuralFraming, "Structural Framing", true);
            yield return new AutoJoinCategoryItem(Autodesk.Revit.DB.BuiltInCategory.OST_Walls, "Walls", true);
        }

        private void MoveSelectedAutoJoinCategory(int delta)
        {
            if (AutoJoinCategoriesListBox == null || _autoJoinCategoryItems.Count == 0)
            {
                return;
            }

            int index = AutoJoinCategoriesListBox.SelectedIndex;
            if (index < 0)
            {
                return;
            }

            int newIndex = Math.Max(0, Math.Min(_autoJoinCategoryItems.Count - 1, index + delta));
            if (newIndex == index)
            {
                return;
            }

            _autoJoinCategoryItems.Move(index, newIndex);
            AutoJoinCategoriesListBox.SelectedIndex = newIndex;
            AutoJoinCategoriesListBox.ScrollIntoView(AutoJoinCategoriesListBox.SelectedItem);
            UpdateAutoJoinCategoryButtons();
        }

        private void UpdateAutoJoinCategoryButtons()
        {
            if (AutoJoinCategoriesListBox == null)
            {
                return;
            }

            int index = AutoJoinCategoriesListBox.SelectedIndex;
            bool hasSelection = index >= 0 && index < _autoJoinCategoryItems.Count;

            if (AutoJoinMoveUpButton != null)
            {
                AutoJoinMoveUpButton.IsEnabled = hasSelection && index > 0;
            }

            if (AutoJoinMoveDownButton != null)
            {
                AutoJoinMoveDownButton.IsEnabled = hasSelection && index < _autoJoinCategoryItems.Count - 1;
            }

            if (AutoJoinResetOrderButton != null)
            {
                AutoJoinResetOrderButton.IsEnabled = _autoJoinCategoryItems.Count > 0;
            }

            if (AutoJoinToggleSelectionButton != null)
            {
                AutoJoinToggleSelectionButton.IsEnabled = hasSelection;
            }
        }

        private void InitializeFoundationRebarDesignUi()
        {
            if (FoundationRebarTypeModeCombo == null)
            {
                return;
            }

            _foundationRebarUiEventsSuspended = true;
            try
            {
                EnsureFoundationRebarPlaceholderBarTypeItems();
                ApplyFoundationRebarPreset("sync", announce: false);
            }
            finally
            {
                _foundationRebarUiEventsSuspended = false;
            }

            _foundationRebarPreviewDirty = true;
            SyncFoundationRebarShorthandSpecTextBoxesFromCurrentInputs();
            UpdateFoundationRebarDesignUiState();
            ClearFoundationRebarInputs(announce: false);
            SyncFoundationNaviateCloneUiFromLegacyInputs();

            Dispatcher.BeginInvoke(
                new Action(() =>
                {
                    if (!RenderFoundationRebarPreviewFromCurrentInputs(strictValidation: false, showStatusOnFailure: false))
                    {
                        RenderFoundationRebarPreviewPlaceholder();
                    }
                }),
                DispatcherPriority.Background);
        }

        private bool IsFoundationNaviateCloneUiVisible()
        {
            return FoundationRebarNaviateClonePanel?.Visibility == System.Windows.Visibility.Visible;
        }

        private bool TryGetFoundationNaviateCloneLayerFromSender(object sender, out bool isTop)
        {
            isTop = true;
            if (!(sender is FrameworkElement element))
            {
                return false;
            }

            string name = (element.Name ?? "").Trim();
            if (string.IsNullOrWhiteSpace(name))
            {
                return false;
            }

            if (name.IndexOf("Top", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                isTop = true;
                return true;
            }

            if (name.IndexOf("Bottom", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                isTop = false;
                return true;
            }

            return false;
        }

