        private void SetFoundationNaviateLayerDirectionCloneUi(bool isTop, FoundationNaviateUiMainLayerDirection direction)
        {
            bool previous = _foundationNaviateCloneUiSyncInProgress;
            _foundationNaviateCloneUiSyncInProgress = true;
            try
            {
                if (direction == FoundationNaviateUiMainLayerDirection.TransversalBars)
                {
                    if (GetFoundationNaviateDirectionTransRadio(isTop) != null)
                    {
                        GetFoundationNaviateDirectionTransRadio(isTop).IsChecked = true;
                    }
                }
                else if (GetFoundationNaviateDirectionLongRadio(isTop) != null)
                {
                    GetFoundationNaviateDirectionLongRadio(isTop).IsChecked = true;
                }
            }
            finally
            {
                _foundationNaviateCloneUiSyncInProgress = previous;
            }
        }

        private void SetFoundationNaviateReinforcementModeCloneUi(bool isTop, FoundationNaviateUiReinforcementDisplayMode mode)
        {
            System.Windows.Controls.Primitives.ToggleButton continuousToggle = GetFoundationNaviateContinuousToggle(isTop);
            System.Windows.Controls.Primitives.ToggleButton lapToggle = GetFoundationNaviateLapToggle(isTop);
            bool previous = _foundationNaviateCloneUiSyncInProgress;
            _foundationNaviateCloneUiSyncInProgress = true;
            try
            {
                bool lap = mode == FoundationNaviateUiReinforcementDisplayMode.LapLength;
                if (continuousToggle != null) continuousToggle.IsChecked = !lap;
                if (lapToggle != null) lapToggle.IsChecked = lap;
            }
            finally
            {
                _foundationNaviateCloneUiSyncInProgress = previous;
            }
        }

        private void SetFoundationNaviateQuantityModeCloneUi(bool isTop, FoundationNaviateUiQuantityInputMode mode)
        {
            bool previous = _foundationNaviateCloneUiSyncInProgress;
            _foundationNaviateCloneUiSyncInProgress = true;
            try
            {
                bool bars = mode == FoundationNaviateUiQuantityInputMode.NumberOfBars;
                RadioButton barsRadio = GetFoundationNaviateQtyBarsRadio(isTop);
                RadioButton spacingRadio = GetFoundationNaviateQtySpacingRadio(isTop);
                if (barsRadio != null) barsRadio.IsChecked = bars;
                if (spacingRadio != null) spacingRadio.IsChecked = !bars;
            }
            finally
            {
                _foundationNaviateCloneUiSyncInProgress = previous;
            }
        }

        private void NormalizeFoundationNaviateReinforcementModeCloneUi(bool isTop)
        {
            System.Windows.Controls.Primitives.ToggleButton continuousToggle = GetFoundationNaviateContinuousToggle(isTop);
            System.Windows.Controls.Primitives.ToggleButton lapToggle = GetFoundationNaviateLapToggle(isTop);
            if (continuousToggle == null || lapToggle == null)
            {
                return;
            }

            bool previous = _foundationNaviateCloneUiSyncInProgress;
            _foundationNaviateCloneUiSyncInProgress = true;
            try
            {
                if (continuousToggle.IsChecked == true && lapToggle.IsChecked == true)
                {
                    lapToggle.IsChecked = false;
                }
                else if (continuousToggle.IsChecked != true && lapToggle.IsChecked != true)
                {
                    continuousToggle.IsChecked = true;
                }
            }
            finally
            {
                _foundationNaviateCloneUiSyncInProgress = previous;
            }
        }

        private static bool TryEstimateFoundationRebarBarDiameterMm(System.Windows.Controls.ComboBox combo, out double diameterMm)
        {
            diameterMm = 0.0;
            string text = GetFoundationRebarComboText(combo);
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            MatchCollection matches = Regex.Matches(text, @"\d+(\.\d+)?");
            if (matches.Count == 0)
            {
                return false;
            }

            string last = matches[matches.Count - 1].Value;
            if (!double.TryParse(last, NumberStyles.Float, CultureInfo.InvariantCulture, out diameterMm) &&
                !double.TryParse(last, NumberStyles.Float, CultureInfo.CurrentCulture, out diameterMm))
            {
                return false;
            }

            return diameterMm > 0.0;
        }

        private static int ParseFoundationNaviateIntOrDefault(System.Windows.Controls.TextBox textBox, int fallback, int minValue)
        {
            string raw = (textBox?.Text ?? "").Trim();
            if (int.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsed) ||
                int.TryParse(raw, NumberStyles.Integer, CultureInfo.CurrentCulture, out parsed))
            {
                return Math.Max(minValue, parsed);
            }

            return Math.Max(minValue, fallback);
        }

        private static double ParseFoundationNaviateDoubleOrDefault(System.Windows.Controls.TextBox textBox, double fallback, double minValue)
        {
            string raw = (textBox?.Text ?? "").Trim();
            if (TryParseFlexibleDouble(raw, out double parsed))
            {
                return Math.Max(minValue, parsed);
            }

            return Math.Max(minValue, fallback);
        }

        private void UpdateFoundationNaviateCloneOverlapComputedText(bool isTop)
        {
            TextBlock label = GetFoundationNaviateOverlapComputedTextBlock(isTop);
            if (label == null)
            {
                return;
            }

            double multiplier = ParseFoundationNaviateDoubleOrDefault(GetFoundationNaviateOverlapMultiplierTextBox(isTop), 40.0, 0.0);
            if (TryEstimateFoundationRebarBarDiameterMm(GetFoundationNaviateBarTypeCombo(isTop), out double diameterMm))
            {
                double overlapMm = multiplier * diameterMm;
                label.Text = $"x \u03A6 = {overlapMm:0.#} mm";
                return;
            }

            label.Text = $"x \u03A6 = {(multiplier * 10.0):0.#} mm";
        }

        private void UpdateFoundationNaviateCloneLayerVisualState(bool isTop)
        {
            CheckBox enabledCheckBox = GetFoundationNaviateLayerEnabledCheckBox(isTop);
            bool layerEnabled = enabledCheckBox?.IsChecked == true;

            NormalizeFoundationNaviateReinforcementModeCloneUi(isTop);

            bool isLong = GetFoundationNaviateLayerDirectionFromCloneUi(isTop) == FoundationNaviateUiMainLayerDirection.LongitudinalBars;
            System.Windows.Controls.Button longitudinalButton = GetFoundationNaviateLongitudinalButton(isTop);
            if (longitudinalButton != null)
            {
                longitudinalButton.Background = isLong
                    ? new SolidColorBrush(WpfColor.FromRgb(216, 229, 244))
                    : new SolidColorBrush(WpfColor.FromRgb(234, 234, 234));
                longitudinalButton.BorderBrush = isLong
                    ? new SolidColorBrush(WpfColor.FromRgb(175, 192, 210))
                    : new SolidColorBrush(WpfColor.FromRgb(174, 180, 188));
                longitudinalButton.Foreground = isLong
                    ? new SolidColorBrush(WpfColor.FromRgb(39, 73, 110))
                    : new SolidColorBrush(WpfColor.FromRgb(69, 76, 86));
            }

            System.Windows.Controls.Button swapButton = GetFoundationNaviateDirectionSwapButton(isTop);
            if (swapButton != null)
            {
                swapButton.IsEnabled = layerEnabled;
            }

            System.Windows.Controls.Button rotateButton = GetFoundationNaviateDirectionRotateButton(isTop);
            if (rotateButton != null)
            {
                rotateButton.IsEnabled = layerEnabled;
            }

            RadioButton longRadio = GetFoundationNaviateDirectionLongRadio(isTop);
            RadioButton transRadio = GetFoundationNaviateDirectionTransRadio(isTop);
            if (longRadio != null) longRadio.IsEnabled = layerEnabled;
            if (transRadio != null) transRadio.IsEnabled = layerEnabled;

            System.Windows.Controls.Primitives.ToggleButton continuousToggle = GetFoundationNaviateContinuousToggle(isTop);
            System.Windows.Controls.Primitives.ToggleButton lapToggle = GetFoundationNaviateLapToggle(isTop);
            if (continuousToggle != null) continuousToggle.IsEnabled = layerEnabled;
            if (lapToggle != null) lapToggle.IsEnabled = layerEnabled;

            System.Windows.Controls.TextBox overlapBox = GetFoundationNaviateOverlapMultiplierTextBox(isTop);
            if (overlapBox != null) overlapBox.IsEnabled = layerEnabled;

            System.Windows.Controls.ComboBox barTypeCombo = GetFoundationNaviateBarTypeCombo(isTop);
            if (barTypeCombo != null) barTypeCombo.IsEnabled = layerEnabled;
            System.Windows.Controls.ComboBox shapeCombo = GetFoundationNaviateShapeCombo(isTop);
            if (shapeCombo != null) shapeCombo.IsEnabled = layerEnabled;
            System.Windows.Controls.ComboBox hookStartCombo = GetFoundationNaviateHookStartCombo(isTop);
            if (hookStartCombo != null) hookStartCombo.IsEnabled = layerEnabled;
            System.Windows.Controls.ComboBox hookEndCombo = GetFoundationNaviateHookEndCombo(isTop);
            if (hookEndCombo != null) hookEndCombo.IsEnabled = layerEnabled;

            RadioButton barsRadio = GetFoundationNaviateQtyBarsRadio(isTop);
            RadioButton spacingRadio = GetFoundationNaviateQtySpacingRadio(isTop);
            if (barsRadio != null) barsRadio.IsEnabled = layerEnabled;
            if (spacingRadio != null) spacingRadio.IsEnabled = layerEnabled;

            bool barsMode = GetFoundationNaviateQuantityModeFromCloneUi(isTop) == FoundationNaviateUiQuantityInputMode.NumberOfBars;
            System.Windows.Controls.TextBox barsTextBox = GetFoundationNaviateQtyBarsTextBox(isTop);
            System.Windows.Controls.TextBox spacingTextBox = GetFoundationNaviateQtySpacingTextBox(isTop);
            if (barsTextBox != null) barsTextBox.IsEnabled = layerEnabled && barsMode;
            if (spacingTextBox != null) spacingTextBox.IsEnabled = layerEnabled && !barsMode;

            Border section = GetFoundationNaviateLayerSectionBorder(isTop);
            if (section != null)
            {
                section.Opacity = layerEnabled ? 1.0 : 0.85;
            }

            UpdateFoundationNaviateCloneOverlapComputedText(isTop);
        }

        private void UpdateFoundationNaviateCloneUiState()
        {
            if (!IsFoundationNaviateCloneUiVisible())
            {
                return;
            }

            UpdateFoundationNaviateCloneLayerVisualState(isTop: true);
            UpdateFoundationNaviateCloneLayerVisualState(isTop: false);
        }

        private void SyncFoundationNaviateCloneUiFromLegacyInputs()
        {
            if (!IsFoundationNaviateCloneUiVisible())
            {
                return;
            }

            bool previous = _foundationNaviateCloneUiSyncInProgress;
            _foundationNaviateCloneUiSyncInProgress = true;
            try
            {
                SyncFoundationNaviateCloneLayerUiFromLegacyInputs(isTop: true);
                SyncFoundationNaviateCloneLayerUiFromLegacyInputs(isTop: false);
            }
            finally
            {
                _foundationNaviateCloneUiSyncInProgress = previous;
            }

            UpdateFoundationNaviateCloneUiState();
        }

        private void SyncFoundationNaviateCloneLayerUiFromLegacyInputs(bool isTop)
        {
            string xSpec = isTop ? (FoundationRebarTopXSpecTextBox?.Text ?? "") : (FoundationRebarBottomXSpecTextBox?.Text ?? "");
            string ySpec = isTop ? (FoundationRebarTopYSpecTextBox?.Text ?? "") : (FoundationRebarBottomYSpecTextBox?.Text ?? "");
            string shapeText = isTop ? (FoundationRebarEasyTopShapeCodeTextBox?.Text ?? "") : (FoundationRebarEasyBottomShapeCodeTextBox?.Text ?? "");
            string lapExpr = isTop ? (FoundationRebarTopLapExprTextBox?.Text ?? "") : (FoundationRebarBottomLapExprTextBox?.Text ?? "");
            System.Windows.Controls.TextBox spacingX = isTop ? FoundationRebarTopSpacingXMmTextBox : FoundationRebarBottomSpacingXMmTextBox;

            FoundationNaviateUiQuantityInputMode quantityMode = InferFoundationNaviateQuantityMode(xSpec, ySpec, out int barCount);
            SetFoundationNaviateQuantityModeCloneUi(isTop, quantityMode);

            if (quantityMode == FoundationNaviateUiQuantityInputMode.NumberOfBars)
            {
                SetFoundationText(GetFoundationNaviateQtyBarsTextBox(isTop), Math.Max(2, barCount).ToString(CultureInfo.InvariantCulture));
            }
            else
            {
                double spacingMm = ParseFoundationNaviateDoubleOrDefault(spacingX, 150.0, 1.0);
                SetFoundationText(GetFoundationNaviateQtySpacingTextBox(isTop), spacingMm.ToString("0.###", CultureInfo.InvariantCulture));
            }

            SetFoundationNaviateLayerDirectionCloneUi(isTop, FoundationNaviateUiMainLayerDirection.LongitudinalBars);

            string normalizedShape = string.IsNullOrWhiteSpace(shapeText) ? "None" : shapeText.Trim();
            SetFoundationComboSelectionByText(GetFoundationNaviateShapeCombo(isTop), normalizedShape);
            SetFoundationComboSelectionByText(GetFoundationNaviateHookStartCombo(isTop), "None");
            SetFoundationComboSelectionByText(GetFoundationNaviateHookEndCombo(isTop), "None");

            double referenceLengthMm = ParseFoundationNaviateDoubleOrDefault(FoundationRebarLengthMmTextBox, 2500.0, 1.0);
            bool hasLap = TryParseFoundationRebarLengthExpressionMm(lapExpr, Math.Max(1.0, referenceLengthMm), out double lapMm) && lapMm > 0.0;
            SetFoundationNaviateReinforcementModeCloneUi(
                isTop,
                hasLap ? FoundationNaviateUiReinforcementDisplayMode.LapLength : FoundationNaviateUiReinforcementDisplayMode.Continuous);

            int overlapMultiplier = 40;
            if (hasLap && TryEstimateFoundationRebarBarDiameterMm(GetFoundationNaviateBarTypeCombo(isTop), out double diameterMm) && diameterMm > 0.0)
            {
                overlapMultiplier = Math.Max(1, (int)Math.Round(lapMm / diameterMm, MidpointRounding.AwayFromZero));
            }

            SetFoundationText(
                GetFoundationNaviateOverlapMultiplierTextBox(isTop),
                overlapMultiplier.ToString(CultureInfo.InvariantCulture));
        }

        private void ApplyFoundationNaviateCloneLayerToLegacyInputs(bool isTop)
        {
            System.Windows.Controls.TextBox spacingXTextBox = isTop ? FoundationRebarTopSpacingXMmTextBox : FoundationRebarBottomSpacingXMmTextBox;
            System.Windows.Controls.TextBox spacingYTextBox = isTop ? FoundationRebarTopSpacingYMmTextBox : FoundationRebarBottomSpacingYMmTextBox;
            System.Windows.Controls.TextBox lapExprTextBox = isTop ? FoundationRebarTopLapExprTextBox : FoundationRebarBottomLapExprTextBox;
            System.Windows.Controls.TextBox shapeCodeTextBox = isTop ? FoundationRebarEasyTopShapeCodeTextBox : FoundationRebarEasyBottomShapeCodeTextBox;

            if (shapeCodeTextBox != null)
            {
                string shapeCode = (GetFoundationRebarComboText(GetFoundationNaviateShapeCombo(isTop)) ?? "").Trim();
                if (string.IsNullOrWhiteSpace(shapeCode))
                {
                    shapeCode = "None";
                }

                SetFoundationText(shapeCodeTextBox, shapeCode);
            }

            double widthMm = ParseFoundationNaviateDoubleOrDefault(FoundationRebarWidthMmTextBox, 2500.0, 200.0);
            double lengthMm = ParseFoundationNaviateDoubleOrDefault(FoundationRebarLengthMmTextBox, 2500.0, 200.0);
            double sideCoverMm = ParseFoundationNaviateDoubleOrDefault(FoundationRebarSideCoverMmTextBox, 50.0, 0.0);

            FoundationNaviateUiQuantityInputMode quantityMode = GetFoundationNaviateQuantityModeFromCloneUi(isTop);
            if (quantityMode == FoundationNaviateUiQuantityInputMode.NumberOfBars)
            {
                int count = ParseFoundationNaviateIntOrDefault(GetFoundationNaviateQtyBarsTextBox(isTop), 2, 2);
                if (TryConvertFoundationRebarBarCountToSpacingMm(count, widthMm, sideCoverMm, out double xSpacingMm))
                {
                    SetFoundationText(spacingXTextBox, xSpacingMm.ToString("0.###", CultureInfo.InvariantCulture));
                }
                else
                {
                    SetFoundationText(spacingXTextBox, "150");
                }

                if (TryConvertFoundationRebarBarCountToSpacingMm(count, lengthMm, sideCoverMm, out double ySpacingMm))
                {
                    SetFoundationText(spacingYTextBox, ySpacingMm.ToString("0.###", CultureInfo.InvariantCulture));
                }
                else
                {
                    SetFoundationText(spacingYTextBox, "150");
                }
            }
            else
            {
                double spacingMm = ParseFoundationNaviateDoubleOrDefault(GetFoundationNaviateQtySpacingTextBox(isTop), 150.0, 1.0);
                string spacingText = spacingMm.ToString("0.###", CultureInfo.InvariantCulture);
                SetFoundationText(spacingXTextBox, spacingText);
                SetFoundationText(spacingYTextBox, spacingText);
            }

            if (lapExprTextBox != null)
            {
                double lapMm = 0.0;
                if (GetFoundationNaviateReinforcementModeFromCloneUi(isTop) == FoundationNaviateUiReinforcementDisplayMode.LapLength)
                {
                    double multiplier = ParseFoundationNaviateDoubleOrDefault(GetFoundationNaviateOverlapMultiplierTextBox(isTop), 40.0, 0.0);
                    if (multiplier > 0.0 &&
                        TryEstimateFoundationRebarBarDiameterMm(GetFoundationNaviateBarTypeCombo(isTop), out double diameterMm) &&
                        diameterMm > 0.0)
                    {
                        lapMm = multiplier * diameterMm;
                    }
                }

                SetFoundationText(
                    lapExprTextBox,
                    lapMm > 0.0 ? lapMm.ToString("0.###", CultureInfo.InvariantCulture) : "0");
            }
        }

        private void SyncFoundationNaviateCloneToLegacyInputsAndMarkDirty()
        {
            if (_foundationRebarUiEventsSuspended || _foundationNaviateCloneUiSyncInProgress)
            {
                return;
            }

            if (!IsFoundationNaviateCloneUiVisible())
            {
                HandleFoundationRebarPreviewInputChanged();
                return;
            }

            bool previousSuspend = _foundationRebarUiEventsSuspended;
            _foundationRebarUiEventsSuspended = true;
            try
            {
                ApplyFoundationNaviateCloneLayerToLegacyInputs(isTop: true);
                ApplyFoundationNaviateCloneLayerToLegacyInputs(isTop: false);
            }
            finally
            {
                _foundationRebarUiEventsSuspended = previousSuspend;
            }

            UpdateFoundationNaviateCloneUiState();
            HandleFoundationRebarPreviewInputChanged();
        }

        private void OnFoundationNaviateLayerDirectionToggleClick(object sender, RoutedEventArgs e)
        {
            if (_foundationRebarUiEventsSuspended || _foundationNaviateCloneUiSyncInProgress)
            {
                return;
            }

            if (!TryGetFoundationNaviateCloneLayerFromSender(sender, out bool isTop))
            {
                return;
            }

            FoundationNaviateUiMainLayerDirection nextDirection;
            if (ReferenceEquals(sender, GetFoundationNaviateLongitudinalButton(isTop)))
            {
                nextDirection = FoundationNaviateUiMainLayerDirection.LongitudinalBars;
            }
            else
            {
                nextDirection =
                    GetFoundationNaviateLayerDirectionFromCloneUi(isTop) == FoundationNaviateUiMainLayerDirection.LongitudinalBars
                        ? FoundationNaviateUiMainLayerDirection.TransversalBars
                        : FoundationNaviateUiMainLayerDirection.LongitudinalBars;
            }

            SetFoundationNaviateLayerDirectionCloneUi(isTop, nextDirection);
            UpdateFoundationNaviateCloneUiState();
            SyncFoundationNaviateCloneToLegacyInputsAndMarkDirty();
        }

        private void OnFoundationNaviateReinforcementModeToggleClick(object sender, RoutedEventArgs e)
        {
            if (_foundationRebarUiEventsSuspended || _foundationNaviateCloneUiSyncInProgress)
            {
                return;
            }

            if (!TryGetFoundationNaviateCloneLayerFromSender(sender, out bool isTop))
            {
                return;
            }

            System.Windows.Controls.Primitives.ToggleButton continuousToggle = GetFoundationNaviateContinuousToggle(isTop);
            System.Windows.Controls.Primitives.ToggleButton lapToggle = GetFoundationNaviateLapToggle(isTop);
            if (continuousToggle == null || lapToggle == null)
            {
                return;
            }

            bool previous = _foundationNaviateCloneUiSyncInProgress;
            _foundationNaviateCloneUiSyncInProgress = true;
            try
            {
                if (ReferenceEquals(sender, continuousToggle))
                {
                    if (continuousToggle.IsChecked == true)
                    {
                        lapToggle.IsChecked = false;
                    }
                    else if (lapToggle.IsChecked != true)
                    {
                        continuousToggle.IsChecked = true;
                    }
                }
                else if (ReferenceEquals(sender, lapToggle))
                {
                    if (lapToggle.IsChecked == true)
                    {
                        continuousToggle.IsChecked = false;
                    }
                    else if (continuousToggle.IsChecked != true)
                    {
                        lapToggle.IsChecked = true;
                    }
                }
            }
            finally
            {
                _foundationNaviateCloneUiSyncInProgress = previous;
            }

            UpdateFoundationNaviateCloneUiState();
            SyncFoundationNaviateCloneToLegacyInputsAndMarkDirty();
        }

