        private void OnFoundationRebarPreviewCanvasMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            var canvas = sender as System.Windows.Controls.Canvas;
            if (canvas == null)
            {
                return;
            }

            List<FoundationPreviewDragHandle> handles = GetFoundationRebarPreviewDragHandleList(canvas);
            if (handles == null || handles.Count == 0)
            {
                return;
            }

            System.Windows.Point p = e.GetPosition(canvas);
            FoundationPreviewDragHandle handle = FindFoundationRebarPreviewDragHandle(handles, p);
            if (handle == null)
            {
                return;
            }

            _foundationRebarPreviewSelectedEditField = handle.Field;
            _foundationRebarPreviewActiveDragHandle = handle;
            _foundationRebarPreviewActiveDragCanvas = canvas;
            _foundationRebarPreviewCanvasHandleDragging = true;
            _foundationRebarPreviewCanvasLastDragPoint = p;

            try
            {
                canvas.CaptureMouse();
            }
            catch
            {
            }

            RenderFoundationRebarPreviewFromCurrentInputs(strictValidation: false, showStatusOnFailure: false);
            SyncFoundationRebarPreviewActiveDragHandleToCurrentCanvas();
            e.Handled = true;
        }

        private void OnFoundationRebarPreviewCanvasMouseMove(object sender, MouseEventArgs e)
        {
            var canvas = sender as System.Windows.Controls.Canvas;
            if (canvas == null || !_foundationRebarPreviewCanvasHandleDragging || !ReferenceEquals(canvas, _foundationRebarPreviewActiveDragCanvas))
            {
                return;
            }

            if (e.LeftButton != MouseButtonState.Pressed)
            {
                EndFoundationRebarPreviewCanvasHandleDrag();
                return;
            }

            FoundationPreviewDragHandle handle = _foundationRebarPreviewActiveDragHandle;
            if (handle == null)
            {
                return;
            }

            System.Windows.Point p = e.GetPosition(canvas);
            double deltaPx = handle.Axis == FoundationPreviewDragAxis.Horizontal
                ? (p.X - _foundationRebarPreviewCanvasLastDragPoint.X)
                : (p.Y - _foundationRebarPreviewCanvasLastDragPoint.Y);

            if (Math.Abs(deltaPx) < 0.25)
            {
                return;
            }

            _foundationRebarPreviewCanvasLastDragPoint = p;

            double deltaMm = deltaPx * handle.MmPerPixel * handle.DragSign;
            if (Math.Abs(deltaMm) < 0.05)
            {
                return;
            }

            if (TryAdjustFoundationRebarPreviewFieldByDelta(handle.Field, deltaMm))
            {
                SyncFoundationRebarPreviewActiveDragHandleToCurrentCanvas();
            }

            e.Handled = true;
        }

        private void OnFoundationRebarPreviewCanvasMouseLeftButtonUp(object sender, MouseButtonEventArgs e)
        {
            EndFoundationRebarPreviewCanvasHandleDrag();
        }

        private void OnFoundationRebarPreviewCanvasMouseLeave(object sender, MouseEventArgs e)
        {
            if (_foundationRebarPreviewCanvasHandleDragging && e.LeftButton != MouseButtonState.Pressed)
            {
                EndFoundationRebarPreviewCanvasHandleDrag();
            }
        }

        private void OnFoundationRebarPreviewCanvasMouseWheel(object sender, MouseWheelEventArgs e)
        {
            if ((Keyboard.Modifiers & ModifierKeys.Control) != ModifierKeys.Control)
            {
                return;
            }

            var canvas = sender as System.Windows.Controls.Canvas;
            FoundationPreviewEditField field = _foundationRebarPreviewSelectedEditField;
            if (field == FoundationPreviewEditField.None && canvas != null)
            {
                List<FoundationPreviewDragHandle> handles = GetFoundationRebarPreviewDragHandleList(canvas);
                FoundationPreviewDragHandle hovered = handles == null ? null : FindFoundationRebarPreviewDragHandle(handles, e.GetPosition(canvas));
                if (hovered != null)
                {
                    field = hovered.Field;
                }
            }

            if (field == FoundationPreviewEditField.None)
            {
                field = ReferenceEquals(canvas, FoundationRebarPlanCanvas)
                    ? FoundationPreviewEditField.Length
                    : FoundationPreviewEditField.Thickness;
            }

            double stepMm = GetFoundationRebarPreviewWheelStepMm(field);
            if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
            {
                stepMm *= 5.0;
            }

            double deltaMm = e.Delta > 0 ? stepMm : -stepMm;
            if (TryAdjustFoundationRebarPreviewFieldByDelta(field, deltaMm))
            {
                _foundationRebarPreviewSelectedEditField = field;
            }

            e.Handled = true;
        }

        private void EndFoundationRebarPreviewCanvasHandleDrag()
        {
            _foundationRebarPreviewCanvasHandleDragging = false;
            _foundationRebarPreviewActiveDragHandle = null;

            if (_foundationRebarPreviewActiveDragCanvas != null)
            {
                try
                {
                    _foundationRebarPreviewActiveDragCanvas.ReleaseMouseCapture();
                }
                catch
                {
                }
            }

            _foundationRebarPreviewActiveDragCanvas = null;
        }

        private void SyncFoundationRebarPreviewActiveDragHandleToCurrentCanvas()
        {
            if (_foundationRebarPreviewActiveDragCanvas == null || _foundationRebarPreviewSelectedEditField == FoundationPreviewEditField.None)
            {
                return;
            }

            List<FoundationPreviewDragHandle> handles = GetFoundationRebarPreviewDragHandleList(_foundationRebarPreviewActiveDragCanvas);
            if (handles == null)
            {
                return;
            }

            for (int i = 0; i < handles.Count; i++)
            {
                FoundationPreviewDragHandle handle = handles[i];
                if (handle != null && handle.Field == _foundationRebarPreviewSelectedEditField)
                {
                    _foundationRebarPreviewActiveDragHandle = handle;
                    return;
                }
            }
        }

        private List<FoundationPreviewDragHandle> GetFoundationRebarPreviewDragHandleList(System.Windows.Controls.Canvas canvas)
        {
            if (ReferenceEquals(canvas, FoundationRebarPlanCanvas))
            {
                return _foundationRebarPlanDragHandles;
            }

            if (ReferenceEquals(canvas, FoundationRebarSectionACanvas))
            {
                return _foundationRebarSectionADragHandles;
            }

            if (ReferenceEquals(canvas, FoundationRebarSectionBCanvas))
            {
                return _foundationRebarSectionBDragHandles;
            }

            return null;
        }

        private static FoundationPreviewDragHandle FindFoundationRebarPreviewDragHandle(List<FoundationPreviewDragHandle> handles, System.Windows.Point p)
        {
            if (handles == null || handles.Count == 0)
            {
                return null;
            }

            FoundationPreviewDragHandle best = null;
            double bestDistSq = double.MaxValue;
            for (int i = 0; i < handles.Count; i++)
            {
                FoundationPreviewDragHandle handle = handles[i];
                if (handle == null || !handle.HitRectPx.Contains(p))
                {
                    continue;
                }

                double dx = p.X - handle.CenterXPx;
                double dy = p.Y - handle.CenterYPx;
                double distSq = (dx * dx) + (dy * dy);
                if (distSq < bestDistSq)
                {
                    best = handle;
                    bestDistSq = distSq;
                }
            }

            return best;
        }

        private bool TryAdjustFoundationRebarPreviewFieldByDelta(FoundationPreviewEditField field, double deltaMm)
        {
            if (field == FoundationPreviewEditField.None || double.IsNaN(deltaMm) || double.IsInfinity(deltaMm) || Math.Abs(deltaMm) < 1e-9)
            {
                return false;
            }

            if (!TryGetFoundationRebarPreviewFieldValueMm(field, out double currentMm))
            {
                return false;
            }

            return TrySetFoundationRebarPreviewFieldValueMm(field, currentMm + deltaMm);
        }

        private bool TrySetFoundationRebarPreviewFieldValueMm(FoundationPreviewEditField field, double valueMm)
        {
            if (!TryGetFoundationRebarPreviewFieldTextBox(field, out System.Windows.Controls.TextBox textBox, out double minMm))
            {
                return false;
            }

            if (textBox == null)
            {
                return false;
            }

            double clampedMm = Math.Max(minMm, valueMm);
            if (double.IsNaN(clampedMm) || double.IsInfinity(clampedMm))
            {
                return false;
            }

            clampedMm = Math.Round(clampedMm, 1);
            if (TryGetFoundationRebarPreviewFieldValueMm(field, out double currentMm) && Math.Abs(currentMm - clampedMm) < 0.05)
            {
                _foundationRebarPreviewSelectedEditField = field;
                return false;
            }

            _foundationRebarPreviewSelectedEditField = field;

            _foundationRebarUiEventsSuspended = true;
            try
            {
                SetFoundationText(textBox, clampedMm.ToString("0.#", CultureInfo.InvariantCulture));
            }
            finally
            {
                _foundationRebarUiEventsSuspended = false;
            }

            HandleFoundationRebarPreviewInputChanged();
            RenderFoundationRebarPreviewFromCurrentInputs(strictValidation: false, showStatusOnFailure: false);
            return true;
        }

        private bool TryGetFoundationRebarPreviewFieldValueMm(FoundationPreviewEditField field, out double valueMm)
        {
            valueMm = 0.0;
            if (!TryGetFoundationRebarPreviewFieldTextBox(field, out System.Windows.Controls.TextBox textBox, out _))
            {
                return false;
            }

            if (textBox == null)
            {
                return false;
            }

            return TryParseFlexibleDouble((textBox.Text ?? "").Trim(), out valueMm);
        }

        private bool TryGetFoundationRebarPreviewFieldTextBox(
            FoundationPreviewEditField field,
            out System.Windows.Controls.TextBox textBox,
            out double minMm)
        {
            textBox = null;
            minMm = 0.0;

            switch (field)
            {
                case FoundationPreviewEditField.Length:
                    textBox = FoundationRebarLengthMmTextBox;
                    minMm = 200.0;
                    return true;
                case FoundationPreviewEditField.Width:
                    textBox = FoundationRebarWidthMmTextBox;
                    minMm = 200.0;
                    return true;
                case FoundationPreviewEditField.Thickness:
                    textBox = FoundationRebarThicknessMmTextBox;
                    minMm = 150.0;
                    return true;
                case FoundationPreviewEditField.PedestalHeight:
                    textBox = FoundationRebarPedestalHeightMmTextBox;
                    minMm = 0.0;
                    return true;
                case FoundationPreviewEditField.PedestalWidth:
                    textBox = FoundationRebarPedestalWidthMmTextBox;
                    minMm = 0.0;
                    return true;
                case FoundationPreviewEditField.PedestalDepth:
                    textBox = FoundationRebarPedestalDepthMmTextBox;
                    minMm = 0.0;
                    return true;
                default:
                    return false;
            }
        }

        private static double GetFoundationRebarPreviewWheelStepMm(FoundationPreviewEditField field)
        {
            switch (field)
            {
                case FoundationPreviewEditField.Length:
                case FoundationPreviewEditField.Width:
                case FoundationPreviewEditField.PedestalWidth:
                case FoundationPreviewEditField.PedestalDepth:
                    return 25.0;
                case FoundationPreviewEditField.Thickness:
                case FoundationPreviewEditField.PedestalHeight:
                    return 10.0;
                default:
                    return 10.0;
            }
        }

        private static string GetFoundationRebarPreviewFieldLabel(FoundationPreviewEditField field)
        {
            switch (field)
            {
                case FoundationPreviewEditField.Length: return "L";
                case FoundationPreviewEditField.Width: return "B";
                case FoundationPreviewEditField.Thickness: return "T";
                case FoundationPreviewEditField.PedestalHeight: return "Ped.H";
                case FoundationPreviewEditField.PedestalWidth: return "Ped.W";
                case FoundationPreviewEditField.PedestalDepth: return "Ped.B";
                default: return "";
            }
        }

        private void OnFoundationRebarPreviewViewportMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            if (!(sender is UIElement element))
            {
                return;
            }

            _foundationRebarPreviewIsDragging = true;
            _foundationRebarPreviewLastMousePoint = e.GetPosition(element);
            try
            {
                element.CaptureMouse();
            }
            catch
            {
            }
        }

        private void OnFoundationRebarPreviewViewportMouseMove(object sender, MouseEventArgs e)
        {
            if (!_foundationRebarPreviewIsDragging || !(sender is UIElement element) || e.LeftButton != MouseButtonState.Pressed)
            {
                return;
            }

            System.Windows.Point p = e.GetPosition(element);
            Vector delta = p - _foundationRebarPreviewLastMousePoint;
            _foundationRebarPreviewLastMousePoint = p;

            _foundationRebarPreviewYawDeg += delta.X * 0.45;
            _foundationRebarPreviewPitchDeg -= delta.Y * 0.30;
            _foundationRebarPreviewPitchDeg = Math.Max(-80.0, Math.Min(80.0, _foundationRebarPreviewPitchDeg));

            RefreshFoundationRebarPreviewCameraOnly();
        }

        private void OnFoundationRebarPreviewViewportMouseLeftButtonUp(object sender, MouseButtonEventArgs e)
        {
            _foundationRebarPreviewIsDragging = false;
            if (sender is UIElement element)
            {
                try
                {
                    element.ReleaseMouseCapture();
                }
                catch
                {
                }
            }
        }

        private void OnFoundationRebarPreviewViewportMouseWheel(object sender, MouseWheelEventArgs e)
        {
            if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
            {
                FoundationPreviewEditField field = _foundationRebarPreviewSelectedEditField;
                if (field == FoundationPreviewEditField.None)
                {
                    field = FoundationPreviewEditField.Thickness;
                }

                double stepMm = GetFoundationRebarPreviewWheelStepMm(field);
                if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
                {
                    stepMm *= 5.0;
                }

                double deltaMm = e.Delta > 0 ? stepMm : -stepMm;
                TryAdjustFoundationRebarPreviewFieldByDelta(field, deltaMm);
                e.Handled = true;
                return;
            }

            double scale = e.Delta > 0 ? 1.12 : 1.0 / 1.12;
            _foundationRebarPreviewZoomFactor *= scale;
            _foundationRebarPreviewZoomFactor = Math.Max(0.2, Math.Min(6.0, _foundationRebarPreviewZoomFactor));
            RefreshFoundationRebarPreviewCameraOnly();
            e.Handled = true;
        }

