        private void InitializeWallRebarDesignUi()
        {
            bool previousSuspend = _wallNaviateUiEventsSuspended;
            _wallNaviateUiEventsSuspended = true;
            try
            {
                string[] barTypes =
                {
                    "DB10", "DB12", "DB14", "DB16", "DB18", "DB20",
                    "DB22", "DB25", "DB28", "DB30", "DB32"
                };
                string[] hookOptions =
                {
                    "None",
                    "Standard - 90 deg.",
                    "Standard - 180 deg.",
                    "Rebar Hook 90",
                    "Standard - 135 deg."
                };
                string[] overlapOptions = { "20", "25", "30", "35", "40", "45", "50", "55", "60", "65", "70", "80" };

                foreach (System.Windows.Controls.ComboBox combo in GetWallNaviateAllBarTypeCombos())
                {
                    PopulateWallNaviateCombo(combo, barTypes, "DB10");
                }

                foreach (System.Windows.Controls.ComboBox combo in GetWallNaviateHookCombos())
                {
                    PopulateWallNaviateCombo(combo, hookOptions, "None");
                }

                foreach (System.Windows.Controls.ComboBox combo in GetWallNaviateOverlapCombos())
                {
                    PopulateWallNaviateCombo(combo, overlapOptions, "40");
                }

                if (WallNaviateVerticalSpacingTextBox != null && string.IsNullOrWhiteSpace(WallNaviateVerticalSpacingTextBox.Text))
                {
                    WallNaviateVerticalSpacingTextBox.Text = "200 mm";
                }
                if (WallNaviateHorizontalSpacingTextBox != null && string.IsNullOrWhiteSpace(WallNaviateHorizontalSpacingTextBox.Text))
                {
                    WallNaviateHorizontalSpacingTextBox.Text = "200 mm";
                }
                if (WallNaviateMaxBarLengthTextBox != null && string.IsNullOrWhiteSpace(WallNaviateMaxBarLengthTextBox.Text))
                {
                    WallNaviateMaxBarLengthTextBox.Text = "12000 mm";
                }
                if (WallNaviateFixedSplitLapLengthTextBox != null && string.IsNullOrWhiteSpace(WallNaviateFixedSplitLapLengthTextBox.Text))
                {
                    WallNaviateFixedSplitLapLengthTextBox.Text = "600 mm";
                }
                if (WallNaviateTieSpacingXTextBox != null && string.IsNullOrWhiteSpace(WallNaviateTieSpacingXTextBox.Text))
                {
                    WallNaviateTieSpacingXTextBox.Text = "600 mm";
                }
                if (WallNaviateTieSpacingZTextBox != null && string.IsNullOrWhiteSpace(WallNaviateTieSpacingZTextBox.Text))
                {
                    WallNaviateTieSpacingZTextBox.Text = "600 mm";
                }

                if (WallNaviateMainReinfMode1 != null && WallNaviateMainReinfMode2 != null)
                {
                    if (WallNaviateMainReinfMode1.IsChecked != true && WallNaviateMainReinfMode2.IsChecked != true)
                    {
                        WallNaviateMainReinfMode1.IsChecked = true;
                        WallNaviateMainReinfMode2.IsChecked = false;
                    }
                }

                if (WallNaviateTopDowelMode1Toggle != null && WallNaviateTopDowelMode2Toggle != null && WallNaviateTopDowelMode3Toggle != null)
                {
                    EnsureExclusiveWallNaviateToggleSelection(
                        preferred: WallNaviateTopDowelMode1Toggle,
                        WallNaviateTopDowelMode1Toggle,
                        WallNaviateTopDowelMode2Toggle,
                        WallNaviateTopDowelMode3Toggle);
                }

                if (WallNaviateLeftDowelMode1Toggle != null && WallNaviateLeftDowelMode2Toggle != null && WallNaviateLeftDowelMode3Toggle != null)
                {
                    EnsureExclusiveWallNaviateToggleSelection(
                        preferred: WallNaviateLeftDowelMode1Toggle,
                        WallNaviateLeftDowelMode1Toggle,
                        WallNaviateLeftDowelMode2Toggle,
                        WallNaviateLeftDowelMode3Toggle);
                }

                if (WallNaviateRightDowelMode1Toggle != null && WallNaviateRightDowelMode2Toggle != null && WallNaviateRightDowelMode3Toggle != null)
                {
                    EnsureExclusiveWallNaviateToggleSelection(
                        preferred: WallNaviateRightDowelMode1Toggle,
                        WallNaviateRightDowelMode1Toggle,
                        WallNaviateRightDowelMode2Toggle,
                        WallNaviateRightDowelMode3Toggle);
                }
            }
            finally
            {
                _wallNaviateUiEventsSuspended = previousSuspend;
            }

            UpdateWallNaviateFormUiState();
        }

        private IEnumerable<System.Windows.Controls.ComboBox> GetWallNaviateAllBarTypeCombos()
        {
            if (WallNaviateVerticalBarTypeCombo != null) yield return WallNaviateVerticalBarTypeCombo;
            if (WallNaviateHorizontalBarTypeCombo != null) yield return WallNaviateHorizontalBarTypeCombo;
            if (WallNaviateTieBarTypeCombo != null) yield return WallNaviateTieBarTypeCombo;
            if (WallNaviateTopDowelBarTypeCombo != null) yield return WallNaviateTopDowelBarTypeCombo;
            if (WallNaviateLeftDowelBarTypeCombo != null) yield return WallNaviateLeftDowelBarTypeCombo;
            if (WallNaviateRightDowelBarTypeCombo != null) yield return WallNaviateRightDowelBarTypeCombo;
        }

        private IEnumerable<System.Windows.Controls.ComboBox> GetWallNaviateHookCombos()
        {
            if (WallNaviateVerticalHookTopCombo != null) yield return WallNaviateVerticalHookTopCombo;
            if (WallNaviateHorizontalLeftHookCombo != null) yield return WallNaviateHorizontalLeftHookCombo;
            if (WallNaviateHorizontalRightHookCombo != null) yield return WallNaviateHorizontalRightHookCombo;
        }

        private IEnumerable<System.Windows.Controls.ComboBox> GetWallNaviateOverlapCombos()
        {
            if (WallNaviateTopDowelOverlapCombo != null) yield return WallNaviateTopDowelOverlapCombo;
            if (WallNaviateLeftDowelOverlapCombo != null) yield return WallNaviateLeftDowelOverlapCombo;
            if (WallNaviateRightDowelOverlapCombo != null) yield return WallNaviateRightDowelOverlapCombo;
        }

        private static void PopulateWallNaviateCombo(System.Windows.Controls.ComboBox combo, IEnumerable<string> values, string defaultValue)
        {
            if (combo == null)
            {
                return;
            }

            string previousSelection = GetWallNaviateSelectedComboText(combo);

            combo.Items.Clear();
            foreach (string value in values ?? Array.Empty<string>())
            {
                combo.Items.Add(new ComboBoxItem { Content = value ?? "" });
            }

            string desired = string.IsNullOrWhiteSpace(previousSelection) ? defaultValue : previousSelection;
            if (!TrySetWallNaviateComboSelection(combo, desired))
            {
                TrySetWallNaviateComboSelection(combo, defaultValue);
            }

            if (combo.SelectedIndex < 0 && combo.Items.Count > 0)
            {
                combo.SelectedIndex = 0;
            }
        }

        private static bool TrySetWallNaviateComboSelection(System.Windows.Controls.ComboBox combo, string text)
        {
            if (combo == null)
            {
                return false;
            }

            string target = (text ?? string.Empty).Trim();
            for (int i = 0; i < combo.Items.Count; i++)
            {
                object item = combo.Items[i];
                string itemText;
                if (item is ComboBoxItem cbi)
                {
                    itemText = cbi.Content?.ToString() ?? "";
                }
                else
                {
                    itemText = item?.ToString() ?? "";
                }

                if (string.Equals(itemText.Trim(), target, StringComparison.OrdinalIgnoreCase))
                {
                    combo.SelectedIndex = i;
                    return true;
                }
            }

            return false;
        }

        private static string GetWallNaviateSelectedComboText(System.Windows.Controls.ComboBox combo)
        {
            if (combo == null)
            {
                return string.Empty;
            }

            if (combo.SelectedItem is ComboBoxItem cbi)
            {
                return cbi.Content?.ToString() ?? string.Empty;
            }

            return combo.SelectedItem?.ToString() ?? combo.Text ?? string.Empty;
        }

        private static void EnsureExclusiveWallNaviateToggleSelection(System.Windows.Controls.Primitives.ToggleButton preferred, params System.Windows.Controls.Primitives.ToggleButton[] toggles)
        {
            if (toggles == null || toggles.Length == 0)
            {
                return;
            }

            System.Windows.Controls.Primitives.ToggleButton chosen = toggles.FirstOrDefault(t => t?.IsChecked == true) ?? preferred ?? toggles.FirstOrDefault(t => t != null);
            if (chosen == null)
            {
                return;
            }

            foreach (System.Windows.Controls.Primitives.ToggleButton toggle in toggles)
            {
                if (toggle == null)
                {
                    continue;
                }

                toggle.IsChecked = ReferenceEquals(toggle, chosen);
            }
        }

        private void UpdateWallNaviateFormUiState()
        {
            SyncWallNaviateLapLengthBarTypeCombosFromMainBars();

            int topPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(
                WallNaviateTopDowelMode1Toggle,
                WallNaviateTopDowelMode2Toggle,
                WallNaviateTopDowelMode3Toggle);
            int leftPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(
                WallNaviateLeftDowelMode1Toggle,
                WallNaviateLeftDowelMode2Toggle,
                WallNaviateLeftDowelMode3Toggle);
            int rightPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(
                WallNaviateRightDowelMode1Toggle,
                WallNaviateRightDowelMode2Toggle,
                WallNaviateRightDowelMode3Toggle);

            UpdateWallNaviateDowelSectionState(
                WallNaviateTopDowelCheckBox,
                WallNaviateTopDowelSectionBorder,
                WallNaviateTopDowelBarTypeCombo,
                WallNaviateTopDowelOverlapCombo,
                WallNaviateTopDowelMode1Toggle,
                WallNaviateTopDowelMode2Toggle,
                WallNaviateTopDowelMode3Toggle);

            UpdateWallNaviateDowelSectionState(
                WallNaviateLeftDowelCheckBox,
                WallNaviateLeftDowelSectionBorder,
                WallNaviateLeftDowelBarTypeCombo,
                WallNaviateLeftDowelOverlapCombo,
                WallNaviateLeftDowelMode1Toggle,
                WallNaviateLeftDowelMode2Toggle,
                WallNaviateLeftDowelMode3Toggle);

            UpdateWallNaviateDowelSectionState(
                WallNaviateRightDowelCheckBox,
                WallNaviateRightDowelSectionBorder,
                WallNaviateRightDowelBarTypeCombo,
                WallNaviateRightDowelOverlapCombo,
                WallNaviateRightDowelMode1Toggle,
                WallNaviateRightDowelMode2Toggle,
                WallNaviateRightDowelMode3Toggle);

            UpdateWallNaviateDowelOverlapSummary(
                GetWallNaviateActiveDowelBarTypeCombo(WallNaviateVerticalBarTypeCombo, WallNaviateTopDowelBarTypeCombo, topPatternMode),
                WallNaviateTopDowelOverlapCombo,
                WallNaviateTopDowelOverlapSummaryTextBlock);
            UpdateWallNaviateDowelOverlapSummary(
                GetWallNaviateActiveDowelBarTypeCombo(WallNaviateHorizontalBarTypeCombo, WallNaviateLeftDowelBarTypeCombo, leftPatternMode),
                WallNaviateLeftDowelOverlapCombo,
                WallNaviateLeftDowelOverlapSummaryTextBlock);
            UpdateWallNaviateDowelOverlapSummary(
                GetWallNaviateActiveDowelBarTypeCombo(WallNaviateHorizontalBarTypeCombo, WallNaviateRightDowelBarTypeCombo, rightPatternMode),
                WallNaviateRightDowelOverlapCombo,
                WallNaviateRightDowelOverlapSummaryTextBlock);

            UpdateWallNaviateToolboxSectionState();
        }

        private void UpdateWallNaviateToolboxSectionState()
        {
            bool autoSplitEnabled = WallNaviateAutoSplitCheckBox?.IsChecked == true;
            bool useFixedSplitLap = autoSplitEnabled && WallNaviateUseFixedSplitLapCheckBox?.IsChecked == true;
            bool tieBarsEnabled = WallNaviateCreateTieBarsCheckBox?.IsChecked == true;

            if (WallNaviateMaxBarLengthTextBox != null) WallNaviateMaxBarLengthTextBox.IsEnabled = autoSplitEnabled;
            if (WallNaviateUseFixedSplitLapCheckBox != null) WallNaviateUseFixedSplitLapCheckBox.IsEnabled = autoSplitEnabled;
            if (WallNaviateFixedSplitLapLengthTextBox != null) WallNaviateFixedSplitLapLengthTextBox.IsEnabled = useFixedSplitLap;

            if (WallNaviateTieBarTypeCombo != null) WallNaviateTieBarTypeCombo.IsEnabled = tieBarsEnabled;
            if (WallNaviateTieSpacingXTextBox != null) WallNaviateTieSpacingXTextBox.IsEnabled = tieBarsEnabled;
            if (WallNaviateTieSpacingZTextBox != null) WallNaviateTieSpacingZTextBox.IsEnabled = tieBarsEnabled;
        }

        private void SyncWallNaviateLapLengthBarTypeCombosFromMainBars()
        {
            string verticalBarTypeName = (GetWallNaviateSelectedComboText(WallNaviateVerticalBarTypeCombo) ?? "").Trim();
            string horizontalBarTypeName = (GetWallNaviateSelectedComboText(WallNaviateHorizontalBarTypeCombo) ?? "").Trim();
            int topPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(
                WallNaviateTopDowelMode1Toggle,
                WallNaviateTopDowelMode2Toggle,
                WallNaviateTopDowelMode3Toggle);
            int leftPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(
                WallNaviateLeftDowelMode1Toggle,
                WallNaviateLeftDowelMode2Toggle,
                WallNaviateLeftDowelMode3Toggle);
            int rightPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(
                WallNaviateRightDowelMode1Toggle,
                WallNaviateRightDowelMode2Toggle,
                WallNaviateRightDowelMode3Toggle);

            SyncWallNaviateDowelBarTypeCombo(WallNaviateTopDowelBarTypeCombo, verticalBarTypeName, topPatternMode);
            SyncWallNaviateDowelBarTypeCombo(WallNaviateLeftDowelBarTypeCombo, horizontalBarTypeName, leftPatternMode);
            SyncWallNaviateDowelBarTypeCombo(WallNaviateRightDowelBarTypeCombo, horizontalBarTypeName, rightPatternMode);
        }

        private void SyncWallNaviateDowelBarTypeCombo(System.Windows.Controls.ComboBox dowelBarTypeCombo, string inheritedBarTypeName, int patternModeIndex)
        {
            if (dowelBarTypeCombo == null || string.IsNullOrWhiteSpace(inheritedBarTypeName))
            {
                return;
            }

            bool useInheritedBarType = patternModeIndex <= 0;
            string selectedBarTypeName = (GetWallNaviateSelectedComboText(dowelBarTypeCombo) ?? "").Trim();
            if (useInheritedBarType || string.IsNullOrWhiteSpace(selectedBarTypeName))
            {
                TrySetWallNaviateComboSelection(dowelBarTypeCombo, inheritedBarTypeName);
            }
        }

        private static System.Windows.Controls.ComboBox GetWallNaviateActiveDowelBarTypeCombo(
            System.Windows.Controls.ComboBox inheritedBarTypeCombo,
            System.Windows.Controls.ComboBox dowelBarTypeCombo,
            int patternModeIndex)
        {
            if (patternModeIndex <= 0)
            {
                return inheritedBarTypeCombo;
            }

            return dowelBarTypeCombo ?? inheritedBarTypeCombo;
        }

        private static void UpdateWallNaviateDowelSectionState(
            CheckBox checkBox,
            Border sectionBorder,
            System.Windows.Controls.ComboBox barTypeCombo,
            System.Windows.Controls.ComboBox overlapCombo,
            System.Windows.Controls.Primitives.ToggleButton mode1,
            System.Windows.Controls.Primitives.ToggleButton mode2,
            System.Windows.Controls.Primitives.ToggleButton mode3)
        {
            bool isEnabled = checkBox?.IsChecked == true;
            int selectedPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(mode1, mode2, mode3);
            bool useInheritedBarType = selectedPatternMode <= 0;

            if (barTypeCombo != null) barTypeCombo.IsEnabled = isEnabled && !useInheritedBarType;
            if (overlapCombo != null) overlapCombo.IsEnabled = isEnabled;
            if (mode1 != null) mode1.IsEnabled = isEnabled;
            if (mode2 != null) mode2.IsEnabled = isEnabled;
            if (mode3 != null) mode3.IsEnabled = isEnabled;

            if (sectionBorder != null)
            {
                sectionBorder.Opacity = isEnabled ? 1.0 : 0.65;
            }
        }

        private static void UpdateWallNaviateDowelOverlapSummary(System.Windows.Controls.ComboBox barTypeCombo, System.Windows.Controls.ComboBox overlapCombo, TextBlock summaryTextBlock)
        {
            if (summaryTextBlock == null)
            {
                return;
            }

            int multiplier = TryParseWallNaviateInt(GetWallNaviateSelectedComboText(overlapCombo), 40);
            int diameterMm = TryParseWallNaviateBarDiameterMm(GetWallNaviateSelectedComboText(barTypeCombo), 10);
            int lapMm = Math.Max(0, multiplier) * Math.Max(0, diameterMm);
            summaryTextBlock.Text = $"x Φ = {lapMm} mm";
        }

        private static int TryParseWallNaviateBarDiameterMm(string text, int fallback)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return fallback;
            }

            Match m = Regex.Match(text, @"(\d+)");
            if (!m.Success)
            {
                return fallback;
            }

            return int.TryParse(m.Groups[1].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value)
                ? value
                : fallback;
        }

        private static int TryParseWallNaviateInt(string text, int fallback)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return fallback;
            }

            Match m = Regex.Match(text, @"-?\d+");
            if (!m.Success)
            {
                return fallback;
            }

            return int.TryParse(m.Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value)
                ? value
                : fallback;
        }

        private void OnWallNaviateMainBarsModeChecked(object sender, RoutedEventArgs e)
        {
            if (_wallNaviateUiEventsSuspended)
            {
                return;
            }

            _wallNaviateUiEventsSuspended = true;
            try
            {
                if (ReferenceEquals(sender, WallNaviateMainReinfMode1) && WallNaviateMainReinfMode1?.IsChecked == true)
                {
                    if (WallNaviateMainReinfMode2 != null)
                    {
                        WallNaviateMainReinfMode2.IsChecked = false;
                    }
                }
                else if (ReferenceEquals(sender, WallNaviateMainReinfMode2) && WallNaviateMainReinfMode2?.IsChecked == true)
                {
                    if (WallNaviateMainReinfMode1 != null)
                    {
                        WallNaviateMainReinfMode1.IsChecked = false;
                    }
                }

                if ((WallNaviateMainReinfMode1?.IsChecked != true) && (WallNaviateMainReinfMode2?.IsChecked != true))
                {
                    if (WallNaviateMainReinfMode1 != null)
                    {
                        WallNaviateMainReinfMode1.IsChecked = true;
                    }
                }
            }
            finally
            {
                _wallNaviateUiEventsSuspended = false;
            }

            UpdateWallNaviateFormUiState();
        }

        private void OnWallNaviateMainBarsModeUnchecked(object sender, RoutedEventArgs e)
        {
            if (_wallNaviateUiEventsSuspended)
            {
                return;
            }

            _wallNaviateUiEventsSuspended = true;
            try
            {
                if ((WallNaviateMainReinfMode1?.IsChecked != true) && (WallNaviateMainReinfMode2?.IsChecked != true))
                {
                    if (ReferenceEquals(sender, WallNaviateMainReinfMode1) && WallNaviateMainReinfMode2 != null)
                    {
                        WallNaviateMainReinfMode2.IsChecked = true;
                    }
                    else if (WallNaviateMainReinfMode1 != null)
                    {
                        WallNaviateMainReinfMode1.IsChecked = true;
                    }
                }
            }
            finally
            {
                _wallNaviateUiEventsSuspended = false;
            }

            UpdateWallNaviateFormUiState();
        }

        private void OnWallNaviateDowelModeChecked(object sender, RoutedEventArgs e)
        {
            if (_wallNaviateUiEventsSuspended || !(sender is System.Windows.Controls.Primitives.ToggleButton changed))
            {
                return;
            }

            _wallNaviateUiEventsSuspended = true;
            try
            {
                if (ReferenceEquals(changed, WallNaviateTopDowelMode1Toggle) ||
                    ReferenceEquals(changed, WallNaviateTopDowelMode2Toggle) ||
                    ReferenceEquals(changed, WallNaviateTopDowelMode3Toggle))
                {
                    EnsureExclusiveWallNaviateToggleSelection(
                        changed,
                        WallNaviateTopDowelMode1Toggle,
                        WallNaviateTopDowelMode2Toggle,
                        WallNaviateTopDowelMode3Toggle);
                }
                else if (ReferenceEquals(changed, WallNaviateLeftDowelMode1Toggle) ||
                         ReferenceEquals(changed, WallNaviateLeftDowelMode2Toggle) ||
                         ReferenceEquals(changed, WallNaviateLeftDowelMode3Toggle))
                {
                    EnsureExclusiveWallNaviateToggleSelection(
                        changed,
                        WallNaviateLeftDowelMode1Toggle,
                        WallNaviateLeftDowelMode2Toggle,
                        WallNaviateLeftDowelMode3Toggle);
                }
                else if (ReferenceEquals(changed, WallNaviateRightDowelMode1Toggle) ||
                         ReferenceEquals(changed, WallNaviateRightDowelMode2Toggle) ||
                         ReferenceEquals(changed, WallNaviateRightDowelMode3Toggle))
                {
                    EnsureExclusiveWallNaviateToggleSelection(
                        changed,
                        WallNaviateRightDowelMode1Toggle,
                        WallNaviateRightDowelMode2Toggle,
                        WallNaviateRightDowelMode3Toggle);
