        private bool TryRaiseWallNaviateGenerateRequest()
        {
            if (!TryUpdateWallNaviateRequestFromUi())
            {
                return false;
            }

            _handler.Request.RequestType = CadToModelRequestType.GenerateWallRebar;
            _externalEvent.Raise();
            return true;
        }

        private bool TryUpdateWallNaviateRequestFromUi()
        {
            List<ElementId> hostIds = _wallRebarSelectedHostElementIds
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First())
                .ToList();

            if (hostIds.Count <= 0)
            {
                ShowStatus("WALL: Select wall/floor host(s) first.");
                return false;
            }

            if (!TryParseWallNaviateMmTextToFeet(WallNaviateVerticalSpacingTextBox?.Text, "Vertical spacing", out double verticalSpacingFt))
            {
                return false;
            }

            if (!TryParseWallNaviateMmTextToFeet(WallNaviateHorizontalSpacingTextBox?.Text, "Horizontal spacing", out double horizontalSpacingFt))
            {
                return false;
            }

            bool autoSplitEnabled = WallNaviateAutoSplitCheckBox?.IsChecked == true;
            double maxBarLengthFt = 0.0;
            if (autoSplitEnabled &&
                !TryParseWallNaviateMmTextToFeet(WallNaviateMaxBarLengthTextBox?.Text, "Max bar length", out maxBarLengthFt))
            {
                return false;
            }
            if (autoSplitEnabled && maxBarLengthFt > MmToFeetUi(12000.0) + 1e-9)
            {
                ShowStatus("WALL: Max bar length must be <= 12000 mm.");
                return false;
            }

            bool useFixedSplitLapLength = autoSplitEnabled && WallNaviateUseFixedSplitLapCheckBox?.IsChecked == true;
            double fixedSplitLapLengthFt = 0.0;
            if (useFixedSplitLapLength &&
                !TryParseWallNaviateMmTextToFeet(WallNaviateFixedSplitLapLengthTextBox?.Text, "Split lap length", out fixedSplitLapLengthFt))
            {
                return false;
            }
            if (autoSplitEnabled && useFixedSplitLapLength && fixedSplitLapLengthFt >= (maxBarLengthFt - MmToFeetUi(20.0)))
            {
                ShowStatus("WALL: Split lap length must be smaller than max bar length.");
                return false;
            }

            string verticalBarTypeName = (GetWallNaviateSelectedComboText(WallNaviateVerticalBarTypeCombo) ?? "").Trim();
            string horizontalBarTypeName = (GetWallNaviateSelectedComboText(WallNaviateHorizontalBarTypeCombo) ?? "").Trim();
            if (string.IsNullOrWhiteSpace(verticalBarTypeName))
            {
                ShowStatus("WALL: Select bar type for Vertical Bars.");
                return false;
            }
            if (string.IsNullOrWhiteSpace(horizontalBarTypeName))
            {
                ShowStatus("WALL: Select bar type for Horizontal Bars.");
                return false;
            }

            bool createTieBars = WallNaviateCreateTieBarsCheckBox?.IsChecked == true;
            string tieBarTypeName = (GetWallNaviateSelectedComboText(WallNaviateTieBarTypeCombo) ?? "").Trim();
            if (createTieBars && string.IsNullOrWhiteSpace(tieBarTypeName))
            {
                tieBarTypeName = horizontalBarTypeName;
            }

            double tieSpacingXFt = 0.0;
            double tieSpacingZFt = 0.0;
            if (createTieBars)
            {
                if (string.IsNullOrWhiteSpace(tieBarTypeName))
                {
                    ShowStatus("WALL: Select bar type for Tie Bars.");
                    return false;
                }

                if (!TryParseWallNaviateMmTextToFeet(WallNaviateTieSpacingXTextBox?.Text, "Tie spacing X", out tieSpacingXFt))
                {
                    return false;
                }

                if (!TryParseWallNaviateMmTextToFeet(WallNaviateTieSpacingZTextBox?.Text, "Tie spacing Z", out tieSpacingZFt))
                {
                    return false;
                }
            }

            WallNaviateRebarRequest nav = new WallNaviateRebarRequest
            {
                IsEnabled = true,
                SettingName = GetWallNaviateSettingName(),
                DeleteExistingRebar = true,
                HostElementIds = hostIds.ToList(),
                MainBars = new WallNaviateMainBarsRequest
                {
                    UseReinforcementMode1 = WallNaviateMainReinfMode1?.IsChecked == true,
                    ReinforcementMode1OptionIndex = ClampWallNaviateMainBarsOptionIndex(WallNaviateMainReinfMode1OptionsCombo?.SelectedIndex ?? 0),
                    UseReinforcementMode2 = WallNaviateMainReinfMode2?.IsChecked == true,
                    ReinforcementMode2OptionIndex = ClampWallNaviateMainBarsOptionIndex(WallNaviateMainReinfMode2OptionsCombo?.SelectedIndex ?? 0),
                    VerticalBarTypeName = verticalBarTypeName,
                    VerticalHookTop = (GetWallNaviateSelectedComboText(WallNaviateVerticalHookTopCombo) ?? "None").Trim(),
                    VerticalSpacingFt = verticalSpacingFt,
                    HorizontalBarTypeName = horizontalBarTypeName,
                    HorizontalHookLeft = (GetWallNaviateSelectedComboText(WallNaviateHorizontalLeftHookCombo) ?? "None").Trim(),
                    HorizontalHookRight = (GetWallNaviateSelectedComboText(WallNaviateHorizontalRightHookCombo) ?? "None").Trim(),
                    HorizontalSpacingFt = horizontalSpacingFt,
                    AutoSplitEnabled = autoSplitEnabled,
                    MaxBarLengthFt = autoSplitEnabled ? maxBarLengthFt : 0.0,
                    UseFixedSplitLapLength = useFixedSplitLapLength,
                    FixedSplitLapLengthFt = useFixedSplitLapLength ? fixedSplitLapLengthFt : 0.0,
                    CreateTieBars = createTieBars,
                    TieBarTypeName = createTieBars ? tieBarTypeName : "",
                    TieSpacingXFt = createTieBars ? tieSpacingXFt : 0.0,
                    TieSpacingZFt = createTieBars ? tieSpacingZFt : 0.0
                },
                TopDowels = BuildWallNaviateDowelRequestFromUi(
                    WallNaviateTopDowelCheckBox,
                    WallNaviateTopDowelMode1Toggle,
                    WallNaviateTopDowelMode2Toggle,
                    WallNaviateTopDowelMode3Toggle,
                    verticalBarTypeName,
                    WallNaviateTopDowelBarTypeCombo,
                    WallNaviateTopDowelOverlapCombo),
                LeftDowels = BuildWallNaviateDowelRequestFromUi(
                    WallNaviateLeftDowelCheckBox,
                    WallNaviateLeftDowelMode1Toggle,
                    WallNaviateLeftDowelMode2Toggle,
                    WallNaviateLeftDowelMode3Toggle,
                    horizontalBarTypeName,
                    WallNaviateLeftDowelBarTypeCombo,
                    WallNaviateLeftDowelOverlapCombo),
                RightDowels = BuildWallNaviateDowelRequestFromUi(
                    WallNaviateRightDowelCheckBox,
                    WallNaviateRightDowelMode1Toggle,
                    WallNaviateRightDowelMode2Toggle,
                    WallNaviateRightDowelMode3Toggle,
                    horizontalBarTypeName,
                    WallNaviateRightDowelBarTypeCombo,
                    WallNaviateRightDowelOverlapCombo)
            };

            _handler.Request.WallRebarHostElementIds = hostIds;
            _handler.Request.WallRebarUseNaviateDataModel = true;
            _handler.Request.WallRebarNaviate = nav;
            return true;
        }

        private static int ClampWallNaviateMainBarsOptionIndex(int index)
        {
            if (index <= 0)
            {
                return 0;
            }

            return 1;
        }

        private string GetWallNaviateSettingName()
        {
            string settingName = (GetWallNaviateSelectedComboText(WallNaviateSettingCombo) ?? "").Trim();
            return string.IsNullOrWhiteSpace(settingName) ? "<In Session>" : settingName;
        }

        private bool TryParseWallNaviateMmTextToFeet(string rawText, string label, out double valueFt)
        {
            valueFt = 0.0;
            string raw = (rawText ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                ShowStatus($"WALL: {label} is required.");
                return false;
            }

            if (!TryParseWallNaviateLengthToMm(raw, out double valueMm) || valueMm <= 0.0)
            {
                ShowStatus($"WALL: {label} must be > 0 mm.");
                return false;
            }

            valueFt = MmToFeetUi(valueMm);
            return true;
        }

        private static bool TryParseWallNaviateLengthToMm(string rawText, out double valueMm)
        {
            valueMm = 0.0;
            string raw = (rawText ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            // Accept common UI inputs like: 200, 200 mm, 20cm, 0.2m.
            Match m = Regex.Match(
                raw,
                @"^\s*(?<value>[+-]?\d+(?:[.,]\d+)?)\s*(?<unit>mm|millimeter|millimetre|cm|centimeter|centimetre|m|meter|metre)?\s*$",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            if (!m.Success)
            {
                return false;
            }

            if (!TryParseFlexibleDouble(m.Groups["value"].Value, out double numeric))
            {
                return false;
            }

            string unit = (m.Groups["unit"].Value ?? "").Trim().ToLowerInvariant();
            switch (unit)
            {
                case "m":
                case "meter":
                case "metre":
                    valueMm = numeric * 1000.0;
                    break;
                case "cm":
                case "centimeter":
                case "centimetre":
                    valueMm = numeric * 10.0;
                    break;
                default:
                    valueMm = numeric;
                    break;
            }

            return true;
        }

        private WallNaviateDowelRequest BuildWallNaviateDowelRequestFromUi(
            CheckBox enabledCheckBox,
            System.Windows.Controls.Primitives.ToggleButton mode1,
            System.Windows.Controls.Primitives.ToggleButton mode2,
            System.Windows.Controls.Primitives.ToggleButton mode3,
            string inheritedBarTypeName,
            System.Windows.Controls.ComboBox dowelBarTypeCombo,
            System.Windows.Controls.ComboBox overlapCombo)
        {
            int selectedPatternMode = GetWallNaviateSelectedDowelPatternModeIndex(mode1, mode2, mode3);
            bool useMainBarType = selectedPatternMode <= 0;
            string inherited = (inheritedBarTypeName ?? "").Trim();
            string selected = (GetWallNaviateSelectedComboText(dowelBarTypeCombo) ?? "").Trim();
            if (!useMainBarType && string.IsNullOrWhiteSpace(selected))
            {
                selected = inherited;
            }

            return new WallNaviateDowelRequest
            {
                IsEnabled = enabledCheckBox?.IsChecked == true,
                PatternModeIndex = selectedPatternMode,
                UseMainBarType = useMainBarType,
                BarTypeName = useMainBarType ? inherited : selected,
                OverlapDiameterMultiplier = Math.Max(0, TryParseWallNaviateInt(GetWallNaviateSelectedComboText(overlapCombo), 40))
            };
        }

        private static int GetWallNaviateSelectedDowelPatternModeIndex(
            System.Windows.Controls.Primitives.ToggleButton mode1,
            System.Windows.Controls.Primitives.ToggleButton mode2,
            System.Windows.Controls.Primitives.ToggleButton mode3)
        {
            if (mode2?.IsChecked == true) return 1;
            if (mode3?.IsChecked == true) return 2;
            return 0;
        }

        private void OnFoundationRebarResetClick(object sender, RoutedEventArgs e)
        {
            _foundationRebarUiEventsSuspended = true;
            try
            {
                if (FoundationRebarHostTextBox != null)
                {
                    FoundationRebarHostTextBox.Text = "(not selected)";
                }
                _foundationRebarHostPreview = null;

                if (FoundationRebarScopeCombo != null && FoundationRebarScopeCombo.Items.Count > 0)
                {
                    FoundationRebarScopeCombo.SelectedIndex = 0;
                }

                ApplyFoundationRebarPreset("sync", announce: false);
                if (FoundationRebarParameterTabControl != null)
                {
                    FoundationRebarParameterTabControl.SelectedIndex = 0;
                }
            }
            finally
            {
                _foundationRebarUiEventsSuspended = false;
            }

            SyncFoundationNaviateCloneUiFromLegacyInputs();
            _foundationRebarPreviewDirty = true;
            _foundationRebarPreviewHasRendered = false;
            _foundationRebarLastPreviewUtc = DateTime.MinValue;
            ResetFoundationRebarPreviewCameraState();
            UpdateFoundationRebarDesignUiState();
            RenderFoundationRebarPreviewPlaceholder();
            ShowStatus("FOUNDATION: UI parameters reset to preset defaults for the selected type.");
        }

