        private void ClearFoundationRebarInputs(bool announce)
        {
            bool previousSuspend = _foundationRebarUiEventsSuspended;
            _foundationRebarUiEventsSuspended = true;
            try
            {
                if (FoundationRebarHostTextBox != null)
                {
                    FoundationRebarHostTextBox.Text = "(not selected)";
                }

                _foundationRebarHostPreview = null;

                SetFoundationText(FoundationRebarLengthMmTextBox, "");
                SetFoundationText(FoundationRebarWidthMmTextBox, "");
                SetFoundationText(FoundationRebarThicknessMmTextBox, "");
                SetFoundationText(FoundationRebarPedestalHeightMmTextBox, "");
                SetFoundationText(FoundationRebarPedestalWidthMmTextBox, "");
                SetFoundationText(FoundationRebarPedestalDepthMmTextBox, "");

                // The Naviate clone panel currently hides cover inputs, so keep safe defaults here.
                // Clearing these to blank causes strict validation to fail on Generate ("Top cover must be >= 0 mm").
                SetFoundationText(FoundationRebarTopCoverMmTextBox, "40");
                SetFoundationText(FoundationRebarBottomCoverMmTextBox, "50");
                SetFoundationText(FoundationRebarSideCoverMmTextBox, "50");

                SetFoundationText(FoundationRebarTopSpacingXMmTextBox, "");
                SetFoundationText(FoundationRebarTopSpacingYMmTextBox, "");
                SetFoundationText(FoundationRebarBottomSpacingXMmTextBox, "");
                SetFoundationText(FoundationRebarBottomSpacingYMmTextBox, "");

                SetFoundationText(FoundationRebarTopLapExprTextBox, "");
                SetFoundationText(FoundationRebarBottomLapExprTextBox, "");

                SetFoundationText(FoundationRebarEasyTopShapeCodeTextBox, "");
                SetFoundationText(FoundationRebarEasyBottomShapeCodeTextBox, "");
                SetFoundationText(FoundationRebarEasySideShapeCodeTextBox, "");

                SetFoundationText(FoundationRebarBottomTieSpacingMmTextBox, "");
                SetFoundationText(FoundationRebarMidTieSpacingMmTextBox, "");
                SetFoundationText(FoundationRebarTopTieSpacingMmTextBox, "");
                SetFoundationText(FoundationRebarBottomZoneLengthExprTextBox, "");
                SetFoundationText(FoundationRebarMidZoneLengthExprTextBox, "");
                SetFoundationText(FoundationRebarTopZoneLengthExprTextBox, "");

                SetFoundationText(FoundationRebarStarterMainSpecTextBox, "");
                SetFoundationText(FoundationRebarStarterTieSpecTextBox, "");

                if (FoundationRebarCreateTopBarsCheckBox != null) FoundationRebarCreateTopBarsCheckBox.IsChecked = false;
                if (FoundationRebarCreateBottomBarsCheckBox != null) FoundationRebarCreateBottomBarsCheckBox.IsChecked = false;
                if (FoundationRebarCreateLinksCheckBox != null) FoundationRebarCreateLinksCheckBox.IsChecked = false;
                if (FoundationRebarIncludeStarterBarsCheckBox != null) FoundationRebarIncludeStarterBarsCheckBox.IsChecked = false;
                if (FoundationRebarShowDimensionsCheckBox != null) FoundationRebarShowDimensionsCheckBox.IsChecked = false;
                if (FoundationRebarShowBarMarkersCheckBox != null) FoundationRebarShowBarMarkersCheckBox.IsChecked = false;
            }
            finally
            {
                _foundationRebarUiEventsSuspended = previousSuspend;
            }

            SyncFoundationNaviateCloneUiFromLegacyInputs();
            _foundationRebarPreviewDirty = true;
            _foundationRebarPreviewHasRendered = false;
            _foundationRebarLastPreviewUtc = DateTime.MinValue;
            _foundationNaviateInputUiSnapshot = null;
            ResetFoundationRebarPreviewCameraState();
            RenderFoundationRebarPreviewPlaceholder();

            if (FoundationRebarLiveSummaryText != null)
            {
                FoundationRebarLiveSummaryText.Text = "Foundation input cleared. Pick host and enter new values.";
            }

            if (FoundationRebarValidationHintText != null)
            {
                FoundationRebarValidationHintText.Text = "Tip: Load Defaults to prefill values, or type everything manually in the new Foundation screen.";
                FoundationRebarValidationHintText.Foreground = new SolidColorBrush(WpfColor.FromRgb(122, 90, 0));
            }

            UpdateFoundationRebarDesignUiState();

            if (announce)
            {
                ShowStatus("FOUNDATION: Cleared all Foundation input data.");
            }
        }

