        private void OnFoundationRebarApplyPresetClick(object sender, RoutedEventArgs e)
        {
            var button = sender as System.Windows.Controls.Button;
            string key = (button?.Tag?.ToString() ?? "").Trim();
            if (string.IsNullOrWhiteSpace(key))
            {
                return;
            }

            _foundationRebarUiEventsSuspended = true;
            try
            {
                ApplyFoundationRebarPreset(key, announce: false);
            }
            finally
            {
                _foundationRebarUiEventsSuspended = false;
            }

            SyncFoundationNaviateCloneUiFromLegacyInputs();
            HandleFoundationRebarPreviewInputChanged();
            ShowStatus($"FOUNDATION: Applied preset '{button?.Content ?? key}'.");
        }

        private void HandleFoundationRebarPreviewInputChanged()
        {
            if (_foundationRebarUiEventsSuspended)
            {
                return;
            }

            SyncFoundationRebarShorthandSpecTextBoxesFromCurrentInputs();
            _foundationRebarPreviewDirty = true;
            UpdateFoundationRebarDesignUiState();
        }

        private void UpdateFoundationRebarDesignUiState()
        {
            SyncFoundationRebarShorthandSpecTextBoxesFromCurrentInputs();
            UpdateFoundationNaviateCloneUiState();
            string typeText = GetFoundationRebarComboText(FoundationRebarTypeModeCombo);
            string scopeText = GetFoundationRebarComboText(FoundationRebarScopeCombo);

            if (FoundationRebarWorkflowHintText != null)
            {
                string previewState = _foundationRebarPreviewDirty ? "Preview out of date" :
                    (_foundationRebarPreviewHasRendered ? "Preview current" : "Preview not generated");
                FoundationRebarWorkflowHintText.Text =
                    $"{typeText} | {scopeText} | {previewState} | Dynamic input supports mm / NxL / factor*L";
            }

            if (FoundationRebarUpdatePreviewButton != null)
            {
                FoundationRebarUpdatePreviewButton.Content = _foundationRebarPreviewDirty ? "Update Preview *" : "Update Preview";
            }

            if (FoundationRebarGenerateButton != null)
            {
                FoundationRebarGenerateButton.IsEnabled = true;
            }

            if (FoundationRebarActionHintText != null)
            {
                if (_foundationRebarPreviewHasRendered && _foundationRebarLastPreviewUtc > DateTime.MinValue)
                {
                    FoundationRebarActionHintText.Text =
                        _foundationRebarPreviewDirty
                            ? $"Preview changed after last update ({_foundationRebarLastPreviewUtc:HH:mm:ss}). Click Update Preview."
                            : $"Preview synchronized at {_foundationRebarLastPreviewUtc:HH:mm:ss}.";
                }
                else
                {
                    FoundationRebarActionHintText.Text =
                        "Pick Host, tune parameters, update preview, then generate real rebar on the selected foundation host.";
                }
            }

            if (!TryBuildFoundationRebarPreviewUiData(strictValidation: false, out FoundationRebarPreviewUiData data, out string validationMessage))
            {
                return;
            }

            UpdateFoundationRebarSummaryUi(data, validationMessage);
        }

        private void EnsureFoundationRebarPlaceholderBarTypeItems()
        {
            EnsureFoundationRebarPlaceholderBarTypeItems(FoundationRebarMainBarTypeCombo, new[] { "T16", "T20", "T25", "T32" }, 1);
            EnsureFoundationRebarPlaceholderBarTypeItems(FoundationRebarDistributionBarTypeCombo, new[] { "T10", "T12", "T16", "T20" }, 1);
            EnsureFoundationRebarPlaceholderBarTypeItems(FoundationRebarLinkBarTypeCombo, new[] { "T10", "T12", "T16" }, 0);
        }

        private static void EnsureFoundationRebarPlaceholderBarTypeItems(System.Windows.Controls.ComboBox combo, IEnumerable<string> items, int defaultIndex)
        {
            if (combo == null || combo.Items.Count > 0)
            {
                return;
            }

            combo.ItemsSource = (items ?? Enumerable.Empty<string>()).ToList();
            if (combo.Items.Count > 0)
            {
                combo.SelectedIndex = Math.Max(0, Math.Min(combo.Items.Count - 1, defaultIndex));
            }
        }

        private void ApplyFoundationRebarPreset(string presetKey, bool announce)
        {
            string key = (presetKey ?? "").Trim().ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(key))
            {
                return;
            }

            if (key == "sync")
            {
                bool syncedFromHost = TrySyncFoundationRebarSchematicGeometryFromSelectedHost(announce: false);
                if (!syncedFromHost)
                {
                    ApplyFoundationRebarTypePreset(GetFoundationRebarComboText(FoundationRebarTypeModeCombo));
                    if (announce)
                    {
                        ShowStatus("FOUNDATION: No host selected. Schematic geometry synced from selected foundation type preset.");
                    }
                }
                else if (announce)
                {
                    ShowStatus("FOUNDATION: Schematic geometry synced from selected host geometry.");
                }
                return;
            }

            if (key == "dense")
            {
                SetFoundationText(FoundationRebarTopSpacingXMmTextBox, "125");
                SetFoundationText(FoundationRebarTopSpacingYMmTextBox, "125");
                SetFoundationText(FoundationRebarBottomSpacingXMmTextBox, "125");
                SetFoundationText(FoundationRebarBottomSpacingYMmTextBox, "125");
                SetFoundationText(FoundationRebarBottomTieSpacingMmTextBox, "100");
                SetFoundationText(FoundationRebarMidTieSpacingMmTextBox, "125");
                SetFoundationText(FoundationRebarTopTieSpacingMmTextBox, "100");
                if (FoundationRebarCreateLinksCheckBox != null) FoundationRebarCreateLinksCheckBox.IsChecked = true;
                if (announce) ShowStatus("FOUNDATION: Dense reinforcement preset applied.");
                return;
            }

            if (key == "economy")
            {
                SetFoundationText(FoundationRebarTopSpacingXMmTextBox, "200");
                SetFoundationText(FoundationRebarTopSpacingYMmTextBox, "200");
                SetFoundationText(FoundationRebarBottomSpacingXMmTextBox, "200");
                SetFoundationText(FoundationRebarBottomSpacingYMmTextBox, "200");
                SetFoundationText(FoundationRebarBottomTieSpacingMmTextBox, "150");
                SetFoundationText(FoundationRebarMidTieSpacingMmTextBox, "200");
                SetFoundationText(FoundationRebarTopTieSpacingMmTextBox, "150");
                if (announce) ShowStatus("FOUNDATION: Economy reinforcement preset applied.");
                return;
            }

            if (key == "isolated" || key == "strip" || key == "pilecap" || key == "raft")
            {
                if (FoundationRebarTypeModeCombo != null)
                {
                    switch (key)
                    {
                        case "isolated":
                            SetFoundationComboSelectionByText(FoundationRebarTypeModeCombo, "Isolated Footing");
                            break;
                        case "strip":
                            SetFoundationComboSelectionByText(FoundationRebarTypeModeCombo, "Strip Footing");
                            break;
                        case "pilecap":
                            SetFoundationComboSelectionByText(FoundationRebarTypeModeCombo, "Pile Cap");
                            break;
                        case "raft":
                            SetFoundationComboSelectionByText(FoundationRebarTypeModeCombo, "Raft / Mat");
                            break;
                    }
                }

                ApplyFoundationRebarTypePreset(GetFoundationRebarComboText(FoundationRebarTypeModeCombo));
                if (announce)
                {
                    ShowStatus($"FOUNDATION: {key} preset applied.");
                }
            }
        }

        private void ApplyFoundationRebarTypePreset(string typeText)
        {
            string normalized = (typeText ?? "").Trim().ToLowerInvariant();

            if (normalized.Contains("strip"))
            {
                SetFoundationText(FoundationRebarLengthMmTextBox, "4500");
                SetFoundationText(FoundationRebarWidthMmTextBox, "1200");
                SetFoundationText(FoundationRebarThicknessMmTextBox, "500");
                SetFoundationText(FoundationRebarPedestalHeightMmTextBox, "450");
                SetFoundationText(FoundationRebarPedestalWidthMmTextBox, "400");
                SetFoundationText(FoundationRebarPedestalDepthMmTextBox, "800");
            }
            else if (normalized.Contains("pile"))
            {
                SetFoundationText(FoundationRebarLengthMmTextBox, "3200");
                SetFoundationText(FoundationRebarWidthMmTextBox, "2800");
                SetFoundationText(FoundationRebarThicknessMmTextBox, "900");
                SetFoundationText(FoundationRebarPedestalHeightMmTextBox, "900");
                SetFoundationText(FoundationRebarPedestalWidthMmTextBox, "900");
                SetFoundationText(FoundationRebarPedestalDepthMmTextBox, "900");
            }
            else if (normalized.Contains("raft") || normalized.Contains("mat"))
            {
                SetFoundationText(FoundationRebarLengthMmTextBox, "6000");
                SetFoundationText(FoundationRebarWidthMmTextBox, "5000");
                SetFoundationText(FoundationRebarThicknessMmTextBox, "700");
                SetFoundationText(FoundationRebarPedestalHeightMmTextBox, "0");
                SetFoundationText(FoundationRebarPedestalWidthMmTextBox, "800");
                SetFoundationText(FoundationRebarPedestalDepthMmTextBox, "800");
            }
            else
            {
                SetFoundationText(FoundationRebarLengthMmTextBox, "2500");
                SetFoundationText(FoundationRebarWidthMmTextBox, "2500");
                SetFoundationText(FoundationRebarThicknessMmTextBox, "600");
                SetFoundationText(FoundationRebarPedestalHeightMmTextBox, "500");
                SetFoundationText(FoundationRebarPedestalWidthMmTextBox, "600");
                SetFoundationText(FoundationRebarPedestalDepthMmTextBox, "600");
            }

            SetFoundationText(FoundationRebarTopCoverMmTextBox, "40");
            SetFoundationText(FoundationRebarBottomCoverMmTextBox, "50");
            SetFoundationText(FoundationRebarSideCoverMmTextBox, "50");
            SetFoundationText(FoundationRebarTopSpacingXMmTextBox, "150");
            SetFoundationText(FoundationRebarTopSpacingYMmTextBox, "150");
            SetFoundationText(FoundationRebarBottomSpacingXMmTextBox, "150");
            SetFoundationText(FoundationRebarBottomSpacingYMmTextBox, "150");
            SetFoundationText(FoundationRebarBottomTieSpacingMmTextBox, "100");
            SetFoundationText(FoundationRebarMidTieSpacingMmTextBox, "150");
            SetFoundationText(FoundationRebarTopTieSpacingMmTextBox, "100");
            SetFoundationText(FoundationRebarTopLapExprTextBox, "0");
            SetFoundationText(FoundationRebarBottomLapExprTextBox, "0");
            SetFoundationText(FoundationRebarBottomZoneLengthExprTextBox, "0");
            SetFoundationText(FoundationRebarMidZoneLengthExprTextBox, "0");
            SetFoundationText(FoundationRebarTopZoneLengthExprTextBox, "0");

            if (FoundationRebarIncludeStarterBarsCheckBox != null)
            {
                FoundationRebarIncludeStarterBarsCheckBox.IsChecked = !normalized.Contains("raft") && !normalized.Contains("mat");
            }

            if (FoundationRebarCreateLinksCheckBox != null) FoundationRebarCreateLinksCheckBox.IsChecked = true;
            if (FoundationRebarCreateTopBarsCheckBox != null) FoundationRebarCreateTopBarsCheckBox.IsChecked = true;
            if (FoundationRebarCreateBottomBarsCheckBox != null) FoundationRebarCreateBottomBarsCheckBox.IsChecked = true;
            if (FoundationRebarShowDimensionsCheckBox != null) FoundationRebarShowDimensionsCheckBox.IsChecked = true;
            if (FoundationRebarShowBarMarkersCheckBox != null) FoundationRebarShowBarMarkersCheckBox.IsChecked = true;
        }

        private bool TrySyncFoundationRebarSchematicGeometryFromSelectedHost(bool announce)
        {
            if (_foundationRebarHostPreview == null || _foundationRebarHostPreview.HostElementId == ElementId.InvalidElementId)
            {
                return false;
            }

            if (!string.IsNullOrWhiteSpace(_foundationRebarHostPreview.SuggestedTypeMode))
            {
                SetFoundationComboSelectionByText(FoundationRebarTypeModeCombo, _foundationRebarHostPreview.SuggestedTypeMode);
            }

            double lengthMm = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.LengthFt));
            double widthMm = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.WidthFt));
            double thicknessMm = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.ThicknessFt));

            SetFoundationText(FoundationRebarLengthMmTextBox, lengthMm.ToString("0.#", CultureInfo.InvariantCulture));
            SetFoundationText(FoundationRebarWidthMmTextBox, widthMm.ToString("0.#", CultureInfo.InvariantCulture));
            SetFoundationText(FoundationRebarThicknessMmTextBox, thicknessMm.ToString("0.#", CultureInfo.InvariantCulture));
            SyncFoundationRebarPedestalFootprintFromDetectedColumn();

            if (announce)
            {
                string columnSuffix = "";
                if (_foundationRebarHostPreview.DetectedColumnElementId != ElementId.InvalidElementId &&
                    _foundationRebarHostPreview.DetectedColumnWidthFt > 1e-9 &&
                    _foundationRebarHostPreview.DetectedColumnDepthFt > 1e-9)
                {
                    columnSuffix =
                        $" Detected column {_foundationRebarHostPreview.DetectedColumnElementId.Value} " +
                        $"({FeetToMmUi(_foundationRebarHostPreview.DetectedColumnWidthFt):0.#}x{FeetToMmUi(_foundationRebarHostPreview.DetectedColumnDepthFt):0.#} mm).";
                }

                ShowStatus(
                    $"FOUNDATION: Synced preview geometry from host {_foundationRebarHostPreview.HostElementId.Value} " +
                    $"({lengthMm:0.#}x{widthMm:0.#}x{thicknessMm:0.#} mm).{columnSuffix}");
            }

            return true;
        }

        private static void SetFoundationText(System.Windows.Controls.TextBox textBox, string value)
        {
            if (textBox == null)
            {
                return;
            }

            if (!string.Equals(textBox.Text ?? "", value ?? "", StringComparison.Ordinal))
            {
                textBox.Text = value ?? "";
            }
        }

        private bool SyncFoundationRebarPedestalFootprintFromDetectedColumn()
        {
            if (_foundationRebarHostPreview == null ||
                _foundationRebarHostPreview.DetectedColumnElementId == ElementId.InvalidElementId)
            {
                return false;
            }

            double pedWidthMm = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.DetectedColumnWidthFt));
            double pedDepthMm = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.DetectedColumnDepthFt));
            if (pedWidthMm <= 0.0 || pedDepthMm <= 0.0)
            {
                return false;
            }

            SetFoundationText(FoundationRebarPedestalWidthMmTextBox, pedWidthMm.ToString("0.#", CultureInfo.InvariantCulture));
            SetFoundationText(FoundationRebarPedestalDepthMmTextBox, pedDepthMm.ToString("0.#", CultureInfo.InvariantCulture));
            return true;
        }

        private void SyncFoundationRebarShorthandSpecTextBoxesFromCurrentInputs()
        {
            if (_foundationRebarShorthandSyncInProgress)
            {
                return;
            }

            _foundationRebarShorthandSyncInProgress = true;
            try
            {
                SetFoundationText(
                    FoundationRebarTopXSpecTextBox,
                    BuildFoundationRebarShorthandSpecText(FoundationRebarMainBarTypeCombo, FoundationRebarTopSpacingXMmTextBox));
                SetFoundationText(
                    FoundationRebarTopYSpecTextBox,
                    BuildFoundationRebarShorthandSpecText(FoundationRebarDistributionBarTypeCombo, FoundationRebarTopSpacingYMmTextBox));
                SetFoundationText(
                    FoundationRebarBottomXSpecTextBox,
                    BuildFoundationRebarShorthandSpecText(FoundationRebarMainBarTypeCombo, FoundationRebarBottomSpacingXMmTextBox));
                SetFoundationText(
                    FoundationRebarBottomYSpecTextBox,
                    BuildFoundationRebarShorthandSpecText(FoundationRebarDistributionBarTypeCombo, FoundationRebarBottomSpacingYMmTextBox));
            }
            finally
            {
                _foundationRebarShorthandSyncInProgress = false;
            }
        }

        private static string BuildFoundationRebarShorthandSpecText(
            System.Windows.Controls.ComboBox barTypeCombo,
            System.Windows.Controls.TextBox spacingTextBox)
        {
            string barType = (GetFoundationRebarComboText(barTypeCombo) ?? "").Trim();
            string spacingRaw = (spacingTextBox?.Text ?? "").Trim();
            if (string.IsNullOrWhiteSpace(barType) && string.IsNullOrWhiteSpace(spacingRaw))
            {
                return "";
            }

            if (!TryParseFlexibleDouble(spacingRaw, out double spacingMm) || spacingMm <= 0.0)
            {
                if (string.IsNullOrWhiteSpace(barType))
                {
                    return spacingRaw;
                }

                return string.IsNullOrWhiteSpace(spacingRaw) ? barType : $"{barType}@{spacingRaw}";
            }

            return string.IsNullOrWhiteSpace(barType)
                ? spacingMm.ToString("0.###", CultureInfo.InvariantCulture)
                : $"{barType}@{spacingMm.ToString("0.###", CultureInfo.InvariantCulture)}";
        }

        private bool TryApplyFoundationRebarShorthandSpecFromTextBox(System.Windows.Controls.TextBox specTextBox, bool showStatusOnFailure)
        {
            if (specTextBox == null)
            {
                return false;
            }

            string raw = (specTextBox.Text ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            if (!TryResolveFoundationRebarShorthandTargets(
                specTextBox,
                out System.Windows.Controls.ComboBox barTypeCombo,
                out System.Windows.Controls.TextBox spacingTextBox))
            {
                return false;
            }

            if (!TryParseFoundationRebarShorthandSpec(raw, out string barToken, out double spacingMm))
            {
                if (!TryParseFoundationRebarCountBarSpec(raw, out int barCount, out string countBarToken) ||
                    !TryGetFoundationRebarShorthandAxisInputs(specTextBox, out double dimensionMm, out double coverMm) ||
                    !TryConvertFoundationRebarBarCountToSpacingMm(barCount, dimensionMm, coverMm, out spacingMm))
                {
                    if (showStatusOnFailure)
                    {
                        ShowStatus("FOUNDATION: rebar spec must be DiaxSpacing (DB25x150 / DB25@150) or No.xDia (15xDB25 / 15DB25).");
                    }

                    return false;
                }

                barToken = countBarToken;
            }

            bool previousSuspend = _foundationRebarUiEventsSuspended;
            bool changed = false;
            _foundationRebarUiEventsSuspended = true;
            try
            {
                string beforeBar = GetFoundationRebarComboText(barTypeCombo);
                if (!TrySelectFoundationBarTypeComboByToken(barTypeCombo, barToken))
                {
                    if (showStatusOnFailure)
                    {
                        ShowStatus($"FOUNDATION: bar type '{barToken}' not found in rebar type list.");
                    }

                    return false;
                }

                string afterBar = GetFoundationRebarComboText(barTypeCombo);
                changed |= !string.Equals(beforeBar ?? "", afterBar ?? "", StringComparison.Ordinal);

                string spacingText = spacingMm.ToString("0.###", CultureInfo.InvariantCulture);
                if (spacingTextBox != null && !string.Equals(spacingTextBox.Text ?? "", spacingText, StringComparison.Ordinal))
                {
                    spacingTextBox.Text = spacingText;
                    changed = true;
                }
            }
            finally
            {
                _foundationRebarUiEventsSuspended = previousSuspend;
            }

            SyncFoundationRebarShorthandSpecTextBoxesFromCurrentInputs();
            return changed;
        }

        private bool TryResolveFoundationRebarShorthandTargets(
            System.Windows.Controls.TextBox specTextBox,
            out System.Windows.Controls.ComboBox barTypeCombo,
            out System.Windows.Controls.TextBox spacingTextBox)
        {
            barTypeCombo = null;
            spacingTextBox = null;

            if (ReferenceEquals(specTextBox, FoundationRebarTopXSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyTopXSpecTextBox))
            {
                barTypeCombo = FoundationRebarMainBarTypeCombo;
                spacingTextBox = FoundationRebarTopSpacingXMmTextBox;
                return true;
            }

            if (ReferenceEquals(specTextBox, FoundationRebarTopYSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyTopYSpecTextBox))
            {
                barTypeCombo = FoundationRebarDistributionBarTypeCombo;
                spacingTextBox = FoundationRebarTopSpacingYMmTextBox;
                return true;
            }

            if (ReferenceEquals(specTextBox, FoundationRebarBottomXSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyBottomXSpecTextBox))
            {
                barTypeCombo = FoundationRebarMainBarTypeCombo;
                spacingTextBox = FoundationRebarBottomSpacingXMmTextBox;
                return true;
            }

            if (ReferenceEquals(specTextBox, FoundationRebarBottomYSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyBottomYSpecTextBox))
            {
                barTypeCombo = FoundationRebarDistributionBarTypeCombo;
                spacingTextBox = FoundationRebarBottomSpacingYMmTextBox;
                return true;
            }

            return false;
        }

        private static bool TryParseFoundationRebarShorthandSpec(string text, out string barToken, out double spacingMm)
        {
            barToken = "";
            spacingMm = 0.0;

            string raw = (text ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            Match match = Regex.Match(
                raw,
                @"^\s*(?<bar>[A-Za-z][A-Za-z0-9\.\-]*)\s*(?:@|[xX])\s*(?<spacing>[0-9]+(?:[\.,][0-9]+)?)\s*$",
                RegexOptions.CultureInvariant);
            if (match.Success)
            {
                string bar = (match.Groups["bar"].Value ?? "").Trim();
                string spacing = (match.Groups["spacing"].Value ?? "").Trim();
                if (!string.IsNullOrWhiteSpace(bar) &&
                    TryParseFlexibleDouble(spacing, out spacingMm) &&
                    spacingMm > 0.0)
                {
                    barToken = bar;
                    return true;
                }
            }

            int atIndex = raw.IndexOf('@');
            if (atIndex <= 0 || atIndex >= raw.Length - 1)
            {
                return false;
            }

            string left = raw.Substring(0, atIndex).Trim();
            string right = raw.Substring(atIndex + 1).Trim();
            if (string.IsNullOrWhiteSpace(left) || string.IsNullOrWhiteSpace(right))
            {
                return false;
            }

            if (!TryParseFlexibleDouble(right, out spacingMm) || spacingMm <= 0.0)
            {
                return false;
            }

            barToken = left;
            return true;
        }

        private bool TryGetFoundationRebarShorthandAxisInputs(
            System.Windows.Controls.TextBox specTextBox,
            out double dimensionMm,
            out double coverMm)
        {
            dimensionMm = 0.0;
            coverMm = 0.0;

            double lengthMm = TryParseFlexibleDouble((FoundationRebarLengthMmTextBox?.Text ?? "").Trim(), out double parsedLengthMm)
                ? parsedLengthMm
                : 2500.0;
            double widthMm = TryParseFlexibleDouble((FoundationRebarWidthMmTextBox?.Text ?? "").Trim(), out double parsedWidthMm)
                ? parsedWidthMm
                : 2500.0;
            coverMm = TryParseFlexibleDouble((FoundationRebarSideCoverMmTextBox?.Text ?? "").Trim(), out double parsedCoverMm)
                ? Math.Max(0.0, parsedCoverMm)
                : 50.0;

            if (ReferenceEquals(specTextBox, FoundationRebarTopXSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyTopXSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarBottomXSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyBottomXSpecTextBox))
            {
                dimensionMm = Math.Max(0.0, widthMm);
                return true;
            }

            if (ReferenceEquals(specTextBox, FoundationRebarTopYSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyTopYSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarBottomYSpecTextBox) ||
                ReferenceEquals(specTextBox, FoundationRebarEasyBottomYSpecTextBox))
            {
                dimensionMm = Math.Max(0.0, lengthMm);
                return true;
            }

            return false;
        }

        private static bool TryParseFoundationRebarCountBarSpec(string text, out int barCount, out string barToken)
        {
            barCount = 0;
            barToken = "";

            string raw = (text ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            Match match = Regex.Match(
                raw,
                @"^\s*(?:(?:N[Oº°\.]*)\s*)?(?<count>\d+)\s*(?:[xX\*]\s*)?(?<bar>[A-Za-z][A-Za-z0-9\.\-]*)\s*$",
                RegexOptions.CultureInvariant);
            if (!match.Success)
            {
                return false;
            }

            if (!int.TryParse(match.Groups["count"].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out barCount))
            {
                return false;
            }

            if (barCount < 2)
            {
                return false;
            }

            barToken = (match.Groups["bar"].Value ?? "").Trim();
            return !string.IsNullOrWhiteSpace(barToken);
        }

        private static bool TryConvertFoundationRebarBarCountToSpacingMm(
            int barCount,
            double dimensionMm,
            double coverMm,
            out double spacingMm)
        {
            spacingMm = 0.0;
            if (barCount < 2 || dimensionMm <= 0.0)
            {
                return false;
            }

            double usableMm = Math.Max(0.0, dimensionMm - (2.0 * Math.Max(0.0, coverMm)));
            if (usableMm <= 1.0)
            {
                return false;
            }

            spacingMm = usableMm / Math.Max(1, barCount - 1);
            return spacingMm > 0.0 && !double.IsNaN(spacingMm) && !double.IsInfinity(spacingMm);
        }

        private static bool TrySelectFoundationBarTypeComboByToken(System.Windows.Controls.ComboBox combo, string barToken)
        {
            if (combo == null || string.IsNullOrWhiteSpace(barToken))
            {
                return false;
            }

            string token = (barToken ?? "").Trim();
            string normalizedToken = NormalizeFoundationBarTypeToken(token);
            string tokenDigits = new string(token.Where(char.IsDigit).ToArray());
            object bestMatch = null;
            int bestScore = int.MaxValue;

            foreach (object item in combo.Items)
            {
                string itemText = item is System.Windows.Controls.ComboBoxItem cbi
                    ? (cbi.Content?.ToString() ?? "")
                    : item is ComboItem ci
                        ? (ci.Name ?? "")
                        : (item?.ToString() ?? "");
                string trimmed = (itemText ?? "").Trim();
                if (string.IsNullOrWhiteSpace(trimmed))
                {
                    continue;
                }

                if (string.Equals(trimmed, token, StringComparison.OrdinalIgnoreCase))
                {
                    combo.SelectedItem = item;
                    return true;
                }

                string normalizedItem = NormalizeFoundationBarTypeToken(trimmed);
                if (!string.IsNullOrWhiteSpace(normalizedToken))
                {
                    if (string.Equals(normalizedItem, normalizedToken, StringComparison.OrdinalIgnoreCase))
                    {
                        combo.SelectedItem = item;
                        return true;
                    }

                    if (normalizedItem.IndexOf(normalizedToken, StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        int score = Math.Max(0, normalizedItem.Length - normalizedToken.Length);
                        if (score < bestScore)
                        {
                            bestScore = score;
                            bestMatch = item;
                        }
                    }
                }

                if (!string.IsNullOrWhiteSpace(tokenDigits))
                {
                    string itemDigits = new string(trimmed.Where(char.IsDigit).ToArray());
                    if (!string.IsNullOrWhiteSpace(itemDigits) &&
                        string.Equals(itemDigits, tokenDigits, StringComparison.OrdinalIgnoreCase))
                    {
                        int score = 100 + Math.Abs(trimmed.Length - token.Length);
                        if (score < bestScore)
                        {
                            bestScore = score;
                            bestMatch = item;
                        }
                    }
                }
            }

            if (bestMatch != null)
            {
                combo.SelectedItem = bestMatch;
                return true;
            }

            return false;
        }

        private static string NormalizeFoundationBarTypeToken(string text)
        {
            string raw = (text ?? "").Trim().ToUpperInvariant();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return "";
            }

            var sb = new StringBuilder(raw.Length);
            foreach (char ch in raw)
            {
                if (char.IsLetterOrDigit(ch))
                {
                    sb.Append(ch);
                }
            }

            return sb.ToString();
        }

        private static string GetFoundationRebarComboText(System.Windows.Controls.ComboBox combo)
        {
            if (combo == null)
            {
                return "";
            }

            if (combo.SelectedItem is System.Windows.Controls.ComboBoxItem comboBoxItem)
            {
                return comboBoxItem.Content?.ToString() ?? "";
            }

            if (combo.SelectedItem is ComboItem comboItem)
            {
                return comboItem.Name ?? "";
            }

            return combo.SelectedItem?.ToString() ?? combo.Text ?? "";
        }

        private static void SetFoundationComboSelectionByText(System.Windows.Controls.ComboBox combo, string targetText)
        {
            if (combo == null || string.IsNullOrWhiteSpace(targetText))
            {
                return;
            }

            foreach (object item in combo.Items)
            {
                string text = item is System.Windows.Controls.ComboBoxItem cbi
                    ? (cbi.Content?.ToString() ?? "")
                    : item is ComboItem ci
                        ? (ci.Name ?? "")
                        : (item?.ToString() ?? "");

                if (string.Equals(text, targetText, StringComparison.OrdinalIgnoreCase))
                {
                    combo.SelectedItem = item;
                    return;
                }
            }
        }

        private bool TryBuildFoundationRebarPreviewUiData(bool strictValidation, out FoundationRebarPreviewUiData data, out string validationMessage)
        {
            data = null;
            validationMessage = "";

            if (FoundationRebarLengthMmTextBox == null)
            {
                return false;
            }

            var errors = new List<string>();
            var warnings = new List<string>();

            double ReadMm(System.Windows.Controls.TextBox box, string label, double fallback, double minValue, bool strict = true)
            {
                string raw = (box?.Text ?? "").Trim();
                if (TryParseFlexibleDouble(raw, out double parsed) && parsed >= minValue)
                {
                    return parsed;
                }

                string message = $"{label} must be >= {minValue:0.#} mm.";
                if (strictValidation && strict)
                {
                    errors.Add(message);
                }
                else
                {
                    warnings.Add(message + $" Using {fallback:0.#}.");
                }

                return fallback;
            }

            string ReadText(System.Windows.Controls.TextBox box, string fallback)
            {
                string raw = (box?.Text ?? "").Trim();
                return string.IsNullOrWhiteSpace(raw) ? (fallback ?? "") : raw;
            }

            data = new FoundationRebarPreviewUiData
            {
                HostText = FoundationRebarHostTextBox?.Text ?? "",
                TypeMode = GetFoundationRebarComboText(FoundationRebarTypeModeCombo),
                ScopeMode = GetFoundationRebarComboText(FoundationRebarScopeCombo),
                MainBarType = GetFoundationRebarComboText(FoundationRebarMainBarTypeCombo),
                DistributionBarType = GetFoundationRebarComboText(FoundationRebarDistributionBarTypeCombo),
                LinkBarType = GetFoundationRebarComboText(FoundationRebarLinkBarTypeCombo),
                LengthMm = ReadMm(FoundationRebarLengthMmTextBox, "Length", 2500, 200),
                WidthMm = ReadMm(FoundationRebarWidthMmTextBox, "Width", 2500, 200),
                ThicknessMm = ReadMm(FoundationRebarThicknessMmTextBox, "Thickness", 600, 150),
                PedestalHeightMm = ReadMm(FoundationRebarPedestalHeightMmTextBox, "Pedestal height", 0, 0, strict: false),
                PedestalWidthMm = ReadMm(FoundationRebarPedestalWidthMmTextBox, "Pedestal width", 600, 0, strict: false),
                PedestalDepthMm = ReadMm(FoundationRebarPedestalDepthMmTextBox, "Pedestal depth", 600, 0, strict: false),
                TopCoverMm = ReadMm(FoundationRebarTopCoverMmTextBox, "Top cover", 40, 0),
                BottomCoverMm = ReadMm(FoundationRebarBottomCoverMmTextBox, "Bottom cover", 50, 0),
                SideCoverMm = ReadMm(FoundationRebarSideCoverMmTextBox, "Side cover", 50, 0),
                TopSpacingXMm = ReadMm(FoundationRebarTopSpacingXMmTextBox, "Top X spacing", 150, 1),
                TopSpacingYMm = ReadMm(FoundationRebarTopSpacingYMmTextBox, "Top Y spacing", 150, 1),
                BottomSpacingXMm = ReadMm(FoundationRebarBottomSpacingXMmTextBox, "Bottom X spacing", 150, 1),
                BottomSpacingYMm = ReadMm(FoundationRebarBottomSpacingYMmTextBox, "Bottom Y spacing", 150, 1),
                BottomTieSpacingMm = ReadMm(FoundationRebarBottomTieSpacingMmTextBox, "Bottom tie spacing", 100, 1),
                MidTieSpacingMm = ReadMm(FoundationRebarMidTieSpacingMmTextBox, "Mid tie spacing", 150, 1),
                TopTieSpacingMm = ReadMm(FoundationRebarTopTieSpacingMmTextBox, "Top tie spacing", 100, 1),
                TopLapExpr = ReadText(FoundationRebarTopLapExprTextBox, "0"),
                BottomLapExpr = ReadText(FoundationRebarBottomLapExprTextBox, "0"),
                BottomZoneExpr = ReadText(FoundationRebarBottomZoneLengthExprTextBox, "0"),
                MidZoneExpr = ReadText(FoundationRebarMidZoneLengthExprTextBox, "0"),
                TopZoneExpr = ReadText(FoundationRebarTopZoneLengthExprTextBox, "0"),
                IncludeStarterBars = FoundationRebarIncludeStarterBarsCheckBox?.IsChecked == true,
                CreateLinks = FoundationRebarCreateLinksCheckBox?.IsChecked == true,
                CreateTopBars = FoundationRebarCreateTopBarsCheckBox?.IsChecked == true,
                CreateBottomBars = FoundationRebarCreateBottomBarsCheckBox?.IsChecked == true,
                ShowDimensions = FoundationRebarShowDimensionsCheckBox?.IsChecked == true,
                ShowBarMarkers = FoundationRebarShowBarMarkersCheckBox?.IsChecked == true
            };

            bool easyTabSelected = ReferenceEquals(FoundationRebarParameterTabControl?.SelectedItem, FoundationRebarEasyParameterTabItem);
            bool newDesignerVisible = FoundationRebarNewDesignerRoot?.Visibility == System.Windows.Visibility.Visible;
            if (easyTabSelected && !newDesignerVisible)
            {
                // Easy mode intentionally uses one tie spacing field for all side-bar zones.
                data.BottomTieSpacingMm = data.MidTieSpacingMm;
                data.TopTieSpacingMm = data.MidTieSpacingMm;
                data.CreateLinks = false;
            }

            if (data.TopCoverMm + data.BottomCoverMm >= data.ThicknessMm - 1.0)
            {
                (strictValidation ? errors : warnings).Add("Top cover + bottom cover must be smaller than thickness.");
            }

            if ((data.SideCoverMm * 2.0) >= Math.Min(data.LengthMm, data.WidthMm) - 1.0)
            {
                (strictValidation ? errors : warnings).Add("Side cover is too large for the selected L/B dimensions.");
            }

            data.EstimatedTopBarsX = data.CreateTopBars ? EstimateFoundationRebarBarCount(data.WidthMm, data.SideCoverMm, data.TopSpacingXMm) : 0;
            data.EstimatedTopBarsY = data.CreateTopBars ? EstimateFoundationRebarBarCount(data.LengthMm, data.SideCoverMm, data.TopSpacingYMm) : 0;
            data.EstimatedBottomBarsX = data.CreateBottomBars ? EstimateFoundationRebarBarCount(data.WidthMm, data.SideCoverMm, data.BottomSpacingXMm) : 0;
            data.EstimatedBottomBarsY = data.CreateBottomBars ? EstimateFoundationRebarBarCount(data.LengthMm, data.SideCoverMm, data.BottomSpacingYMm) : 0;

            if (data.CreateLinks)
            {
                double effectiveDepthMm = Math.Max(0.0, data.ThicknessMm - data.TopCoverMm - data.BottomCoverMm);
                double avgTieSpacingMm = Math.Max(1.0, (data.BottomTieSpacingMm + data.MidTieSpacingMm + data.TopTieSpacingMm) / 3.0);
                data.EstimatedTieLevels = Math.Max(1, (int)Math.Floor(effectiveDepthMm / avgTieSpacingMm) + 1);
            }
            else
            {
                data.EstimatedTieLevels = 0;
            }

            if (errors.Count > 0)
            {
                validationMessage = errors[0];
                return !strictValidation;
            }

            validationMessage = warnings.Count > 0 ? warnings[0] : "";
            return true;
        }

        private static int EstimateFoundationRebarBarCount(double dimensionMm, double coverMm, double spacingMm)
        {
            if (dimensionMm <= 0.0 || spacingMm <= 0.0)
            {
                return 0;
            }

            double usableMm = Math.Max(0.0, dimensionMm - (2.0 * Math.Max(0.0, coverMm)));
            if (usableMm <= 1.0)
            {
                return 0;
            }

            return Math.Max(2, (int)Math.Floor(usableMm / spacingMm) + 1);
        }

        private static FoundationNaviateUiQuantityInputMode InferFoundationNaviateQuantityMode(
            string xDirectionSpec,
            string yDirectionSpec,
            out int inferredBars)
        {
            inferredBars = 0;

            if (TryParseFoundationRebarCountBarSpec(xDirectionSpec, out int xBars, out _))
            {
                inferredBars = xBars;
                return FoundationNaviateUiQuantityInputMode.NumberOfBars;
            }

            if (TryParseFoundationRebarCountBarSpec(yDirectionSpec, out int yBars, out _))
            {
                inferredBars = yBars;
                return FoundationNaviateUiQuantityInputMode.NumberOfBars;
            }

            return FoundationNaviateUiQuantityInputMode.Spacing;
        }

        private FoundationNaviateInputUiData BuildFoundationNaviateInputUiDataFromCurrentUi(FoundationRebarPreviewUiData legacyData)
        {
            var naviate = new FoundationNaviateInputUiData();
            if (legacyData == null)
            {
                return naviate;
            }

            string topXSpec = (FoundationRebarTopXSpecTextBox?.Text ?? "").Trim();
            string topYSpec = (FoundationRebarTopYSpecTextBox?.Text ?? "").Trim();
            string btmXSpec = (FoundationRebarBottomXSpecTextBox?.Text ?? "").Trim();
            string btmYSpec = (FoundationRebarBottomYSpecTextBox?.Text ?? "").Trim();
            string topShapeCode = (FoundationRebarEasyTopShapeCodeTextBox?.Text ?? "21").Trim();
            string bottomShapeCode = (FoundationRebarEasyBottomShapeCodeTextBox?.Text ?? "21").Trim();
            string sideShapeCode = (FoundationRebarEasySideShapeCodeTextBox?.Text ?? "21").Trim();
            string starterMainSpec = (FoundationRebarStarterMainSpecTextBox?.Text ?? "").Trim();
            string starterTieSpec = (FoundationRebarStarterTieSpecTextBox?.Text ?? "").Trim();

            bool topHasLap = TryParseFoundationRebarLengthExpressionMm(legacyData.TopLapExpr, Math.Max(1.0, legacyData.LengthMm), out double topLapMm) && topLapMm > 0.0;
            bool bottomHasLap = TryParseFoundationRebarLengthExpressionMm(legacyData.BottomLapExpr, Math.Max(1.0, legacyData.LengthMm), out double bottomLapMm) && bottomLapMm > 0.0;

            FoundationNaviateUiQuantityInputMode topMode = InferFoundationNaviateQuantityMode(topXSpec, topYSpec, out int topBars);
            FoundationNaviateUiQuantityInputMode bottomMode = InferFoundationNaviateQuantityMode(btmXSpec, btmYSpec, out int bottomBars);

            naviate.SettingName = "<In Session>";
            naviate.FollowPickedHostGeometry = true;
            naviate.DeleteExistingRebar = true;
            naviate.ShowDimensionsInPreview = legacyData.ShowDimensions;
            naviate.ShowBarMarkersInPreview = legacyData.ShowBarMarkers;
            naviate.TopCoverMm = legacyData.TopCoverMm;
            naviate.BottomCoverMm = legacyData.BottomCoverMm;
            naviate.SideCoverMm = legacyData.SideCoverMm;

            naviate.TopBars = new FoundationNaviateLayerUiData
            {
                LayerKey = FoundationNaviateUiLayerKey.Top,
                PanelTitle = "Top Rebar",
                IsEnabled = legacyData.CreateTopBars,
                MainLayerDirection = FoundationNaviateUiMainLayerDirection.LongitudinalBars,
                ReinforcementDisplayMode = topHasLap ? FoundationNaviateUiReinforcementDisplayMode.LapLength : FoundationNaviateUiReinforcementDisplayMode.Continuous,
                ReinforcementDisplayImagePath = topHasLap
                    ? naviate.Images.LapLengthReinforcementImage.RelativePath
                    : naviate.Images.ContinuousReinforcementImage.RelativePath,
                LayerReinforcementImagePath = naviate.Images.TopReinforcementImage.RelativePath,
                OverlapInputMode = FoundationNaviateUiOverlapInputMode.LengthMm,
                OverlapLengthMm = topHasLap ? topLapMm : 0.0,
                OverlapDiameterMultiplier = 40,
                BarType = legacyData.MainBarType,
                ShapeCode = string.IsNullOrWhiteSpace(topShapeCode) ? "21" : topShapeCode,
                QuantityInputMode = topMode,
                NumberOfBars = topBars > 0 ? topBars : Math.Max(2, legacyData.EstimatedTopBarsX),
                SpacingMm = legacyData.TopSpacingXMm,
                XDirectionSpec = topXSpec,
                YDirectionSpec = topYSpec,
                XSpacingMm = legacyData.TopSpacingXMm,
                YSpacingMm = legacyData.TopSpacingYMm,
                LapLengthExpr = legacyData.TopLapExpr ?? "0"
            };

            naviate.BottomBars = new FoundationNaviateLayerUiData
            {
                LayerKey = FoundationNaviateUiLayerKey.Bottom,
                PanelTitle = "Bottom Rebar",
                IsEnabled = legacyData.CreateBottomBars,
                MainLayerDirection = FoundationNaviateUiMainLayerDirection.LongitudinalBars,
                ReinforcementDisplayMode = bottomHasLap ? FoundationNaviateUiReinforcementDisplayMode.LapLength : FoundationNaviateUiReinforcementDisplayMode.Continuous,
                ReinforcementDisplayImagePath = bottomHasLap
                    ? naviate.Images.LapLengthReinforcementImage.RelativePath
                    : naviate.Images.ContinuousReinforcementImage.RelativePath,
                LayerReinforcementImagePath = naviate.Images.BottomReinforcementImage.RelativePath,
                OverlapInputMode = FoundationNaviateUiOverlapInputMode.LengthMm,
                OverlapLengthMm = bottomHasLap ? bottomLapMm : 0.0,
                OverlapDiameterMultiplier = 40,
                BarType = legacyData.MainBarType,
                ShapeCode = string.IsNullOrWhiteSpace(bottomShapeCode) ? "21" : bottomShapeCode,
                QuantityInputMode = bottomMode,
                NumberOfBars = bottomBars > 0 ? bottomBars : Math.Max(2, legacyData.EstimatedBottomBarsX),
                SpacingMm = legacyData.BottomSpacingXMm,
                XDirectionSpec = btmXSpec,
                YDirectionSpec = btmYSpec,
                XSpacingMm = legacyData.BottomSpacingXMm,
                YSpacingMm = legacyData.BottomSpacingYMm,
                LapLengthExpr = legacyData.BottomLapExpr ?? "0"
            };

            naviate.SideBars = new FoundationNaviateSideBarsUiData
            {
                IsEnabled = legacyData.CreateLinks,
                BarType = legacyData.LinkBarType,
                ShapeCode = string.IsNullOrWhiteSpace(sideShapeCode) ? "21" : sideShapeCode,
                BottomTieSpacingMm = legacyData.BottomTieSpacingMm,
                MidTieSpacingMm = legacyData.MidTieSpacingMm,
                TopTieSpacingMm = legacyData.TopTieSpacingMm,
                BottomZoneExpr = legacyData.BottomZoneExpr ?? "0",
                MidZoneExpr = legacyData.MidZoneExpr ?? "0",
                TopZoneExpr = legacyData.TopZoneExpr ?? "0",
                TieSpec = BuildFoundationRebarShorthandSpecText(FoundationRebarLinkBarTypeCombo, FoundationRebarMidTieSpacingMmTextBox)
            };

            var starter = new FoundationNaviateColumnStarterBarsUiData
            {
                IsEnabled = legacyData.IncludeStarterBars,
                MainSpec = starterMainSpec,
                TieSpec = starterTieSpec,
                MainBarType = legacyData.MainBarType,
                TieBarType = legacyData.LinkBarType
            };
            if (TryParseFoundationRebarCountBarSpec(starterMainSpec, out int starterBarsCount, out string starterBarToken))
            {
                starter.BarsX = starterBarsCount;
                starter.BarsY = starterBarsCount;
                starter.MainBarType = string.IsNullOrWhiteSpace(starterBarToken) ? starter.MainBarType : starterBarToken;
            }
            if (TryParseFoundationRebarShorthandSpec(starterTieSpec, out string starterTieToken, out double starterTieSpacingMm))
            {
                starter.TieSpacingMm = Math.Max(0.0, starterTieSpacingMm);
                starter.TieBarType = string.IsNullOrWhiteSpace(starterTieToken) ? starter.TieBarType : starterTieToken;
            }
            naviate.ColumnStarterBars = starter;

            if (IsFoundationNaviateCloneUiVisible())
            {
                string settingName = (GetFoundationRebarComboText(FoundationNaviateSettingCombo) ?? "").Trim();
                if (!string.IsNullOrWhiteSpace(settingName))
                {
                    naviate.SettingName = settingName;
                }

                ApplyFoundationNaviateCloneLayerOverridesToSnapshot(naviate.TopBars, legacyData, isTop: true, naviate.Images);
                ApplyFoundationNaviateCloneLayerOverridesToSnapshot(naviate.BottomBars, legacyData, isTop: false, naviate.Images);
            }

            return naviate;
        }

        private static string BuildFoundationNaviateCountSpecText(int barCount, string barType)
        {
            int count = Math.Max(2, barCount);
            string token = (barType ?? "").Trim();
            return string.IsNullOrWhiteSpace(token)
                ? count.ToString(CultureInfo.InvariantCulture)
                : $"{count}x{token}";
        }

        private static string BuildFoundationNaviateSpacingSpecText(string barType, double spacingMm)
        {
            double spacing = Math.Max(0.0, spacingMm);
            string token = (barType ?? "").Trim();
            if (string.IsNullOrWhiteSpace(token))
            {
                return spacing <= 0.0 ? "" : spacing.ToString("0.###", CultureInfo.InvariantCulture);
            }

            return spacing <= 0.0
                ? token
                : $"{token}@{spacing.ToString("0.###", CultureInfo.InvariantCulture)}";
        }

        private void ApplyFoundationNaviateCloneLayerOverridesToSnapshot(
            FoundationNaviateLayerUiData target,
            FoundationRebarPreviewUiData legacyData,
            bool isTop,
            FoundationNaviateImageCatalogUiData images)
        {
            if (target == null || legacyData == null || !IsFoundationNaviateCloneUiVisible())
            {
                return;
            }

            target.IsEnabled = GetFoundationNaviateLayerEnabledCheckBox(isTop)?.IsChecked == true;
            target.MainLayerDirection = GetFoundationNaviateLayerDirectionFromCloneUi(isTop);
            target.ReinforcementDisplayMode = GetFoundationNaviateReinforcementModeFromCloneUi(isTop);
            target.ReinforcementDisplayImagePath =
                target.ReinforcementDisplayMode == FoundationNaviateUiReinforcementDisplayMode.LapLength
                    ? (images?.LapLengthReinforcementImage?.RelativePath ?? target.ReinforcementDisplayImagePath)
                    : (images?.ContinuousReinforcementImage?.RelativePath ?? target.ReinforcementDisplayImagePath);
            target.OverlapInputMode = FoundationNaviateUiOverlapInputMode.DiameterMultiplier;

            int overlapMultiplier = ParseFoundationNaviateIntOrDefault(GetFoundationNaviateOverlapMultiplierTextBox(isTop), 40, 0);
            target.OverlapDiameterMultiplier = overlapMultiplier;

            double overlapLengthMm = 0.0;
            if (target.ReinforcementDisplayMode == FoundationNaviateUiReinforcementDisplayMode.LapLength &&
                overlapMultiplier > 0 &&
                TryEstimateFoundationRebarBarDiameterMm(GetFoundationNaviateBarTypeCombo(isTop), out double barDiameterMm) &&
                barDiameterMm > 0.0)
            {
                overlapLengthMm = overlapMultiplier * barDiameterMm;
            }
            else
            {
                string lapExpr = isTop ? legacyData.TopLapExpr : legacyData.BottomLapExpr;
                if (TryParseFoundationRebarLengthExpressionMm(lapExpr, Math.Max(1.0, legacyData.LengthMm), out double parsedLapMm))
                {
                    overlapLengthMm = Math.Max(0.0, parsedLapMm);
                }
            }

            target.OverlapLengthMm = overlapLengthMm;

            string selectedBarType = (GetFoundationRebarComboText(GetFoundationNaviateBarTypeCombo(isTop)) ?? "").Trim();
            if (!string.IsNullOrWhiteSpace(selectedBarType))
            {
                target.BarType = selectedBarType;
            }

            string selectedShape = (GetFoundationRebarComboText(GetFoundationNaviateShapeCombo(isTop)) ?? "").Trim();
            target.ShapeCode = string.IsNullOrWhiteSpace(selectedShape) ? "None" : selectedShape;
            target.HookAtStart = (GetFoundationRebarComboText(GetFoundationNaviateHookStartCombo(isTop)) ?? "None").Trim();
            if (string.IsNullOrWhiteSpace(target.HookAtStart)) target.HookAtStart = "None";
            target.HookAtEnd = (GetFoundationRebarComboText(GetFoundationNaviateHookEndCombo(isTop)) ?? "None").Trim();
            if (string.IsNullOrWhiteSpace(target.HookAtEnd)) target.HookAtEnd = "None";

            target.QuantityInputMode = GetFoundationNaviateQuantityModeFromCloneUi(isTop);
            target.NumberOfBars = ParseFoundationNaviateIntOrDefault(GetFoundationNaviateQtyBarsTextBox(isTop), target.NumberOfBars, 2);
            target.SpacingMm = ParseFoundationNaviateDoubleOrDefault(GetFoundationNaviateQtySpacingTextBox(isTop), target.SpacingMm, 1.0);

            target.XSpacingMm = isTop ? legacyData.TopSpacingXMm : legacyData.BottomSpacingXMm;
            target.YSpacingMm = isTop ? legacyData.TopSpacingYMm : legacyData.BottomSpacingYMm;

            string distributionBarType = (legacyData.DistributionBarType ?? "").Trim();
            string yBarTypeForClone = !string.IsNullOrWhiteSpace(target.BarType) ? target.BarType : distributionBarType;
            if (target.QuantityInputMode == FoundationNaviateUiQuantityInputMode.NumberOfBars)
            {
                target.XDirectionSpec = BuildFoundationNaviateCountSpecText(target.NumberOfBars, target.BarType);
                target.YDirectionSpec = BuildFoundationNaviateCountSpecText(target.NumberOfBars, yBarTypeForClone);
            }
            else
            {
                target.XDirectionSpec = BuildFoundationNaviateSpacingSpecText(target.BarType, target.XSpacingMm);
                target.YDirectionSpec = BuildFoundationNaviateSpacingSpecText(yBarTypeForClone, target.YSpacingMm);
            }

            target.LapLengthExpr = isTop
                ? (legacyData.TopLapExpr ?? "0")
                : (legacyData.BottomLapExpr ?? "0");
        }

        private static FoundationNaviateMainLayerDirection MapFoundationNaviateDirectionToRequest(FoundationNaviateUiMainLayerDirection value)
        {
            return value == FoundationNaviateUiMainLayerDirection.TransversalBars
                ? FoundationNaviateMainLayerDirection.TransversalBars
                : FoundationNaviateMainLayerDirection.LongitudinalBars;
        }

        private static FoundationNaviateReinforcementDisplayMode MapFoundationNaviateDisplayModeToRequest(FoundationNaviateUiReinforcementDisplayMode value)
        {
            return value == FoundationNaviateUiReinforcementDisplayMode.LapLength
                ? FoundationNaviateReinforcementDisplayMode.LapLength
                : FoundationNaviateReinforcementDisplayMode.Continuous;
        }

        private static FoundationNaviateQuantityInputMode MapFoundationNaviateQuantityModeToRequest(FoundationNaviateUiQuantityInputMode value)
        {
            return value == FoundationNaviateUiQuantityInputMode.NumberOfBars
                ? FoundationNaviateQuantityInputMode.NumberOfBars
                : FoundationNaviateQuantityInputMode.Spacing;
        }

        private static FoundationNaviateOverlapInputMode MapFoundationNaviateOverlapModeToRequest(FoundationNaviateUiOverlapInputMode value)
        {
            return value == FoundationNaviateUiOverlapInputMode.DiameterMultiplier
                ? FoundationNaviateOverlapInputMode.DiameterMultiplier
                : FoundationNaviateOverlapInputMode.LengthMm;
        }

        private FoundationNaviateRebarRequest BuildFoundationNaviateRequestFromUiSnapshot(
            FoundationNaviateInputUiData uiData,
            ComboItem mainBar,
            ComboItem distributionBar,
            ComboItem linkBar,
            double topLapFt,
            double bottomLapFt,
            double bottomZoneFt,
            double midZoneFt,
            double topZoneFt)
        {
            FoundationNaviateInputUiData ui = uiData ?? new FoundationNaviateInputUiData();

            FoundationNaviateLayerRequest BuildLayer(FoundationNaviateLayerUiData layerUi, bool isTop)
            {
                FoundationNaviateLayerUiData src = layerUi ?? new FoundationNaviateLayerUiData();
                return new FoundationNaviateLayerRequest
                {
                    LayerKey = isTop ? FoundationNaviateRebarLayerKey.Top : FoundationNaviateRebarLayerKey.Bottom,
                    IsEnabled = src.IsEnabled,
                    MainLayerDirection = MapFoundationNaviateDirectionToRequest(src.MainLayerDirection),
                    ReinforcementDisplayMode = MapFoundationNaviateDisplayModeToRequest(src.ReinforcementDisplayMode),
                    OverlapInputMode = MapFoundationNaviateOverlapModeToRequest(src.OverlapInputMode),
                    OverlapDiameterMultiplier = src.OverlapDiameterMultiplier,
                    OverlapLengthFt = MmToFeetUi(Math.Max(0.0, src.OverlapLengthMm)),
                    BarTypeId = (mainBar?.Id) ?? ElementId.InvalidElementId,
                    BarTypeName = src.BarType ?? "",
                    ShapeCode = src.ShapeCode ?? "None",
                    HookAtStart = src.HookAtStart ?? "None",
                    HookAtEnd = src.HookAtEnd ?? "None",
                    QuantityInputMode = MapFoundationNaviateQuantityModeToRequest(src.QuantityInputMode),
                    NumberOfBars = Math.Max(0, src.NumberOfBars),
                    SpacingFt = MmToFeetUi(Math.Max(0.0, src.SpacingMm)),
                    XDirectionSpec = src.XDirectionSpec ?? "",
                    YDirectionSpec = src.YDirectionSpec ?? "",
                    XSpacingFt = MmToFeetUi(Math.Max(0.0, src.XSpacingMm)),
                    YSpacingFt = MmToFeetUi(Math.Max(0.0, src.YSpacingMm)),
                    LapLengthFt = isTop ? topLapFt : bottomLapFt
                };
            }

            var request = new FoundationNaviateRebarRequest
            {
                IsEnabled = true,
                SettingName = ui.SettingName ?? "<In Session>",
                FollowPickedHostGeometry = ui.FollowPickedHostGeometry,
                DeleteExistingRebar = ui.DeleteExistingRebar,
                ShowDimensionsInPreview = ui.ShowDimensionsInPreview,
                ShowBarMarkersInPreview = ui.ShowBarMarkersInPreview,
                TopCoverFt = MmToFeetUi(Math.Max(0.0, ui.TopCoverMm)),
                BottomCoverFt = MmToFeetUi(Math.Max(0.0, ui.BottomCoverMm)),
                SideCoverFt = MmToFeetUi(Math.Max(0.0, ui.SideCoverMm)),
                TopBars = BuildLayer(ui.TopBars, isTop: true),
                BottomBars = BuildLayer(ui.BottomBars, isTop: false),
                SideBars = new FoundationNaviateSideBarsRequest
                {
                    IsEnabled = ui.SideBars?.IsEnabled == true,
                    BarTypeId = (linkBar?.Id) ?? ElementId.InvalidElementId,
                    BarTypeName = ui.SideBars?.BarType ?? "",
                    TieSpec = ui.SideBars?.TieSpec ?? "",
                    ShapeCode = ui.SideBars?.ShapeCode ?? "None",
                    HookAtStart = ui.SideBars?.HookAtStart ?? "None",
                    HookAtEnd = ui.SideBars?.HookAtEnd ?? "None",
                    BottomTieSpacingFt = MmToFeetUi(Math.Max(0.0, ui.SideBars?.BottomTieSpacingMm ?? 0.0)),
                    MidTieSpacingFt = MmToFeetUi(Math.Max(0.0, ui.SideBars?.MidTieSpacingMm ?? 0.0)),
                    TopTieSpacingFt = MmToFeetUi(Math.Max(0.0, ui.SideBars?.TopTieSpacingMm ?? 0.0)),
                    BottomZoneLengthFt = bottomZoneFt,
                    MidZoneLengthFt = midZoneFt,
                    TopZoneLengthFt = topZoneFt
                },
                ColumnStarterBars = new FoundationNaviateColumnStarterBarsRequest
                {
                    IsEnabled = ui.ColumnStarterBars?.IsEnabled == true,
                    MainSpec = ui.ColumnStarterBars?.MainSpec ?? "",
                    XDirectionSpec = ui.ColumnStarterBars?.XDirectionSpec ?? "",
                    YDirectionSpec = ui.ColumnStarterBars?.YDirectionSpec ?? "",
                    TieSpec = ui.ColumnStarterBars?.TieSpec ?? "",
                    BarsX = Math.Max(0, ui.ColumnStarterBars?.BarsX ?? 0),
                    BarsY = Math.Max(0, ui.ColumnStarterBars?.BarsY ?? 0),
                    MainBarTypeId = (mainBar?.Id) ?? ElementId.InvalidElementId,
                    TieBarTypeId = (linkBar?.Id) ?? ElementId.InvalidElementId,
                    MainBarTypeName = ui.ColumnStarterBars?.MainBarType ?? "",
                    TieBarTypeName = ui.ColumnStarterBars?.TieBarType ?? "",
                    TieShapeCode = ui.ColumnStarterBars?.TieShapeCode ?? "None",
                    TieHookAtStart = ui.ColumnStarterBars?.TieHookAtStart ?? "None",
                    TieHookAtEnd = ui.ColumnStarterBars?.TieHookAtEnd ?? "None",
                    TieSpacingFt = MmToFeetUi(Math.Max(0.0, ui.ColumnStarterBars?.TieSpacingMm ?? 0.0)),
                    TopLapLengthFt = 0.0,
                    TopLapBarDiameterMultiplier = Math.Max(0, ui.ColumnStarterBars?.TopLapBarDiameterMultiplier ?? 0),
                    LapBarsPercent = Math.Max(0, ui.ColumnStarterBars?.LapBarsPercent ?? 100)
                }
            };

            // Preserve Y-direction main-bar type reference in compatibility stage via bar type names inside specs.
            if (distributionBar != null && string.IsNullOrWhiteSpace(request.TopBars.BarTypeName))
            {
                request.TopBars.BarTypeName = distributionBar.Name ?? "";
            }

            return request;
        }

        private void UpdateFoundationRebarSummaryUi(FoundationRebarPreviewUiData data, string validationMessage)
        {
            if (data == null)
            {
                return;
            }

            if (FoundationRebarLiveSummaryText != null)
            {
                double refLengthMm = Math.Max(1.0, data.LengthMm);
                string topLapText = TryParseFoundationRebarLengthExpressionMm(data.TopLapExpr, refLengthMm, out double topLapMm)
                    ? $"{data.TopLapExpr} ({topLapMm:0.#} mm)"
                    : data.TopLapExpr;
                string bottomLapText = TryParseFoundationRebarLengthExpressionMm(data.BottomLapExpr, refLengthMm, out double bottomLapMm)
                    ? $"{data.BottomLapExpr} ({bottomLapMm:0.#} mm)"
                    : data.BottomLapExpr;
                string topXCountDia = FormatFoundationRebarCountDiaSpec(data.EstimatedTopBarsX, data.MainBarType);
                string topYCountDia = FormatFoundationRebarCountDiaSpec(data.EstimatedTopBarsY, data.DistributionBarType);
                string btmXCountDia = FormatFoundationRebarCountDiaSpec(data.EstimatedBottomBarsX, data.MainBarType);
                string btmYCountDia = FormatFoundationRebarCountDiaSpec(data.EstimatedBottomBarsY, data.DistributionBarType);

                FoundationRebarLiveSummaryText.Text =
                    $"Type: {data.TypeMode} | Scope: {data.ScopeMode}\n" +
                    $"Host: {(string.IsNullOrWhiteSpace(data.HostText) ? "(not selected)" : data.HostText)}\n" +
                    $"Geometry (mm): LxBxT = {data.LengthMm:0.#} x {data.WidthMm:0.#} x {data.ThicknessMm:0.#} | Pedestal HxWxB = {data.PedestalHeightMm:0.#} x {data.PedestalWidthMm:0.#} x {data.PedestalDepthMm:0.#}\n" +
                    $"Cover (mm): top/bottom/side = {data.TopCoverMm:0.#}/{data.BottomCoverMm:0.#}/{data.SideCoverMm:0.#} | Starter bars: {(data.IncludeStarterBars ? "On" : "Off")}\n" +
                    $"Top bars est.: X={topXCountDia}, Y={topYCountDia} @ {data.TopSpacingXMm:0.#}/{data.TopSpacingYMm:0.#} mm | Lap={topLapText}\n" +
                    $"Bottom bars est.: X={btmXCountDia}, Y={btmYCountDia} @ {data.BottomSpacingXMm:0.#}/{data.BottomSpacingYMm:0.#} mm | Lap={bottomLapText}\n" +
                    $"Links/Zones: {(data.CreateLinks ? "On" : "Off")} | Tie spacing B/M/T = {data.BottomTieSpacingMm:0.#}/{data.MidTieSpacingMm:0.#}/{data.TopTieSpacingMm:0.#} mm | Est. levels ≈ {data.EstimatedTieLevels}";
            }

            if (FoundationRebarValidationHintText != null)
            {
                bool hasWarning = !string.IsNullOrWhiteSpace(validationMessage);
                FoundationRebarValidationHintText.Text = hasWarning
                    ? validationMessage
                    : "Tips: use presets to start, then tune covers/spacing. Preview updates can be re-run after every edit.";
                FoundationRebarValidationHintText.Foreground = new SolidColorBrush(
                    hasWarning ? WpfColor.FromRgb(154, 96, 0) : WpfColor.FromRgb(62, 96, 138));
            }
        }

        private static string FormatFoundationRebarCountDiaSpec(int count, string barTypeText)
        {
            int normalizedCount = Math.Max(0, count);
            string bar = (barTypeText ?? "").Trim();
            if (normalizedCount <= 0)
            {
                return "0";
            }

            return string.IsNullOrWhiteSpace(bar)
                ? normalizedCount.ToString(CultureInfo.InvariantCulture)
                : normalizedCount.ToString(CultureInfo.InvariantCulture) + bar;
        }

        private static bool TryParseFoundationRebarLengthExpressionMm(string text, double referenceLengthMm, out double value)
        {
            value = 0.0;
            string raw = (text ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return false;
            }

            if (TryParseFlexibleDouble(raw, out value) && value >= 0.0)
            {
                return true;
            }

            string compact = Regex.Replace(raw.ToUpperInvariant(), "\\s+", "");
            Match relativeMatch = Regex.Match(
                compact,
                "^(?<factor>[0-9]+(?:[\\.,][0-9]+)?)(?<percent>%?)\\*(?<ref>L|LEN|LENGTH)$",
                RegexOptions.CultureInvariant);
            if (relativeMatch.Success && referenceLengthMm > 0.0)
            {
                if (!TryParseFlexibleDouble(relativeMatch.Groups["factor"].Value, out double factor) || factor < 0.0)
                {
                    return false;
                }

                if (relativeMatch.Groups["percent"].Value == "%")
                {
                    factor /= 100.0;
                }

                value = factor * referenceLengthMm;
                return true;
            }

            string normalized = compact
                .Replace("×", "X")
                .Replace("@", "X");

            int xIndex = normalized.IndexOf('X');
            if (xIndex <= 0 || xIndex >= normalized.Length - 1 || normalized.IndexOf('X', xIndex + 1) >= 0)
            {
                return false;
            }

            string countPart = normalized.Substring(0, xIndex);
            string lengthPart = normalized.Substring(xIndex + 1);
            if (!TryParseFlexibleDouble(countPart, out double count) ||
                !TryParseFlexibleDouble(lengthPart, out double lengthMm) ||
                count < 0.0 || lengthMm < 0.0)
            {
                return false;
            }

            value = count * lengthMm;
            return true;
        }

        private bool RenderFoundationRebarPreviewFromCurrentInputs(bool strictValidation, bool showStatusOnFailure)
        {
            if (!TryBuildFoundationRebarPreviewUiData(strictValidation, out FoundationRebarPreviewUiData data, out string validationMessage) || data == null)
            {
                if (!string.IsNullOrWhiteSpace(validationMessage))
                {
                    if (FoundationRebarValidationHintText != null)
                    {
                        FoundationRebarValidationHintText.Text = validationMessage;
                        FoundationRebarValidationHintText.Foreground = new SolidColorBrush(WpfColor.FromRgb(166, 69, 0));
                    }

                    if (showStatusOnFailure)
                    {
                        ShowStatus("FOUNDATION: " + validationMessage);
                    }
                }

                if (!_foundationRebarPreviewHasRendered)
                {
                    RenderFoundationRebarPreviewPlaceholder();
                }

                UpdateFoundationRebarDesignUiState();
                return false;
            }

            RenderFoundationRebar3DSchematic(data);
            RenderFoundationRebarPlanSchematic(data);
            RenderFoundationRebarSectionSchematic(FoundationRebarSectionACanvas, data, useLengthForHorizontalAxis: true, sectionName: "A-A");
            RenderFoundationRebarSectionSchematic(FoundationRebarSectionBCanvas, data, useLengthForHorizontalAxis: false, sectionName: "B-B");
            _foundationNaviateInputUiSnapshot = BuildFoundationNaviateInputUiDataFromCurrentUi(data);

            _foundationRebarPreviewDirty = false;
            _foundationRebarPreviewHasRendered = true;
            _foundationRebarLastPreviewUtc = DateTime.Now;

            if (FoundationRebarPreviewInfoText != null)
            {
                string selectedFieldText = _foundationRebarPreviewSelectedEditField == FoundationPreviewEditField.None
                    ? "none"
                    : GetFoundationRebarPreviewFieldLabel(_foundationRebarPreviewSelectedEditField);
                FoundationRebarPreviewInfoText.Text =
                    $"Schematic preview | {data.TypeMode} | LxBxT = {data.LengthMm:0.#} x {data.WidthMm:0.#} x {data.ThicknessMm:0.#} mm | " +
                    $"Top est X/Y = {data.EstimatedTopBarsX}/{data.EstimatedTopBarsY} | Bottom est X/Y = {data.EstimatedBottomBarsX}/{data.EstimatedBottomBarsY} | " +
                    $"Ties {(data.CreateLinks ? "On" : "Off")} ({data.EstimatedTieLevels} levels approx.) | 3D: Drag=Rotate / Wheel=Zoom / Ctrl+Wheel=Edit selected ({selectedFieldText}) | Plan/Section: drag handles";
            }

            UpdateFoundationRebarSummaryUi(data, validationMessage);
            UpdateFoundationRebarDesignUiState();
            return true;
        }

        private bool TryRaiseFoundationRebarGenerateRequest()
        {
            if (!TryUpdateFoundationRebarRequestFromUi())
            {
                return false;
            }

            _handler.Request.RequestType = CadToModelRequestType.GenerateFoundationRebar;
            _externalEvent.Raise();
            return true;
        }

        private bool TryUpdateFoundationRebarRequestFromUi()
        {
            if (_foundationRebarHostPreview == null || _foundationRebarHostPreview.HostElementId == ElementId.InvalidElementId)
            {
                ShowStatus("FOUNDATION: pick a structural foundation host first.");
                return false;
            }

            if (!(FoundationRebarMainBarTypeCombo?.SelectedItem is ComboItem mainBar))
            {
                ShowStatus("FOUNDATION: select Top/Bottom Main bar type.");
                return false;
            }

            if (!(FoundationRebarDistributionBarTypeCombo?.SelectedItem is ComboItem distributionBar))
            {
                ShowStatus("FOUNDATION: select Distribution bar type.");
                return false;
            }

            ComboItem linkBar = FoundationRebarLinkBarTypeCombo?.SelectedItem as ComboItem;

            if (!TryBuildFoundationRebarPreviewUiData(strictValidation: true, out FoundationRebarPreviewUiData data, out string validationMessage) || data == null)
            {
                if (!string.IsNullOrWhiteSpace(validationMessage))
                {
                    ShowStatus("FOUNDATION: " + validationMessage);
                }
                return false;
            }

            if (data.CreateLinks && linkBar == null)
            {
                ShowStatus("FOUNDATION: select Link/Stirrup bar type.");
                return false;
            }

            if (TryGetFoundationRebarHostGeometryMismatchMessage(data, out string hostMismatchMessage))
            {
                ShowStatus("FOUNDATION: " + hostMismatchMessage + " Generation will use actual Revit host geometry. Re-pick the host (Pick Host/Pick Element) to align preview.");
            }

            double referenceLengthMm = Math.Max(1.0, data.LengthMm);
            if (!TryParseFoundationRebarExprToFeet(data.TopLapExpr, referenceLengthMm, "Top lap", out double topLapFt))
            {
                return false;
            }
            if (!TryParseFoundationRebarExprToFeet(data.BottomLapExpr, referenceLengthMm, "Bottom lap", out double bottomLapFt))
            {
                return false;
            }
            if (!TryParseFoundationRebarExprToFeet(data.BottomZoneExpr, referenceLengthMm, "Bottom zone length", out double bottomZoneFt))
            {
                return false;
            }
            if (!TryParseFoundationRebarExprToFeet(data.MidZoneExpr, referenceLengthMm, "Mid zone length", out double midZoneFt))
            {
                return false;
            }
            if (!TryParseFoundationRebarExprToFeet(data.TopZoneExpr, referenceLengthMm, "Top zone length", out double topZoneFt))
            {
                return false;
            }

            _handler.Request.FoundationRebarHostElementId = _foundationRebarHostPreview.HostElementId;
            _handler.Request.FoundationRebarMainBarTypeId = mainBar.Id;
            _handler.Request.FoundationRebarDistributionBarTypeId = distributionBar.Id;
            _handler.Request.FoundationRebarLinkBarTypeId = linkBar.Id;
            _handler.Request.FoundationRebarTypeModeText = data.TypeMode ?? "";
            _handler.Request.FoundationRebarScopeModeText = data.ScopeMode ?? "";
            _handler.Request.FoundationRebarApplyToSameType = IsFoundationRebarSameTypeScope(data.ScopeMode);
            _handler.Request.FoundationRebarCreateTopBars = data.CreateTopBars;
            _handler.Request.FoundationRebarCreateBottomBars = data.CreateBottomBars;
            _handler.Request.FoundationRebarCreateLinks = data.CreateLinks;
            _handler.Request.FoundationRebarIncludeStarterBars = data.IncludeStarterBars;
            _handler.Request.FoundationRebarDeleteExisting = true;

            _handler.Request.FoundationRebarLengthOverrideFt = MmToFeetUi(data.LengthMm);
            _handler.Request.FoundationRebarWidthOverrideFt = MmToFeetUi(data.WidthMm);
            _handler.Request.FoundationRebarThicknessOverrideFt = MmToFeetUi(data.ThicknessMm);
            _handler.Request.FoundationRebarPedestalHeightFt = MmToFeetUi(data.PedestalHeightMm);
            _handler.Request.FoundationRebarPedestalWidthFt = MmToFeetUi(data.PedestalWidthMm);
            _handler.Request.FoundationRebarPedestalDepthFt = MmToFeetUi(data.PedestalDepthMm);

            _handler.Request.FoundationRebarTopCoverFt = MmToFeetUi(data.TopCoverMm);
            _handler.Request.FoundationRebarBottomCoverFt = MmToFeetUi(data.BottomCoverMm);
            _handler.Request.FoundationRebarSideCoverFt = MmToFeetUi(data.SideCoverMm);
            _handler.Request.FoundationRebarTopSpacingXFt = MmToFeetUi(data.TopSpacingXMm);
            _handler.Request.FoundationRebarTopSpacingYFt = MmToFeetUi(data.TopSpacingYMm);
            _handler.Request.FoundationRebarBottomSpacingXFt = MmToFeetUi(data.BottomSpacingXMm);
            _handler.Request.FoundationRebarBottomSpacingYFt = MmToFeetUi(data.BottomSpacingYMm);
            _handler.Request.FoundationRebarBottomTieSpacingFt = MmToFeetUi(data.BottomTieSpacingMm);
            _handler.Request.FoundationRebarMidTieSpacingFt = MmToFeetUi(data.MidTieSpacingMm);
            _handler.Request.FoundationRebarTopTieSpacingFt = MmToFeetUi(data.TopTieSpacingMm);
            _handler.Request.FoundationRebarTopLapLengthFt = topLapFt;
            _handler.Request.FoundationRebarBottomLapLengthFt = bottomLapFt;
            _handler.Request.FoundationRebarBottomZoneLengthFt = bottomZoneFt;
            _handler.Request.FoundationRebarMidZoneLengthFt = midZoneFt;
            _handler.Request.FoundationRebarTopZoneLengthFt = topZoneFt;

            _foundationNaviateInputUiSnapshot = BuildFoundationNaviateInputUiDataFromCurrentUi(data);
            _handler.Request.FoundationRebarUseNaviateDataModel = true;
            _handler.Request.FoundationRebarNaviate = BuildFoundationNaviateRequestFromUiSnapshot(
                _foundationNaviateInputUiSnapshot,
                mainBar,
                distributionBar,
                linkBar,
                topLapFt,
                bottomLapFt,
                bottomZoneFt,
                midZoneFt,
                topZoneFt);

            return true;
        }

        private bool TryParseFoundationRebarExprToFeet(string expression, double referenceLengthMm, string label, out double valueFt)
        {
            valueFt = 0.0;
            string raw = (expression ?? "").Trim();
            if (string.IsNullOrWhiteSpace(raw))
            {
                return true;
            }

            if (!TryParseFoundationRebarLengthExpressionMm(raw, referenceLengthMm, out double valueMm))
            {
                ShowStatus($"FOUNDATION: {label} must be mm, NxL, or factor*L.");
                return false;
            }

            valueFt = MmToFeetUi(Math.Max(0.0, valueMm));
            return true;
        }

        private static bool IsFoundationRebarSameTypeScope(string scopeText)
        {
            string normalized = (scopeText ?? "").Trim().ToLowerInvariant();
            return normalized.Contains("same type");
        }

        private bool TryGetFoundationRebarHostGeometryMismatchMessage(FoundationRebarPreviewUiData data, out string message)
        {
            message = "";
            if (data == null || _foundationRebarHostPreview == null || _foundationRebarHostPreview.HostElementId == ElementId.InvalidElementId)
            {
                return false;
            }

            double hostL = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.LengthFt));
            double hostB = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.WidthFt));
            double hostT = Math.Max(0.0, FeetToMmUi(_foundationRebarHostPreview.ThicknessFt));
            double uiL = Math.Max(0.0, data.LengthMm);
            double uiB = Math.Max(0.0, data.WidthMm);
            double uiT = Math.Max(0.0, data.ThicknessMm);

            // Allow L/B swap due to host local-axis orientation.
            double directDelta = Math.Abs(uiL - hostL) + Math.Abs(uiB - hostB);
            double swappedDelta = Math.Abs(uiL - hostB) + Math.Abs(uiB - hostL);
            bool swappedPlanMatch = swappedDelta < directDelta;

            double planDeltaL = swappedPlanMatch ? Math.Abs(uiL - hostB) : Math.Abs(uiL - hostL);
            double planDeltaB = swappedPlanMatch ? Math.Abs(uiB - hostL) : Math.Abs(uiB - hostB);
            double deltaT = Math.Abs(uiT - hostT);

            const double mmTolerance = 10.0;
            if (planDeltaL <= mmTolerance && planDeltaB <= mmTolerance && deltaT <= mmTolerance)
            {
                return false;
            }

            string hostDimsText = swappedPlanMatch
                ? $"{hostB:0.#}x{hostL:0.#}x{hostT:0.#} mm (host axes swapped)"
                : $"{hostL:0.#}x{hostB:0.#}x{hostT:0.#} mm";
            string uiDimsText = $"{uiL:0.#}x{uiB:0.#}x{uiT:0.#} mm";

            message =
                $"Preview geometry ({uiDimsText}) differs from selected host {_foundationRebarHostPreview.HostElementId.Value} ({hostDimsText}).";
            return true;
        }

        private void RenderFoundationRebarPreviewPlaceholder()
        {
            if (FoundationRebarPreviewViewport != null)
            {
                FoundationRebarPreviewViewport.Children.Clear();
                FoundationRebarPreviewViewport.Camera = null;
            }

            _foundationRebarPreviewSceneWidthFt = 0.0;
            _foundationRebarPreviewSceneDepthFt = 0.0;
            _foundationRebarPreviewSceneHeightFt = 0.0;
            _foundationRebarPreviewIsDragging = false;
            EndFoundationRebarPreviewCanvasHandleDrag();
            _foundationRebarPlanDragHandles.Clear();
            _foundationRebarSectionADragHandles.Clear();
            _foundationRebarSectionBDragHandles.Clear();

            DrawFoundationPreviewPlaceholderCanvas(FoundationRebarPlanCanvas, "PLAN PREVIEW", "Update Preview to draw schematic plan");
            DrawFoundationPreviewPlaceholderCanvas(FoundationRebarSectionACanvas, "SECTION A-A", "Update Preview to draw section");
            DrawFoundationPreviewPlaceholderCanvas(FoundationRebarSectionBCanvas, "SECTION B-B", "Update Preview to draw section");

            if (FoundationRebarPreviewInfoText != null)
            {
                FoundationRebarPreviewInfoText.Text =
                    "Preview panels are ready. Update Preview to draw handles. 3D: drag rotate / wheel zoom. Plan+Section: drag handles. Ctrl+Wheel edits selected dimension.";
            }
        }

        private void RefreshFoundationRebarPreviewCameraOnly()
        {
            var viewport = FoundationRebarPreviewViewport;
            if (viewport == null)
            {
                return;
            }

            if (_foundationRebarPreviewSceneWidthFt <= 0.0 ||
                _foundationRebarPreviewSceneDepthFt <= 0.0 ||
                _foundationRebarPreviewSceneHeightFt <= 0.0)
            {
                return;
            }

            viewport.Camera = BuildFoundationRebarPreviewCamera(
                _foundationRebarPreviewSceneWidthFt,
                _foundationRebarPreviewSceneDepthFt,
                _foundationRebarPreviewSceneHeightFt);
        }

        private Media3D.ProjectionCamera BuildFoundationRebarPreviewCamera(double widthFt, double depthFt, double heightFt)
        {
            double maxDim = Math.Max(Math.Max(widthFt, depthFt), heightFt);
            if (maxDim < 1e-6) maxDim = MmToFeetUi(1000);

            double yawRad = _foundationRebarPreviewYawDeg * Math.PI / 180.0;
            double pitchRad = _foundationRebarPreviewPitchDeg * Math.PI / 180.0;
            double radius = (maxDim * 2.9) / Math.Max(0.2, _foundationRebarPreviewZoomFactor);
            double horizontal = Math.Cos(pitchRad);
            var center = new Media3D.Point3D(0.0, 0.0, Math.Max(heightFt * 0.45, MmToFeetUi(120)));
            var cameraPos = new Media3D.Point3D(
                center.X + radius * horizontal * Math.Cos(yawRad),
                center.Y + radius * horizontal * Math.Sin(yawRad),
                center.Z + radius * Math.Sin(pitchRad));

            return new Media3D.PerspectiveCamera
            {
                Position = cameraPos,
                LookDirection = new Media3D.Vector3D(center.X - cameraPos.X, center.Y - cameraPos.Y, center.Z - cameraPos.Z),
                UpDirection = new Media3D.Vector3D(0, 0, 1),
                FieldOfView = 42
            };
        }

        private void RenderFoundationRebar3DSchematic(FoundationRebarPreviewUiData data)
        {
            var viewport = FoundationRebarPreviewViewport;
            if (viewport == null || data == null)
            {
                return;
            }

            viewport.Children.Clear();

            var group = new Media3D.Model3DGroup();
            group.Children.Add(new Media3D.AmbientLight(WpfColor.FromRgb(240, 244, 250)));
            group.Children.Add(new Media3D.DirectionalLight(WpfColor.FromRgb(220, 232, 245), new Media3D.Vector3D(-1, -1, -1)));
            group.Children.Add(new Media3D.DirectionalLight(WpfColor.FromRgb(180, 205, 230), new Media3D.Vector3D(1, 1, -0.6)));

            double lFt = Math.Max(MmToFeetUi(100.0), MmToFeetUi(data.LengthMm));
            double bFt = Math.Max(MmToFeetUi(100.0), MmToFeetUi(data.WidthMm));
            double tFt = Math.Max(MmToFeetUi(80.0), MmToFeetUi(data.ThicknessMm));
            double pedHFt = Math.Max(0.0, MmToFeetUi(data.PedestalHeightMm));
            double pedWFt = Math.Max(0.0, MmToFeetUi(data.PedestalWidthMm));
            double pedDFt = Math.Max(0.0, MmToFeetUi(data.PedestalDepthMm));

            XYZ footingMin = new XYZ(-lFt * 0.5, -bFt * 0.5, 0.0);
            XYZ footingMax = new XYZ(lFt * 0.5, bFt * 0.5, tFt);
            double wireThkFt = Math.Max(MmToFeetUi(6.0), Math.Min(lFt, bFt) * 0.003);
            AddAxisAlignedPreviewWireBox(group, footingMin, footingMax, wireThkFt, CreatePreviewMaterial(WpfColor.FromRgb(95, 133, 190)));

            if (data.IncludeStarterBars && pedHFt > 1e-6 && pedWFt > 1e-6 && pedDFt > 1e-6)
            {
                XYZ pedMin = new XYZ(-pedWFt * 0.5, -pedDFt * 0.5, tFt);
                XYZ pedMax = new XYZ(pedWFt * 0.5, pedDFt * 0.5, tFt + pedHFt);
                AddAxisAlignedPreviewWireBox(group, pedMin, pedMax, Math.Max(MmToFeetUi(4.0), wireThkFt * 0.85), CreatePreviewMaterial(WpfColor.FromRgb(145, 128, 96)));
            }

            Media3D.Material topMat = CreatePreviewMaterial(WpfColor.FromRgb(0, 165, 105));
            Media3D.Material bottomMat = CreatePreviewMaterial(WpfColor.FromRgb(0, 130, 220));
            Media3D.Material tieMat = CreatePreviewMaterial(WpfColor.FromRgb(235, 140, 40));

            double sideCoverFt = MmToFeetUi(Math.Max(0.0, data.SideCoverMm));
            double topCoverFt = MmToFeetUi(Math.Max(0.0, data.TopCoverMm));
            double bottomCoverFt = MmToFeetUi(Math.Max(0.0, data.BottomCoverMm));
            double barThkFt = Math.Max(MmToFeetUi(8.0), Math.Min(lFt, bFt) * 0.008);

            double x0 = footingMin.X + sideCoverFt;
            double x1 = footingMax.X - sideCoverFt;
            double y0 = footingMin.Y + sideCoverFt;
            double y1 = footingMax.Y - sideCoverFt;
            double zTop = Math.Max(footingMin.Z, footingMax.Z - topCoverFt);
            double zBottom = Math.Min(footingMax.Z, footingMin.Z + bottomCoverFt);

            if (data.CreateTopBars && x1 > x0 + 1e-6 && y1 > y0 + 1e-6)
            {
                int drawTopX = Math.Max(2, Math.Min(14, data.EstimatedTopBarsX > 0 ? data.EstimatedTopBarsX : 2));
                int drawTopY = Math.Max(2, Math.Min(14, data.EstimatedTopBarsY > 0 ? data.EstimatedTopBarsY : 2));
                foreach (double y in BuildLinearPositions(y0, y1, drawTopX))
                {
                    AddPreviewLineBox(group, new XYZ(x0, y, zTop), new XYZ(x1, y, zTop), barThkFt, topMat);
                }
                foreach (double x in BuildLinearPositions(x0, x1, drawTopY))
                {
                    AddPreviewLineBox(group, new XYZ(x, y0, zTop), new XYZ(x, y1, zTop), barThkFt, topMat);
                }
            }

            if (data.CreateBottomBars && x1 > x0 + 1e-6 && y1 > y0 + 1e-6)
            {
                int drawBottomX = Math.Max(2, Math.Min(14, data.EstimatedBottomBarsX > 0 ? data.EstimatedBottomBarsX : 2));
                int drawBottomY = Math.Max(2, Math.Min(14, data.EstimatedBottomBarsY > 0 ? data.EstimatedBottomBarsY : 2));
                foreach (double y in BuildLinearPositions(y0, y1, drawBottomX))
                {
                    AddPreviewLineBox(group, new XYZ(x0, y, zBottom), new XYZ(x1, y, zBottom), barThkFt * 0.9, bottomMat);
                }
                foreach (double x in BuildLinearPositions(x0, x1, drawBottomY))
                {
                    AddPreviewLineBox(group, new XYZ(x, y0, zBottom), new XYZ(x, y1, zBottom), barThkFt * 0.9, bottomMat);
                }
            }

            if (data.CreateLinks && x1 > x0 + 1e-6 && y1 > y0 + 1e-6)
            {
                double zTieBottom = zBottom + Math.Max(MmToFeetUi(15.0), barThkFt * 0.8);
                double zTieTop = zTop - Math.Max(MmToFeetUi(15.0), barThkFt * 0.8);
                double tieLineThk = Math.Max(MmToFeetUi(5.0), barThkFt * 0.7);
                foreach (double z in BuildLinearPositions(zTieBottom, zTieTop, Math.Max(2, Math.Min(6, data.EstimatedTieLevels))))
                {
                    AddPreviewLineBox(group, new XYZ(x0, y0, z), new XYZ(x1, y0, z), tieLineThk, tieMat);
                    AddPreviewLineBox(group, new XYZ(x1, y0, z), new XYZ(x1, y1, z), tieLineThk, tieMat);
                    AddPreviewLineBox(group, new XYZ(x1, y1, z), new XYZ(x0, y1, z), tieLineThk, tieMat);
                    AddPreviewLineBox(group, new XYZ(x0, y1, z), new XYZ(x0, y0, z), tieLineThk, tieMat);
                }

                int drawVerticalLoopsY = Math.Max(2, Math.Min(18, data.EstimatedTopBarsX > 0 ? data.EstimatedTopBarsX : 2));
                int drawVerticalLoopsX = Math.Max(2, Math.Min(18, data.EstimatedTopBarsY > 0 ? data.EstimatedTopBarsY : 2));

                foreach (double y in BuildLinearPositions(y0, y1, drawVerticalLoopsY))
                {
                    AddPreviewLineBox(group, new XYZ(x0, y, zTieBottom), new XYZ(x1, y, zTieBottom), tieLineThk, tieMat);
                    AddPreviewLineBox(group, new XYZ(x0, y, zTieTop), new XYZ(x1, y, zTieTop), tieLineThk, tieMat);
                    AddPreviewLineBox(group, new XYZ(x0, y, zTieBottom), new XYZ(x0, y, zTieTop), tieLineThk, tieMat);
                    AddPreviewLineBox(group, new XYZ(x1, y, zTieBottom), new XYZ(x1, y, zTieTop), tieLineThk, tieMat);
                }

                foreach (double x in BuildLinearPositions(x0, x1, drawVerticalLoopsX))
                {
                    AddPreviewLineBox(group, new XYZ(x, y0, zTieBottom), new XYZ(x, y1, zTieBottom), tieLineThk * 0.9, tieMat);
                    AddPreviewLineBox(group, new XYZ(x, y0, zTieTop), new XYZ(x, y1, zTieTop), tieLineThk * 0.9, tieMat);
                    AddPreviewLineBox(group, new XYZ(x, y0, zTieBottom), new XYZ(x, y0, zTieTop), tieLineThk * 0.9, tieMat);
                    AddPreviewLineBox(group, new XYZ(x, y1, zTieBottom), new XYZ(x, y1, zTieTop), tieLineThk * 0.9, tieMat);
                }
            }

            double totalHeightFt = tFt + pedHFt;
            _foundationRebarPreviewSceneWidthFt = lFt;
            _foundationRebarPreviewSceneDepthFt = bFt;
            _foundationRebarPreviewSceneHeightFt = Math.Max(totalHeightFt, MmToFeetUi(120));
            viewport.Camera = BuildFoundationRebarPreviewCamera(
                _foundationRebarPreviewSceneWidthFt,
                _foundationRebarPreviewSceneDepthFt,
                _foundationRebarPreviewSceneHeightFt);

            viewport.Children.Add(new Media3D.ModelVisual3D { Content = group });
        }

        private void RenderFoundationRebarPlanSchematic(FoundationRebarPreviewUiData data)
        {
            var canvas = FoundationRebarPlanCanvas;
            if (canvas == null || data == null)
            {
                return;
            }

            double widthPx = GetFoundationCanvasSize(canvas.ActualWidth, 360.0);
            double heightPx = GetFoundationCanvasSize(canvas.ActualHeight, 240.0);
            if (widthPx < 40.0 || heightPx < 40.0)
            {
                return;
            }

            canvas.Children.Clear();
            AddFoundationCanvasBackground(canvas, widthPx, heightPx);
            _foundationRebarPlanDragHandles.Clear();

            double outerPad = 10.0;
            double gap = 10.0;
            double footerHeight = 18.0;
            double panelHeight = Math.Max(60.0, heightPx - (2.0 * outerPad) - footerHeight);
            double panelWidth = Math.Max(80.0, (widthPx - (2.0 * outerPad) - gap) * 0.5);
            double topViewLeft = outerPad;
            double bottomViewLeft = topViewLeft + panelWidth + gap;
            double panelTop = outerPad;

            RenderFoundationRebarPlanLayerSchematic(
                canvas,
                data,
                topViewLeft,
                panelTop,
                panelWidth,
                panelHeight,
                isTopView: true);

            RenderFoundationRebarPlanLayerSchematic(
                canvas,
                data,
                bottomViewLeft,
                panelTop,
                panelWidth,
                panelHeight,
                isTopView: false);

            AddFoundationCanvasText(canvas, 8.0, heightPx - 16.0,
                $"TOP: {data.MainBarType}/{data.DistributionBarType} @ {data.TopSpacingXMm:0.#}/{data.TopSpacingYMm:0.#} mm ({data.EstimatedTopBarsX}/{data.EstimatedTopBarsY})  |  " +
                $"BOTTOM: {data.MainBarType}/{data.DistributionBarType} @ {data.BottomSpacingXMm:0.#}/{data.BottomSpacingYMm:0.#} mm ({data.EstimatedBottomBarsX}/{data.EstimatedBottomBarsY})",
                WpfColor.FromRgb(70, 86, 110), 10.0, centered: false);
        }

        private void RenderFoundationRebarPlanLayerSchematic(
            Canvas canvas,
            FoundationRebarPreviewUiData data,
            double panelLeft,
            double panelTop,
            double panelWidth,
            double panelHeight,
            bool isTopView)
        {
            if (canvas == null || data == null || panelWidth <= 10.0 || panelHeight <= 10.0)
            {
                return;
            }

            WpfColor panelBorder = isTopView ? WpfColor.FromRgb(80, 138, 92) : WpfColor.FromRgb(66, 121, 182);
            WpfColor panelTitleColor = isTopView ? WpfColor.FromRgb(48, 104, 62) : WpfColor.FromRgb(48, 88, 138);
            WpfColor barColor = isTopView ? WpfColor.FromRgb(0, 160, 96) : WpfColor.FromRgb(0, 123, 209);
            string title = isTopView ? "TOP VIEW" : "BOTTOM VIEW";

            AddFoundationCanvasRect(canvas, panelLeft, panelTop, panelWidth, panelHeight, panelBorder, 1.1, null, fillColor: WpfColor.FromArgb(8, panelBorder.R, panelBorder.G, panelBorder.B));
            AddFoundationCanvasText(canvas, panelLeft + 8.0, panelTop + 14.0, title, panelTitleColor, 10.5, centered: false);

            double headerH = 20.0;
            double footerH = 18.0;
            double innerPad = 10.0;
            double drawAreaLeft = panelLeft + innerPad;
            double drawAreaTop = panelTop + headerH;
            double drawAreaWidth = Math.Max(20.0, panelWidth - (innerPad * 2.0));
            double drawAreaHeight = Math.Max(20.0, panelHeight - headerH - footerH - 4.0);

            double padPx = 18.0;
            double scale = Math.Min(
                (drawAreaWidth - (2.0 * padPx)) / Math.Max(1.0, data.LengthMm),
                (drawAreaHeight - (2.0 * padPx)) / Math.Max(1.0, data.WidthMm));
            scale = Math.Max(0.02, scale);

            double drawW = data.LengthMm * scale;
            double drawH = data.WidthMm * scale;
            double left = drawAreaLeft + ((drawAreaWidth - drawW) * 0.5);
            double top = drawAreaTop + ((drawAreaHeight - drawH) * 0.5);
            double pedLeft = 0.0;
            double pedTop = 0.0;
            double pedW = 0.0;
            double pedH = 0.0;
            bool hasPedRect = false;

            AddFoundationCanvasRect(canvas, left, top, drawW, drawH, WpfColor.FromRgb(72, 108, 158), 1.4, null, fillColor: WpfColor.FromArgb(6, 72, 108, 158));

            double coverPx = Math.Max(1.0, data.SideCoverMm * scale);
            double innerLeft = left + coverPx;
            double innerTop = top + coverPx;
            double innerW = Math.Max(0.0, drawW - (2.0 * coverPx));
            double innerH = Math.Max(0.0, drawH - (2.0 * coverPx));
            if (innerW > 2.0 && innerH > 2.0)
            {
                AddFoundationCanvasRect(canvas, innerLeft, innerTop, innerW, innerH, WpfColor.FromRgb(148, 160, 176), 1.0, new DoubleCollection { 4, 3 });
            }

            if (data.IncludeStarterBars && data.PedestalHeightMm > 0.0 && data.PedestalWidthMm > 0.0 && data.PedestalDepthMm > 0.0)
            {
                pedW = Math.Min(drawW, Math.Max(0.0, data.PedestalWidthMm * scale));
                pedH = Math.Min(drawH, Math.Max(0.0, data.PedestalDepthMm * scale));
                pedLeft = left + ((drawW - pedW) * 0.5);
                pedTop = top + ((drawH - pedH) * 0.5);
                hasPedRect = pedW > 0.0 && pedH > 0.0;
                AddFoundationCanvasRect(canvas, pedLeft, pedTop, pedW, pedH, WpfColor.FromRgb(161, 118, 72), 1.1, null, fillColor: WpfColor.FromArgb(18, 176, 130, 75));
            }

            if (data.CreateLinks && innerW > 4.0 && innerH > 4.0)
            {
                DrawFoundationPlanLinkPerimeterMarkers(canvas, data, innerLeft, innerTop, innerW, innerH);
            }

            if (innerW > 4.0 && innerH > 4.0)
            {
                if (isTopView && data.CreateTopBars)
                {
                    DrawFoundationPlanBarSet(canvas, innerLeft, innerTop, innerW, innerH, data.EstimatedTopBarsX, data.EstimatedTopBarsY, barColor, data.ShowBarMarkers, dashed: false);
                }

                if (!isTopView && data.CreateBottomBars)
                {
                    DrawFoundationPlanBarSet(canvas, innerLeft, innerTop, innerW, innerH, data.EstimatedBottomBarsX, data.EstimatedBottomBarsY, barColor, data.ShowBarMarkers, dashed: false);
                }
            }

            if (data.ShowDimensions)
            {
                AddFoundationCanvasText(canvas, left + (drawW * 0.5), Math.Max(2.0, top - 14.0), $"{data.LengthMm:0.#} mm", WpfColor.FromRgb(68, 92, 122), 9.6, centered: true);
                AddFoundationCanvasText(canvas, Math.Max(2.0, left - 4.0), top + (drawH * 0.5), $"{data.WidthMm:0.#} mm", WpfColor.FromRgb(68, 92, 122), 9.6, centered: false);
            }

            int barsX = isTopView ? data.EstimatedTopBarsX : data.EstimatedBottomBarsX;
            int barsY = isTopView ? data.EstimatedTopBarsY : data.EstimatedBottomBarsY;
            double spacingX = isTopView ? data.TopSpacingXMm : data.BottomSpacingXMm;
            double spacingY = isTopView ? data.TopSpacingYMm : data.BottomSpacingYMm;
            string layerLabel = isTopView ? "Top" : "Bottom";
            AddFoundationCanvasText(
                canvas,
                panelLeft + 8.0,
                panelTop + panelHeight - 6.0,
                $"{layerLabel} bars {data.MainBarType}/{data.DistributionBarType} | X/Y={barsX}/{barsY} @ {spacingX:0.#}/{spacingY:0.#}",
                WpfColor.FromRgb(74, 88, 110),
                9.2,
                centered: false);

            if (isTopView)
            {
                AddFoundationRebarPlanDirectEditHandles(canvas, left, top, drawW, drawH, scale, hasPedRect, pedLeft, pedTop, pedW, pedH);
            }
        }

        private void DrawFoundationPlanBarSet(
            Canvas canvas,
            double left,
            double top,
            double width,
            double height,
            int barsX,
            int barsY,
            WpfColor color,
            bool drawMarkers,
            bool dashed)
        {
            if (canvas == null || width <= 2.0 || height <= 2.0)
            {
                return;
            }

            int drawBarsX = Math.Max(2, Math.Min(40, barsX > 0 ? barsX : 2));
            int drawBarsY = Math.Max(2, Math.Min(40, barsY > 0 ? barsY : 2));
            DoubleCollection dash = dashed ? new DoubleCollection { 3, 2 } : null;

            List<double> yPositions = BuildLinearPositions(top, top + height, drawBarsX).ToList();
            List<double> xPositions = BuildLinearPositions(left, left + width, drawBarsY).ToList();

            foreach (double y in yPositions)
            {
                AddFoundationCanvasLine(canvas, left, y, left + width, y, color, 1.0, dash);
            }

            foreach (double x in xPositions)
            {
                AddFoundationCanvasLine(canvas, x, top, x, top + height, color, 1.0, dash);
            }

            if (!drawMarkers)
            {
                return;
            }

            int markerBudget = 120;
            foreach (double y in yPositions)
            {
                foreach (double x in xPositions)
                {
                    if (markerBudget-- <= 0)
                    {
                        return;
                    }
                    AddFoundationCanvasCircle(canvas, x, y, 1.6, color, WpfColor.FromArgb(110, color.R, color.G, color.B));
                }
            }
        }

        private void DrawFoundationPlanLinkPerimeterMarkers(
            Canvas canvas,
            FoundationRebarPreviewUiData data,
            double left,
            double top,
            double width,
            double height)
        {
            if (canvas == null || data == null || width <= 2.0 || height <= 2.0)
            {
                return;
            }

            WpfColor cageColor = WpfColor.FromRgb(228, 130, 42);
            AddFoundationCanvasRect(canvas, left, top, width, height, cageColor, 1.0, new DoubleCollection { 2, 2 });

            double spacingX;
            if (data.TopSpacingXMm > 1e-6 && data.BottomSpacingXMm > 1e-6) spacingX = Math.Min(data.TopSpacingXMm, data.BottomSpacingXMm);
            else spacingX = data.TopSpacingXMm > 1e-6 ? data.TopSpacingXMm : data.BottomSpacingXMm;
            if (spacingX <= 1e-6) spacingX = 150.0;

            double spacingY;
            if (data.TopSpacingYMm > 1e-6 && data.BottomSpacingYMm > 1e-6) spacingY = Math.Min(data.TopSpacingYMm, data.BottomSpacingYMm);
            else spacingY = data.TopSpacingYMm > 1e-6 ? data.TopSpacingYMm : data.BottomSpacingYMm;
            if (spacingY <= 1e-6) spacingY = 150.0;

            int loopCountAlongY = Math.Max(2, Math.Min(40, EstimateFoundationRebarBarCount(data.WidthMm, data.SideCoverMm, spacingX)));
            int loopCountAlongX = Math.Max(2, Math.Min(40, EstimateFoundationRebarBarCount(data.LengthMm, data.SideCoverMm, spacingY)));

            double tickLen = 4.0;
            foreach (double y in BuildLinearPositions(top, top + height, loopCountAlongY))
            {
                AddFoundationCanvasLine(canvas, left, y, left + tickLen, y, cageColor, 0.9, null);
                AddFoundationCanvasLine(canvas, left + width - tickLen, y, left + width, y, cageColor, 0.9, null);
            }

            foreach (double x in BuildLinearPositions(left, left + width, loopCountAlongX))
            {
                AddFoundationCanvasLine(canvas, x, top, x, top + tickLen, cageColor, 0.9, null);
                AddFoundationCanvasLine(canvas, x, top + height - tickLen, x, top + height, cageColor, 0.9, null);
            }
        }

        private void RenderFoundationRebarSectionSchematic(Canvas canvas, FoundationRebarPreviewUiData data, bool useLengthForHorizontalAxis, string sectionName)
        {
            if (canvas == null || data == null)
            {
                return;
            }

            double widthPx = GetFoundationCanvasSize(canvas.ActualWidth, 360.0);
            double heightPx = GetFoundationCanvasSize(canvas.ActualHeight, 240.0);
            if (widthPx < 40.0 || heightPx < 40.0)
            {
                return;
            }

            canvas.Children.Clear();
            AddFoundationCanvasBackground(canvas, widthPx, heightPx);
            List<FoundationPreviewDragHandle> sectionHandles = GetFoundationRebarPreviewDragHandleList(canvas);
            if (sectionHandles != null)
            {
                sectionHandles.Clear();
            }

            double planDimMm = useLengthForHorizontalAxis ? data.LengthMm : data.WidthMm;
            double pedPlanDimMm = useLengthForHorizontalAxis ? data.PedestalWidthMm : data.PedestalDepthMm;
            double totalHeightMm = data.ThicknessMm + Math.Max(0.0, data.IncludeStarterBars ? data.PedestalHeightMm : 0.0);
            double padPx = 24.0;
            double scale = Math.Min((widthPx - (2.0 * padPx)) / Math.Max(1.0, planDimMm), (heightPx - (2.0 * padPx)) / Math.Max(1.0, totalHeightMm));
            scale = Math.Max(0.02, scale);

            double footingW = planDimMm * scale;
            double footingH = data.ThicknessMm * scale;
            double footingLeft = (widthPx - footingW) * 0.5;
            double footingTop = heightPx - padPx - footingH;
            double pedLeft = 0.0;
            double pedTop = 0.0;
            double pedW = 0.0;
            double pedH = 0.0;
            bool hasPedRect = false;

            AddFoundationCanvasRect(canvas, footingLeft, footingTop, footingW, footingH, WpfColor.FromRgb(72, 108, 158), 1.5, null, fillColor: WpfColor.FromArgb(10, 72, 108, 158));

            double topCoverPx = Math.Max(1.0, data.TopCoverMm * scale);
            double bottomCoverPx = Math.Max(1.0, data.BottomCoverMm * scale);
            double sideCoverPx = Math.Max(1.0, data.SideCoverMm * scale);
            if (footingW > 2.0 * sideCoverPx)
            {
                AddFoundationCanvasRect(canvas,
                    footingLeft + sideCoverPx,
                    footingTop + topCoverPx,
                    Math.Max(0.0, footingW - (2.0 * sideCoverPx)),
                    Math.Max(0.0, footingH - topCoverPx - bottomCoverPx),
                    WpfColor.FromRgb(148, 160, 176),
                    1.0,
                    new DoubleCollection { 4, 3 });
            }

            if (data.IncludeStarterBars && data.PedestalHeightMm > 0.0 && pedPlanDimMm > 0.0)
            {
                pedW = Math.Min(footingW, pedPlanDimMm * scale);
                pedH = data.PedestalHeightMm * scale;
                pedLeft = footingLeft + ((footingW - pedW) * 0.5);
                pedTop = footingTop - pedH;
                hasPedRect = pedW > 0.0 && pedH > 0.0;
                AddFoundationCanvasRect(canvas, pedLeft, pedTop, pedW, pedH, WpfColor.FromRgb(161, 118, 72), 1.2, null, fillColor: WpfColor.FromArgb(18, 176, 130, 75));

                if (data.CreateTopBars)
                {
                    int starterBars = Math.Max(2, Math.Min(8, useLengthForHorizontalAxis ? Math.Max(2, data.EstimatedTopBarsY / 2) : Math.Max(2, data.EstimatedTopBarsX / 2)));
                    foreach (double x in BuildLinearPositions(pedLeft + 6.0, pedLeft + pedW - 6.0, starterBars))
                    {
                        AddFoundationCanvasLine(canvas, x, pedTop + pedH, x, pedTop + Math.Max(2.0, pedH * 0.25), WpfColor.FromRgb(40, 140, 70), 1.0, null);
                    }
                }
            }

            if (data.CreateTopBars)
            {
                double y = footingTop + topCoverPx;
                AddFoundationCanvasLine(canvas, footingLeft + sideCoverPx, y, footingLeft + footingW - sideCoverPx, y, WpfColor.FromRgb(0, 160, 96), 1.4, null);
            }

            if (data.CreateBottomBars)
            {
                double y = footingTop + footingH - bottomCoverPx;
                AddFoundationCanvasLine(canvas, footingLeft + sideCoverPx, y, footingLeft + footingW - sideCoverPx, y, WpfColor.FromRgb(0, 123, 209), 1.4, new DoubleCollection { 3, 2 });
            }

            if (data.CreateLinks)
            {
                double cageTop = footingTop + topCoverPx;
                double cageBottom = footingTop + footingH - bottomCoverPx;
                double cageLeft = footingLeft + sideCoverPx;
                double cageRight = footingLeft + footingW - sideCoverPx;
                if (cageBottom > cageTop + 4.0 && cageRight > cageLeft + 4.0)
                {
                    int lines = Math.Max(2, Math.Min(6, data.EstimatedTieLevels));
                    foreach (double y in BuildLinearPositions(cageTop, cageBottom, lines))
                    {
                        AddFoundationCanvasLine(canvas, cageLeft, y, cageRight, y, WpfColor.FromArgb(150, 235, 140, 40), 1.0, new DoubleCollection { 2, 2 });
                    }

                    int loopCountAlongSection = useLengthForHorizontalAxis
                        ? Math.Max(2, Math.Min(16, data.EstimatedTopBarsY > 0 ? data.EstimatedTopBarsY : 2))
                        : Math.Max(2, Math.Min(16, data.EstimatedTopBarsX > 0 ? data.EstimatedTopBarsX : 2));
                    foreach (double x in BuildLinearPositions(cageLeft, cageRight, loopCountAlongSection))
                    {
                        AddFoundationCanvasLine(canvas, x, cageTop, x, cageBottom, WpfColor.FromArgb(135, 210, 90, 70), 0.9, new DoubleCollection { 2, 2 });
                    }

                    AddFoundationCanvasRect(canvas, cageLeft, cageTop, Math.Max(0.0, cageRight - cageLeft), Math.Max(0.0, cageBottom - cageTop),
                        WpfColor.FromArgb(120, 180, 70, 170), 0.9, new DoubleCollection { 3, 2 });
                }
            }

            if (data.ShowDimensions)
            {
                AddFoundationCanvasText(canvas, footingLeft + (footingW * 0.5), Math.Max(2.0, footingTop - 16.0), $"{planDimMm:0.#} mm", WpfColor.FromRgb(68, 92, 122), 10.0, centered: true);
                AddFoundationCanvasText(canvas, Math.Max(2.0, footingLeft - 4.0), footingTop + (footingH * 0.5), $"{data.ThicknessMm:0.#} mm", WpfColor.FromRgb(68, 92, 122), 10.0, centered: false);
            }

            AddFoundationCanvasText(canvas, 8.0, heightPx - 16.0,
                $"{sectionName} | {(useLengthForHorizontalAxis ? "Along L" : "Along B")} | Covers T/B/S={data.TopCoverMm:0.#}/{data.BottomCoverMm:0.#}/{data.SideCoverMm:0.#}",
                WpfColor.FromRgb(70, 86, 110), 10.0, centered: false);

            AddFoundationRebarSectionDirectEditHandles(
                canvas,
                useLengthForHorizontalAxis,
                footingLeft,
                footingTop,
                footingW,
                footingH,
                scale,
                hasPedRect,
                pedLeft,
                pedTop,
                pedW,
                pedH);
        }

        private void AddFoundationRebarPlanDirectEditHandles(
            Canvas canvas,
            double left,
            double top,
            double width,
            double height,
            double scalePxPerMm,
            bool hasPedRect,
            double pedLeft,
            double pedTop,
            double pedW,
            double pedH)
        {
            if (canvas == null || scalePxPerMm <= 1e-6)
            {
                return;
            }

            double mmPerPx = 1.0 / scalePxPerMm;
            double rightHandleX = left + width + 10.0;
            double topHandleY = Math.Max(8.0, top - 10.0);

            AddFoundationRebarPreviewDragHandle(
                canvas,
                _foundationRebarPlanDragHandles,
                FoundationPreviewEditField.Length,
                rightHandleX,
                top + (height * 0.5),
                FoundationPreviewDragAxis.Horizontal,
                mmPerPx,
                1.0,
                200.0);

            AddFoundationRebarPreviewDragHandle(
                canvas,
                _foundationRebarPlanDragHandles,
                FoundationPreviewEditField.Width,
                left + (width * 0.5),
                topHandleY,
                FoundationPreviewDragAxis.Vertical,
                mmPerPx,
                -1.0,
                200.0);

            if (hasPedRect && pedW > 2.0 && pedH > 2.0)
            {
                AddFoundationRebarPreviewDragHandle(
                    canvas,
                    _foundationRebarPlanDragHandles,
                    FoundationPreviewEditField.PedestalWidth,
                    pedLeft + pedW + 8.0,
                    pedTop + (pedH * 0.5),
                    FoundationPreviewDragAxis.Horizontal,
                    mmPerPx,
                    1.0,
                    0.0);

                AddFoundationRebarPreviewDragHandle(
                    canvas,
                    _foundationRebarPlanDragHandles,
                    FoundationPreviewEditField.PedestalDepth,
                    pedLeft + (pedW * 0.5),
                    Math.Max(8.0, pedTop - 8.0),
                    FoundationPreviewDragAxis.Vertical,
                    mmPerPx,
                    -1.0,
                    0.0);
            }
        }

        private void AddFoundationRebarSectionDirectEditHandles(
            Canvas canvas,
            bool useLengthForHorizontalAxis,
            double footingLeft,
            double footingTop,
            double footingW,
            double footingH,
            double scalePxPerMm,
            bool hasPedRect,
            double pedLeft,
            double pedTop,
            double pedW,
            double pedH)
        {
            if (canvas == null || scalePxPerMm <= 1e-6)
            {
                return;
            }

            List<FoundationPreviewDragHandle> handles = GetFoundationRebarPreviewDragHandleList(canvas);
            if (handles == null)
            {
                return;
            }

            double mmPerPx = 1.0 / scalePxPerMm;
            FoundationPreviewEditField planField = useLengthForHorizontalAxis
                ? FoundationPreviewEditField.Length
                : FoundationPreviewEditField.Width;
            FoundationPreviewEditField pedPlanField = useLengthForHorizontalAxis
                ? FoundationPreviewEditField.PedestalWidth
                : FoundationPreviewEditField.PedestalDepth;

            AddFoundationRebarPreviewDragHandle(
                canvas,
                handles,
                planField,
                footingLeft + footingW + 10.0,
                footingTop + (footingH * 0.5),
                FoundationPreviewDragAxis.Horizontal,
                mmPerPx,
                1.0,
                200.0);

            AddFoundationRebarPreviewDragHandle(
                canvas,
                handles,
                FoundationPreviewEditField.Thickness,
                footingLeft + (footingW * 0.5),
                Math.Max(8.0, footingTop - 10.0),
                FoundationPreviewDragAxis.Vertical,
                mmPerPx,
                -1.0,
                150.0);

            if (hasPedRect && pedW > 2.0 && pedH > 2.0)
            {
                AddFoundationRebarPreviewDragHandle(
                    canvas,
                    handles,
                    pedPlanField,
                    pedLeft + pedW + 8.0,
                    pedTop + (pedH * 0.5),
                    FoundationPreviewDragAxis.Horizontal,
                    mmPerPx,
                    1.0,
                    0.0);

                AddFoundationRebarPreviewDragHandle(
                    canvas,
                    handles,
                    FoundationPreviewEditField.PedestalHeight,
                    pedLeft + (pedW * 0.5),
                    Math.Max(8.0, pedTop - 8.0),
                    FoundationPreviewDragAxis.Vertical,
                    mmPerPx,
                    -1.0,
                    0.0);
            }
        }

        private void AddFoundationRebarPreviewDragHandle(
            Canvas canvas,
            List<FoundationPreviewDragHandle> handles,
            FoundationPreviewEditField field,
            double centerX,
            double centerY,
            FoundationPreviewDragAxis axis,
            double mmPerPixel,
            double dragSign,
            double minValueMm)
        {
            if (canvas == null || handles == null || field == FoundationPreviewEditField.None)
            {
                return;
            }

            double x = Math.Max(6.0, centerX);
            double y = Math.Max(6.0, centerY);
            bool isSelected = field == _foundationRebarPreviewSelectedEditField;
            WpfColor stroke = isSelected ? WpfColor.FromRgb(218, 78, 41) : WpfColor.FromRgb(72, 92, 118);
            WpfColor fill = isSelected ? WpfColor.FromArgb(220, 255, 228, 210) : WpfColor.FromArgb(210, 248, 251, 255);
            double arm = 6.0;

            if (axis == FoundationPreviewDragAxis.Horizontal)
            {
                AddFoundationCanvasLine(canvas, x - arm, y, x + arm, y, stroke, isSelected ? 1.5 : 1.0, null);
                AddFoundationCanvasLine(canvas, x + arm, y - 3.0, x + arm, y + 3.0, stroke, isSelected ? 1.3 : 0.9, null);
            }
            else
            {
                AddFoundationCanvasLine(canvas, x, y - arm, x, y + arm, stroke, isSelected ? 1.5 : 1.0, null);
                AddFoundationCanvasLine(canvas, x - 3.0, y - arm, x + 3.0, y - arm, stroke, isSelected ? 1.3 : 0.9, null);
            }

            AddFoundationCanvasCircle(canvas, x, y, isSelected ? 4.8 : 4.2, stroke, fill);

            string label = GetFoundationRebarPreviewFieldLabel(field);
            if (!string.IsNullOrWhiteSpace(label))
            {
                AddFoundationCanvasText(canvas, x + 8.0, Math.Max(2.0, y - 10.0), label, stroke, 9.2, centered: false);
            }

            handles.Add(new FoundationPreviewDragHandle
            {
                Field = field,
                Axis = axis,
                CenterXPx = x,
                CenterYPx = y,
                HitRectPx = new Rect(x - 12.0, y - 12.0, 24.0, 24.0),
                MmPerPixel = Math.Max(0.001, mmPerPixel),
                DragSign = Math.Abs(dragSign) < 1e-9 ? 1.0 : dragSign,
                MinValueMm = Math.Max(0.0, minValueMm),
                Label = label
            });
        }

        private static double GetFoundationCanvasSize(double actual, double fallback)
        {
            if (double.IsNaN(actual) || double.IsInfinity(actual) || actual < 1.0)
            {
                return fallback;
            }

            return actual;
        }

        private static void DrawFoundationPreviewPlaceholderCanvas(Canvas canvas, string title, string message)
        {
            if (canvas == null)
            {
                return;
            }

            double widthPx = GetFoundationCanvasSize(canvas.ActualWidth, 360.0);
            double heightPx = GetFoundationCanvasSize(canvas.ActualHeight, 240.0);
            canvas.Children.Clear();
            AddFoundationCanvasBackground(canvas, widthPx, heightPx);
            AddFoundationCanvasRect(canvas, 12.0, 12.0, Math.Max(20.0, widthPx - 24.0), Math.Max(20.0, heightPx - 24.0), WpfColor.FromRgb(190, 202, 220), 1.0, new DoubleCollection { 4, 3 });
            AddFoundationCanvasText(canvas, widthPx * 0.5, Math.Max(18.0, (heightPx * 0.5) - 8.0), title, WpfColor.FromRgb(92, 108, 130), 11.0, centered: true);
            AddFoundationCanvasText(canvas, widthPx * 0.5, (heightPx * 0.5) + 10.0, message, WpfColor.FromRgb(118, 132, 150), 10.0, centered: true);
        }

        private static void AddFoundationCanvasBackground(Canvas canvas, double widthPx, double heightPx)
        {
            if (canvas == null)
            {
                return;
            }

            var bg = new System.Windows.Shapes.Rectangle
            {
                Width = Math.Max(0.0, widthPx),
                Height = Math.Max(0.0, heightPx),
                Fill = new SolidColorBrush(WpfColor.FromRgb(248, 250, 253)),
                StrokeThickness = 0.0,
                IsHitTestVisible = false
            };
            Canvas.SetLeft(bg, 0.0);
            Canvas.SetTop(bg, 0.0);
            canvas.Children.Add(bg);

            for (double x = 0.0; x <= widthPx; x += 24.0)
            {
                AddFoundationCanvasLine(canvas, x, 0.0, x, heightPx, WpfColor.FromArgb(28, 70, 90, 120), 0.8, null);
            }
            for (double y = 0.0; y <= heightPx; y += 24.0)
            {
                AddFoundationCanvasLine(canvas, 0.0, y, widthPx, y, WpfColor.FromArgb(28, 70, 90, 120), 0.8, null);
            }
        }

        private static void AddFoundationCanvasRect(Canvas canvas, double left, double top, double width, double height, WpfColor strokeColor, double strokeThickness, DoubleCollection dashArray, WpfColor? fillColor = null)
        {
            if (canvas == null || width <= 0.0 || height <= 0.0)
            {
                return;
            }

            var rect = new System.Windows.Shapes.Rectangle
            {
                Width = width,
                Height = height,
                Stroke = new SolidColorBrush(strokeColor),
                StrokeThickness = strokeThickness,
                Fill = fillColor.HasValue ? new SolidColorBrush(fillColor.Value) : Brushes.Transparent,
                IsHitTestVisible = false
            };
            if (dashArray != null)
            {
                rect.StrokeDashArray = dashArray;
            }

            Canvas.SetLeft(rect, left);
            Canvas.SetTop(rect, top);
            canvas.Children.Add(rect);
        }

        private static void AddFoundationCanvasLine(Canvas canvas, double x1, double y1, double x2, double y2, WpfColor color, double thickness, DoubleCollection dashArray)
        {
            if (canvas == null)
            {
                return;
            }

            var line = new System.Windows.Shapes.Line
            {
                X1 = x1,
                Y1 = y1,
                X2 = x2,
                Y2 = y2,
                Stroke = new SolidColorBrush(color),
                StrokeThickness = thickness,
                IsHitTestVisible = false
            };
            if (dashArray != null)
            {
                line.StrokeDashArray = dashArray;
            }
            canvas.Children.Add(line);
        }

        private static void AddFoundationCanvasCircle(Canvas canvas, double centerX, double centerY, double radius, WpfColor strokeColor, WpfColor fillColor)
        {
            if (canvas == null || radius <= 0.0)
            {
                return;
            }

            var ellipse = new System.Windows.Shapes.Ellipse
            {
                Width = radius * 2.0,
                Height = radius * 2.0,
                Stroke = new SolidColorBrush(strokeColor),
                StrokeThickness = 0.7,
                Fill = new SolidColorBrush(fillColor),
                IsHitTestVisible = false
            };
            Canvas.SetLeft(ellipse, centerX - radius);
            Canvas.SetTop(ellipse, centerY - radius);
            canvas.Children.Add(ellipse);
        }

        private static void AddFoundationCanvasText(Canvas canvas, double x, double y, string text, WpfColor color, double fontSize, bool centered)
        {
            if (canvas == null || string.IsNullOrWhiteSpace(text))
            {
                return;
            }

            var tb = new System.Windows.Controls.TextBlock
            {
                Text = text,
                Foreground = new SolidColorBrush(color),
                FontSize = fontSize,
                IsHitTestVisible = false
            };
            tb.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
            Size sz = tb.DesiredSize;
            Canvas.SetLeft(tb, centered ? (x - (sz.Width * 0.5)) : x);
            Canvas.SetTop(tb, centered ? (y - (sz.Height * 0.5)) : y);
            canvas.Children.Add(tb);
        }

