        private string ApplyTasSmartLayerSelection(bool announce)
        {
            System.Windows.Controls.ComboBox layerCombo = GetActiveCad2ModelLayerCombo();
            if (layerCombo == null)
            {
                if (announce)
                {
                    ShowStatus($"IDENTIFY / {GetCad2ModelTasActiveElementForStatus()}: Layer Manager is not required for this tool.");
                }

                return "";
            }

            string toolName = GetActiveCad2ModelToolName();
            List<string> layerNames = GetComboLayerNames(layerCombo);
            if (layerNames.Count == 0)
            {
                if (announce)
                {
                    ShowStatus($"IDENTIFY / {GetCad2ModelTasActiveElementForStatus()}: Pick Link first so Layer Manager can read DWG layers.");
                }

                return "";
            }

            List<Cad2ModelTasLayerCandidate> candidates = BuildTasLayerCandidates(toolName, layerNames, includeLabelLayers: false);
            Cad2ModelTasLayerCandidate best = candidates.FirstOrDefault(c => c.Score > 0);
            if (best == null)
            {
                string noMatch = $"Layer Manager: no confident {GetCad2ModelTasActiveElementForStatus()} layer found.";
                if (announce)
                {
                    ShowStatus(noMatch + " Select the CAD layer manually.");
                }

                return noMatch;
            }

            SelectComboItemByName(layerCombo, best.Name);
            EnsureActiveLayerModeForTool();

            string labelMessage = ApplyTasSmartLabelLayerSelection(toolName);
            string top = FormatLayerCandidateSummary(candidates);
            string message = $"Layer Manager: selected '{best.Name}' for {GetCad2ModelTasActiveElementForStatus()} (score {best.Score}). {top}{labelMessage}";
            RefreshCad2ModelTasAttributeRows(
                _cad2ModelTasActiveCategory,
                _cad2ModelTasActiveElement,
                _cad2ModelTasActiveToolName,
                _cad2ModelTasActiveConnected,
                null);
            UpdateCad2ModelTasWorkflowRail();

            if (announce)
            {
                ShowStatus(message);
            }

            return message;
        }

        private string ApplyTasSmartLabelLayerSelection(string toolName)
        {
            System.Windows.Controls.ComboBox labelCombo = GetActiveCad2ModelLabelLayerCombo();
            if (labelCombo == null)
            {
                return "";
            }

            List<string> layerNames = GetComboLayerNames(labelCombo);
            if (layerNames.Count == 0)
            {
                return "";
            }

            List<Cad2ModelTasLayerCandidate> candidates = BuildTasLayerCandidates(toolName, layerNames, includeLabelLayers: true);
            Cad2ModelTasLayerCandidate best = candidates.FirstOrDefault(c => c.Score > 0);
            if (best == null)
            {
                return "";
            }

            SelectComboItemByName(labelCombo, best.Name);
            return $" Label layer '{best.Name}'.";
        }

        private void RefreshCad2ModelTasLayerManagerTooltip()
        {
            if (Cad2ModelTasRibbonLayerManagerButton == null)
            {
                return;
            }

            Cad2ModelTasRibbonLayerManagerButton.ToolTip = BuildTasSmartLayerAdvisorText(_cad2ModelTasActiveToolName);
        }

        private string BuildTasSmartLayerAdvisorText(string toolName)
        {
            System.Windows.Controls.ComboBox layerCombo = GetActiveCad2ModelLayerCombo();
            if (layerCombo == null)
            {
                return "No CAD layer required";
            }

            List<string> layerNames = GetComboLayerNames(layerCombo);
            if (layerNames.Count == 0)
            {
                return "Pick Link first";
            }

            List<Cad2ModelTasLayerCandidate> candidates = BuildTasLayerCandidates(toolName, layerNames, includeLabelLayers: false);
            Cad2ModelTasLayerCandidate best = candidates.FirstOrDefault(c => c.Score > 0);
            if (best == null)
            {
                return "No confident match";
            }

            return $"Recommended: {best.Name} (score {best.Score})";
        }

        private System.Windows.Controls.ComboBox GetActiveCad2ModelLayerCombo()
        {
            if (IsGridlineTab()) return LayerCombo_Grid;
            if (IsBoredPileTab()) return BoredLayerCombo_Bored;
            if (IsFoundationTab()) return SlabLayerCombo_Foundation;
            if (IsSlabTab()) return LayerCombo_Slab;
            if (IsWallTab()) return LayerCombo_Wall;
            if (IsBeamTab()) return LayerCombo_Beam;
            if (IsColumnTabActive()) return LayerCombo;
            if (IsDrawingTab()) return GetDrawingLayerCombo();
            return null;
        }

        private System.Windows.Controls.ComboBox GetActiveCad2ModelLabelLayerCombo()
        {
            if (IsGridlineTab()) return LabelLayerCombo_Grid;
            if (IsColumnTabActive()) return GetColumnLabelLayerCombo();
            if (IsBeamTab()) return BeamLabelLayerCombo;
            return null;
        }

        private void EnsureActiveLayerModeForTool()
        {
            if (IsGridlineTab() && LayerModeRadio_Grid != null) LayerModeRadio_Grid.IsChecked = true;
            else if (IsBoredPileTab() && LayerModeRadio_Bored != null) LayerModeRadio_Bored.IsChecked = true;
            else if (IsFoundationTab() && LayerModeRadio_Foundation != null) LayerModeRadio_Foundation.IsChecked = true;
            else if (IsSlabTab() && LayerModeRadio_Slab != null) LayerModeRadio_Slab.IsChecked = true;
            else if (IsWallTab() && LayerModeRadio_Wall != null) LayerModeRadio_Wall.IsChecked = true;
            else if (IsBeamTab() && LayerModeRadio_Beam != null) LayerModeRadio_Beam.IsChecked = true;
            else if (IsColumnTabActive() && LayerModeRadio != null) LayerModeRadio.IsChecked = true;
        }

        private static List<string> GetComboLayerNames(System.Windows.Controls.ComboBox combo)
        {
            var names = new List<string>();
            if (combo?.ItemsSource == null)
            {
                return names;
            }

            foreach (object item in combo.ItemsSource)
            {
                string name = item?.ToString() ?? "";
                if (!string.IsNullOrWhiteSpace(name))
                {
                    names.Add(name);
                }
            }

            return names;
        }

        private List<Cad2ModelTasLayerCandidate> BuildTasLayerCandidates(string toolName, List<string> layers, bool includeLabelLayers)
        {
            return (layers ?? new List<string>())
                .Select(layer =>
                {
                    int score = ScoreTasLayerName(toolName, layer, includeLabelLayers);
                    return new Cad2ModelTasLayerCandidate(
                        layer,
                        score,
                        BuildTasLayerCandidateReason(toolName, layer, includeLabelLayers, score));
                })
                .OrderByDescending(c => c.Score)
                .ThenBy(c => c.Name, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static List<Cad2ModelTasLayerDialogRow> BuildTasLayerDialogRows(
            List<Cad2ModelTasLayerCandidate> mainCandidates,
            List<Cad2ModelTasLayerCandidate> labelCandidates,
            string selectedMainName,
            string selectedLabelName)
        {
            var rows = new List<Cad2ModelTasLayerDialogRow>();
            AddTasLayerDialogRows(rows, "Main", mainCandidates, selectedMainName);
            AddTasLayerDialogRows(rows, "Label", labelCandidates, selectedLabelName);
            return rows;
        }

        private static void AddTasLayerDialogRows(
            List<Cad2ModelTasLayerDialogRow> rows,
            string usage,
            List<Cad2ModelTasLayerCandidate> candidates,
            string selectedName)
        {
            if (rows == null || candidates == null || candidates.Count == 0)
            {
                return;
            }

            int rank = 1;
            foreach (Cad2ModelTasLayerCandidate candidate in candidates.Take(80))
            {
                bool selected = string.Equals(candidate.Name, selectedName, StringComparison.OrdinalIgnoreCase);
                string status = selected
                    ? "Selected"
                    : (rank == 1 && candidate.Score > 0 ? "Recommended" : (candidate.Score > 0 ? "Candidate" : "Low"));

                rows.Add(new Cad2ModelTasLayerDialogRow(
                    usage,
                    rank,
                    candidate.Name,
                    candidate.Score,
                    status,
                    candidate.Reason));
                rank++;
            }
        }

        private static string FormatLayerCandidateSummary(List<Cad2ModelTasLayerCandidate> candidates)
        {
            if (candidates == null || candidates.Count == 0)
            {
                return "";
            }

            List<Cad2ModelTasLayerCandidate> top = candidates.Where(c => c.Score > 0).Take(3).ToList();
            if (top.Count == 0)
            {
                return "";
            }

            return "Top: " + string.Join(", ", top.Select(c => $"{c.Name}({c.Score})")) + ".";
        }

        private static string BuildTasLayerCandidateReason(string toolName, string layerName, bool includeLabelLayer, int score)
        {
            if (string.IsNullOrWhiteSpace(layerName))
            {
                return "Blank layer name";
            }

            string tool = toolName ?? "";
            string name = layerName.ToUpperInvariant();
            var reasons = new List<string>();

            if (includeLabelLayer)
            {
                if (name.Contains("TEXT") || name.Contains("LABEL")) reasons.Add("text or label keyword");
                if (name.Contains("TAG") || name.Contains("MARK") || name.Contains("NAME")) reasons.Add("mark keyword");
                if (name.Contains("DIM")) reasons.Add("dimension penalty");
            }

            if (string.Equals(tool, "Column", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("COLUMN") || ContainsTasLayerToken(name, "COL")) reasons.Add("column keyword");
                if (name.Contains("CENTER") || name.Contains("CENTRE") || name.Contains("CTR") || name.Contains("CTRE")) reasons.Add("centerline keyword");
                if (name.Contains("POINT") || ContainsTasLayerToken(name, "PT")) reasons.Add("point keyword");
            }
            else if (string.Equals(tool, "Wall", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("WALL") || ContainsTasLayerToken(name, "WL")) reasons.Add("wall keyword");
                if (name.Contains("CENTER") || name.Contains("CENTRE") || name.Contains("CTR") || name.Contains("CTRE")) reasons.Add("centerline keyword");
                if (name.Contains("LINE") || ContainsTasLayerToken(name, "CL")) reasons.Add("line keyword");
            }
            else if (string.Equals(tool, "Beam", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("BEAM") || ContainsTasLayerToken(name, "BM")) reasons.Add("beam keyword");
                if (name.Contains("GIRDER") || name.Contains("FRAMING")) reasons.Add("framing keyword");
            }
            else if (string.Equals(tool, "Gridline", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("GRID") || name.Contains("AXIS") || name.Contains("AIXS")) reasons.Add("grid axis keyword");
                if (ContainsTasLayerToken(name, "GL")) reasons.Add("gridline token");
            }
            else if (string.Equals(tool, "Bored Pile", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("PILE") || name.Contains("BORED") || name.Contains("BORE")) reasons.Add("pile keyword");
                if (ContainsTasLayerToken(name, "BP")) reasons.Add("bored pile token");
            }
            else if (string.Equals(tool, "Foundation", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("FOUNDATION") || name.Contains("FOOTING")) reasons.Add("foundation keyword");
                if (name.Contains("PILECAP") || name.Contains("PILE CAP")) reasons.Add("pile cap keyword");
                if (name.Contains("ISOLATED") || name.Contains("PAD")) reasons.Add("pad footing keyword");
            }
            else if (string.Equals(tool, "Slab", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("SLAB") || name.Contains("FLOOR")) reasons.Add("slab or floor keyword");
                if (name.Contains("PLATE")) reasons.Add("plate keyword");
            }

            if (name.Contains("HATCH") || name.Contains("FILL") || name.Contains("DIM") || name.Contains("ANNOT"))
            {
                reasons.Add("annotation or hatch penalty");
            }

            if (reasons.Count == 0)
            {
                return score > 0 ? "TAS naming pattern" : "No TAS layer keyword";
            }

            return string.Join(", ", reasons.Take(4));
        }

        private static int ScoreTasLayerName(string toolName, string layerName, bool includeLabelLayer)
        {
            if (string.IsNullOrWhiteSpace(layerName))
            {
                return 0;
            }

            string tool = toolName ?? "";
            string name = layerName.ToUpperInvariant();
            int score = 0;

            if (includeLabelLayer)
            {
                if (name.Contains("TEXT")) score += 8;
                if (name.Contains("LABEL")) score += 8;
                if (name.Contains("TAG")) score += 5;
                if (name.Contains("MARK")) score += 5;
                if (name.Contains("NAME")) score += 3;
                if (name.Contains("DIM")) score -= 4;
            }

            if (string.Equals(tool, "Column", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("COLUMN")) score += 12;
                if (ContainsTasLayerToken(name, "COL")) score += 8;
                if (name.Contains("C-")) score += 2;
                if (name.Contains("CENTER") || name.Contains("CENTRE") || name.Contains("CTR") || name.Contains("CTRE")) score += 4;
                if (name.Contains("POINT") || ContainsTasLayerToken(name, "PT")) score += 2;
                if (name.Contains("GRID") || name.Contains("PILE") || name.Contains("SLAB") || name.Contains("BEAM") || name.Contains("WALL")) score -= 5;
            }
            else if (string.Equals(tool, "Wall", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("WALL")) score += 12;
                if (ContainsTasLayerToken(name, "WL")) score += 5;
                if (name.Contains("CENTER") || name.Contains("CENTRE") || name.Contains("CTR") || name.Contains("CTRE")) score += 3;
                if (name.Contains("LINE") || ContainsTasLayerToken(name, "CL")) score += 2;
                if (name.Contains("GRID") || name.Contains("COLUMN") || name.Contains("PILE") || name.Contains("SLAB") || name.Contains("BEAM")) score -= 5;
            }
            else if (string.Equals(tool, "Beam", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("BEAM")) score += 12;
                if (ContainsTasLayerToken(name, "BM")) score += 7;
                if (name.Contains("GIRDER")) score += 5;
                if (name.Contains("FRAMING")) score += 3;
                if (name.Contains("GRID") || name.Contains("COLUMN") || name.Contains("PILE") || name.Contains("SLAB") || name.Contains("WALL")) score -= 5;
            }
            else if (string.Equals(tool, "Gridline", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("GRID")) score += 12;
                if (name.Contains("AXIS") || name.Contains("AIXS")) score += 8;
                if (ContainsTasLayerToken(name, "GL")) score += 4;
                if (includeLabelLayer && (name.Contains("TEXT") || name.Contains("NO"))) score += 4;
                if (name.Contains("COLUMN") || name.Contains("BEAM") || name.Contains("WALL") || name.Contains("SLAB")) score -= 4;
            }
            else if (string.Equals(tool, "Bored Pile", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("PILE")) score += 12;
                if (name.Contains("BORED") || name.Contains("BORE")) score += 8;
                if (ContainsTasLayerToken(name, "BP")) score += 5;
                if (name.Contains("CAP") || name.Contains("COLUMN") || name.Contains("BEAM") || name.Contains("WALL")) score -= 4;
            }
            else if (string.Equals(tool, "Foundation", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("FOUNDATION") || name.Contains("FOOTING")) score += 12;
                if (name.Contains("PILECAP") || name.Contains("PILE CAP")) score += 8;
                if (name.Contains("ISOLATED") || name.Contains("PAD")) score += 6;
                if (name.Contains("SLAB")) score += 3;
                if (name.Contains("GRID") || name.Contains("COLUMN") || name.Contains("BEAM") || name.Contains("WALL")) score -= 4;
            }
            else if (string.Equals(tool, "Slab", StringComparison.OrdinalIgnoreCase))
            {
                if (name.Contains("SLAB")) score += 12;
                if (name.Contains("FLOOR")) score += 6;
                if (name.Contains("PLATE")) score += 3;
                if (name.Contains("GRID") || name.Contains("COLUMN") || name.Contains("BEAM") || name.Contains("WALL")) score -= 4;
            }

            if (name.Contains("HATCH") || name.Contains("FILL") || name.Contains("DIM") || name.Contains("ANNOT"))
            {
                score -= 3;
            }

            return score;
        }

        private static bool ContainsTasLayerToken(string name, string token)
        {
            if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(token)) return false;

            int idx = name.IndexOf(token, StringComparison.OrdinalIgnoreCase);
            if (idx < 0) return false;

            bool leftOk = idx == 0 || !char.IsLetterOrDigit(name[idx - 1]);
            int rightIndex = idx + token.Length;
            bool rightOk = rightIndex >= name.Length || !char.IsLetterOrDigit(name[rightIndex]);
            return leftOk && rightOk;
        }

        private sealed class Cad2ModelTasLayerCandidate
        {
            public Cad2ModelTasLayerCandidate(string name, int score, string reason)
            {
                Name = name ?? "";
                Score = score;
                Reason = reason ?? "";
