            if (BaseLevelCombo_Bored != null) BaseLevelCombo_Bored.ItemsSource = items;
            if (TopLevelCombo_Bored != null) TopLevelCombo_Bored.ItemsSource = items;
            if (FoundationLevelCombo_Foundation != null) FoundationLevelCombo_Foundation.ItemsSource = items;
            System.Windows.Controls.ComboBox leanLevelCombo = GetLeanConcreteLevelCombo();
            if (leanLevelCombo != null) leanLevelCombo.ItemsSource = items;
            if (WallBaseLevelCombo != null) WallBaseLevelCombo.ItemsSource = items;
            if (WallTopLevelCombo != null) WallTopLevelCombo.ItemsSource = items;
            if (BeamBaseLevelCombo != null) BeamBaseLevelCombo.ItemsSource = items;
            if (BeamTopLevelCombo != null) BeamTopLevelCombo.ItemsSource = items;
            if (SlabLevelCombo != null) SlabLevelCombo.ItemsSource = items;

            if (items.Count > 0)
            {
                if (BaseLevelCombo != null) BaseLevelCombo.SelectedIndex = 0;
                if (TopLevelCombo != null) TopLevelCombo.SelectedIndex = Math.Min(1, items.Count - 1);
                if (BaseLevelCombo_Bored != null) BaseLevelCombo_Bored.SelectedIndex = 0;
                if (TopLevelCombo_Bored != null) TopLevelCombo_Bored.SelectedIndex = Math.Min(1, items.Count - 1);
                if (FoundationLevelCombo_Foundation != null) FoundationLevelCombo_Foundation.SelectedIndex = 0;
                if (leanLevelCombo != null) leanLevelCombo.SelectedIndex = 0;
                if (WallBaseLevelCombo != null) WallBaseLevelCombo.SelectedIndex = 0;
                if (WallTopLevelCombo != null) WallTopLevelCombo.SelectedIndex = Math.Min(1, items.Count - 1);
                if (BeamBaseLevelCombo != null) BeamBaseLevelCombo.SelectedIndex = 0;
                if (BeamTopLevelCombo != null) BeamTopLevelCombo.SelectedIndex = Math.Min(1, items.Count - 1);
                if (SlabLevelCombo != null) SlabLevelCombo.SelectedIndex = 0;
            }
        }

