        public void UpdateFoundationSlabTypes(List<ComboItem> items)
        {
            System.Windows.Controls.ComboBox leanTypeCombo = GetLeanConcreteTypeCombo();
            if (FoundationSlabTypeCombo_Foundation == null && leanTypeCombo == null) return;

            ElementId foundationSelectedId = (FoundationSlabTypeCombo_Foundation?.SelectedItem as ComboItem)?.Id
                                             ?? Autodesk.Revit.DB.ElementId.InvalidElementId;
            ElementId leanSelectedId = (leanTypeCombo?.SelectedItem as ComboItem)?.Id
                                       ?? Autodesk.Revit.DB.ElementId.InvalidElementId;

            if (FoundationSlabTypeCombo_Foundation != null)
            {
                FoundationSlabTypeCombo_Foundation.ItemsSource = items;
            }
            if (leanTypeCombo != null)
            {
                leanTypeCombo.ItemsSource = items;
            }

            if (FoundationSlabTypeCombo_Foundation != null)
            {
                if (foundationSelectedId != Autodesk.Revit.DB.ElementId.InvalidElementId)
                {
                    ComboItem match = items.FirstOrDefault(i => i.Id == foundationSelectedId);
                    if (match != null)
                    {
                        FoundationSlabTypeCombo_Foundation.SelectedItem = match;
                    }
                }

                if (FoundationSlabTypeCombo_Foundation.SelectedItem == null && items.Count > 0)
                {
                    FoundationSlabTypeCombo_Foundation.SelectedIndex = 0;
                }
            }

            if (leanTypeCombo != null)
            {
                if (leanSelectedId != Autodesk.Revit.DB.ElementId.InvalidElementId)
                {
                    ComboItem match = items.FirstOrDefault(i => i.Id == leanSelectedId);
                    if (match != null)
                    {
                        leanTypeCombo.SelectedItem = match;
                    }
                }

                if (leanTypeCombo.SelectedItem == null && items.Count > 0)
                {
                    leanTypeCombo.SelectedIndex = 0;
                }
            }
        }

