        public void UpdateWallRebarSelectedHosts(IList<ElementId> hostIds, int wallCount, int floorCount)
        {
            _wallRebarSelectedHostElementIds.Clear();
            _wallRebarSelectedHostElementIds.AddRange((hostIds ?? Array.Empty<ElementId>())
                .Where(id => id != null && id != ElementId.InvalidElementId)
                .GroupBy(id => id.Value)
                .Select(g => g.First()));

            int total = _wallRebarSelectedHostElementIds.Count;
            if (WallNaviateStatusTextBlock != null)
            {
                WallNaviateStatusTextBlock.Text = total > 0
                    ? $"Selected {total} host(s): {wallCount} wall(s), {floorCount} floor(s)."
                    : "Please select wall/floor element(s) in view.";
            }

            UpdateWallRebarSelectionUiState();
        }

        public void UpdateFoundationRebarHostPreview(FoundationRebarHostPreviewData data)
        {
            _foundationRebarHostPreview = data;

            bool previousSuspend = _foundationRebarUiEventsSuspended;
            _foundationRebarUiEventsSuspended = true;
            try
            {
                if (FoundationRebarHostTextBox != null)
                {
                    FoundationRebarHostTextBox.Text = data == null || data.HostElementId == ElementId.InvalidElementId
                        ? "(not selected)"
                        : (string.IsNullOrWhiteSpace(data.HostDisplayName) ? $"Element {data.HostElementId.Value}" : data.HostDisplayName);
                }

                if (data != null && data.HostElementId != ElementId.InvalidElementId)
                {
                    if (!string.IsNullOrWhiteSpace(data.SuggestedTypeMode))
                    {
                        SetFoundationComboSelectionByText(FoundationRebarTypeModeCombo, data.SuggestedTypeMode);
                    }

                    SetFoundationText(FoundationRebarLengthMmTextBox, FeetToMmUi(Math.Max(0.0, data.LengthFt)).ToString("0.#", CultureInfo.InvariantCulture));
                    SetFoundationText(FoundationRebarWidthMmTextBox, FeetToMmUi(Math.Max(0.0, data.WidthFt)).ToString("0.#", CultureInfo.InvariantCulture));
                    SetFoundationText(FoundationRebarThicknessMmTextBox, FeetToMmUi(Math.Max(0.0, data.ThicknessFt)).ToString("0.#", CultureInfo.InvariantCulture));
                    SyncFoundationRebarPedestalFootprintFromDetectedColumn();
                }
            }
            finally
            {
                _foundationRebarUiEventsSuspended = previousSuspend;
            }

            _foundationRebarPreviewDirty = true;
            UpdateFoundationRebarDesignUiState();
            RenderFoundationRebarPreviewFromCurrentInputs(strictValidation: false, showStatusOnFailure: false);

            if (data != null && data.HostElementId != ElementId.InvalidElementId)
            {
                string suffix = "";
                if (data.DetectedColumnElementId != ElementId.InvalidElementId &&
                    data.DetectedColumnWidthFt > 1e-9 &&
                    data.DetectedColumnDepthFt > 1e-9)
                {
                    suffix =
                        $" Detected column {data.DetectedColumnElementId.Value} " +
                        $"-> Ped.W/Ped.B = {FeetToMmUi(data.DetectedColumnWidthFt):0.#}/{FeetToMmUi(data.DetectedColumnDepthFt):0.#} mm.";
                }

                ShowStatus($"FOUNDATION: selected host {data.HostElementId.Value}. Preview geometry synced from host.{suffix}");
            }
        }

        public void UpdateColumnRebarHostPreview(ColumnRebarHostPreviewData data)
        {
            _columnRebarHostPreview = data;
            _columnRebarSectionZoomFactor = 1.0;
            _columnRebarSectionPanXPx = 0.0;
            _columnRebarSectionPanYPx = 0.0;
            _columnRebarElevationZoomFactor = 1.0;
            _columnRebarElevationPanXPx = 0.0;
            _columnRebarElevationPanYPx = 0.0;
            _columnRebarElevationHoveredTieLevelIndex = -1;
            _columnRebarSectionSelectedTieXIndices.Clear();
            _columnRebarSectionSelectedTieYIndices.Clear();
            _columnRebarSectionCustomLineTies.Clear();
            _columnRebarSectionCustomRectTies.Clear();
            _columnRebarSectionPendingRectStartGridNode = null;
            _columnRebarSectionGridRenderState = null;
            _columnRebarElevationRenderState = null;

            var hostTextBox = GetColumnRebarHostTextBox();
            if (hostTextBox != null)
            {
                if (data == null || data.HostElementId == ElementId.InvalidElementId)
                {
                    hostTextBox.Text = "(not selected)";
                }
                else
                {
                    List<ElementId> selectedHostIds = (_handler?.Request?.ColumnRebarHostElementIds ?? new List<ElementId>())
                        .Where(x => x != null && x != ElementId.InvalidElementId)
                        .GroupBy(x => x.Value)
                        .Select(g => g.First())
                        .ToList();
                    List<string> selectedFloors = (_handler?.Request?.ColumnRebarSelectedFloorNames ?? new List<string>())
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .Select(x => x.Trim())
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                        .ToList();

                    string firstLabel = string.IsNullOrWhiteSpace(data.HostDisplayName)
                        ? $"Element {data.HostElementId.Value}"
                        : data.HostDisplayName;
                    if (selectedHostIds.Count > 1)
                    {
                        string floorsLabel = selectedFloors.Count > 0
                            ? $" | Floors: {string.Join(", ", selectedFloors)}"
                            : "";
                        hostTextBox.Text = $"{selectedHostIds.Count} columns selected (preview: {firstLabel}){floorsLabel}";
                    }
                    else
                    {
                        hostTextBox.Text = firstLabel;
                    }
                }
            }

            RefreshColumnRebarPreviewFromUi();

            if (data != null && data.HostElementId != ElementId.InvalidElementId)
            {
                int selectedCount = (_handler?.Request?.ColumnRebarHostElementIds ?? new List<ElementId>())
                    .Count(x => x != null && x != ElementId.InvalidElementId);
                int floorCount = (_handler?.Request?.ColumnRebarSelectedFloorNames ?? new List<string>())
                    .Count(x => !string.IsNullOrWhiteSpace(x));
                if (selectedCount > 1)
                {
                    string floorSuffix = floorCount > 0 ? $" across {floorCount} floor(s)" : "";
                    ShowStatus($"Column Rebar: selected {selectedCount} columns{floorSuffix}. Preview shows the first selected column ({data.HostElementId.Value}).");
                }
                else
                {
                    ShowStatus($"Column Rebar: selected host column {data.HostElementId.Value}.");
                }
            }
        }

