        public void ApplyColumnAutoSettings(string layerName, bool useCircles, bool useBlocks, bool useLines, int previewCount)
        {
            if (!string.IsNullOrWhiteSpace(layerName))
            {
                if (LayerModeRadio != null)
                {
                    LayerModeRadio.IsChecked = true;
                }

                if (LayerCombo != null)
                {
                    SelectComboItemByName(LayerCombo, layerName);
                }
            }

            if (CirclesCheck != null) CirclesCheck.IsChecked = useCircles;
            if (BlocksCheck != null) BlocksCheck.IsChecked = useBlocks;
            if (LinesCheck != null) LinesCheck.IsChecked = useLines;

            string layerLabel = string.IsNullOrWhiteSpace(layerName) ? "current selection" : $"'{layerName}'";
            ShowStatus($"Auto-Identify: Layer {layerLabel}. Preview: {previewCount} columns.");
            UpdateCad2ModelTasWorkflowRail();
        }

        public void ApplyColumnSidelinePick(string layerName, bool useCircles, bool useBlocks, bool useLines, int previewCount, bool byLayer)
        {
            if (byLayer)
            {
                if (LayerModeRadio != null)
                {
                    LayerModeRadio.IsChecked = true;
                }

                if (!string.IsNullOrWhiteSpace(layerName) && LayerCombo != null)
                {
                    SelectComboItemByName(LayerCombo, layerName);
                }
            }
            else if (SelectModeRadio != null)
            {
                SelectModeRadio.IsChecked = true;
            }

            if (CirclesCheck != null) CirclesCheck.IsChecked = useCircles;
            if (BlocksCheck != null) BlocksCheck.IsChecked = useBlocks;
            if (LinesCheck != null) LinesCheck.IsChecked = useLines;

            string sourceLabel = byLayer && !string.IsNullOrWhiteSpace(layerName)
                ? $"layer '{layerName}'"
                : "picked sideline selection";
            ShowStatus($"Pick Sideline: {sourceLabel}. Preview: {previewCount} column(s).");
            UpdateCad2ModelTasWorkflowRail();
        }

        public void ApplyColumnLabelPick(string layerName, int labelCount, bool byLayer)
        {
            if (byLayer && !string.IsNullOrWhiteSpace(layerName) && GetColumnLabelLayerCombo() != null)
            {
                SelectComboItemByName(GetColumnLabelLayerCombo(), layerName);
            }

            string sourceLabel = byLayer && !string.IsNullOrWhiteSpace(layerName)
                ? $"layer '{layerName}'"
                : "picked label selection";
            ShowStatus($"Pick Label: {sourceLabel}. Found {labelCount} label(s).");
            UpdateCad2ModelTasWorkflowRail();
        }

