        public void ShowStatus(string message)
        {
            _pendingStatusText = message ?? "";
            if (StatusText != null)
            {
                StatusText.Text = _pendingStatusText;
            }
        }

        public void BeginProgress(string title, string detail)
        {
            void show()
            {
                _progressCancelRequested = false;

                if (_progressDialog == null)
                {
                    _progressDialog = new ProgressDialogWindow
                    {
                        Owner = this
                    };
                    _progressDialog.CancelRequested += OnProgressCancelRequested;
                    _progressDialog.Closed += OnProgressDialogClosed;
                }

                _progressDialog.SetTitleText(title);
                _progressDialog.ResetCancelButton();
                _progressDialog.SetProgress(0, detail ?? "Preparing...");

                if (!_progressDialog.IsVisible)
                {
                    _progressDialog.Show();
                }
            }

            if (Dispatcher.CheckAccess())
            {
                show();
            }
            else
            {
                Dispatcher.Invoke(show);
            }

            PumpUi();
        }

        public void BeginProgress(string title, int total, string detail)
        {
            string initialDetail = detail ?? "Preparing...";
            if (total > 0)
            {
                initialDetail = $"{initialDetail} (0/{total})";
            }

            BeginProgress(title, initialDetail);
        }

        public void UpdateProgress(int processed, int total, string detail)
        {
            if (total <= 0) total = 1;
            int percent = (int)Math.Round((processed * 100.0) / total);
            if (percent < 0) percent = 0;
            if (percent > 100) percent = 100;

            void update()
            {
                if (_progressDialog == null) return;
                _progressDialog.SetProgress(percent, detail);
            }

            if (Dispatcher.CheckAccess())
            {
                update();
            }
            else
            {
                Dispatcher.Invoke(update);
            }

            PumpUi();
        }

        public bool IsProgressCancellationRequested()
        {
            if (Dispatcher.CheckAccess())
            {
                return _progressCancelRequested;
            }

            return Dispatcher.Invoke(() => _progressCancelRequested);
        }

        public void EndProgress()
        {
            void close()
            {
                if (_progressDialog != null && _progressDialog.IsVisible)
                {
                    _progressDialog.Hide();
                }
            }

            if (Dispatcher.CheckAccess())
            {
                close();
            }
            else
            {
                Dispatcher.Invoke(close);
            }

            PumpUi();
        }

        private void OnProgressCancelRequested(object sender, EventArgs e)
        {
            _progressCancelRequested = true;
            ShowStatus("Cancelling...");
        }

        private void OnProgressDialogClosed(object sender, EventArgs e)
        {
            _progressCancelRequested = true;
            if (_progressDialog != null)
            {
                _progressDialog.CancelRequested -= OnProgressCancelRequested;
                _progressDialog.Closed -= OnProgressDialogClosed;
            }
            _progressDialog = null;
        }

        private void PumpUi()
        {
            if (Dispatcher.CheckAccess())
            {
                Dispatcher.Invoke(DispatcherPriority.Background, new Action(() => { }));
            }
            else
            {
                Dispatcher.Invoke(() => Dispatcher.Invoke(DispatcherPriority.Background, new Action(() => { })));
            }
        }

        public void UpdateQsSummary(string message)
        {
            if (QsSummaryText != null)
            {
                QsSummaryText.Text = message ?? "";
            }
            UpdateQsOverviewKpis();
            ShowStatus(message);
        }

        internal void UpdateSiteProgressSummary(
            List<SiteProgressSummaryRow> combined,
            List<SiteProgressSummaryRow> byBuilding,
            string message,
            List<SiteProgressElementDetailRow> elementRows = null)
        {
            void update()
            {
                _siteProgressCombinedSourceRows = (combined ?? new List<SiteProgressSummaryRow>())
                    .Select(CloneSiteProgressRowShallow)
                    .ToList();
                _siteProgressElementRows = (elementRows ?? new List<SiteProgressElementDetailRow>())
                    .Select(CloneSiteProgressElementRowShallow)
                    .ToList();
                ApplySiteProgressPivot();

                _siteProgressByBuildingRows.Clear();
                foreach (SiteProgressSummaryRow row in byBuilding ?? new List<SiteProgressSummaryRow>())
                {
                    _siteProgressByBuildingRows.Add(row);
                }
                _siteProgressLastRefreshLocal = DateTime.Now;
                UpdateProgressDashboardStructureRows();

                if (SiteProgressSummaryText != null)
                {
                    SiteProgressSummaryText.Text = message ?? "";
                }

                PopulateSiteProgressBuildingFilterOptions();
                UpdateProgressDashboardCharts();
                UpdateSiteProgressTabTotals();
                RefreshPmDashboardSummaryAndChart();
            }

            if (Dispatcher.CheckAccess())
            {
                update();
            }
            else
            {
                Dispatcher.Invoke(update);
            }

            ShowStatus(message);

            if (_powerBiRefreshPipelinePending)
            {
                _powerBiRefreshPipelinePending = false;
                ExecutePowerBiRefreshPipelineFromCurrentRows();
            }

            if (_powerBiSummaryAllElementsPending)
            {
                _powerBiSummaryAllElementsPending = false;
                string summary = BuildPowerBiAllElementsSummaryText();
                SetPowerBiExportSummary(summary);
                ShowStatus("Power BI: All Elements summary updated.");
            }

            UpdatePowerBiRuntimeInfo();
        }

        private void ApplySiteProgressFiltersToRequest()
        {
            string structure = (SiteProgressStructureFilterCombo?.SelectedItem as string) ?? (SiteProgressStructureFilterCombo?.Text ?? "");
            string building = (SiteProgressBuildingLevelFilterCombo?.SelectedItem as string) ?? (SiteProgressBuildingLevelFilterCombo?.Text ?? "");

            if (string.IsNullOrWhiteSpace(structure)) structure = SiteProgressFilterAll;
            if (string.IsNullOrWhiteSpace(building)) building = SiteProgressFilterAll;

            _handler.Request.SiteProgressStructureFilter = structure.Trim();
            _handler.Request.SiteProgressBuildingLevelFilter = building.Trim();
        }

        private void PopulateSiteProgressBuildingFilterOptions()
        {
            if (SiteProgressBuildingLevelFilterCombo == null) return;

            string selected = SiteProgressBuildingLevelFilterCombo.SelectedItem as string;
            var options = new List<string> { SiteProgressFilterAll };
            options.AddRange(_siteProgressCombinedSourceRows
                .Select(r => r.BuildingLevel)
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(s => s, StringComparer.OrdinalIgnoreCase));

            SiteProgressBuildingLevelFilterCombo.ItemsSource = options;
            if (!string.IsNullOrWhiteSpace(selected) &&
                options.Any(o => string.Equals(o, selected, StringComparison.OrdinalIgnoreCase)))
            {
                SiteProgressBuildingLevelFilterCombo.SelectedItem =
                    options.First(o => string.Equals(o, selected, StringComparison.OrdinalIgnoreCase));
            }
            else
            {
                SiteProgressBuildingLevelFilterCombo.SelectedIndex = 0;
            }
        }

        private void ApplySiteProgressPivot()
        {
            List<SiteProgressSummaryRow> source = _siteProgressCombinedSourceRows ?? new List<SiteProgressSummaryRow>();
            SiteProgressPivotMode mode = GetSiteProgressPivotMode();
            SiteProgressPivotMetric metric = GetSiteProgressPivotMetric();

            List<SiteProgressSummaryRow> rows = BuildSiteProgressPivotRows(source, mode, metric);

            _siteProgressCombinedRows.Clear();
            foreach (SiteProgressSummaryRow row in rows)
            {
                _siteProgressCombinedRows.Add(row);
            }

            UpdateSiteProgressTabTotals();
            RefreshPmDetailProgressFilterOptions();
            ApplyPmDetailProgressFilters();
        }

        private SiteProgressPivotMode GetSiteProgressPivotMode()
        {
            string mode = SiteProgressPivotModeCombo?.SelectedItem as string;
            if (string.Equals(mode, "Pivot by BuildingLevel", StringComparison.OrdinalIgnoreCase)) return SiteProgressPivotMode.ByBuildingLevel;
            if (string.Equals(mode, "Pivot by Structure Element", StringComparison.OrdinalIgnoreCase)) return SiteProgressPivotMode.ByStructureElement;
            return SiteProgressPivotMode.ByFloorAndElement;
        }

        private SiteProgressPivotMetric GetSiteProgressPivotMetric()
        {
            string mode = SiteProgressPivotMetricCombo?.SelectedItem as string;
            if (string.Equals(mode, "Formwork(%)", StringComparison.OrdinalIgnoreCase)) return SiteProgressPivotMetric.Formwork;
            if (string.Equals(mode, "Reinforcement(%)", StringComparison.OrdinalIgnoreCase)) return SiteProgressPivotMetric.Reinforcement;
            return SiteProgressPivotMetric.Volume;
        }

        private SiteProgressDashboardValueMode GetSiteProgressDashboardValueMode()
        {
            string mode = SiteProgressDashboardValueModeCombo?.SelectedItem as string;
            if (string.Equals(mode, "Progress (%)", StringComparison.OrdinalIgnoreCase))
            {
                return SiteProgressDashboardValueMode.ProgressPercent;
            }

            return SiteProgressDashboardValueMode.AbsoluteBoq;
        }

        private static List<SiteProgressSummaryRow> BuildSiteProgressPivotRows(
            List<SiteProgressSummaryRow> rows,
            SiteProgressPivotMode pivotMode,
            SiteProgressPivotMetric metric)
        {
            rows = rows ?? new List<SiteProgressSummaryRow>();
            if (rows.Count == 0) return rows;

            if (pivotMode == SiteProgressPivotMode.ByFloorAndElement)
            {
                return rows
                    .Select(CloneSiteProgressRowShallow)
                    .OrderBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(r => GetSiteProgressStructureOrder(r.StructureElement))
                    .ThenBy(r => r.StructureElement, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(r => r.TypeName, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }

            IEnumerable<IGrouping<string, SiteProgressSummaryRow>> groups = pivotMode == SiteProgressPivotMode.ByBuildingLevel
                ? rows.GroupBy(r => r.BuildingLevel ?? "", StringComparer.OrdinalIgnoreCase)
                : rows.GroupBy(r => r.StructureElement ?? "", StringComparer.OrdinalIgnoreCase);

            var result = new List<SiteProgressSummaryRow>();
            foreach (IGrouping<string, SiteProgressSummaryRow> g in groups)
            {
                List<SiteProgressSummaryRow> items = g.ToList();
                if (items.Count == 0) continue;

                double reinfBoq = items.Sum(x => x.ReinforcementKg);
                double formBoq = items.Sum(x => x.FormworkM2);
                double volBoq = items.Sum(x => x.VolumeM3);
                double reinfCompleted = items.Sum(x => x.ReinforcementCompletedKg);
                double formCompleted = items.Sum(x => x.FormworkCompletedM2);
                double volCompleted = items.Sum(x => x.VolumeCompletedM3);

                double pReinf = reinfBoq > 1e-9 ? (reinfCompleted * 100.0 / reinfBoq) : 0.0;
                double pForm = formBoq > 1e-9 ? (formCompleted * 100.0 / formBoq) : 0.0;
                double pVol = volBoq > 1e-9 ? (volCompleted * 100.0 / volBoq) : 0.0;
                double progress = ResolveSiteProgressMetricPercent(metric, pReinf, pForm, pVol);
                string level = pivotMode == SiteProgressPivotMode.ByBuildingLevel ? g.Key : "(All Levels)";
                string element = pivotMode == SiteProgressPivotMode.ByStructureElement ? g.Key : "(All Elements)";
                if (string.IsNullOrWhiteSpace(level)) level = "Unassigned";
                if (string.IsNullOrWhiteSpace(element)) element = "Unassigned";

                result.Add(new SiteProgressSummaryRow
                {
                    GroupName = g.Key,
                    BuildingLevel = level,
                    StructureElement = element,
                    TypeName = "(All Types)",
                    ElementCount = items.Sum(x => x.ElementCount),
                    ReinforcementKg = reinfBoq,
                    FormworkM2 = formBoq,
                    VolumeM3 = volBoq,
                    SiteProgressReinforcementPercent = pReinf,
                    SiteProgressFormworkPercent = pForm,
                    SiteProgressVolumePercent = pVol,
                    ReinforcementCompletedKg = reinfCompleted,
                    FormworkCompletedM2 = formCompleted,
                    VolumeCompletedM3 = volCompleted,
                    ProgressPercent = progress,
                    Status = ResolveSiteProgressStatus(progress),
                    TotalBoq = volBoq,
                    CompletedBoq = volCompleted,
                    RemainingBoq = Math.Max(0.0, volBoq - volCompleted),
                    ElementIds = items
                        .SelectMany(x => x.ElementIds ?? new List<int>())
                        .Where(id => id > 0)
                        .Distinct()
                        .OrderBy(id => id)
                        .ToList()
                });
            }

            if (pivotMode == SiteProgressPivotMode.ByBuildingLevel)
            {
                return result
                    .OrderBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(r => GetSiteProgressStructureOrder(r.StructureElement))
                    .ToList();
            }

            return result
                .OrderBy(r => GetSiteProgressStructureOrder(r.StructureElement))
                .ThenBy(r => r.StructureElement, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static double ResolveSiteProgressMetricPercent(SiteProgressPivotMetric metric, double pReinf, double pForm, double pVol)
        {
            if (metric == SiteProgressPivotMetric.Reinforcement) return Math.Max(0.0, Math.Min(100.0, pReinf));
            if (metric == SiteProgressPivotMetric.Formwork) return Math.Max(0.0, Math.Min(100.0, pForm));
            return Math.Max(0.0, Math.Min(100.0, pVol));
        }

        private static string ResolveSiteProgressStatus(double progress)
        {
            if (progress >= 99.999) return "Completed";
            if (progress <= 0.001) return "Not Started";
            return "In Progress";
        }

        private static OxyColor GetDashboardTotalBarColor(double progressPercent)
        {
            if (progressPercent >= 99.999) return OxyColor.Parse("#4D9C66");
            if (progressPercent <= 0.001) return OxyColor.Parse("#2F75B5");
            return OxyColor.Parse("#3F82C2");
        }

        private static OxyColor GetDashboardCompletedBarColor(double progressPercent)
        {
            if (progressPercent >= 99.999) return OxyColor.Parse("#2E8B57");
            if (progressPercent <= 0.001) return OxyColor.Parse("#8EA6C7");
            return OxyColor.Parse("#E08C2E");
        }

        private static OxyColor GetDashboardRemainingBarColor(double progressPercent)
        {
            if (progressPercent >= 99.999) return OxyColor.Parse("#D9EBD9");
            if (progressPercent <= 0.001) return OxyColor.Parse("#C0504D");
            return OxyColor.Parse("#D47A46");
        }

        private static string BuildDashboardTotalBarLabel(SiteProgressDashboardPlotPoint point, bool percentMode)
        {
            if (point == null)
            {
                return "T:0";
            }

            double rawTotal = Math.Max(0.0, point.RawTotalBoq);
            double shownTotal = Math.Max(0.0, point.TotalBoq);
            if (percentMode)
            {
                double totalPercent = rawTotal > 1e-9 ? 100.0 : 0.0;
                return "T:" + totalPercent.ToString("0.#", CultureInfo.InvariantCulture) + "%";
            }

            return "T:" + FormatDashboardChartValue(shownTotal);
        }

        private static string BuildDashboardSeriesBarLabel(string seriesCode, double value, bool percentMode)
        {
            double safe = Math.Max(0.0, value);
            string prefix = string.IsNullOrWhiteSpace(seriesCode) ? "" : seriesCode.Trim() + ":";
            if (percentMode)
            {
                return prefix + safe.ToString("0.#", CultureInfo.InvariantCulture) + "%";
            }

            return prefix + FormatDashboardChartValue(safe);
        }

        private static void AddDashboardBarValueLabel(
            PlotModel model,
            double x0,
            double x1,
            double value,
            double axisMax,
            string label,
            OxyColor textColor,
            bool percentMode,
            int laneIndex,
            bool showWhenZero)
        {
            if (model == null || !(axisMax > 0.0) || string.IsNullOrWhiteSpace(label))
            {
                return;
            }

            double safeValue = Math.Max(0.0, value);
            if (!showWhenZero && safeValue <= 1e-9)
            {
                return;
            }

            double x = x0 + ((x1 - x0) * 0.5);
            int lane = Math.Max(0, laneIndex);
            double laneOffset = axisMax * (0.005 + (lane * 0.004));
            double baseOffset = percentMode ? axisMax * 0.012 : axisMax * 0.015;
            double y = safeValue + baseOffset + laneOffset;
            OxyPlot.VerticalAlignment verticalAlignment = OxyPlot.VerticalAlignment.Bottom;

            if (safeValue <= 1e-9)
            {
                y = axisMax * (0.016 + (lane * 0.01));
            }
            else
            {
                double nearTopThreshold = percentMode ? axisMax * 0.86 : axisMax * 0.93;
                if (safeValue >= nearTopThreshold)
                {
                    y = safeValue - (axisMax * (0.028 + (lane * 0.014)));
                    y = Math.Max(axisMax * 0.04, y);
                    verticalAlignment = OxyPlot.VerticalAlignment.Top;
                }
                else
                {
                    y = Math.Min(axisMax * 0.988, y);
                }
            }

            model.Annotations.Add(new TextAnnotation
            {
                Text = label,
                TextPosition = new DataPoint(x, y),
                TextHorizontalAlignment = OxyPlot.HorizontalAlignment.Center,
                TextVerticalAlignment = verticalAlignment,
                FontSize = 8.5,
                TextColor = textColor,
                Background = OxyColor.FromAColor(220, OxyColors.White),
                Stroke = OxyColor.Parse("#CED8E6"),
                StrokeThickness = 0.4
            });
        }

        private static System.Windows.Media.SolidColorBrush ToMediaBrush(OxyColor color)
        {
            var brush = new System.Windows.Media.SolidColorBrush(
                System.Windows.Media.Color.FromArgb(color.A, color.R, color.G, color.B));
            if (brush.CanFreeze)
            {
                brush.Freeze();
            }

            return brush;
        }

        private static int GetSiteProgressStructureOrder(string structure)
        {
            if (string.IsNullOrWhiteSpace(structure)) return 999;
            string s = structure.Trim();
            if (s.Equals("Structural Foundation", StringComparison.OrdinalIgnoreCase)) return 1;
            if (s.Equals("Structural Column", StringComparison.OrdinalIgnoreCase)) return 2;
            if (s.Equals("Wall", StringComparison.OrdinalIgnoreCase)) return 3;
            if (s.Equals("Structural Framing", StringComparison.OrdinalIgnoreCase)) return 4;
            if (s.Equals("Floor", StringComparison.OrdinalIgnoreCase)) return 5;
            if (s.Equals("Stair", StringComparison.OrdinalIgnoreCase)) return 6;
            return 999;
        }

        private static SiteProgressSummaryRow CloneSiteProgressRowShallow(SiteProgressSummaryRow row)
        {
            if (row == null) return new SiteProgressSummaryRow();
            return new SiteProgressSummaryRow
            {
                GroupName = row.GroupName,
                StructureElement = row.StructureElement,
                BuildingLevel = row.BuildingLevel,
                TypeName = row.TypeName,
                ElementTypeName = row.ElementTypeName,
                ElementCount = row.ElementCount,
                ReinforcementKg = row.ReinforcementKg,
                FormworkM2 = row.FormworkM2,
                VolumeM3 = row.VolumeM3,
                SiteProgressReinforcementPercent = row.SiteProgressReinforcementPercent,
                SiteProgressFormworkPercent = row.SiteProgressFormworkPercent,
                SiteProgressVolumePercent = row.SiteProgressVolumePercent,
                ReinforcementCompletedKg = row.ReinforcementCompletedKg,
                FormworkCompletedM2 = row.FormworkCompletedM2,
                VolumeCompletedM3 = row.VolumeCompletedM3,
                Status = row.Status,
                ProgressPercent = row.ProgressPercent,
                TotalBoq = row.TotalBoq,
                CompletedBoq = row.CompletedBoq,
                RemainingBoq = row.RemainingBoq,
                ElementIds = (row.ElementIds ?? new List<int>()).ToList()
            };
        }

        private static SiteProgressElementDetailRow CloneSiteProgressElementRowShallow(SiteProgressElementDetailRow row)
        {
            if (row == null) return new SiteProgressElementDetailRow();
            return new SiteProgressElementDetailRow
            {
                ElementId = row.ElementId,
                UniqueId = row.UniqueId,
                StructuralPlan = row.StructuralPlan,
                BuildingLevel = row.BuildingLevel,
                StructureElement = row.StructureElement,
                Category = row.Category,
                FamilyName = row.FamilyName,
                TypeName = row.TypeName,
                ReinforcementKg = row.ReinforcementKg,
                FormworkM2 = row.FormworkM2,
                VolumeM3 = row.VolumeM3,
                SiteProgressReinforcementPercent = row.SiteProgressReinforcementPercent,
                SiteProgressFormworkPercent = row.SiteProgressFormworkPercent,
                SiteProgressVolumePercent = row.SiteProgressVolumePercent,
                ReinforcementCompletedKg = row.ReinforcementCompletedKg,
                FormworkCompletedM2 = row.FormworkCompletedM2,
                VolumeCompletedM3 = row.VolumeCompletedM3,
                ProgressPercent = row.ProgressPercent,
                Status = row.Status
            };
        }

        private static BoqTableRow CloneBoqTableRowShallow(BoqTableRow row)
        {
            if (row == null)
            {
                return new BoqTableRow();
            }

            return new BoqTableRow
            {
                StructureElement = row.StructureElement ?? "",
                BuildingLevel = row.BuildingLevel ?? "",
                Room = row.Room ?? "",
                TypeName = row.TypeName ?? "",
                Quantity = row.Quantity,
                TotalVolumeM3 = row.TotalVolumeM3,
                TotalFormworkAreaM2 = row.TotalFormworkAreaM2,
                QsRuleCode = row.QsRuleCode ?? "",
                QsFormula = row.QsFormula ?? "",
                QsBreakdown = row.QsBreakdown ?? "",
                QsValues = CloneBoqQsValues(row),
                StructureOrder = row.StructureOrder
            };
        }

        private static Dictionary<string, double> CloneBoqQsValues(BoqTableRow row)
        {
            var values = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
            if (row?.QsValues == null)
            {
                return values;
            }

            foreach (KeyValuePair<string, double> pair in row.QsValues)
            {
                if (string.IsNullOrWhiteSpace(pair.Key) || Math.Abs(pair.Value) <= 1e-9)
                {
                    continue;
                }

                values[pair.Key] = pair.Value;
            }

            return values;
        }

        private static Dictionary<string, double> MergeBoqQsValues(IEnumerable<BoqTableRow> rows)
        {
            var values = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
            if (rows == null)
            {
                return values;
            }

            foreach (BoqTableRow row in rows)
            {
                if (row?.QsValues == null) continue;
                foreach (KeyValuePair<string, double> pair in row.QsValues)
                {
                    if (string.IsNullOrWhiteSpace(pair.Key) || Math.Abs(pair.Value) <= 1e-9)
                    {
                        continue;
                    }

                    double current;
                    values.TryGetValue(pair.Key, out current);
                    values[pair.Key] = current + pair.Value;
                }
            }

            return values;
        }

        private void UpdateProgressDashboardStructureRows()
        {
            SiteProgressPivotMetric metric = GetSiteProgressPivotMetric();
            var rows = (_siteProgressCombinedSourceRows ?? new List<SiteProgressSummaryRow>())
                .GroupBy(r => r.StructureElement ?? "", StringComparer.OrdinalIgnoreCase)
                .Select(g =>
                {
                    List<SiteProgressSummaryRow> items = g.ToList();
                    double totalBoq = items.Sum(r => GetSiteProgressMetricBoq(r, metric));
                    double completedBoq = items.Sum(r => GetSiteProgressMetricCompletedBoq(r, metric));
                    if (completedBoq < 0.0) completedBoq = 0.0;
                    if (completedBoq > totalBoq && totalBoq > 0.0) completedBoq = totalBoq;
                    double remainingBoq = Math.Max(0.0, totalBoq - completedBoq);
                    double progress = totalBoq > 1e-9 ? (completedBoq * 100.0 / totalBoq) : 0.0;
                    progress = Math.Max(0.0, Math.Min(100.0, progress));
                    string status = ResolveSiteProgressStatus(progress);

                    string structure = string.IsNullOrWhiteSpace(g.Key) ? "Unassigned" : g.Key;
                    return new SiteProgressSummaryRow
                    {
                        StructureElement = structure,
                        BuildingLevel = "(All Levels)",
                        TypeName = "(All Types)",
                        ElementCount = items.Sum(r => r.ElementCount),
                        TotalBoq = totalBoq,
                        CompletedBoq = completedBoq,
                        RemainingBoq = remainingBoq,
                        ProgressPercent = progress,
                        Status = status,
                        ElementIds = items
                            .SelectMany(r => r.ElementIds ?? new List<int>())
                            .Where(id => id > 0)
                            .Distinct()
                            .OrderBy(id => id)
                            .ToList()
                    };
                })
                .OrderBy(r => GetSiteProgressStructureOrder(r.StructureElement))
                .ThenBy(r => r.StructureElement, StringComparer.OrdinalIgnoreCase)
                .ToList();

            _siteProgressDashboardStructureRows.Clear();
            foreach (SiteProgressSummaryRow row in rows)
            {
                _siteProgressDashboardStructureRows.Add(row);
            }

            UpdateSiteProgressTabTotals();
        }

        private static double GetSiteProgressMetricBoq(SiteProgressSummaryRow row, SiteProgressPivotMetric metric)
        {
            if (row == null) return 0.0;
            if (metric == SiteProgressPivotMetric.Reinforcement) return row.ReinforcementKg;
            if (metric == SiteProgressPivotMetric.Formwork) return row.FormworkM2;
            return row.VolumeM3;
        }

        private static double GetSiteProgressMetricCompletedBoq(SiteProgressSummaryRow row, SiteProgressPivotMetric metric)
        {
            if (row == null) return 0.0;
            if (metric == SiteProgressPivotMetric.Reinforcement) return row.ReinforcementCompletedKg;
            if (metric == SiteProgressPivotMetric.Formwork) return row.FormworkCompletedM2;
            return row.VolumeCompletedM3;
        }

        private static string FormatDashboardChartValue(double value)
        {
            double abs = Math.Abs(value);
            if (abs >= 1000000.0) return (value / 1000000.0).ToString("0.##", CultureInfo.InvariantCulture) + "M";
            if (abs >= 1000.0) return (value / 1000.0).ToString("0.##", CultureInfo.InvariantCulture) + "K";
            return value.ToString("0.##", CultureInfo.InvariantCulture);
        }

        private void UpdateSiteProgressTabTotals()
        {
            if (SiteProgressCombinedTotalsText != null)
            {
                SiteProgressCombinedTotalsText.Text = BuildSiteProgressTotalsText(_siteProgressCombinedRows);
            }
            if (SiteProgressByBuildingTotalsText != null)
            {
                SiteProgressByBuildingTotalsText.Text = BuildSiteProgressTotalsText(_siteProgressByBuildingRows);
            }
            if (SiteProgressDashboardTotalsText != null)
            {
                SiteProgressDashboardTotalsText.Text = BuildSiteProgressDashboardTotalsText(_siteProgressDashboardStructureRows);
            }

            AutoFitSiteProgressGridHeaders();
        }

        private void AutoFitSiteProgressGridHeaders()
        {
            AutoFitDataGridHeaderWidths(SiteProgressCombinedGrid);
            AutoFitDataGridHeaderWidths(SiteProgressByBuildingGrid);
        }

        private static void AutoFitDataGridHeaderWidths(DataGrid grid)
        {
            if (grid == null || grid.Columns == null || grid.Columns.Count == 0)
            {
                return;
            }

            foreach (DataGridColumn column in grid.Columns)
            {
                if (column == null)
                {
                    continue;
                }

                if (column.MinWidth < 60.0)
                {
                    column.MinWidth = 60.0;
                }

                // Keep headers fully readable while letting users resize if needed.
                column.Width = new DataGridLength(1.0, DataGridLengthUnitType.SizeToHeader);
            }
        }

        private static string BuildSiteProgressTotalsText(IEnumerable<SiteProgressSummaryRow> rows)
        {
            List<SiteProgressSummaryRow> items = (rows ?? new List<SiteProgressSummaryRow>())
                .Where(r => r != null)
                .ToList();

            int rowCount = items.Count;
            int elementCount = items.Sum(r => Math.Max(0, r.ElementCount));

            double reinfBoq = items.Sum(r => Math.Max(0.0, r.ReinforcementKg));
            double formBoq = items.Sum(r => Math.Max(0.0, r.FormworkM2));
            double volBoq = items.Sum(r => Math.Max(0.0, r.VolumeM3));

            double reinfCompleted = items.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.ReinforcementKg), r.ReinforcementCompletedKg)));
            double formCompleted = items.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.FormworkM2), r.FormworkCompletedM2)));
            double volCompleted = items.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.VolumeM3), r.VolumeCompletedM3)));

            double reinfProgress = reinfBoq > 1e-9 ? (reinfCompleted * 100.0 / reinfBoq) : 0.0;
            double formProgress = formBoq > 1e-9 ? (formCompleted * 100.0 / formBoq) : 0.0;
            double volProgress = volBoq > 1e-9 ? (volCompleted * 100.0 / volBoq) : 0.0;

            return "Sum: Rows=" + rowCount.ToString(CultureInfo.InvariantCulture) +
                   " | Elements=" + elementCount.ToString(CultureInfo.InvariantCulture) +
                   " | Reinforcement: " + reinfCompleted.ToString("0.###", CultureInfo.InvariantCulture) + "/" + reinfBoq.ToString("0.###", CultureInfo.InvariantCulture) + " Kg (" + reinfProgress.ToString("0.##", CultureInfo.InvariantCulture) + "%)" +
                   " | Formwork: " + formCompleted.ToString("0.###", CultureInfo.InvariantCulture) + "/" + formBoq.ToString("0.###", CultureInfo.InvariantCulture) + " m2 (" + formProgress.ToString("0.##", CultureInfo.InvariantCulture) + "%)" +
                   " | Volume: " + volCompleted.ToString("0.###", CultureInfo.InvariantCulture) + "/" + volBoq.ToString("0.###", CultureInfo.InvariantCulture) + " m3 (" + volProgress.ToString("0.##", CultureInfo.InvariantCulture) + "%)";
        }

        private static string BuildSiteProgressDashboardTotalsText(IEnumerable<SiteProgressSummaryRow> rows)
        {
            List<SiteProgressSummaryRow> items = (rows ?? new List<SiteProgressSummaryRow>())
                .Where(r => r != null)
                .ToList();

            int rowCount = items.Count;
            int elementCount = items.Sum(r => Math.Max(0, r.ElementCount));
            double totalBoq = items.Sum(r => Math.Max(0.0, r.TotalBoq));
            double completedBoq = items.Sum(r => Math.Max(0.0, Math.Min(Math.Max(0.0, r.TotalBoq), r.CompletedBoq)));
            double remainingBoq = Math.Max(0.0, totalBoq - completedBoq);
            double progress = totalBoq > 1e-9 ? (completedBoq * 100.0 / totalBoq) : 0.0;
            progress = Math.Max(0.0, Math.Min(100.0, progress));

            return "Sum: Rows=" + rowCount.ToString(CultureInfo.InvariantCulture) +
                   " | Elements=" + elementCount.ToString(CultureInfo.InvariantCulture) +
                   " | Total BOQ=" + totalBoq.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Completed BOQ=" + completedBoq.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Remaining BOQ=" + remainingBoq.ToString("0.###", CultureInfo.InvariantCulture) +
                   " | Progress=" + progress.ToString("0.##", CultureInfo.InvariantCulture) + "%";
        }

        private void UpdateProgressDashboardCharts()
        {
            SiteProgressDashboardValueMode valueMode = GetSiteProgressDashboardValueMode();
            List<SiteProgressSummaryRow> structureRows = _siteProgressDashboardStructureRows
                .OrderByDescending(r => r.RemainingBoq)
                .ThenByDescending(r => r.TotalBoq)
                .ThenBy(r => r.StructureElement, StringComparer.OrdinalIgnoreCase)
                .ToList();
            RenderSiteProgressPlotChart(structureRows, valueMode);

            double totalBoq = structureRows.Sum(r => r.TotalBoq);
            double completedBoq = structureRows.Sum(r => r.CompletedBoq);
            if (completedBoq < 0.0) completedBoq = 0.0;
            if (completedBoq > totalBoq && totalBoq > 0.0) completedBoq = totalBoq;
            double remainingBoq = Math.Max(0.0, totalBoq - completedBoq);
            double siteProgress = (totalBoq > 1e-9 ? (completedBoq * 100.0 / totalBoq) : 0.0);
            siteProgress = Math.Max(0.0, Math.Min(100.0, siteProgress));
            if (FindName("DashboardOverallSummaryText") is TextBlock dashboardOverallSummaryText)
            {
                dashboardOverallSummaryText.Text = "Overall: " +
                    completedBoq.ToString("0.###", CultureInfo.InvariantCulture) + "/" +
                    totalBoq.ToString("0.###", CultureInfo.InvariantCulture) +
                    " (" + siteProgress.ToString("0.##", CultureInfo.InvariantCulture) + "%)";
            }

            OxyColor donutCompletedColor = GetDashboardCompletedBarColor(siteProgress);
            OxyColor donutRemainingColor = GetDashboardRemainingBarColor(siteProgress);
            RenderSiteProgressDonutChart(completedBoq, remainingBoq, donutCompletedColor, donutRemainingColor);
            System.Windows.Media.SolidColorBrush donutCompletedBrush = ToMediaBrush(donutCompletedColor);
            System.Windows.Media.SolidColorBrush donutRemainingBrush = ToMediaBrush(donutRemainingColor);

            if (DashboardDonutCenterPercentText != null)
            {
                DashboardDonutCenterPercentText.Text = siteProgress.ToString("0.##", CultureInfo.InvariantCulture) + "%";
            }
            if (DashboardLegendCompletedText != null)
            {
                DashboardLegendCompletedText.Text = "Complete: " + completedBoq.ToString("0.###", CultureInfo.InvariantCulture);
            }
            if (DashboardLegendCompletedSwatch != null)
            {
                DashboardLegendCompletedSwatch.Fill = donutCompletedBrush;
            }
            if (DashboardLegendRemainingText != null)
            {
                DashboardLegendRemainingText.Text = "Remaining: " + remainingBoq.ToString("0.###", CultureInfo.InvariantCulture);
            }
            if (DashboardLegendRemainingSwatch != null)
            {
                DashboardLegendRemainingSwatch.Fill = donutRemainingBrush;
            }

            UpdateDashboardKpiCards(completedBoq, remainingBoq, siteProgress);
            UpdateDashboardContextLine(valueMode);
        }

        private void RenderSiteProgressDonutChart(
            double completedBoq,
            double remainingBoq,
            OxyColor completedColor,
            OxyColor remainingColor)
        {
            if (SiteProgressDashboardDonutPlotView == null)
            {
                return;
            }

            double safeCompleted = Math.Max(0.0, completedBoq);
            double safeRemaining = Math.Max(0.0, remainingBoq);
            if (safeCompleted <= 1e-9 && safeRemaining <= 1e-9)
            {
                safeRemaining = 1.0;
            }

            var model = new PlotModel
            {
                Background = OxyColor.Parse("#F8FAFD"),
                PlotAreaBorderColor = OxyColors.Undefined,
                PlotAreaBorderThickness = new OxyThickness(0),
                Padding = new OxyThickness(0),
                PlotMargins = new OxyThickness(0),
                TextColor = OxyColor.Parse("#3C4B61"),
                IsLegendVisible = false
            };

            var donutSeries = new PieSeries
            {
                StartAngle = 270,
                AngleSpan = 360,
                InnerDiameter = 0.62,
                Stroke = OxyColor.Parse("#FFFFFF"),
                StrokeThickness = 1.0,
                OutsideLabelFormat = "",
                InsideLabelFormat = "",
                TickHorizontalLength = 0,
                TickRadialLength = 0
            };

            donutSeries.Slices.Add(new PieSlice("Complete", safeCompleted)
            {
                Fill = completedColor
            });
            donutSeries.Slices.Add(new PieSlice("Remaining", safeRemaining)
            {
                Fill = remainingColor
            });

            model.Series.Add(donutSeries);
            SiteProgressDashboardDonutPlotView.Model = model;
        }

        private void UpdateDashboardKpiCards(double completedBoq, double remainingBoq, double siteProgress)
        {
            if (DashboardKpiPercentCompleteText != null)
            {
                DashboardKpiPercentCompleteText.Text = siteProgress.ToString("0.##", CultureInfo.InvariantCulture) + "%";
            }
            if (DashboardKpiCompletedBoqText != null)
            {
                DashboardKpiCompletedBoqText.Text = completedBoq.ToString("0.###", CultureInfo.InvariantCulture);
            }
            if (DashboardKpiRemainingBoqText != null)
            {
                DashboardKpiRemainingBoqText.Text = remainingBoq.ToString("0.###", CultureInfo.InvariantCulture);
            }

            int totalElements = _siteProgressElementRows.Count;
            int updatedElements = _siteProgressElementRows.Count(r =>
                (r.SiteProgressReinforcementPercent > 1e-9) ||
                (r.SiteProgressFormworkPercent > 1e-9) ||
                (r.SiteProgressVolumePercent > 1e-9));
            if (DashboardKpiElementsUpdatedText != null)
            {
                DashboardKpiElementsUpdatedText.Text = updatedElements.ToString(CultureInfo.InvariantCulture) +
                    " / " + totalElements.ToString(CultureInfo.InvariantCulture);
            }

            if (DashboardKpiLastRefreshText != null)
            {
                DashboardKpiLastRefreshText.Text = _siteProgressLastRefreshLocal == DateTime.MinValue
                    ? "--"
                    : _siteProgressLastRefreshLocal.ToString("dd-MMM-yyyy HH:mm:ss", CultureInfo.InvariantCulture);
            }
        }

        private void UpdateDashboardContextLine(SiteProgressDashboardValueMode valueMode)
        {
            if (SiteProgressDashboardContextText == null) return;

            string structureFilter = (SiteProgressStructureFilterCombo?.SelectedItem as string) ??
                                     (SiteProgressStructureFilterCombo?.Text ?? SiteProgressFilterAll);
            if (string.IsNullOrWhiteSpace(structureFilter)) structureFilter = SiteProgressFilterAll;
            string buildingFilter = (SiteProgressBuildingLevelFilterCombo?.SelectedItem as string) ??
                                    (SiteProgressBuildingLevelFilterCombo?.Text ?? SiteProgressFilterAll);
            if (string.IsNullOrWhiteSpace(buildingFilter)) buildingFilter = SiteProgressFilterAll;

            string scopeText = SiteProgressScopeSelectionRadio?.IsChecked == true
                ? "Selection"
                : (SiteProgressScopeViewRadio?.IsChecked == true ? "Current View" : "Entire Model");
            string pivotText = (SiteProgressPivotModeCombo?.SelectedItem as string) ?? "Pivot by Floor + Element";
            string metricText = (SiteProgressPivotMetricCombo?.SelectedItem as string) ?? "Volume(%)";
            string valueModeText = valueMode == SiteProgressDashboardValueMode.ProgressPercent ? "Progress (%)" : "Absolute BOQ";

            SiteProgressDashboardContextText.Text =
                "Scope: " + scopeText +
                " | Pivot: " + pivotText +
                " | Metric: " + metricText +
                " | Value: " + valueModeText +
                " | Filters: Structure=" + structureFilter.Trim() +
                ", Building=" + buildingFilter.Trim();
        }

        private void RenderSiteProgressPlotChart(List<SiteProgressSummaryRow> structureRows, SiteProgressDashboardValueMode valueMode)
        {
            if (SiteProgressDashboardPlotView == null)
            {
                return;
            }

            bool percentMode = valueMode == SiteProgressDashboardValueMode.ProgressPercent;

            var points = new List<SiteProgressDashboardPlotPoint>();
            foreach (SiteProgressSummaryRow row in structureRows ?? new List<SiteProgressSummaryRow>())
            {
                double rawTotal = Math.Max(0.0, row.TotalBoq);
                double rawCompleted = Math.Max(0.0, Math.Min(rawTotal, row.CompletedBoq));
                double rawRemaining = Math.Max(0.0, rawTotal - rawCompleted);
                double progress = rawTotal > 1e-9 ? (rawCompleted * 100.0 / rawTotal) : 0.0;
                progress = Math.Max(0.0, Math.Min(100.0, progress));

                bool hasBoqBase = rawTotal > 1e-9;
                double total = percentMode ? (hasBoqBase ? 100.0 : 0.0) : rawTotal;
                double completed = percentMode ? (hasBoqBase ? progress : 0.0) : rawCompleted;
                double remaining = percentMode
                    ? (hasBoqBase ? Math.Max(0.0, 100.0 - completed) : 0.0)
                    : rawRemaining;

                points.Add(new SiteProgressDashboardPlotPoint
                {
                    Label = string.IsNullOrWhiteSpace(row.StructureElement) ? "Unassigned" : row.StructureElement,
                    TotalBoq = total,
                    CompletedBoq = completed,
                    RemainingBoq = remaining,
                    RawTotalBoq = rawTotal,
                    RawCompletedBoq = rawCompleted,
                    RawRemainingBoq = rawRemaining,
                    ProgressPercent = progress
                });
            }

            const double canvasHeight = 420.0;
            const double itemStep = 120.0;
            int itemCount = Math.Max(1, points.Count);
            double canvasWidth = Math.Max(900.0, 140.0 + (itemCount * itemStep));

            SiteProgressDashboardPlotView.Width = canvasWidth;
            SiteProgressDashboardPlotView.Height = canvasHeight;
            if (SiteProgressDashboardChartZoomHost != null)
            {
                SiteProgressDashboardChartZoomHost.Width = canvasWidth;
                SiteProgressDashboardChartZoomHost.MinHeight = canvasHeight;
            }

            bool hasData = points.Count > 0;
            if (SiteProgressDashboardChartScrollViewer != null)
            {
                SiteProgressDashboardChartScrollViewer.HorizontalScrollBarVisibility = hasData
                    ? ScrollBarVisibility.Auto
                    : ScrollBarVisibility.Disabled;
                SiteProgressDashboardChartScrollViewer.VerticalScrollBarVisibility = hasData
                    ? ScrollBarVisibility.Auto
                    : ScrollBarVisibility.Disabled;
            }

            double maxSeriesValue = points.Count == 0
                ? 1.0
                : points.Max(p => Math.Max(p.TotalBoq, Math.Max(p.CompletedBoq, p.RemainingBoq)));
            double axisMax = percentMode ? 100.0 : GetDashboardNiceUpperBound(maxSeriesValue);
            if (!(axisMax > 0.0))
            {
                axisMax = 1.0;
            }

            var model = new PlotModel
            {
                PlotAreaBorderColor = OxyColor.Parse("#D8E0EA"),
                PlotAreaBorderThickness = new OxyThickness(1),
                Background = OxyColor.Parse("#F8FAFD"),
                TextColor = OxyColor.Parse("#3C4B61"),
                PlotMargins = new OxyThickness(56, 14, 18, 58),
                IsLegendVisible = false
            };

            var xAxis = new LinearAxis
            {
                Position = AxisPosition.Bottom,
                Minimum = -0.5,
                Maximum = Math.Max(0.5, points.Count - 0.5),
                MajorStep = 1.0,
                MinorStep = 1.0,
                TicklineColor = OxyColor.Parse("#B6C3D4"),
                AxislineColor = OxyColor.Parse("#77879A"),
                TextColor = OxyColor.Parse("#3C4B61"),
                FontSize = 10,
                IsPanEnabled = false,
                IsZoomEnabled = false,
                LabelFormatter = x =>
                {
                    int idx = (int)Math.Round(x);
                    if (idx < 0 || idx >= points.Count)
                    {
                        return "";
                    }

                    if (Math.Abs(x - idx) > 0.25)
                    {
                        return "";
                    }

                    return ShortenDashboardStructureLabel(points[idx].Label);
                }
            };
            model.Axes.Add(xAxis);

            var valueAxis = new LinearAxis
            {
                Position = AxisPosition.Left,
                Minimum = 0.0,
                Maximum = axisMax,
                MajorGridlineStyle = LineStyle.Solid,
                MajorGridlineColor = OxyColor.Parse("#D8E0EA"),
                MinorGridlineStyle = LineStyle.None,
                TicklineColor = OxyColor.Parse("#B6C3D4"),
                AxislineColor = OxyColor.Parse("#77879A"),
                TextColor = OxyColor.Parse("#4B5A73"),
                FontSize = 10,
                IsPanEnabled = false,
                IsZoomEnabled = false,
                LabelFormatter = v => percentMode
                    ? v.ToString("0", CultureInfo.InvariantCulture) + "%"
                    : FormatDashboardChartValue(v)
            };
            model.Axes.Add(valueAxis);

            if (!hasData)
            {
                if (SiteProgressDashboardZoomXSlider != null && Math.Abs(SiteProgressDashboardZoomXSlider.Value - 1.0) > 1e-6)
                {
                    SiteProgressDashboardZoomXSlider.Value = 1.0;
                }
                if (SiteProgressDashboardZoomYSlider != null && Math.Abs(SiteProgressDashboardZoomYSlider.Value - 1.0) > 1e-6)
                {
                    SiteProgressDashboardZoomYSlider.Value = 1.0;
                }
                ApplySiteProgressDashboardChartZoom();

                model.Annotations.Add(new TextAnnotation
                {
                    Text = "No progress data available.",
                    TextPosition = new DataPoint(Math.Max(0.0, (points.Count - 1) * 0.5), axisMax * 0.5),
                    TextColor = OxyColor.Parse("#6E7C90"),
                    FontSize = 13,
                    Stroke = OxyColors.Undefined,
                    TextHorizontalAlignment = OxyPlot.HorizontalAlignment.Center
                });

                SiteProgressDashboardPlotView.Model = model;
                return;
            }

            var totalSeries = new RectangleBarSeries
            {
                Title = "Total BOQ",
                FillColor = OxyColor.Parse("#2F75B5"),
                StrokeColor = OxyColor.Parse("#255D91"),
                StrokeThickness = 0.6,
                TrackerFormatString = "{0}" + Environment.NewLine + "X: {2:0.##}" + Environment.NewLine + "Y: {4:0.###}"
            };
            var completedSeries = new RectangleBarSeries
            {
                Title = "Completed BOQ",
                FillColor = OxyColor.Parse("#5B9BD5"),
                StrokeColor = OxyColor.Parse("#3D79AF"),
                StrokeThickness = 0.6,
                TrackerFormatString = "{0}" + Environment.NewLine + "X: {2:0.##}" + Environment.NewLine + "Y: {4:0.###}"
            };
            var remainingSeries = new RectangleBarSeries
            {
                Title = "Remaining BOQ",
                FillColor = OxyColor.Parse("#C0504D"),
                StrokeColor = OxyColor.Parse("#8E3A38"),
                StrokeThickness = 0.6,
                TrackerFormatString = "{0}" + Environment.NewLine + "X: {2:0.##}" + Environment.NewLine + "Y: {4:0.###}"
            };

            for (int i = 0; i < points.Count; i++)
            {
                SiteProgressDashboardPlotPoint point = points[i];
                const double groupWidth = 0.72;
                double barWidth = groupWidth / 3.0;
                double groupStart = i - (groupWidth * 0.5);

                double totalX0 = groupStart;
                double totalX1 = totalX0 + barWidth;
                double completedX0 = totalX1;
                double completedX1 = completedX0 + barWidth;
                double remainingX0 = completedX1;
                double remainingX1 = remainingX0 + barWidth;

                OxyColor totalColor = GetDashboardTotalBarColor(point.ProgressPercent);
                OxyColor completedColor = GetDashboardCompletedBarColor(point.ProgressPercent);
                OxyColor remainingColor = GetDashboardRemainingBarColor(point.ProgressPercent);

                totalSeries.Items.Add(new RectangleBarItem(totalX0, 0.0, totalX1, point.TotalBoq)
                {
                    Color = totalColor
                });
                completedSeries.Items.Add(new RectangleBarItem(completedX0, 0.0, completedX1, point.CompletedBoq)
                {
                    Color = completedColor
                });
                remainingSeries.Items.Add(new RectangleBarItem(remainingX0, 0.0, remainingX1, point.RemainingBoq)
                {
                    Color = remainingColor
                });

                bool hasAnySeriesValue = (point.TotalBoq > 1e-9) || (point.CompletedBoq > 1e-9) || (point.RemainingBoq > 1e-9);
                if (hasAnySeriesValue)
                {
                    string totalLabel = BuildDashboardTotalBarLabel(point, percentMode);
                    string completedLabel = BuildDashboardSeriesBarLabel("C", point.CompletedBoq, percentMode);
                    string remainingLabel = BuildDashboardSeriesBarLabel("R", point.RemainingBoq, percentMode);

                    AddDashboardBarValueLabel(
                        model,
                        totalX0,
                        totalX1,
                        point.TotalBoq,
                        axisMax,
                        totalLabel,
                        OxyColor.Parse("#1F3552"),
                        percentMode,
                        0,
                        true);
                    AddDashboardBarValueLabel(
                        model,
                        completedX0,
                        completedX1,
                        point.CompletedBoq,
                        axisMax,
                        completedLabel,
                        OxyColor.Parse("#2A5D8F"),
                        percentMode,
                        1,
                        true);
                    AddDashboardBarValueLabel(
                        model,
                        remainingX0,
                        remainingX1,
                        point.RemainingBoq,
                        axisMax,
                        remainingLabel,
                        OxyColor.Parse("#8B3A36"),
                        percentMode,
                        2,
                        true);
                }
            }

            model.Series.Add(totalSeries);
            model.Series.Add(completedSeries);
            model.Series.Add(remainingSeries);
            SiteProgressDashboardPlotView.Model = model;
        }

        private static double GetDashboardNiceUpperBound(double value)
        {
            if (!(value > 0.0))
            {
                return 1.0;
            }

            double exponent = Math.Floor(Math.Log10(value));
            double magnitude = Math.Pow(10.0, exponent);
            double normalized = value / magnitude;
            double niceNormalized;
            if (normalized <= 1.0) niceNormalized = 1.0;
            else if (normalized <= 2.0) niceNormalized = 2.0;
            else if (normalized <= 5.0) niceNormalized = 5.0;
            else niceNormalized = 10.0;
            return niceNormalized * magnitude;
        }

        private static string ShortenDashboardStructureLabel(string label)
        {
            string text = (label ?? "").Trim();
            if (text.Length <= 14)
            {
                return text;
            }

            return text.Substring(0, 14) + "...";
        }

        internal void UpdateBoqRows(List<BoqTableRow> rows)
        {
            _boqAllRows = rows ?? new List<BoqTableRow>();
            PopulateBoqFilterOptions();
            PopulateBoqReportFilterOptions();
            ApplyBoqFilter();
            SyncPrepareBoqWithCurrentBoq(setMissingToZero: false);
            _ = TryAutoSyncBoqCsvAsync();
            _ = TryAutoSyncBoqExcelLinkAsync();
        }

        private void PopulateBoqFilterOptions()
        {
            string selectedElement = BoqElementFilterCombo?.SelectedItem as string;
            string selectedLevel = BoqBuildingLevelFilterCombo?.SelectedItem as string;

            var elementOptions = new List<string> { "All" };
            elementOptions.AddRange(_boqAllRows
                .Select(r => r.StructureElement)
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(s => GetBoqStructureOrder(s))
                .ThenBy(s => s, StringComparer.OrdinalIgnoreCase));

            if (BoqElementFilterCombo != null)
            {
                BoqElementFilterCombo.ItemsSource = elementOptions;
                if (!string.IsNullOrWhiteSpace(selectedElement) &&
                    elementOptions.Any(s => string.Equals(s, selectedElement, StringComparison.OrdinalIgnoreCase)))
                {
                    BoqElementFilterCombo.SelectedItem = elementOptions.First(s => string.Equals(s, selectedElement, StringComparison.OrdinalIgnoreCase));
                }
                else
                {
                    BoqElementFilterCombo.SelectedIndex = 0;
                }
            }

            var levelOptions = new List<string> { "All" };
            levelOptions.AddRange(_boqAllRows
                .Select(r => r.BuildingLevel)
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(s => s, StringComparer.OrdinalIgnoreCase));

            if (BoqBuildingLevelFilterCombo != null)
            {
                BoqBuildingLevelFilterCombo.ItemsSource = levelOptions;
                if (!string.IsNullOrWhiteSpace(selectedLevel) &&
                    levelOptions.Any(s => string.Equals(s, selectedLevel, StringComparison.OrdinalIgnoreCase)))
                {
                    BoqBuildingLevelFilterCombo.SelectedItem = levelOptions.First(s => string.Equals(s, selectedLevel, StringComparison.OrdinalIgnoreCase));
                }
                else
                {
                    BoqBuildingLevelFilterCombo.SelectedIndex = 0;
                }
            }
        }

        private void PopulateBoqReportFilterOptions()
        {
            string selectedFrom = BoqReportFloorFromCombo?.SelectedItem as string;
            string selectedTo = BoqReportFloorToCombo?.SelectedItem as string;
            string selectedQuantity = BoqReportQuantityScopeCombo?.SelectedItem as string;

            var levelOptions = new List<string> { BoqReportAllFloorsLabel };
            levelOptions.AddRange(GetBoqReportOrderedLevels(_boqAllRows));

            _boqReportFilterUiUpdating = true;
            try
            {
                ApplyBoqReportComboOptions(BoqReportFloorFromCombo, levelOptions, selectedFrom, BoqReportAllFloorsLabel);
                ApplyBoqReportComboOptions(BoqReportFloorToCombo, levelOptions, selectedTo, BoqReportAllFloorsLabel);
                ApplyBoqReportComboOptions(BoqReportQuantityScopeCombo, BoqReportQuantityScopeOptions, selectedQuantity, BoqReportAllQuantitiesLabel);
            }
            finally
            {
                _boqReportFilterUiUpdating = false;
            }
        }

        private static void ApplyBoqReportComboOptions(System.Windows.Controls.ComboBox combo, IEnumerable<string> options, string selected, string fallback)
        {
            if (combo == null) return;

            List<string> list = (options ?? Enumerable.Empty<string>())
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (list.Count == 0)
            {
                list.Add(fallback ?? "");
            }

            combo.ItemsSource = list;
            if (!string.IsNullOrWhiteSpace(selected) &&
                list.Any(s => string.Equals(s, selected, StringComparison.OrdinalIgnoreCase)))
            {
                combo.SelectedItem = list.First(s => string.Equals(s, selected, StringComparison.OrdinalIgnoreCase));
            }
            else
            {
                string preferred = string.IsNullOrWhiteSpace(fallback) ? list[0] : fallback;
                combo.SelectedItem = list.FirstOrDefault(s => string.Equals(s, preferred, StringComparison.OrdinalIgnoreCase)) ?? list[0];
            }
        }

        private void ApplyBoqFilter()
        {
            string elementFilter = BoqElementFilterCombo?.SelectedItem as string;
            string levelFilter = BoqBuildingLevelFilterCombo?.SelectedItem as string;

            IEnumerable<BoqTableRow> query = _boqAllRows;
            if (!string.IsNullOrWhiteSpace(elementFilter) &&
                !string.Equals(elementFilter, "All", StringComparison.OrdinalIgnoreCase))
            {
                query = query.Where(r => string.Equals(r.StructureElement, elementFilter, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(levelFilter) &&
                !string.Equals(levelFilter, "All", StringComparison.OrdinalIgnoreCase))
            {
                query = query.Where(r => string.Equals(r.BuildingLevel, levelFilter, StringComparison.OrdinalIgnoreCase));
            }

            List<BoqTableRow> filtered = query
                .ToList();

            BoqPivotMode pivotMode = GetBoqPivotMode();
            switch (pivotMode)
            {
                case BoqPivotMode.ByFloor:
                    filtered = filtered
                        .GroupBy(r => r.BuildingLevel ?? "", StringComparer.OrdinalIgnoreCase)
                        .Select(g => new BoqTableRow
                        {
                            StructureElement = "(All Elements)",
                            BuildingLevel = g.Key,
                            Room = "(All Rooms)",
                            TypeName = "(All Types)",
                            Quantity = g.Sum(x => x.Quantity),
                            TotalVolumeM3 = g.Sum(x => x.TotalVolumeM3),
                            TotalFormworkAreaM2 = g.Sum(x => x.TotalFormworkAreaM2),
                            QsRuleCode = CombineBoqAuditValues(g, x => x.QsRuleCode, 360),
                            QsFormula = CombineBoqAuditValues(g, x => x.QsFormula, 420),
                            QsBreakdown = CombineBoqAuditValues(g, x => x.QsBreakdown, 1000),
                            QsValues = MergeBoqQsValues(g),
                            StructureOrder = 0
                        })
                        .OrderBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    break;

                case BoqPivotMode.ByElement:
                    filtered = filtered
                        .GroupBy(r => $"{r.StructureOrder}|{r.StructureElement}", StringComparer.OrdinalIgnoreCase)
                        .Select(g =>
                        {
                            BoqTableRow first = g.First();
                            return new BoqTableRow
                            {
                                StructureElement = first.StructureElement,
                                BuildingLevel = "(All Levels)",
                                Room = "(All Rooms)",
                                TypeName = "(All Types)",
                                Quantity = g.Sum(x => x.Quantity),
                                TotalVolumeM3 = g.Sum(x => x.TotalVolumeM3),
                                TotalFormworkAreaM2 = g.Sum(x => x.TotalFormworkAreaM2),
                                QsRuleCode = CombineBoqAuditValues(g, x => x.QsRuleCode, 360),
                                QsFormula = CombineBoqAuditValues(g, x => x.QsFormula, 420),
                                QsBreakdown = CombineBoqAuditValues(g, x => x.QsBreakdown, 1000),
                                QsValues = MergeBoqQsValues(g),
                                StructureOrder = first.StructureOrder
                            };
                        })
                        .OrderBy(r => r.StructureOrder)
                        .ThenBy(r => r.StructureElement, StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    break;

                case BoqPivotMode.ByFloorAndElement:
                    filtered = filtered
                        .GroupBy(r => $"{r.StructureOrder}|{r.StructureElement}|{r.BuildingLevel}", StringComparer.OrdinalIgnoreCase)
                        .Select(g =>
                        {
                            BoqTableRow first = g.First();
                            return new BoqTableRow
                            {
                                StructureElement = first.StructureElement,
                                BuildingLevel = first.BuildingLevel,
                                Room = "(All Rooms)",
                                TypeName = "(All Types)",
                                Quantity = g.Sum(x => x.Quantity),
                                TotalVolumeM3 = g.Sum(x => x.TotalVolumeM3),
                                TotalFormworkAreaM2 = g.Sum(x => x.TotalFormworkAreaM2),
                                QsRuleCode = CombineBoqAuditValues(g, x => x.QsRuleCode, 360),
                                QsFormula = CombineBoqAuditValues(g, x => x.QsFormula, 420),
                                QsBreakdown = CombineBoqAuditValues(g, x => x.QsBreakdown, 1000),
                                QsValues = MergeBoqQsValues(g),
                                StructureOrder = first.StructureOrder
                            };
                        })
                        .OrderBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(r => r.StructureOrder)
                        .ToList();
                    break;

                case BoqPivotMode.ByFloorRoomElement:
                    filtered = filtered
                        .GroupBy(r => $"{r.StructureOrder}|{r.StructureElement}|{r.BuildingLevel}|{r.Room}", StringComparer.OrdinalIgnoreCase)
                        .Select(g =>
                        {
                            BoqTableRow first = g.First();
                            return new BoqTableRow
                            {
                                StructureElement = first.StructureElement,
                                BuildingLevel = first.BuildingLevel,
                                Room = string.IsNullOrWhiteSpace(first.Room) ? "(No Room)" : first.Room,
                                TypeName = "(All Types)",
                                Quantity = g.Sum(x => x.Quantity),
                                TotalVolumeM3 = g.Sum(x => x.TotalVolumeM3),
                                TotalFormworkAreaM2 = g.Sum(x => x.TotalFormworkAreaM2),
                                QsRuleCode = CombineBoqAuditValues(g, x => x.QsRuleCode, 360),
                                QsFormula = CombineBoqAuditValues(g, x => x.QsFormula, 420),
                                QsBreakdown = CombineBoqAuditValues(g, x => x.QsBreakdown, 1000),
                                QsValues = MergeBoqQsValues(g),
                                StructureOrder = first.StructureOrder
                            };
                        })
                        .OrderBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(r => r.Room, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(r => r.StructureOrder)
                        .ToList();
                    break;

                default:
                    filtered = filtered
                        .OrderBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(r => r.Room, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(r => r.StructureOrder)
                        .ThenBy(r => r.TypeName, StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    break;
            }

            _boqRows.Clear();
            foreach (BoqTableRow row in filtered)
            {
                _boqRows.Add(row);
            }

            if (BoqSummaryText != null)
            {
                int levelCount = filtered
                    .Select(r => r.BuildingLevel)
                    .Where(s => !string.IsNullOrWhiteSpace(s))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count();
                string modeText = pivotMode == BoqPivotMode.ByFloor
                    ? "Pivot Mode (Floor)"
                    : pivotMode == BoqPivotMode.ByElement
                        ? "Pivot Mode (Element)"
                        : pivotMode == BoqPivotMode.ByFloorAndElement
                            ? "Pivot Mode (Floor + Element)"
                            : pivotMode == BoqPivotMode.ByFloorRoomElement
                                ? "Pivot Mode (Floor + Room + Element)"
                                : "Detail Mode (with Type)";
                BoqSummaryText.Text = $"{modeText}. Tip: select cell(s) then Ctrl+C or drag to Excel / Prepare BOQ. Auto Sync writes to linked Excel or last CSV after Refresh/Generate.";
                UpdateBoqOverviewKpis(levelCount, modeText.Replace("Mode ", ""));
            }
            else
            {
                UpdateBoqOverviewKpis(levelCount: 0, modeText: "Detail (Type)");
            }

            RefreshBoqReportCategoryTree();
            ApplyBoqReport();
        }

        private void OnBoqReportRefreshClick(object sender, RoutedEventArgs e)
        {
            if ((_boqAllRows == null || _boqAllRows.Count == 0) && _boqRows.Count == 0)
            {
                ShowStatus("BOQ Report: refreshing source quantities...");
                OnBoqRefreshClick(sender, e);
                return;
            }

            RefreshBoqReportCategoryTree();
            ApplyBoqReport();
            ShowStatus($"BOQ Report refreshed: {_boqReportRows.Count} row(s).");
        }

        private void OnBoqReportAdaptiveClick(object sender, RoutedEventArgs e)
        {
            List<BoqReportColumnSpec> columns = (_boqReportColumns != null && _boqReportColumns.Count > 0)
                ? _boqReportColumns
                : GetBoqReportColumnSpecs(_boqReportMode);
            int columnCount = columns?.Count ?? 0;
            int pages = columnCount <= 7 ? 1 : (columnCount <= 12 ? 2 : 3);
            if (BoqReportAutoFitPagesText != null)
            {
                BoqReportAutoFitPagesText.Text = pages.ToString(CultureInfo.InvariantCulture);
            }

            ApplyBoqReport();
            ShowStatus("BOQ Report adaptive print width: " + pages.ToString(CultureInfo.InvariantCulture) + " page(s).");
        }

        private void OnBoqReportFilterChanged(object sender, SelectionChangedEventArgs e)
        {
            if (_boqReportFilterUiUpdating)
            {
                return;
            }

            if (sender == BoqReportQuantityScopeCombo)
            {
                _boqReportCategoryFilter = "";
            }

            RefreshBoqReportCategoryTree();
            ApplyBoqReport();

            if (IsLoaded)
            {
                ShowStatus("BOQ Report filter: " + GetBoqReportFilterSummary() + ".");
            }
        }

        private void OnBoqReportExportExcelClick(object sender, RoutedEventArgs e)
        {
            List<BoqReportExportSheet> sheets = BuildBoqReportExportSheets();
            int rowCount = sheets.Sum(s => s.Rows?.Count ?? 0);
            if (sheets.Count == 0 || rowCount == 0)
            {
                ShowStatus("No BOQ report rows to export.");
                return;
            }

            var dialog = new SaveFileDialog
            {
                Title = "Export BOQ Report Excel",
                Filter = "Excel Workbook (*.xlsx)|*.xlsx|All files (*.*)|*.*",
                FileName = "CBIM-BOQ-Report_" + DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture) + ".xlsx",
                AddExtension = true,
                DefaultExt = ".xlsx"
            };

            bool? result = dialog.ShowDialog(this);
            if (result != true || string.IsNullOrWhiteSpace(dialog.FileName))
            {
                return;
            }

            try
            {
                ExportBoqReportWorkbookToExcel(sheets, dialog.FileName);
                ShowStatus($"BOQ Report workbook exported: {dialog.FileName} ({sheets.Count} sheet(s), {rowCount} row(s)).");
            }
            catch (Exception ex)
            {
                ShowStatus("BOQ Report Excel export failed: " + ex.Message);
            }
        }

        private void OnBoqReportPrintClick(object sender, RoutedEventArgs e)
        {
            if (_boqReportRows.Count == 0 || BoqReportGrid == null)
            {
                ShowStatus("No BOQ report rows to print.");
                return;
            }

            try
            {
                var dialog = new PrintDialog();
                bool? result = dialog.ShowDialog();
                if (result == true)
                {
                    dialog.PrintVisual(BoqReportGrid, "CBIM BOQ Report");
                    ShowStatus("BOQ Report sent to printer/PDF.");
                }
            }
            catch (Exception ex)
            {
                ShowStatus("BOQ Report print failed: " + ex.Message);
            }
        }

        private void OnBoqReportTreeSelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (!(e.NewValue is TreeViewItem item) || item.Tag == null)
            {
                return;
            }

            string mode = Convert.ToString(item.Tag, CultureInfo.InvariantCulture) ?? "";
            if (string.IsNullOrWhiteSpace(mode))
            {
                return;
            }

            _boqReportMode = mode.Trim();
            ApplyBoqReport();
            ShowStatus("BOQ Report view: " + GetBoqReportModeTitle(_boqReportMode) + ".");
        }

        private void OnBoqReportCategoryTreeSelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
        {
            if (!(e.NewValue is BoqReportCategoryNode node))
            {
                return;
            }

            _boqReportCategoryFilter = node.Filter ?? "";
            ApplyBoqReport();
            ShowStatus("BOQ Report category: " + (string.IsNullOrWhiteSpace(node.Name) ? "All Categories" : node.Name) + ".");
        }

        private void RefreshBoqReportCategoryTree()
        {
            if (_boqReportCategoryNodes == null)
            {
                return;
            }

            string currentFilter = _boqReportCategoryFilter ?? "";
            List<BoqTableRow> source = GetBoqReportFilteredSourceRows();

            _boqReportCategoryNodes.Clear();
            _boqReportCategoryNodes.Add(new BoqReportCategoryNode
            {
                Name = "All Categories",
                Filter = ""
            });

            string[] categories =
            {
                "Column",
                "Wall",
                "Door/Window Opening",
                "Beam",
                "Slab",
                "Staircase",
                "Foundation",
                "Finishes",
                "Auxiliary Concrete",
                "Soil",
                "Other"
            };

            foreach (string category in categories)
            {
                List<BoqTableRow> categoryRows = source
                    .Where(r => string.Equals(NormalizeBoqReportCategoryName(r?.StructureElement), category, StringComparison.OrdinalIgnoreCase))
                    .ToList();

                if (categoryRows.Count == 0 &&
                    !IsPrimaryBoqReportCategory(category))
                {
                    continue;
                }

                var node = new BoqReportCategoryNode
                {
                    Name = categoryRows.Count > 0
                        ? category + " (" + categoryRows.Sum(r => r.Quantity).ToString(CultureInfo.InvariantCulture) + ")"
                        : category,
                    Filter = "category:" + category
                };

                foreach (var typeGroup in categoryRows
                    .GroupBy(r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName.Trim(), StringComparer.OrdinalIgnoreCase)
                    .OrderBy(g => g.Key, StringComparer.OrdinalIgnoreCase)
                    .Take(200))
                {
                    node.Children.Add(new BoqReportCategoryNode
                    {
                        Name = typeGroup.Key + " (" + typeGroup.Sum(r => r.Quantity).ToString(CultureInfo.InvariantCulture) + ")",
                        Filter = "type:" + category + "|" + typeGroup.Key
                    });
                }

                _boqReportCategoryNodes.Add(node);
            }

            if (!string.IsNullOrWhiteSpace(currentFilter) && !BoqReportCategoryFilterExists(currentFilter))
            {
                _boqReportCategoryFilter = "";
            }
        }

        private bool BoqReportCategoryFilterExists(string filter)
        {
            if (string.IsNullOrWhiteSpace(filter)) return true;

            foreach (BoqReportCategoryNode node in _boqReportCategoryNodes)
            {
                if (BoqReportCategoryFilterExists(node, filter)) return true;
            }

            return false;
        }

        private static bool BoqReportCategoryFilterExists(BoqReportCategoryNode node, string filter)
        {
            if (node == null) return false;
            if (string.Equals(node.Filter, filter, StringComparison.OrdinalIgnoreCase)) return true;
            foreach (BoqReportCategoryNode child in node.Children)
            {
                if (BoqReportCategoryFilterExists(child, filter)) return true;
            }

            return false;
        }

        private void ApplyBoqReport()
        {
            EnsureBoqReportModeDefaultCategory();
            List<BoqTableRow> source = GetBoqReportFilteredSourceRows()
                .Where(r => MatchesBoqReportCategoryFilter(r, _boqReportCategoryFilter))
                .ToList();

            List<BoqReportRow> rows = BuildBoqReportViewRows(source, _boqReportMode);
            ConfigureBoqReportSheet(_boqReportMode);

            _boqReportRows.Clear();
            foreach (BoqReportRow row in rows)
            {
                _boqReportRows.Add(row);
            }

            if (BoqReportGrid != null)
            {
                BoqReportGrid.Items.Refresh();
            }

            if (BoqReportEmptyStateText != null)
            {
                BoqReportEmptyStateText.Visibility = _boqReportRows.Count == 0
                    ? System.Windows.Visibility.Visible
                    : System.Windows.Visibility.Collapsed;
            }

            if (BoqReportSummaryText != null)
            {
                int sourceCount = source.Count;
                double volume = _boqReportRows.Sum(r => r.TotalVolumeM3);
                double formwork = _boqReportRows.Sum(r => r.TotalFormworkAreaM2);
                BoqReportSummaryText.Text =
                    GetBoqReportModeTitle(_boqReportMode) + " | " +
                    _boqReportRows.Count.ToString(CultureInfo.InvariantCulture) + " report row(s), " +
                    sourceCount.ToString(CultureInfo.InvariantCulture) + " source row(s), " +
                    "Volume " + volume.ToString("N3", CultureInfo.InvariantCulture) + " m3, " +
                    "Formwork " + formwork.ToString("N3", CultureInfo.InvariantCulture) + " m2 | " +
                    GetBoqReportFilterSummary() + ".";
            }

            if (BoqReportTitleText != null)
            {
                BoqReportTitleText.Text = GetBoqReportSheetTitle(_boqReportMode);
            }
            if (BoqReportProjectText != null)
            {
                BoqReportProjectText.Text = "Project Name: " + GetBoqReportProjectName();
            }
            if (BoqReportCompileDateText != null)
            {
                BoqReportCompileDateText.Text = "Compile Date: " + DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            }
        }

        private List<BoqReportRow> BuildBoqReportViewRows(List<BoqTableRow> source, string mode)
        {
            List<BoqReportRow> rows = BuildBoqReportRows(source ?? new List<BoqTableRow>(), mode);
            rows = AddBoqReportSubtotalRows(rows, mode);
            rows = EnsureBoqReportTemplateRows(rows, mode);
            PopulateBoqReportTemplateValues(rows, mode);
            return rows;
        }

        private List<BoqReportExportSheet> BuildBoqReportExportSheets()
        {
            List<BoqTableRow> source = GetBoqReportFilteredSourceRows();
            List<BoqReportExportSheetSpec> specs = BuildBoqReportExportSheetSpecs(source);
            var sheets = new List<BoqReportExportSheet>();
            string originalMode = _boqReportMode ?? "";
            string originalFilter = _boqReportCategoryFilter ?? "";

            try
            {
                foreach (BoqReportExportSheetSpec spec in specs)
                {
                    if (spec == null || string.IsNullOrWhiteSpace(spec.Mode))
                    {
                        continue;
                    }

                    _boqReportMode = spec.Mode;
                    _boqReportCategoryFilter = spec.CategoryFilter ?? "";

                    List<BoqTableRow> sheetSource = source
                        .Where(r => MatchesBoqReportCategoryFilter(r, _boqReportCategoryFilter))
                        .ToList();
                    List<BoqReportRow> rows = BuildBoqReportViewRows(sheetSource, spec.Mode);
                    if (rows.Count == 0)
                    {
                        continue;
                    }

                    sheets.Add(new BoqReportExportSheet
                    {
                        SheetName = spec.SheetName,
                        Title = GetBoqReportSheetTitle(spec.Mode),
                        Mode = spec.Mode,
                        CategoryFilter = spec.CategoryFilter ?? "",
                        Columns = GetBoqReportColumnSpecs(spec.Mode),
                        Rows = rows
                    });
                }
            }
            finally
            {
                _boqReportMode = originalMode;
                _boqReportCategoryFilter = originalFilter;
            }

            return sheets;
        }

        private List<BoqReportExportSheetSpec> BuildBoqReportExportSheetSpecs(List<BoqTableRow> source)
        {
            var specs = new List<BoqReportExportSheetSpec>();

            foreach (string category in GetBoqReportExportCategories(source))
            {
                specs.Add(new BoqReportExportSheetSpec
                {
                    Mode = "SummaryByElement",
                    CategoryFilter = "category:" + category,
                    SheetName = "QS-" + GetBoqReportCategorySheetToken(category)
                });
            }

            AddBoqReportExportSheetSpec(specs, "SummaryBySegmentation", "", "QS-Segmentation");
            AddBoqReportExportSheetSpec(specs, "SummaryColumn1", "", "Column-1");
            AddBoqReportExportSheetSpec(specs, "SummaryColumn2", "", "Column-2");
            AddBoqReportExportSheetSpec(specs, "SummaryDoorWindow", "", "Door-Window");
            AddBoqReportExportSheetSpec(specs, "SummaryWallFinish", "", "Wall-Finish");
            AddBoqReportExportSheetSpec(specs, "SummaryPStructure", "", "P-Structure");
            AddBoqReportExportSheetSpec(specs, "SummaryPFinishes", "", "P-Finishes");
            AddBoqReportExportSheetSpec(specs, "WorksheetExpression", "", "Worksheet-Expression");
            AddBoqReportExportSheetSpec(specs, "WorksheetWall", "", "Worksheet-Wall");
            AddBoqReportExportSheetSpec(specs, "IndexConcreteUnit", "", "Index-ConcreteUnit");
            AddBoqReportExportSheetSpec(specs, "IndexOverall", "", "Index-Overall");
            AddBoqReportExportSheetSpec(specs, "IndexConcreteGrade", "", "Index-ConcreteGrade");
            AddBoqReportExportSheetSpec(specs, "IndexSteelRatio", "", "Index-SteelRatio");
            AddBoqReportExportSheetSpec(specs, "SteelSummary", "", "Steel-Summary");
            AddBoqReportExportSheetSpec(specs, "SteelPlate", "", "Steel-Plate");
            AddBoqReportExportSheetSpec(specs, "SteelBolt", "", "Steel-Bolt");
            AddBoqReportExportSheetSpec(specs, "SteelAnchorBolt", "", "Steel-AnchorBolt");
            AddBoqReportExportSheetSpec(specs, "SteelShearStud", "", "Steel-ShearStud");
            AddBoqReportExportSheetSpec(specs, "MaterialTileSpec", "", "Tile-Spec");
            AddBoqReportExportSheetSpec(specs, "MaterialTileRoom", "", "Tile-Room");

            return specs;
        }

        private static void AddBoqReportExportSheetSpec(List<BoqReportExportSheetSpec> specs, string mode, string filter, string sheetName)
        {
            if (specs == null) return;
            specs.Add(new BoqReportExportSheetSpec
            {
                Mode = mode ?? "",
                CategoryFilter = filter ?? "",
                SheetName = sheetName ?? ""
            });
        }

        private static List<string> GetBoqReportExportCategories(IEnumerable<BoqTableRow> source)
        {
            var categories = new List<string>
            {
                "Column",
                "Wall",
                "Door/Window Opening",
                "Beam",
                "Slab",
                "Staircase",
                "Foundation"
            };

            foreach (string category in (source ?? Enumerable.Empty<BoqTableRow>())
                .Where(r => r != null)
                .Select(r => NormalizeBoqReportCategoryName(r.StructureElement))
                .Where(c => !string.IsNullOrWhiteSpace(c))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(GetBoqReportCategoryOrder)
                .ThenBy(c => c, StringComparer.OrdinalIgnoreCase))
            {
                if (!categories.Contains(category, StringComparer.OrdinalIgnoreCase))
                {
                    categories.Add(category);
                }
            }

            return categories;
        }

        private static string GetBoqReportCategorySheetToken(string category)
        {
            string text = (category ?? "").Trim();
            if (string.Equals(text, "Door/Window Opening", StringComparison.OrdinalIgnoreCase)) return "DoorWindow";
            if (string.Equals(text, "Auxiliary Concrete", StringComparison.OrdinalIgnoreCase)) return "AuxConcrete";
            if (string.Equals(text, "Staircase", StringComparison.OrdinalIgnoreCase)) return "Stair";
            if (string.IsNullOrWhiteSpace(text)) return "Other";

            text = Regex.Replace(text, @"[^A-Za-z0-9]+", "");
            return string.IsNullOrWhiteSpace(text) ? "Other" : text;
        }

        private void EnsureBoqReportModeDefaultCategory()
        {
            if (string.Equals(_boqReportMode, "SummaryByElement", StringComparison.OrdinalIgnoreCase) &&
                string.IsNullOrWhiteSpace(_boqReportCategoryFilter))
            {
                _boqReportCategoryFilter = "category:" + GetDefaultBoqReportCategoryForScope();
            }
        }

        private List<BoqTableRow> GetBoqReportFilteredSourceRows()
        {
            IEnumerable<BoqTableRow> query = (_boqAllRows != null && _boqAllRows.Count > 0)
                ? (IEnumerable<BoqTableRow>)_boqAllRows
                : (IEnumerable<BoqTableRow>)_boqRows;

            List<string> orderedLevels = GetBoqReportOrderedLevels(query);
            string floorFrom = BoqReportFloorFromCombo?.SelectedItem as string;
            string floorTo = BoqReportFloorToCombo?.SelectedItem as string;
            string quantityScope = BoqReportQuantityScopeCombo?.SelectedItem as string;

            query = query
                .Where(r => MatchesBoqReportFloorRange(r, orderedLevels, floorFrom, floorTo))
                .Where(r => MatchesBoqReportQuantityScope(r, quantityScope));

            return query
                .Where(r => r != null)
                .OrderBy(r => r.StructureOrder)
                .ThenBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.Room, StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.TypeName, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static List<string> GetBoqReportOrderedLevels(IEnumerable<BoqTableRow> rows)
        {
            return (rows ?? Enumerable.Empty<BoqTableRow>())
                .Where(r => r != null)
                .Select(r => r.BuildingLevel)
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(s => s, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static bool MatchesBoqReportFloorRange(BoqTableRow row, List<string> orderedLevels, string floorFrom, string floorTo)
        {
            if (row == null) return false;
            bool hasFrom = !IsAllBoqReportFloorFilter(floorFrom);
            bool hasTo = !IsAllBoqReportFloorFilter(floorTo);
            if (!hasFrom && !hasTo) return true;

            List<string> levels = orderedLevels ?? new List<string>();
            string level = (row.BuildingLevel ?? "").Trim();
            int rowIndex = IndexOfBoqReportLevel(levels, level);
            if (rowIndex < 0) return false;

            int fromIndex = hasFrom ? IndexOfBoqReportLevel(levels, floorFrom) : 0;
            int toIndex = hasTo ? IndexOfBoqReportLevel(levels, floorTo) : levels.Count - 1;
            if (fromIndex < 0) fromIndex = 0;
            if (toIndex < 0) toIndex = levels.Count - 1;
            if (fromIndex > toIndex)
            {
                int tmp = fromIndex;
                fromIndex = toIndex;
                toIndex = tmp;
            }

            return rowIndex >= fromIndex && rowIndex <= toIndex;
        }

        private static bool IsAllBoqReportFloorFilter(string value)
        {
            return string.IsNullOrWhiteSpace(value) ||
                   string.Equals(value, "All", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(value, BoqReportAllFloorsLabel, StringComparison.OrdinalIgnoreCase);
        }

        private static int IndexOfBoqReportLevel(List<string> levels, string level)
        {
            if (levels == null || string.IsNullOrWhiteSpace(level)) return -1;
            for (int i = 0; i < levels.Count; i++)
            {
                if (string.Equals(levels[i], level, StringComparison.OrdinalIgnoreCase))
                {
                    return i;
                }
            }

            return -1;
        }

        private static bool MatchesBoqReportQuantityScope(BoqTableRow row, string scope)
        {
            if (row == null) return false;
            string value = string.IsNullOrWhiteSpace(scope) ? BoqReportAllQuantitiesLabel : scope.Trim();
            if (string.Equals(value, BoqReportAllQuantitiesLabel, StringComparison.OrdinalIgnoreCase)) return true;

            if (string.Equals(value, "Concrete + Formwork", StringComparison.OrdinalIgnoreCase))
            {
                return IsBoqProjectStructureReportRow(row) &&
                       (row.TotalVolumeM3 > 1e-9 || row.TotalFormworkAreaM2 > 1e-9 || HasBoqRowQsPrefix(row, "FWK."));
            }

            if (string.Equals(value, "Concrete Volume", StringComparison.OrdinalIgnoreCase))
            {
                return IsBoqProjectStructureReportRow(row) && row.TotalVolumeM3 > 1e-9;
            }

            if (string.Equals(value, "Formwork Area", StringComparison.OrdinalIgnoreCase))
            {
                return row.TotalFormworkAreaM2 > 1e-9 || HasBoqRowQsPrefix(row, "FWK.");
            }

            if (string.Equals(value, "Steel / Rebar", StringComparison.OrdinalIgnoreCase))
            {
                return GetBoqRowQsValue(row, "Rebar.Weight") > 1e-9 ||
                       IsBoqSteelReportRow(row, "SteelSummary") ||
                       ContainsWord(row.StructureElement, "rebar") ||
                       ContainsWord(row.TypeName, "rebar");
            }

            if (string.Equals(value, "Finishes", StringComparison.OrdinalIgnoreCase))
            {
                return IsBoqFinishReportRow(row);
            }

            if (string.Equals(value, "Openings", StringComparison.OrdinalIgnoreCase))
            {
                return IsBoqDoorWindowReportRow(row);
            }

            if (string.Equals(value, "Soil / Excavation", StringComparison.OrdinalIgnoreCase))
            {
                return IsBoqReportCategory(row, "Soil") ||
                       ContainsWord(row.StructureElement, "excavation") ||
                       ContainsWord(row.TypeName, "excavation") ||
                       ContainsWord(row.QsRuleCode, "excavation");
            }

            return true;
        }

        private static bool HasBoqRowQsPrefix(BoqTableRow row, string prefix)
        {
            if (row?.QsValues == null || string.IsNullOrWhiteSpace(prefix)) return false;
            return row.QsValues.Any(pair =>
                pair.Value > 1e-9 &&
                pair.Key != null &&
                pair.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase));
        }

        private static double GetBoqRowQsValue(BoqTableRow row, string key)
        {
            if (row?.QsValues == null || string.IsNullOrWhiteSpace(key)) return 0.0;
            return row.QsValues.TryGetValue(key, out double value) ? value : 0.0;
        }

        private string GetDefaultBoqReportCategoryForScope()
        {
            string scope = BoqReportQuantityScopeCombo?.SelectedItem as string;
            if (string.Equals(scope, "Finishes", StringComparison.OrdinalIgnoreCase)) return "Finishes";
            if (string.Equals(scope, "Openings", StringComparison.OrdinalIgnoreCase)) return "Door/Window Opening";
            if (string.Equals(scope, "Soil / Excavation", StringComparison.OrdinalIgnoreCase)) return "Soil";
            return "Column";
        }

        private string GetBoqReportFilterSummary()
        {
            string from = (BoqReportFloorFromCombo?.SelectedItem as string) ?? BoqReportAllFloorsLabel;
            string to = (BoqReportFloorToCombo?.SelectedItem as string) ?? BoqReportAllFloorsLabel;
            string quantity = (BoqReportQuantityScopeCombo?.SelectedItem as string) ?? BoqReportAllQuantitiesLabel;

            string floorText;
            if (IsAllBoqReportFloorFilter(from) && IsAllBoqReportFloorFilter(to))
            {
                floorText = BoqReportAllFloorsLabel;
            }
            else if (IsAllBoqReportFloorFilter(from))
            {
                floorText = "Up to " + to;
            }
            else if (IsAllBoqReportFloorFilter(to))
            {
                floorText = "From " + from;
            }
            else
            {
                floorText = from + " to " + to;
            }

            return "Floors: " + floorText + ", Quantity: " + quantity;
        }

        private int GetBoqReportAutoFitPageCount()
        {
            string text = (BoqReportAutoFitPagesText?.Text ?? "").Trim();
            if (int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int pages))
            {
                return Math.Max(1, Math.Min(10, pages));
            }

            return 1;
        }

        private void ConfigureBoqReportSheet(string mode)
        {
            _boqReportColumns = GetBoqReportColumnSpecs(mode);
            if (BoqReportGrid == null)
            {
                return;
            }

            BoqReportGrid.Columns.Clear();
            foreach (BoqReportColumnSpec spec in _boqReportColumns)
            {
                var binding = new System.Windows.Data.Binding(spec.BindingPath ?? "");
                if (!string.IsNullOrWhiteSpace(spec.StringFormat))
                {
                    binding.StringFormat = spec.StringFormat;
                }

                var column = new DataGridTextColumn
                {
                    Header = spec.Header ?? "",
                    Binding = binding,
                    Width = new DataGridLength(Math.Max(40.0, spec.Width))
                };

                if (spec.IsNumeric)
                {
                    column.ElementStyle = CreateBoqReportRightAlignedCellStyle();
                }

                BoqReportGrid.Columns.Add(column);
            }
        }

        private static Style CreateBoqReportRightAlignedCellStyle()
        {
            var style = new Style(typeof(TextBlock));
            style.Setters.Add(new Setter(TextBlock.TextAlignmentProperty, TextAlignment.Right));
            style.Setters.Add(new Setter(TextBlock.PaddingProperty, new Thickness(4, 0, 4, 0)));
            return style;
        }

