                Col("Formwork (m2)", nameof(BoqReportRow.TotalFormworkAreaM2), 115, true, "{0:N3}"),
                Col("Rule Code", nameof(BoqReportRow.QsRuleCode), 150),
                Col("Formula / Breakdown", nameof(BoqReportRow.FormulaBreakdown), 300));
        }

        private static List<BoqReportColumnSpec> BoqReportCols(params BoqReportColumnSpec[] columns)
        {
            return (columns ?? Array.Empty<BoqReportColumnSpec>()).ToList();
        }

        private static BoqReportColumnSpec Col(string header, string bindingPath, double width, bool isNumeric = false, string stringFormat = "")
        {
            return new BoqReportColumnSpec
            {
                Header = header ?? "",
                BindingPath = bindingPath ?? "",
                Width = width,
                IsNumeric = isNumeric,
                StringFormat = stringFormat ?? ""
            };
        }

        private List<BoqReportRow> AddBoqReportSubtotalRows(List<BoqReportRow> rows, string mode)
        {
            if (rows == null || rows.Count == 0 || !ShouldBoqReportAddSubtotals(mode))
            {
                return rows ?? new List<BoqReportRow>();
            }

            var result = new List<BoqReportRow>();
            foreach (var group in rows.GroupBy(r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                .OrderBy(g => g.Key, StringComparer.OrdinalIgnoreCase))
            {
                result.AddRange(group);
                result.Add(BuildBoqReportSubtotalRow(group, "Subtotal", isTotal: false));
            }

            result.Add(BuildBoqReportSubtotalRow(rows, "Total", isTotal: true));
            return result;
        }

        private List<BoqReportRow> EnsureBoqReportTemplateRows(List<BoqReportRow> rows, string mode)
        {
            rows = rows ?? new List<BoqReportRow>();
            if (rows.Count > 0 || !ShouldBoqReportShowBlankTemplate(mode))
            {
                return rows;
            }

            string reportName = GetBoqReportModeTitle(mode);
            var result = new List<BoqReportRow>();
            for (int i = 0; i < 24; i++)
            {
                result.Add(new BoqReportRow
                {
                    ReportName = reportName,
                    BuildingLevel = "",
                    RowLabel = "",
                    TypeName = "",
                    Quantity = 0,
                    TotalVolumeM3 = 0.0,
                    TotalFormworkAreaM2 = 0.0
                });
            }

            if (IsBoqReportSteelMode(mode) ||
                string.Equals(mode, "MaterialTileSpec", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(mode, "MaterialTileRoom", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(mode, "SummaryDoorWindow", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(mode, "SummaryWallFinish", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(mode, "SummaryPFinishes", StringComparison.OrdinalIgnoreCase))
            {
                result.Insert(0, new BoqReportRow
                {
                    ReportName = reportName,
                    BuildingLevel = "",
                    RowLabel = "Subtotal",
                    TypeName = "Subtotal",
                    IsSubtotal = true
                });
                result.Insert(1, new BoqReportRow
                {
                    ReportName = reportName,
                    BuildingLevel = "Total",
                    RowLabel = "Total",
                    TypeName = "Total",
                    IsTotal = true
                });
            }

            return result;
        }

        private static bool ShouldBoqReportShowBlankTemplate(string mode)
        {
            if (string.Equals(mode, "SummaryByElement", StringComparison.OrdinalIgnoreCase)) return true;
            if (string.Equals(mode, "SummaryBySegmentation", StringComparison.OrdinalIgnoreCase)) return true;
            if (string.Equals(mode, "SummaryDoorWindow", StringComparison.OrdinalIgnoreCase)) return true;
            if (string.Equals(mode, "SummaryWallFinish", StringComparison.OrdinalIgnoreCase)) return true;
            if (string.Equals(mode, "SummaryPFinishes", StringComparison.OrdinalIgnoreCase)) return true;
            if (IsBoqReportSteelMode(mode)) return true;
            if (string.Equals(mode, "MaterialTileSpec", StringComparison.OrdinalIgnoreCase)) return true;
            if (string.Equals(mode, "MaterialTileRoom", StringComparison.OrdinalIgnoreCase)) return true;
            return false;
        }

        private static bool ShouldBoqReportAddSubtotals(string mode)
        {
            if (string.Equals(mode, "WorksheetExpression", StringComparison.OrdinalIgnoreCase)) return false;
            if (string.Equals(mode, "WorksheetWall", StringComparison.OrdinalIgnoreCase)) return true;
            if (IsBoqReportIndexMode(mode)) return false;
            if (IsBoqReportSteelMode(mode)) return true;
            if (string.Equals(mode, "MaterialTileSpec", StringComparison.OrdinalIgnoreCase)) return true;
            if (string.Equals(mode, "MaterialTileRoom", StringComparison.OrdinalIgnoreCase)) return true;
            return true;
        }

        private static BoqReportRow BuildBoqReportSubtotalRow(IEnumerable<BoqReportRow> rows, string label, bool isTotal)
        {
            List<BoqReportRow> list = rows?.Where(r => r != null).ToList() ?? new List<BoqReportRow>();
            var values = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
            foreach (BoqReportRow row in list)
            {
                if (row.QsValues == null) continue;
                foreach (KeyValuePair<string, double> pair in row.QsValues)
                {
                    double current;
                    values.TryGetValue(pair.Key, out current);
                    values[pair.Key] = current + pair.Value;
                }
            }

            return new BoqReportRow
            {
                ReportName = list.FirstOrDefault()?.ReportName ?? "",
                StructureElement = isTotal ? "" : list.FirstOrDefault()?.StructureElement ?? "",
                BuildingLevel = isTotal ? "Total" : list.FirstOrDefault()?.BuildingLevel ?? "",
                Room = "",
                TypeName = label,
                RowLabel = label,
                Quantity = list.Sum(r => r.Quantity),
                TotalVolumeM3 = list.Sum(r => r.TotalVolumeM3),
                TotalFormworkAreaM2 = list.Sum(r => r.TotalFormworkAreaM2),
                QsRuleCode = "",
                QsFormula = "",
                QsBreakdown = "",
                FormulaBreakdown = "",
                IsSubtotal = !isTotal,
                IsTotal = isTotal,
                QsValues = values
            };
        }

        private void PopulateBoqReportTemplateValues(List<BoqReportRow> rows, string mode)
        {
            if (rows == null)
            {
                return;
            }

            int serial = 1;
            string category = GetBoqReportActiveCategory();
            foreach (BoqReportRow row in rows)
            {
                string label = row.IsSubtotal || row.IsTotal
                    ? (row.RowLabel ?? row.TypeName ?? "")
                    : (string.IsNullOrWhiteSpace(row.TypeName) ? row.StructureElement : row.TypeName);

                row.RowLabel = label;
                row.Location = string.IsNullOrWhiteSpace(row.Room) ? row.BuildingLevel : row.Room;
                row.Material = ResolveBoqReportMaterial(row);
                row.Unit = ResolveBoqReportUnit(row, mode);

                double volume = row.TotalVolumeM3;
                double formwork = row.TotalFormworkAreaM2;
                double rebar = GetBoqReportValue(row, "Rebar.Weight");
                double area = GetBoqReportFirstValue(row, "HOST_AREA_COMPUTED", "Area", "CBIM_QsFinishArea", "CBIM_QsFinishGrossArea");

                row.Value01 = FormatBoqReportNumber(volume);
                row.Value02 = FormatBoqReportNumber(formwork);
                row.Value03 = row.Quantity > 0 ? row.Quantity.ToString(CultureInfo.InvariantCulture) : "";
                row.Value04 = FormatBoqReportNumber(rebar);
                row.Value05 = "";
                row.Value06 = "";
                row.Value07 = FormatBoqReportNumber(area);
                row.Value08 = "";
                row.Value09 = "";
                row.Value10 = "";
                row.Value11 = "";
                row.Value12 = "";

                if (string.Equals(mode, "SummaryColumn1", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(mode, "SummaryColumn2", StringComparison.OrdinalIgnoreCase))
                {
                    row.Material = "In-situ Concrete";
                    row.Value06 = FormatBoqReportNumber(GetBoqReportFirstValue(row, "FWK.Col.Stage.Basic", "FWK.Col.Sides"));
                }
                else if (string.Equals(mode, "SummaryDoorWindow", StringComparison.OrdinalIgnoreCase) ||
                         string.Equals(category, "Door/Window Opening", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value01 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Floor.Opening.Area", "FIN.WF.OpeningDeduct", "FIN.CF.OpeningDeduct", "FIN.FF.OpeningDeduct"));
                    row.Value02 = FormatBoqReportNumber(GetBoqReportFirstValue(row, "FWK.Floor.Opening.Count", "Quantity"));
                    row.Value03 = FormatBoqReportNumber(GetBoqReportValue(row, "Opening.Width", "Width"));
                    row.Value04 = FormatBoqReportNumber(GetBoqReportValue(row, "Opening.Height", "Height"));
                    row.Value05 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Floor.Opening.Girth"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Wall.OpeningSide", "FWK.Floor.OpeningSide"));
                }
                else if (string.Equals(mode, "SummaryWallFinish", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value01 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.WF.Area", "FIN.WF.Gross"));
                    row.Value02 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.WF.Return"));
                    row.Value03 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.WF.Area"));
                }
                else if (string.Equals(mode, "SummaryPStructure", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Col.Stage.Basic", "FWK.Beam.Stage.Basic", "FWK.Floor.StrutBasic", "FWK.Foun.SideArea.Staged"));
                }
                else if (string.Equals(mode, "SummaryPFinishes", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value01 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.FF.Area", "FIN.FF.Gross"));
                    row.Value02 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.CF.Area", "FIN.CF.Gross"));
                    row.Value03 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.CF.Return"));
                    row.Value04 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.SC.Area", "FIN.SC.Gross"));
                    row.Value05 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.SC.Return"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.WF.Area", "FIN.WF.Gross"));
                    row.Value07 = FormatBoqReportNumber(GetBoqReportValue(row, "FIN.WF.Return", "FIN.FF.Return"));
                    row.Value08 = row.Quantity > 0 ? row.Quantity.ToString(CultureInfo.InvariantCulture) : "";
                    row.Value12 = FormatBoqReportNumber(
                        GetBoqReportValue(row, "FIN.FF.Area", "FIN.CF.Area", "FIN.SC.Area", "FIN.WF.Area", "FIN.WP.Area"));
                }
                else if (string.Equals(mode, "WorksheetExpression", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value01 = serial.ToString(CultureInfo.InvariantCulture);
                    serial++;
                }
                else if (string.Equals(mode, "WorksheetWall", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value01 = FormatBoqReportNumber(volume);
                    row.Value03 = row.Quantity > 0 ? row.Quantity.ToString(CultureInfo.InvariantCulture) : "";
                    row.Value04 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Wall.NetLength", "FWK.Wall.Length"));
                    row.Value05 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Wall.Thickness", "Width"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Wall.OriginalHeight"));
                }
                else if (string.Equals(mode, "IndexConcreteUnit", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value08 = serial.ToString(CultureInfo.InvariantCulture);
                    serial++;
                    row.Value01 = FormatBoqReportNumber(volume);
                    row.Value02 = FormatBoqReportNumber(area);
                    row.Value03 = FormatBoqReportNumber(area > 1e-9 ? volume / area * 100.0 : 0.0);
                    SetConcreteGradeValues(row);
                }
                else if (string.Equals(mode, "IndexOverall", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value08 = row.Value08.Length == 0 ? serial.ToString(CultureInfo.InvariantCulture) : row.Value08;
                    serial++;
                    row.Value01 = FormatBoqReportNumber(row.Unit == "m2" ? formwork : volume);
                    row.Value02 = "";
                }
                else if (string.Equals(mode, "IndexConcreteGrade", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value01 = FormatBoqReportNumber(volume);
                    SetConcreteGradeValues(row);
                }
                else if (string.Equals(mode, "IndexSteelRatio", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value01 = FormatBoqReportNumber(volume);
                    row.Value04 = FormatBoqReportNumber(rebar);
                    row.Value05 = FormatBoqReportNumber(volume > 1e-9 ? rebar / volume : 0.0);
                }
                else if (IsBoqReportSteelMode(mode))
                {
                    row.Value03 = row.Quantity > 0 ? row.Quantity.ToString(CultureInfo.InvariantCulture) : "";
                    row.Value04 = FormatBoqReportNumber(rebar);
                    row.Value02 = FormatBoqReportNumber(formwork);
                }
                else if (string.Equals(mode, "MaterialTileSpec", StringComparison.OrdinalIgnoreCase) ||
                         string.Equals(mode, "MaterialTileRoom", StringComparison.OrdinalIgnoreCase))
                {
                    double netArea = GetBoqReportValue(row, "FIN.FF.Area", "FIN.WF.Area", "FIN.CF.Area", "FIN.SC.Area", "FIN.WP.Area");
                    row.Value01 = FormatBoqReportNumber(netArea, showZero: true);
                    row.Value02 = FormatBoqReportNumber(netArea, showZero: true);
                    row.Value03 = "0";
                    row.Value04 = row.Quantity > 0 ? row.Quantity.ToString(CultureInfo.InvariantCulture) : "0";
                    row.Value05 = "0.00";
                }
                else if (string.Equals(category, "Column", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value05 = FormatBoqReportNumber(EstimateBoqReportGirth(row, "Column"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Col.Stage.Basic"));
                }
                else if (string.Equals(category, "Wall", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value03 = row.Quantity > 0 ? row.Quantity.ToString(CultureInfo.InvariantCulture) : "";
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Wall.OriginalHeight"));
                    row.Value07 = FormatBoqReportNumber(area);
                    row.Value08 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Wall.NetLength", "FWK.Wall.Length"));
                }
                else if (string.Equals(category, "Beam", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value05 = FormatBoqReportNumber(EstimateBoqReportGirth(row, "Beam"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Beam.Stage.1", "FWK.Beam.Stage.Basic"));
                    row.Value07 = FormatBoqReportNumber(GetBoqReportValue(row, "CBIM_Beam_Length"));
                    row.Value08 = FormatBoqReportNumber(GetBoqReportValue(row, "CBIM_Beam_Length"));
                }
                else if (string.Equals(category, "Slab", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value02 = FormatBoqReportNumber(GetBoqReportFirstValue(row, "FWK.Floor.Bottom", "FWK.Floor.StrutSoffit", "FWK.Floor.Total"));
                    row.Value05 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Floor.EdgeBreak.Lte250", "FWK.Floor.EdgeBreak.Lte500", "FWK.Floor.EdgeBreak.Lte1000"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Floor.StrutBasic", "FWK.Floor.StrutStageArea", "FWK.Floor.StrutStage.1", "FWK.Floor.StrutStage.2", "FWK.Floor.StrutStage.3", "FWK.Floor.StrutStage.4"));
                    row.Value08 = FormatBoqReportNumber(area);
                }
                else if (string.Equals(category, "Staircase", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value02 = FormatBoqReportNumber(GetBoqReportFirstValue(row, "FWK.Stair.Painting", "FWK.Stair.Total"));
                    row.Value03 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Stair.StepCount"));
                    row.Value05 = FormatBoqReportNumber(GetBoqReportFirstValue(row, "FWK.Stair.PaintingSide", "FWK.Stair.Sides"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Stair.PaintingSide"));
                    row.Value07 = FormatBoqReportNumber(GetBoqReportFirstValue(row, "FWK.Stair.PaintingBottom", "FWK.Stair.Bottom"));
                }
                else if (string.Equals(category, "Foundation", StringComparison.OrdinalIgnoreCase))
                {
                    row.Value05 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Foun.Sides"));
                    row.Value06 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Foun.Top"));
                    row.Value07 = FormatBoqReportNumber(GetBoqReportValue(row, "FWK.Foun.Top"));
                    row.Value08 = FormatBoqReportNumber(area);
                }
            }
        }

        private static void SetConcreteGradeValues(BoqReportRow row)
        {
            string grade = GuessBoqReportConcreteGrade(row);
            row.Value04 = string.Equals(grade, "C20", StringComparison.OrdinalIgnoreCase) ? FormatBoqReportNumber(row.TotalVolumeM3) : "";
            row.Value05 = string.Equals(grade, "C25", StringComparison.OrdinalIgnoreCase) ? FormatBoqReportNumber(row.TotalVolumeM3) : "";
            row.Value06 = string.Equals(grade, "C30", StringComparison.OrdinalIgnoreCase) || string.IsNullOrWhiteSpace(grade) ? FormatBoqReportNumber(row.TotalVolumeM3) : "";
        }

        private static string GuessBoqReportConcreteGrade(BoqReportRow row)
        {
            string text = ((row?.TypeName ?? "") + " " + (row?.RowLabel ?? "") + " " + (row?.QsRuleCode ?? "")).ToUpperInvariant();
            if (text.Contains("C20")) return "C20";
            if (text.Contains("C25")) return "C25";
            if (text.Contains("C30")) return "C30";
            return "";
        }

        private static string FormatBoqReportNumber(double value, int decimals = 3, bool showZero = false)
        {
            if (Math.Abs(value) <= 1e-9 && !showZero)
            {
                return "";
            }

            return value.ToString("N" + Math.Max(0, decimals).ToString(CultureInfo.InvariantCulture), CultureInfo.InvariantCulture);
        }

        private static double GetBoqReportValue(BoqReportRow row, params string[] names)
        {
            if (row == null || names == null || names.Length == 0)
            {
                return 0.0;
            }

            double sum = 0.0;
            bool matched = false;
            foreach (string name in names)
            {
                if (string.IsNullOrWhiteSpace(name)) continue;
                if (string.Equals(name, "Quantity", StringComparison.OrdinalIgnoreCase))
                {
                    sum += row.Quantity;
                    matched = true;
                    continue;
                }

                if (row.QsValues != null && row.QsValues.TryGetValue(name, out double value))
                {
                    sum += value;
                    matched = true;
                }
            }

            return matched ? sum : 0.0;
        }

        private static double GetBoqReportFirstValue(BoqReportRow row, params string[] names)
        {
            if (row == null || names == null || names.Length == 0)
            {
                return 0.0;
            }

            foreach (string name in names)
            {
                if (string.IsNullOrWhiteSpace(name)) continue;
                if (string.Equals(name, "Quantity", StringComparison.OrdinalIgnoreCase))
                {
                    if (row.Quantity > 0) return row.Quantity;
                    continue;
                }

                if (row.QsValues != null &&
                    row.QsValues.TryGetValue(name, out double value) &&
                    Math.Abs(value) > 1e-9)
                {
                    return value;
                }
            }

            return 0.0;
        }

        private static double EstimateBoqReportGirth(BoqReportRow row, string category)
        {
            if (row == null)
            {
                return 0.0;
            }

            if (string.Equals(category, "Beam", StringComparison.OrdinalIgnoreCase))
            {
                double width = GetBoqReportValue(row, "CBIM_Beam_Width");
                double depth = GetBoqReportValue(row, "CBIM_Beam_Depth");
                if (width > 1e-9 && depth > 1e-9)
                {
                    return 2.0 * (width + depth);
                }
            }

            return 0.0;
        }

        private static string ResolveBoqReportMaterial(BoqReportRow row)
        {
            if (row == null) return "";
            string category = NormalizeBoqReportCategoryName(row.StructureElement);
            if (IsBoqProjectStructureReportRow(new BoqTableRow { StructureElement = row.StructureElement }))
            {
                return "In-situ Concrete";
            }

            if (string.Equals(category, "Finishes", StringComparison.OrdinalIgnoreCase))
            {
                return "Finish";
            }

            if (IsBoqSteelReportRow(new BoqTableRow { StructureElement = row.StructureElement, TypeName = row.TypeName, QsRuleCode = row.QsRuleCode }, "SteelSummary"))
            {
                return "Steel";
            }

            return "";
        }

        private static string ResolveBoqReportUnit(BoqReportRow row, string mode)
        {
            if (row == null) return "";
            if (!string.IsNullOrWhiteSpace(row.Unit)) return row.Unit;
            if (string.Equals(mode, "IndexOverall", StringComparison.OrdinalIgnoreCase))
            {
                string category = NormalizeBoqReportCategoryName(row.StructureElement);
                return string.Equals(category, "Wall", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(category, "Column", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(category, "Beam", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(category, "Slab", StringComparison.OrdinalIgnoreCase) ||
                       string.Equals(category, "Foundation", StringComparison.OrdinalIgnoreCase)
                    ? "m3"
                    : "m2";
            }

            return "";
        }

        private string GetBoqReportActiveCategory()
        {
            string filter = (_boqReportCategoryFilter ?? "").Trim();
            if (filter.StartsWith("category:", StringComparison.OrdinalIgnoreCase))
            {
                return filter.Substring("category:".Length).Trim();
            }

            if (filter.StartsWith("type:", StringComparison.OrdinalIgnoreCase))
            {
                string raw = filter.Substring("type:".Length);
                int idx = raw.IndexOf('|');
                return idx >= 0 ? raw.Substring(0, idx).Trim() : raw.Trim();
            }

            if (string.Equals(_boqReportMode, "SummaryColumn1", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(_boqReportMode, "SummaryColumn2", StringComparison.OrdinalIgnoreCase))
            {
                return "Column";
            }

            return "";
        }

        private string GetBoqReportSheetTitle(string mode)
        {
            string category = GetBoqReportActiveCategory();
            if (string.Equals(mode, "SummaryByElement", StringComparison.OrdinalIgnoreCase) &&
                !string.IsNullOrWhiteSpace(category))
            {
                return "Quantity Summary - " + GetBoqReportCategorySheetName(category);
            }

            return GetBoqReportModeTitle(mode);
        }

        private static string GetBoqReportCategorySheetName(string category)
        {
            if (string.Equals(category, "Door/Window Opening", StringComparison.OrdinalIgnoreCase)) return "Wall Opening";
            if (string.Equals(category, "Slab", StringComparison.OrdinalIgnoreCase)) return "In-situ Slab";
            if (string.Equals(category, "Staircase", StringComparison.OrdinalIgnoreCase)) return "Straight Flight";
            if (string.Equals(category, "Foundation", StringComparison.OrdinalIgnoreCase)) return "Raft Foundation";
            return string.IsNullOrWhiteSpace(category) ? "Element" : category;
        }

        private static string GetBoqReportProjectName()
        {
            return "Template";
        }

        private List<BoqReportRow> BuildBoqReportRows(List<BoqTableRow> source, string mode)
        {
            string reportName = GetBoqReportModeTitle(mode);
            List<BoqTableRow> rows = source ?? new List<BoqTableRow>();

            if (string.Equals(mode, "WorksheetExpression", StringComparison.OrdinalIgnoreCase))
            {
                return rows
                    .Select(r => ToBoqReportRow(reportName, r))
                    .OrderBy(r => GetBoqStructureOrder(r.StructureElement))
                    .ThenBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(r => r.Room, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(r => r.TypeName, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }

            if (string.Equals(mode, "WorksheetWall", StringComparison.OrdinalIgnoreCase))
            {
                return rows
                    .Where(r => IsBoqReportCategory(r, "Wall"))
                    .Select(r => ToBoqReportRow(reportName, r))
                    .ToList();
            }

            if (string.Equals(mode, "SummaryBySegmentation", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows,
                    reportName,
                    r => NormalizeBoqReportCategoryName(r.StructureElement),
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => string.IsNullOrWhiteSpace(r.Room) ? "(All Rooms)" : r.Room,
                    r => "(All Types)");
            }

            if (string.Equals(mode, "SummaryColumn1", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(r => IsBoqReportCategory(r, "Column")),
                    reportName,
                    r => "Column",
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => "(All Rooms)",
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            if (string.Equals(mode, "SummaryColumn2", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(r => IsBoqReportCategory(r, "Column")),
                    reportName,
                    r => "Column",
                    r => "(All Levels)",
                    r => "(All Rooms)",
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            if (string.Equals(mode, "SummaryDoorWindow", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(IsBoqDoorWindowReportRow),
                    reportName,
                    r => NormalizeBoqReportCategoryName(r.StructureElement),
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => string.IsNullOrWhiteSpace(r.Room) ? "(All Rooms)" : r.Room,
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            if (string.Equals(mode, "SummaryWallFinish", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(IsBoqWallFinishReportRow),
                    reportName,
                    r => r.StructureElement,
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => string.IsNullOrWhiteSpace(r.Room) ? "(All Rooms)" : r.Room,
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            if (string.Equals(mode, "SummaryPStructure", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(IsBoqProjectStructureReportRow),
                    reportName,
                    r => NormalizeBoqReportCategoryName(r.StructureElement),
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => "(All Rooms)",
                    r => "(All Types)");
            }

            if (string.Equals(mode, "SummaryPFinishes", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(IsBoqFinishReportRow),
                    reportName,
                    r => r.StructureElement,
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => string.IsNullOrWhiteSpace(r.Room) ? "(All Rooms)" : r.Room,
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            if (IsBoqReportIndexMode(mode))
            {
                return BuildBoqReportIndexRows(rows, mode, reportName);
            }

            if (IsBoqReportSteelMode(mode))
            {
                return BuildBoqReportAggregates(
                    rows.Where(r => IsBoqSteelReportRow(r, mode)),
                    reportName,
                    r => string.IsNullOrWhiteSpace(r.StructureElement) ? "Steel" : r.StructureElement,
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => "(All Rooms)",
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            if (string.Equals(mode, "MaterialTileSpec", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(IsBoqMaterialReportRow),
                    reportName,
                    r => r.StructureElement,
                    r => "(All Levels)",
                    r => "(All Rooms)",
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            if (string.Equals(mode, "MaterialTileRoom", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregates(
                    rows.Where(IsBoqMaterialReportRow),
                    reportName,
                    r => r.StructureElement,
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => string.IsNullOrWhiteSpace(r.Room) ? "(No Room)" : r.Room,
                    r => string.IsNullOrWhiteSpace(r.TypeName) ? "(No Type)" : r.TypeName);
            }

            return BuildBoqReportAggregates(
                rows,
                reportName,
                r => string.IsNullOrWhiteSpace(r.StructureElement) ? "(No Element)" : r.StructureElement,
                r => "(All Levels)",
                r => "(All Rooms)",
                r => "(All Types)");
        }

        private List<BoqReportRow> BuildBoqReportAggregates(
            IEnumerable<BoqTableRow> rows,
            string reportName,
            Func<BoqTableRow, string> elementSelector,
            Func<BoqTableRow, string> levelSelector,
            Func<BoqTableRow, string> roomSelector,
            Func<BoqTableRow, string> typeSelector)
        {
            if (rows == null)
            {
                return new List<BoqReportRow>();
            }

            return rows
                .Where(r => r != null)
                .GroupBy(r => BuildBoqReportGroupKey(
                    elementSelector(r),
                    levelSelector(r),
                    roomSelector(r),
                    typeSelector(r)), StringComparer.OrdinalIgnoreCase)
                .Select(g =>
                {
                    BoqTableRow first = g.First();
                    return BuildBoqReportAggregateRow(
                        reportName,
                        g,
                        elementSelector(first),
                        levelSelector(first),
                        roomSelector(first),
                        typeSelector(first));
                })
                .OrderBy(r => GetBoqReportCategoryOrder(NormalizeBoqReportCategoryName(r.StructureElement)))
                .ThenBy(r => r.StructureElement, StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.BuildingLevel, StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.Room, StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.TypeName, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static BoqReportRow BuildBoqReportAggregateRow(
            string reportName,
            IEnumerable<BoqTableRow> rows,
            string element,
            string level,
            string room,
            string type)
        {
            List<BoqTableRow> list = rows?.Where(r => r != null).ToList() ?? new List<BoqTableRow>();
            string formula = CombineBoqAuditValues(list, x => x.QsFormula, 520);
            string breakdown = CombineBoqAuditValues(list, x => x.QsBreakdown, 1200);
            return new BoqReportRow
            {
                ReportName = reportName ?? "",
                StructureElement = element ?? "",
                BuildingLevel = level ?? "",
                Room = room ?? "",
                TypeName = type ?? "",
                Quantity = list.Sum(x => x.Quantity),
                TotalVolumeM3 = list.Sum(x => x.TotalVolumeM3),
                TotalFormworkAreaM2 = list.Sum(x => x.TotalFormworkAreaM2),
                QsRuleCode = CombineBoqAuditValues(list, x => x.QsRuleCode, 420),
                QsFormula = formula,
                QsBreakdown = breakdown,
                FormulaBreakdown = BuildBoqReportFormulaBreakdown(formula, breakdown),
                QsValues = MergeBoqQsValues(list)
            };
        }

        private static BoqReportRow ToBoqReportRow(string reportName, BoqTableRow row)
        {
            string formula = row?.QsFormula ?? "";
            string breakdown = row?.QsBreakdown ?? "";
            return new BoqReportRow
            {
                ReportName = reportName ?? "",
                StructureElement = row?.StructureElement ?? "",
                BuildingLevel = row?.BuildingLevel ?? "",
                Room = row?.Room ?? "",
                TypeName = row?.TypeName ?? "",
                Quantity = row?.Quantity ?? 0,
                TotalVolumeM3 = row?.TotalVolumeM3 ?? 0.0,
                TotalFormworkAreaM2 = row?.TotalFormworkAreaM2 ?? 0.0,
                QsRuleCode = row?.QsRuleCode ?? "",
                QsFormula = formula,
                QsBreakdown = breakdown,
                FormulaBreakdown = BuildBoqReportFormulaBreakdown(formula, breakdown),
                QsValues = CloneBoqQsValues(row)
            };
        }

        private static List<BoqReportRow> BuildBoqReportIndexRows(List<BoqTableRow> rows, string mode, string reportName)
        {
            List<BoqTableRow> source = rows ?? new List<BoqTableRow>();
            if (string.Equals(mode, "IndexOverall", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportOverallIndexRows(source, reportName);
            }

            if (string.Equals(mode, "IndexConcreteGrade", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregatesStatic(
                    source.Where(IsBoqProjectStructureReportRow),
                    reportName,
                    r => NormalizeBoqReportCategoryName(r.StructureElement),
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => "(All Rooms)",
                    r => "Concrete Grade");
            }

            if (string.Equals(mode, "IndexSteelRatio", StringComparison.OrdinalIgnoreCase))
            {
                return BuildBoqReportAggregatesStatic(
                    source.Where(IsBoqProjectStructureReportRow),
                    reportName,
                    r => NormalizeBoqReportCategoryName(r.StructureElement),
                    r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                    r => "(All Rooms)",
                    r => "Steel Ratio");
            }

            return BuildBoqReportAggregatesStatic(
                source.Where(IsBoqProjectStructureReportRow),
                reportName,
                r => NormalizeBoqReportCategoryName(r.StructureElement),
                r => string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel,
                r => "(All Rooms)",
                r => "Unit Concrete Index");
        }

        private static List<BoqReportRow> BuildBoqReportOverallIndexRows(List<BoqTableRow> source, string reportName)
        {
            List<BoqTableRow> rows = source?.Where(IsBoqProjectStructureReportRow).ToList() ?? new List<BoqTableRow>();
            var result = new List<BoqReportRow>();

            result.Add(new BoqReportRow
            {
                ReportName = reportName ?? "",
                StructureElement = "Earthwork Index",
                RowLabel = "Earthwork Index",
                Unit = "m3",
                Value08 = "1"
            });

            int serial = 2;
            foreach (string category in new[] { "Foundation", "Wall", "Column", "Beam", "Slab", "Staircase" })
            {
                List<BoqTableRow> group = rows
                    .Where(r => string.Equals(NormalizeBoqReportCategoryName(r.StructureElement), category, StringComparison.OrdinalIgnoreCase))
                    .ToList();
                if (group.Count == 0) continue;

                result.Add(BuildBoqReportAggregateRow(
                    reportName,
                    group,
                    category,
                    "(All Levels)",
                    "(All Rooms)",
                    "Concrete " + GetBoqReportCategorySheetName(category)));
                result[result.Count - 1].RowLabel = "Concrete " + GetBoqReportCategorySheetName(category);
                result[result.Count - 1].Unit = "m3";
                result[result.Count - 1].Value08 = "2." + (serial - 1).ToString(CultureInfo.InvariantCulture);
                serial++;
            }

            serial = 1;
            foreach (string category in new[] { "Foundation", "Wall", "Column", "Beam", "Slab", "Staircase" })
            {
                List<BoqTableRow> group = rows
                    .Where(r => string.Equals(NormalizeBoqReportCategoryName(r.StructureElement), category, StringComparison.OrdinalIgnoreCase))
                    .ToList();
                if (group.Count == 0) continue;

                result.Add(BuildBoqReportAggregateRow(
                    reportName,
                    group,
                    "Formwork Index",
                    "(All Levels)",
                    "(All Rooms)",
                    "Formwork " + GetBoqReportCategorySheetName(category)));
                result[result.Count - 1].RowLabel = "Formwork " + GetBoqReportCategorySheetName(category);
                result[result.Count - 1].Unit = "m2";
                result[result.Count - 1].Value08 = "3." + serial.ToString(CultureInfo.InvariantCulture);
                serial++;
            }

            return result;
        }

        private static List<BoqReportRow> BuildBoqReportAggregatesStatic(
            IEnumerable<BoqTableRow> rows,
            string reportName,
            Func<BoqTableRow, string> elementSelector,
            Func<BoqTableRow, string> levelSelector,
            Func<BoqTableRow, string> roomSelector,
            Func<BoqTableRow, string> typeSelector)
        {
            if (rows == null)
            {
                return new List<BoqReportRow>();
            }

            return rows
                .Where(r => r != null)
                .GroupBy(r => BuildBoqReportGroupKey(elementSelector(r), levelSelector(r), roomSelector(r), typeSelector(r)), StringComparer.OrdinalIgnoreCase)
                .Select(g =>
                {
                    BoqTableRow first = g.First();
                    return BuildBoqReportAggregateRow(reportName, g, elementSelector(first), levelSelector(first), roomSelector(first), typeSelector(first));
                })
                .OrderBy(r => r.StructureElement, StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.TypeName, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static string BuildBoqReportFormulaBreakdown(string formula, string breakdown)
        {
            string f = (formula ?? "").Trim();
            string b = (breakdown ?? "").Trim();
            if (!string.IsNullOrWhiteSpace(f) && !string.IsNullOrWhiteSpace(b))
            {
                return f + " | " + b;
            }

            return !string.IsNullOrWhiteSpace(f) ? f : b;
        }

        private static string BuildBoqReportGroupKey(params string[] parts)
        {
            return string.Join("|", (parts ?? Array.Empty<string>()).Select(p => (p ?? "").Trim().ToUpperInvariant()));
        }

        private static bool MatchesBoqReportCategoryFilter(BoqTableRow row, string filter)
        {
            if (row == null) return false;
            if (string.IsNullOrWhiteSpace(filter)) return true;

            string f = filter.Trim();
            if (f.StartsWith("category:", StringComparison.OrdinalIgnoreCase))
            {
                string category = f.Substring("category:".Length).Trim();
                return IsBoqReportCategory(row, category);
            }

            if (f.StartsWith("type:", StringComparison.OrdinalIgnoreCase))
            {
                string raw = f.Substring("type:".Length);
                string[] parts = raw.Split(new[] { '|' }, 2);
                if (parts.Length != 2) return true;
                return IsBoqReportCategory(row, parts[0]) &&
                       string.Equals((row.TypeName ?? "").Trim(), parts[1].Trim(), StringComparison.OrdinalIgnoreCase);
            }

            return true;
        }

        private static bool IsBoqReportCategory(BoqTableRow row, string category)
        {
            return string.Equals(NormalizeBoqReportCategoryName(row?.StructureElement), category, StringComparison.OrdinalIgnoreCase);
        }

        private static string NormalizeBoqReportCategoryName(string structureElement)
        {
            string text = (structureElement ?? "").Trim();
            if (text.Length == 0) return "Other";

            if (ContainsWord(text, "column")) return "Column";
            if (ContainsWord(text, "wall") && !ContainsWord(text, "finish")) return "Wall";
            if (ContainsWord(text, "door") || ContainsWord(text, "window")) return "Door/Window Opening";
            if (ContainsWord(text, "framing") || ContainsWord(text, "beam") || ContainsWord(text, "lintel")) return "Beam";
            if (ContainsWord(text, "floor") || ContainsWord(text, "slab") || ContainsWord(text, "drop") || ContainsWord(text, "eave")) return "Slab";
            if (ContainsWord(text, "stair")) return "Staircase";
            if (ContainsWord(text, "foundation") || string.Equals(text, "Foundation", StringComparison.OrdinalIgnoreCase)) return "Foundation";
            if (IsBoqFinishLabel(text)) return "Finishes";
            if (ContainsWord(text, "soil")) return "Soil";
            if (ContainsWord(text, "kerb") || ContainsWord(text, "concrete")) return "Auxiliary Concrete";
            return "Other";
        }

        private static int GetBoqReportCategoryOrder(string category)
        {
            if (string.Equals(category, "Column", StringComparison.OrdinalIgnoreCase)) return 1;
            if (string.Equals(category, "Wall", StringComparison.OrdinalIgnoreCase)) return 2;
            if (string.Equals(category, "Door/Window Opening", StringComparison.OrdinalIgnoreCase)) return 3;
            if (string.Equals(category, "Beam", StringComparison.OrdinalIgnoreCase)) return 4;
            if (string.Equals(category, "Slab", StringComparison.OrdinalIgnoreCase)) return 5;
            if (string.Equals(category, "Staircase", StringComparison.OrdinalIgnoreCase)) return 6;
            if (string.Equals(category, "Foundation", StringComparison.OrdinalIgnoreCase)) return 7;
            if (string.Equals(category, "Finishes", StringComparison.OrdinalIgnoreCase)) return 8;
            if (string.Equals(category, "Auxiliary Concrete", StringComparison.OrdinalIgnoreCase)) return 9;
            if (string.Equals(category, "Soil", StringComparison.OrdinalIgnoreCase)) return 10;
            return 99;
        }

        private static bool IsPrimaryBoqReportCategory(string category)
        {
            return string.Equals(category, "Column", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Wall", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Door/Window Opening", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Beam", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Slab", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Staircase", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Foundation", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsBoqFinishLabel(string text)
        {
            return ContainsWord(text, "finish") ||
                   ContainsWord(text, "ceiling") ||
                   ContainsWord(text, "waterproof") ||
                   ContainsWord(text, "tile") ||
                   ContainsWord(text, "paint") ||
                   ContainsWord(text, "plaster");
        }

        private static bool IsBoqFinishReportRow(BoqTableRow row)
        {
            return row != null &&
                   (IsBoqFinishLabel(row.StructureElement) ||
                    IsBoqFinishLabel(row.TypeName) ||
                    IsBoqFinishLabel(row.QsRuleCode));
        }

        private static bool IsBoqWallFinishReportRow(BoqTableRow row)
        {
            if (row == null) return false;
            return ContainsWord(row.StructureElement, "wall finish") ||
                   (ContainsWord(row.StructureElement, "wall") && IsBoqFinishReportRow(row));
        }

        private static bool IsBoqProjectStructureReportRow(BoqTableRow row)
        {
            if (row == null) return false;
            string category = NormalizeBoqReportCategoryName(row.StructureElement);
            return string.Equals(category, "Column", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Wall", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Beam", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Slab", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Staircase", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(category, "Foundation", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsBoqDoorWindowReportRow(BoqTableRow row)
        {
            if (row == null) return false;
            return IsBoqReportCategory(row, "Door/Window Opening") ||
                   ContainsWord(row.StructureElement, "opening") ||
                   ContainsWord(row.TypeName, "opening") ||
                   ContainsWord(row.QsRuleCode, "opening");
        }

        private static bool IsBoqMaterialReportRow(BoqTableRow row)
        {
            if (row == null) return false;
            return IsBoqFinishReportRow(row) ||
                   ContainsWord(row.StructureElement, "material") ||
                   ContainsWord(row.TypeName, "material");
        }

        private static bool IsBoqReportIndexMode(string mode)
        {
            return string.Equals(mode, "IndexConcreteUnit", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(mode, "IndexOverall", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(mode, "IndexConcreteGrade", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(mode, "IndexSteelRatio", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsBoqReportSteelMode(string mode)
        {
            return string.Equals(mode, "SteelSummary", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(mode, "SteelPlate", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(mode, "SteelBolt", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(mode, "SteelAnchorBolt", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(mode, "SteelShearStud", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsBoqSteelReportRow(BoqTableRow row, string mode)
        {
            if (row == null) return false;
            string haystack = ((row.StructureElement ?? "") + " " + (row.TypeName ?? "") + " " + (row.QsRuleCode ?? "")).Trim();
            if (string.Equals(mode, "SteelPlate", StringComparison.OrdinalIgnoreCase)) return ContainsWord(haystack, "plate");
            if (string.Equals(mode, "SteelAnchorBolt", StringComparison.OrdinalIgnoreCase)) return ContainsWord(haystack, "anchor");
            if (string.Equals(mode, "SteelShearStud", StringComparison.OrdinalIgnoreCase)) return ContainsWord(haystack, "stud");
            if (string.Equals(mode, "SteelBolt", StringComparison.OrdinalIgnoreCase)) return ContainsWord(haystack, "bolt");
            return ContainsWord(haystack, "steel") || ContainsWord(haystack, "plate") || ContainsWord(haystack, "bolt") || ContainsWord(haystack, "stud");
        }

        private static bool ContainsWord(string text, string token)
        {
            return (text ?? "").IndexOf(token ?? "", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static string GetBoqReportModeTitle(string mode)
        {
            if (string.Equals(mode, "SummaryBySegmentation", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (by Segmentation)";
            if (string.Equals(mode, "SummaryByElement", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (by Element)";
            if (string.Equals(mode, "SummaryColumn1", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (Column 1)";
            if (string.Equals(mode, "SummaryColumn2", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (Column 2)";
            if (string.Equals(mode, "SummaryDoorWindow", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (Door/Window)";
            if (string.Equals(mode, "SummaryWallFinish", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (Wall Finish)";
            if (string.Equals(mode, "SummaryPStructure", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (P-Structure)";
            if (string.Equals(mode, "SummaryPFinishes", StringComparison.OrdinalIgnoreCase)) return "Quantity Summary (P-Finishes)";
            if (string.Equals(mode, "WorksheetExpression", StringComparison.OrdinalIgnoreCase)) return "Quantity Measurement Worksheet (Expression)";
            if (string.Equals(mode, "WorksheetWall", StringComparison.OrdinalIgnoreCase)) return "Quantity Measurement Worksheet (Wall)";
            if (string.Equals(mode, "IndexConcreteUnit", StringComparison.OrdinalIgnoreCase)) return "Single-Unit Concrete Index Table";
            if (string.Equals(mode, "IndexOverall", StringComparison.OrdinalIgnoreCase)) return "Project Overall Index Table";
            if (string.Equals(mode, "IndexConcreteGrade", StringComparison.OrdinalIgnoreCase)) return "Concrete Grade Index Table";
            if (string.Equals(mode, "IndexSteelRatio", StringComparison.OrdinalIgnoreCase)) return "Steel Ratio Index Table";
            if (string.Equals(mode, "SteelSummary", StringComparison.OrdinalIgnoreCase)) return "Structural Steel Summary";
            if (string.Equals(mode, "SteelPlate", StringComparison.OrdinalIgnoreCase)) return "Plate Summary";
            if (string.Equals(mode, "SteelBolt", StringComparison.OrdinalIgnoreCase)) return "Bolt Summary";
            if (string.Equals(mode, "SteelAnchorBolt", StringComparison.OrdinalIgnoreCase)) return "Anchor Bolt Summary";
            if (string.Equals(mode, "SteelShearStud", StringComparison.OrdinalIgnoreCase)) return "Shear Stud Summary";
            if (string.Equals(mode, "MaterialTileSpec", StringComparison.OrdinalIgnoreCase)) return "Tile Schedule (by Spec)";
            if (string.Equals(mode, "MaterialTileRoom", StringComparison.OrdinalIgnoreCase)) return "Tile Schedule (by Room)";
            return "Quantity Summary (by Element)";
        }

        private static string CombineBoqAuditValues(IEnumerable<BoqTableRow> rows, Func<BoqTableRow, string> selector, int maxLength)
        {
            if (rows == null || selector == null)
            {
                return "";
            }

            List<string> values = rows
                .Select(selector)
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Select(s => s.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (values.Count == 0)
            {
                return "";
            }

            string joined = string.Join(" | ", values);
            if (joined.Length <= maxLength)
            {
                return joined;
            }

            int keep = Math.Max(0, maxLength - 4);
            return joined.Substring(0, keep) + " ...";
        }

        private BoqPivotMode GetBoqPivotMode()
        {
            string mode = BoqPivotModeCombo?.SelectedItem as string;
            if (string.Equals(mode, "Pivot by Floor", StringComparison.OrdinalIgnoreCase)) return BoqPivotMode.ByFloor;
            if (string.Equals(mode, "Pivot by Element", StringComparison.OrdinalIgnoreCase)) return BoqPivotMode.ByElement;
            if (string.Equals(mode, "Pivot by Floor + Element", StringComparison.OrdinalIgnoreCase)) return BoqPivotMode.ByFloorAndElement;
            if (string.Equals(mode, "Pivot by Floor + Room + Element", StringComparison.OrdinalIgnoreCase)) return BoqPivotMode.ByFloorRoomElement;
            return BoqPivotMode.DetailType;
        }

        private bool TryBuildBoqClipboardPayload(bool includeHeader, out string tsv, out string csv, out int rowCount, out int colCount)
        {
            tsv = "";
            csv = "";
            rowCount = 0;
            colCount = 0;

            if (BoqTableGrid == null) return false;

            List<BoqTableRow> rows = GetBoqRowsForPayload(out bool fromCellSelection, out int rowStartIndex);
            List<DataGridColumn> columns = GetBoqColumnsForPayload();

            if (rows.Count == 0 || columns.Count == 0) return false;

            _boqLastSelectionStartRowIndex = rowStartIndex;
            _boqLastSelectionRowCount = rows.Count;
            _boqLastSelectionColumnDisplayIndices = columns
                .Select(c => c.DisplayIndex)
                .OrderBy(i => i)
                .ToList();
            _boqLastSelectionIsCellBased = fromCellSelection;
            _boqLastSelectedCells = fromCellSelection ? GetSelectedBoqCellSet() : new HashSet<(int, int)>();

            var sbTsv = new StringBuilder(rows.Count * 64 + 128);
            var sbCsv = new StringBuilder(rows.Count * 64 + 128);
            if (includeHeader)
            {
                var headers = columns
                    .Select(c => SanitizeForTab(c?.Header?.ToString() ?? ""))
                    .ToList();
                sbTsv.AppendLine(string.Join("\t", headers));
                sbCsv.AppendLine(string.Join(",", headers.Select(EscapeCsv)));
            }

            for (int r = 0; r < rows.Count; r++)
            {
                BoqTableRow row = rows[r];
                int absoluteRowIndex = rowStartIndex + r;
                var vals = new List<string>(columns.Count);
                foreach (DataGridColumn col in columns)
                {
                    if (fromCellSelection && _boqLastSelectedCells != null)
                    {
                        if (!_boqLastSelectedCells.Contains((absoluteRowIndex, col.DisplayIndex)))
                        {
                            vals.Add("");
                            continue;
                        }
                    }

                    vals.Add(SanitizeForTab(GetBoqCellValue(row, col)));
                }
                sbTsv.AppendLine(string.Join("\t", vals));
                sbCsv.AppendLine(string.Join(",", vals.Select(EscapeCsv)));
            }

            tsv = sbTsv.ToString();
            csv = sbCsv.ToString();
            rowCount = rows.Count;
            colCount = columns.Count;
            return true;
        }

        private List<BoqTableRow> GetBoqRowsForPayload(out bool fromCellSelection, out int rowStartIndex)
        {
            fromCellSelection = false;
            rowStartIndex = 0;

            List<DataGridCellInfo> cells = BoqTableGrid.SelectedCells
                .Where(c => c.Column != null && c.Item is BoqTableRow)
                .ToList();

            if (cells.Count == 0)
            {
                List<BoqTableRow> selectedRows = GetSelectedBoqRows();
                if (selectedRows.Count > 0)
                {
                    BoqTableRow first = selectedRows.First();
                    rowStartIndex = Math.Max(0, _boqRows.IndexOf(first));
                    return selectedRows;
                }

                rowStartIndex = 0;
                return _boqRows.ToList();
            }

            var rowIndexes = new List<int>();
            foreach (DataGridCellInfo cell in cells)
            {
                if (cell.Item is BoqTableRow row)
                {
                    int idx = _boqRows.IndexOf(row);
                    if (idx >= 0) rowIndexes.Add(idx);
                }
            }

            if (rowIndexes.Count == 0)
            {
                rowStartIndex = 0;
                return _boqRows.ToList();
            }

            int min = rowIndexes.Min();
            int max = rowIndexes.Max();
            fromCellSelection = true;
            rowStartIndex = min;
            return _boqRows.Skip(min).Take(max - min + 1).ToList();
        }

        private List<DataGridColumn> GetBoqColumnsForPayload()
        {
            if (BoqTableGrid == null) return new List<DataGridColumn>();

            List<DataGridCellInfo> cells = BoqTableGrid.SelectedCells
                .Where(c => c.Column != null && c.Item is BoqTableRow)
                .ToList();

            if (cells.Count == 0)
            {
                return BoqTableGrid.Columns.OrderBy(c => c.DisplayIndex).ToList();
            }

            var colIndexes = new List<int>();
            foreach (DataGridCellInfo cell in cells)
            {
                colIndexes.Add(cell.Column.DisplayIndex);
            }

            if (colIndexes.Count == 0)
            {
                return BoqTableGrid.Columns.OrderBy(c => c.DisplayIndex).ToList();
            }

            int min = colIndexes.Min();
            int max = colIndexes.Max();
            return BoqTableGrid.Columns
                .Where(c => c.DisplayIndex >= min && c.DisplayIndex <= max)
                .OrderBy(c => c.DisplayIndex)
                .ToList();
        }

        private HashSet<(int RowIndex, int ColDisplayIndex)> GetSelectedBoqCellSet()
        {
            var set = new HashSet<(int, int)>();
            if (BoqTableGrid == null) return set;

            foreach (DataGridCellInfo cell in BoqTableGrid.SelectedCells)
            {
                if (!(cell.Item is BoqTableRow row) || cell.Column == null) continue;
                int rowIndex = _boqRows.IndexOf(row);
                if (rowIndex < 0) continue;
                set.Add((rowIndex, cell.Column.DisplayIndex));
            }

            return set;
        }

        private static string GetBoqCellValue(BoqTableRow row, DataGridColumn column)
        {
            if (row == null || column == null) return "";

            string key = GetBoqColumnKey(column);
            switch (key)
            {
                case "StructureElement":
                case "Structure Element":
                    return row.StructureElement ?? "";
                case "BuildingLevel":
                case "Building Level":
                    return row.BuildingLevel ?? "";
                case "Room":
                    return row.Room ?? "";
                case "TypeName":
                case "Type":
                    return row.TypeName ?? "";
                case "Quantity":
                case "Qty":
                    return row.Quantity.ToString(CultureInfo.InvariantCulture);
                case "TotalVolumeM3":
                case "Volume (m3)":
                    return row.TotalVolumeM3.ToString("F3", CultureInfo.InvariantCulture);
                case "TotalFormworkAreaM2":
                case "Formwork (m2)":
                    return row.TotalFormworkAreaM2.ToString("F3", CultureInfo.InvariantCulture);
                case "QsRuleCode":
                case "Rule Code":
                    return row.QsRuleCode ?? "";
                case "QsFormula":
                case "Formula":
                    return row.QsFormula ?? "";
                case "QsBreakdown":
                case "Breakdown":
                    return row.QsBreakdown ?? "";
                default:
                    return "";
            }
        }

        private static string GetBoqColumnKey(DataGridColumn column)
        {
            if (column == null) return "";
            if (!string.IsNullOrWhiteSpace(column.SortMemberPath))
            {
                return column.SortMemberPath.Trim();
            }

            if (column is DataGridBoundColumn bound &&
                bound.Binding is System.Windows.Data.Binding binding &&
                binding.Path != null &&
                !string.IsNullOrWhiteSpace(binding.Path.Path))
            {
                return binding.Path.Path.Trim();
            }

            return (column.Header?.ToString() ?? "").Trim();
        }

        private List<BoqTableRow> GetSelectedBoqRows()
        {
            if (BoqTableGrid == null || BoqTableGrid.SelectedItems == null)
            {
                return new List<BoqTableRow>();
            }

            var selected = new List<BoqTableRow>();
            foreach (object item in BoqTableGrid.SelectedItems)
            {
                if (item is BoqTableRow row)
                {
                    selected.Add(row);
                }
            }

            if (selected.Count == 0)
            {
                return selected;
            }

            var selectedSet = new HashSet<BoqTableRow>(selected);
            return _boqRows.Where(r => selectedSet.Contains(r)).ToList();
        }

        private List<BoqTableRow> GetBoqRowsForTransfer()
        {
            List<BoqTableRow> selected = GetSelectedBoqRows();
            if (selected.Count > 0)
            {
                return selected;
            }

            return _boqRows.ToList();
        }

        private static string BuildBoqTabSeparated(IReadOnlyList<BoqTableRow> rows, bool includeHeader)
        {
            var sb = new StringBuilder(rows.Count * 64 + 128);
            if (includeHeader)
            {
                sb.AppendLine("Structure Element\tBuildingLevel\tRoom\tType\tQty\tVolume (m3)\tFormwork (m2)\tRule Code\tFormula\tBreakdown");
            }

            foreach (BoqTableRow row in rows)
            {
                sb.Append(SanitizeForTab(row.StructureElement)).Append('\t')
                  .Append(SanitizeForTab(row.BuildingLevel)).Append('\t')
                  .Append(SanitizeForTab(row.Room)).Append('\t')
                  .Append(SanitizeForTab(row.TypeName)).Append('\t')
                  .Append(row.Quantity.ToString(CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.TotalVolumeM3.ToString("N3", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.TotalFormworkAreaM2.ToString("N3", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(SanitizeForTab(row.QsRuleCode)).Append('\t')
                  .Append(SanitizeForTab(row.QsFormula)).Append('\t')
                  .Append(SanitizeForTab(row.QsBreakdown))
                  .AppendLine();
            }

            return sb.ToString();
        }

        private static string BuildBoqCsv(IReadOnlyList<BoqTableRow> rows, bool includeHeader)
        {
            var sb = new StringBuilder(rows.Count * 64 + 128);
            if (includeHeader)
            {
                sb.AppendLine("Structure Element,BuildingLevel,Room,Type,Qty,Volume (m3),Formwork (m2),Rule Code,Formula,Breakdown");
            }

            foreach (BoqTableRow row in rows)
            {
                sb.Append(EscapeCsv(row.StructureElement)).Append(',')
                  .Append(EscapeCsv(row.BuildingLevel)).Append(',')
                  .Append(EscapeCsv(row.Room)).Append(',')
                  .Append(EscapeCsv(row.TypeName)).Append(',')
                  .Append(row.Quantity.ToString(CultureInfo.InvariantCulture)).Append(',')
                  .Append(row.TotalVolumeM3.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                  .Append(row.TotalFormworkAreaM2.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                  .Append(EscapeCsv(row.QsRuleCode)).Append(',')
                  .Append(EscapeCsv(row.QsFormula)).Append(',')
                  .Append(EscapeCsv(row.QsBreakdown))
                  .AppendLine();
            }

            return sb.ToString();
        }

        private string BuildPrepareBoqCsv(IReadOnlyList<PrepareBoqRow> rows)
        {
            var sb = new StringBuilder(rows.Count * 96 + 128);
            string hUse = HeaderFromMap(_prepareBoqHeaderMap, "Use", "Use");
            string hSheet = HeaderFromMap(_prepareBoqHeaderMap, "Sheet", "Sheet");
            string hItemCode = HeaderFromMap(_prepareBoqHeaderMap, "ItemCode", "Item Code");
            string hDescription = HeaderFromMap(_prepareBoqHeaderMap, "Description", "Description");
            string hUnit = HeaderFromMap(_prepareBoqHeaderMap, "Unit", "Unit");
            string hStructure = HeaderFromMap(_prepareBoqHeaderMap, "StructureElement", "Structure Element");
            string hLevel = HeaderFromMap(_prepareBoqHeaderMap, "BuildingLevel", "BuildingLevel");
            string hRoom = HeaderFromMap(_prepareBoqHeaderMap, "Room", "Room");
            string hType = HeaderFromMap(_prepareBoqHeaderMap, "Type", "Type");
            string hQty = HeaderFromMap(_prepareBoqHeaderMap, "Qty", "Qty");
            string hVolume = HeaderFromMap(_prepareBoqHeaderMap, "Volume", "Volume (m3)");
            string hFormwork = HeaderFromMap(_prepareBoqHeaderMap, "Formwork", "Formwork (m2)");
            string hRuleCode = HeaderFromMap(_prepareBoqHeaderMap, "QsRuleCode", "Rule Code");
            string hFormula = HeaderFromMap(_prepareBoqHeaderMap, "QsFormula", "Formula");
            string hBreakdown = HeaderFromMap(_prepareBoqHeaderMap, "QsBreakdown", "Breakdown");

            sb.AppendLine(string.Join(",", new[]
            {
                EscapeCsv(hUse),
                EscapeCsv(hSheet),
                EscapeCsv(hItemCode),
                EscapeCsv(hDescription),
                EscapeCsv(hUnit),
                EscapeCsv(hStructure),
                EscapeCsv(hLevel),
                EscapeCsv(hRoom),
                EscapeCsv(hType),
                EscapeCsv(hQty),
                EscapeCsv(hVolume),
                EscapeCsv(hFormwork),
                EscapeCsv(hRuleCode),
                EscapeCsv(hFormula),
                EscapeCsv(hBreakdown)
            }));

            foreach (PrepareBoqRow row in rows)
            {
                sb.Append(row.IsEnabled ? "1" : "0").Append(',')
                  .Append(EscapeCsv(row.SourceSheet)).Append(',')
                  .Append(EscapeCsv(row.ItemCode)).Append(',')
                  .Append(EscapeCsv(row.Description)).Append(',')
                  .Append(EscapeCsv(row.Unit)).Append(',')
                  .Append(EscapeCsv(row.StructureElement)).Append(',')
                  .Append(EscapeCsv(row.BuildingLevel)).Append(',')
                  .Append(EscapeCsv(row.Room)).Append(',')
                  .Append(EscapeCsv(row.TypeName)).Append(',')
                  .Append(row.Quantity.ToString(CultureInfo.InvariantCulture)).Append(',')
                  .Append(row.TotalVolumeM3.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                  .Append(row.TotalFormworkAreaM2.ToString("F3", CultureInfo.InvariantCulture)).Append(',')
                  .Append(EscapeCsv(row.QsRuleCode)).Append(',')
                  .Append(EscapeCsv(row.QsFormula)).Append(',')
                  .Append(EscapeCsv(row.QsBreakdown))
                  .AppendLine();
            }

            return sb.ToString();
        }

        private static string BuildBoqKey(string structureElement, string buildingLevel, string typeName)
        {
            return (structureElement ?? "").Trim().ToUpperInvariant() + "|" +
                   (buildingLevel ?? "").Trim().ToUpperInvariant() + "|" +
                   (typeName ?? "").Trim().ToUpperInvariant();
        }

        private static string BuildBoqKey(string structureElement, string buildingLevel, string room, string typeName)
        {
            return (structureElement ?? "").Trim().ToUpperInvariant() + "|" +
                   (buildingLevel ?? "").Trim().ToUpperInvariant() + "|" +
                   (room ?? "").Trim().ToUpperInvariant() + "|" +
                   (typeName ?? "").Trim().ToUpperInvariant();
        }

        private Dictionary<string, BoqTableRow> BuildBoqIndexMapForSync()
        {
            var map = new Dictionary<string, BoqTableRow>(StringComparer.OrdinalIgnoreCase);
            IEnumerable<BoqTableRow> source = (_boqAllRows != null && _boqAllRows.Count > 0)
                ? (IEnumerable<BoqTableRow>)_boqAllRows
                : (IEnumerable<BoqTableRow>)_boqRows;
            List<BoqTableRow> detailRows = source
                .Where(r =>
                    r != null &&
                    !string.IsNullOrWhiteSpace(r.StructureElement) &&
                    !string.IsNullOrWhiteSpace(r.BuildingLevel) &&
                    !string.IsNullOrWhiteSpace(r.TypeName))
                .ToList();

            foreach (BoqTableRow row in detailRows)
            {
                string key = BuildBoqKey(row.StructureElement, row.BuildingLevel, row.Room, row.TypeName);
                map[key] = row;
            }

            foreach (var g in detailRows.GroupBy(r => BuildBoqKey(r.StructureElement, r.BuildingLevel, r.Room, "(All Types)"), StringComparer.OrdinalIgnoreCase))
            {
                map[g.Key] = new BoqTableRow
                {
                    StructureElement = g.First().StructureElement,
                    BuildingLevel = g.First().BuildingLevel,
                    Room = g.First().Room,
                    TypeName = "(All Types)",
                    Quantity = g.Sum(x => x.Quantity),
                    TotalVolumeM3 = g.Sum(x => x.TotalVolumeM3),
                    TotalFormworkAreaM2 = g.Sum(x => x.TotalFormworkAreaM2),
                    QsRuleCode = CombineBoqAuditValues(g, x => x.QsRuleCode, 360),
                    QsFormula = CombineBoqAuditValues(g, x => x.QsFormula, 420),
                    QsBreakdown = CombineBoqAuditValues(g, x => x.QsBreakdown, 1000),
                    QsValues = MergeBoqQsValues(g),
                    StructureOrder = g.First().StructureOrder
                };
            }

            foreach (var g in detailRows.GroupBy(r => BuildBoqKey(r.StructureElement, "(All Levels)", "(All Types)"), StringComparer.OrdinalIgnoreCase))
            {
                map[g.Key] = new BoqTableRow
                {
                    StructureElement = g.First().StructureElement,
                    BuildingLevel = "(All Levels)",
                    Room = "(All Rooms)",
                    TypeName = "(All Types)",
                    Quantity = g.Sum(x => x.Quantity),
                    TotalVolumeM3 = g.Sum(x => x.TotalVolumeM3),
                    TotalFormworkAreaM2 = g.Sum(x => x.TotalFormworkAreaM2),
                    QsRuleCode = CombineBoqAuditValues(g, x => x.QsRuleCode, 360),
                    QsFormula = CombineBoqAuditValues(g, x => x.QsFormula, 420),
                    QsBreakdown = CombineBoqAuditValues(g, x => x.QsBreakdown, 1000),
                    QsValues = MergeBoqQsValues(g),
                    StructureOrder = g.First().StructureOrder
                };
            }

            foreach (var g in detailRows.GroupBy(r => BuildBoqKey("(All Elements)", r.BuildingLevel, "(All Types)"), StringComparer.OrdinalIgnoreCase))
            {
                map[g.Key] = new BoqTableRow
                {
                    StructureElement = "(All Elements)",
                    BuildingLevel = g.First().BuildingLevel,
                    Room = "(All Rooms)",
                    TypeName = "(All Types)",
                    Quantity = g.Sum(x => x.Quantity),
                    TotalVolumeM3 = g.Sum(x => x.TotalVolumeM3),
                    TotalFormworkAreaM2 = g.Sum(x => x.TotalFormworkAreaM2),
                    QsRuleCode = CombineBoqAuditValues(g, x => x.QsRuleCode, 360),
                    QsFormula = CombineBoqAuditValues(g, x => x.QsFormula, 420),
                    QsBreakdown = CombineBoqAuditValues(g, x => x.QsBreakdown, 1000),
                    QsValues = MergeBoqQsValues(g),
                    StructureOrder = 0
                };
            }

            return map;
        }

        private int SyncPrepareBoqWithCurrentBoq(bool setMissingToZero)
        {
            if (_prepareBoqRows.Count == 0)
            {
                UpdatePrepareBoqSummary();
                return 0;
            }

            Dictionary<string, BoqTableRow> index = BuildBoqIndexMapForSync();
            int updated = 0;
            foreach (PrepareBoqRow row in _prepareBoqRows)
            {
                string key = row.LinkedBoqKey;
                if (string.IsNullOrWhiteSpace(key))
                {
                    key = BuildBoqKey(row.StructureElement, row.BuildingLevel, row.Room, row.TypeName);
                }
                if (string.IsNullOrWhiteSpace(row.StructureElement) ||
                    string.IsNullOrWhiteSpace(row.BuildingLevel) ||
                    string.IsNullOrWhiteSpace(row.TypeName))
                {
                    continue;
                }

                if (index.TryGetValue(key, out BoqTableRow src))
                {
                    row.Quantity = src.Quantity;
                    row.TotalVolumeM3 = src.TotalVolumeM3;
                    row.TotalFormworkAreaM2 = src.TotalFormworkAreaM2;
                    row.QsRuleCode = src.QsRuleCode ?? "";
                    row.QsFormula = src.QsFormula ?? "";
                    row.QsBreakdown = src.QsBreakdown ?? "";
                    row.LinkedBoqKey = key;
                    updated++;
                }
                else if (setMissingToZero)
                {
                    row.Quantity = 0;
                    row.TotalVolumeM3 = 0.0;
                    row.TotalFormworkAreaM2 = 0.0;
                    row.QsRuleCode = "";
                    row.QsFormula = "";
                    row.QsBreakdown = "";
                }
            }

            PrepareBoqGrid?.Items.Refresh();
            UpdatePrepareBoqSummary();
            return updated;
        }

        private List<BoqTableRow> ParseBoqRowsFromDroppedText(string tsv)
        {
            var rows = new List<BoqTableRow>();
            if (string.IsNullOrWhiteSpace(tsv)) return rows;

            string[] lines = tsv.Replace("\r\n", "\n").Split('\n');
            foreach (string raw in lines)
            {
                string line = raw ?? "";
                if (string.IsNullOrWhiteSpace(line)) continue;
                string[] parts = line.Split('\t');
                if (parts.Length < 3) continue;

                string structure = (parts.Length > 0 ? parts[0] : "").Trim();
                string level = (parts.Length > 1 ? parts[1] : "").Trim();
                if (string.Equals(structure, "Structure Element", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                bool hasRoomColumn = parts.Length >= 7;
                string room = hasRoomColumn ? (parts.Length > 2 ? parts[2] : "").Trim() : "";
                string type = hasRoomColumn
                    ? (parts.Length > 3 ? parts[3] : "").Trim()
                    : (parts.Length > 2 ? parts[2] : "").Trim();
                if (string.IsNullOrWhiteSpace(structure) ||
                    string.IsNullOrWhiteSpace(level) ||
                    string.IsNullOrWhiteSpace(type))
                {
                    continue;
                }

                int qty = 0;
                double vol = 0.0;
                double fwk = 0.0;
                int qtyIndex = hasRoomColumn ? 4 : 3;
                int volumeIndex = hasRoomColumn ? 5 : 4;
                int formworkIndex = hasRoomColumn ? 6 : 5;
                int ruleCodeIndex = hasRoomColumn ? 7 : 6;
                int formulaIndex = hasRoomColumn ? 8 : 7;
                int breakdownIndex = hasRoomColumn ? 9 : 8;
                if (parts.Length > qtyIndex)
                {
                    int.TryParse(parts[qtyIndex], NumberStyles.Any, CultureInfo.InvariantCulture, out qty);
                    if (qty == 0) int.TryParse(parts[qtyIndex], NumberStyles.Any, CultureInfo.CurrentCulture, out qty);
                }
                if (parts.Length > volumeIndex)
                {
                    double.TryParse(parts[volumeIndex], NumberStyles.Any, CultureInfo.InvariantCulture, out vol);
                    if (Math.Abs(vol) < 1e-9) double.TryParse(parts[volumeIndex], NumberStyles.Any, CultureInfo.CurrentCulture, out vol);
                }
                if (parts.Length > formworkIndex)
                {
                    double.TryParse(parts[formworkIndex], NumberStyles.Any, CultureInfo.InvariantCulture, out fwk);
                    if (Math.Abs(fwk) < 1e-9) double.TryParse(parts[formworkIndex], NumberStyles.Any, CultureInfo.CurrentCulture, out fwk);
                }

                rows.Add(new BoqTableRow
                {
                    StructureElement = structure,
                    BuildingLevel = level,
                    Room = room,
                    TypeName = type,
                    Quantity = qty,
                    TotalVolumeM3 = vol,
                    TotalFormworkAreaM2 = fwk,
                    QsRuleCode = parts.Length > ruleCodeIndex ? parts[ruleCodeIndex].Trim() : "",
                    QsFormula = parts.Length > formulaIndex ? parts[formulaIndex].Trim() : "",
                    QsBreakdown = parts.Length > breakdownIndex ? parts[breakdownIndex].Trim() : ""
                });
            }

            return rows;
        }

        private int GetPrepareBoqDropRowIndex(System.Windows.Point point)
        {
            if (PrepareBoqGrid == null) return -1;
            DependencyObject hit = PrepareBoqGrid.InputHitTest(point) as DependencyObject;
            while (hit != null && !(hit is DataGridRow))
            {
                hit = System.Windows.Media.VisualTreeHelper.GetParent(hit);
            }

            if (hit is DataGridRow row)
            {
                return row.GetIndex();
            }

            return -1;
        }

        private int GetPrepareBoqSelectedRowIndex()
        {
            if (PrepareBoqGrid == null)
            {
                return -1;
            }

            if (PrepareBoqGrid.CurrentItem is PrepareBoqRow current)
            {
                int idx = _prepareBoqRows.IndexOf(current);
                if (idx >= 0) return idx;
            }

            if (PrepareBoqGrid.SelectedItem is PrepareBoqRow selected)
            {
                int idx = _prepareBoqRows.IndexOf(selected);
                if (idx >= 0) return idx;
            }

            return -1;
        }

        private void UpdatePrepareBoqSummary()
        {
            int enabled = _prepareBoqRows.Count(r => r.IsEnabled);
            double sumVolume = _prepareBoqRows.Where(r => r.IsEnabled).Sum(r => r.TotalVolumeM3);
            double sumFormwork = _prepareBoqRows.Where(r => r.IsEnabled).Sum(r => r.TotalFormworkAreaM2);

            if (PrepareBoqSummaryText != null)
            {
                PrepareBoqSummaryText.Text = $"Prepare BOQ rows: {_prepareBoqRows.Count}, enabled: {enabled}, Volume: {sumVolume:N3} m3, Formwork: {sumFormwork:N3} m2.";
            }
            if (PrepareBoqKpiRowsText != null)
            {
                PrepareBoqKpiRowsText.Text = _prepareBoqRows.Count.ToString(CultureInfo.InvariantCulture);
            }
            if (PrepareBoqKpiEnabledText != null)
            {
                PrepareBoqKpiEnabledText.Text = enabled.ToString(CultureInfo.InvariantCulture);
            }
            if (PrepareBoqKpiVolumeText != null)
            {
                PrepareBoqKpiVolumeText.Text = sumVolume.ToString("N3", CultureInfo.InvariantCulture);
            }
            if (PrepareBoqKpiFormworkText != null)
            {
                PrepareBoqKpiFormworkText.Text = sumFormwork.ToString("N3", CultureInfo.InvariantCulture);
            }
            if (PrepareBoqEmptyStateText != null)
            {
                PrepareBoqEmptyStateText.Visibility = _prepareBoqRows.Count > 0
                    ? System.Windows.Visibility.Collapsed
                    : System.Windows.Visibility.Visible;
            }
        }

        private static PrepareBoqImportResult ReadPrepareBoqFromFile(string path)
        {
            string ext = Path.GetExtension(path) ?? "";
            if (string.Equals(ext, ".xlsx", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(ext, ".xlsm", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(ext, ".xls", StringComparison.OrdinalIgnoreCase))
            {
                return ReadPrepareBoqFromExcel(path);
            }

            return ReadPrepareBoqFromCsv(path);
        }

        private static List<string> ParseCsvLine(string line)
        {
            var values = new List<string>();
            if (line == null) return values;

            var sb = new StringBuilder();
            bool inQuotes = false;
            for (int i = 0; i < line.Length; i++)
            {
                char ch = line[i];
                if (ch == '"')
                {
                    if (inQuotes && i + 1 < line.Length && line[i + 1] == '"')
                    {
                        sb.Append('"');
                        i++;
                    }
                    else
                    {
                        inQuotes = !inQuotes;
                    }
                    continue;
                }

                if (ch == ',' && !inQuotes)
                {
                    values.Add(sb.ToString());
                    sb.Clear();
                    continue;
                }

                sb.Append(ch);
            }

            values.Add(sb.ToString());
            return values;
        }

        private static int IndexOfHeader(IReadOnlyList<string> headers, params string[] names)
        {
            if (headers == null || names == null) return -1;
            for (int i = 0; i < headers.Count; i++)
            {
                string h = (headers[i] ?? "").Trim();
                foreach (string n in names)
                {
                    if (string.Equals(h, n, StringComparison.OrdinalIgnoreCase))
                    {
                        return i;
                    }
                }
            }

            return -1;
        }

        private static string ValueAt(IReadOnlyList<string> cells, int index)
        {
            if (cells == null || index < 0 || index >= cells.Count) return "";
            return cells[index]?.Trim() ?? "";
        }

        private static int IntAt(IReadOnlyList<string> cells, int index)
        {
            string value = ValueAt(cells, index);
            if (int.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out int i)) return i;
            if (int.TryParse(value, NumberStyles.Any, CultureInfo.CurrentCulture, out i)) return i;
            return 0;
        }

        private static double DoubleAt(IReadOnlyList<string> cells, int index)
        {
            string value = ValueAt(cells, index);
            if (double.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out double d)) return d;
            if (double.TryParse(value, NumberStyles.Any, CultureInfo.CurrentCulture, out d)) return d;
            return 0.0;
        }

        private static bool BoolAt(IReadOnlyList<string> cells, int index, bool defaultValue = true)
        {
            string value = ValueAt(cells, index);
            if (string.IsNullOrWhiteSpace(value)) return defaultValue;
            if (string.Equals(value, "1", StringComparison.OrdinalIgnoreCase)) return true;
            if (string.Equals(value, "0", StringComparison.OrdinalIgnoreCase)) return false;
            if (bool.TryParse(value, out bool b)) return b;
            return defaultValue;
        }

        private static PrepareBoqImportResult ReadPrepareBoqFromCsv(string path)
        {
            var result = new PrepareBoqImportResult();
            string[] lines = File.ReadAllLines(path);
            if (lines.Length == 0) return result;

            List<string> headers = ParseCsvLine(lines[0]);
            int idxUse = IndexOfHeader(headers, "Use", "Enabled");
            int idxSheet = IndexOfHeader(headers, "Sheet", "Worksheet");
            int idxItemCode = IndexOfHeader(headers, "Item Code", "ItemCode", "Code");
            int idxDescription = IndexOfHeader(headers, "Description", "Desc");
            int idxUnit = IndexOfHeader(headers, "Unit", "UOM");
            int idxElement = IndexOfHeader(headers, "Structure Element", "StructureElement", "Element");
            int idxLevel = IndexOfHeader(headers, "BuildingLevel", "Building Level", "Level");
            int idxRoom = IndexOfHeader(headers, "Room", "Room Name", "FIN.Room");
            int idxType = IndexOfHeader(headers, "Type", "Type Name", "TypeName");
            int idxQty = IndexOfHeader(headers, "Qty", "Quantity", "Tender Quantity", "Total Quantity");
            int idxVolume = IndexOfHeader(headers, "Volume (m3)", "Volume", "Concrete Volume", "Vol (m3)");
            int idxFormwork = IndexOfHeader(headers, "Formwork (m2)", "Formwork", "Formwork Area");
            int idxRuleCode = IndexOfHeader(headers, "Rule Code", "QS Rule Code", "QsRuleCode", "CBIM_QsRuleCode");
            int idxFormula = IndexOfHeader(headers, "Formula", "QS Formula", "QsFormula", "CBIM_QsFormula");
            int idxBreakdown = IndexOfHeader(headers, "Breakdown", "QS Breakdown", "QsBreakdown", "CBIM_QsBreakdown");

            if (idxUse >= 0) result.HeaderMap["Use"] = headers[idxUse];
            if (idxSheet >= 0) result.HeaderMap["Sheet"] = headers[idxSheet];
            if (idxItemCode >= 0) result.HeaderMap["ItemCode"] = headers[idxItemCode];
            if (idxDescription >= 0) result.HeaderMap["Description"] = headers[idxDescription];
            if (idxUnit >= 0) result.HeaderMap["Unit"] = headers[idxUnit];
            if (idxElement >= 0) result.HeaderMap["StructureElement"] = headers[idxElement];
            if (idxLevel >= 0) result.HeaderMap["BuildingLevel"] = headers[idxLevel];
            if (idxRoom >= 0) result.HeaderMap["Room"] = headers[idxRoom];
            if (idxType >= 0) result.HeaderMap["Type"] = headers[idxType];
            if (idxQty >= 0) result.HeaderMap["Qty"] = headers[idxQty];
            if (idxVolume >= 0) result.HeaderMap["Volume"] = headers[idxVolume];
            if (idxFormwork >= 0) result.HeaderMap["Formwork"] = headers[idxFormwork];
            if (idxRuleCode >= 0) result.HeaderMap["QsRuleCode"] = headers[idxRuleCode];
            if (idxFormula >= 0) result.HeaderMap["QsFormula"] = headers[idxFormula];
            if (idxBreakdown >= 0) result.HeaderMap["QsBreakdown"] = headers[idxBreakdown];

            for (int i = 1; i < lines.Length; i++)
            {
                if (string.IsNullOrWhiteSpace(lines[i])) continue;
                List<string> cells = ParseCsvLine(lines[i]);
                var row = new PrepareBoqRow
                {
                    IsEnabled = BoolAt(cells, idxUse, true),
                    SourceSheet = ValueAt(cells, idxSheet),
                    ItemCode = ValueAt(cells, idxItemCode),
                    Description = ValueAt(cells, idxDescription),
                    Unit = string.IsNullOrWhiteSpace(ValueAt(cells, idxUnit)) ? "EA" : ValueAt(cells, idxUnit),
                    StructureElement = ValueAt(cells, idxElement),
                    BuildingLevel = ValueAt(cells, idxLevel),
                    Room = ValueAt(cells, idxRoom),
                    TypeName = ValueAt(cells, idxType),
                    Quantity = IntAt(cells, idxQty),
                    TotalVolumeM3 = DoubleAt(cells, idxVolume),
                    TotalFormworkAreaM2 = DoubleAt(cells, idxFormwork),
                    QsRuleCode = ValueAt(cells, idxRuleCode),
                    QsFormula = ValueAt(cells, idxFormula),
                    QsBreakdown = ValueAt(cells, idxBreakdown)
                };
                if (!string.IsNullOrWhiteSpace(row.StructureElement) &&
                    !string.IsNullOrWhiteSpace(row.BuildingLevel) &&
                    !string.IsNullOrWhiteSpace(row.TypeName))
                {
                    row.LinkedBoqKey = BuildBoqKey(row.StructureElement, row.BuildingLevel, row.Room, row.TypeName);
                }
                result.Rows.Add(row);
            }

            return result;
        }

        private static PrepareBoqImportResult ReadPrepareBoqFromExcel(string path)
        {
            var result = new PrepareBoqImportResult();

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Open(path, Type.Missing, true);
                dynamic workbook = workbookObj;
                object worksheetsObj = null;
                try
                {
                    worksheetsObj = workbook.Worksheets;
                    dynamic worksheets = worksheetsObj;
                    int sheetCount = Convert.ToInt32(worksheets.Count, CultureInfo.InvariantCulture);
                    bool capturedHeader = false;
                    int importedSheets = 0;

                    for (int wsIndex = 1; wsIndex <= sheetCount; wsIndex++)
                    {
                        object worksheetObj = null;
                        object usedRangeObj = null;
                        try
                        {
                            worksheetObj = worksheets[wsIndex];
                            dynamic worksheet = worksheetObj;
                            usedRangeObj = worksheet.UsedRange;
                            dynamic usedRange = usedRangeObj;
                            object valuesObj = usedRange.Value2;
                            object[,] values = NormalizeExcelRangeToMatrix(valuesObj);
                            if (values == null)
                            {
                                continue;
                            }

                            string sheetName = Convert.ToString(worksheet.Name, CultureInfo.InvariantCulture) ?? ("Sheet" + wsIndex.ToString(CultureInfo.InvariantCulture));
                            int before = result.Rows.Count;
                            bool thisSheetCapturedHeader = AppendPrepareBoqRowsFromExcelMatrix(values, result, !capturedHeader, sheetName);
                            if (thisSheetCapturedHeader)
                            {
                                capturedHeader = true;
                            }

                            if (result.Rows.Count > before)
                            {
                                importedSheets++;
                            }
                        }
                        finally
                        {
                            SafeReleaseCom(usedRangeObj);
                            SafeReleaseCom(worksheetObj);
                        }
                    }

                    result.SheetCount = importedSheets;
                }
                finally
                {
                    SafeReleaseCom(worksheetsObj);
                }

                workbook.Close(false);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }

            return result;
        }

        private static object[,] NormalizeExcelRangeToMatrix(object valuesObj)
        {
            if (valuesObj == null)
            {
                return null;
            }

            if (valuesObj is object[,] matrix)
            {
                return matrix;
            }

            // Excel may return a scalar for single-cell UsedRange; normalize to 2D.
            var single = new object[1, 1];
            single[0, 0] = valuesObj;
            return single;
        }

        private static void ReadSiteProgressFromExcel(
            string path,
            out List<SiteProgressSummaryRow> combined,
            out List<SiteProgressSummaryRow> byBuilding,
            out int importedSheets)
        {
            combined = new List<SiteProgressSummaryRow>();
            byBuilding = new List<SiteProgressSummaryRow>();
            importedSheets = 0;

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Open(path, Type.Missing, true);
                dynamic workbook = workbookObj;
                object worksheetsObj = null;
                try
                {
                    worksheetsObj = workbook.Worksheets;
                    dynamic worksheets = worksheetsObj;
                    int sheetCount = Convert.ToInt32(worksheets.Count, CultureInfo.InvariantCulture);

                    for (int wsIndex = 1; wsIndex <= sheetCount; wsIndex++)
                    {
                        object worksheetObj = null;
                        try
                        {
                            worksheetObj = worksheets[wsIndex];
                            dynamic worksheet = worksheetObj;
                            string sheetName = (Convert.ToString(worksheet.Name, CultureInfo.InvariantCulture) ?? "").Trim();
                            List<SiteProgressSummaryRow> rows = ReadSiteProgressRowsFromWorksheet(worksheet);
                            if (rows.Count == 0)
                            {
                                continue;
                            }

                            string key = sheetName.Replace(" ", "").ToLowerInvariant();
                            if (key.Contains("overall") || key.Contains("building"))
                            {
                                byBuilding = rows;
                            }
                            else if (key.Contains("elementfloor") || key.Contains("elementandfloor") || key.Contains("element_floor"))
                            {
                                combined = rows;
                            }
                            else if (key.Contains("element") || key.Contains("floor"))
                            {
                                if (combined.Count == 0) combined = rows;
                            }
                            else if (combined.Count == 0)
                            {
                            }
                            else if (byBuilding.Count == 0)
                            {
                                byBuilding = rows;
                            }

                            importedSheets++;
                        }
                        finally
                        {
                            SafeReleaseCom(worksheetObj);
                        }
                    }
                }
                finally
                {
                    SafeReleaseCom(worksheetsObj);
                }

                workbook.Close(false);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }
        }

        private static List<SiteProgressSummaryRow> ReadSiteProgressRowsFromWorksheet(dynamic worksheet)
        {
            var rows = new List<SiteProgressSummaryRow>();
            if (worksheet == null) return rows;

            object usedRangeObj = null;
            try
            {
                usedRangeObj = worksheet.UsedRange;
                dynamic usedRange = usedRangeObj;
                object valuesObj = usedRange.Value2;
                object[,] values = NormalizeExcelRangeToMatrix(valuesObj);
                if (values == null)
                {
                    return rows;
                }

                int rMin = values.GetLowerBound(0);
                int rMax = values.GetUpperBound(0);
                int cMin = values.GetLowerBound(1);
                int cMax = values.GetUpperBound(1);

                int headerRow = -1;
                int scanMax = Math.Min(rMax, rMin + 30);
                for (int r = rMin; r <= scanMax; r++)
                {
                    var headers = new List<string>();
                    for (int c = cMin; c <= cMax; c++)
                    {
                        headers.Add(ToCellString(values[r, c]).Trim());
                    }

                    int idxProgressHeader = IndexOfHeader(headers, "Volume (%)", "Progress (%)", "Progress");
                    int idxGroupHeader = IndexOfHeader(headers, "Structure Element", "Element Structure", "BuildingLevel", "Building Level", "Building", "Group", "Name");
                    if (idxProgressHeader >= 0 && idxGroupHeader >= 0)
                    {
                        headerRow = r;
                        break;
                    }
                }

                if (headerRow < rMin)
                {
                    return rows;
                }

                var headerNames = new List<string>();
                for (int c = cMin; c <= cMax; c++)
                {
                    headerNames.Add(ToCellString(values[headerRow, c]).Trim());
                }

                int idxLevel = IndexOfHeader(headerNames, "BuildingLevel", "Building Level", "Floor", "Level");
                int idxStructure = IndexOfHeader(headerNames, "Structure Element", "Element Structure");
                int idxType = IndexOfHeader(headerNames, "Type");
                int idxGroup = IndexOfHeader(headerNames, "Building", "Group", "Name");
                int idxElements = IndexOfHeader(headerNames, "Element qty", "Elements", "Element Count", "Count");

                int idxReinfBoq = IndexOfHeader(headerNames, "Reinforcement(Kg)", "Reinforcement (Kg)");
                int idxFormBoq = IndexOfHeader(headerNames, "Formwork(m2)", "Formwork (m2)", "Formwork");
                int idxVolBoq = IndexOfHeader(headerNames, "Volume(m3)", "Volume (m3)", "Volume");
                int idxReinfPct = IndexOfHeader(headerNames, "Reinforcement(%)", "Reinforcement (%)");
                int idxFormPct = IndexOfHeader(headerNames, "Formwork(%)", "Formwork (%)");
                int idxVolPct = IndexOfHeader(headerNames, "Volume(%)", "Volume (%)", "Progress (%)");
                int idxReinfComp = IndexOfHeader(headerNames, "Reinforcement Completed(Kg)", "Reinforcement Completed");
                int idxFormComp = IndexOfHeader(headerNames, "Formwork Completed(m2)", "Formwork Completed");
                int idxVolComp = IndexOfHeader(headerNames, "Volume Completed(m3)", "Volume Completed", "Completed BOQ");
                int idxStatus = IndexOfHeader(headerNames, "Status");

                for (int r = headerRow + 1; r <= rMax; r++)
                {
                    string level = (idxLevel >= 0 && idxLevel + cMin <= cMax) ? ToCellString(values[r, cMin + idxLevel]).Trim() : "";
                    string structure = (idxStructure >= 0 && idxStructure + cMin <= cMax) ? ToCellString(values[r, cMin + idxStructure]).Trim() : "";
                    string type = (idxType >= 0 && idxType + cMin <= cMax) ? ToCellString(values[r, cMin + idxType]).Trim() : "";
                    string group = (idxGroup >= 0 && idxGroup + cMin <= cMax) ? ToCellString(values[r, cMin + idxGroup]).Trim() : "";
                    if (string.IsNullOrWhiteSpace(level) && string.IsNullOrWhiteSpace(structure) && string.IsNullOrWhiteSpace(group))
                    {
                        continue;
                    }

                    int elementCount = idxElements >= 0 && idxElements + cMin <= cMax ? ToCellInt(values[r, cMin + idxElements]) : 0;
                    double reinfBoq = idxReinfBoq >= 0 && idxReinfBoq + cMin <= cMax ? ToCellDouble(values[r, cMin + idxReinfBoq]) : 0.0;
                    double formBoq = idxFormBoq >= 0 && idxFormBoq + cMin <= cMax ? ToCellDouble(values[r, cMin + idxFormBoq]) : 0.0;
                    double volBoq = idxVolBoq >= 0 && idxVolBoq + cMin <= cMax ? ToCellDouble(values[r, cMin + idxVolBoq]) : 0.0;
                    double pReinf = idxReinfPct >= 0 && idxReinfPct + cMin <= cMax ? ToCellDouble(values[r, cMin + idxReinfPct]) : 0.0;
                    double pForm = idxFormPct >= 0 && idxFormPct + cMin <= cMax ? ToCellDouble(values[r, cMin + idxFormPct]) : 0.0;
                    double pVol = idxVolPct >= 0 && idxVolPct + cMin <= cMax ? ToCellDouble(values[r, cMin + idxVolPct]) : 0.0;
                    double reinfComp = idxReinfComp >= 0 && idxReinfComp + cMin <= cMax ? ToCellDouble(values[r, cMin + idxReinfComp]) : 0.0;
                    double formComp = idxFormComp >= 0 && idxFormComp + cMin <= cMax ? ToCellDouble(values[r, cMin + idxFormComp]) : 0.0;
                    double volComp = idxVolComp >= 0 && idxVolComp + cMin <= cMax ? ToCellDouble(values[r, cMin + idxVolComp]) : 0.0;
                    if (pReinf <= 1.0 && pReinf > 0.0) pReinf *= 100.0;
                    if (pForm <= 1.0 && pForm > 0.0) pForm *= 100.0;
                    if (pVol <= 1.0 && pVol > 0.0) pVol *= 100.0;
                    if (reinfBoq > 1e-9 && reinfComp <= 1e-9 && pReinf > 0.0) reinfComp = reinfBoq * pReinf / 100.0;
                    if (formBoq > 1e-9 && formComp <= 1e-9 && pForm > 0.0) formComp = formBoq * pForm / 100.0;
                    if (volBoq > 1e-9 && volComp <= 1e-9 && pVol > 0.0) volComp = volBoq * pVol / 100.0;
                    if (reinfBoq > 1e-9 && pReinf <= 0.0 && reinfComp > 0.0) pReinf = reinfComp * 100.0 / reinfBoq;
                    if (formBoq > 1e-9 && pForm <= 0.0 && formComp > 0.0) pForm = formComp * 100.0 / formBoq;
                    if (volBoq > 1e-9 && pVol <= 0.0 && volComp > 0.0) pVol = volComp * 100.0 / volBoq;
                    string status = idxStatus >= 0 && idxStatus + cMin <= cMax ? ToCellString(values[r, cMin + idxStatus]).Trim() : "";
                    double progress = pVol > 0.0 ? pVol : (pForm > 0.0 ? pForm : pReinf);
                    if (string.IsNullOrWhiteSpace(status))
                    {
                        status = progress <= 0.0 ? "Not Started" : (progress >= 99.99 ? "Completed" : "In Progress");
                    }

                    rows.Add(new SiteProgressSummaryRow
                    {
                        GroupName = group,
                        StructureElement = structure,
                        BuildingLevel = level,
                        TypeName = type,
                        ElementCount = elementCount,
                        ReinforcementKg = reinfBoq,
                        FormworkM2 = formBoq,
                        VolumeM3 = volBoq,
                        SiteProgressReinforcementPercent = pReinf,
                        SiteProgressFormworkPercent = pForm,
                        SiteProgressVolumePercent = pVol,
                        ReinforcementCompletedKg = reinfComp,
                        FormworkCompletedM2 = formComp,
                        VolumeCompletedM3 = volComp,
                        Status = status,
                        ProgressPercent = progress,
                        TotalBoq = volBoq,
                        CompletedBoq = volComp
                    });
                }
            }
            finally
            {
                SafeReleaseCom(usedRangeObj);
            }

            return rows;
        }

        private static bool AppendPrepareBoqRowsFromExcelMatrix(object[,] values, PrepareBoqImportResult result, bool captureHeaderMap, string sheetName)
        {
            if (values == null || result == null)
            {
                return false;
            }

            int rMin = values.GetLowerBound(0);
            int rMax = values.GetUpperBound(0);
            int cMin = values.GetLowerBound(1);
            int cMax = values.GetUpperBound(1);

            int headerRow = -1;
            int scanMax = Math.Min(rMax, rMin + 120);
            for (int r = rMin; r <= scanMax; r++)
            {
                for (int c = cMin; c <= cMax; c++)
                {
                    string v = Convert.ToString(values[r, c], CultureInfo.InvariantCulture) ?? "";
                    if (v.IndexOf("description", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        headerRow = r;
                        break;
                    }
                }

                if (headerRow >= rMin) break;
            }

            int idxNo = cMin;
            int idxDescription = cMin + 1 <= cMax ? cMin + 1 : cMin;
            int idxUnit = cMin + 2 <= cMax ? cMin + 2 : cMin;
            int idxElement = -1;
            int idxLevel = -1;
            int idxRoom = -1;
            int idxType = -1;
            int idxQty = -1;
            int idxVolume = -1;
            int idxFormwork = -1;
            int idxRuleCode = -1;
            int idxFormula = -1;
            int idxBreakdown = -1;
            int startRow = rMin;
            bool headerCaptured = false;

            if (headerRow >= rMin)
            {
                startRow = headerRow + 1;
                for (int c = cMin; c <= cMax; c++)
                {
                    string h = Convert.ToString(values[headerRow, c], CultureInfo.InvariantCulture) ?? "";
                    string hc = h.Trim();
                    if (string.Equals(hc, "NO.", StringComparison.OrdinalIgnoreCase) || string.Equals(hc, "NO", StringComparison.OrdinalIgnoreCase))
                        idxNo = c;
                    else if (string.Equals(hc, "DESCRIPTION", StringComparison.OrdinalIgnoreCase) || string.Equals(hc, "Description", StringComparison.OrdinalIgnoreCase))
                        idxDescription = c;
                    else if (string.Equals(hc, "UNIT", StringComparison.OrdinalIgnoreCase) || string.Equals(hc, "Unit", StringComparison.OrdinalIgnoreCase))
                        idxUnit = c;
                    else if (string.Equals(hc, "Structure Element", StringComparison.OrdinalIgnoreCase))
                        idxElement = c;
                    else if (string.Equals(hc, "BuildingLevel", StringComparison.OrdinalIgnoreCase) || string.Equals(hc, "Building Level", StringComparison.OrdinalIgnoreCase))
                        idxLevel = c;
                    else if (string.Equals(hc, "Room", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "Room Name", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "FIN.Room", StringComparison.OrdinalIgnoreCase))
                        idxRoom = c;
                    else if (string.Equals(hc, "Type", StringComparison.OrdinalIgnoreCase))
                        idxType = c;
                    else if (string.Equals(hc, "Qty", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "Quantity", StringComparison.OrdinalIgnoreCase) ||
                             hc.IndexOf("quantity", StringComparison.OrdinalIgnoreCase) >= 0)
                        idxQty = c;
                    else if (string.Equals(hc, "Volume (m3)", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "Volume", StringComparison.OrdinalIgnoreCase) ||
                             hc.IndexOf("volume", StringComparison.OrdinalIgnoreCase) >= 0)
                        idxVolume = c;
                    else if (string.Equals(hc, "Formwork (m2)", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "Formwork", StringComparison.OrdinalIgnoreCase) ||
                             hc.IndexOf("formwork", StringComparison.OrdinalIgnoreCase) >= 0)
                        idxFormwork = c;
                    else if (string.Equals(hc, "Rule Code", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "QS Rule Code", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "QsRuleCode", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "CBIM_QsRuleCode", StringComparison.OrdinalIgnoreCase))
                        idxRuleCode = c;
                    else if (string.Equals(hc, "Formula", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "QS Formula", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "QsFormula", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "CBIM_QsFormula", StringComparison.OrdinalIgnoreCase))
                        idxFormula = c;
                    else if (string.Equals(hc, "Breakdown", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "QS Breakdown", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "QsBreakdown", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(hc, "CBIM_QsBreakdown", StringComparison.OrdinalIgnoreCase))
                        idxBreakdown = c;
                }

                if (captureHeaderMap)
                {
                    if (idxNo >= cMin) result.HeaderMap["ItemCode"] = ToCellString(values[headerRow, idxNo]);
                    if (idxDescription >= cMin) result.HeaderMap["Description"] = ToCellString(values[headerRow, idxDescription]);
                    if (idxUnit >= cMin) result.HeaderMap["Unit"] = ToCellString(values[headerRow, idxUnit]);
                    if (idxElement >= cMin) result.HeaderMap["StructureElement"] = ToCellString(values[headerRow, idxElement]);
                    if (idxLevel >= cMin) result.HeaderMap["BuildingLevel"] = ToCellString(values[headerRow, idxLevel]);
                    if (idxRoom >= cMin) result.HeaderMap["Room"] = ToCellString(values[headerRow, idxRoom]);
                    if (idxType >= cMin) result.HeaderMap["Type"] = ToCellString(values[headerRow, idxType]);
                    if (idxQty >= cMin) result.HeaderMap["Qty"] = ToCellString(values[headerRow, idxQty]);
                    if (idxVolume >= cMin) result.HeaderMap["Volume"] = ToCellString(values[headerRow, idxVolume]);
                    if (idxFormwork >= cMin) result.HeaderMap["Formwork"] = ToCellString(values[headerRow, idxFormwork]);
                    if (idxRuleCode >= cMin) result.HeaderMap["QsRuleCode"] = ToCellString(values[headerRow, idxRuleCode]);
                    if (idxFormula >= cMin) result.HeaderMap["QsFormula"] = ToCellString(values[headerRow, idxFormula]);
                    if (idxBreakdown >= cMin) result.HeaderMap["QsBreakdown"] = ToCellString(values[headerRow, idxBreakdown]);
                    headerCaptured = true;
                }
            }

            for (int r = startRow; r <= rMax; r++)
            {
                string code = ToCellString(values[r, idxNo]);
                string desc = ToCellString(values[r, idxDescription]);
                string unit = ToCellString(values[r, idxUnit]);
                string element = idxElement >= cMin ? ToCellString(values[r, idxElement]) : "";
                string level = idxLevel >= cMin ? ToCellString(values[r, idxLevel]) : "";
                string room = idxRoom >= cMin ? ToCellString(values[r, idxRoom]) : "";
                string type = idxType >= cMin ? ToCellString(values[r, idxType]) : "";
                int qty = idxQty >= cMin ? ToCellInt(values[r, idxQty]) : 0;
                double vol = idxVolume >= cMin ? ToCellDouble(values[r, idxVolume]) : 0.0;
                double fwk = idxFormwork >= cMin ? ToCellDouble(values[r, idxFormwork]) : 0.0;
                string ruleCode = idxRuleCode >= cMin ? ToCellString(values[r, idxRuleCode]) : "";
                string formula = idxFormula >= cMin ? ToCellString(values[r, idxFormula]) : "";
                string breakdown = idxBreakdown >= cMin ? ToCellString(values[r, idxBreakdown]) : "";

                if (string.IsNullOrWhiteSpace(code) &&
                    string.IsNullOrWhiteSpace(desc) &&
                    string.IsNullOrWhiteSpace(element) &&
                    string.IsNullOrWhiteSpace(type))
                {
                    continue;
                }

                result.Rows.Add(new PrepareBoqRow
                {
                    IsEnabled = true,
                    SourceSheet = sheetName ?? "",
                    ItemCode = code,
                    Description = desc,
                    Unit = string.IsNullOrWhiteSpace(unit) ? "EA" : unit,
                    StructureElement = element,
                    BuildingLevel = level,
                    Room = room,
                    TypeName = type,
                    Quantity = qty,
                    TotalVolumeM3 = vol,
                    TotalFormworkAreaM2 = fwk,
                    QsRuleCode = ruleCode,
                    QsFormula = formula,
                    QsBreakdown = breakdown,
                    LinkedBoqKey =
                        !string.IsNullOrWhiteSpace(element) &&
                        !string.IsNullOrWhiteSpace(level) &&
                        !string.IsNullOrWhiteSpace(type)
                            ? BuildBoqKey(element, level, room, type)
                            : ""
                });
            }

            return headerCaptured;
        }

        private static string ToCellString(object value)
        {
            if (value == null) return "";
            string s = Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
            return s.Trim();
        }

        private static string NormalizeImportedHeaderCell(string raw)
        {
            string text = (raw ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            if (TryExtractHeaderNameFromJson(text, out string name))
            {
                return name;
            }

            return text;
        }

        private static bool TryExtractHeaderNameFromJson(string headerCell, out string name)
        {
            name = "";
            string text = (headerCell ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return false;
            }

            Match match = ImportedHeaderNameRegex.Match(text);
            if (!match.Success)
            {
                return false;
            }

            string extracted = (match.Groups["name"]?.Value ?? "").Trim();
            if (string.IsNullOrWhiteSpace(extracted))
            {
                return false;
            }

            name = extracted;
            return true;
        }

        private static int ToCellInt(object value)
        {
            string s = ToCellString(value);
            if (int.TryParse(s, NumberStyles.Any, CultureInfo.InvariantCulture, out int i)) return i;
            if (int.TryParse(s, NumberStyles.Any, CultureInfo.CurrentCulture, out i)) return i;
            return 0;
        }

        private static double ToCellDouble(object value)
        {
            string s = ToCellString(value);
            if (double.TryParse(s, NumberStyles.Any, CultureInfo.InvariantCulture, out double d)) return d;
            if (double.TryParse(s, NumberStyles.Any, CultureInfo.CurrentCulture, out d)) return d;
            return 0.0;
        }

        private static string SanitizeForTab(string value)
        {
            if (string.IsNullOrWhiteSpace(value)) return "";
            return value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ').Trim();
        }

        private static string EscapeCsv(string value)
        {
            string sanitized = SanitizeForTab(value);
            if (sanitized.IndexOfAny(new[] { ',', '"', ';' }) >= 0)
            {
                return "\"" + sanitized.Replace("\"", "\"\"") + "\"";
            }
            return sanitized;
        }

        private bool TryBuildSiteProgressClipboardPayload(out string tsv, out int rowCount)
        {
            tsv = "";
            rowCount = 0;

            List<SiteProgressSummaryRow> combined = _siteProgressCombinedRows.ToList();
            List<SiteProgressSummaryRow> byBuilding = _siteProgressByBuildingRows.ToList();
            if (combined.Count == 0 && byBuilding.Count == 0)
            {
                return false;
            }

            var sb = new StringBuilder();
            sb.AppendLine("By Element + Floor");
            sb.AppendLine("BuildingLevel\tStructure Element\tType\tElement qty\tReinforcement(Kg)\tFormwork(m2)\tVolume(m3)\tReinforcement(%)\tFormwork(%)\tVolume(%)\tReinforcement Completed(Kg)\tFormwork Completed(m2)\tVolume Completed(m3)\tStatus");
            foreach (SiteProgressSummaryRow row in combined)
            {
                sb.Append(SanitizeForTab(row.BuildingLevel)).Append('\t')
                  .Append(SanitizeForTab(row.StructureElement)).Append('\t')
                  .Append(SanitizeForTab(row.TypeName)).Append('\t')
                  .Append(row.ElementCount.ToString(CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.ReinforcementKg.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.FormworkM2.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.VolumeM3.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.SiteProgressReinforcementPercent.ToString("0.##", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.SiteProgressFormworkPercent.ToString("0.##", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.SiteProgressVolumePercent.ToString("0.##", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.ReinforcementCompletedKg.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.FormworkCompletedM2.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.VolumeCompletedM3.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(SanitizeForTab(row.Status))
                  .AppendLine();
            }

            sb.AppendLine();
            sb.AppendLine("Overall (By Building)");
            sb.AppendLine("Building\tElements\tTotal BOQ\tCompleted BOQ\tProgress (%)");
            foreach (SiteProgressSummaryRow row in byBuilding)
            {
                sb.Append(SanitizeForTab(row.GroupName)).Append('\t')
                  .Append(row.ElementCount.ToString(CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.TotalBoq.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.CompletedBoq.ToString("0.###", CultureInfo.InvariantCulture)).Append('\t')
                  .Append(row.ProgressPercent.ToString("0.##", CultureInfo.InvariantCulture))
                  .AppendLine();
            }

            rowCount = combined.Count + byBuilding.Count;
            tsv = sb.ToString();
            return true;
        }

        private void ExportSiteProgressRowsToExcel(
            List<SiteProgressSummaryRow> combined,
            List<SiteProgressSummaryRow> byBuilding,
            List<SiteProgressElementDetailRow> elementRows,
            string filePath)
        {
            combined = combined ?? new List<SiteProgressSummaryRow>();
            byBuilding = byBuilding ?? new List<SiteProgressSummaryRow>();
            elementRows = elementRows ?? new List<SiteProgressElementDetailRow>();

            var byBuildingFloor = elementRows
                .GroupBy(r => new
                {
                    Building = string.IsNullOrWhiteSpace(r.StructuralPlan) ? "Unassigned" : r.StructuralPlan,
                    Floor = string.IsNullOrWhiteSpace(r.BuildingLevel) ? "Unassigned" : r.BuildingLevel
                })
                .Select(g =>
                {
                    double total = g.Sum(x => x.VolumeM3);
                    double completed = g.Sum(x => x.VolumeCompletedM3);
                    if (completed < 0.0) completed = 0.0;
                    if (completed > total && total > 0.0) completed = total;
                    double remaining = Math.Max(0.0, total - completed);
                    double progress = total > 1e-9 ? (completed * 100.0 / total) : 0.0;
                    progress = Math.Max(0.0, Math.Min(100.0, progress));
                    string status = progress <= 0.0 ? "Not Started" : (progress >= 99.99 ? "Completed" : "In Progress");
                    return new
                    {
                        g.Key.Building,
                        g.Key.Floor,
                        ElementCount = g.Count(),
                        TotalBoq = total,
                        CompletedBoq = completed,
                        RemainingBoq = remaining,
                        ProgressPercent = progress,
                        Status = status
                    };
                })
                .OrderBy(r => r.Building, StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.Floor, StringComparer.OrdinalIgnoreCase)
                .ToList();

            SiteProgressSummaryRow overallRow = byBuilding.FirstOrDefault(r =>
                string.Equals(r.GroupName, "Entire Building", StringComparison.OrdinalIgnoreCase));

            double totalBoq;
            double completedBoq;
            int totalElements;
            if (elementRows.Count > 0)
            {
                totalBoq = elementRows.Sum(r => r.VolumeM3);
                completedBoq = elementRows.Sum(r => r.VolumeCompletedM3);
                totalElements = elementRows.Count;
            }
            else if (overallRow != null)
            {
                totalBoq = overallRow.TotalBoq;
                completedBoq = overallRow.CompletedBoq;
                totalElements = overallRow.ElementCount;
            }
            else
            {
                totalBoq = combined.Sum(r => r.VolumeM3);
                completedBoq = combined.Sum(r => r.VolumeCompletedM3);
                totalElements = combined.Sum(r => r.ElementCount);
            }

            if (completedBoq < 0.0) completedBoq = 0.0;
            if (completedBoq > totalBoq && totalBoq > 0.0) completedBoq = totalBoq;
            double remainingBoq = Math.Max(0.0, totalBoq - completedBoq);
            double overallProgress = totalBoq > 1e-9 ? (completedBoq * 100.0 / totalBoq) : 0.0;
            overallProgress = Math.Max(0.0, Math.Min(100.0, overallProgress));

            int statusNotStarted = elementRows.Count(r => string.Equals(r.Status, "Not Started", StringComparison.OrdinalIgnoreCase));
            int statusInProgress = elementRows.Count(r => string.Equals(r.Status, "In Progress", StringComparison.OrdinalIgnoreCase));
            int statusCompleted = elementRows.Count(r => string.Equals(r.Status, "Completed", StringComparison.OrdinalIgnoreCase));

            string scopeLabel = GetSiteProgressScope().ToString();
            string structureFilter = (SiteProgressStructureFilterCombo?.SelectedItem as string) ?? SiteProgressFilterAll;
            string buildingFilter = (SiteProgressBuildingLevelFilterCombo?.SelectedItem as string) ?? SiteProgressFilterAll;

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;
            object summarySheetObj = null;
            object byFloorSheetObj = null;
            object combinedSheetObj = null;
            object detailSheetObj = null;
            object summaryRangeObj = null;
            object byFloorRangeObj = null;
            object combinedRangeObj = null;
            object detailRangeObj = null;
            object summaryHeaderRangeObj = null;
            object byFloorHeaderRangeObj = null;
            object combinedHeaderRangeObj = null;
            object detailHeaderRangeObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Add();
                dynamic workbook = workbookObj;

                summarySheetObj = workbook.Worksheets[1];
                dynamic summarySheet = summarySheetObj;
                summarySheet.Name = "ManagementSummary";

                while (workbook.Worksheets.Count < 4)
                {
                    workbook.Worksheets.Add(After: workbook.Worksheets[workbook.Worksheets.Count]);
                }

                byFloorSheetObj = workbook.Worksheets[2];
                dynamic byFloorSheet = byFloorSheetObj;
                byFloorSheet.Name = "ByBuildingFloor";

                combinedSheetObj = workbook.Worksheets[3];
                dynamic combinedSheet = combinedSheetObj;
                combinedSheet.Name = "ByElementFloor";

                detailSheetObj = workbook.Worksheets[4];
                dynamic detailSheet = detailSheetObj;
                detailSheet.Name = "ElementDetail";

                const int summaryColCount = 4;
                var summaryMatrix = new object[20, summaryColCount];
                summaryMatrix[0, 0] = "Management Progress Report";
