                SafeReleaseCom(byFloorSheetObj);
                SafeReleaseCom(summarySheetObj);
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }
        }

        private void ExportBoqRowsToExcel(List<BoqTableRow> rows, string filePath)
        {
            if (rows == null || rows.Count == 0)
            {
                throw new InvalidOperationException("No BOQ rows to export.");
            }

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;
            object worksheetObj = null;
            object rangeObj = null;
            object topLeftObj = null;
            object bottomRightObj = null;
            object headerRangeObj = null;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Add();
                dynamic workbook = workbookObj;

                worksheetObj = workbook.Worksheets[1];
                dynamic worksheet = worksheetObj;
                worksheet.Name = "BOQ";

                try
                {
                    // Keep Revit level names as text. Without this, Excel may coerce
                    // floor-like strings into dates during bulk Value2 assignment.
                    worksheet.Columns[2].NumberFormat = "@";
                }
                catch
                {
                    // Export should still continue if Excel refuses formatting.
                }

                int rowCount = rows.Count + 1;
                const int colCount = 10;
                var matrix = new object[rowCount, colCount];

                matrix[0, 0] = "Structure Element";
                matrix[0, 1] = "BuildingLevel";
                matrix[0, 2] = "Room";
                matrix[0, 3] = "Type";
                matrix[0, 4] = "Qty";
                matrix[0, 5] = "Volume (m3)";
                matrix[0, 6] = "Formwork (m2)";
                matrix[0, 7] = "Rule Code";
                matrix[0, 8] = "Formula";
                matrix[0, 9] = "Breakdown";

                for (int i = 0; i < rows.Count; i++)
                {
                    BoqTableRow row = rows[i];
                    matrix[i + 1, 0] = row.StructureElement ?? "";
                    matrix[i + 1, 1] = row.BuildingLevel ?? "";
                    matrix[i + 1, 2] = row.Room ?? "";
                    matrix[i + 1, 3] = row.TypeName ?? "";
                    matrix[i + 1, 4] = row.Quantity;
                    matrix[i + 1, 5] = Math.Round(row.TotalVolumeM3, 3);
                    matrix[i + 1, 6] = Math.Round(row.TotalFormworkAreaM2, 3);
                    matrix[i + 1, 7] = row.QsRuleCode ?? "";
                    matrix[i + 1, 8] = row.QsFormula ?? "";
                    matrix[i + 1, 9] = row.QsBreakdown ?? "";
                }

                topLeftObj = worksheet.Cells[1, 1];
                bottomRightObj = worksheet.Cells[rowCount, colCount];
                rangeObj = worksheet.Range[topLeftObj, bottomRightObj];
                dynamic range = rangeObj;
                range.Value2 = matrix;

                headerRangeObj = worksheet.Range[worksheet.Cells[1, 1], worksheet.Cells[1, colCount]];
                dynamic headerRange = headerRangeObj;
                headerRange.Font.Bold = true;

                try
                {
                    worksheet.Columns.AutoFit();
                }
                catch
                {
                    // ignore formatting issues
                }

                // 51 = xlOpenXMLWorkbook (*.xlsx)
                workbook.SaveAs(filePath, 51);
                workbook.Close(true);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(headerRangeObj);
                SafeReleaseCom(bottomRightObj);
                SafeReleaseCom(topLeftObj);
                SafeReleaseCom(rangeObj);
                SafeReleaseCom(worksheetObj);
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }
        }

        private static object GetBoqReportExportValue(BoqReportRow row, string bindingPath)
        {
            return GetBoqReportExportValue(row, new BoqReportColumnSpec { BindingPath = bindingPath ?? "" });
        }

        private static object GetBoqReportExportValue(BoqReportRow row, BoqReportColumnSpec column)
        {
            string bindingPath = column?.BindingPath ?? "";
            if (row == null || string.IsNullOrWhiteSpace(bindingPath))
            {
                return "";
            }

            PropertyInfo prop = typeof(BoqReportRow).GetProperty(bindingPath);
            object value = prop?.GetValue(row, null);
            if (value is double d)
            {
                return Math.Round(d, 3);
            }
            if (value is float f)
            {
                return Math.Round(f, 3);
            }
            if (column?.IsNumeric == true && value is string s)
            {
                string text = (s ?? "").Trim();
                if (text.Length == 0)
                {
                    return "";
                }

                if (double.TryParse(text, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out double parsed))
                {
                    return Math.Round(parsed, 3);
                }
            }

            return value ?? "";
        }

        private void ExportBoqReportWorkbookToExcel(List<BoqReportExportSheet> sheets, string filePath)
        {
            sheets = (sheets ?? new List<BoqReportExportSheet>())
                .Where(s => s != null && s.Rows != null && s.Rows.Count > 0 && s.Columns != null && s.Columns.Count > 0)
                .ToList();
            if (sheets.Count == 0)
            {
                throw new InvalidOperationException("No BOQ report sheets to export.");
            }

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;
            string filterSummary = GetBoqReportFilterSummary();
            int autoFitPages = GetBoqReportAutoFitPageCount();
            List<BoqReportAuditSheetSpec> auditSheets = BuildBoqReportAuditSheetSpecs();

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ?? throw new InvalidOperationException("Microsoft Excel is not available.");
                appObj = Activator.CreateInstance(excelType);
                dynamic app = appObj;
                app.DisplayAlerts = false;
                app.Visible = false;

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;
                workbookObj = workbooks.Add();
                dynamic workbook = workbookObj;
                int workbookSheetCount = sheets.Count + auditSheets.Count + 1;

                while (workbook.Worksheets.Count < workbookSheetCount)
                {
                    workbook.Worksheets.Add(After: workbook.Worksheets[workbook.Worksheets.Count]);
                }

                while (workbook.Worksheets.Count > workbookSheetCount)
                {
                    object extraSheetObj = null;
                    try
                    {
                        extraSheetObj = workbook.Worksheets[workbook.Worksheets.Count];
                        dynamic extraSheet = extraSheetObj;
                        extraSheet.Delete();
                    }
                    finally
                    {
                        SafeReleaseCom(extraSheetObj);
                    }
                }

                var usedSheetNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                object indexSheetObj = null;
                try
                {
                    indexSheetObj = workbook.Worksheets[1];
                    dynamic indexSheet = indexSheetObj;
                    indexSheet.Name = BuildLinksheetSafeSheetName("Report Index", usedSheetNames);
                    WriteBoqReportIndexWorksheet(indexSheet, sheets, auditSheets, filterSummary, autoFitPages);
                }
                finally
                {
                    SafeReleaseCom(indexSheetObj);
                }

                for (int i = 0; i < sheets.Count; i++)
                {
                    object worksheetObj = null;
                    try
                    {
                        worksheetObj = workbook.Worksheets[i + 2];
                        dynamic worksheet = worksheetObj;
                        worksheet.Name = BuildLinksheetSafeSheetName(sheets[i].SheetName, usedSheetNames);
                        WriteBoqReportSheetToWorksheet(worksheet, sheets[i], filterSummary, autoFitPages);
                    }
                    finally
                    {
                        SafeReleaseCom(worksheetObj);
                    }
                }

                for (int i = 0; i < auditSheets.Count; i++)
                {
                    object worksheetObj = null;
                    try
                    {
                        worksheetObj = workbook.Worksheets[sheets.Count + i + 2];
                        dynamic worksheet = worksheetObj;
                        BoqReportAuditSheetSpec auditSheet = auditSheets[i];
                        worksheet.Name = BuildLinksheetSafeSheetName(auditSheet.SheetName, usedSheetNames);
                        WriteBoqReportAuditWorksheet(worksheet, auditSheet, filterSummary, autoFitPages);
                    }
                    finally
                    {
                        SafeReleaseCom(worksheetObj);
                    }
                }

                try
                {
                    object firstSheetObj = workbook.Worksheets[1];
                    dynamic firstSheet = firstSheetObj;
                    firstSheet.Activate();
                    SafeReleaseCom(firstSheetObj);
                }
                catch
                {
                    // Workbook content is complete even if Excel refuses to activate the index sheet.
                }

                workbook.SaveAs(filePath, 51);
                workbook.Close(true);
                app.Quit();
            }
            finally
            {
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }
        }

        private List<BoqReportAuditSheetSpec> BuildBoqReportAuditSheetSpecs()
        {
            int settingsRows = GetBoqReportAuditSettingsRows().Count;
            int rulesRows = GetBoqReportAuditRulesRows().Count;
            List<BoqTableRow> sourceRows = GetBoqReportFilteredSourceRows();
            int controlRows = BuildBoqReportControlTotalRows(sourceRows).Count;
            int coverageRows = BuildBoqReportRuleCoverageRows(sourceRows).Count;
            int exceptionRows = BuildBoqReportExceptionRows(sourceRows).Count;
            int traceBucketRows = BuildBoqReportTraceBucketRows(sourceRows).Count;

            return new List<BoqReportAuditSheetSpec>
            {
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Audit Summary",
                    Title = "BOQ Report Audit Summary",
                    RowCount = 14
                },
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Audit Settings",
                    Title = "Measurement Settings Audit",
                    RowCount = settingsRows
                },
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Audit Rules",
                    Title = "Measurement Rules Audit",
                    RowCount = rulesRows
                },
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Check Totals",
                    Title = "TAS Quantity Control Totals",
                    Type = "Control",
                    RowCount = controlRows
                },
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Check Rule Coverage",
                    Title = "Measurement Rule Coverage Check",
                    Type = "Control",
                    RowCount = coverageRows
                },
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Check Exceptions",
                    Title = "TAS Report Exception Review",
                    Type = "Control",
                    RowCount = exceptionRows
                },
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Trace Elements",
                    Title = "Element Quantity Trace",
                    Type = "Trace",
                    RowCount = sourceRows.Count
                },
                new BoqReportAuditSheetSpec
                {
                    SheetName = "Trace QS Buckets",
                    Title = "QS Bucket Trace",
                    Type = "Trace",
                    RowCount = traceBucketRows
                }
            };
        }

        private static void WriteBoqReportIndexWorksheet(dynamic worksheet, List<BoqReportExportSheet> sheets, List<BoqReportAuditSheetSpec> auditSheets, string filterSummary, int autoFitPages)
        {
            sheets = sheets ?? new List<BoqReportExportSheet>();
            auditSheets = auditSheets ?? new List<BoqReportAuditSheetSpec>();
            int rowCount = Math.Max(12, sheets.Count + auditSheets.Count + 8);
            const int colCount = 7;
            var matrix = new object[rowCount, colCount];

            matrix[0, 0] = "CBIM QS BOQ Report";
            matrix[1, 0] = "Project Name";
            matrix[1, 1] = GetBoqReportProjectName();
            matrix[2, 0] = "Compile Date";
            matrix[2, 1] = DateTime.Now.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture);
            matrix[3, 0] = "Report Scope";
            matrix[3, 1] = filterSummary ?? "";
            matrix[4, 0] = "Auto-Fit Pages";
            matrix[4, 1] = autoFitPages.ToString(CultureInfo.InvariantCulture);
            matrix[6, 0] = "No.";
            matrix[6, 1] = "Sheet";
            matrix[6, 2] = "Type";
            matrix[6, 3] = "Report";
            matrix[6, 4] = "Rows";
            matrix[6, 5] = "Volume (m3)";
            matrix[6, 6] = "Formwork (m2)";

            for (int i = 0; i < sheets.Count; i++)
            {
                BoqReportExportSheet sheet = sheets[i];
                int r = i + 7;
                matrix[r, 0] = i + 1;
                matrix[r, 1] = sheet.SheetName ?? "";
                matrix[r, 2] = "Report";
                matrix[r, 3] = sheet.Title ?? "";
                matrix[r, 4] = sheet.Rows?.Count ?? 0;
                matrix[r, 5] = Math.Round((sheet.Rows ?? new List<BoqReportRow>()).Sum(x => x.TotalVolumeM3), 3);
                matrix[r, 6] = Math.Round((sheet.Rows ?? new List<BoqReportRow>()).Sum(x => x.TotalFormworkAreaM2), 3);
            }

            for (int i = 0; i < auditSheets.Count; i++)
            {
                BoqReportAuditSheetSpec sheet = auditSheets[i];
                int r = sheets.Count + i + 7;
                matrix[r, 0] = sheets.Count + i + 1;
                matrix[r, 1] = sheet.SheetName ?? "";
                matrix[r, 2] = string.IsNullOrWhiteSpace(sheet.Type) ? "Audit" : sheet.Type;
                matrix[r, 3] = sheet.Title ?? "";
                matrix[r, 4] = sheet.RowCount;
                matrix[r, 5] = "";
                matrix[r, 6] = "";
            }

            object topLeftObj = null;
            object bottomRightObj = null;
            object rangeObj = null;
            object titleRangeObj = null;
            object titleRightObj = null;
            object headerRangeObj = null;
            object headerRightObj = null;

            try
            {
                topLeftObj = worksheet.Cells[1, 1];
                bottomRightObj = worksheet.Cells[rowCount, colCount];
                rangeObj = worksheet.Range[topLeftObj, bottomRightObj];
                dynamic range = rangeObj;
                range.Value2 = matrix;

                titleRightObj = worksheet.Cells[1, colCount];
                titleRangeObj = worksheet.Range[topLeftObj, titleRightObj];
                dynamic titleRange = titleRangeObj;
                titleRange.Merge();
                titleRange.Font.Bold = true;
                titleRange.Font.Size = 16;
                titleRange.HorizontalAlignment = -4108;
                titleRange.Interior.Color = ToExcelOleColor(31, 78, 121);
                titleRange.Font.Color = ToExcelOleColor(255, 255, 255);

                headerRightObj = worksheet.Cells[7, colCount];
                headerRangeObj = worksheet.Range[worksheet.Cells[7, 1], headerRightObj];
                dynamic headerRange = headerRangeObj;
                headerRange.Font.Bold = true;
                headerRange.Interior.Color = ToExcelOleColor(157, 195, 230);
                headerRange.HorizontalAlignment = -4108;

                range.Borders.LineStyle = 1;
                range.Borders.Color = 0;

                try
                {
                    worksheet.Columns.AutoFit();
                    worksheet.Columns[4].ColumnWidth = Math.Max(36.0, worksheet.Columns[4].ColumnWidth);
                    dynamic pageSetup = worksheet.PageSetup;
                    pageSetup.Orientation = 2;
                    pageSetup.Zoom = false;
                    pageSetup.FitToPagesWide = Math.Max(1, autoFitPages);
                    pageSetup.FitToPagesTall = false;
                    pageSetup.CenterHorizontally = true;
                }
                catch
                {
                    // Keep export resilient on machines with different Excel versions.
                }
            }
            finally
            {
                SafeReleaseCom(headerRangeObj);
                SafeReleaseCom(headerRightObj);
                SafeReleaseCom(titleRangeObj);
                SafeReleaseCom(titleRightObj);
                SafeReleaseCom(rangeObj);
                SafeReleaseCom(bottomRightObj);
                SafeReleaseCom(topLeftObj);
            }
        }

        private void WriteBoqReportAuditWorksheet(dynamic worksheet, BoqReportAuditSheetSpec auditSheet, string filterSummary, int autoFitPages)
        {
            string sheetName = auditSheet?.SheetName ?? "";
            if (string.Equals(sheetName, "Audit Settings", StringComparison.OrdinalIgnoreCase))
            {
                WriteBoqReportAuditSettingsWorksheet(worksheet, filterSummary, autoFitPages);
                return;
            }

            if (string.Equals(sheetName, "Audit Rules", StringComparison.OrdinalIgnoreCase))
            {
                WriteBoqReportAuditRulesWorksheet(worksheet, filterSummary, autoFitPages);
                return;
            }

            if (string.Equals(sheetName, "Check Totals", StringComparison.OrdinalIgnoreCase))
            {
                WriteBoqReportCheckTotalsWorksheet(worksheet, filterSummary, autoFitPages);
                return;
            }

            if (string.Equals(sheetName, "Check Rule Coverage", StringComparison.OrdinalIgnoreCase))
            {
                WriteBoqReportRuleCoverageWorksheet(worksheet, filterSummary, autoFitPages);
                return;
            }

            if (string.Equals(sheetName, "Check Exceptions", StringComparison.OrdinalIgnoreCase))
            {
                WriteBoqReportExceptionsWorksheet(worksheet, filterSummary, autoFitPages);
                return;
            }

            if (string.Equals(sheetName, "Trace Elements", StringComparison.OrdinalIgnoreCase))
            {
                WriteBoqReportTraceElementsWorksheet(worksheet, filterSummary, autoFitPages);
                return;
            }

            if (string.Equals(sheetName, "Trace QS Buckets", StringComparison.OrdinalIgnoreCase))
            {
                WriteBoqReportTraceBucketsWorksheet(worksheet, filterSummary, autoFitPages);
                return;
            }

            WriteBoqReportAuditSummaryWorksheet(worksheet, filterSummary, autoFitPages);
        }

