        private void WriteBoqReportExceptionsWorksheet(dynamic worksheet, string filterSummary, int autoFitPages)
        {
            List<BoqReportExceptionRow> rows = BuildBoqReportExceptionRows(GetBoqReportFilteredSourceRows());
            const int colCount = 11;
            int rowCount = Math.Max(1, rows.Count) + 4;
            var matrix = new object[rowCount, colCount];

            matrix[0, 0] = "TAS Report Exception Review";
            matrix[1, 0] = "Project Name: " + GetBoqReportProjectName();
            matrix[1, 6] = "Compile Date: " + DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            matrix[2, 0] = "Report Scope: " + (filterSummary ?? "");
            matrix[3, 0] = "Severity";
            matrix[3, 1] = "Source Sheet";
            matrix[3, 2] = "Reference";
            matrix[3, 3] = "Element / Category";
            matrix[3, 4] = "Floor";
            matrix[3, 5] = "Type / Name";
            matrix[3, 6] = "Rule Code";
            matrix[3, 7] = "Bucket Key";
            matrix[3, 8] = "Value";
            matrix[3, 9] = "Status";
            matrix[3, 10] = "Review Action";

            if (rows.Count == 0)
            {
                matrix[4, 0] = "OK";
                matrix[4, 1] = "Check Exceptions";
                matrix[4, 9] = "No exceptions found";
                matrix[4, 10] = "Continue TAS comparison.";
            }
            else
            {
                for (int i = 0; i < rows.Count; i++)
                {
                    BoqReportExceptionRow row = rows[i];
                    int r = i + 4;
                    matrix[r, 0] = row.Severity ?? "";
                    matrix[r, 1] = row.SourceSheet ?? "";
                    matrix[r, 2] = row.Reference ?? "";
                    matrix[r, 3] = row.StructureElement ?? "";
                    matrix[r, 4] = row.BuildingLevel ?? "";
                    matrix[r, 5] = row.TypeName ?? "";
