        private static void WriteBoqReportAuditTableWorksheet(dynamic worksheet, object[,] matrix, int rowCount, int colCount, int headerRow, int autoFitPages)
        {
            object topLeftObj = null;
            object bottomRightObj = null;
            object rangeObj = null;
            object titleRangeObj = null;
            object titleRightObj = null;
            object metaRangeObj = null;
            object headerRangeObj = null;

            try
            {
                topLeftObj = worksheet.Cells[1, 1];
                bottomRightObj = worksheet.Cells[rowCount, colCount];
                rangeObj = worksheet.Range[topLeftObj, bottomRightObj];
                dynamic range = rangeObj;
                range.Value2 = matrix;
                range.Borders.LineStyle = 1;
                range.Borders.Color = 0;
                range.VerticalAlignment = -4108;

                titleRightObj = worksheet.Cells[1, colCount];
                titleRangeObj = worksheet.Range[topLeftObj, titleRightObj];
                dynamic titleRange = titleRangeObj;
                titleRange.Merge();
                titleRange.Font.Bold = true;
                titleRange.Font.Size = 14;
                titleRange.HorizontalAlignment = -4108;
                titleRange.Interior.Color = ToExcelOleColor(31, 78, 121);
                titleRange.Font.Color = ToExcelOleColor(255, 255, 255);

                metaRangeObj = worksheet.Range[worksheet.Cells[2, 1], worksheet.Cells[3, colCount]];
                dynamic metaRange = metaRangeObj;
                metaRange.Font.Italic = true;
                metaRange.Interior.Color = ToExcelOleColor(242, 242, 242);

                headerRangeObj = worksheet.Range[worksheet.Cells[headerRow, 1], worksheet.Cells[headerRow, colCount]];
                dynamic headerRange = headerRangeObj;
                headerRange.Font.Bold = true;
                headerRange.HorizontalAlignment = -4108;
                headerRange.WrapText = true;
                headerRange.Interior.Color = ToExcelOleColor(157, 195, 230);

                try
                {
                    headerRange.AutoFilter();
                    worksheet.Rows[1].RowHeight = 24;
                    worksheet.Rows[headerRow].RowHeight = 36;
                    worksheet.Columns.AutoFit();
                    for (int c = 1; c <= colCount; c++)
                    {
                        double width = worksheet.Columns[c].ColumnWidth;
                        if (width > 46.0)
                        {
                            worksheet.Columns[c].ColumnWidth = 46.0;
                        }
                    }

                    worksheet.Columns[4].ColumnWidth = Math.Max(28.0, worksheet.Columns[4].ColumnWidth);
                    worksheet.Columns[5].ColumnWidth = Math.Max(28.0, worksheet.Columns[5].ColumnWidth);
                    worksheet.Columns[6].ColumnWidth = Math.Max(32.0, worksheet.Columns[6].ColumnWidth);
                    worksheet.Columns.WrapText = true;

                    dynamic pageSetup = worksheet.PageSetup;
                    pageSetup.Orientation = 2;
                    pageSetup.Zoom = false;
                    pageSetup.FitToPagesWide = Math.Max(1, autoFitPages);
                    pageSetup.FitToPagesTall = false;
                    pageSetup.PrintTitleRows = "$1:$4";
                    pageSetup.CenterHorizontally = true;
                }
                catch
                {
                    // Audit data is complete even when presentation settings are unavailable.
                }
            }
            finally
            {
                SafeReleaseCom(headerRangeObj);
                SafeReleaseCom(metaRangeObj);
                SafeReleaseCom(titleRangeObj);
                SafeReleaseCom(titleRightObj);
                SafeReleaseCom(rangeObj);
                SafeReleaseCom(bottomRightObj);
                SafeReleaseCom(topLeftObj);
            }
        }

