        private static List<BoqReportControlTotalRow> BuildBoqReportControlTotalRows(List<BoqTableRow> sourceRows)
        {
            List<BoqTableRow> rows = sourceRows?.Where(r => r != null).ToList() ?? new List<BoqTableRow>();
            var result = new List<BoqReportControlTotalRow>();

            foreach (IGrouping<string, BoqTableRow> group in rows
                .GroupBy(r => BuildBoqReportGroupKey(NormalizeBoqReportCategoryName(r.StructureElement), r.BuildingLevel), StringComparer.OrdinalIgnoreCase)
                .OrderBy(g => GetBoqReportCategoryOrder(NormalizeBoqReportCategoryName(g.First().StructureElement)))
                .ThenBy(g => NormalizeBoqReportCategoryName(g.First().StructureElement), StringComparer.OrdinalIgnoreCase)
                .ThenBy(g => g.First().BuildingLevel ?? "", StringComparer.OrdinalIgnoreCase))
            {
                BoqTableRow first = group.First();
                result.Add(BuildBoqReportControlTotalRow(
                    "Floor",
                    NormalizeBoqReportCategoryName(first.StructureElement),
                    string.IsNullOrWhiteSpace(first.BuildingLevel) ? "Unassigned" : first.BuildingLevel,
                    group));
            }

            foreach (IGrouping<string, BoqTableRow> group in rows
                .GroupBy(r => NormalizeBoqReportCategoryName(r.StructureElement), StringComparer.OrdinalIgnoreCase)
                .OrderBy(g => GetBoqReportCategoryOrder(g.Key))
                .ThenBy(g => g.Key, StringComparer.OrdinalIgnoreCase))
            {
                result.Add(BuildBoqReportControlTotalRow("Category Total", group.Key, "(All Floors)", group));
            }

            if (rows.Count > 0)
            {
                result.Add(BuildBoqReportControlTotalRow("Grand Total", "(All Categories)", "(All Floors)", rows));
            }

            return result;
        }

        private static BoqReportControlTotalRow BuildBoqReportControlTotalRow(
            string groupType,
            string structureElement,
            string buildingLevel,
            IEnumerable<BoqTableRow> sourceRows)
        {
            List<BoqTableRow> rows = sourceRows?.Where(r => r != null).ToList() ?? new List<BoqTableRow>();
            double volume = rows.Sum(r => r.TotalVolumeM3);
            double formwork = rows.Sum(r => r.TotalFormworkAreaM2);
            double finishGross = SumBoqReportQsValues(rows, key =>
                key.StartsWith("FIN.", StringComparison.OrdinalIgnoreCase) &&
                key.IndexOf(".Gross", StringComparison.OrdinalIgnoreCase) >= 0);
            double finishNet = SumBoqReportQsValues(rows, key =>
                key.StartsWith("FIN.", StringComparison.OrdinalIgnoreCase) &&
                key.IndexOf(".Area", StringComparison.OrdinalIgnoreCase) >= 0);
            double finishDeduct = SumBoqReportQsValues(rows, key =>
                key.StartsWith("FIN.", StringComparison.OrdinalIgnoreCase) &&
                key.IndexOf("OpeningDeduct", StringComparison.OrdinalIgnoreCase) >= 0);
            double openingArea = SumBoqReportQsValues(rows, key =>
                key.IndexOf("Opening.Area", StringComparison.OrdinalIgnoreCase) >= 0);
            double rebar = SumBoqReportQsValues(rows, key =>
                string.Equals(key, "Rebar.Weight", StringComparison.OrdinalIgnoreCase));
            int bucketCount = rows.Sum(r => r.QsValues?.Count(p => Math.Abs(p.Value) > 1e-9) ?? 0);
            int quantity = rows.Sum(r => r.Quantity);

            bool hasMeasuredQuantity =
                quantity > 0 ||
                Math.Abs(volume) > 1e-9 ||
                Math.Abs(formwork) > 1e-9 ||
                Math.Abs(finishGross) > 1e-9 ||
                Math.Abs(finishNet) > 1e-9 ||
                Math.Abs(finishDeduct) > 1e-9 ||
                Math.Abs(openingArea) > 1e-9 ||
                Math.Abs(rebar) > 1e-9;

            string status = "OK";
            if (!hasMeasuredQuantity)
            {
                status = "Check empty quantity";
            }
            else if (volume < -1e-9 || formwork < -1e-9 || finishNet < -1e-9 || rebar < -1e-9)
            {
                status = "Check negative value";
            }

            return new BoqReportControlTotalRow
            {
                GroupType = groupType ?? "",
                StructureElement = structureElement ?? "",
                BuildingLevel = buildingLevel ?? "",
                RowCount = rows.Count,
                Quantity = quantity,
                VolumeM3 = volume,
                FormworkM2 = formwork,
                FinishGrossM2 = finishGross,
                FinishNetM2 = finishNet,
                FinishDeductM2 = finishDeduct,
                OpeningAreaM2 = openingArea,
                RebarKg = rebar,
                BucketCount = bucketCount,
                Status = status
            };
        }

        private List<BoqReportRuleCoverageRow> BuildBoqReportRuleCoverageRows(List<BoqTableRow> sourceRows)
        {
            List<BoqTableRow> rows = sourceRows?.Where(r => r != null).ToList() ?? new List<BoqTableRow>();
            List<QsMeasurementRuleRow> rules = GetBoqReportAuditRulesRows(GetBoqReportAuditRulesProfile());
            var result = new List<BoqReportRuleCoverageRow>();

            foreach (QsMeasurementRuleRow rule in rules)
            {
                List<BoqTableRow> scopedRows = rows
                    .Where(r => MatchesBoqReportRuleCoverageCategory(r, rule.Category))
                    .ToList();
                string bucketKey = ExtractBoqReportRuleBucketKey(rule.Value);
                bool referenceRule = IsBoqReportReferenceRule(rule);
                int matchedRows = 0;
                double totalValue = 0.0;

                if (!string.IsNullOrWhiteSpace(bucketKey) && !referenceRule)
                {
                    foreach (BoqTableRow source in scopedRows)
                    {
                        double value = GetBoqReportRuleCoverageValue(source, bucketKey);
                        if (Math.Abs(value) > 1e-9)
                        {
                            matchedRows++;
                            totalValue += value;
                        }
                    }
                }

                result.Add(new BoqReportRuleCoverageRow
                {
                    Active = rule.IsEnabled ? "Yes" : "No",
                    Category = rule.Category ?? "",
                    Code = rule.Code ?? "",
                    TasSheet = rule.Option ?? "",
                    Description = rule.Description ?? "",
                    Mapping = rule.Value ?? "",
                    BucketKey = bucketKey,
                    Unit = rule.Unit ?? "",
                    Method = rule.Method ?? "",
                    ScopeRows = scopedRows.Count,
                    RowsMatched = matchedRows,
                    TotalValue = totalValue,
                    Status = GetBoqReportRuleCoverageStatus(rule, bucketKey, referenceRule, scopedRows.Count, matchedRows)
                });
            }

            return result;
        }

        private List<BoqReportExceptionRow> BuildBoqReportExceptionRows(List<BoqTableRow> sourceRows)
        {
            List<BoqTableRow> rows = sourceRows?.Where(r => r != null).ToList() ?? new List<BoqTableRow>();
            var result = new List<BoqReportExceptionRow>();

            foreach (BoqReportControlTotalRow row in BuildBoqReportControlTotalRows(rows))
            {
                if (string.Equals(row.Status, "OK", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                result.Add(new BoqReportExceptionRow
                {
                    Severity = string.Equals(row.Status, "Check negative value", StringComparison.OrdinalIgnoreCase) ? "Error" : "Warning",
                    SourceSheet = "Check Totals",
                    Reference = row.GroupType ?? "",
                    StructureElement = row.StructureElement ?? "",
                    BuildingLevel = row.BuildingLevel ?? "",
                    Value = Math.Abs(row.VolumeM3) > 1e-9 ? row.VolumeM3 : row.FormworkM2,
                    Status = row.Status ?? "",
                    ReviewAction = "Review source rows and measurement settings for this total group."
                });
            }

            foreach (BoqReportRuleCoverageRow row in BuildBoqReportRuleCoverageRows(rows))
            {
                if (!string.Equals(row.Active, "Yes", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (string.Equals(row.Status, "No value in scope", StringComparison.OrdinalIgnoreCase))
                {
                    result.Add(new BoqReportExceptionRow
                    {
                        Severity = "Warning",
                        SourceSheet = "Check Rule Coverage",
                        Reference = row.TasSheet ?? "",
                        StructureElement = row.Category ?? "",
                        RuleCode = row.Code ?? "",
                        BucketKey = row.BucketKey ?? "",
                        Value = row.TotalValue,
                        Status = row.Status ?? "",
                        ReviewAction = "Rule is active and source rows exist, but no matching QS bucket value was found."
                    });
                }
                else if (string.Equals(row.Status, "No source rows in scope", StringComparison.OrdinalIgnoreCase))
                {
                    result.Add(new BoqReportExceptionRow
                    {
                        Severity = "Info",
                        SourceSheet = "Check Rule Coverage",
                        Reference = row.TasSheet ?? "",
                        StructureElement = row.Category ?? "",
                        RuleCode = row.Code ?? "",
                        BucketKey = row.BucketKey ?? "",
                        Value = row.TotalValue,
                        Status = row.Status ?? "",
                        ReviewAction = "Active rule has no source rows under the current report filter."
                    });
                }
            }

            for (int i = 0; i < rows.Count; i++)
            {
                BoqTableRow row = rows[i];
                if (row == null) continue;

                bool hasMeasuredValue =
                    row.Quantity > 0 ||
                    Math.Abs(row.TotalVolumeM3) > 1e-9 ||
                    Math.Abs(row.TotalFormworkAreaM2) > 1e-9;
                int bucketCount = row.QsValues?.Count(p => Math.Abs(p.Value) > 1e-9) ?? 0;
                if (hasMeasuredValue && bucketCount == 0)
                {
                    result.Add(new BoqReportExceptionRow
                    {
                        Severity = "Warning",
                        SourceSheet = "Trace Elements",
                        Reference = "Row " + (i + 1).ToString(CultureInfo.InvariantCulture),
                        StructureElement = NormalizeBoqReportCategoryName(row.StructureElement),
                        BuildingLevel = row.BuildingLevel ?? "",
                        TypeName = row.TypeName ?? "",
                        RuleCode = row.QsRuleCode ?? "",
                        Status = "Missing QS buckets",
                        ReviewAction = "Measured row has no QS bucket trace; recalculate QS or check shared parameters."
                    });
                }

                if (row.TotalVolumeM3 < -1e-9 || row.TotalFormworkAreaM2 < -1e-9)
                {
                    result.Add(new BoqReportExceptionRow
                    {
                        Severity = "Error",
                        SourceSheet = "Trace Elements",
                        Reference = "Row " + (i + 1).ToString(CultureInfo.InvariantCulture),
                        StructureElement = NormalizeBoqReportCategoryName(row.StructureElement),
                        BuildingLevel = row.BuildingLevel ?? "",
                        TypeName = row.TypeName ?? "",
                        RuleCode = row.QsRuleCode ?? "",
                        Value = row.TotalVolumeM3 < -1e-9 ? row.TotalVolumeM3 : row.TotalFormworkAreaM2,
                        Status = "Negative row quantity",
                        ReviewAction = "Review deductions/intersections for this model item."
                    });
                }
            }

            return result
                .OrderBy(r => GetBoqReportExceptionSeverityOrder(r.Severity))
                .ThenBy(r => r.SourceSheet ?? "", StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.StructureElement ?? "", StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.BuildingLevel ?? "", StringComparer.OrdinalIgnoreCase)
                .ThenBy(r => r.RuleCode ?? "", StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static int GetBoqReportExceptionSeverityOrder(string severity)
        {
            if (string.Equals(severity, "Error", StringComparison.OrdinalIgnoreCase)) return 0;
            if (string.Equals(severity, "Warning", StringComparison.OrdinalIgnoreCase)) return 1;
            if (string.Equals(severity, "Info", StringComparison.OrdinalIgnoreCase)) return 2;
            return 3;
        }

        private static double SumBoqReportQsValues(IEnumerable<BoqTableRow> rows, Func<string, bool> keyPredicate)
        {
            if (rows == null || keyPredicate == null)
            {
                return 0.0;
            }

            double total = 0.0;
            foreach (BoqTableRow row in rows)
            {
                if (row?.QsValues == null) continue;
                foreach (KeyValuePair<string, double> pair in row.QsValues)
                {
                    string key = pair.Key ?? "";
                    if (keyPredicate(key))
                    {
                        total += pair.Value;
                    }
                }
            }

            return total;
        }

        private static bool MatchesBoqReportRuleCoverageCategory(BoqTableRow row, string ruleCategory)
        {
            if (row == null) return false;
            string rule = (ruleCategory ?? "").Trim();
            if (string.IsNullOrWhiteSpace(rule)) return true;

            string category = NormalizeBoqReportCategoryName(row.StructureElement);
            if (string.Equals(category, rule, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (rule.EndsWith(" Finish", StringComparison.OrdinalIgnoreCase) &&
                category.EndsWith(" Finish", StringComparison.OrdinalIgnoreCase))
            {
                return string.Equals(category, rule, StringComparison.OrdinalIgnoreCase);
            }

            return false;
        }

        private static string ExtractBoqReportRuleBucketKey(string mapping)
        {
            string text = (mapping ?? "").Trim();
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            if (string.Equals(text, "Element count", StringComparison.OrdinalIgnoreCase))
            {
                return "Quantity";
            }

            int aliasIndex = CultureInfo.InvariantCulture.CompareInfo.IndexOf(text, " as ", CompareOptions.IgnoreCase);
            if (aliasIndex > 0)
            {
                text = text.Substring(0, aliasIndex).Trim();
            }

            Match match = Regex.Match(text, @"(?<key>(?:FWK|FIN|CBIM|HOST)[A-Za-z0-9_.]+|Rebar\.Weight)", RegexOptions.IgnoreCase);
            return match.Success ? match.Groups["key"].Value : "";
        }

        private static bool IsBoqReportReferenceRule(QsMeasurementRuleRow rule)
        {
            string method = (rule?.Method ?? "").Trim();
            return string.Equals(method, "Classification", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(method, "Reference", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(method, "Parameter Map", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(method, "Room Grouping", StringComparison.OrdinalIgnoreCase);
        }

        private static double GetBoqReportRuleCoverageValue(BoqTableRow row, string bucketKey)
        {
            if (row == null || string.IsNullOrWhiteSpace(bucketKey))
            {
                return 0.0;
            }

            if (string.Equals(bucketKey, "Quantity", StringComparison.OrdinalIgnoreCase))
            {
                return row.Quantity;
            }

            return row.QsValues != null && row.QsValues.TryGetValue(bucketKey, out double value)
                ? value
                : 0.0;
        }

        private static string GetBoqReportRuleCoverageStatus(QsMeasurementRuleRow rule, string bucketKey, bool referenceRule, int scopeRows, int matchedRows)
        {
            if (rule == null || !rule.IsEnabled)
            {
                return "Disabled";
            }

            if (referenceRule)
            {
                return "Reference / classification";
            }

            if (string.IsNullOrWhiteSpace(bucketKey))
            {
                return "Derived / no direct bucket";
            }

            if (matchedRows > 0)
            {
                return "Matched";
            }

            return scopeRows > 0 ? "No value in scope" : "No source rows in scope";
        }

        private static List<BoqReportTraceBucketRow> BuildBoqReportTraceBucketRows(List<BoqTableRow> sourceRows)
        {
            var result = new List<BoqReportTraceBucketRow>();
            List<BoqTableRow> rows = sourceRows ?? new List<BoqTableRow>();

            for (int i = 0; i < rows.Count; i++)
            {
                BoqTableRow source = rows[i];
                if (source?.QsValues == null || source.QsValues.Count == 0)
                {
                    continue;
                }

                foreach (KeyValuePair<string, double> pair in source.QsValues
                    .Where(p => !string.IsNullOrWhiteSpace(p.Key) && Math.Abs(p.Value) > 1e-9)
                    .OrderBy(p => GetBoqReportTraceBucketClass(p.Key), StringComparer.OrdinalIgnoreCase)
                    .ThenBy(p => p.Key ?? "", StringComparer.OrdinalIgnoreCase))
                {
                    result.Add(new BoqReportTraceBucketRow
                    {
                        SourceRowNo = i + 1,
                        StructureElement = NormalizeBoqReportCategoryName(source.StructureElement),
                        BuildingLevel = source.BuildingLevel ?? "",
                        Room = source.Room ?? "",
                        TypeName = source.TypeName ?? "",
                        BucketName = pair.Key ?? "",
                        BucketClass = GetBoqReportTraceBucketClass(pair.Key),
                        Unit = GetBoqReportTraceBucketUnit(pair.Key),
                        Value = pair.Value,
                        QsRuleCode = source.QsRuleCode ?? "",
                        QsFormula = source.QsFormula ?? "",
                        QsBreakdown = source.QsBreakdown ?? ""
                    });
                }
            }

            return result;
        }

        private static string GetBoqReportTraceBucketClass(string key)
        {
            string value = key ?? "";
            if (value.IndexOf("Deduct", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf(".Sub", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return value.StartsWith("FIN.", StringComparison.OrdinalIgnoreCase)
                    ? "Finish Deduction"
                    : "Formwork Deduction";
            }

            if (value.StartsWith("FIN.", StringComparison.OrdinalIgnoreCase))
            {
                if (value.IndexOf("Gross", StringComparison.OrdinalIgnoreCase) >= 0) return "Finish Gross";
                if (value.IndexOf("Return", StringComparison.OrdinalIgnoreCase) >= 0) return "Finish Return";
                return "Finish Net";
            }

            if (value.StartsWith("FWK.", StringComparison.OrdinalIgnoreCase))
            {
                if (value.IndexOf("Opening", StringComparison.OrdinalIgnoreCase) >= 0) return "Opening / Void";
                if (value.IndexOf("Stage", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    value.IndexOf("Strut", StringComparison.OrdinalIgnoreCase) >= 0) return "Formwork Stage";
                if (value.IndexOf("Top", StringComparison.OrdinalIgnoreCase) >= 0) return "Formwork Top";
                if (value.IndexOf("Bottom", StringComparison.OrdinalIgnoreCase) >= 0) return "Formwork Bottom";
                if (value.IndexOf("Side", StringComparison.OrdinalIgnoreCase) >= 0) return "Formwork Side";
                return "Formwork";
            }

            if (string.Equals(value, "Rebar.Weight", StringComparison.OrdinalIgnoreCase))
            {
                return "Rebar";
            }

            if (value.IndexOf("Volume", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Concrete Volume";
            }

            if (value.IndexOf("Area", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Area";
            }

            if (value.IndexOf("Length", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Girth", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "Length";
            }

            return "Quantity";
        }

        private static string GetBoqReportTraceBucketUnit(string key)
        {
            string value = key ?? "";
            if (string.Equals(value, "Rebar.Weight", StringComparison.OrdinalIgnoreCase) ||
                value.IndexOf("Weight", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "kg";
            }

            if (value.IndexOf("Volume", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "m3";
            }

            if (value.IndexOf("Count", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Number", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("StepCount", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "pc";
            }

            if (value.EndsWith("StrutStage", StringComparison.OrdinalIgnoreCase))
            {
                return "stage";
            }

            if (value.IndexOf("Length", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Girth", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Height", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Width", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Depth", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "m";
            }

            if (value.StartsWith("FIN.", StringComparison.OrdinalIgnoreCase) ||
                value.StartsWith("FWK.", StringComparison.OrdinalIgnoreCase) ||
                value.IndexOf("Area", StringComparison.OrdinalIgnoreCase) >= 0 ||
                string.Equals(value, "CBIM_FormworkArea", StringComparison.OrdinalIgnoreCase))
            {
                return "m2";
            }

            return "";
        }

        private static void WriteBoqReportSheetToWorksheet(dynamic worksheet, BoqReportExportSheet sheet, string filterSummary, int autoFitPages)
        {
            List<BoqReportColumnSpec> columns = sheet.Columns ?? new List<BoqReportColumnSpec>();
            List<BoqReportRow> rows = sheet.Rows ?? new List<BoqReportRow>();
            int colCount = Math.Max(1, columns.Count);
            int rowCount = rows.Count + 4;
            var matrix = new object[rowCount, colCount];

            matrix[0, 0] = sheet.Title ?? "";
            matrix[1, 0] = "Project Name: " + GetBoqReportProjectName();
            matrix[1, colCount - 1] = "Compile Date: " + DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            matrix[2, 0] = "Report Scope: " + (filterSummary ?? "");

            for (int c = 0; c < columns.Count; c++)
            {
                matrix[3, c] = columns[c].Header ?? "";
            }

            for (int r = 0; r < rows.Count; r++)
            {
                BoqReportRow row = rows[r];
                for (int c = 0; c < columns.Count; c++)
                {
                    matrix[r + 4, c] = GetBoqReportExportValue(row, columns[c]);
                }
            }

            object topLeftObj = null;
            object bottomRightObj = null;
            object rangeObj = null;
            object titleTopLeftObj = null;
            object titleBottomRightObj = null;
            object titleRangeObj = null;
            object headerTopLeftObj = null;
            object headerBottomRightObj = null;
            object headerRangeObj = null;
            object fullTopLeftObj = null;
            object fullBottomRightObj = null;
            object fullRangeObj = null;
            object scopeTopLeftObj = null;
            object scopeBottomRightObj = null;
            object scopeRangeObj = null;

            try
            {
                topLeftObj = worksheet.Cells[1, 1];
                bottomRightObj = worksheet.Cells[rowCount, colCount];
                rangeObj = worksheet.Range[topLeftObj, bottomRightObj];
                dynamic range = rangeObj;
                range.Value2 = matrix;

                titleTopLeftObj = worksheet.Cells[1, 1];
                titleBottomRightObj = worksheet.Cells[1, colCount];
                titleRangeObj = worksheet.Range[titleTopLeftObj, titleBottomRightObj];
                dynamic titleRange = titleRangeObj;
                titleRange.Merge();
                titleRange.Font.Bold = true;
                titleRange.Font.Size = 14;
                titleRange.HorizontalAlignment = -4108;

                scopeTopLeftObj = worksheet.Cells[3, 1];
                scopeBottomRightObj = worksheet.Cells[3, colCount];
                scopeRangeObj = worksheet.Range[scopeTopLeftObj, scopeBottomRightObj];
                dynamic scopeRange = scopeRangeObj;
                scopeRange.Merge();
                scopeRange.Font.Italic = true;
                scopeRange.Interior.Color = ToExcelOleColor(242, 242, 242);

                headerTopLeftObj = worksheet.Cells[4, 1];
                headerBottomRightObj = worksheet.Cells[4, colCount];
                headerRangeObj = worksheet.Range[headerTopLeftObj, headerBottomRightObj];
                dynamic headerRange = headerRangeObj;
                headerRange.Font.Bold = true;
                headerRange.HorizontalAlignment = -4108;
                headerRange.VerticalAlignment = -4108;
                headerRange.WrapText = true;
                headerRange.Interior.Color = ToExcelOleColor(157, 195, 230);

                fullTopLeftObj = worksheet.Cells[1, 1];
                fullBottomRightObj = worksheet.Cells[rowCount, colCount];
                fullRangeObj = worksheet.Range[fullTopLeftObj, fullBottomRightObj];
                dynamic fullRange = fullRangeObj;
                fullRange.Borders.LineStyle = 1;
                fullRange.Borders.Color = 0;

                try
                {
                    worksheet.Rows[1].RowHeight = 24;
                    worksheet.Rows[4].RowHeight = 42;
                    worksheet.Columns.AutoFit();
                    for (int c = 0; c < columns.Count; c++)
                    {
                        if ((columns[c]?.Width ?? 0.0) > 120.0)
                        {
                            worksheet.Columns[c + 1].ColumnWidth = Math.Min(42.0, Math.Max(14.0, (columns[c].Width / 7.0)));
                        }
                    }

                    dynamic pageSetup = worksheet.PageSetup;
                    pageSetup.Orientation = columns.Count >= 8 ? 2 : 1;
                    pageSetup.Zoom = false;
                    pageSetup.FitToPagesWide = Math.Max(1, autoFitPages);
                    pageSetup.FitToPagesTall = false;
                    pageSetup.PrintTitleRows = "$1:$4";
                    pageSetup.CenterHorizontally = true;
                }
                catch
                {
                    // Export data is more important than presentation polish.
                }
            }
            finally
            {
                SafeReleaseCom(scopeRangeObj);
                SafeReleaseCom(scopeBottomRightObj);
                SafeReleaseCom(scopeTopLeftObj);
                SafeReleaseCom(fullRangeObj);
                SafeReleaseCom(fullBottomRightObj);
                SafeReleaseCom(fullTopLeftObj);
                SafeReleaseCom(headerRangeObj);
                SafeReleaseCom(headerBottomRightObj);
                SafeReleaseCom(headerTopLeftObj);
                SafeReleaseCom(titleRangeObj);
                SafeReleaseCom(titleBottomRightObj);
                SafeReleaseCom(titleTopLeftObj);
                SafeReleaseCom(rangeObj);
                SafeReleaseCom(bottomRightObj);
                SafeReleaseCom(topLeftObj);
            }
        }

        private static object FindExcelWorkbook(object workbooksObj, string fullName)
        {
            if (workbooksObj == null) return null;
            if (string.IsNullOrWhiteSpace(fullName)) return null;

            try
            {
                dynamic workbooks = workbooksObj;
                foreach (object wb in workbooks)
                {
                    try
                    {
                        string candidate = Convert.ToString(((dynamic)wb).FullName) ?? "";
                        if (string.Equals(candidate, fullName, StringComparison.OrdinalIgnoreCase))
                        {
                            return wb;
                        }
                    }
                    catch
                    {
                        // ignore and continue
                    }
                }
            }
            catch
            {
                // ignore
            }

            return null;
        }

        private static object GetExcelWorksheet(object workbookObj, string sheetName)
        {
            if (workbookObj == null || string.IsNullOrWhiteSpace(sheetName)) return null;
            try
            {
                dynamic workbook = workbookObj;
                return workbook.Worksheets[sheetName];
            }
            catch
            {
                return null;
            }
        }

        private static void SafeReleaseCom(object comObj)
        {
            if (comObj == null) return;
            try
            {
                if (Marshal.IsComObject(comObj))
                {
                    Marshal.FinalReleaseComObject(comObj);
                }
            }
            catch
            {
                // ignore
            }
        }

