        private ShopDrawingGroupMode GetShopDrawingGroupMode()
        {
            string value = "";
            if (ShopDrawingGroupModeCombo?.SelectedValue != null)
            {
                value = ShopDrawingGroupModeCombo.SelectedValue.ToString();
            }

            if (string.IsNullOrWhiteSpace(value) &&
                ShopDrawingGroupModeCombo?.SelectedItem is ComboBoxItem item)
            {
                value = item.Tag?.ToString() ?? item.Content?.ToString() ?? "";
            }

            if (Enum.TryParse(value, ignoreCase: true, out ShopDrawingGroupMode parsed))
            {
                return parsed;
            }

            string text = value ?? "";
            if (text.IndexOf("Host", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return ShopDrawingGroupMode.LevelCategoryAndHost;
            }

            if (text.IndexOf("Category", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return ShopDrawingGroupMode.LevelAndCategory;
            }

            return ShopDrawingGroupMode.LevelOnly;
        }

        private static string GetShopDrawingComboText(System.Windows.Controls.ComboBox combo, string fallback)
        {
            string text = combo?.Text ?? "";
            if (!string.IsNullOrWhiteSpace(text) &&
                text.IndexOf("ComboBoxItem", StringComparison.OrdinalIgnoreCase) < 0)
            {
                return text.Trim();
            }

            if (combo?.SelectedItem is ComboBoxItem item && item.Content != null)
            {
                return item.Content.ToString();
            }

            return fallback;
        }

        private static string NormalizeShopDrawingUiText(string value, string fallback, int maxLength)
        {
            string text = string.IsNullOrWhiteSpace(value) ? fallback : value.Trim();
            text = Regex.Replace(text, @"\s+", " ");
            if (maxLength > 0 && text.Length > maxLength)
            {
                text = text.Substring(0, maxLength);
            }

            return string.IsNullOrWhiteSpace(text) ? fallback : text;
        }

        private static string NormalizeShopDrawingUiPrefix(string value, string fallback)
        {
            string text = string.IsNullOrWhiteSpace(value) ? fallback : value.Trim();
            text = Regex.Replace(text.ToUpperInvariant(), @"[^A-Z0-9_-]+", "-").Trim('-', '_');
            if (text.Length > 32)
            {
                text = text.Substring(0, 32).Trim('-', '_');
            }

            return string.IsNullOrWhiteSpace(text) ? fallback : text;
        }

        private static string FormatShopDrawingGroupMode(ShopDrawingGroupMode groupMode)
        {
            if (groupMode == ShopDrawingGroupMode.LevelCategoryAndHost)
            {
                return "level + category + host";
            }

            if (groupMode == ShopDrawingGroupMode.LevelAndCategory)
            {
                return "level + category";
            }

            return "level only";
        }

