        private static void SelectComboItemByName(System.Windows.Controls.ComboBox combo, string name)
        {
            if (combo == null || combo.ItemsSource == null || string.IsNullOrWhiteSpace(name))
            {
                return;
            }

            foreach (object item in combo.ItemsSource)
            {
                if (item == null) continue;
                if (string.Equals(item.ToString(), name, StringComparison.OrdinalIgnoreCase))
                {
                    combo.SelectedItem = item;
                    return;
                }
            }
        }

        private static bool TrySelectComboItemById(System.Windows.Controls.ComboBox combo, ElementId id)
        {
            if (combo == null || combo.ItemsSource == null || id == null || id == ElementId.InvalidElementId)
            {
                return false;
            }

            foreach (object item in combo.ItemsSource)
            {
                if (item is ComboItem comboItem && comboItem.Id == id)
                {
                    combo.SelectedItem = comboItem;
                    return true;
                }
            }

            return false;
        }

        private static List<ColumnSectionSpec> ParseColumnSectionSpecs(string text)
        {
            var results = new List<ColumnSectionSpec>();
            var lines = text.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
            var byName = new Dictionary<string, ColumnSectionSpec>(StringComparer.OrdinalIgnoreCase);

            foreach (string rawLine in lines)
            {
                string line = rawLine.Trim();
                if (string.IsNullOrWhiteSpace(line)) continue;

                string[] cols = line.Split('\t');
                if (cols.Length < 3)
                {
                    cols = line.Split(',');
                }
                if (cols.Length < 3)
                {
                    cols = line.Split(';');
                }
                if (cols.Length < 3) continue;

                string name = cols[0].Trim();
                string w = cols[1].Trim();
                string l = cols[2].Trim();

                if (IsHeaderRow(name, w, l)) continue;
                if (string.IsNullOrWhiteSpace(name)) continue;

                if (!TryParseDouble(w, out double widthMm)) continue;
                if (!TryParseDouble(l, out double lengthMm)) continue;

                var spec = new ColumnSectionSpec
                {
                    Name = name,
                    WidthMm = widthMm,
                    LengthMm = lengthMm
                };

                byName[name] = spec;
            }

            results.AddRange(byName.Values);
            return results;
        }

        private static List<ColumnSectionSpec> ReadColumnSectionSpecsFromExcel(string path, out string sourceLabel)
        {
            sourceLabel = "Excel";

            if (string.IsNullOrWhiteSpace(path))
            {
                throw new InvalidOperationException("Column section Excel path is empty.");
            }

            string fullPath = Path.GetFullPath(path);
            if (!File.Exists(fullPath))
            {
                throw new FileNotFoundException("Excel file not found: " + fullPath, fullPath);
            }

            object appObj = null;
            object workbooksObj = null;
            object workbookObj = null;
            object worksheetObj = null;
            object usedRangeObj = null;
            object selectionObj = null;
            bool createdApp = false;
            bool openedWorkbook = false;

            try
            {
                Type excelType = Type.GetTypeFromProgID("Excel.Application") ??
                                 throw new InvalidOperationException("Microsoft Excel is not available.");

                try
                {
                    appObj = ComActiveObject.GetActiveObject("Excel.Application");
                }
                catch
                {
                    appObj = Activator.CreateInstance(excelType);
                    createdApp = true;
                }

                dynamic app = appObj;
                if (createdApp)
                {
                    app.DisplayAlerts = false;
                    app.Visible = false;
                }

                workbooksObj = app.Workbooks;
                dynamic workbooks = workbooksObj;

                workbookObj = FindExcelWorkbook(workbooksObj, fullPath);
                if (workbookObj == null)
                {
                    workbookObj = workbooks.Open(fullPath, Type.Missing, true);
                    openedWorkbook = true;
                }

                bool isActiveWorkbook = false;
                object activeWorkbookObj = null;
                try
                {
                    activeWorkbookObj = app.ActiveWorkbook;
                    string activeFullName = Convert.ToString(((dynamic)activeWorkbookObj).FullName, CultureInfo.InvariantCulture) ?? "";
                    isActiveWorkbook = PathsEqual(activeFullName, fullPath);
                }
                catch
                {
                    isActiveWorkbook = false;
                }
                finally
                {
                    SafeReleaseCom(activeWorkbookObj);
                }

                if (isActiveWorkbook)
                {
                    try
                    {
                        selectionObj = app.Selection;
                    }
                    catch
                    {
                        selectionObj = null;
                    }

                    if (selectionObj != null)
                    {
                        object selectionValuesObj = ((dynamic)selectionObj).Value2;
                        object[,] selectionValues = NormalizeExcelRangeToMatrix(selectionValuesObj);
                        List<ColumnSectionSpec> fromSelection = ParseColumnSectionSpecsFromExcelMatrix(selectionValues);
                        if (fromSelection.Count > 0)
                        {
                            string selectionSheetName = "";
                            object activeSheetObj = null;
                            try
                            {
                                activeSheetObj = app.ActiveSheet;
                                selectionSheetName = Convert.ToString(((dynamic)activeSheetObj).Name, CultureInfo.InvariantCulture) ?? "";
                            }
                            catch
                            {
                                selectionSheetName = "";
                            }
                            finally
                            {
                                SafeReleaseCom(activeSheetObj);
                            }

                            sourceLabel = string.IsNullOrWhiteSpace(selectionSheetName)
                                ? Path.GetFileName(fullPath) + " (selection)"
                                : Path.GetFileName(fullPath) + " [" + selectionSheetName + "] selection";
                            return fromSelection;
                        }
                    }
                }

                worksheetObj = GetExcelWorksheet(workbookObj, "Column_Section")
                               ?? GetExcelWorksheet(workbookObj, "Column Section")
                               ?? GetExcelWorksheet(workbookObj, "ColumnSection");

                if (worksheetObj == null && isActiveWorkbook)
                {
                    try
                    {
                        worksheetObj = app.ActiveSheet;
                    }
                    catch
                    {
                        worksheetObj = null;
                    }
                }

                if (worksheetObj == null)
                {
                    worksheetObj = ((dynamic)workbookObj).Worksheets[1];
                }

                dynamic worksheet = worksheetObj;
                string worksheetName = Convert.ToString(worksheet.Name, CultureInfo.InvariantCulture) ?? "Sheet1";

                usedRangeObj = worksheet.UsedRange;
                object valuesObj = ((dynamic)usedRangeObj).Value2;
                object[,] values = NormalizeExcelRangeToMatrix(valuesObj);
                List<ColumnSectionSpec> fromSheet = ParseColumnSectionSpecsFromExcelMatrix(values);
                sourceLabel = Path.GetFileName(fullPath) + " [" + worksheetName + "]";
                return fromSheet;
            }
            finally
            {
                if (openedWorkbook && workbookObj != null)
                {
                    try
                    {
                        ((dynamic)workbookObj).Close(false);
                    }
                    catch
                    {
                    }
                }

                if (createdApp && appObj != null)
                {
                    try
                    {
                        ((dynamic)appObj).Quit();
                    }
                    catch
                    {
                    }
                }

                SafeReleaseCom(selectionObj);
                SafeReleaseCom(usedRangeObj);
                SafeReleaseCom(worksheetObj);
                SafeReleaseCom(workbookObj);
                SafeReleaseCom(workbooksObj);
                SafeReleaseCom(appObj);
            }
        }

        private static List<ColumnSectionSpec> ParseColumnSectionSpecsFromExcelMatrix(object[,] values)
        {
            var results = new List<ColumnSectionSpec>();
            if (values == null)
            {
                return results;
            }

            int rowCount = values.GetLength(0);
            int colCount = values.GetLength(1);
            if (rowCount <= 0 || colCount <= 0)
            {
                return results;
            }

            if (!TryFindColumnSectionExcelColumns(
                    values,
                    rowCount,
                    colCount,
                    out int headerRow,
                    out int nameCol,
                    out int widthCol,
                    out int lengthCol))
            {
                headerRow = 1;
                nameCol = 1;
                widthCol = Math.Min(2, colCount);
                lengthCol = Math.Min(3, colCount);
            }

            var byName = new Dictionary<string, ColumnSectionSpec>(StringComparer.OrdinalIgnoreCase);
            for (int row = headerRow + 1; row <= rowCount; row++)
            {
                string name = GetExcelCellText(values, row, nameCol);
                string widthRaw = GetExcelCellText(values, row, widthCol);
                string lengthRaw = GetExcelCellText(values, row, lengthCol);

                if (string.IsNullOrWhiteSpace(name) &&
                    string.IsNullOrWhiteSpace(widthRaw) &&
                    string.IsNullOrWhiteSpace(lengthRaw))
                {
                    continue;
                }

                if (IsHeaderRow(name, widthRaw, lengthRaw))
                {
                    continue;
                }

                if (string.IsNullOrWhiteSpace(name))
                {
                    continue;
                }

                if (!TryParseDouble(widthRaw, out double widthMm))
                {
                    continue;
                }

                if (!TryParseDouble(lengthRaw, out double lengthMm))
                {
                    continue;
                }

                string normalizedName = name.Trim();
                byName[normalizedName] = new ColumnSectionSpec
                {
                    Name = normalizedName,
                    WidthMm = widthMm,
                    LengthMm = lengthMm
                };
            }

            results.AddRange(byName.Values);
            return results;
        }

        private static bool TryFindColumnSectionExcelColumns(
            object[,] values,
            int rowCount,
            int colCount,
            out int headerRow,
            out int nameCol,
            out int widthCol,
            out int lengthCol)
        {
            headerRow = 0;
            nameCol = 0;
            widthCol = 0;
            lengthCol = 0;

            int maxRowsToScan = Math.Min(rowCount, 20);
            for (int row = 1; row <= maxRowsToScan; row++)
            {
                int foundName = 0;
                int foundWidth = 0;
                int foundLength = 0;

                for (int col = 1; col <= colCount; col++)
                {
                    string token = NormalizeExcelHeaderToken(GetExcelCellText(values, row, col));
                    if (string.IsNullOrWhiteSpace(token))
                    {
                        continue;
                    }

                    if (foundName == 0 && token.Contains("name"))
                    {
                        foundName = col;
                    }

                    if (foundWidth == 0 &&
                        (token.Contains("width") || string.Equals(token, "w", StringComparison.OrdinalIgnoreCase)))
                    {
                        foundWidth = col;
                    }

                    if (foundLength == 0 &&
                        (token.Contains("length") || string.Equals(token, "l", StringComparison.OrdinalIgnoreCase)))
                    {
                        foundLength = col;
                    }
                }

                if (foundName > 0 && foundWidth > 0 && foundLength > 0)
                {
                    headerRow = row;
                    nameCol = foundName;
                    widthCol = foundWidth;
                    lengthCol = foundLength;
                    return true;
                }
            }

            return false;
        }

        private static string GetExcelCellText(object[,] values, int row, int col)
        {
            if (values == null)
            {
                return "";
            }

            if (row < 1 || row > values.GetLength(0) || col < 1 || col > values.GetLength(1))
            {
                return "";
            }

            object raw = values[row, col];
            return raw == null ? "" : (Convert.ToString(raw, CultureInfo.InvariantCulture) ?? "").Trim();
        }

        private static string NormalizeExcelHeaderToken(string text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return "";
            }

            string trimmed = text.Trim().ToLowerInvariant();
            var sb = new StringBuilder(trimmed.Length);
            foreach (char ch in trimmed)
            {
                if (char.IsLetterOrDigit(ch))
                {
                    sb.Append(ch);
                }
            }

            return sb.ToString();
        }

        private static bool PathsEqual(string leftPath, string rightPath)
        {
            if (string.IsNullOrWhiteSpace(leftPath) || string.IsNullOrWhiteSpace(rightPath))
            {
                return false;
            }

            try
            {
                string leftFull = Path.GetFullPath(leftPath.Trim());
                string rightFull = Path.GetFullPath(rightPath.Trim());
                return string.Equals(leftFull, rightFull, StringComparison.OrdinalIgnoreCase);
            }
            catch
            {
                return string.Equals(leftPath.Trim(), rightPath.Trim(), StringComparison.OrdinalIgnoreCase);
            }
        }

        private static List<WallSectionSpec> ParseWallSectionSpecs(string text)
        {
            var results = new List<WallSectionSpec>();
            var lines = text.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
            var byName = new Dictionary<string, WallSectionSpec>(StringComparer.OrdinalIgnoreCase);

            foreach (string rawLine in lines)
            {
                string line = rawLine.Trim();
                if (string.IsNullOrWhiteSpace(line)) continue;

                string[] cols = line.Split('\t');
                if (cols.Length < 2)
                {
                    cols = line.Split(',');
                }
                if (cols.Length < 2)
                {
                    cols = line.Split(';');
                }
                if (cols.Length < 2) continue;

                string name = cols[0].Trim();
                string w = cols[1].Trim();

                if (IsHeaderRow(name, w, "")) continue;
                if (string.IsNullOrWhiteSpace(name)) continue;

                if (!TryParseDouble(w, out double widthMm)) continue;

                var spec = new WallSectionSpec
                {
                    Name = name,
                    WidthMm = widthMm
                };

                byName[name] = spec;
            }

            results.AddRange(byName.Values);
            return results;
        }

