        private static List<SlabSectionSpec> ParseSlabSectionSpecs(string text)
        {
            var results = new List<SlabSectionSpec>();
            var lines = text.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
            var byName = new Dictionary<string, SlabSectionSpec>(StringComparer.OrdinalIgnoreCase);

            foreach (string rawLine in lines)
            {
                string line = rawLine.Trim();
                if (string.IsNullOrWhiteSpace(line)) continue;

                string[] cols = line.Split('\t');
                if (cols.Length < 2)
                {
                    cols = line.Split(',');
                }
                if (cols.Length < 2)
                {
                    cols = line.Split(';');
                }
                if (cols.Length < 2) continue;

                string name = cols[0].Trim();
                string t = cols[1].Trim();

                if (IsSlabHeaderRow(name, t)) continue;
                if (string.IsNullOrWhiteSpace(name)) continue;

                if (!TryParseDouble(t, out double thicknessMm)) continue;

                var spec = new SlabSectionSpec
                {
                    Name = name,
                    ThicknessMm = thicknessMm
                };

                byName[name] = spec;
            }

            results.AddRange(byName.Values);
            return results;
        }

        private static bool IsSlabHeaderRow(string name, string thickness)
        {
            string n = name?.ToLowerInvariant() ?? "";
            string t = thickness?.ToLowerInvariant() ?? "";

            return n.Contains("name") && (t.Contains("thick") || t.Contains("depth") || t.Contains("t"));
        }

        private static string GetDatabaseFolder()
        {
            string baseDir = AppDomain.CurrentDomain.BaseDirectory;
            string[] candidates =
            {
                Path.Combine(baseDir, "database"),
                Path.GetFullPath(Path.Combine(baseDir, "..", "..", "..", "database")),
                @"D:\CamboBIM\20260125_CamboBIM\CamboBIM_Revit\CamboBIM.Revit2024.Addin\database"
            };

            foreach (string candidate in candidates)
            {
                if (Directory.Exists(candidate))
                {
                    return candidate;
                }
            }

            return candidates.Last();
        }

        private static bool IsHeaderRow(string name, string width, string length)
        {
            string n = name?.ToLowerInvariant() ?? "";
            string w = width?.ToLowerInvariant() ?? "";
            string l = length?.ToLowerInvariant() ?? "";

            return n.Contains("name") && w.Contains("width") && l.Contains("length");
        }

        private static bool TryParseDouble(string raw, out double value)
        {
            if (double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value))
            {
                return true;
            }

            return double.TryParse(raw, NumberStyles.Float, CultureInfo.CurrentCulture, out value);
        }

